class ConfigGenerator:
    def __init__(self, env):
        self.env = env
        self.template_path = "config_template.yaml"
        self.output_path = f"config_{env}.yaml"
        self.logging_service_url = "https://logging-service.example/api/config"

    def fetch_logging_config(self):
        try:
            response = requests.get(self.logging_service_url)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error fetching logging config: {e}")
            return {}

    def generate_configuration(self):
        # Load and render the main configuration template
        with open(self.template_path, 'r') as file:
            template_content = Template(file.read())

        env_variables = {
            "development": {"db_url": "dev_db.example.com", "api_key": "dev_key"},
            "testing": {"db_url": "test_db.example.com", "api_key": "test_key"},
            "production": {"db_url": "prod_db.example.com", "api_key": "prod_key"}
        }

        rendered_config = template_content.render(env=self.env, **env_variables[self.env])

        # Fetch logging configuration
        logging_config = self.fetch_logging_config()

        if not logging_config:
            logging_config = {
                "log_rotation": {"enabled": True, "interval": "daily"},
                "external_aggregation": {"url": "https://aggregator.example.com"}
            }

        # Integrate logging settings into the configuration
        final_config = self.integrate_logging_settings(rendered_config, logging_config)

        # Write the final configuration to a file
        with open(self.output_path, 'w') as file:
            file.write(final_config)

    def integrate_logging_settings(self, config_str, logging_config):
        log_section_template = """
