          rotation:
            enabled: {{ logging.log_rotation.enabled }}
            interval: {{ logging.log_rotation.interval }}
          external_aggregation:
            url: {{ logging.external_aggregation.url }}
        """

        log_section = Template(log_section_template).render(logging=logging_config)
        return config_str + "\n" + log_section

    def batch_update(self, updates):
        # Implement batching logic if necessary
        pass

if __name__ == "__main__":
    env = os.getenv("ENVIRONMENT", "development")
    generator = ConfigGenerator(env)
    generator.generate_configuration()
