// Forward declarations for third-party modules
typedef struct CryptoFunc CryptoFunc;
typedef int (*CryptoImpl)(const void* data, size_t len, void* output);

struct CryptoFunc {
    char *name;
    CryptoImpl implementation;
    void *params; // Parameters specific to the algorithm
};

// A list of supported crypto functions (for demonstration)
static CryptoFunc *crypto_functions = NULL;
static int function_count = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Example implementations for demo purposes
int sha256_impl(const void* data, size_t len, void* output) {
    // Implementation of SHA-256 hash
    return 1; // Success
}

int aes_128_cbc_impl(const void* data, size_t len, void* output) {
    // Implementation of AES-128-CBC encryption
    return 1; // Success
}

// Add new crypto functions to the list
void register_crypto_function(const char *name, CryptoImpl impl, void *params) {
    pthread_mutex_lock(&list_mutex);

    int new_count = function_count + 1;
    crypto_functions = realloc(crypto_functions, new_count * sizeof(CryptoFunc));

    if (crypto_functions != NULL) {
        strcpy(crypto_functions[function_count].name, name);
        crypto_functions[function_count].implementation = impl;
        crypto_functions[function_count].params = params;
        function_count++;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Retrieve the list of available cryptographic functions
CryptoFunc *get_crypto_function_list(int *count) {
    pthread_mutex_lock(&list_mutex);

    if (count != NULL) {
        *count = function_count;
    }

    CryptoFunc *copy = malloc(function_count * sizeof(CryptoFunc));
    memcpy(copy, crypto_functions, function_count * sizeof(CryptoFunc));

    pthread_mutex_unlock(&list_mutex);
    return copy;
}

// Free the list of cryptographic functions
void free_crypto_function_list(CryptoFunc *functions) {
    if (functions != NULL) {
        free(functions);
    }
}

int main() {
    // Register some example crypto functions
    register_crypto_function("SHA-256", sha256_impl, NULL);
    register_crypto_function("AES-128-CBC", aes_128_cbc_impl, NULL);

    int count;
    CryptoFunc *functions = get_crypto_function_list(&count);

    for (int i = 0; i < count; ++i) {
        printf("Function: %s\n", functions[i].name);
    }

    free_crypto_function_list(functions);

    return 0;
}
```

