// Define supported cipher algorithms
typedef enum {
    CIPHER_NULL,
    CIPHER_AES,
    CIPHER_DES,
    // Add more ciphers as needed
} CipherAlgorithm;

// Cipher context structure
typedef struct {
    CipherAlgorithm algorithm;
    void *context; // Pointer to the actual cipher context in the framework
    int key_length;
    char *key;
} CipherContext;

CipherContext* load_cipher_context(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        fprintf(stderr, "Error opening configuration file.\n");
        return NULL;
    }

    // Initialize the parser
    ConfigParser *parser = config_parser_init(file);
    if (!parser) {
        fprintf(stderr, "Error initializing config parser.\n");
        fclose(file);
        return NULL;
    }

    CipherContext *cipher_context = malloc(sizeof(CipherContext));
    if (!cipher_context) {
        fprintf(stderr, "Memory allocation failed for cipher context.\n");
        config_parser_free(parser);
        fclose(file);
        return NULL;
    }

    // Parse configuration and initialize cipher
    while (config_parser_has_next(parser)) {
        char *key = config_parser_get_key(parser);
        char *value = config_parser_get_value(parser);

        if (strcmp(key, "algorithm") == 0) {
            if (strcmp(value, "AES") == 0)
                cipher_context->algorithm = CIPHER_AES;
            else if (strcmp(value, "DES") == 0)
                cipher_context->algorithm = CIPHER_DES;
            else
                fprintf(stderr, "Unsupported algorithm specified.\n");
        }
        else if (strcmp(key, "key_length") == 0) {
            cipher_context->key_length = atoi(value);
        }
        else if (strcmp(key, "key") == 0) {
            cipher_context->key = strdup(value);
        }

        config_parser_next(parser);
    }

    // Initialize the cipher context based on parsed values
    if (cipher_context->algorithm != CIPHER_NULL && cipher_context->key) {
        switch (cipher_context->algorithm) {
            case CIPHER_AES:
                cipher_context->context = init_aes_cipher(cipher_context->key, cipher_context->key_length);
                break;
            case CIPHER_DES:
                cipher_context->context = init_des_cipher(cipher_context->key, cipher_context->key_length);
                break;
            // Add more cases as needed
        }
    }

    if (!cipher_context->context) {
        fprintf(stderr, "Failed to initialize cipher context.\n");
        free_cipher_context(cipher_context);
        config_parser_free(parser);
        fclose(file);
        return NULL;
    }

    config_parser_free(parser);
    fclose(file);

    // Return the initialized cipher context
    return cipher_context;
}

// Function to release resources associated with the CipherContext
void free_cipher_context(CipherContext *cipher_context) {
    if (cipher_context) {
        if (cipher_context->context)
            destroy_cipher_context(cipher_context->context);  // Assume this function is provided by the framework
        if (cipher_context->key)
            free(cipher_context->key);
        free(cipher_context);
    }
}
