['Below is a C implementation of a semaphore management system fulfilling the specified requirements. The code uses POSIX semaphores for cross-platform compatibility and ensures thread safety through proper locking mechanisms.

```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    sem_t *sem;
    int value;
    pthread_mutex_t lock;
    size_t active_threads;
    size_t max_active_threads;
    size_t increment_count;
    size_t decrement_count;
} SemaphoreManager;

SemaphoreManager* create_semaphore(const char* name, int initial_value) {
    SemaphoreManager *sm = malloc(sizeof(SemaphoreManager));
    sem_unlink(name); // Remove any existing semaphore with the same name
    if (sem_init(&(sm->sem), 1, initial_value) == -1) { // Creating a named semaphore
        perror("Semaphore initialization failed");
        free(sm);
        return NULL;
    }
    sm->value = initial_value;
    pthread_mutex_init(&(sm->lock), NULL);
    sm->active_threads = 0;
    sm->max_active_threads = 0;
    sm->increment_count = 0;
    sm->decrement_count = 0;

    // Register the semaphore with a monitoring system (pseudo code)
    // register_semaphore_monitoring(sm);

    return sm;
}

void increment(SemaphoreManager *sm) {
    pthread_mutex_lock(&(sm->lock));
    sem_post(sm->sem);
    sm->active_threads++;
    if (sm->active_threads > sm->max_active_threads) {
        sm->max_active_threads = sm->active_threads;
    }
    sm->increment_count++;
    pthread_mutex_unlock(&(sm->lock));

    // Log increment usage
    // log_increment_usage(sm); 
}

void decrement(SemaphoreManager *sm) {
    pthread_mutex_lock(&(sm->lock));
    sem_wait(sm->sem);
    sm->active_threads--;
    sm->decrement_count++;
    pthread_mutex_unlock(&(sm->lock));

    // Log decrement usage
    // log_decrement_usage(sm); 
}

void cleanup_semaphore(SemaphoreManager *sm) {
    pthread_mutex_lock(&(sm->lock));
    while (sm->value > 0 && sem_trywait(sm->sem) == 0) {
        sm->value--;
    }
    pthread_mutex_unlock(&(sm->lock));

    if (sem_destroy(sm->sem) == -1) {
        perror("Semaphore destruction failed");
    }

    // Unregister from monitoring system
    // unregister_semaphore_monitoring(sm);

    free(sm);
}

void log_usage_statistics(SemaphoreManager *sm) {
    printf("Max Active Threads: %zu\n", sm->max_active_threads);
    printf("Increment Count: %zu\n", sm->increment_count);
    printf("Decrement Count: %zu\n", sm->decrement_count);
}

// Test function
void* thread_func(void* arg) {
    SemaphoreManager *sm = (SemaphoreManager *)arg;

    for(int i = 0; i < 5; ++i) {
        increment(sm);
        // Simulate work
        sleep(1); 
        decrement(sm);
    }

    return NULL;
}

int main() {
    const char* sem_name = "my_semaphore";
    SemaphoreManager *sm = create_semaphore(sem_name, 10);

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        if(pthread_create(&threads[i], NULL, thread_func, sm)) {
            perror("Thread creation failed");
            cleanup_semaphore(sm);
            return EXIT_FAILURE;
        }
    }

    for(int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_usage_statistics(sm);

    cleanup_semaphore(sm);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to ensure that increments and decrements of the semaphore are thread-safe.
- **Tracking Usage**: The `SemaphoreManager` struct tracks active threads, maximum concurrent accesses, and increment/decrement counts.
- **Logging**: Placeholder functions for logging provide a mechanism to capture usage statistics without affecting performance critically.
- **Cleanup**: Ensures resources are properly released when no longer needed.

This code should be tested thoroughly under different scenarios, especially with varying thread counts and access patterns, to ensure robustness.']

