```rust
use reqwest::Error;
use scraper::{Html, Selector};
use cached::proc_macro::cached;
use log::{info, error};
use std::time::Duration;

#[derive(Debug)]
struct CacheConfig {
    expiration: Duration,
}

#[tokio::main]
async fn fetch_and_process_html(url: &str, selector_query: &str) -> Result<Vec<String>, Error> {
    env_logger::init();

    let cache_config = CacheConfig { expiration: Duration::from_secs(300) };

    // Cached function to minimize redundant requests
    let html_content = cached_with_expiration(url, &cache_config).await?;

    // Parse HTML and process based on selector query
    if let Ok(texts) = extract_text_from_html(&html_content, selector_query) {
        info!("Successfully processed HTML content");
        return Ok(texts);
    } else {
        error!("Failed to parse HTML content with given selector.");
        return Err(reqwest::Error::new(
            reqwest::StatusCode::INTERNAL_SERVER_ERROR,
            "HTML parsing failed",
        ));
    }
}

async fn fetch_html_content(url: &str) -> Result<String, Error> {
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()?;

    info!("Fetching content from URL: {}", url);
    let response = client.get(url).send().await?;

    if response.status().is_success() {
        return Ok(response.text().await?);
    }

    Err(reqwest::Error::new(
        reqwest::StatusCode::NOT_FOUND,
        "Failed to fetch URL",
    ))
}

#[cached(cache_path = "./html_cache", expiration = 300)]
async fn cached_with_expiration(url: &str, _cache_config: &CacheConfig) -> Result<String, Error> {
    fetch_html_content(url).await
}

fn extract_text_from_html(html_content: &str, selector_query: &str) -> Result<Vec<String>, scraper::error::Error> {
    let document = Html::parse_document(html_content);
    let selector = Selector::parse(selector_query)?;

    let texts = document.select(&selector)
        .filter_map(|element| element.text().next())
        .map(String::from)
        .collect();

    Ok(texts)
}
```

### Key Points:
- **Caching**: We use `cached` to cache the HTML content fetched from URLs. This reduces redundant network requests.
- **Concurrency and Async**: The function is asynchronous, leveraging `tokio` for non-blocking I/O operations.
- **Logging**: Logs are added at various points to trace execution flow and capture errors.
- **Configurability**: `CacheConfig` allows easy adjustment of cache expiration times.

### Trade-offs:
- **Latency vs Memory Usage**: Caching reduces latency but increases memory usage. The trade-off is managed by configurable cache expiration.
- **Parsing Accuracy vs Performance**: Parsing accuracy depends on the correctness of the selector query, while performance can be enhanced with efficient HTML parsing (using `scraper`).

### Extensibility:
The function is designed to easily add more complex extraction criteria or additional data sources, adhering to principles of maintainability and future expansion.']

