from flask import Flask, request, jsonify
import threading
import logging
from jsonschema import validate, ValidationError

app = Flask(__name__)

# Simulated in-memory storage for resources
resources = {}
resource_locks = {}

# Define the resource schema for validation
RESOURCE_SCHEMA = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "value": {"type": "number"}
    },
    "required": ["name", "value"]
}

# Set up logging configuration
logging.basicConfig(level=logging.INFO)

def log_operation(operation, resource_id, status):
    logging.info(f"{operation} operation on {resource_id}: {status}")

def validate_resource(data):
    try:
        validate(instance=data, schema=RESOURCE_SCHEMA)
        return True, None
    except ValidationError as e:
        return False, str(e)

@app.route('/update/<resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if resource_id not in resources:
        return jsonify({"error": "Resource not found"}), 404

    new_data = request.json
    is_valid, error = validate_resource(new_data)

    if not is_valid:
        return jsonify({"error": f"Validation failed: {error}"}), 400

    # Perform idempotent update operation
    current_state = resources[resource_id]
    updated_data = {**current_state, **new_data}

    resources[resource_id] = updated_data

    log_operation("Update", resource_id, "Success")
    return jsonify(resources[resource_id]), 200

@app.route('/delete', methods=['DELETE'])
def batch_delete_resources():
    resource_ids = request.json.get('ids', [])

    if not isinstance(resource_ids, list):
        return jsonify({"error": "Invalid input format"}), 400

    results = {}
    lock = threading.Lock()

    def delete_resource(resource_id):
        nonlocal results
        with lock:
            if resource_id in resources:
                del resources[resource_id]
                log_operation("Delete", resource_id, "Success")
                results[resource_id] = "Deleted"
            else:
                results[resource_id] = "Not Found"

    threads = []
    for resource_id in resource_ids:
        t = threading.Thread(target=delete_resource, args=(resource_id,))
        threads.append(t)
        t.start()

    for thread in threads:
        thread.join()

    return jsonify(results), 200

@app.errorhandler(Exception)
def handle_exception(e):
    logging.exception("An error occurred")
    if isinstance(e, ValidationError):
        return jsonify({"error": str(e)}), 400
    return jsonify({"error": "Internal server error"}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

### Key Points:
- **Validation**: The `validate_resource` function ensures that updates conform to the predefined schema.
- **Idempotency**: The update operation is idempotent as it uses a combination of current and new data.
- **Concurrency Handling**: A lock mechanism (`threading.Lock`) is used in batch deletions to handle concurrent operations on shared resources.
- **Logging**: Operations are logged using Python's `logging` module, capturing detailed information about each request.
- **Error Handling**: Differentiates between validation errors and server errors with appropriate HTTP responses.']

