<?php

function manageUserAccount() {
    require_once 'database.php'; // Assuming a file that initializes database connection
    require_once 'auth_service.php'; // External authentication service integration
    require_once 'logger.php'; // Logger setup for auditing actions

    $response = ['message' => '', 'data' => []];
    $request = $_REQUEST;

    if (!isset($request['name']) || !isset($request['email'])) {
        return json_encode(['message' => 'error', 'data' => ['message' => 'Name and email are required.']]);
    }

    $name = trim($request['name']);
    $email = trim($request['email']);
    $password = isset($request['password']) ? trim($request['password']) : null;
    $id = isset($request['id']) ? intval($request['id']) : null;
    $sub_action = strtolower(trim($request['sub_action']));

    // Validate name and email
    if (empty($name) || !preg_match('/^[a-zA-Z\s]+$/', $name)) {
        return json_encode(['message' => 'error', 'data' => ['message' => 'Invalid name format.']]);
    }
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode(['message' => 'error', 'data' => ['message' => 'Invalid email format.']]);
    }

    $pdo = Database::getConnection();

    switch ($sub_action) {
        case 'create':
            // Check if user already exists
            $stmt = $pdo->prepare("SELECT COUNT(*) FROM users WHERE email = :email");
            $stmt->execute([':email' => $email]);
            if ($stmt->fetchColumn() > 0) {
                return json_encode(['message' => 'error', 'data' => ['message' => 'User already exists.']]);
            }

            // Insert new user
            $stmt = $pdo->prepare("INSERT INTO users (name, email, password, status) VALUES (:name, :email, :password, 'active')");
            $hashedPassword = password_hash($password ?: '', PASSWORD_DEFAULT);
            if ($stmt->execute([':name' => $name, ':email' => $email, ':password' => $hashedPassword])) {
                $response['message'] = 'success';
                $response['data']['id'] = $pdo->lastInsertId();
                $response['data']['name'] = $name;
                $response['data']['email'] = $email;
                $response['data']['status'] = 'active';

                Logger::log("User created: ID {$response['data']['id']}");

            } else {
                return json_encode(['message' => 'error', 'data' => ['message' => 'Failed to create user.']]);
            }
            break;

        case 'update':
            if (!$id) {
                return json_encode(['message' => 'error', 'data' => ['message' => 'ID is required for update.']]);
            }

            // Check if user exists
            $stmt = $pdo->prepare("SELECT * FROM users WHERE id = :id");
            $stmt->execute([':id' => $id]);
            $user = $stmt->fetch(PDO::FETCH_ASSOC);

            if (!$user) {
                return json_encode(['message' => 'error', 'data' => ['message' => 'User not found.']]);
            }

            // Verify current password with external service
            if ($password && !AuthService::verifyPassword($id, $user['password'])) {
                return json_encode(['message' => 'error', 'data' => ['message' => 'Incorrect current password.']]);
            }

            $hashedPassword = password_hash($password ?: $user['password'], PASSWORD_DEFAULT);
            $stmt = $pdo->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
            if ($stmt->execute([':name' => $name, ':email' => $email, ':password' => $hashedPassword, ':id' => $id])) {
                $response['message'] = 'success';
                $response['data']['id'] = $id;
                $response['data']['name'] = $name;
                $response['data']['email'] = $email;
                $response['data']['status'] = 'active';

                Logger::log("User updated: ID {$id}");

            } else {
                return json_encode(['message' => 'error', 'data' => ['message' => 'Failed to update user.']]);
            }
            break;

        case 'delete':
            if (!$id) {
                return json_encode(['message' => 'error', 'data' => ['message' => 'ID is required for deletion.']]);
            }

            // Confirm deletion via callback
            if (!call_user_func('confirmDeletion', $id)) {
                return json_encode(['message' => 'error', 'data' => ['message' => 'Deletion not confirmed.']]);
            }

            $stmt = $pdo->prepare("UPDATE users SET status = 'deleted' WHERE id = :id");
            if ($stmt->execute([':id' => $id])) {
                $response['message'] = 'success';
                $response['data']['id'] = $id;
                $response['data']['status'] = 'deleted';

                Logger::log("User deleted: ID {$id}");

            } else {
                return json_encode(['message' => 'error', 'data' => ['message' => 'Failed to delete user.']]);
            }
            break;

        default:
            return json_encode(['message' => 'error', 'data' => ['message' => 'Invalid sub_action specified.']]);

    }

    // Return JSON response
    Logger::log("Action completed: " . $response['message']);
    return json_encode($response);
}

?>
