public class HtmlValidator
{
    public bool IsValidHtml(string htmlContent)
    {
        try
        {
            var xDoc = new System.Xml.Linq.XDocument();
            xDoc.LoadXml(htmlContent);
            return true;
        }
        catch (Exception ex)
        {
            // Log the exception if necessary
            return false;
        }
    }
