public class HtmlUpdateController : Controller
{
    private readonly HtmlUpdateService _updateService = new HtmlUpdateService();
    private readonly HtmlValidator _htmlValidator = new HtmlValidator();

    [HttpPost]
    public async Task<IActionResult> UpdateElementHtml(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrWhiteSpace(pageSectionId) || 
            string.IsNullOrWhiteSpace(elementId) ||
            string.IsNullOrWhiteSpace(htmlContent))
        {
            return BadRequest("Invalid input parameters.");
        }

        var validationErrors = new List<string>();

        // Validate HTML content
        if (!_htmlValidator.IsValidHtml(htmlContent))
        {
            validationErrors.Add("Malformed HTML content.");
        }

        if (validationErrors.Any())
        {
            return Json(new { RefreshPage = false, Errors = validationErrors });
        }

        try
        {
            // Update the content using an atomic operation
            var updateSuccess = await _updateService.UpdateHtmlContentAsync(pageSectionId, elementId, htmlContent);

            if (!updateSuccess)
            {
                return StatusCode(500, "Failed to update HTML content.");
            }

            return Json(new { RefreshPage = true, Errors = new string[0] });
        }
        catch (Exception ex)
        {
            // Log exception details
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }
}
