        if (!ValidateUsername(username) || !ValidatePassword(password))
            return false;

        lock (_userAccounts)
        {
            if (!_userAccounts.ContainsKey(username))
            {
                _userAccounts[username] = new UserAccount { Username = username, PasswordHash = HashPassword(password), RoleMetrics = new RoleMetrics() };
                return true;
            }
