            if (user.LockoutEndTime > DateTime.UtcNow)
                return false;

            if (user.PasswordHash == HashPassword(password))
            {
                // Reset lockout time
                _cache.Remove(username);
                await UpdateUserRoleMetricsAsync(username);
                return true;
