["```javascript
const fs = require('fs');
const path = require('path');
const util = require('util');

// Promisify readFile and readdir for asynchronous use
const readFileAsync = util.promisify(fs.readFile);
const readdirAsync = util.promisify(fs.readdir);

async function processFilesInDirectory(directory, extensions, concurrencyLimit = 5, logService) {
    let filesToProcess = [];
    try {
        const directoryContents = await readdirAsync(directory);

        // Filter files based on the provided extensions
        filesToProcess = directoryContents.filter(file => {
            return extensions.includes(path.extname(file));
        }).map(filePath => path.join(directory, filePath));

    } catch (error) {
        if (logService) logService.log(`Error reading directory: ${error.message}`);
        throw error;
    }

    const readFilePromise = async (filePath) => {
        try {
            const content = await readFileAsync(filePath, 'utf8');
            if (logService) logService.log(`Successfully read file: ${filePath}`);
            return content;
        } catch (error) {
            if (logService) logService.log(`Error reading file: ${filePath}, Error: ${error.message}`);
            return null; // Return null to handle gracefully
        }
    };

    const results = [];
    let activePromises = [];

    for (const filePath of filesToProcess) {
        const promise = readFilePromise(filePath).then(content => content ? content : '');

        activePromises.push(promise);

        if (activePromises.length >= concurrencyLimit) {
            await Promise.race(activePromises.map(p => p.catch(() => p))); // Wait for any to complete
            results.push(...(await Promise.allSettled(activePromises).then(proms => proms.filter(res => res.status === 'fulfilled').map(res => res.value))));
            activePromises = [];
        }
    }

    if (activePromises.length > 0) {
        // Process any remaining promises
        results.push(...(await Promise.allSettled(activePromises).then(proms => proms.filter(res => res.status === 'fulfilled').map(res => res.value))));
    }

    return results.join('');
}

module.exports = processFilesInDirectory;
```

### Explanation:
- **Concurrency Management**: The function limits concurrent file reads using a `concurrencyLimit`, managing performance and resources.
- **Error Handling**: Errors during reading are caught, logged if logging is integrated, and do not halt other operations.
- **Memory Constraints**: Each file's content is processed individually to avoid loading all into memory at once.
- **External Dependencies**: Supports integration with an external logging service.
- **Scalability**: Uses asynchronous processing to handle large numbers of files efficiently.
- **Usability**: Configurable for different file extensions and allows easy extension for additional processing steps."]

