const async = require('async');
const requireModule = require;
const blueslip = require('blueslip'); // Assuming blueslip is a mocking library

function manageTests(moduleName, testFunctions) {
    const module = requireModule(moduleName);

    function runTest(testFunction, callback) {
        try {
            testFunction(module).then(result => {
                console.log(`Test ${testFunction.name} passed:`, result);
                callback(null);
            }).catch(error => {
                console.error(`Error in test ${testFunction.name}:`, error);
                callback(error);
            });
        } catch (error) {
            console.error(`Exception in test ${testFunction.name}:`, error);
            callback(error);
        }
    }

    async.eachSeries(
        Object.keys(testFunctions),
        function(label, nextTest) {
            const testFn = testFunctions[label];
            console.log(`Running test: ${label}`);

            // Handle external service dependencies with retries
            const attemptTest = (retryCount = 0) => {
                runTest(() => testFn(module), error => {
                    if (error && retryCount < 3) { // Retry up to 3 times
                        console.warn(`Retrying ${label} due to error:`, error);
                        setTimeout(() => attemptTest(retryCount + 1), 1000); // Wait before retrying
                    } else {
                        nextTest(error);
                    }
                });
            };

            attemptTest();
        },
        function(err) {
            if (err) {
                console.error('One or more tests failed:', err);
            }

            blueslip.reset(); // Resetting the mocking library after all tests

            console.log('All tests completed');
        }
    );
}

// Usage example:
const testFunctions = {
    'Test A': async function(module) { /* ... */ },
    'Test B': async function(module) { /* ... */ },
};

manageTests('./myModule', testFunctions);
```

