    this.validScripts = [];
    this.errors = [];
  }

  // Validate script structure and content
  validateScript(script, index) {
    try {
      if (typeof script !== 'object' || !script.url) {
        throw new Error(`Invalid script object at index ${index}: Missing URL`);
      }
      if (!/\.js$/.test(script.url)) {
        throw new Error(`Invalid script file type at index ${index}`);
      }
      if (!script.async || !script.end) {
        throw new Error(`Script missing async or end attribute at index ${index}`);
      }
    } catch (error) {
      console.warn(error.message);
      this.errors.push({ index, error: error.message });
    }
  }

  // Resolve dependencies to ensure correct order
  resolveDependencies() {
    const resolved = [];
    const unresolved = [];

    const addScript = (scriptIndex) => {
      if (resolved.includes(scriptIndex)) return;
      if (unresolved.includes(scriptIndex)) throw new Error(`Circular dependency detected at script ${scriptIndex}`);

      unresolved.push(scriptIndex);
      const script = this.scripts[scriptIndex];

      if (script.dependencies && Array.isArray(script.dependencies)) {
        for (const depIndex of script.dependencies) {
          addScript(depIndex);
        }
      }

      resolved.push(scriptIndex);
      unresolved.splice(unresolved.indexOf(scriptIndex), 1);
    };

    for (let i = 0; i < this.scripts.length; i++) {
      try {
        addScript(i);
      } catch (error) {
        console.warn(error.message);
        this.errors.push({ index: i, error: error.message });
      }
    }

    return resolved.reverse();
  }

  // Check for user-agent compatibility
  isUserAgentCompatible(script) {
    const userAgent = navigator.userAgent.toLowerCase();

    if (!script.userAgents || script.userAgents.length === 0) {
      return true;
    }

    return script.userAgents.some(agent => userAgent.includes(agent.toLowerCase()));
  }

  // Handle external data dependencies with a fallback mechanism
  checkExternalDataDependencies(script, index) {
    try {
      if (script.externalData && typeof script.externalData.check !== 'function') {
        throw new Error(`Invalid external data check function at index ${index}`);
      }

      const dataAvailable = script.externalData && script.externalData.check();
      if (!dataAvailable) {
        throw new Error(`External data not available for script at index ${index}`);
      }

    } catch (error) {
      console.warn(error.message);
      return false;
    }

    return true;
  }

  // Execute conditional scripts
  shouldExecuteScript(script, index) {
    if (!script.condition || typeof script.condition !== 'function') return true;

    try {
      return script.condition();
    } catch (error) {
      console.warn(`Conditional execution error at index ${index}:`, error.message);
      this.errors.push({ index, error: error.message });
      return false;
    }
  }

  // Compile valid scripts into an HTML string
  generateFooterHtml() {
    const resolvedIndices = this.resolveDependencies();

    for (const index of resolvedIndices) {
      const script = this.scripts[index];

      if (
        !this.errors.some(err => err.index === index) &&
        this.isUserAgentCompatible(script) &&
        this.checkExternalDataDependencies(script, index) &&
        this.shouldExecuteScript(script, index)
      ) {
        this.validScripts.push(`<script src="${script.url}" async></script>`);
      }
    }

    return `<footer>${this.validScripts.join('')}</footer>`;
  }
}

// Function to be used for generating the footer with scripts
function generateFooter(scripts) {
  const scriptManager = new ScriptManager(scripts);
  scriptManager.scripts.forEach((script, index) => scriptManager.validateScript(script, index));
  return scriptManager.generateFooterHtml();
}
