(function () {
    'use strict';

    angular.module('app').service('ForwardListManager', ['$window', '$q', function ($window, $q) {

        this.manageForwardList = function (resourceId, url, fieldNames) {
            let forwardList = []; // Assume this is initialized or fetched from a service
            const placeholder = "Placeholder for Update";

            const updateFieldInParentWindow = (fieldName, index) => {
                return $q((resolve, reject) => {
                    if (!$window.parent || typeof $window.parent.postMessage !== 'function') {
                        reject('Parent window is unavailable.');
                        return;
                    }

                    let timeout = setTimeout(() => {
                        reject('Timeout: No response from parent window.');
                    }, 5000);

                    const listener = ($event, data) => {
                        if (data && data.ack === fieldName && data.resourceId === resourceId) {
                            clearTimeout(timeout);
                            forwardList[index][fieldName] = data.updatedValue;
                            resolve();
                        }
                    };

                    $window.addEventListener('message', listener);

                    try {
                        $window.parent.postMessage({ action: 'updateField', resourceName: resourceId, fieldName }, url);
                    } catch (err) {
                        reject(err.message || 'Error sending message to parent window.');
                    }
                });
            };

            let promises = forwardList.map((item, index) => {
                for (let fieldName of fieldNames) {
                    if (fieldName in item) {
                        return updateFieldInParentWindow(fieldName, index);
                    }
                }

                // No matching field found; simulate successful update
                forwardList.push({ [placeholder]: `Updated at ${new Date().toISOString()}` });
                return $q.resolve();
            });

            return Promise.all(promises)
                .then(() => {
                    console.log('Forward list successfully updated.');
                })
                .catch(error => {
                    console.error('Update failed:', error);
                    alert(`Failed to update some fields: ${error}`);
                });
        };
    }]);
})();
```

