class StreamMerger {
  constructor() {
    this.streams = [];
    this.currentData = [];
    this.bufferLimit = 1000; // Example buffer limit to manage memory usage
    this.monitorMetrics();
  }

  addStream(stream) {
    if (typeof stream.getNextChunk === 'function') {
      this.streams.push({ stream, index: -1 });
    }
  }

  getNextMergedValue() {
    if (this.currentData.length > this.bufferLimit) {
      throw new Error('Buffer limit exceeded');
    }

    this.fetchNextChunks();
    this.currentData.sort((a, b) => a.value - b.value);

    return this.currentData.shift().value;
  }

  fetchNextChunks() {
    for (const { stream, index } of this.streams) {
      let chunk;
      try {
        chunk = stream.getNextChunk();
      } catch (error) {
        console.error(`Error fetching from stream: ${error.message}`);
        continue; // Graceful degradation on error
      }

      if (chunk && !Array.isArray(chunk)) {
        throw new Error('Unexpected data format');
      }

      for (const item of chunk || []) {
        this.currentData.push({ value: item, sourceIndex: index });
      }
    }
  }

  monitorMetrics() {
    setInterval(() => {
      const memoryUsage = process.memoryUsage().heapUsed / 1024 / 1024;
      console.log(`Memory Usage: ${memoryUsage.toFixed(2)} MB`);

      // Add additional metrics monitoring as needed
    }, 5000);
  }
}

// Example usage:
// Assuming `stream1`, `stream2`, ... are objects with a getNextChunk method returning an array of numbers.
const merger = new StreamMerger();
merger.addStream(stream1);
merger.addStream(stream2);

try {
  while (true) {
    console.log(merger.getNextMergedValue());
  }
} catch (error) {
  console.error('Error during merging:', error.message);
}
