#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

#define MAX_FILENAME_LENGTH 256
#define NEW_EXTENSION ".mod"

void modify_filename(const char *filename) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    int max_digits = 1, count = 0, i;

    if ((dir = opendir(".")) == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        char full_path[MAX_FILENAME_LENGTH];
        snprintf(full_path, sizeof(full_path), "%s/%s", ".", entry->d_name);

        if (stat(full_path, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
            const char *ext = strrchr(entry->d_name, '.');
            if (ext != NULL && strcmp(ext, NEW_EXTENSION) == 0) {
                char *num_part = strndup(entry->d_name + strlen(entry->d_name) - strlen(ext), strlen(entry->d_name) - strlen(ext));
                for (i = 0; num_part[i] != '\0'; i++) {
                    if (isdigit(num_part[i])) count++;
                }
                free(num_part);
                if (count > max_digits) max_digits = count;
            }
        }
    }

    closedir(dir);

    char base[MAX_FILENAME_LENGTH];
    strncpy(base, filename, sizeof(base));
    char *ext_pos = strrchr(base, '.');
    if (ext_pos != NULL) {
        *ext_pos = '\0';
    }

    char new_filename[MAX_FILENAME_LENGTH], num_str[12];
    snprintf(num_str, sizeof(num_str), "%0*d", max_digits + 1, 0);

    int current_num = 0;
    do {
        snprintf(new_filename, sizeof(new_filename), "%s%s%d%s", base, (ext_pos != NULL ? "." : ""), current_num++, NEW_EXTENSION);
        if (!stat(new_filename, &file_stat) || !S_ISREG(file_stat.st_mode)) {
            continue;
        }
    } while (++current_num);

    printf("New filename: %s\n", new_filename);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }
    modify_filename(argv[1]);
    return EXIT_SUCCESS;
}
```']

