class ThemeCacheManager:
    def __init__(self):
        self.default_theme_dir = None
        self.theme_cache = {}
        self.cache_lock = Lock()
        self.cleanup_interval = 3600  # seconds
        self.check_external_config()

    def check_external_config(self):
        try:
            response = requests.get("https://config-service.example.com/theme-dir")
            if response.status_code == 200:
                self.default_theme_dir = response.json().get('default_theme_dir')
            else:
                logging.warning("Using fallback default theme directory.")
                self.default_theme_dir = "/fallback/default-theme"
        except requests.RequestException as e:
            logging.error(f"Failed to retrieve default theme directory: {e}")
            self.default_theme_dir = "/fallback/default-theme"

