['```rust
use reqwest::{Client, Response, StatusCode};
use std::collections::HashMap;
use std::env;
use std::sync::Arc;
use tokio::time::{sleep, Duration};
use tracing::{info, error};

const MAX_RETRIES: usize = 5;

async fn fetch_with_retry(client: &Client, url: &str) -> Result<Response, reqwest::Error> {
    let mut attempts = 0;
    loop {
        match client.get(url).send().await {
            Ok(response) => return Ok(response),
            Err(e) if is_transient_error(&e) && attempts < MAX_RETRIES => {
                attempts += 1;
                let wait_time = compute_jittered_backoff(attempts);
                info!("Retrying in {:?} due to transient error: {:?}", wait_time, e);
                sleep(wait_time).await;
            }
            Err(e) => return Err(e),
        }
    }
}

fn is_transient_error(err: &reqwest::Error) -> bool {
    matches!(err.status(), Some(StatusCode::SERVICE_UNAVAILABLE)
              | Some(StatusCode::INTERNAL_SERVER_ERROR)
              | Some(StatusCode::BAD_GATEWAY))
}

fn compute_jittered_backoff(attempts: usize) -> Duration {
    let base = 100; // milliseconds
    let jitter = rand::random::<u64>() % (base * attempts / 2);
    tokio::time::Duration::from_millis(base * attempts as u64 + jitter)
}

async fn configure_http_client() -> Client {
    let https_only = env::var("HTTPS_ONLY").unwrap_or_else(|_| "false".to_string());
    let mut builder = reqwest::ClientBuilder::new();

    if https_only == "true" {
        info!("Configuring client for HTTPS only.");
        builder.use_rustls_tls();
    } else {
        info!("Configuring client to support both HTTP and HTTPS.");
        builder.use_native_tls();
    }

    // Optional: Configure session resumption, caching, etc.

    builder
        .build()
        .expect("Failed to build HTTP client")
}

#[tokio::main]
async fn main() {
    let backend_url = env::var("BACKEND_URL").unwrap_or_else(|_| "http://default.backend".to_string());
    let http_client = configure_http_client().await;

    match fetch_with_retry(&http_client, &backend_url).await {
        Ok(response) => {
            info!("Request successful: {:?}", response.status());
            // Process response
        }
        Err(e) => error!("Failed to make request: {:?}", e),
    }
}
```

