<?php

class SubscriptionRenewalProcessor {
    private $paymentGatewayClient;
    private $cache;
    private $dbConnection;
    private const MAX_RETRIES = 3;

    public function __construct($paymentGatewayClient, $cache, $dbConnection) {
        $this->paymentGatewayClient = $paymentGatewayClient;
        $this->cache = $cache;
        $this->dbConnection = $dbConnection;
    }

    public function processSubscriptionRenewal($userId) {
        try {
            $userProfile = $this->getUserProfileWithCache($userId);
            if (!$userProfile) {
                throw new Exception("User profile not found.");
            }

            $paymentStatus = $this->getPaymentStatusFromCache($userId);
            if ($paymentStatus !== 'pending') {
                return "No payment needed or already processed.";
            }

            $retries = 0;
            while ($retries < self::MAX_RETRIES) {
                try {
                    $response = $this->paymentGatewayClient->processPayment($userProfile['paymentInfo']);

                    if ($response->isSuccessful()) {
                        $this->updateDatabaseOnSuccess($userId);
                        return "Subscription renewed successfully.";
                    } else {
                        throw new Exception("Payment failed: " . $response->getError());
                    }
                } catch (Exception $e) {
                    $this->logError("Attempt {$retries + 1} failed: " . $e->getMessage(), $userId);

                    if ($this->isNetworkFailure($e)) {
                        $retries++;
                        continue;
                    }

                    return "Failed to process payment: " . $e->getMessage();
                }
            }

            return "Payment processing exceeded maximum retry attempts.";
        } catch (Exception $e) {
            $this->logError("Critical error in subscription renewal: " . $e->getMessage(), $userId);
            return "An error occurred while renewing the subscription. Please try again later.";
        }
    }

    private function getUserProfileWithCache($userId) {
        $cachedProfile = $this->cache->get("user_profile_{$userId}");

        if ($cachedProfile) {
            return json_decode($cachedProfile, true);
        }

        // Simulated database call
        $queryResult = $this->dbConnection->prepare("SELECT * FROM users WHERE id = ?");
        $queryResult->execute([$userId]);
        $profile = $queryResult->fetch();

        if ($profile) {
            $this->cache->set("user_profile_{$userId}", json_encode($profile), 3600); // Cache for an hour
        }

        return $profile;
    }

    private function getPaymentStatusFromCache($userId) {
        return $this->cache->get("payment_status_{$userId}") ?: 'pending';
    }

    private function updateDatabaseOnSuccess($userId) {
        $stmt = $this->dbConnection->prepare("UPDATE users SET payment_status = ? WHERE id = ?");
        $stmt->execute(['completed', $userId]);

        // Update cache
        $this->cache->set("payment_status_{$userId}", 'completed');
    }

    private function logError($message, $userId) {
        // Log to a file or logging service with minimal overhead
        error_log("User ID {$userId}: " . date('Y-m-d H:i:s') . " - " . $message);
    }

    private function isNetworkFailure(Exception $e) {
        return stripos($e->getMessage(), 'network failure') !== false;
    }
}
```

