import requests
from concurrent.futures import ThreadPoolExecutor
import pandas as pd

def fetch_weather_data(city_name, api_key, preferred_format='JSON'):
    def get_weather_from_api():
        base_url = "http://api.openweathermap.org/data/2.5/weather"
        params = {
            'q': city_name,
            'appid': api_key,
            'units': 'metric'
        }

        try:
            response = requests.get(base_url, params=params, timeout=10)
            response.raise_for_status()

            data = response.json()
            temperature = data['main']['temp']
            humidity = data['main']['humidity']
            return {'temperature': temperature, 'humidity': humidity}

        except requests.exceptions.HTTPError as http_err:
            print(f"HTTP error occurred: {http_err}")
        except requests.exceptions.ConnectionError:
            print("Connection error occurred. Please check your internet connection.")
        except requests.exceptions.Timeout:
            print("The request timed out. Please try again later.")
        except requests.exceptions.RequestException as err:
            print(f"An error occurred: {err}")

    def format_data_as_json(weather_data):
        return weather_data

    def format_data_as_csv(weather_data):
        df = pd.DataFrame([weather_data])
        return df.to_csv(index=False)

    # Using ThreadPoolExecutor for handling high concurrency
    with ThreadPoolExecutor(max_workers=10) as executor:
        future = executor.submit(get_weather_from_api)
        try:
            weather_data = future.result(timeout=15)
            if not weather_data:
                print("Failed to retrieve data.")
                return None

            if preferred_format.upper() == 'CSV':
                return format_data_as_csv(weather_data)
            else:  # Default to JSON
                return format_data_as_json(weather_data)

        except Exception as e:
            print(f"An unexpected error occurred: {e}")
            return None
