["```javascript
const crypto = require('crypto');
const fs = require('fs');

// Function to generate a random string hash
function generateRandomStringHash(length, charset, outputFormat, config = {}) {
    const defaultAlgorithm = config.algorithm || 'sha256';
    const hashFunction = crypto.createHash(defaultAlgorithm);

    // Generate the random string
    let result = '';
    for (let i = 0; i < length; i++) {
        const randomIndex = Math.floor(Math.random() * charset.length);
        result += charset[randomIndex];
    }

    // Hash the generated string
    hashFunction.update(result, 'utf8');
    const hashedData = hashFunction.digest();

    // Return based on outputFormat
    switch (outputFormat) {
        case 'hex':
            return hashedData.toString('hex');
        case 'base64':
            return hashedData.toString('base64');
        case 'raw':
            return hashedData;
        default:
            throw new Error(`Unsupported format: ${outputFormat}`);
    }
}

// Cache implementation
class SimpleCache {
    constructor(maxSize = 100, ttl = 30000) { // Default max size and TTL in ms
        this.cache = new Map();
        this.maxSize = maxSize;
        this.ttl = ttl;
    }

    set(key, value) {
        const now = Date.now();
        if (this.cache.size >= this.maxSize) {
            this.evict();
        }
        this.cache.set(key, { value, expiry: now + this.ttl });
    }

    get(key) {
        const item = this.cache.get(key);
        if (!item || item.expiry < Date.now()) {
            this.cache.delete(key);
            return null;
        }
        return item.value;
    }

    evict() {
        let oldestKey = null;
        let oldestTime = Infinity;

        for (const [key, { expiry }] of this.cache.entries()) {
            if (expiry < oldestTime) {
                oldestKey = key;
                oldestTime = expiry;
            }
        }

        if (oldestKey !== null) {
            this.cache.delete(oldestKey);
        }
    }
}

// Function to read a file synchronously
function readFileSync(filePath, cacheConfig = { enabled: false, maxSize: 100, ttl: 30000 }) {
    const start = Date.now();

    if (cacheConfig.enabled) {
        const cache = new SimpleCache(cacheConfig.maxSize, cacheConfig.ttl);
        const cachedContent = cache.get(filePath);

        if (cachedContent !== null) {
            console.log(`Cache hit for ${filePath}`);
            return cachedContent;
        }
    }

    try {
        const content = fs.readFileSync(filePath, 'utf8');

        if (cacheConfig.enabled) {
            const cache = new SimpleCache(cacheConfig.maxSize, cacheConfig.ttl);
            cache.set(filePath, content);
        }

        console.log(`File read successfully in ${(Date.now() - start)}ms`);
        return content;
    } catch (error) {
        console.error(`Error reading file ${filePath}:`, error.message);
        throw error;
    }
}

module.exports = { generateRandomStringHash, readFileSync };
