const axios = require('axios');

// Simulated cache mechanism
let certificateCache = new Map();

async function fetchCertificateAndKey(oauthRequest) {
    const caUrl = 'https://example-ca.com/certificate';
    const keyStorageUrl = `https://key-storage.service/private-key/${oauthRequest.clientId}`;

    try {
        const [certResponse, keyResponse] = await Promise.all([
            axios.get(caUrl),
            axios.get(keyStorageUrl)
        ]);

        return { cert: certResponse.data, privateKey: keyResponse.data };
    } catch (error) {
        throw new Error(`Failed to fetch certificate or private key: ${error.message}`);
    }
}

async function generatePEMCertificate(oauthRequest) {
    const cacheKey = `${oauthRequest.clientId}-${oauthRequest.scope}`;

    if (certificateCache.has(cacheKey)) {
        return certificateCache.get(cacheKey);
    }

    try {
        let { cert, privateKey } = await fetchCertificateAndKey(oauthRequest);

        // Handle pause/resume logic
        while (oauthRequest.paused) {
            await new Promise(resolve => setTimeout(resolve, 1000)); // Wait for 1 second before retrying
        }

        const pfx = crypto.createPrivateKey(privateKey);
        const certificateBuffer = Buffer.from(cert, 'base64');

        // Convert to PEM format
        const certPEM = `-----BEGIN CERTIFICATE-----\n${certificateBuffer.toString('ascii')}\n-----END CERTIFICATE-----`;
        const keyPEM = `-----BEGIN PRIVATE KEY-----\n${pfx.export({ type: 'pkcs8', format: 'pem' }).split('\n').join('\n  ')}\n-----END PRIVATE KEY-----`;

        const pemCertificate = `${certPEM}\n\n${keyPEM}`;

        // Cache the generated PEM certificate
        certificateCache.set(cacheKey, pemCertificate);

        return pemCertificate;
    } catch (error) {
        throw new Error(`Error generating PEM Certificate: ${error.message}`);
    }
}

module.exports = generatePEMCertificate;
