// dns_resolve.c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import "php_embed.h"
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_RETRIES 3
#define BACKOFF_TIME 2 // seconds

char* resolve_hostname(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];
    static char result[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    for (int retry = 0; retry < MAX_RETRIES; ++retry) {
        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) == 0) {
            for(p = res;p != NULL; p = p->ai_next) {
                inet_ntop(p->ai_family, &(((struct sockaddr_in*)p->ai_addr)->sin_addr), ipstr, sizeof ipstr);
                strcpy(result, ipstr);
            }
            freeaddrinfo(res);
            return result;
        } else {
            fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
            sleep(BACKOFF_TIME * (retry + 1)); // Exponential backoff
        }
    }
    return NULL; // DNS resolution failed after retries
}
