// api_request.php

<?php

function get_user_network_config($api_url, $hostname_ip) {
    static $cache = [];
    $cache_key = md5($hostname_ip);
    $cache_lifetime = 3600; // Cache for 1 hour

    if (isset($cache[$cache_key]) && time() - $cache[$cache_key]['timestamp'] < $cache_lifetime) {
        return $cache[$cache_key]['data'];
    }

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $api_url . "?ip=" . urlencode($hostname_ip));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    for ($retry = 0; $retry < 3; $retry++) {
        $response = curl_exec($ch);

        if (curl_errno($ch) == CURLE_OPERATION_TIMEDOUT || curl_getinfo($ch, CURLINFO_HTTP_CODE) == 429) { // Rate limit
            sleep(2 ** ($retry + 1)); // Exponential backoff
        } else {
            break;
        }
    }

    $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    if ($http_code >= 200 && $http_code < 300) {
        $cache[$cache_key] = [
            'timestamp' => time(),
            'data' => json_decode($response, true)
        ];
        return $cache[$cache_key]['data'];
    } else {
        error_log("API request failed with HTTP code: $http_code");
        curl_close($ch);
        return null;
    }
}

function resolve_and_fetch_config($hostname) {
    $api_url = "https://example.com/api/network-config";

    // Embed C function call using PHP
    $ip_address = php_embed_call("resolve_hostname", [$hostname]);
    if ($ip_address === false) {
        error_log("DNS resolution failed for hostname: $hostname");
        return ['status' => 'failure', 'error' => 'DNS Resolution Failed'];
    }

    $config = get_user_network_config($api_url, $ip_address);
    if ($config === null) {
        error_log("Failed to retrieve network configuration for IP: $ip_address");
        return ['status' => 'failure', 'error' => 'API Request Failed'];
    }

    return [
        'status' => 'success',
        'ip_address' => $ip_address,
        'config' => $config
    ];
}
