class PasswordUpdater
{
    private $dao;
    private $authService;
    private $logger;
    private $rateLimiter;

    public function __construct($dao, $authService, $logger, $rateLimiter)
    {
        $this->dao = $dao;
        $this->authService = $ authService;
        $this->logger = $logger;
        $this->rateLimiter = $rateLimiter;
    }

    public function updatePassword($userId, $newPassword)
    {
        // Step 1: Validate password strength
        if (!$this->validatePasswordStrength($newPassword)) {
            $this->logError("Invalid password strength", $userId);
            throw new Exception('Password does not meet the required criteria.');
        }

        // Step 5: Check rate limiting
        if (!$this->rateLimiter->isAllowed($userId, 'password_update')) {
            $this->logWarning("Rate limit exceeded for user", $userId);
            throw new Exception('Too many password update attempts. Please try again later.');
        }

        try {
            // Start a transaction to ensure atomic operation
            $this->dao->beginTransaction();

            // Step 2: Update the database with the new password (hashed)
            $success = $this->dao->updateUserPassword($userId, password_hash($newPassword, PASSWORD_BCRYPT));

            if (!$success) {
                throw new Exception('Failed to update password in the database.');
            }

            // Step 4: Integrate with external authentication service
            $authSuccess = $this->authService->syncPassword($userId, $newPassword);

            if (!$authSuccess) {
                throw new Exception('Failed to synchronize password with external authentication service.');
            }

            // Commit transaction if everything is successful
            $this->dao->commit();
            $this->logInfo("Password updated successfully", $userId);
        } catch (Exception $e) {
            // Rollback on any failure
            $this->dao->rollBack();
            $this->logError($e->getMessage(), $userId);

            throw new Exception('Password update failed. Please try again.');
        }
