import heapq
from functools import cmp_to_key
import logging
import time
from multiprocessing import Pool, cpu_count
from itertools import islice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def read_large_file(file_path, line_chunk_size=10000):
    """Yield successive chunks of lines from a file."""
    with open(file_path, 'r') as file:
        while True:
            lines = list(islice(file, line_chunk_size))
            if not lines:
                break
            yield lines

def process_lines(chunk, comparator):
    """Sort a chunk of lines using the custom comparator function."""
    return sorted(chunk, key=cmp_to_key(comparator))

def sort_large_file(file_path, comparator, use_parallel=False):
    """Sort lines from a large file and handle them in an efficient manner."""
    try:
        start_time = time.time()
        chunks_sorted = []

        if use_parallel:
            with Pool(cpu_count()) as pool:
                for chunk in read_large_file(file_path):
                    sorted_chunk = pool.apply_async(process_lines, (chunk, comparator))
                    chunks_sorted.append(sorted_chunk.get())
        else:
            for chunk in read_large_file(file_path):
                sorted_chunks = process_lines(chunk, comparator)
                chunks_sorted.extend(sorted_chunks)

        # Merge all sorted chunks
        heap = heapq.merge(*chunks_sorted)

        sequence_number_line = next(heap)  # Get last line after sorting
        logging.info(f"Processing time: {time.time() - start_time:.2f} seconds")

        return extract_sequence_number(sequence_number_line)

    except Exception as e:
        logging.error(f"Error encountered during processing: {e}")
        raise

def extract_sequence_number(line):
    """Extract the sequence number from a line."""
    # Assuming sequence number is at the end after validation
    parts = line.split()
    if len(parts) < 2:
        raise ValueError("Line format invalid for extracting sequence number")

    seq_num, checksum = parts[-1], parts[-2]

    if not validate_checksum(seq_num, checksum):
        raise ValueError("Checksum validation failed")

    return int(seq_num)

def validate_checksum(sequence_number, checksum):
    """Validate the sequence number against a known checksum."""
