struct OctreeNode {
    std::unique_ptr<OctreeNode> children[8] = {nullptr};
    std::vector<int> data;
    bool isLeaf;

    explicit OctreeNode(bool isLeaf = false) : isLeaf(isLeaf) {}
};

class DistributedOctree {
private:
    std::atomic<OctreeNode*> root;
    std::mutex treeMutex;
    std::size_t maxDepth;
    std::size_t capacity;
    std::atomic<std::size_t> nodeCount;

public:
    DistributedOctree(std::size_t featureSize, std::size_t numLeafNodes,
                      std::size_t maxDepth, std::size_t dataCapacity)
        : root(nullptr), maxDepth(maxDepth), capacity(dataCapacity), nodeCount(0) {

        // Initial allocation
        allocateInitialTree(numLeafNodes);
    }

    ~DistributedOctree() {
        clear(root.load());
    }

    void addData(int featureSize, const std::vector<int>& data) {
        std::lock_guard<std::mutex> lock(treeMutex);
        if (root == nullptr) {
            root = new OctreeNode();
        }

        auto node = root;
        for (std::size_t level = 0; level < maxDepth; ++level) {
            int index = determineChildIndex(node, data, level);
            if (!node->children[index]) {
                node->children[index] = std::make_unique<OctreeNode>(false);
                nodeCount++;
                if (nodeCount > capacity) {
                    expandCapacity();
                }
            }
            node = node->children[index].get();
        }

        // Add data at the leaf
        node->data.insert(node->data.end(), data.begin(), data.end());
        node->isLeaf = true;
    }

private:
    void allocateInitialTree(std::size_t numLeafNodes) {
        // Implementation of initial allocation logic to optimize memory layout
    }

    int determineChildIndex(const OctreeNode* node, const std::vector<int>& data, std::size_t level) {
        // Placeholder for determining child index based on feature size and current level
        return 0;
    }

    void expandCapacity() {
        capacity *= 2;  // Example strategy to double the capacity when exceeded
    }

    void clear(OctreeNode* node) {
        if (!node) return;

        for (auto& child : node->children) {
            clear(child.get());
        }

        delete node;
    }

    void preOrderTraversal(const OctreeNode* node, std::function<void(const OctreeNode*)> func) const {
        if (!node) return;
        func(node);
        for (const auto& child : node->children) {
            preOrderTraversal(child.get(), func);
        }
    }

    void inOrderTraversal(const OctreeNode* node, std::function<void(const OctreeNode*)> func) const {
        // Placeholder: In-order traversal not typically defined for trees like octrees
    }

    void postOrderTraversal(const OctreeNode* node, std::function<void(const OctreeNode*)> func) const {
        if (!node) return;
        for (const auto& child : node->children) {
            postOrderTraversal(child.get(), func);
        }
        func(node);
    }

public:
    template <typename Func>
    void traversePreOrder(Func func) const {
        preOrderTraversal(root.load(), func);
    }

    template <typename Func>
    void traverseInOrder(Func func) const {
        inOrderTraversal(root.load(), func);
    }

    template <typename Func>
    void traversePostOrder(Func func) const {
        postOrderTraversal(root.load(), func);
    }
};

// Example usage of the DistributedOctree
int main() {
    auto octree = std::make_unique<DistributedOctree>(10, 1000, 5, 1024);

    // Add data to the octree
    octree->addData(10, {1, 2, 3});

    // Traverse the octree using pre-order traversal
    octree->traversePreOrder([](const OctreeNode* node) {
        if (node->isLeaf) {
            std::cout << "Leaf Node with data: ";
            for (int val : node->data) {
                std::cout << val << ' ';
            }
            std::cout << '\n';
        } else {
            std::cout << "Internal Node\n";
        }
    });

    return 0;
}
