CalibrationFactors current_calibration_factors = {1.0, 1.0, 1.0};

// Simulated function to fetch calibration factors from a remote server
void fetch_calibration_factors(CalibrationFactors *factors) {
    // Assume this function updates `factors` with new values from the server
}

float calculate_weighted_average(SensorPacket packet) {
    return (packet.temperature * current_calibration_factors.calibration_temp +
            packet.humidity * current_calibration_factors.calibration_humidity +
            packet.pressure * current_calibration_factors.calibration_pressure) / 3.0;
}

void process_sensor_data_stream(SensorPacket packets[], size_t num_packets, int* max_avg_packet_id, float* max_weighted_avg) {
    time_t now = time(NULL);
    SensorPacket window[MAX_PACKETS];
    int window_count = 0;

    *max_weighted_avg = -1.0;
    *max_avg_packet_id = -1;

    for (size_t i = 0; i < num_packets; ++i) {
        pthread_mutex_lock(&lock);

        // Fetch calibration factors periodically
        fetch_calibration_factors(&current_calibration_factors);

        time_t packet_time = packets[i].timestamp;
        if (packet_time >= now - WINDOW_SIZE) {
            window[window_count++] = packets[i];
        }

        float weighted_avg = calculate_weighted_average(packets[i]);

        if (*max_weighted_avg < weighted_avg) {
            *max_weighted_avg = weighted_avg;
            *max_avg_packet_id = packets[i].packet_id;
        }

        pthread_mutex_unlock(&lock);

        // Remove outdated packets
        for (int j = 0; j < window_count; ++j) {
            if (window[j].timestamp < now - WINDOW_SIZE) {
                memmove(&window[j], &window[j + 1], (window_count - j - 1) * sizeof(SensorPacket));
                --window_count;
            }
        }

        // Simulate handling of packet duplication and missing values
    }
}

int main() {
    SensorPacket packets[MAX_PACKETS];
    int max_avg_packet_id;
    float max_weighted_avg;

    // Assume packets are filled with data

    process_sensor_data_stream(packets, MAX_PACKETS, &max_avg_packet_id, &max_weighted_avg);

    printf("Max Weighted Average: %f, Packet ID: %d\n", max_weighted_avg, max_avg_packet_id);

    return 0;
}
