    public int Seed
    {
        get => _seed ?? throw new InvalidOperationException("Seed not set.");
        set => _seed = value;
    }

    private Random _random;

    public DynamicRangeGenerator(T min, T max, int? seed = null)
    {
        if (min.CompareTo(max) > 0)
            throw new ArgumentException("Min cannot be greater than Max.");

        SetMin(min);
        SetMax(max);

        Seed = seed;
        ResetRandom();
    }

    private void SetMin(T value)
    {
        _min = value;
        CheckAndResetRange();
        UpdateRandomGenerator();
    }

    private void SetMax(T value)
    {
        _max = value;
        CheckAndResetRange();
        UpdateRandomGenerator();
    }

    private void ResetRandom()
    {
        if (_random != null && !_seed.HasValue)
            return;

        _random = new Random(_seed ?? Environment.TickCount);
    }

    private void UpdateRandomGenerator()
    {
        if (_min is double minDouble && _max is double maxDouble)
            _random = new Random((int)(_seed.GetValueOrDefault() * 1000000.0));
        else
            ResetRandom();
    }

    private void CheckAndResetRange()
    {
        // In case the range becomes invalid after setting Min/Max, handle gracefully.
        if (_min.CompareTo(_max) > 0)
        {
            var temp = _min;
            SetMin(_max);
            SetMax(temp);
        }
    }

    public T GenerateRandom(bool inclusive = true)
    {
        if (!_random.IsAlive) ResetRandom();

        double scale = (inclusive && typeof(T) == typeof(double)) ? 1.0 : double.Epsilon;
        double rawValue = _random.NextDouble() * scale + (_min is double minD ? minD : Convert.ToDouble(_min));

        return (T)(typeof(T) == typeof(int)
                ? (object)(_random.Next(Convert.ToInt32(_min), Convert.ToInt32(_max) + 1))
                : (object)Math.Round(rawValue, midPointCalculationPrecision(typeof(T))));
    }

    private int midPointCalculationPrecision(Type type)
    {
        return type == typeof(double) ? 15 : 0; // More precision for double midpoint
    }

    public T CalculateMidpoint()
    {
        var average = (Convert.ToDouble(_min) + Convert.ToDouble(_max)) / 2.0;
        return (T)(typeof(T) == typeof(int)
                ? (object)Math.Round(average)
                : (object)average);
    }

    public bool Intersects(DynamicRangeGenerator<T> other)
    {
        if (_min.CompareTo(other.Max) > 0 || _max.CompareTo(other.Min) < 0)
            return false;

        return true;
    }

    public override string ToString()
    {
        return $"DynamicRangeGenerator: Min = {_min}, Max = {_max}, Seed = {(_seed ?? -1)}";
    }
}
```

### Explanation:
- **Generic Type**: The class `DynamicRangeGenerator` is generic and can handle any type that implements `IComparable<T>`. This allows flexibility for integers and floating-point numbers.
- **Constructor and Properties**: Sets initial values, ensuring valid ranges with checks. Allows setting the seed to enable reproducibility.
- **Random Value Generation**: Uses lazy initialization of random number generator. The generation logic handles both integer and double types.
- **Midpoint Calculation**: Provides a midpoint method using type-specific precision for floating-point numbers.
- **Intersection Check**: Determines if two ranges overlap, ensuring accurate logical operations across different ranges.
- **ToString Override**: Offers a concise representation of the current state, including min, max, and seed values.

This implementation balances performance needs with flexibility and robustness required in scalable applications.']

["Below is an implementation of a flexible reduction utility in JavaScript. It uses worker threads to process multiple streams concurrently, supports both synchronous and asynchronous modes, and includes logging and backpressure mechanisms.

```javascript
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const os = require('os');
const { EventEmitter } = require('events');

class ReductionUtility extends EventEmitter {
  constructor(config) {
    super();
    this.config = config || {};
    this.asyncMode = this.config.asyncMode !== undefined ? this.config.asyncMode : true;
    this.defaultNumericValue = this.config.defaultNumericValue || 0;
    this.maxWorkers = Math.min(100, os.cpus().length * 2);
    this.currentWorkers = 0;
    this.queue = [];
    this.backpressureThreshold = this.config.backpressureThreshold || 50;
  }

  async processStream(streamId, dataGenerator) {
    if (this.currentWorkers >= this.maxWorkers) {
      return this.emit('backpressure', streamId);
    }

    const workerPromise = new Promise((resolve, reject) => {
      const worker = new Worker(__filename, { workerData: { streamId, dataGenerator } });

      worker.on('message', (result) => resolve(result));
      worker.on('error', (err) => reject(err));
      worker.on('exit', () => this.currentWorkers--);

      this.currentWorkers++;
    });

    if (this.asyncMode) {
      return workerPromise;
    } else {
      return new Promise((resolve, reject) => {
        resolve(workerPromise);
      }).then(resolve, reject);
    }
  }

  static runReduction({ streamId, dataGenerator }) {
    const results = [];

    for (let data of dataGenerator()) {
      if (!Number.isFinite(data)) {
        data = this.defaultNumericValue;
      }

      results.push(data);

      console.log(`[${new Date().toISOString()}] Stream: ${streamId}, Current State: ${results.reduce((a, b) => a + b, 0)}`);
    }

    const finalResult = results.reduce((a, b) => a + b, 0);
    parentPort.postMessage({ streamId, result: finalResult });
  }
}

if (!isMainThread) {
  ReductionUtility.runReduction(workerData);
} else {
  module.exports = ReductionUtility;
}

// Test Cases
async function test() {
  const utility = new ReductionUtility({
    asyncMode: true,
    defaultNumericValue: 0,
    backpressureThreshold: 10
  });

  // Simulate data generators
  const stream1Data = () => (new Array(100)).fill(1).map((_, i) => i);
  const stream2Data = () => ([1, null, 'a', undefined, 5].repeat(20));

  utility.on('backpressure', (streamId) => {
    console.log(`Backpressure triggered for stream: ${streamId}`);
  });

  try {
    await Promise.all([
      utility.processStream('stream1', stream1Data),
      utility.processStream('stream2', stream2Data)
    ]);

    console.log('All streams processed successfully.');
  } catch (error) {
    console.error('Error processing streams:', error);
  }
}

test();
```

### Explanation:
- **ReductionUtility Class:** Manages worker threads and handles data reduction.
- **processStream Method:** Handles both synchronous and asynchronous modes, spawning workers as needed.
- **runReduction Static Method:** Runs in each worker to process the stream data.
- **Backpressure Mechanism:** Checks if the maximum number of workers is reached and emits an event if so.
- **Logging:** Outputs detailed logs with timestamps for monitoring purposes.
- **Test Function:** Simulates different streams with varying data qualities, checking functionality."]

