#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <mysql/mysql.h>

// Function to initialize database connection, execute query, and retrieve user roles.
int fetch_user_roles(const char *server, const char *user, const char *password,
                     const char *database, const char *table) {
    MYSQL *conn;
    MYSQL_RES *result;
    MYSQL_ROW row;
    int role_count = 0;

    // Initialize MySQL connection
    conn = mysql_init(NULL);
    if (conn == NULL) {
        log_error("MySQL initialization failed.");
        return -1;
    }

    // Connect to the database server
    if (!mysql_real_connect(conn, server, user, password, database,
                            0, NULL, 0)) {
        log_error("Database connection failed: %s", mysql_error(conn));
        mysql_close(conn);
        return -1;
    }

    // Query to retrieve roles from specified table
    char query[256];
    snprintf(query, sizeof(query), "SELECT DISTINCT role_name FROM %s;", table);

    // Execute the query
    if (mysql_query(conn, query)) {
        log_error("Query execution failed: %s", mysql_error(conn));
        mysql_close(conn);
        return -1;
    }

    result = mysql_store_result(conn);
    if (result == NULL) {
        log_error("Failed to store result: %s", mysql_error(conn));
        mysql_close(conn);
        return -1;
    }

    // Process the results and count roles
    while ((row = mysql_fetch_row(result))) {
        const char *role_name = row[0];
        printf("Role: %s\n", role_name);  // Example of handling each role

        role_count++;
    }

    // Free resources and close connection
    mysql_free_result(result);
    mysql_close(conn);

    return role_count;
}

// Helper function to log errors (stub implementation)
void log_error(const char *message, ...) {
    va_list args;
    va_start(args, message);
    vfprintf(stderr, message, args);
    fprintf(stderr, "\n");
    va_end(args);
}

int main() {
    const char *server = "your_server";
    const char *user = "your_user";
    const char *password = "your_password";
    const char *database = "your_database";
    const char *table = "roles_table";

    int num_roles = fetch_user_roles(server, user, password, database, table);
    if (num_roles >= 0) {
        printf("Number of roles retrieved: %d\n", num_roles);
    } else {
        fprintf(stderr, "Failed to retrieve roles.\n");
    }

    return 0;
}
```

### Explanation:
- **MySQL Connection**: The code uses MySQL's C API to connect to the database and execute a query.
- **Error Handling**: Logs errors using `log_error` function with detailed messages.
- **Query Execution**: Uses `mysql_query` to run a SQL command and retrieves roles from a specified table.
- **Result Processing**: Fetches rows one by one, counting them as it prints each role name.
- **Resource Management**: Properly frees results and closes the connection to avoid memory leaks.']

