#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* validateAndTrimString(const char *input, size_t maxSize, int (*callback)(const char*)) {
    if (strlen(input) > maxSize) {
        return NULL;
    }

    // Allocate memory for the new string with space for null terminator and '/'
    char *trimmed = malloc(strlen(input) + 2);
    if (!trimmed) {
        return NULL; // Handle allocation failure
    }

    // Copy input to trimmed, trimming trailing whitespace
    char *end = trimmed;
    while (*input != '\0') {
        if (isspace((unsigned char)*input)) {
            while (isspace((unsigned char)*(++input))) {}
            break;
        }
        *(end++) = *(input++);
    }

    // Null-terminate and append '/'
    *end++ = '/';
    *end = '\0';

    // Optional callback invocation
    if (callback && !callback(trimmed)) {
        free(trimmed);
        return NULL;
    }

    return trimmed;
}
