function filterDOMElements(rootNode, selector, testFunction) {
    const result = [];

    function traverse(node) {
        if (!node) return;

        // Apply the test function to determine if node matches criteria
        if (testFunction(node)) {
            result.push(node);
        }

        // Traverse child nodes
        for (let child of node.childNodes) {
            traverse(child);
        }
    }

    // Start traversal from rootNode
    traverse(rootNode);

    return result;
}
