double compute_average_of_last_two_fields(const char *line) {
    int num1, num2;
    double average;
    const char *last_comma = strrchr(line, ',');

    // Get the last field
    const char *last_field_start = last_comma ? last_comma + 1 : line;

    // Find the second to last field
    const char *second_last_comma = (last_comma) ? strrchr(line, ',', strlen(line) - (last_comma - line) - 1) : NULL;
    const char *second_last_field_start = (second_last_comma) ? second_last_comma + 1 : NULL;

    if (!second_last_field_start || !sscanf(second_last_field_start, "%d", &num2) == 1 ||
        !sscanf(last_field_start, "%d", &num1) == 1) {
        fprintf(stderr, "Error parsing numerical fields.\n");
        return -1; // Indicate error
    }

    average = (num1 + num2) / 2.0;
    return average;
}

