#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

#define MAX_NAME_LENGTH 255
#define MIN_READABLE_LENGTH 10

typedef struct {
    char current_name[256];
    size_t size;
    time_t last_modification_timestamp;
} FileMetadata;

const char *extensions[] = {"txt", "jpg", "png", "gif"};
const int num_extensions = sizeof(extensions) / sizeof(extensions[0]);

char* sanitize_filename(const char* filename, char* sanitized_name, int max_length) {
    const char* valid_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._-";
    size_t i, j;

    for (i = 0, j = 0; filename[i] != '\0' && j < max_length - 1; ++i) {
        if (strchr(valid_chars, filename[i])) {
            sanitized_name[j++] = filename[i];
        } else {
            sanitized_name[j++] = '_';
        }
    }

    if (j >= min(MIN_READABLE_LENGTH, max_length - 1)) {
        sanitized_name[j] = '\0';
    } else {
        // Ensure minimum readable portion
        strncpy(sanitized_name + j, filename + strlen(filename) - MIN_READABLE_LENGTH + 1,
                MIN_READABLE_LENGTH);
        sanitized_name[min(j + MIN_READABLE_LENGTH, max_length - 1)] = '\0';
    }

    return sanitized_name;
}

char* generate_sequence(const FileMetadata *metadata) {
    time_t now = time(NULL);
    char* sequence = malloc(21); // Enough for size in bytes + milliseconds
    if (!sequence) return NULL;

    snprintf(sequence, 21, "%zu_%lu", metadata->size, (unsigned long)(now % 1000));
    return sequence;
}

char* generate_new_filename(FileMetadata *metadata) {
    char sanitized_name[256];
    char *base_name = strtok(strdup(metadata->current_name), ".");

    if (!base_name) base_name = "";

    sanitize_filename(base_name, sanitized_name, MAX_NAME_LENGTH - 20);
    char* sequence = generate_sequence(metadata);

    if (!sequence) {
        free(base_name);
        return NULL;
    }

    int ext_index = rand() % num_extensions;
    const char *extension = extensions[ext_index];

    size_t total_length = strlen(sanitized_name) + strlen(sequence) + strlen(extension) + 1;

    if (total_length > MAX_NAME_LENGTH) {
        size_t truncate_len = total_length - MAX_NAME_LENGTH + 3; // for sequence and dot
        sanitized_name[MAX_NAME_LENGTH - truncate_len] = '\0';
    }

    char *new_filename = malloc(total_length);
    if (!new_filename) {
        free(sequence);
        free(base_name);
        return NULL;
    }

    snprintf(new_filename, total_length, "%s_%s.%s", sanitized_name, sequence, extension);

    free(sequence);
    free(base_name);

    return new_filename;
}

void rename_files(FileMetadata *files, size_t num_files) {
    if (!files || !num_files) return;

    for (size_t i = 0; i < num_files; ++i) {
        char *new_filename = generate_new_filename(&files[i]);

        if (!new_filename) {
            fprintf(stderr, "Failed to allocate memory for new filename.\n");
            continue;
        }

        printf("Renaming '%s' to '%s'\n", files[i].current_name, new_filename);

        // Here you would actually rename the file using system calls,
        // e.g., rename(files[i].current_name, new_filename);

        free(new_filename);
    }
}
