    EVP_add_cipher(EVP_aes_192_cbc());
    EVP_add_cipher(EVP_aes_256_cbc());

    // Add Camellia block ciphers
    EVP_add_cipher(EVP_camellia_128_cbc());
    EVP_add_cipher(EVP_camellia_192_cbc());
    EVP_add_cipher(EVP_camellia_256_cbc());

    // Add MD5 and SHA digest algorithms
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha224());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest(EVP_sha384());
    EVP_add_digest(EVP_sha512());

    // Create necessary aliases for MD5 and SHA
    EVP_add_digest_alias("md5", "MD5");
    EVP_add_digest_alias("sha1", "SHA1");

    // Add RSA with SHA1
    EVP_add_cipher(EVP_pkey_rsa());
    EVP_add_digest_alias("RSA-SHA1", "rsa_with_sha1");

    // Log initialization of cryptographic primitives (example log statement)
    printf("Cryptographic library initialized with AES, Camellia, MD5, SHA, and RSA-SHA1.\n");

    // Handle potential errors
    if (!EVP_aes_128_cbc() || !EVP_camellia_128_cbc()) {
        fprintf(stderr, "Error initializing cryptographic primitives.\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
}

