// Function to handle deserialization in Java environment.
JNIEXPORT jint JNICALL Java_convertAndDeserialize(JNIEnv *env, jobject obj,
                                                 jstring jpegFilePath,
                                                 jstring pdfOutputPath,
                                                 jbyteArray byteArray,
                                                 jlong maxBufferSize) {
    const char *jpegPath = (*env)->GetStringUTFChars(env, jpegFilePath, 0);
    const char *pdfPath = (*env)->GetStringUTFChars(env, pdfOutputPath, 0);

    FILE *jpegFile = fopen(jpegPath, "rb");
    if (!jpegFile) {
        fprintf(stderr, "Failed to open JPEG file.\n");
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        return 1;
    }

    int conversionResult = convertJpegToPdf(jpegFile, pdfPath);
    fclose(jpegFile);

    if (conversionResult != 0) {
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        return 1;
    }

    jbyte *bytes = (*env)->GetByteArrayElements(env, byteArray, NULL);
    jlong byteLength = (*env)->GetArrayLength(env, byteArray);

    if (byteLength > maxBufferSize) {
        fprintf(stderr, "Deserialization buffer size exceeds maximum allowed.\n");
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);
        return 1;
    }

    jobjectInputStream = (jobjectInputStream *)malloc(sizeof(jobjectInputStream));
    if (!jobjectInputStream) {
        fprintf(stderr, "Memory allocation failed for ObjectInputStream.\n");
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);
        return 1;
    }

    jclass objectInputStreamClass = (*env)->FindClass(env, "java/io/ObjectInputStream");
    if (!objectInputStreamClass) {
        fprintf(stderr, "ObjectInputStream class not found.\n");
        free(jobjectInputStream);
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);
        return 1;
    }

    jmethodID constructor = (*env)->GetMethodID(env, objectInputStreamClass, "<init>", "([B)V");
    if (!constructor) {
        fprintf(stderr, "ObjectInputStream constructor not found.\n");
        free(jobjectInputStream);
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);
        return 1;
    }

    jobjectInputStream->stream = (*env)->NewObjectA(env, objectInputStreamClass, constructor, &bytes);

    if ((*env)->ExceptionCheck(env)) {
        fprintf(stderr, "Deserialization exception occurred.\n");
        free(jobjectInputStream);
        (*env)->DeleteLocalRef(env, jobjectInputStream->stream);
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);
        return 1;
    }

    // Assuming a method exists to read the object from the stream
    jmethodID readObjectMethod = (*env)->GetMethodID(env, objectInputStreamClass, "readObject", "()Ljava/lang/Object;");
    if (!readObjectMethod) {
        fprintf(stderr, "readObject method not found.\n");
        free(jobjectInputStream);
        (*env)->DeleteLocalRef(env, jobjectInputStream->stream);
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);
        return 1;
    }

    jthrowable exception = NULL;
    jobject deserializedObject = (jobject)(*env)->CallObjectMethodA(env, jobjectInputStream->stream, readObjectMethod, &exception);

    if (exception) {
        const char *message = (*env)->GetStringUTFChars(env, (*env)->ExceptionDescribe(env), 0);
        fprintf(stderr, "Deserialization failed: %s\n", message);
        (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
        (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
        (*env)->DeleteLocalRef(env, exception);
        (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);
        free(jobjectInputStream);
        (*env)->DeleteLocalRef(env, jobjectInputStream->stream);
        return 1;
    }

    // Clean up
    (*env)->DeleteLocalRef(env, jobjectInputStream->stream);
    free(jobjectInputStream);

    (*env)->ReleaseStringUTFChars(env, jpegFilePath, jpegPath);
    (*env)->ReleaseStringUTFChars(env, pdfOutputPath, pdfPath);
    (*env)->ReleaseByteArrayElements(env, byteArray, bytes, 0);

    return 0;
}
