#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>

#define MAX_COMMANDS 100
#define BUFFER_SIZE 1024

volatile sig_atomic_t interrupted = 0;

void handle_sigint(int sig) {
    interrupted = 1;
}

void execute_commands(const char *commands, const char *output_dir) {
    signal(SIGINT, handle_sigint);

    char *cmds[MAX_COMMANDS];
    int cmd_count = 0;

    // Split commands by semicolon
    char *command = strtok(strdup(commands), ";");
    while (command != NULL && cmd_count < MAX_COMMANDS) {
        cmds[cmd_count++] = command;
        command = strtok(NULL, ";");
    }

    for (int i = 0; i < cmd_count; ++i) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            exit(EXIT_FAILURE);
        } else if (pid == 0) { // Child process
            char output_file[256];
            snprintf(output_file, sizeof(output_file), "%s/command_%d_output.txt", output_dir, i);

            int fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (fd == -1) {
                perror("open");
                exit(EXIT_FAILURE);
            }

            // Redirect stdout and stderr
            dup2(fd, STDOUT_FILENO);
            dup2(fd, STDERR_FILENO);
            close(fd);

            // Create a new process group
            setpgid(0, 0);

            // Execute the command
            execlp("/bin/sh", "sh", "-c", cmds[i], NULL);
            perror("execlp");
            exit(EXIT_FAILURE);
        }
    }

    while (cmd_count > 0) {
        if (interrupted) {
            for (int i = 0; i < cmd_count; ++i) {
                kill(-pid, SIGINT); // Send SIGINT to all child processes
            }
            interrupted = 0;
        }

        int status;
        pid_t wpid = wait(&status);
        if (wpid == -1 && errno != EINTR) {
            perror("wait");
            break;
        }

        for (int i = 0; i < cmd_count; ++i) {
            if (wpid == cmds[i]) {
                --cmd_count;
                for (int j = i; j < cmd_count; ++j) {
                    cmds[j] = cmds[j + 1];
                }
                break;
            }
        }
    }

    printf("All commands have been executed or terminated.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <commands> <output_dir>\n", argv[0]);
        return EXIT_FAILURE;
    }

    execute_commands(argv[1], argv[2]);

    return EXIT_SUCCESS;
}
```

This code implements the specified requirements by:

- Splitting input commands separated by semicolons.
- Creating a new process group for each command to handle signals independently.
- Redirecting standard output and error streams to separate files.
- Handling SIGINT to terminate all child processes gracefully.
- Managing resources efficiently with proper file descriptor handling.
- Providing feedback on the execution status of commands.']

