    private static Session setupSSHConnection(JSch jsch, String username, String sshHost)
            throws JSchException {
        jsch.setConfig("StrictHostKeyChecking", "no");
        return jsch.getSession(username, sshHost, 22).setPassword(password).open();
    }

    private static void validateAndCreateDirectory(Session session, String backupDir) throws SftpException {
        Channel channel = session.openChannel("sftp");
        channel.connect();

        ChannelSftp sftpChannel = (ChannelSftp) channel;
        try {
            if (!sftpChannel.exists(backupDir)) {
                sftpChannel.mkdir(backupDir);
            }
        } catch (IOException e) {
            logger.log(Level.WARNING, "Failed to create directory", e);
            throw new RuntimeException(e);
        } finally {
            channel.disconnect();
        }
    }

    private static File createTarGz(String sourceDirPath) throws IOException {
        String baseName = sourceDirPath + ".tar.gz";
        FileOutputStream fos = new FileOutputStream(baseName);
        GzipCompressorOutputStream gzip = new GzipCompressorOutputStream(fos);
        TarArchiveOutputStream tarOut = new TarArchiveOutputStream(gzip);

        Files.walk(Paths.get(sourceDirPath))
                .filter(path -> !Files.isDirectory(path))
                .forEach(filePath -> {
                    try {
                        String entryName = sourceDirPath.relativize(filePath).toString();
                        TarArchiveEntry entry = new TarArchiveEntry(filePath.toFile(), entryName);
                        entry.setSize(filePath.toFile().length());
                        tarOut.putArchiveEntry(entry);

                        Files.copy(filePath, tarOut);
                        tarOut.closeArchiveEntry();
                    } catch (IOException e) {
                        logger.log(Level.SEVERE, "Error creating tar.gz", e);
                    }
                });

        tarOut.finish();
        gzip.close();
        fos.close();

        return new File(baseName);
    }

    private static boolean uploadToRemote(String host, Session session, File file, String remotePath)
            throws JSchException, SftpException {
        Channel channel = session.openChannel("sftp");
        channel.connect();

        ChannelSftp sftpChannel = (ChannelSftp) channel;
        try {
            sftpChannel.put(file.getAbsolutePath(), remotePath + "/" + file.getName());
            return true;
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to upload file", e);
            return false;
        } finally {
            channel.disconnect();
        }
    }

