#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "jansson.h" // Assuming Jansson library is used for JSON parsing

#define MAX_THREADS 1024
#define LOG_LEVELS[] = {"DEBUG", "INFO", "WARN", "ERROR"}

typedef struct {
    char *db_host;
    int db_port;
    char *username;
    char *password;
    int threads;
    int max_connections;
    const char *log_level;
    double cpu_usage;
    double memory_usage;
} Config;

int is_valid_hostname(const char *hostname) {
    if (strlen(hostname) > 255 || strchr(hostname, '.') == NULL)
        return 0;
    char *dot = hostname;
    while ((dot = strchr(dot + 1, '.')) != NULL) {
        if (!isalnum(*(dot - 1))) return 0;
    }
    return isalnum(*hostname);
}

int is_valid_port(int port) {
    return (port > 0 && port <= 65535);
}

const char *is_valid_log_level(const char *level) {
    for (size_t i = 0; i < sizeof(LOG_LEVELS) / sizeof(char*); ++i)
        if (strcmp(level, LOG_LEVELS[i]) == 0)
            return level;
    return NULL;
}

int is_non_empty_string(const char *str) {
    return str != NULL && strlen(str) > 0;
}

int parse_config(const char *json_data, Config *config) {
    json_error_t error;
    json_t *root = json_loads(json_data, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return 0;
    }

    json_t *db_host = json_object_get(root, "db_host");
    json_t *db_port = json_object_get(root, "port");
    json_t *username = json_object_get(root, "username");
    json_t *password = json_object_get(root, "password");
    json_t *threads = json_object_get(root, "threads");
    json_t *max_connections = json_object_get(root, "max_connections");
    json_t *log_level = json_object_get(root, "log_level");
    json_t *cpu_usage = json_object_get(root, "cpu_usage");
    json_t *memory_usage = json_object_get(root, "memory_usage");

    if (!json_is_string(db_host) || !is_valid_hostname(json_string_value(db_host)) ||
        !json_is_integer(db_port) || !is_valid_port(json_integer_value(db_port)) ||
        !json_is_string(username) || !is_non_empty_string(json_string_value(username)) ||
        !json_is_string(password) || !is_non_empty_string(json_string_value(password)) ||
        !json_is_integer(threads) || json_integer_value(threads) < 1 ||
        !json_is_integer(max_connections) || json_integer_value(max_connections) <= 0 ||
        !json_is_string(log_level) || is_valid_log_level(json_string_value(log_level)) == NULL)
    {
        json_decref(root);
        return 0;
    }

    config->db_host = strdup(json_string_value(db_host));
    config->db_port = json_integer_value(db_port);
    config->username = strdup(json_string_value(username));
    config->password = strdup(json_string_value(password));
    config->threads = json_integer_value(threads);
    config->max_connections = json_integer_value(max_connections);
    config->log_level = json_string_value(log_level);

    if (json_is_real(cpu_usage) && json_number_value(cpu_usage) >= 0 && json_number_value(cpu_usage) <= 100)
        config->cpu_usage = json_number_value(cpu_usage);

    if (json_is_real(memory_usage) && json_number_value(memory_usage) >= 0 && json_number_value(memory_usage) <= 1024)
        config->memory_usage = json_number_value(memory_usage);

    json_decref(root);
    return 1;
}

int validate_config(const char *filename, Config *config) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *json_data = (char *)malloc(length + 1);
    fread(json_data, 1, length, file);
    fclose(file);
    json_data[length] = '\0';

    int valid = parse_config(json_data, config);
    free(json_data);

    return valid;
}
