        try
        {
            if (_memoryTracker.CurrentUsage > _memoryBudgetBytes)
                ReduceOperationScope();

            var currentState = ExtractInitialState(inputByteArray);
            ProcessTransitions(currentState, inputByteArray, transitionPolicy);

