            // Retrieve the schema validator for validation
            String className = clazz.getSimpleName();
            JsonSchemaValidator validator = schemaCache.computeIfAbsent(className, JsonConverterUtil::createSchemaValidator);

            if (!validator.validateJson(jsonTree)) {
                logger.error("JSON structure does not match the predefined schema.");
                return null;
