#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int read_integers(int **array) {
    int *buffer = NULL, size = 0, capacity = 10, value, i;

    buffer = (int *)malloc(capacity * sizeof(int));
    if (!buffer) return -1;

    while (scanf("%d", &value) == 1) {
        if (size >= capacity) {
            capacity *= 2;
            int *new_buffer = realloc(buffer, capacity * sizeof(int));
            if (!new_buffer) {
                free(buffer);
                return -1;
            }
            buffer = new_buffer;
        }
        buffer[size++] = value;
    }

    *array = (int *)realloc(buffer, size * sizeof(int));
    if (*array == NULL && size != 0) {
        free(buffer);
        return -1;
    }

    return size;
}

void process_integers() {
    int *numbers = NULL;
    int count = read_integers(&numbers);

    if (count <= 0 || numbers == NULL) {
        fprintf(stderr, "Error reading integers.\n");
        exit(EXIT_FAILURE);
    }

    int max_value = INT_MIN;
    for (int i = 0; i < count; ++i) {
        if (numbers[i] > max_value) {
            max_value = numbers[i];
        }
    }

    printf("Largest integer: %d\n", max_value);

    free(numbers);
}

void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T **array, int count) {
    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*array)[i].RNTI = rand() % 500;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 50;
        (*array)[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG to 0 or 1
    }
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array, int count) {
    if (array != NULL) {
        free(array);
    }
}

int main() {
    process_integers();

    int crc_count = 5; // Example size for CRC indications array
    NFAPI_CRC_INDICATION_PDU_T *crc_array = NULL;

    populate_crc_indications(&crc_array, crc_count);

    free_crc_indications(crc_array, crc_count);

    return 0;
}
