['Below is an implementation in C++ and Java, designed to handle memory allocation and management tasks as described. The C++ part manages dynamic memory allocations using smart pointers for simplicity, while the Java section handles remote service connections.

```cpp
#include <iostream>
#include <cstdlib>
#include <ctime>
#include <random>
#include <memory>

struct Record {
    int value;
};

class MemoryManager {
public:
    std::unique_ptr<long[]> allocateOffsets(size_t size) {
        try {
            return std::make_unique<long[]>(size);
        } catch (const std::bad_alloc&) {
            logError("Failed to allocate memory for offsets.");
            return nullptr;
        }
    }

    std::unique_ptr<int[]> allocateKeys(size_t size) {
        try {
            return std::make_unique<int[]>(size);
        } catch (const std::bad_alloc&) {
            logError("Failed to allocate memory for keys.");
            return nullptr;
        }
    }

    std::unique_ptr<Record[]> allocateRecords(size_t size, int minVal, int maxVal) {
        try {
            auto records = std::make_unique<Record[]>(size);
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dist(minVal, maxVal);

            for (size_t i = 0; i < size; ++i) {
                records[i].value = dist(gen);
            }
            return records;
        } catch (const std::bad_alloc&) {
            logError("Failed to allocate memory for records.");
            return nullptr;
        }
    }

private:
    void logError(const std::string& message) {
        std::cerr << "ERROR: " << message << std::endl;
    }
};

```

```java
import java.io.IOException;
import java.net.Socket;

public class RemoteServiceConnector {

    private static final int MAX_RETRIES = 5;

    public boolean connectToRemoteService(String host, int port) {
        int attempts = 0;
        while (attempts < MAX_RETRIES) {
            try (Socket socket = new Socket(host, port)) {
                // Assume some initial handshake or setup code here
                System.out.println("Successfully connected to remote service.");
                return true;
            } catch (IOException e) {
                attempts++;
                logError("Attempt " + attempts + ": Connection failed. Retrying...");
                try {
                    Thread.sleep(1000);  // Wait before retrying
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    logError("Interrupted during connection retries.");
                    return false;
                }
            }
        }
        logError("All attempts to connect have failed.");
        return false;
    }

    private void logError(String message) {
        System.err.println("ERROR: " + message);
    }
}

public class MainProgram {
    public static int mainFunction() {
        // Example configuration values
        size_t offsetSize = 100;
        size_t keySize = 50;
        size_t recordSize = 200;
        int minValue = 1, maxValue = 100;

        MemoryManager memoryManager = new MemoryManager();

        auto offsets = memoryManager.allocateOffsets(offsetSize);
        if (!offsets) return 1; // Allocation failed

        auto keys = memoryManager.allocateKeys(keySize);
        if (!keys) return 2; // Allocation failed

        auto records = memoryManager.allocateRecords(recordSize, minValue, maxValue);
        if (!records) return 3; // Allocation failed

        // Java service connection part
        RemoteServiceConnector connector = new RemoteServiceConnector();
        if (!connector.connectToRemoteService("remote.example.com", 8080)) {
            return 4; // Connection to remote service failed
        }

        // Return success code
        return 0;
    }
}
