use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::io::{self, BufRead};
use std::thread;

#[repr(C)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: CRCIndicationRel8Tag,
}

#[repr(C)]
struct CRCIndicationRel8Tag {
    crc_flag: bool,
}

fn processAndAggregateData() -> io::Result<()> {
    let reader = io::stdin();
    let input: Vec<String> = reader.lock().lines()
        .filter_map(Result::ok)
        .collect();

    // Shared state for aggregation
    let even_count = Arc::new(Mutex::new(0));
    let odd_count = Arc::new(Mutex::new(0));
    let sum = Arc::new(Mutex::new(0));
    let max_value = Arc::new(Mutex::new(i32::MIN));

    let handles: Vec<_> = input.into_par_iter().enumerate().map(|(i, line)| {
        let even_count = Arc::clone(&even_count);
        let odd_count = Arc::clone(&odd_count);
        let sum = Arc::clone(&sum);
        let max_value = Arc::clone(&max_value);

        thread::spawn(move || {
            if let Ok(num) = line.parse::<i32>() {
                // Locks and updates each shared resource
                {
                    let mut even_c = even_count.lock().unwrap();
                    *even_c += if num % 2 == 0 {1} else {0};
                }

                {
                    let mut odd_c = odd_count.lock().unwrap();
                    *odd_c += if num % 2 != 0 {1} else {0};
                }

                {
                    let mut s = sum.lock().unwrap();
                    *s += num;
                }

                {
                    let mut m = max_value.lock().unwrap();
                    if num > *m {
                        *m = num;
                    }
                }
            }
        })
    }).collect();

    for handle in handles {
        handle.join().expect("Thread panicked");
    }

    // Create NFAPI_CRC_INDICATION_PDU_T array
    let num_elements = 10; // Example size, adjust as needed
    let mut crc_indications: Vec<NFAPI_CRC_INDICATION_PDU_T> = vec![NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: 1, // Dummy value
        rnti: 2, // Dummy value
        crc_indication_rel8_tag: CRCIndicationRel8Tag { crc_flag: false },
    }; num_elements];

    for i in 0..num_elements {
        crc_indications[i].crc_indication_rel8_tag.crc_flag = rand::random(); // Randomize the flag
    }

    // Output summary results (for demonstration purposes)
    let even_c = *even_count.lock().unwrap();
    let odd_c = *odd_count.lock().unwrap();
    let s = *sum.lock().unwrap();
    let m = *max_value.lock().unwrap();

    println!("Even count: {}, Odd count: {}", even_c, odd_c);
    println!("Sum of all numbers: {}", s);
    println!("Maximum value encountered: {}", m);

    Ok(())
}

fn main() -> io::Result<()> {
    processAndAggregateData()
}
