public class HashModule {

    /**
     * Computes the MD5 hash for a given input string.
     *
     * @param input The input string to be hashed.
     * @return A hexadecimal string representation of the MD5 hash, or null if an error occurs.
     */
    public static String computeMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();

            for (byte b : digest) {
                hexString.append(String.format("%02x", b));
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Error: MD5 algorithm not found.");
            return null;
        } catch (Exception e) {
            System.err.println("Hashing error occurred: " + e.getMessage());
            return null;
        }
