// C: Command Execution Module

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>

/**
 * Executes an external command asynchronously and waits for its completion.
 *
 * @param command The command to be executed, including arguments.
 */
void executeCommand(const char* hash, const char* command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("Fork failed");
        return;
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for the child to finish

        if (WIFEXITED(status)) {
            printf("Child exited with status %d\n", WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Child killed by signal %d\n", WTERMSIG(status));
        }
    } else { // Child process
        char commandLine[256];
        snprintf(commandLine, sizeof(commandLine), "%s %s", command, hash);

        int fd[2];
        if (pipe(fd) == -1) {
            perror("Pipe failed");
            exit(EXIT_FAILURE);
        }

        pid_t child_pid = fork();
        if (child_pid < 0) {
            perror("Fork failed");
            close(fd[0]);
            close(fd[1]);
            exit(EXIT_FAILURE);
        } else if (child_pid == 0) { // Grand-child process
            dup2(fd[1], STDOUT_FILENO); 
            dup2(fd[1], STDERR_FILENO);
            close(fd[0]);
            execlp("sh", "sh", "-c", commandLine, NULL);

            perror("execlp failed");
            exit(EXIT_FAILURE);
        } else { // Parent process of child
            close(fd[1]);

            char buffer[128];
            ssize_t bytesRead;
            while ((bytesRead = read(fd[0], buffer, sizeof(buffer) - 1)) > 0) {
                buffer[bytesRead] = '\0';
                printf("Command Output: %s", buffer);
            }

            close(fd[0]);
        }

        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Example usage
    const char* hash = "d41d8cd98f00b204e9800998ecf8427e";
    executeCommand(hash, "/bin/echo");
    return 0;
}
```

**Notes:**

1. The Java method uses `MessageDigest` to compute the MD5 hash and handles exceptions gracefully.
2. The C function uses fork to create a child process for command execution and manages inter-process communication via pipes.
3. Error handling is implemented in both parts to ensure robustness.
4. Integration between Java and C can be achieved using JNI or similar methods, which are not detailed here due to complexity beyond the scope of this example.
5. The code should be further extended with timeout management, enhanced logging, and possibly integration tools for a fully operational system.']

