            if (is_RNTI_unique(list, rnti)) {
                NFAPI_CRC_INDICATION_PDU_T pdu = {
                    .RX_UE_INFORMATION_TAG = rand(),
                    .RNTI = rnti,
                    .CRC_INDICATION_REL8_TAG = { .CRCFLAG = rand() % 2 }
                };

                if (validate_CRCFLAG(&pdu)) {
                    insert_into_list(list, pdu);
                    inserted = true;
                }
            }

            pthread_mutex_unlock(&list->lock);

            // Simulating network delay
            usleep(100000); // Sleep for 100ms
        }

        if (!inserted) {
            fprintf(stderr, "Failed to insert unique RNTI after %d attempts\n", MAX_RETRIES);
        }
    }
}

void free_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    struct Node* current = list->head;
    while (current != NULL) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->node_count = 0;
    list->used_memory = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL));

    LinkedList* list = create_linked_list();
    if (!list) return EXIT_FAILURE;

    manage_linked_list(list, 100); // Manage 100 elements

    free_linked_list(list);

    return EXIT_SUCCESS;
}
