    if (list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_pdu->rxUeInfo = rxUeInfo;
    new_pdu->RNTI = rnti;
    new_pdu->crcTag.CRCFLAG = rand() % 2; // Random CRC flag
