    new_pdu->prev = list->tail;

    if (list->tail) {
        list->tail->next = new_pdu;
    } else {
        list->head = new_pdu;
    }

    list->tail = new_pdu;
    ++list->count;
    log_operation("Added PDU");

    pthread_mutex_unlock(&list->lock);
