    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        if (current->RNTI == rnti) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }

            if (current->next) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }

            free(current);
            --list->count;
            log_operation("Removed PDU");
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void clear_crc_list(CRC_List* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    log_operation("Cleared List");
    pthread_mutex_unlock(&list->lock);
}

void free_crc_list(CRC_List* list) {
