#define MAX_INT 2147483647

typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int *int_array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} IntegerStreamProcessor;

void initialize_processor(IntegerStreamProcessor *processor) {
    processor->capacity = 10; // Initial capacity
    processor->count = 0;
    processor->int_array = malloc(processor->capacity * sizeof(int));
    if (!processor->int_array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&processor->lock, NULL);
}

void free_processor(IntegerStreamProcessor *processor) {
    free(processor->int_array);
    pthread_mutex_destroy(&processor->lock);
}

int is_valid_integer(const char *data, size_t length) {
    if (length == 0) return 0;
    int sign = 1;
    if (*data == '-') {
        sign = -1;
        data++;
    }
    int value = 0;
    while (*data) {
        if (*data < '0' || *data > '9') return 0;
        int digit = *data - '0';
        if (value > (MAX_INT - digit) / 10) return 0; // Overflow check
        value = value * 10 + digit;
        data++;
    }
    return sign == 1 ? value <= MAX_INT : -value >= INT_MIN;
}

void process_packet(IntegerStreamProcessor *processor, const char *data, size_t length) {
    pthread_mutex_lock(&processor->lock);

    // Assuming data is null-terminated or has a defined end
    int number = atoi(data);
    if (is_valid_integer(data, length)) {
        if (processor->count >= processor->capacity) {
            processor->capacity *= 2;
            processor->int_array = realloc(processor->int_array, processor->capacity * sizeof(int));
            if (!processor->int_array) {
                perror("Failed to reallocate memory");
                pthread_mutex_unlock(&processor->lock);
                exit(EXIT_FAILURE);
            }
        }
        processor->int_array[processor->count++] = number;
    }

    pthread_mutex_unlock(&processor->lock);
}

void print_largest_integer(IntegerStreamProcessor *processor) {
    pthread_mutex_lock(&processor->lock);

    if (processor->count == 0) {
        printf("No valid integers received.\n");
    } else {
        int largest = processor->int_array[0];
        for (size_t i = 1; i < processor->count; ++i) {
            if (processor->int_array[i] > largest) {
                largest = processor->int_array[i];
            }
        }
        printf("Largest integer: %d\n", largest);
    }

    pthread_mutex_unlock(&processor->lock);
}

void populate_crc_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        pdu_list[i].rx_ue_information_tag = rand() % 65536;
        pdu_list[i].rnti = rand() % 65536;
        pdu_list[i].crc_indication_rel8_tag = rand() & 1; // Random CRCFLAG (0 or 1)
    }
}

// Example usage
int main() {
    IntegerStreamProcessor processor;
    initialize_processor(&processor);

    // Simulate receiving packets
    process_packet(&processor, "123", 3);
    process_packet(&processor, "-456", 4);
    process_packet(&processor, "7890", 4);
    process_packet(&processor, "invalid", 7); // Malformed packet

    print_largest_integer(&processor);

    size_t n = 5;
    NFAPI_CRC_INDICATION_PDU_T pdu_list[n];
    populate_crc_pdu_list(pdu_list, n);

    for (size_t i = 0; i < n; ++i) {
        printf("PDU[%zu]: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               i,
               pdu_list[i].rx_ue_information_tag,
               pdu_list[i].rnti,
               pdu_list[i].crc_indication_rel8_tag);
    }

    free_processor(&processor);
    return 0;
}
