```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for SessionData
typedef struct UserPlaneFifo {
    // Add necessary fields and methods for packet buffers
} UserPlaneFifo;

typedef struct ControlPlaneFifo {
    // Add necessary fields and methods for control plane messages
} ControlPlaneFifo;

typedef struct SessionData {
    int SessionID;
    UserPlaneFifo userPlaneFifo;
    ControlPlaneFifo controlPlaneFifo;
    struct SessionData* next;
} SessionData;

// Define the head of the linked list and a mutex for thread safety
static SessionData* sessionListHead = NULL;
static pthread_mutex_t sessionMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new SessionData node
SessionData* createSession(int sessionId) {
    SessionData* newSession = (SessionData*)malloc(sizeof(SessionData));
    if (!newSession) return NULL; // Handle memory allocation failure

    newSession->SessionID = sessionId;
    // Initialize UserPlaneFifo and ControlPlaneFifo as needed
    newSession->next = NULL;

    return newSession;
}

// Function to add a session to the linked list
void addSession(int sessionId) {
    pthread_mutex_lock(&sessionMutex);

    SessionData* newSession = createSession(sessionId);
    if (!newSession) {
        fprintf(stderr, "Failed to allocate memory for session %d\n", sessionId);
        pthread_mutex_unlock(&sessionMutex);
        return;
    }

    // Insert at the beginning of the list
    newSession->next = sessionListHead;
    sessionListHead = newSession;

    pthread_mutex_unlock(&sessionMutex);
}

// Function to remove a session from the linked list by SessionID
void removeSession(int sessionId) {
    pthread_mutex_lock(&sessionMutex);

    SessionData *current = sessionListHead, *prev = NULL;
    while (current != NULL && current->SessionID != sessionId) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Session not found
        pthread_mutex_unlock(&sessionMutex);
        return;
    }

    // Remove the session from the list
    if (prev == NULL) {
        sessionListHead = current->next; // Removing head
    } else {
        prev->next = current->next;
    }

    free(current); // Free the memory

    pthread_mutex_unlock(&sessionMutex);
}

// Function to clean up all sessions
void cleanupSessions() {
    pthread_mutex_lock(&sessionMutex);

    SessionData* current = sessionListHead;
    while (current != NULL) {
        SessionData* temp = current;
        current = current->next;

        // Clean up resources for UserPlaneFifo and ControlPlaneFifo as needed

        free(temp);
    }

    sessionListHead = NULL; // Reset the list head
    pthread_mutex_unlock(&sessionMutex);
}

// Example usage
int main() {
    addSession(1);
    addSession(2);

    removeSession(1);

    cleanupSessions();

    return 0;
}
```

### Key Points:
- **Thread Safety**: The linked list operations are protected by a mutex to ensure thread safety.
- **Dynamic Memory Management**: Each `SessionData` is dynamically allocated and deallocated.
- **Resource Cleanup**: A cleanup function is provided to release all resources when sessions are no longer needed.
- **Scalability**: New sessions can be added efficiently, maintaining performance as the list grows.']

