    Fifo UserPlaneFifo;
    Fifo ControlPlaneFifo;
    time_t last_active;
    struct SessionData* next;
} SessionData;

typedef struct {
    SessionData* head;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    time_t session_timeout;
} SessionManager;

void log_event(const char *event) {
    printf("%s\n", event);
}

SessionManager* initialize_manager(size_t max_buffer_size, time_t timeout) {
    SessionManager* manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);

    manager->head = NULL;
    manager->count = 0;
    manager->session_timeout = timeout;

    return manager;
}

void cleanup_fifo(Fifo* fifo) {
    if (fifo) {
        pthread_mutex_lock(&fifo->lock);
        free(fifo->buffers);
        pthread_mutex_unlock(&fifo->lock);
        pthread_mutex_destroy(&fifo->lock);
    }
}

Fifo initialize_fifo(size_t max_size) {
    Fifo fifo;
    fifo.buffers = malloc(sizeof(PacketBuffer) * max_size);
    if (!fifo.buffers) exit(EXIT_FAILURE);

    fifo.max_size = max_size;
    fifo.current_size = 0;

    pthread_mutex_init(&fifo.lock, NULL);
    return fifo;
}

void cleanup_session(SessionData* session) {
    if (session) {
        cleanup_fifo(&session->UserPlaneFifo);
        cleanup_fifo(&session->ControlPlaneFifo);
        free(session);
    }
}

SessionData* create_session(int session_id, SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_SESSIONS) {
        log_event("Max sessions reached. Cannot create new session.");
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    SessionData* session = malloc(sizeof(SessionData));
    if (!session) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    session->SessionID = session_id;
    session->UserPlaneFifo = initialize_fifo(1024); // Example size
    session->ControlPlaneFifo = initialize_fifo(512); // Example size
    session->last_active = time(NULL);

    session->next = manager->head;
    manager->head = session;
    manager->count++;

    log_event("Session created.");

    pthread_mutex_unlock(&manager->lock);
    return session;
}

void terminate_session(int session_id, SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    SessionData *current = manager->head, *prev = NULL;
    while (current) {
        if (current->SessionID == session_id) {
            if (prev) prev->next = current->next;
            else manager->head = current->next;

            cleanup_session(current);
            manager->count--;
            log_event("Session terminated.");
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void monitor_sessions(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    size_t active_sessions = manager->count;
    double avg_user_buffer_usage = 0.0, avg_control_buffer_usage = 0.0;

    SessionData* current = manager->head;
    while (current) {
        avg_user_buffer_usage += ((double)current->UserPlaneFifo.current_size / 
                                  current->UserPlaneFifo.max_size);
        avg_control_buffer_usage += ((double)current->ControlPlaneFifo.current_size / 
                                     current->ControlPlaneFifo.max_size);
        current = current->next;
    }

    if (active_sessions > 0) {
        avg_user_buffer_usage /= active_sessions;
        avg_control_buffer_usage /= active_sessions;
    }

    printf("Active Sessions: %zu\n", active_sessions);
    printf("Average User Buffer Usage: %.2f%%\n", avg_user_buffer_usage * 100);
    printf("Average Control Buffer Usage: %.2f%%\n", avg_control_buffer_usage * 100);

    pthread_mutex_unlock(&manager->lock);
}

void* session_timeout_checker(void* arg) {
    SessionManager* manager = (SessionManager*)arg;
    while (1) {
        sleep(5); // Check every 5 seconds

        time_t now = time(NULL);
        pthread_mutex_lock(&manager->lock);

        SessionData *current = manager->head, *prev = NULL;
        while (current) {
            if ((now - current->last_active) > manager->session_timeout) {
                log_event("Session timed out.");
                if (prev) prev->next = current->next;
                else manager->head = current->next;

                cleanup_session(current);
                manager->count--;
            }
            prev = current;
            current = current->next;
        }

        pthread_mutex_unlock(&manager->lock);
    }
    return NULL;
}

void start_manager(SessionManager* manager) {
    pthread_t timeout_thread;
    pthread_create(&timeout_thread, NULL, session_timeout_checker, manager);
    pthread_detach(timeout_thread);
}
```

