    pthread_mutex_init(&fifo->lock, NULL);
    fifo->size = initial_size;
}

void initialize_control_plane_fifos(ControlPlaneFifo *fifo, int initial_size) {
    fifo->messages = (ControlPlaneMessage *)malloc(initial_size * sizeof(ControlPlaneMessage));
    pthread_mutex_init(&fifo->lock, NULL);
    fifo->size = initial_size;
}

// Function to add a new session
