    if (!new_node) {
        perror("Failed to allocate memory for new session");
        return;
    }

    new_node->SessionID = session_id;
    initialize_fifo(&new_node->up_fifo, 10); // Initial buffer size
    initialize_control_plane_fifos(&new_node->cp_fifo, 5); // Initial message queue size

    pthread_mutex_lock(&list_lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_lock);
}

// Function to free all sessions and resources
void free_sessions() {
    SessionData *current = head;

    while (current != NULL) {
        SessionData *temp = current;
        current = current->next;

        // Free FIFOs
        free(temp->up_fifo.buffer);
        pthread_mutex_destroy(&temp->up_fifo.lock);

        free(temp->cp_fifo.messages);
        pthread_mutex_destroy(&temp->cp_fifo.lock);

        free(temp);
    }

    head = NULL;
}

// Function to initialize and populate the session list
void initialize_and_populate_session_list(int num_sessions) {
