#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(unsigned int crcflag, unsigned long rx_tag, unsigned long rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->crc_tag.CRCFLAG = crcflag;
    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    return pdu;
}

void add_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        free(pdu);
        return;
    }
    new_node->data = *pdu;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_element(LinkedList* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void remove_element(LinkedList* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                list->head = current->next;

            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_list(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void log_creation(NFAPI_CRC_INDICATION_PDU_T* pdu, const char* level) {
    printf("[%s] Created PDU: RXUE=%lu, RNTI=%lu, CRCFLAG=%u\n", level, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->crc_tag.CRCFLAG);
}

void serialize_list(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);
    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_element(list, create_pdu(pdu.crc_tag.CRCFLAG, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI));
    }
    fclose(file);
}

void test_create_and_add() {
    LinkedList* list = create_list();
    if (!list) return;

    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(rand() % 2, rand(), rand());
        add_element(list, pdu);
        log_creation(pdu, "INFO");
    }

    iterate_list(list, [](NFAPI_CRC_INDICATION_PDU_T* pdu) {
        printf("Iterating: RXUE=%lu, RNTI=%lu, CRCFLAG=%u\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->crc_tag.CRCFLAG);
    });

    remove_element(list, 12345); // Example RNTI to remove
    free_list(list);
}

int main() {
    test_create_and_add();
    return 0;
}
