#include <netdb.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>

#define MAX_ATTEMPTS 5
#define TIMEOUT_SECONDS 10
#define TOTAL_EXECUTION_TIME 30
#define HOSTNAME_BUFFER_SIZE 256

enum LogLevel {
    LOG_LEVEL_NONE,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_DEBUG
};

void log_message(enum LogLevel level, const char *message) {
    if (level == LOG_LEVEL_ERROR || (level == LOG_LEVEL_DEBUG && current_log_level >= LOG_LEVEL_DEBUG)) {
        printf("%s\n", message);
    }
}

int resolve_dns(const char *hostname, u_char **ip_address, enum LogLevel log_level) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int attempt, attempts = 0;
    struct addrinfo hints, *res, *p;
    u_char *address_buffer = NULL;
    size_t address_length = 0;
    time_t start_time, current_time;

    if (hostname == NULL || strlen(hostname) >= HOSTNAME_BUFFER_SIZE) {
        log_message(LOG_LEVEL_ERROR, "Invalid hostname.");
        return -1;
    }

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Support both IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    start_time = time(NULL);

    while (attempts < MAX_ATTEMPTS) {
        current_time = time(NULL);
        if (difftime(current_time, start_time) > TOTAL_EXECUTION_TIME) {
            log_message(LOG_LEVEL_ERROR, "Exceeded total execution time.");
            free(address_buffer);
            return -1;
        }

        int ret = getaddrinfo(hostname, NULL, &hints, &res);
        if (ret == 0) {
            for (p = res; p != NULL; p = p->ai_next) {
                char ipstr[INET6_ADDRSTRLEN];
                void *addr;

                if (p->ai_family == AF_INET) { // IPv4
                    struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                    addr = &(ipv4->sin_addr);
                } else { // IPv6
                    struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                    addr = &(ipv6->sin6_addr);
                }

                inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));

                size_t needed_length = strlen(ipstr) + 1; // Include null terminator
                if (address_length < needed_length) {
                    u_char *new_buffer = realloc(address_buffer, needed_length);
                    if (!new_buffer) {
                        free(address_buffer);
                        freeaddrinfo(res);
                        log_message(LOG_LEVEL_ERROR, "Memory allocation failed.");
                        return -1;
                    }
                    address_buffer = new_buffer;
                    address_length = needed_length;
                }

                strncpy((char *)address_buffer, ipstr, needed_length);
                freeaddrinfo(res);
                *ip_address = address_buffer;
                return 0; // Success
            }
        } else {
            log_message(LOG_LEVEL_DEBUG, "getaddrinfo failed.");
            sleep(TIMEOUT_SECONDS); // Wait before retrying
        }

        attempts++;
    }

    if (address_buffer) {
        free(address_buffer);
    }
    log_message(LOG_LEVEL_ERROR, "Failed to resolve DNS after multiple attempts.");
    return -1; // Failure
}

// Usage example
/*
