void calculate_average_time_difference(const long *timestamps, size_t count) {
    if (count < 2) return;

    long total_diff = 0;
    for (size_t i = 1; i < count; ++i) {
        total_diff += timestamps[i] - timestamps[i - 1];
    }

    double average_diff = (double)total_diff / (count - 1);
    printf("Average time difference: %.2f\n", average_diff);
}

void process_timestamps() {
    long *timestamps = (long *)malloc(MAX_TIMESTAMPS * sizeof(long));
    if (!timestamps) {
