    }

    size_t count = 0;
    while (scanf("%ld", &timestamps[count]) == 1 && count < MAX_TIMESTAMPS) {
        ++count;

        // Buffer management strategy: process in chunks
        if (count >= BUFFER_SIZE) {
            calculate_average_time_difference(timestamps, count);
