typedef enum {
    TYPE_A,
    TYPE_B,
    // Add other frame types as needed
} FrameType;

typedef struct {
    time_t Timestamp;
    FrameType FrameType;
    size_t PacketSize;
    int ErrorIndicator;  // 0 for no error, 1 for error
} FrameMetadata;

#define MAX_FRAMES 1000000

void logError(size_t index) {
    static FILE *logFile = NULL;
    if (!logFile) {
        logFile = fopen("errors.log", "a");
        if (logFile == NULL) {
            perror("Failed to open error log file");
            exit(EXIT_FAILURE);
        }
    }
    fprintf(logFile, "Error at frame index %zu\n", index);
    fflush(logFile);  // Ensure each log entry is written immediately
}

void initializeFrames(FrameMetadata *frames, size_t count) {
    if (frames == NULL || count > MAX_FRAMES) return;

    srand((unsigned int)time(NULL));  // Seed once at the start

    for (size_t i = 0; i < count; ++i) {
        frames[i].Timestamp = time(NULL);  // Initialize timestamp to current time
        frames[i].FrameType = (rand() % 2 == 0) ? TYPE_A : TYPE_B;  // Randomly assign frame type

        // Assign a random packet size, for example between 64 and 1500 bytes
        frames[i].PacketSize = rand() % (1501 - 64) + 64;

        double errorProbability = log(frames[i].PacketSize) / log(2.0);  // Logarithmic scale

        if (frames[i].FrameType == TYPE_B) {
            errorProbability *= 2;  // Increase probability for Type B frames
        }

        int randomValue = rand() % 100;
        frames[i].ErrorIndicator = (randomValue < errorProbability * 10) ? 1 : 0;

        if (frames[i].ErrorIndicator) {
            logError(i);  // Log errors for debugging purposes
        }
    }
}
