// Error logging function
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Function to generate a pseudo-random boolean based on seed
bool random_crcflag(unsigned int *seed) {
    const unsigned int a = 1103515245;
    const unsigned int c = 12345;
    *seed = (*seed * a + c) & 0x7fffffff;
    return (*seed % 2) == 0;
}

// Function to serialize the list of structures to a file
void serialize_to_file(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t count, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&count, sizeof(size_t), 1, file);
        fwrite(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
        fclose(file);
    } else {
        log_error("Failed to open file for serialization.");
    }
}

// Main function
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pdu_list(size_t N, unsigned int seed, const char* filename) {
    if (N > MAX_M) {
        log_error("Requested number of structures exceeds maximum limit");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t allocated_size = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;

    while (allocated_size < N) {
        NFAPI_CRC_INDICATION_PDU_T* temp_pdu_list = realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (allocated_size + 1));

        if (!temp_pdu_list) {
            log_error("Memory allocation failed. Retrying...");
            free(pdu_list);
            sleep(1); // Retry after a delay
            continue;
        }

        pdu_list = temp_pdu_list;
        allocated_size++;

