        pdu->CRCFLAG = random_crcflag(&seed);
        pdu->timestamp = time(NULL);

        pthread_mutex_unlock(&mutex);
    }

    serialize_to_file(pdu_list, allocated_size, filename);

    return pdu_list;
}

// Function to free the dynamically allocated list
void free_nfa_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    if (pdu_list) {
        free(pdu_list);
    }
}
