        (*frameArray)[i].FrameType = rand() % 3;
        (*frameArray)[i].PacketSize = rand() % 1024 + 1;

        // Determine ErrorIndicator based on size and type
        int errorProbability = ((*frameArray)[i].PacketSize / 256) * (rand() % 5);
        if ((*frameArray)[i].FrameType == TYPE_B) {
            errorProbability += 3;
        } else if ((*frameArray)[i].FrameType == TYPE_C) {
            errorProbability += 5;
        }
        (*frameArray)[i].ErrorIndicator = (rand() % 100 < errorProbability);

    }

    // Allocate memory for graph vertices and check for allocation failure
    *graph = (Vertex*)malloc(numVertices * sizeof(Vertex));
    if (*graph == NULL) {
        fprintf(stderr, "Memory allocation failed for graph.\n");
        free(*frameArray);
        exit(EXIT_FAILURE);
    }

    // Initialize adjacency list representation of the graph
    for (int i = 0; i < numVertices; ++i) {
        (*graph)[i].vertexType = rand() % 3;
        (*graph)[i].capacity = rand() % 100 + 1;
        (*graph)[i].loadFactor = (double)(rand() % 100) / 10.0;
        (*graph)[i].edges = NULL;

        // Randomly connect vertices with edges
        int numEdges = rand() % 5; // Each vertex can have up to 4 edges
        for (int j = 0; j < numEdges; ++j) {
            Edge* newEdge = (Edge*)malloc(sizeof(Edge));
            if (newEdge == NULL) {
                fprintf(stderr, "Memory allocation failed for edge.\n");
                // Free previously allocated edges before exit
                while ((*graph)[i].edges != NULL) {
                    Edge* temp = (*graph)[i].edges;
                    (*graph)[i].edges = (*graph)[i].edges->next;
                    free(temp);
                }
                free(*frameArray);
                for (int k = 0; k < i; ++k) {
                    while ((*graph)[k].edges != NULL) {
                        Edge* temp = (*graph)[k].edges;
                        (*graph)[k].edges = (*graph)[k].edges->next;
                        free(temp);
                    }
                }
                free(*graph);
                exit(EXIT_FAILURE);
            }

            newEdge->targetVertex = rand() % numVertices;
            while (newEdge->targetVertex == i) { // Avoid self-loop
                newEdge->targetVertex = rand() % numVertices;
            }
            newEdge->Weight = (double)(rand() % 1000) / 10.0;
            newEdge->Bandwidth = rand() % 100 + 1;
            newEdge->next = (*graph)[i].edges;
            (*graph)[i].edges = newEdge;
        }
    }

    // Connect vertices into a linked list for easier management
    Vertex* current = *graph;
    for (int i = 1; i < numVertices; ++i) {
        current->next = &(*graph)[i];
        current = current->next;
    }
    current->next = NULL; // End of the graph list
}
