#define MAX_DATASETS 100000

typedef struct {
    int SampleCount;
    double DataMean;
    double DataVariance;
    int OutlierIndicator; // 0 for no outlier, 1 for outlier
} DataSet;

void populateDataSets(DataSet dataSets[], int count, double varianceSensitivity, double outlierThreshold) {
    if (count > MAX_DATASETS || count <= 0) {
        fprintf(stderr, "Invalid number of datasets\n");
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < count; ++i) {
        dataSets[i].SampleCount = rand() % 1001 + 50; // SampleCount between 50 and 1050
        dataSets[i].DataMean = ((double)rand() / RAND_MAX) * 200.0 - 100.0; // DataMean between -100 and 100
        double variance = (double)rand() / RAND_MAX * 10.0 + 1.0; // DataVariance between 1 and 11
        dataSets[i].DataVariance = variance;

        // Calculate outlier probability based on SampleCount and DataVariance
        double outlierProbability = 1 - exp(-varianceSensitivity * variance);
        if (dataSets[i].SampleCount > outlierThreshold) {
            outlierProbability *= 2; // Increase likelihood for higher SampleCounts
        }

        // Randomly assign OutlierIndicator based on calculated probability
        dataSets[i].OutlierIndicator = ((double)rand() / RAND_MAX < outlierProbability) ? 1 : 0;

        // Log the decision for debugging purposes (consider using a more sophisticated logging mechanism)
        if (dataSets[i].OutlierIndicator == 1) {
            printf("DataSet %d: SampleCount=%d, DataMean=%.2f, DataVariance=%.2f - OUTLIER DETECTED\n",
                   i, dataSets[i].SampleCount, dataSets[i].DataMean, dataSets[i].DataVariance);
        }
    }
}

// Documentation:
// To configure the outlier detection algorithm:
// - `varianceSensitivity`: Adjusts how sensitive the function is to DataVariance when calculating outlier probability.
//   Higher values increase sensitivity. Default: 0.1
// - `outlierThreshold`: A threshold for SampleCount above which the likelihood of an outlier increases.
//   Default: 500

int main() {
    DataSet dataSets[MAX_DATASETS];
    double varianceSensitivity = 0.1; // Adjust this parameter to configure sensitivity
    double outlierThreshold = 500.0;  // Adjust this threshold for increased outlier probability

    populateDataSets(dataSets, MAX_DATASETS, varianceSensitivity, outlierThreshold);

    return 0;
}
