#define BUFFER_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    time_t Timestamp;
    char FrameType[10];
    size_t PacketSize;
    int ErrorIndicator;
} FrameMetadata;

typedef struct GraphVertex {
    int VertexType;
    int Capacity;
    float LoadFactor;
    struct GraphEdge* edges;
    int edge_count;
} GraphVertex;

typedef struct GraphEdge {
    int Weight;
    int Bandwidth;
    struct GraphVertex* vertex;
} GraphEdge;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void handle_incoming_data(int sockfd) {
    uint8_t buffer[BUFFER_SIZE];
    size_t valid_count = 0;
    int* integers = NULL;

    while (1) {
        ssize_t bytes_received = recv(sockfd, buffer, BUFFER_SIZE, 0);
        if (bytes_received <= 0) {
            break; // End of stream or error
        }

        for (ssize_t i = 0; i < bytes_received;) {
            if (i + sizeof(int) > bytes_received) {
                fprintf(stderr, "Malformed packet\n");
                break;
            }

            int value;
            memcpy(&value, &buffer[i], sizeof(int));
            pthread_mutex_lock(&mutex);
            integers = realloc(integers, (valid_count + 1) * sizeof(int));
            if (!integers) {
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }
            integers[valid_count++] = value;
            pthread_mutex_unlock(&mutex);

            i += sizeof(int);
        }
    }

    pthread_mutex_lock(&mutex);
    int max_value = (valid_count > 0) ? integers[0] : INT_MIN;
    for (size_t i = 1; i < valid_count; ++i) {
        if (integers[i] > max_value) {
            max_value = integers[i];
        }
    }

    printf("Largest integer: %d\n", max_value);
    free(integers);
    pthread_mutex_unlock(&mutex);
}

void generateDataAndGraph(size_t frame_count, size_t vertex_count) {
    FrameMetadata* frames = malloc(frame_count * sizeof(FrameMetadata));
    if (!frames) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    GraphVertex* graph_vertices = malloc(vertex_count * sizeof(GraphVertex));
    if (!graph_vertices) {
        free(frames);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < frame_count; ++i) {
        frames[i].Timestamp = time(NULL);
        snprintf(frames[i].FrameType, sizeof(frames[i].FrameType), "TYPE%d", rand() % 3);
        frames[i].PacketSize = rand() % 1500;

        float error_probability = (float)frames[i].PacketSize / 1000.0;
        if ((rand() / (RAND_MAX + 1.0)) < error_probability) {
            frames[i].ErrorIndicator = 1;
        } else {
            frames[i].ErrorIndicator = 0;
        }
    }

    for (size_t i = 0; i < vertex_count; ++i) {
        graph_vertices[i].VertexType = rand() % 5;
        graph_vertices[i].Capacity = rand() % 100 + 1;
        graph_vertices[i].LoadFactor = ((float)rand() / RAND_MAX);
        graph_vertices[i].edges = NULL;
        graph_vertices[i].edge_count = 0;

        size_t edge_count = rand() % 10 + 1; // Random number of edges
        graph_vertices[i].edges = malloc(edge_count * sizeof(GraphEdge));
        if (!graph_vertices[i].edges) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < edge_count; ++j) {
            GraphVertex* target_vertex = &graph_vertices[rand() % vertex_count];
            graph_vertices[i].edges[j].Weight = rand() % 100;
            graph_vertices[i].edges[j].Bandwidth = rand() % 100 + 1;
            graph_vertices[i].edges[j].vertex = target_vertex;
        }
        graph_vertices[i].edge_count = edge_count;
    }

    // Free allocated resources
    for (size_t i = 0; i < vertex_count; ++i) {
        free(graph_vertices[i].edges);
    }
    free(frames);
    free(graph_vertices);
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        return EXIT_FAILURE;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(8080);

    // Assuming server IP is set here
    inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr);

    if (connect(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, (void*)handle_incoming_data, (void*)(intptr_t)sockfd);

    generateDataAndGraph(1000, 50);

    close(sockfd);
    pthread_join(thread_id, NULL);
    return EXIT_SUCCESS;
}
