#define MAX_EVENTS 10000000

typedef struct {
    uint16_t RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t CRCFLAG;
    // Other fields...
} NFAPI_CRC_INDICATION_REL8_TAG;

