    uint32_t seq_num;
    time_t timestamp;
    RX_UE_INFORMATION_TAG rx_ue_info;
    // Other fields...
} NFAPI_RX_PDU_T;

typedef struct {
    NFAPI_RX_PDU_T pdus[MAX_EVENTS];
    size_t count;
    uint32_t last_seq_num;
    clock_t prev_timestamp;
} BufferManager;

BufferManager buffer_manager = { .count = 0, .last_seq_num = 0, .prev_timestamp = 0 };

bool is_duplicate_rnti(uint16_t rnti) {
    for (size_t i = 0; i < buffer_manager.count; ++i) {
        if (buffer_manager.pdus[i].rx_ue_info.RNTI == rnti) {
            return true;
        }
    }
    return false;
}

void process_crc_indication(NFAPI_CRC_INDICATION_REL8_TAG *crc_tag) {
    crc_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
}

void handle_event(time_t current_timestamp, RX_UE_INFORMATION_TAG *rx_info) {
    if (is_duplicate_rnti(rx_info->RNTI)) {
        fprintf(stderr, "Duplicate RNTI detected: %u\n", rx_info->RNTI);
        return;
    }

    if (buffer_manager.count >= MAX_EVENTS) {
        fprintf(stderr, "Buffer overflow!\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_RX_PDU_T *pdu = &buffer_manager.pdus[buffer_manager.count];
    pdu->seq_num = ++buffer_manager.last_seq_num;
    pdu->timestamp = current_timestamp;
    memcpy(&pdu->rx_ue_info, rx_info, sizeof(RX_UE_INFORMATION_TAG));

    buffer_manager.prev_timestamp = current_timestamp;

    // Calculate time difference
    if (buffer_manager.prev_timestamp != 0) {
        double diff = difftime(current_timestamp, buffer_manager.prev_timestamp);
        printf("Average Time Difference: %.2f seconds\n", diff / buffer_manager.count);
    }

    ++buffer_manager.count;
}

int main() {
    srand(time(NULL));

    // Simulate incoming events
    while (true) {
        time_t current_time = time(NULL);

        RX_UE_INFORMATION_TAG rx_info = { .RNTI = rand() % 65535 };
        handle_event(current_time, &rx_info);
    }

    return 0;
}
