    // RF frame header structure definition
} RF_FRAME_HEADER;

typedef struct {
    // RF frame payload structure definition, possibly using external libraries for encoding/decoding
} RF_FRAME_PAYLOAD;

typedef struct {
    RF_FRAME_HEADER header;
    RF_FRAME_PAYLOAD payload;
    time_t timestamp;  // For data synchronization
    // Additional fields can be added here in the future
} LTE_PHY_RX_BUFFER_T;

// Global variables for buffer management
#define MAX_BUFFER_SIZE 1000

LTE_PHY_RX_BUFFER_T* buffer = NULL;
size_t current_size = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER; // For thread safety

void initialize_buffer() {
    buffer = (LTE_PHY_RX_BUFFER_T*)malloc(MAX_BUFFER_SIZE * sizeof(LTE_PHY_RX_BUFFER_T));
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed for LTE_PHY_RX_BUFFER_T array.\n");
        exit(EXIT_FAILURE);
    }
}

void purge_old_entries() {
    time_t now = time(NULL);

    pthread_mutex_lock(&buffer_mutex);
    size_t new_size = 0;
    for (size_t i = 0; i < current_size; ++i) {
        if (now - buffer[i].timestamp < 60) { // Keep entries younger than 60 seconds
            buffer[new_size++] = buffer[i];
        }
    }
    current_size = new_size;

    pthread_mutex_unlock(&buffer_mutex);
}

int insert_entry(const RF_FRAME_HEADER* header, const RF_FRAME_PAYLOAD* payload) {
    if (!header || !payload) return -1; // Error handling for null pointers

    pthread_mutex_lock(&buffer_mutex);

    if (current_size >= MAX_BUFFER_SIZE) {
        purge_old_entries();
    }

    if (current_size < MAX_BUFFER_SIZE) {
        buffer[current_size].header = *header;
        buffer[current_size].payload = *payload;
        buffer[current_size].timestamp = time(NULL);
        current_size++;
    } else {
        fprintf(stderr, "Buffer is full and could not purge old entries.\n");
        pthread_mutex_unlock(&buffer_mutex);
        return -1; // Error handling for full buffer
    }

    pthread_mutex_unlock(&buffer_mutex);

    return 0;
}

LTE_PHY_RX_BUFFER_T* retrieve_entry(size_t index) {
    if (index >= current_size) return NULL;

    return &buffer[index];
}

void cleanup_buffer() {
    free(buffer);
    buffer = NULL;
    current_size = 0;
}
