    srand((unsigned int)time(NULL));

    // Allocate memory for offsets and keys
    long *offsets = (long*)safeMalloc(1000 * sizeof(long));  // Assuming a max of 1000 entries
    int *keys = (int*)safeMalloc(1000 * sizeof(int));

    // Allocate memory for records
    record *records = (record*)safeMalloc(1000 * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return 1; // Allocation failure
    }

    // Populate records with random integers within the range [rangeMin, rangeMax]
    for (size_t i = 0; i < 1000; ++i) {
        records[i].value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
    }

    // Convert JPEG to PDF using a placeholder third-party tool command
    char command[256];
    snprintf(command, sizeof(command), "jpeg2pdf %s %s", inputFilePath, outputFilePath);

    int conversionSuccess = system(command);

