int generate_unique_rnti_and_crcflag(uint16_t* rnti, uint8_t* crcflag, uint16_t* existing_rtis, size_t count) {
    while (1) {
        *rnti = rand() % 65536; // Random RNTI
        *crcflag = rand() % 2;   // Random CRCFLAG (0 or 1)

        int is_unique = 1;
        for (size_t i = 0; i < count; ++i) {
            if (existing_rtis[i] == *rnti) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique)
            return 0; // Success
    }
}

// Function to dynamically allocate and populate the array of structures
