#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SIZE 10000000
#define GROWTH_FACTOR 2

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    unsigned int RNTI;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t size;
} HashTable;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

HashTable* create_hash_table(size_t size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->table = (Node**)calloc(size, sizeof(Node*));
    return ht;
}

unsigned int hash_function(unsigned int RNTI, size_t size) {
    return RNTI % size;
}

int insert_hash_table(HashTable* ht, unsigned int RNTI) {
    pthread_mutex_lock(&lock);
    unsigned int index = hash_function(RNTI, ht->size);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&lock);
        return 0; // Memory allocation failed
    }
    new_node->RNTI = RNTI;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
    pthread_mutex_unlock(&lock);
    return 1;
}

int check_hash_table(HashTable* ht, unsigned int RNTI) {
    pthread_mutex_lock(&lock);
    unsigned int index = hash_function(RNTI, ht->size);
    Node* node = ht->table[index];
    while (node) {
        if (node->RNTI == RNTI) {
            pthread_mutex_unlock(&lock);
            return 1;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&lock);
    return 0;
}

void free_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node* node = ht->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(ht->table);
    free(ht);
}

void log_message(const char* message, int level) {
    // Placeholder for logging framework integration
    if (level >= 1) { // Assuming 1 is the verbosity level threshold
        printf("%s\n", message);
    }
}

NFAPI_CRC_INDICATION_PDU_T** allocate_pdu_array(size_t initial_size, size_t* current_size, int* error_code) {
    *error_code = 0;
    HashTable* ht = create_hash_table(initial_size);

    NFAPI_CRC_INDICATION_PDU_T** pdu_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * initial_size);
    if (!pdu_array) {
        *error_code = -1;
        free_hash_table(ht);
        return NULL;
    }

    srand(time(NULL));
    size_t count = 0;
    while (count < initial_size) {
        unsigned int rnti = rand() % MAX_SIZE;
        if (!check_hash_table(ht, rnti)) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu) {
                *error_code = -2; // Allocation failure
                break;
            }
            pdu->RX_UE_INFORMATION_TAG = count + 1;
            pdu->RNTI = rnti;
            pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

            if (insert_hash_table(ht, rnti)) {
                pdu_array[count++] = pdu;
                log_message("Allocated and populated PDU", 1);
            } else {
                free(pdu);
            }
        }

        if ((count + 1) * GROWTH_FACTOR >= MAX_SIZE && count < initial_size) {
            size_t new_size = count + 1;
            NFAPI_CRC_INDICATION_PDU_T** temp_array = (NFAPI_CRC_INDICATION_PDU_T**)realloc(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_size);
            if (!temp_array) {
                *error_code = -3; // Reallocation failure
                break;
            }
            pdu_array = temp_array;
        }
    }

    *current_size = count;
    free_hash_table(ht);

    return pdu_array;
}

void deallocate_pdu_array(NFAPI_CRC_INDICATION_PDU_T** pdu_array, size_t current_size) {
    for (size_t i = 0; i < current_size; ++i) {
        free(pdu_array[i]);
        log_message("Deallocated PDU", 1);
    }
    free(pdu_array);
}

int main() {
    size_t current_size;
    int error_code;

    NFAPI_CRC_INDICATION_PDU_T** pdu_array = allocate_pdu_array(1000, &current_size, &error_code);

    if (error_code != 0) {
        log_message("Error allocating PDU array", 1);
        return error_code;
    }

    // Use the pdu_array as needed...

    deallocate_pdu_array(pdu_array, current_size);

    return 0;
}
