#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#define MAX_RNTI 65535

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    bool logging_enabled;
    time_t last_log_time;
} LinkedList;

void log_action(const char* action, uint32_t index) {
    time_t now = time(NULL);
    if (difftime(now, last_log_time) >= 1.0) {
        printf("[%s] %s at index: %u\n", ctime(&now), action, index);
        last_log_time = now;
    }
}

int validate_rnti(uint16_t rnti) {
    return (rnti <= MAX_RNTI) ? 0 : -1;
}

int is_duplicate_tag(LinkedList* list, uint32_t tag) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    list->logging_enabled = true;
    time(&list->last_log_time);
    return list;
}

void free_node(Node* node) {
    free(node);
}

int insert_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (validate_rnti(element.RNTI) != 0 || is_duplicate_tag(list, element.RX_UE_INFORMATION_TAG)) {
        printf("Error: Invalid RNTI or Duplicate Tag\n");
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    log_action("Insertion", (uint32_t)(list->size - 1));

    return 0;
}

int delete_element(LinkedList* list, uint32_t index) {
    if (index >= list->size) {
        printf("Error: Index out of bounds\n");
        return -1;
    }

    Node *current = list->head, *previous = NULL;
    for (uint32_t i = 0; i < index && current != NULL; ++i) {
        previous = current;
        current = current->next;
    }

    if (!current) return -2;

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free_node(current);
    list->size--;

    log_action("Deletion", index);

    return 0;
}

void destroy_linked_list(LinkedList* list) {
    Node *current = list->head, *tmp;

    while (current != NULL) {
        tmp = current;
        current = current->next;
        free_node(tmp);
    }

    free(list);
}
```

This code uses a linked list for managing the dynamic array of structures. It includes logging functionality with frequency control to prevent excessive log entries and ensures data validation on `RNTI` and unique tags within elements. The functions handle memory allocation, insertion, deletion, and cleanup efficiently while maintaining robust error handling and reporting mechanisms.']

