} NFMMB_ENCAPSULATED_DATA_T;

typedef struct Node {
    NFMMB_ENCAPSULATED_DATA_T data;
    struct Node* next;
} Node;

typedef enum { LOG_TO_CONSOLE, LOG_TO_FILE } LogType;

LogType log_mode = LOG_TO_CONSOLE;
FILE *log_file = NULL;

void configure_logging(LogType mode, const char *file_path) {
    if (mode == LOG_TO_CONSOLE) {
        log_file = NULL;
    } else if (mode == LOG_TO_FILE && file_path != NULL) {
        log_file = fopen(file_path, "a");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }
}

void log_message(const char *message) {
    if (log_mode == LOG_TO_CONSOLE) {
        printf("%s\n", message);
    } else if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
    }
}

Node* create_node(NFMMB_ENCAPSULATED_DATA_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node *head) {
    Node *tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        if (tmp->data.ENCRYPTION_KEY) {
            free(tmp->data.ENCRYPTION_KEY);
        }
        free(tmp);
    }
}

Node* insert_node(Node *head, NFMMB_ENCAPSULATED_DATA_T data, unsigned int sequence_number) {
    Node **tracer = &head;
    while (*tracer && (*tracer)->data.SEQUENCE_NUMBER < sequence_number) {
        tracer = &(*tracer)->next;
    }

    Node *new_node = create_node(data);
    new_node->next = *tracer;
    *tracer = new_node;

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Inserted node: SEQUENCE_NUMBER=%u, MMB_DATA_TAG=%d",
             data.SEQUENCE_NUMBER, data.MMB_DATA_TAG);
    log_message(log_msg);

    return head;
}

bool validate_mmb_data_tag(NFMMB_ENCAPSULATED_DATA_T data) {
    // Assume a validation logic here
    return true; 
}

void traverse_and_validate(Node *head) {
    Node *current = head;
    while (current != NULL) {
        if (!validate_mmb_data_tag(current->data)) {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Invalid data tag: SEQUENCE_NUMBER=%u, MMB_DATA_TAG=%d",
                     current->data.SEQUENCE_NUMBER, current->data.MMB_DATA_TAG);
            log_message(log_msg);
        }
        current = current->next;
    }
}

Node* populate_list(unsigned int num_entries, float encryption_probability) {
    Node *head = NULL;
    srand(time(NULL));

    for (unsigned int i = 0; i < num_entries; ++i) {
        NFMMB_ENCAPSULATED_DATA_T data;
        data.MMB_DATA_TAG = rand() % 1000;
        data.SEQUENCE_NUMBER = i;

        if ((float)rand() / RAND_MAX < encryption_probability) {
            data.ENCRYPTION_KEY = strdup("SampleKey"); // Simulate retrieval
        } else {
            data.ENCRYPTION_KEY = NULL;
        }

        head = insert_node(head, data, i);
    }

    return head;
}

int main(int argc, char *argv[]) {
    configure_logging(LOG_TO_CONSOLE, NULL);

    unsigned int num_entries = 10;
    float encryption_probability = 0.3;

    Node* list_head = populate_list(num_entries, encryption_probability);
    traverse_and_validate(list_head);

    free_list(list_head);

    if (log_file) fclose(log_file);

    return 0;
}
