        free(*array);
        *array = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* initialize_crc_indication_array(size_t num_entries, double crc_probability) {
    if (!check_network_connectivity()) {
        log_message("Network connectivity issue detected.");
        return NULL;
    }

    if (num_entries <= 0 || num_entries > MAX_ENTRIES || crc_probability < 0.0 || crc_probability > 1.0) {
        log_message("Invalid input parameters for initializing CRC indication array.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_message("Memory allocation failed for CRC indication array.");
        return NULL;
    }

    bool rx_ue_tags[num_entries];
    memset(rx_ue_tags, false, num_entries);

    srand((unsigned int)time(NULL));  // Seed random number generator

    for (size_t i = 0; i < num_entries; ++i) {
        unsigned short rx_ue_tag = fetch_unique_rx_ue_tag();

        if (rx_ue_tag == DEFAULT_RX_UE_TAG || rx_ue_tags[rx_ue_tag]) {  // Fallback mechanism
            do {
                rx_ue_tag = rand() % MAX_ENTRIES;
            } while (rx_ue_tags[rx_ue_tag]);
        }

        array[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
        rx_ue_tags[rx_ue_tag] = true;

        unsigned short rnti = fetch_rnti_from_source();
        if (rnti == DEFAULT_RNTI) {
            rnti = rand() % MAX_ENTRIES;  // Fallback mechanism
        }

        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = (rand() / (double)RAND_MAX) < crc_probability;

        // Perform validation on RX_UE_INFORMATION_TAG, etc.
    }

    return array;
}

void process_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t count) {
    if (!array) {
        log_message("Null CRC indication array provided.");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        // Example operation: Validate RX_UE_INFORMATION_TAG
        if (array[i].RX_UE_INFORMATION_TAG == DEFAULT_RX_UE_TAG) {
            log_message("Validation failed for RX_UE_INFORMATION_TAG.");
        }
    }
}

int main() {
    size_t num_entries = 100;
    double crc_probability = 0.3;

    NFAPI_CRC_INDICATION_PDU_T* array = initialize_crc_indication_array(num_entries, crc_probability);
    if (array) {
        process_crc_indication_array(array, num_entries);
        free_crc_indication_array(&array, num_entries);
    }

    return 0;
}
