#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

typedef struct {
    unsigned char *data;
    size_t size;
    int success;
} CompressionResult;

CompressionResult compressFile(const char *filePath, int compressionLevel, size_t outputBufferSize) {
    FILE *file = fopen(filePath, "rb");
    if (!file) return (CompressionResult){NULL, 0, 0};

    // Determine file size
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char *inputBuffer = malloc(fileSize);
    if (!inputBuffer) {
        fclose(file);
        return (CompressionResult){NULL, 0, 0};
    }

    fread(inputBuffer, 1, fileSize, file);
    fclose(file);

    // Initialize zlib stream
    z_stream strm;
    memset(&strm, 0, sizeof(strm));
    int ret = deflateInit2(&strm, compressionLevel, Z_DEFLATED, MAX_WBITS + 16, 8, Z_DEFAULT_STRATEGY);
    if (ret != Z_OK) {
        free(inputBuffer);
        return (CompressionResult){NULL, 0, 0};
    }

    // Allocate output buffer
    unsigned char *outputBuffer = malloc(outputBufferSize);
    if (!outputBuffer) {
        deflateEnd(&strm);
        free(inputBuffer);
        return (CompressionResult){NULL, 0, 0};
    }

    strm.avail_in = fileSize;
    strm.next_in = inputBuffer;
    strm.avail_out = outputBufferSize;
    strm.next_out = outputBuffer;

    // Perform compression
    ret = deflate(&strm, Z_FINISH);
    if (ret != Z_STREAM_END) {
        free(inputBuffer);
        free(outputBuffer);
        deflateEnd(&strm);
        return (CompressionResult){NULL, 0, 0};
    }

    size_t compressedSize = outputBufferSize - strm.avail_out;
    unsigned char *compressedData = realloc(outputBuffer, compressedSize);

    if (!compressedData) {
        free(inputBuffer);
        free(outputBuffer);
        deflateEnd(&strm);
        return (CompressionResult){NULL, 0, 0};
    }

    deflateEnd(&strm);
    free(inputBuffer);

    // Return the result
    return (CompressionResult){compressedData, compressedSize, 1};
}
