    uint32_t RNTI;
    uint8_t CRCFLAG; // CRC_INDICATION_REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

// Mock logging framework
void log_memory_action(const char* action, size_t size) {
    printf("%s %zu bytes\n", action, size);
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int check_rnti_exists(NFAPI_CRC_INDICATION_PDU_T *array, uint32_t rnti, int count) {
    for (int i = 0; i < count; ++i) {
        if (array[i].RNTI == rnti) return 1;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* populate_array(int *count) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int capacity = 1000; // Initial allocation
    array = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        log_memory_action("Failed to allocate", capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        return NULL;
    }

    log_memory_action("Allocated", capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    uint16_t tag = 0;
    while (*count < MAX_ELEMENTS) {
        pthread_mutex_lock(&mutex);

        // Simulate external data source for RNTI and RX_UE_INFORMATION_TAG
        uint32_t rnti = rand() % (MAX_ELEMENTS / 2); // Mock RNTI generation
        if (!check_rnti_exists(array, rnti, *count)) {
            NFAPI_CRC_INDICATION_PDU_T element;
            element.RX_UE_INFORMATION_TAG = ++tag;
            element.RNTI = rnti;
            element.CRCFLAG = rand() % 2; // Random CRC flag

            if (*count >= capacity) {
                capacity *= 2;
                NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

                if (!new_array) {
                    log_memory_action("Failed to reallocate", capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                    free(array);
                    *count = 0;
                    pthread_mutex_unlock(&mutex);
                    return NULL;
                }

                array = new_array;
                log_memory_action("Reallocated", capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }

            array[*count] = element;
            (*count)++;
        }

        pthread_mutex_unlock(&mutex);

        // Simulate network latency and variability
        if (rand() % 1000 < 50) {
            usleep(1); // Sleep to simulate network conditions
        }
    }

    return array;
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T *array, int count) {
    if (array) {
        free(array);
        log_memory_action("Freed", count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

int main() {
    srand(time(NULL));

    int element_count = 0;
    NFAPI_CRC_INDICATION_PDU_T *data_array = populate_array(&element_count);

    if (data_array) {
        printf("Successfully populated %d elements.\n", element_count);
        // Perform operations with data_array...

        free_resources(data_array, element_count);
    } else {
        printf("Failed to allocate memory for the array.\n");
    }

    return 0;
}
```

### Key Considerations:
- **Thread Safety:** Uses a mutex (`pthread_mutex_t`) to ensure thread-safe access during population.
- **Memory Management:** Allocates an initial capacity and doubles as needed, checking for allocation failures.
- **Logging Framework:** Logs memory actions using a simple logging function.
- **Simulated External Data Source:** Randomly generates RNTI values.
- **Network Simulation:** Introduces artificial delays to simulate network variability.
- **Graceful Handling of Failures:** Checks and logs reallocation failures, freeing resources appropriately.']

