typedef struct LogEntry {
    char *data;
    struct LogEntry *next;
} LogEntry;

// Global variables for managing the list and threading
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
LogEntry *logHead = NULL;  // Head of linked list to store logs

void initializeNFAPI_CRC_INDICATION_PDU_Array(int num_elements, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (num_elements <= 0 || array == NULL) return;

    *array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    // Initialize and populate the NFAPI_CRC_INDICATION_PDU_T array
    for (int i = 0; i < num_elements; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand();  // Unique identifier for RX_UE_INFORMATION_TAG
        (*array)[i].RNTI = i + 1;                     // Assigning RNTI from 1 to num_elements
        (*array)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (i % 2) ? 0x01 : 0x00;  // Simple predefined algorithm
    }
}

// Function to compute MD5 hash of a log entry and return it as a hexadecimal string
void computeMD5Hash(const char *data, char *outputBuffer) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)data, strlen(data), (unsigned char*)&digest);

    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(outputBuffer + (i * 2), "%02x", (unsigned int)digest[i]);
}

// Thread-safe function to process log entries
void processLogEntry(const char *logData) {
    pthread_mutex_lock(&lock);

    // Create a new log entry node
    LogEntry *newEntry = malloc(sizeof(LogEntry));
    if (!newEntry) {
        fprintf(stderr, "Memory allocation failed for log entry.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    newEntry->data = strdup(logData);  // Copy the log data
    newEntry->next = NULL;

    // Append to the list
    if (logHead == NULL) {
        logHead = newEntry;
    } else {
        LogEntry *current = logHead;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntry;
    }

    // Compute unique identifier and MD5 hash
    char md5Hash[MD5_DIGEST_LENGTH*2 + 1];
    computeMD5Hash(logData, md5Hash);

    printf("Processed Log: %s | Hash: %s\n", logData, md5Hash);  // Simulate storing to cache

    pthread_mutex_unlock(&lock);
}

// Function to simulate receiving and processing logs from a queue
void handleIncomingLogs(const char **logEntries, size_t numEntries) {
    for (size_t i = 0; i < numEntries; ++i) {
        processLogEntry(logEntries[i]);
    }
}

// Main function to demonstrate the setup
int main() {
    const int numElements = 10;
    NFAPI_CRC_INDICATION_PDU_T *array;

    initializeNFAPI_CRC_INDICATION_PDU_Array(numElements, &array);

    // Simulating log entries
    const char *logEntries[] = {
        "Critical system error",
        "Routine maintenance completed",
        "Security alert: Unauthorized access attempt detected"
    };

    handleIncomingLogs(logEntries, 3);

    free(array);

    // Clean up the linked list of logs
    pthread_mutex_lock(&lock);
    LogEntry *current = logHead;
    while (current != NULL) {
        LogEntry *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&lock);

    return 0;
}
