#define MAX_SIZE 10000000
extern void log_event(const char *message);
extern bool check_memory_leaks(void); // Placeholder for external memory leak checking function

void initialize_random_seed() {
    srand((unsigned)time(NULL));
}

uint16_t generate_unique_rnti(uint16_t* existing_rntis, size_t count) {
    uint16_t new_rnti;
    do {
        new_rnti = (rand() % MAX_SIZE);
    } while (bsearch(&new_rnti, existing_rntis, count, sizeof(uint16_t), 
                     (__compar_fn_t)memcmp));
    return new_rnti;
}

bool add_rnti_to_set(uint16_t rnti, uint16_t* set, size_t* count, size_t max_size) {
    if (*count >= max_size) return false;
    if (bsearch(&rnti, set, *count, sizeof(uint16_t), 
                (__compar_fn_t)memcmp)) return false;

    set[(*count)++] = rnti;
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* populate_nfa_pdu_array(size_t N) {
    if (N == 0 || N > MAX_SIZE) {
        log_event("Invalid input size");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_event("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T array");
        return NULL;
    }

    uint16_t* rnti_set = malloc(MAX_SIZE * sizeof(uint16_t));
    size_t rnti_count = 0;

    initialize_random_seed();
    log_event("Starting population of NFAPI_CRC_INDICATION_PDU_T array");

    for (size_t i = 0; i < N; ++i) {
        while (true) {
            uint16_t unique_rnti = generate_unique_rnti(rnti_set, rnti_count);
            if (add_rnti_to_set(unique_rnti, rnti_set, &rnti_count, MAX_SIZE)) {
                break;
            }
        }

        array[i].RX_UE_INFORMATION_TAG = i + 1; // Example unique tag generation
        array[i].RNTI = unique_rnti;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRC flag
    }

    log_event("Finished populating NFAPI_CRC_INDICATION_PDU_T array");

    free(rnti_set);
    rnti_set = NULL;

    return array;
}

void cleanup_resources(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
        log_event("Resources deallocated");
    }

    if (!check_memory_leaks()) {
        log_event("Memory leak detected during cleanup");
    }
}
