#include <stdio.h>
#include <stdlib.h>
import time
import random

// Define custom data structures
typedef struct {
    int timestamp;
    char cellIdentity[10];
    int signalStrength;
    int *ueIdentifiers; // Dynamically allocated array
    int *uePowerLevels; // Dynamically allocated array
    size_t ueCount;
} NetworkEvent;

typedef struct {
    int Timestamp;
    char FrameType;
    int PacketSize;
    int ErrorIndicator;
} FrameMetadata;

// Define a linked list node for storing events
typedef struct EventNode {
    NetworkEvent data;
    struct EventNode *next;
} EventNode;

// Function prototypes
void handleNetworkTraffic(int numFrames);
void insertEvent(EventNode **head, NetworkEvent event);
void deleteEvent(EventNode **head, int timestamp);
NetworkEvent* filterEventsBySignalStrength(EventNode *head, int threshold);
FrameMetadata* initializeFrameMetadataArray(size_t count);
int generateErrorIndicator(char frameType, int packetSize);
void logError(const char *message);

// Function to manage network traffic and frames
void handleNetworkTraffic(int numFrames) {
    // Initialize the linked list for storing events
    EventNode *head = NULL;

    // Example of inserting an event (details would be provided dynamically)
    NetworkEvent exampleEvent = { .timestamp = time.time(), .signalStrength = 30, .ueCount = 2 };
    char exampleCellId[] = "cell123";
    int ueIds[] = {101, 102};
    int powerLevels[] = {5, 10};

    exampleEvent.ueIdentifiers = malloc(exampleEvent.ueCount * sizeof(int));
    exampleEvent.uePowerLevels = malloc(exampleEvent.ueCount * sizeof(int));
    memcpy(exampleEvent.ueIdentifiers, ueIds, exampleEvent.ueCount * sizeof(int));
    memcpy(exampleEvent.uePowerLevels, powerLevels, exampleEvent.ueCount * sizeof(int));

    strcpy(exampleEvent.cellIdentity, exampleCellId);

    insertEvent(&head, exampleEvent);

    // Example of filtering events
    int signalThreshold = 25;
    NetworkEvent *filteredEvents = filterEventsBySignalStrength(head, signalThreshold);

    // Initialize frame metadata array for processing application
    FrameMetadata *frames = initializeFrameMetadataArray(numFrames);

    // Cleanup dynamic memory allocated for events
    while (head != NULL) {
        EventNode *temp = head;
        head = head->next;

        free(temp->data.ueIdentifiers);
        free(temp->data.uePowerLevels);
        free(temp);
    }
}

// Insert a new event into the linked list
void insertEvent(EventNode **head, NetworkEvent event) {
    EventNode *newNode = (EventNode *)malloc(sizeof(EventNode));
    newNode->data = event;
    newNode->next = *head;
    *head = newNode;
}

// Delete an event from the linked list by timestamp
void deleteEvent(EventNode **head, int timestamp) {
    EventNode *temp = *head, *prev = NULL;

    if (temp != NULL && temp->data.timestamp == timestamp) {
        *head = temp->next;
        free(temp->data.ueIdentifiers);
        free(temp->data.uePowerLevels);
        free(temp);
        return;
    }

    while (temp != NULL && temp->data.timestamp != timestamp) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;
    free(temp->data.ueIdentifiers);
    free(temp->data.uePowerLevels);
    free(temp);
}

// Filter events by signal strength
NetworkEvent* filterEventsBySignalStrength(EventNode *head, int threshold) {
    size_t count = 0;
    EventNode *current = head;

    // First pass to count matching nodes
    while (current != NULL) {
        if (current->data.signalStrength >= threshold) {
            count++;
        }
        current = current->next;
    }

    NetworkEvent *result = malloc(count * sizeof(NetworkEvent));
    current = head;
    size_t index = 0;

    // Second pass to collect matching nodes
    while (current != NULL) {
        if (current->data.signalStrength >= threshold) {
            result[index++] = current->data;
        }
        current = current->next;
    }

    return result;
}

// Initialize frame metadata array with random error indicators
FrameMetadata* initializeFrameMetadataArray(size_t count) {
    FrameMetadata *frames = malloc(count * sizeof(FrameMetadata));

    for (size_t i = 0; i < count; i++) {
        frames[i].Timestamp = time.time();
        frames[i].FrameType = 'A' + rand() % 3;
        frames[i].PacketSize = rand() % 1500 + 1;
        frames[i].ErrorIndicator = generateErrorIndicator(frames[i].FrameType, frames[i].PacketSize);
    }

    return frames;
}

// Generate error indicator based on frame type and size
int generateErrorIndicator(char frameType, int packetSize) {
    double baseProbability = (frameType == 'B') ? 0.05 : 0.01;
    double probability = baseProbability + log2(packetSize / 100.0);

    return random.random() < probability;
}

// Log errors without significantly degrading performance
void logError(const char *message) {
    // Minimal logging to avoid performance hit; consider more sophisticated systems for production use.
    fprintf(stderr, "Error: %s\n", message);
