typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    long offset;
    int key;
    unsigned int value;
} Record;

#define MAX_ERRORS 100
char error_log[MAX_ERRORS][256];
int error_count = 0;

void log_error(const char *message) {
    if (error_count < MAX_ERRORS) {
        snprintf(error_log[error_count++], sizeof(error_log[0]), "%s", message);
    }
}

Record* manage_memory(int maxOffsets, int maxRecords, const char *filename) {
    Offset *offsetArray = NULL;
    Key *keyArray = NULL;
    Record *recordArray = NULL;

    // Allocate memory for offset and key arrays
    offsetArray = (Offset*)malloc(maxOffsets * sizeof(Offset));
    if (!offsetArray) {
        log_error("Failed to allocate memory for offsets.");
        return NULL;
    }

    keyArray = (Key*)malloc(maxOffsets * sizeof(Key));
    if (!keyArray) {
        free(offsetArray);
        log_error("Failed to allocate memory for keys.");
        return NULL;
    }

    // Allocate memory for record array
    recordArray = (Record*)calloc(maxRecords, sizeof(Record));
    if (!recordArray) {
        free(offsetArray);
        free(keyArray);
        log_error("Failed to allocate memory for records.");
        return NULL;
    }

    FILE *file = fopen(filename, "r");
    if (!file) {
        free(offsetArray);
        free(keyArray);
        free(recordArray);
        log_error("Failed to open input file.");
        return NULL;
    }

    // Read and validate data from the file
    int keySeen[maxOffsets] = {0};
    long offsetSeen[maxOffsets] = {0};

    for (int i = 0; i < maxRecords && fscanf(file, "%ld %d", &recordArray[i].offset, &recordArray[i].key) == 2; ++i) {
        if (i >= maxOffsets || recordArray[i].offset < 0 || recordArray[i].key < 0 ||
            keySeen[recordArray[i].key] || offsetSeen[recordArray[i].offset]) {

            log_error("Invalid or duplicate data encountered in file.");
            fclose(file);
            free(offsetArray);
            free(keyArray);
            free(recordArray);
            return NULL;
        }

        keySeen[recordArray[i].key] = 1;
        offsetSeen[(int)recordArray[i].offset] = 1;
    }

    if (ferror(file)) {
        log_error("Error reading from file.");
        fclose(file);
        free(offsetArray);
        free(keyArray);
        free(recordArray);
        return NULL;
    }

    fclose(file);

    // Set unique random values for each record
    srand((unsigned int)time(NULL));
    unsigned int usedValues[maxRecords] = {0};

    for (int i = 0; i < maxRecords; ++i) {
        int value;
        do {
            value = rand() % 1001;
        } while (usedValues[value]);

        recordArray[i].value = (unsigned int)value;
        usedValues[value] = 1;

        // Initialize offset and key fields
        recordArray[i].offset = i < maxOffsets ? offsetArray[i].offset : -1;
        recordArray[i].key = i < maxOffsets ? keyArray[i].key : -1;
    }

    free(offsetArray);
    free(keyArray);

    return recordArray;
}

int main() {
    int maxOffsets = 1000;
    int maxRecords = 500;
    const char *filename = "data.txt";

    Record *records = manage_memory(maxOffsets, maxRecords, filename);
    if (!records) {
        printf("Error occurred:\n");
        for (int i = 0; i < error_count; ++i) {
            printf("%s\n", error_log[i]);
        }
        return EXIT_FAILURE;
    }

    // Use the records as needed...

    free(records);
    return EXIT_SUCCESS;
}
