#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 1024
#define TIMESTAMP_MIN 1609459200 // Example: Jan 1, 2021
#define TIMESTAMP_MAX 1704067200 // Example: Dec 31, 2025

typedef struct DataPacket {
    uint32_t packet_id;
    time_t timestamp;
    size_t payload_size;
    void *payload;
    struct DataPacket *next;
} DataPacket;

DataPacket* initialize_and_populate_list(size_t num_packets) {
    if (num_packets == 0) return NULL;

    DataPacket *head = NULL, *tail = NULL;
    uint32_t current_id = 1;

    for (size_t i = 0; i < num_packets; ++i) {
        // Generate a unique packet ID
        while (find_packet_by_id(head, current_id)) {
            ++current_id;
        }

        // Generate a valid timestamp
        time_t ts = generate_valid_timestamp();

        // Random payload size within limits
        size_t payload_size = rand() % MAX_PAYLOAD_SIZE + 1;

        DataPacket *new_packet = (DataPacket *)malloc(sizeof(DataPacket));
        if (!new_packet) {
            fprintf(stderr, "Memory allocation failed for packet structure\n");
            continue; // Continue to the next iteration in case of failure
        }

        new_packet->packet_id = current_id++;
        new_packet->timestamp = ts;
        new_packet->payload_size = payload_size;

        // Allocate memory for the payload
        new_packet->payload = malloc(payload_size);
        if (!new_packet->payload) {
            fprintf(stderr, "Memory allocation failed for packet payload\n");
            free(new_packet); // Clean up the allocated structure before continuing
            continue;
        }

        // Append to linked list
        new_packet->next = NULL;
        if (tail) {
            tail->next = new_packet;
        } else {
            head = new_packet;
        }
        tail = new_packet;
    }

    return head;
}

int find_packet_by_id(DataPacket *head, uint32_t packet_id) {
    DataPacket *current = head;
    while (current) {
        if (current->packet_id == packet_id) {
            return 1; // Packet ID found
        }
        current = current->next;
    }
    return 0; // Packet ID not found
}

time_t generate_valid_timestamp() {
    time_t ts;
    do {
        ts = TIMESTAMP_MIN + rand() % (TIMESTAMP_MAX - TIMESTAMP_MIN + 1);
    } while (ts < TIMESTAMP_MIN || ts > TIMESTAMP_MAX);
    return ts;
}

// Usage example:
int main() {
    srand(time(NULL)); // Seed for random number generation
    size_t num_packets = 10; // Number of packets to initialize
    DataPacket *list = initialize_and_populate_list(num_packets);

    if (list) {
        printf("Linked list created with %zu packets.\n", num_packets);
    } else {
        printf("Failed to create linked list.\n");
    }

    return 0;
}
```

