} DynamicList;

typedef void (*CleanupCallback)(NFAAPI_CRC_INDICATION_PDU_T *);

DynamicList* create_dynamic_list(size_t n, int enable_logging) {
    if (n == 0 || n > MAX_ALLOWED_N) { // Define MAX_ALLOWED_N appropriately
        fprintf(stderr, "Invalid size for dynamic list\n");
        return NULL;
    }

    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list structure");
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    list->data = (NFAAPI_CRC_INDICATION_PDU_T *)calloc(n, sizeof(NFAAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory for data array");
        free(list);
        return NULL;
    }

    list->count = n;

    // Log creation details
    if (enable_logging) {
        time_t now = time(NULL);
        printf("[%s] Created dynamic list of size %zu\n", ctime(&now), n);
    }

    return list;
}

void populate_dynamic_list(DynamicList *list, CleanupCallback cleanup_cb) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        NFAAPI_CRC_INDICATION_PDU_T *pdu = &list->data[i];

