            fprintf(stderr, "Failed to compute CRC for index %zu\n", i);
            continue;
        }

        // Randomly set CRCFLAG
        pdu->CRCFLAG = rand() % 2; // Example: random 0 or 1

        // Log detailed information
        if (enable_logging) {
            time_t now = time(NULL);
            printf("[%s] Populated PDU at index %zu with size %zu\n", ctime(&now), i, sizeof(*pdu));
        }
    }

    pthread_mutex_unlock(&list->lock);

    // Perform cleanup using the callback if provided
    if (cleanup_cb) {
        for (size_t i = 0; i < list->count; ++i) {
            cleanup_cb(&list->data[i]);
        }
    }
}

void destroy_dynamic_list(DynamicList *list, int enable_logging) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    free(list->data);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);

    // Log destruction details
    if (enable_logging) {
        time_t now = time(NULL);
        printf("[%s] Destroyed dynamic list\n", ctime(&now));
    }
