#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PAYLOAD_SIZE 1024
#define TIMESTAMP_MIN 0
#define TIMESTAMP_MAX 1000000000

typedef struct Metadata {
    char *key;
    char *value;
} Metadata;

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
    void *payload;
    Metadata *metadata;
    struct DataPacket *prev, *next;
} DataPacket;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to check if the metadata adheres to a predefined schema
int validate_metadata(Metadata *metadata) {
    // Simple validation: key and value should not be NULL or empty
    return metadata && metadata->key && metadata->value &&
           strlen(metadata->key) > 0 && strlen(metadata->value) > 0;
}

// Function to create a new DataPacket node
DataPacket* create_data_packet(int packet_id, long timestamp, size_t payload_size, Metadata *metadata) {
    if (payload_size == 0 || payload_size > MAX_PAYLOAD_SIZE ||
        timestamp < TIMESTAMP_MIN || timestamp > TIMESTAMP_MAX ||
        (!metadata && !validate_metadata(metadata))) {
        return NULL;
    }

    DataPacket *new_packet = malloc(sizeof(DataPacket));
    if (!new_packet) {
        fprintf(stderr, "Memory allocation failed for new packet\n");
        return NULL;
    }

    new_packet->packet_id = packet_id;
    new_packet->timestamp = timestamp;
    new_packet->payload_size = payload_size;
    new_packet->payload = malloc(payload_size);
    if (!new_packet->payload) {
        fprintf(stderr, "Memory allocation failed for packet payload\n");
        free(new_packet);
        return NULL;
    }

    memcpy(new_packet->payload, "", payload_size); // Initialize with empty data
    new_packet->metadata = metadata ? strdup(metadata->key) : NULL;  // Simple copy for demonstration
    new_packet->prev = new_packet->next = NULL;

    return new_packet;
}

// Function to check if a packet ID already exists in the list
int packet_id_exists(DataPacket *head, int packet_id) {
    DataPacket *current = head;
    while (current != NULL) {
        if (current->packet_id == packet_id) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Function to initialize and populate the doubly linked list
DataPacket* init_and_populate_list(int *packet_ids, long *timestamps, size_t *payload_sizes, Metadata **metadata_list, size_t count) {
    pthread_mutex_lock(&list_mutex);

    DataPacket *head = NULL, *tail = NULL;

    for (size_t i = 0; i < count; ++i) {
        if (!packet_id_exists(head, packet_ids[i])) {
            DataPacket *new_packet = create_data_packet(packet_ids[i], timestamps[i], payload_sizes[i], metadata_list[i]);
            if (new_packet) {
                new_packet->next = head;
                if (head != NULL) {
                    head->prev = new_packet;
                }
                head = new_packet;

                if (!tail) {
                    tail = new_packet;  // First element is also the last
                }

                printf("Packet ID %d created and added to list\n", packet_ids[i]);
            } else {
                fprintf(stderr, "Failed to create packet with ID %d\n", packet_ids[i]);
            }
        } else {
            fprintf(stderr, "Duplicate Packet ID %d found. Skipping.\n", packet_ids[i]);
        }
    }

    pthread_mutex_unlock(&list_mutex);

    return head;
}

// Cleanup function for the list
void free_data_packet_list(DataPacket *head) {
    while (head != NULL) {
        DataPacket *temp = head;
        head = head->next;

        if (temp->metadata) {
            free(temp->metadata);
        }
        free(temp->payload);
        free(temp);
    }
}

// Example usage
int main() {
    int packet_ids[] = {1, 2, 3};
    long timestamps[] = {100, 200, 300};
    size_t payload_sizes[] = {512, 256, 128};

    Metadata metadata1 = {"key1", "value1"};
    Metadata metadata2 = {"key2", "value2"};
    Metadata *metadata_list[] = {&metadata1, &metadata2, NULL}; // Last one is optional

    DataPacket *list_head = init_and_populate_list(packet_ids, timestamps, payload_sizes, metadata_list, 3);

    free_data_packet_list(list_head);
    return 0;
}
