#define MAX_FRAMES 1000
#define PAYLOAD_SIZE 256

typedef struct {
    uint16_t source;
    uint16_t destination;
} MAC_Header;

typedef struct {
    uint8_t dsap;
    uint8_t ssap;
    uint8_t control;
