} LLC_SSN;

typedef struct {
    char data[PAYLOAD_SIZE];
    uint32_t checksum;
} Data_Payload;

typedef struct {
    MAC_Header mac_header;
    LLC_SSN llc_ssn;
    Data_Payload data_payload;
} NetworkLayerFrame;

uint32_t calculate_checksum(const char *data, size_t length) {
    // Simple checksum implementation (e.g., Adler-32 or CRC32)
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

void initialize_frames(NetworkLayerFrame *frames, size_t count) {
    if (!frames) return;

    srand(time(NULL));
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);

        // Initialize MAC Header with random values
        frames[i].mac_header.source = rand() % 65536;
        frames[i].mac_header.destination = rand() % 65536;

        // Initialize LLC SSN with fixed dsap/ssap and incrementing SN
        frames[i].llc_ssn.dsap = 0xAA;
        frames[i].llc_ssn.ssap = 0xBB;
        frames[i].llc_ssn.control = 0x03;
        frames[i].llc_ssn.sn = i;

        // Initialize Data Payload with random data and calculate checksum
        for (int j = 0; j < PAYLOAD_SIZE; ++j) {
            frames[i].data_payload.data[j] = rand() % 256;
        }
        frames[i].data_payload.checksum = calculate_checksum(frames[i].data_payload.data, PAYLOAD_SIZE);

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
}

int main() {
    size_t frame_count = 100;
    NetworkLayerFrame *frames = malloc(sizeof(NetworkLayerFrame) * frame_count);

    if (frames) {
        initialize_frames(frames, frame_count);

        // Verify checksum for demonstration
        for (size_t i = 0; i < frame_count; ++i) {
            uint32_t calculated_checksum = calculate_checksum(frames[i].data_payload.data, PAYLOAD_SIZE);
            printf("Frame %zu: Checksum match? %s\n", i, (calculated_checksum == frames[i].data_payload.checksum ? "Yes" : "No"));
        }

        free(frames);
    }

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses a mutex to ensure that the frame initialization is thread-safe.
