typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int id; // Unique identifier
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ResourceList;

ResourceList resource_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

Node* create_node(int id, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->id = id;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_list(ResourceList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
}

NFAPI_CRC_INDICATION_PDU_T generate_default_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 0;
    pdu.RNTI = 0;
