    Node* current = resource_list.head;
    while (current != NULL) {
        if (current->id == id) {
            current->data = updated_data;
            printf("Resource with ID %d updated.\n", id);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&resource_list.lock);
}

void handle_delete_request(int id) {
    pthread_mutex_lock(&resource_list.lock);

    Node *current = resource_list.head, *prev = NULL;
    while (current != NULL) {
        if (current->id == id) {
            if (prev == NULL)
                resource_list.head = current->next;
            else
                prev->next = current->next;

            NFAPI_CRC_INDICATION_PDU_T default_pdu = generate_default_pdu();
            // Optionally initialize the deleted node with default values before freeing.

            free(current);
            printf("Resource with ID %d deleted and initialized to defaults.\n", id);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&resource_list.lock);
}

void handle_http_request(char* method, int id, NFAPI_CRC_INDICATION_PDU_T data) {
    if (strcmp(method, "PUT") == 0) {
        handle_put_request(id, data);
    } else if (strcmp(method, "DELETE") == 0) {
        handle_delete_request(id);
    }
}

void initialize_resources() {
    for (int i = 0; i < MAX_RESOURCES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_default_pdu();
        Node* new_node = create_node(i, pdu);
        if (!new_node) continue;

        pthread_mutex_lock(&resource_list.lock);

        new_node->next = resource_list.head;
        resource_list.head = new_node;

        pthread_mutex_unlock(&resource_list.lock);
    }
}

void cleanup() {
    free_list(&resource_list);
    pthread_mutex_destroy(&resource_list.lock);
}

int main() {
    initialize_resources();

    // Simulate HTTP requests
    NFAPI_CRC_INDICATION_PDU_T data_to_update = {1, 2, 3, _Bool(1)};
    handle_http_request("PUT", 0, data_to_update);  // Example PUT request
    handle_http_request("DELETE", 0, (NFAPI_CRC_INDICATION_PDU_T){});  // Example DELETE request

    cleanup();
    return 0;
}
```

### Key Points:
- **Thread Safety**: The code uses a mutex (`pthread_mutex_t`) to ensure that the list is accessed and modified safely in a multi-threaded environment.
- **Memory Management**: Nodes are dynamically allocated and deallocated, ensuring no memory leaks occur. A `free_list` function cleans up all nodes when needed.
- **Error Handling**: Basic error checks (e.g., null pointers) are included where applicable.
- **Initialization and Cleanup**: The list is initialized with default data and properly cleaned up at the end to prevent resource leakage.
