#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define BUFFER_SIZE_LIMIT 4096

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
