    pthread_mutex_t lock;
    size_t size;
} HashTable;

typedef struct {
    void* pool;
    size_t block_size;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    MemoryPool* mem_pool;
    HashTable* hash_table;
    CRC_INDICATION_REL8_TAG crc_tag;
    pthread_mutex_t list_lock;
    NFAPI_CRC_INDICATION_PDU_T* list[MAX_LIST_SIZE];
    size_t current_size;
} NFAPIDevice;

// Function prototypes
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t total_blocks);
void* allocate_from_pool(MemoryPool* pool);
void deallocate_to_pool(MemoryPool* pool, void* ptr);
HashTable* create_hash_table(size_t initial_capacity);
int insert_into_hash(HashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu);
int is_rnti_present(HashTable* table, uint16_t rnti);
void destroy_hash_table(HashTable* table);
void log_error(const char* message);

// Initialize memory pool
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t total_blocks) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->pool = malloc(block_size * total_blocks);
}

// Allocate memory from the pool
void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (!pool->pool) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void* ptr = pool->pool;
    pool->pool = ((char*)pool->pool) + pool->block_size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Deallocate memory back to the pool
void deallocate_to_pool(MemoryPool* pool, void* ptr) {
    // Simple implementation: Not reclaiming in this example.
}

// Create a hash table for RNTI lookup
HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    pthread_mutex_init(&table->lock, NULL);
    table->head = NULL;
    table->size = 0;
    return table;
}

// Insert into hash table with unique RNTI check
int insert_into_hash(HashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&table->lock);

    if (is_rnti_present(table, pdu.RNTI)) {
        pthread_mutex_unlock(&table->lock);
        return 0; // RNTI already present
    }

    Node* new_node = malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = table->head;
    table->head = new_node;
    table->size++;

    pthread_mutex_unlock(&table->lock);
    return 1;
}

// Check if RNTI is present in the hash table
int is_rnti_present(HashTable* table, uint16_t rnti) {
    Node* current = table->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Destroy the hash table
void destroy_hash_table(HashTable* table) {
    Node* current = table->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Log errors with timestamp
void log_error(const char* message) {
    time_t now = time(NULL);
    char buffer[100];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] ERROR: %s\n", buffer, message);
}

// Initialize NFAPIDevice
void init_nfapi_device(NFAPIDevice* device, size_t block_size, size_t total_blocks, int crc_version) {
    pthread_mutex_init(&device->list_lock, NULL);
    device->current_size = 0;
    memset(device->list, 0, sizeof(device->list));

    init_memory_pool(&device->mem_pool, block_size, total_blocks);
    device->hash_table = create_hash_table(MAX_LIST_SIZE);
    device->crc_tag.version = crc_version;

    // Initialize RNG library here (omitted for brevity)
}

// Add NFAPI_CRC_INDICATION_PDU_T to the list
int add_pdu_to_list(NFAPIDevice* device, uint32_t rx_ue_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&device->list_lock);

    if (device->current_size >= MAX_LIST_SIZE) {
        log_error("List is full");
        pthread_mutex_unlock(&device->list_lock);
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(&device->mem_pool->pool);
    if (!pdu) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&device->list_lock);
        return 0;
    }

    pdu->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu->RNTI = rnti;

    if (!insert_into_hash(device->hash_table, *pdu)) {
        deallocate_to_pool(&device->mem_pool->pool, pdu);
        log_error("Duplicate RNTI");
        pthread_mutex_unlock(&device->list_lock);
        return 0;
    }

    device->list[device->current_size++] = pdu;
    pthread_mutex_unlock(&device->list_lock);
    return 1;
}

// Clean up NFAPIDevice
void cleanup_nfapi_device(NFAPIDevice* device) {
    for (size_t i = 0; i < device->current_size; ++i) {
        deallocate_to_pool(&device->mem_pool->pool, device->list[i]);
    }
    destroy_hash_table(device->hash_table);
    pthread_mutex_destroy(&device->list_lock);
}

int main() {
    NFAPIDevice device;
    init_nfapi_device(&device, 128, MAX_LIST_SIZE, 1);

    // Example usage
    add_pdu_to_list(&device, 12345, 6789);

    cleanup_nfapi_device(&device);
    return 0;
}
