    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t current_memory_usage;
    pthread_mutex_t lock;
    uint16_t* rnti_cache; // Simple cache for storing frequently used RNTIs
    int cache_size;
    int cache_count;
} LinkedList;

LinkedList* create_linked_list(int initial_cache_size) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->current_memory_usage = 0;
    pthread_mutex_init(&list->lock, NULL);

    list->rnti_cache = (uint16_t*)calloc(initial_cache_size, sizeof(uint16_t));
    if (!list->rnti_cache) {
        free(list);
        return NULL;
    }
    list->cache_size = initial_cache_size;
    list->cache_count = 0;

    return list;
}

bool is_rnti_cached(LinkedList* list, uint16_t rnti) {
    for (int i = 0; i < list->cache_count; ++i) {
        if (list->rnti_cache[i] == rnti)
            return true;
    }
    return false;
}

void cache_rnti(LinkedList* list, uint16_t rnti) {
    if (list->cache_count < list->cache_size) {
        list->rnti_cache[list->cache_count++] = rnti;
    } else {
        // Simple FIFO strategy to replace old RNTIs
        memmove(&list->rnti_cache[0], &list->rnti_cache[1],
                (list->cache_size - 1) * sizeof(uint16_t));
        list->rnti_cache[list->cache_size - 1] = rnti;
    }
}

bool add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (is_rnti_cached(list, data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return false; // RNTI already cached
    }

    Node** curr = &(list->head);
    for (int retries = 0; retries < RETRY_LIMIT; ++retries) {
        bool rnti_exists = false;

        for (Node* node = *curr; node != NULL; node = node->next) {
            if (node->data.RNTI == data.RNTI) {
                rnti_exists = true;
                break;
            }
        }

        if (!rnti_exists && list->current_memory_usage + sizeof(Node) <= MAX_MEMORY_USAGE) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            if (!new_node) {
                pthread_mutex_unlock(&list->lock);
                return false;
            }

            new_node->data = data;
            new_node->next = *curr;

            *curr = new_node;
            list->current_memory_usage += sizeof(Node);

            cache_rnti(list, data.RNTI);

            pthread_mutex_unlock(&list->lock);
            return true; // Successfully added
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false; // Exceeded retry limit or memory usage exceeded
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list->rnti_cache);
    free(list);
}

int main() {
    // Example usage
    LinkedList* list = create_linked_list(100);
    if (!list) return 1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand() % 65536; // Random RNTI
    pdu.CRC_INDICATION_REL8_TAG = rand() & 0xFF;

    if (!add_to_list(list, pdu)) {
        printf("Failed to add structure due to duplicate RNTI or memory limit.\n");
    }

    free_linked_list(list);
    return 0;
}
