const char* get_crc_directory() {
    const char *crc_dir = getenv("CRC_DIR");
    if (!crc_dir) {
        struct passwd *pw = getpwuid(geteuid());
        if (pw == NULL) return NULL;

        char dir_path[PATH_MAX];
        snprintf(dir_path, sizeof(dir_path), "%s/.crcdir_%ld", pw->pw_dir, time(NULL));

        mkdir(dir_path, 0755);
        setenv("CRC_DIR", dir_path, 1);
        crc_dir = getenv("CRC_DIR");
    }

    struct stat st;
    if (stat(crc_dir, &st) != 0 || !S_ISDIR(st.st_mode)) {
        return NULL;
    }

    return crc_dir;
}

