    pthread_mutex_lock(&list_mutex);
    int fd = openat(AT_FDCWD, crc_dir, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd != -1) {
        dprintf(fd, "Error: %s\n", error_message);
        close(fd);
