#include <dirent.h>

typedef struct {
    time_t timestamp;
    int sequence_number;
    char transport_layer_stats_tag[256];
} MAC_TransportLayerStats;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10
#define ENV_VAR_NAME "MAC_STATS_DIR"

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    MAC_TransportLayerStats *stats_array;
    size_t size;
    size_t capacity;
} DynamicArray;

void init_random() {
    srand(time(NULL));
}

int generate_unique_sequence_number(int *existing_numbers, size_t count) {
    int seq_num;
    do {
        seq_num = rand() % 1000000; // Adjust range as needed
    } while (bsearch(&seq_num, existing_numbers, count, sizeof(seq_num), cmpfunc));
    return seq_num;
}

int cmpfunc(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

void ensure_environment_variable_and_directory() {
    char *path = getenv(ENV_VAR_NAME);
    if (!path) {
        path = "./mac_stats";
        mkdir(path, 0777); // Create directory with read/write/execute permissions
        setenv(ENV_VAR_NAME, path, 1);
    }
}

void log_change(const char *message) {
    pthread_mutex_lock(&mutex);
    FILE *log_file = fopen("changes.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
    pthread_mutex_unlock(&mutex);
}

int add_mac_transport_layer_stats(DynamicArray *array, const char *tag) {
    pthread_mutex_lock(&mutex);

    int existing_numbers[array->size];
    for (size_t i = 0; i < array->size; ++i) {
        existing_numbers[i] = array->stats_array[i].sequence_number;
    }
    qsort(existing_numbers, array->size, sizeof(int), cmpfunc);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_TransportLayerStats *new_array = realloc(array->stats_array, new_capacity * sizeof(MAC_TransportLayerStats));
        if (!new_array) {
            pthread_mutex_unlock(&mutex);
            return -1; // Memory allocation failed
        }
        array->stats_array = new_array;
        array->capacity = new_capacity;
    }

    MAC_TransportLayerStats new_stat;
    new_stat.timestamp = time(NULL);
    new_stat.sequence_number = generate_unique_sequence_number(existing_numbers, array->size);
    strncpy(new_stat.transport_layer_stats_tag, tag, sizeof(new_stat.transport_layer_stats_tag) - 1);

    array->stats_array[array->size++] = new_stat;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Added stat with seq_num: %d", new_stat.sequence_number);
    log_change(log_message);

    pthread_mutex_unlock(&mutex);
    return 0;
}

void init_dynamic_array(DynamicArray *array) {
    array->size = 0;
    array->capacity = INITIAL_SIZE;
    array->stats_array = malloc(array->capacity * sizeof(MAC_TransportLayerStats));
    if (!array->stats_array) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        exit(EXIT_FAILURE);
    }
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&mutex);
    free(array->stats_array);
    pthread_mutex_unlock(&mutex);
}

int main() {
    ensure_environment_variable_and_directory();

    DynamicArray stats_array;
    init_random();
    init_dynamic_array(&stats_array);

    // Example usage
    add_mac_transport_layer_stats(&stats_array, "ExampleTag1");
    add_mac_transport_layer_stats(&stats_array, "ExampleTag2");

    free_dynamic_array(&stats_array);
    return 0;
}
