```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <arpa/inet.h>

#define DEFAULT_NET_CONFIG_DIR ".netconfig"
#define NET_LOG_FILE "net.log"

typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char default_gateway[16];
} NetworkConfig;

typedef struct Node {
    NetworkConfig config;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

int is_valid_ip(const char* ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) != 0;
}

int is_unique_ip(const char* ip) {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    while (current) {
        if (strcmp(current->config.ip_address, ip) == 0) {
            pthread_mutex_unlock(&list_mutex);
            return 0; // Duplicate found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
    return 1; // Unique
}

void log_warning(const char* message, const char* dir) {
    FILE* log_file = fopen(dir ? strcat(strdup(dir), "/") : "", strcat(strdup(NET_LOG_FILE), ""), "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void add_config_to_list(NetworkConfig config) {
    pthread_mutex_lock(&list_mutex);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->config = config;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&list_mutex);
}

void free_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;

    pthread_mutex_unlock(&list_mutex);
}

int parse_config_files(const char** directories, int num_dirs) {
    for (int i = 0; i < num_dirs; ++i) {
        DIR* dir = opendir(directories[i]);
        if (!dir) continue;

        struct dirent* entry;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG) { // Regular file
                char filepath[256];
                snprintf(filepath, sizeof(filepath), "%s/%s", directories[i], entry->d_name);

                FILE* file = fopen(filepath, "r");
                if (!file) continue;

                NetworkConfig config;
                memset(&config, 0, sizeof(config));

                char line[128];
                while (fgets(line, sizeof(line), file)) {
                    if (strncmp(line, "IP=", 3) == 0) strcpy(config.ip_address, line + 3);
                    else if (strncmp(line, "MASK=", 5) == 0) strcpy(config.subnet_mask, line + 5);
                    else if (strncmp(line, "GATEWAY=", 8) == 0) strcpy(config.default_gateway, line + 8);
                }

                fclose(file);

                if (!is_valid_ip(config.ip_address)) {
                    log_warning("Invalid IP address in file: " filepath, directories[i]);
                    continue;
                }

                if (strlen(config.subnet_mask) > 0 && !is_valid_ip(config.subnet_mask)) {
                    log_warning("Invalid subnet mask in file: " filepath, directories[i]);
                    continue;
                }

                if (strlen(config.default_gateway) > 0 && !is_valid_ip(config.default_gateway)) {
                    log_warning("Invalid default gateway in file: " filepath, directories[i]);
                    continue;
                }

                if (!is_unique_ip(config.ip_address)) {
                    char warning_msg[256];
                    snprintf(warning_msg, sizeof(warning_msg), "Duplicate IP address found in file: %s", filepath);
                    log_warning(warning_msg, directories[i]);
                    continue;
                }

                add_config_to_list(config);
            }
        }

        closedir(dir);
    }

    return 0;
}

char* get_directory_path(const char* env_var) {
    if (env_var && getenv(env_var)) {
        size_t len = strlen(getenv(env_var));
        char* path = malloc(len + 1);
        strcpy(path, getenv(env_var));
        return path;
    }
    return NULL;
}

int create_default_dir() {
    char home[1024];
    if (getcwd(home, sizeof(home)) == NULL) {
        perror("Failed to get current working directory");
        return -1;
    }

    char default_path[1024];
    snprintf(default_path, sizeof(default_path), "%s/%s", home, DEFAULT_NET_CONFIG_DIR);

    mkdir(default_path, 0700);
    return 0;
}

int initialize_network_configurations() {
    const char* env_dirs[] = { "NET_CONFIG_DIR", "NET_DEFAULT_DIR" };
    int num_env_dirs = sizeof(env_dirs) / sizeof(env_dirs[0]);
    char* directories[num_env_dirs + 1];

    for (int i = 0; i < num_env_dirs; ++i) {
        char* dir_path = get_directory_path(env_dirs[i]);
        if (dir_path) {
            directories[i] = dir_path;
        } else {
            directories[i] = NULL;
        }
    }

    if (!directories[0] && !directories[1]) {
        if (create_default_dir() != 0) return -1;
        directories[num_env_dirs] = malloc(strlen(getcwd(NULL, 0)) + strlen(DEFAULT_NET_CONFIG_DIR) + 2);
        snprintf(directories[num_env_dirs], strlen(getcwd(NULL, 0)) + strlen(DEFAULT_NET_CONFIG_DIR) + 2, "%s/%s", getcwd(NULL, 0), DEFAULT_NET_CONFIG_DIR);
    } else {
        directories[num_env_dirs] = NULL;
    }

    return parse_config_files((const char**)directories, num_env_dirs + (directories[num_env_dirs] ? 1 : 0));
}

int main() {
    int status = initialize_network_configurations();
    if (status != 0) {
        fprintf(stderr, "Failed to initialize network configurations\n");
        return EXIT_FAILURE;
    }

    // Use the list as needed...

    free_list(); // Clean up

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety:** The function uses a mutex (`pthread_mutex_t`) to ensure thread safety when accessing and modifying the linked list.
- **Dynamic Memory Management:** The linked list is used for storing configurations, allowing dynamic memory allocation.
- **Error Handling:** Robust error checking is implemented for file operations and directory creation.
- **Unique IP Check:** Ensures that each configuration has a unique IP address.
- **Logging:** Logs warnings to `net.log` in the specified directory.']

