            // Update existing entry
            (*current)->data = entry;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = &((*current)->next);
    }

    // Add new entry
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->data = entry;
    newNode->next = NULL;
    *current = newNode;

    pthread_mutex_unlock(&list->lock);
}

// Function to retrieve an entry by RNTI
NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(NFAPIDynamicList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* entry = &current->data;
            pthread_mutex_unlock(&list->lock);
            return entry;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Function to serialize the list to a file
void serialize_list(NFAPIDynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

// Function to deserialize the list from a file
void deserialize_list(NFAPIDynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    // Clear existing list
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    NFAPI_CRC_INDICATION_PDU_T entry;
    while (fread(&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_or_update_entry(list, entry);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

// Function to free the list
void free_list(NFAPIDynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

### Key Points:
