#define MAX_ELEMENTS 5000

typedef struct {
    uint32_t valid_RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_rwlock_t lock;
} CRCList;

void init_crc_list(CRCList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_rwlock_init(&list->lock, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void free_list(CRCList* list) {
    pthread_rwlock_wrlock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
}

int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->size >= MAX_ELEMENTS) return -1;

    Node* node = create_node(pdu);
    if (!node) return -1;

    pthread_rwlock_wrlock(&list->lock);

    if (list->tail) {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    } else {
        list->head = node;
        list->tail = node;
    }
    list->size++;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

void* iterate_list(CRCList* list, int reverse) {
    pthread_rwlock_rdlock(&list->lock);

    Node* current = reverse ? list->tail : list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T pdu = current->data;
        printf("RX_UE_TAG: %u, RNTI: %u, CRCFLAG: %d\n", pdu.valid_RX_UE_INFORMATION_TAG,
               pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);

        if (reverse) {
            current = current->prev;
        } else {
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&list->lock);
}

// Example usage
int main() {
    CRCList list;
    init_crc_list(&list);

    // Simulate adding PDUs to the list
    for (int i = 0; i < 10000; ++i) {  // Add more than MAX_ELEMENTS to test limit
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .valid_RX_UE_INFORMATION_TAG = rand(),
            .RNTI = rand() % 65535,
            .CRC_INDICATION_REL8_TAG = {.CRCFLAG = i % 2}
        };
        add_pdu(&list, pdu);
    }

    // Iterate over the list
    iterate_list(&list, 0);  // Forward iteration
    iterate_list(&list, 1);  // Reverse iteration

    free_list(&list);

    return 0;
}

