typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned long total_crc_processed;
} CRCDynamicArray;

void log_warning(const char* message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

int allocate_and_initialize_structures(CRCDynamicArray *array, size_t n) {
    if (n <= 0) {
        log_warning("Non-positive number of instances requested.");
        return -1;
    }

    const size_t initial_capacity = 10;
    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;

    if (!array->data) {
        log_warning("Initial memory allocation failed.");
        return -1;
    }

    pthread_mutex_init(&array->lock, NULL);
    array->total_crc_processed = 0;

    for (size_t i = 0; i < n; ++i) {
        if (i >= array->capacity) {
            size_t new_capacity = array->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* temp = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!temp) {
                log_warning("Memory reallocation failed.");
                free(array->data);
                pthread_mutex_destroy(&array->lock);
                return -1;
            }

            array->data = temp;
            array->capacity = new_capacity;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = &array->data[i];
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Random value
        pdu->RNTI = rand() % 10000; // Random value
        pdu->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return 0;
}

void process_crc_indications(CRCDynamicArray *array, size_t n) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < n && i < array->capacity; ++i) {
        // Simulate processing
        array->total_crc_processed++;
    }

    pthread_mutex_unlock(&array->lock);
}

void free_structures(CRCDynamicArray *array) {
    if (array->data) {
        free(array->data);
        array->data = NULL;
    }
    pthread_mutex_destroy(&array->lock);
}

void monitor_system(const CRCDynamicArray *array) {
    printf("Total CRC Indications Processed: %lu\n", array->total_crc_processed);
}

int main() {
    srand(time(NULL));

    const size_t n_instances = 50;
    CRCDynamicArray crc_array;

    if (allocate_and_initialize_structures(&crc_array, n_instances) != 0) {
        return EXIT_FAILURE;
    }

    process_crc_indications(&crc_array, n_instances);

    monitor_system(&crc_array);

    free_structures(&crc_array);

    return EXIT_SUCCESS;
}
