    vsnprintf(message, len, format, args);

    LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (new_entry) {
        strcpy(new_entry->message, message);
        new_entry->next = log_buffer_head;
        log_buffer_head = new_entry;
        log_buffer_size += len;

