    pthread_mutex_unlock(&crc_mutex);

    free(message);
    va_end(args);
}

void flush_log_buffer() {
    LogEntry* current = log_buffer_head;
    while (current) {
        retry_log_write(current->message);
        LogEntry* temp = current;
        current = current->next;
        free(temp->message);
        free(temp);
    }
    log_buffer_head = NULL;
    log_buffer_size = 0;
}

void retry_log_write(const char* message) {
