    pthread_t threads[NUM_THREADS];
    struct { int start; int end; } range_info[NUM_THREADS];

    int elements_per_thread = n_elements / NUM_THREADS;
    for (int i = 0; i < NUM_THREADS; ++i) {
        range_info[i].start = i * elements_per_thread;
        range_info[i].end = (i == NUM_THREADS - 1) ? n_elements : (i + 1) * elements_per_thread;

        pthread_create(&threads[i], NULL, process_crc_indications, &range_info[i]);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    flush_log_buffer();
}

