#include <pthread.h>
#include <string.h>

#define MAX_RETRIES 10
#define MEMORY_LIMIT (1 * 1024 * 1024) // 1 MB for every 1000 structures
#define CACHE_SIZE 128

typedef struct {
    uint32_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG; // Assuming it's an integer or similar identifier.
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    uint32_t used_memory; // To track memory usage
    uint32_t rnti_cache[CACHE_SIZE];
} LinkedList;

// Helper function to create a new node.
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Initialize the linked list.
void init_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->used_memory = 0;
    memset(list->rnti_cache, 0, sizeof(list->rnti_cache));
}

// Check if RNTI is already in the cache.
int is_rnti_cached(LinkedList* list, uint32_t rnti) {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (list->rnti_cache[i] == rnti)
            return 1;
    }
    return 0;
}

// Add RNTI to the cache.
void add_rnti_to_cache(LinkedList* list, uint32_t rnti) {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (list->rnti_cache[i] == 0) {
            list->rnti_cache[i] = rnti;
            break;
        }
    }
}

// Check if RNTI is already in the linked list.
int has_rnti(LinkedList* list, uint32_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.crc_tag.RNTI == rnti)
            return 1;
        current = current->next;
    }
    return 0;
}

// Insert a new node into the linked list.
int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    // Check memory limit
    if (list->used_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MEMORY_LIMIT) {
        printf("Memory usage exceeded the limit.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (!is_rnti_cached(list, data.crc_tag.RNTI) && !has_rnti(list, data.crc_tag.RNTI)) {
            Node* new_node = create_node(data);
            if (!new_node) {
                pthread_mutex_unlock(&list->lock);
                return -1;
            }

            // Insert at the head for simplicity.
            new_node->next = list->head;
            list->head = new_node;

            // Update memory usage and cache
            list->used_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
            add_rnti_to_cache(list, data.crc_tag.RNTI);

            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        } else {
            retries++;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Failed to insert after max retries
}

// Validate the CRCFLAG for all nodes.
int validate_crcflags(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.crc_tag.CRCFLAG == 0) { // Assuming 0 is invalid.
            return -1; // Invalid CRCFLAG detected
        }
        current = current->next;
    }
    return 0; // All CRCFLAGS are valid
}

// Cleanup the list and free resources.
void cleanup_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    pthread_mutex_destroy(&list->lock);
}

// Example usage of the linked list.
int main() {
    LinkedList list;
    init_list(&list);

    // Simulate insertion
    NFAPI_CRC_INDICATION_PDU_T data1 = { .RX_UE_INFORMATION_TAG = 123, .crc_tag = { .RNTI = 45678, .CRCFLAG = 1 } };
    int result = insert_node(&list, data1);

    if (result == 0) {
        printf("Node inserted successfully.\n");
    } else {
        printf("Failed to insert node.\n");
    }

    // Validate CRCFLAGS
    if (validate_crcflags(&list) == 0) {
        printf("All CRCFLAGS are valid.\n");
    } else {
        printf("Invalid CRCFLAG detected.\n");
    }

    // Cleanup
    cleanup_list(&list);

    return 0;
}
```

### Key Considerations:
- **Thread Safety**: The `pthread_mutex_t` is used to ensure thread safety when modifying the list.
- **Memory Management**: Memory usage is tracked and capped at 1 MB per 1000 structures, with logging if exceeded.
- **RNTI Uniqueness**: A retry mechanism ensures unique RNTIs are inserted into the list. An in-memory cache reduces the frequency of retries by storing frequently used RNTIs.
- **Performance vs Memory Trade-offs**: This implementation prioritizes efficient memory management and thread safety over frequent re-allocation, optimizing for performance within given constraints.
- **Scalability**: The caching strategy improves throughput but is capped at a fixed size (`CACHE_SIZE`), which can be tuned based on application needs.']

