    unsigned long RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Structure to manage the linked list and cache
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned long* rnti_cache;
    size_t cache_size;
} LinkedListManager;

// Function prototypes
void initialize_manager(LinkedListManager* manager, size_t cache_size);
int insert_pdu(LinkedListManager* manager, int RX_UE_INFORMATION_TAG, unsigned long RNTI);
Node* find_node_by_rnti(LinkedListManager* manager, unsigned long RNTI);
int delete_pdu(LinkedListManager* manager, unsigned long RNTI);
void cleanup_manager(LinkedListManager* manager);

// Initialize the linked list and cache
void initialize_manager(LinkedListManager* manager, size_t cache_size) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->rnti_cache = malloc(cache_size * sizeof(unsigned long));
    manager->cache_size = cache_size;
}

// Insert a new PDU into the linked list
int insert_pdu(LinkedListManager* manager, int RX_UE_INFORMATION_TAG, unsigned long RNTI) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->cache_size; ++i) {
        if (manager->rnti_cache[i] == RNTI) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate RNTI
        }
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failure
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    Node** current = &manager->head;
    while (*current) {
        if ((*current)->data.RNTI == RNTI) {
            free(new_node);
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate RNTI
        }
        current = &(*current)->next;
    }

    *current = new_node;
    *current = NULL;

    // Update cache (simple FIFO strategy)
    manager->rnti_cache[(manager->cache_size + 1) % manager->cache_size] = RNTI;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Find a node by RNTI
Node* find_node_by_rnti(LinkedListManager* manager, unsigned long RNTI) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_unlock(&manager->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Delete a PDU by RNTI
int delete_pdu(LinkedListManager* manager, unsigned long RNTI) {
    pthread_mutex_lock(&manager->lock);

    Node** current = &manager->head;
    while (*current) {
        if ((*current)->data.RNTI == RNTI) {
            Node* to_delete = *current;
            *current = (*current)->next;
            free(to_delete);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Not found
}

// Cleanup the manager and linked list
void cleanup_manager(LinkedListManager* manager) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete);
    }

    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager->rnti_cache);
}

// Web API server (using pseudo-code for HTTP handling)
