    // Initialize server and define endpoints
    // PUT /resources/{id}
    void handle_put_request(int id, const char* data) {
        // Validate and update resource in memory
    }

    // DELETE /resources/{id}
    void handle_delete_request(int id) {
        // Delete resource and return default values
    }
}

int main() {
    LinkedListManager manager;
    initialize_manager(&manager, 100); // Example cache size

    // Start the server
    start_server();

    // Example usage
    insert_pdu(&manager, 1, 12345);
    Node* node = find_node_by_rnti(&manager, 12345);
    if (node) {
        printf("Found PDU with RNTI: %lu\n", node->data.RNTI);
    }

    delete_pdu(&manager, 12345);

    cleanup_manager(&manager);
