using System;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.AspNetCore.SignalR;

public class PageContentUpdaterService
{
    private readonly IHubContext<UpdateHub> _hubContext;
    private readonly IDistributedCache _cache;
    private const string CacheKeyPrefix = "PageVersion_";

    public PageContentUpdaterService(IHubContext<UpdateHub> hubContext, IDistributedCache cache)
    {
        _hubContext = hubContext;
        _cache = cache;
    }

    public async Task<string> UpdatePageContentAsync(string pageSectionId, string elementId, string newHtmlContent, int versionId)
    {
        var cachedVersionKey = $"{CacheKeyPrefix}{pageSectionId}";
        var cachedVersion = await _cache.GetStringAsync(cachedVersionKey);

        if (cachedVersion != null && Convert.ToInt32(cachedVersion) == versionId)
        {
            // Update the content
            await UpdateElementContentAsync(pageSectionId, elementId, newHtmlContent);

            // Invalidate cache to trigger update for others
            await _cache.SetStringAsync(cachedVersionKey, (++versionId).ToString());

            // Notify connected clients via SignalR
            await _hubContext.Clients.All.SendAsync("ReceiveUpdate", pageSectionId, elementId, newHtmlContent);

            return "Content updated successfully.";
        }
        else
        {
            return "Content version is outdated. Please refresh and try again.";
        }
    }

    private async Task UpdateElementContentAsync(string pageSectionId, string elementId, string newHtmlContent)
    {
        // Logic to update the HTML content of the specific element in the server's database or storage.
        // For example:
        await Task.Run(() =>
        {
            Console.WriteLine($"Updating {pageSectionId} - {elementId} with new content.");
            // Simulate a delay for processing
            System.Threading.Thread.Sleep(100);
        });
    }
}

public class UpdateHub : Hub
{
    public async Task SendUpdate(string pageSectionId, string elementId, string htmlContent)
    {
        await Clients.All.SendAsync("ReceiveUpdate", pageSectionId, elementId, htmlContent);
    }
}
