#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define RNTI_MIN 0x0001
#define RNTI_MAX 0xFFFFF

typedef struct {
    int valid;
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInformationTag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST;

bool isValidRNTI(int rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

NFAPI_CRC_INDICATION_LIST* createList(size_t initialCapacity) {
    NFAPI_CRC_INDICATION_LIST* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!list) return NULL;

    list->items = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyList(NFAPI_CRC_INDICATION_LIST* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->items);
        free(list);
    }
}

bool addNFAPIItem(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (!isValidRNTI(item.rnti)) return false;

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LIST_SIZE || list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    list->items[list->count++] = item;

    pthread_mutex_unlock(&list->lock);
    return true;
}

void clearList(NFAPI_CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        list->items[i].ueInformationTag.valid = 0;
    }
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void resizeList(NFAPI_CRC_INDICATION_LIST* list, size_t newCapacity) {
    if (newCapacity > MAX_LIST_SIZE || newCapacity <= list->capacity) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* newItems = realloc(list->items, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newItems) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->items = newItems;
    list->capacity = newCapacity;

    pthread_mutex_unlock(&list->lock);
}

// Unit tests
void testAddItem() {
    NFAPI_CRC_INDICATION_LIST* list = createList(10);

    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T item;
        item.ueInformationTag.valid = 1;
        item.rnti = RNTI_MIN + (rand() % (RNTI_MAX - RNTI_MIN + 1));
        item.crcIndicationRel8Tag.crcFlag = rand() % 2;

        bool success = addNFAPIItem(list, item);
        if (!success) {
            printf("Failed to add item with RNTI: %d\n", item.rnti);
        }
    }

    destroyList(list);
}

void testResizeFunctionality() {
    NFAPI_CRC_INDICATION_LIST* list = createList(10);

    for (size_t i = 0; i < 5; ++i) {
        NFAPI_CRC_INDICATION_PDU_T item;
        item.ueInformationTag.valid = 1;
        item.rnti = RNTI_MIN + rand() % (RNTI_MAX - RNTI_MIN + 1);
        item.crcIndicationRel8Tag.crcFlag = rand() % 2;

        addNFAPIItem(list, item);
    }

    printf("Resizing list...\n");
    resizeList(list, 20);

    clearList(list);
    destroyList(list);
}

int main() {
    srand(time(NULL));

    testAddItem();
    testResizeFunctionality();

    return 0;
}
