// Global variables for concurrency management and statistics.
size_t total_frames_processed = 0;
pthread_mutex_t frames_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t frames_cond = PTHREAD_COND_INITIALIZER;

// Function to allocate memory with error handling
NFAPI_PHY_FRAME_T* allocate_phy_frame_array(size_t n) {
    if (n <= 0) {
        fprintf(stderr, "Warning: Requested allocation size is zero or negative.\n");
        return NULL;
    }

    NFAPI_PHY_FRAME_T *frames = NULL;
    size_t chunk_size = 1; // Start with a small chunk to minimize initial allocation
    while (chunk_size <= n) {
        void* temp_frames = realloc(frames, chunk_size * sizeof(NFAPI_PHY_FRAME_T));
        if (temp_frames != NULL) {
            frames = temp_frames;
            for (size_t i = 0; i < chunk_size; ++i) {
                // Initialize each PHY frame structure
                frames[i].phy_frame_tag = rand() % 256; // Example valid tag initialization
                frames[i].pci = rand() % 1024;          // Example PCI value
                frames[i].symbol_info.modulation_and_codeword_type = rand() % 16;
            }
            if (chunk_size == n) {
                return frames;
            }
        } else {
            fprintf(stderr, "Memory allocation failed, trying a smaller chunk size.\n");
            free(frames);
            chunk_size /= 2; // Reduce chunk size for next attempt
        }

        if (chunk_size == 0) { // If chunk size reduces to zero, handle as failure
            free(frames);
            return NULL;
        }
    }
    return frames; // Should never reach here
}

// Function to process PHY frame array safely across threads
void* process_phy_frames(void* arg) {
    NFAPI_PHY_FRAME_T* frames = (NFAPI_PHY_FRAME_T*)arg;
    size_t n = *(size_t*)frames;

    for (size_t i = 0; i < n; ++i) {
        // Processing logic, e.g., processing each PHY frame
    }

    pthread_mutex_lock(&frames_mutex);
    total_frames_processed += n;
    pthread_cond_signal(&frames_cond); // Signal after updating the count
    pthread_mutex_unlock(&frames_mutex);

    return NULL;
}

// Function to manage dynamic scaling of threads based on workload
void scale_and_process(size_t num_instances) {
    pthread_t thread_ids[num_instances];
    size_t instance_sizes[num_instances];

    for (size_t i = 0; i < num_instances; ++i) {
        // Example varying sizes, can be optimized or determined by workload
        instance_sizes[i] = rand() % 100 + 1;

        NFAPI_PHY_FRAME_T* frames = allocate_phy_frame_array(instance_sizes[i]);
        if (frames == NULL) {
            fprintf(stderr, "Failed to allocate memory for instance %zu\n", i);
            continue; // Skip this instance due to allocation failure
        }

        pthread_create(&thread_ids[i], NULL, process_phy_frames, (void*)&instance_sizes[i]);
    }

    for (size_t i = 0; i < num_instances; ++i) {
        pthread_join(thread_ids[i], NULL);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t desired_num_instances = 10;
    scale_and_process(desired_num_instances);

    // Optionally, wait and print the total frames processed.
    pthread_mutex_lock(&frames_mutex);
    while (total_frames_processed == 0) {
        pthread_cond_wait(&frames_cond, &frames_mutex); // Wait for processing to complete
    }
    printf("Total PHY Frames Processed: %zu\n", total_frames_processed);
    pthread_mutex_unlock(&frames_mutex);

    return 0;
}
