#include <pthread.h>
#include <string.h>

// Define constants
#define MAX_RNTI 65535
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Assume this is an integer for simplicity.
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define a dynamic list with thread-safe operations
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPI_CrcIndicationList;

// Function prototypes
NFAPI_CrcIndicationList* create_list();
void free_list(NFAPI_CrcIndicationList* list);
int add_pdu(NFAPI_CrcIndicationList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu, int log_level);

// Logging function
void log_message(int level, const char* message) {
    if (level >= LOG_LEVEL_INFO) {
        printf("LOG: %s\n", message);
    }
}

// Function implementations

NFAPI_CrcIndicationList* create_list() {
    NFAPI_CrcIndicationList* list = malloc(sizeof(NFAPI_CrcIndicationList));
    if (!list) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for list.");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(NFAPI_CrcIndicationList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_pdu(NFAPI_CrcIndicationList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu, int log_level) {
    if (!list || !pdu) return -1;

    if (pdu->RNTI > MAX_RNTI) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Invalid RNTI value: %u. Skipping PDU.", pdu->RNTI);
        log_message(log_level, msg);
        return 0;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for new node.");
        return -1;
    }

    *new_node = (Node){ .data = *pdu, .next = NULL };

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    log_message(log_level, "PDU added successfully.");
    return 0;
}

// Example usage
int main() {
    NFAPI_CrcIndicationList* list = create_list();
    if (!list) return -1;

    // Simulate adding PDUs with valid and invalid RNTI values
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % (MAX_RNTI + 1); // Random RNTI within valid range
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

        add_pdu(list, &pdu, LOG_LEVEL_DEBUG);
    }

    free_list(list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` lock is used to ensure thread-safe operations on the linked list.
- **Error Handling**: Memory allocation failures and invalid RNTI values are logged and handled gracefully.
- **Logging**: A simple logging mechanism with configurable levels helps in debugging without overwhelming production logs.
- **Scalability**: The code structure allows for easy extension, such as adding more fields to `NFAPI_CRC_INDICATION_PDU_T` or integrating new data sources.']

