    struct Node *next;
    struct Node *prev;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void initialize_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    // Initialize RX_UE_INFORMATION_TAG and RNTI with some values
    element->valid_RX_UE_INFORMATION_TAG = rand() % 1000;
    element->RNTI = rand() % 10000;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;
}

void insert_element(LinkedList *list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_ELEMENTS) return;

    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    new_node->prev = NULL;

    if (list->head != NULL) {
        list->head->prev = new_node;
    }
    list->head = new_node;

    if (list->tail == NULL) {
        list->tail = new_node;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void clear_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList *list) {
    clear_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void iterate_forward(const LinkedList *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

void iterate_reverse(const LinkedList *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->tail;
    while (current != NULL) {
        callback(current->data);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

// Usage example function
void print_element(NFAPI_CRC_INDICATION_PDU_T data) {
    printf("RNTI: %d, CRCFLAG: %d\n", data.RNTI, data.CRC_INDICATION_REL8_TAG.CRCFLAG);
}

int main() {
    LinkedList *list = create_list();

    // Insert elements
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        NFAPI_CRC_INDICATION_PDU_T element;
        initialize_element(&element);
        insert_element(list, element);
    }

    // Iterate forward and print elements
    iterate_forward(list, print_element);

    // Clear list and free resources
    clear_list(list);
    free_list(list);

    return 0;
}
```

### Explanation of Choices:

1. **Data Structure**: A doubly-linked list was chosen to allow efficient insertions and deletions at both ends while supporting iteration in both directions. This choice balances memory usage with the need for flexible access patterns.

2. **Concurrency Control**: A single mutex is used to protect the entire list, providing simplicity and ensuring thread safety during modifications. For applications requiring higher concurrency levels, finer-grained locking or lock-free techniques could be explored but may add complexity without significant performance gain in typical use cases.

3. **Memory Management**: The list dynamically allocates nodes as needed, ensuring efficient memory usage and avoiding fragmentation issues common with fixed-size arrays under heavy load. Nodes are freed during the `clear_list` operation to manage resource cleanup effectively.

4. **Scalability Considerations**: With a maximum size limit of 5000 elements, the design accommodates expected workload characteristics without excessive memory overhead, ensuring system responsiveness even under high traffic loads.

5. **Performance Optimization**: By initializing elements with random data and using callback functions for iteration, the design allows for easy adaptation to different processing needs, enhancing maintainability and usability.']

