typedef struct {
    int *parent;
    size_t n;
} UnionFind;

UnionFind* union_find_create(size_t n) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    uf->n = n;
    uf->parent = malloc(n * sizeof(int));
    for (size_t i = 0; i < n; ++i)
        uf->parent[i] = i;
    return uf;
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void union_sets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY)
        uf->parent[rootY] = rootX;
}

void free_union_find(UnionFind *uf) {
    free(uf->parent);
    free(uf);
}

int disjoint_pairs(int *arr, size_t n) {
    UnionFind *uf = union_find_create(n);
    int disjoint_count = 0;

    for (size_t i = 0; i < n - 1; ++i)
        for (size_t j = i + 1; j < n; ++j)
            if ((find(uf, arr[i]) != find(uf, arr[j]))) {
                union_sets(uf, arr[i], arr[j]);
                disjoint_count++;
            }

    free_union_find(uf);
    return disjoint_count;
}

void* generate_and_populate(void *arg) {
    size_t num_elements = *((size_t*)arg);
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_t lock;

    for (size_t i = 0; i < num_elements; ++i) {
        list[i].rx_ue_info = rand();
        list[i].rnti = rand() & 0xFFFF;
        list[i].crc_indication_tag = rand() % 256;
        list[i].crc_flag = rand() % 2;
    }

    pthread_mutex_init(&lock, NULL);
    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&lock);
        // Simulate some processing
        pthread_mutex_unlock(&lock);
    }
    pthread_mutex_destroy(&lock);

    free(list);
    return NULL;
}

void generateNFAPairCRCIndications(size_t num_pnfs, int *array, size_t array_size) {
    pthread_t threads[2];
    size_t thread_args[2] = {num_pnfs, array_size};

    clock_t start_time = clock();
    disjoint_pairs(array, array_size);
    clock_t end_time = clock();

    double time_taken = (double)(end_time - start_time) / CLOCKS_PER_SEC * 1000;
    printf("Disjoint pair checks took %f milliseconds\n", time_taken);

    pthread_create(&threads[0], NULL, generate_and_populate, &thread_args[0]);
    pthread_create(&threads[1], NULL, generate_and_populate, &thread_args[1]);

    pthread_join(threads[0], NULL);
    pthread_join(threads[1], NULL);
}
```']

['Below is a C implementation that addresses your requirements for managing a dynamic collection of TCP connection metadata structures. This code uses a hash table combined with fine-grained locking to efficiently manage connections while minimizing lock contention. It also includes mechanisms for dynamic resizing and supports concurrent access from multiple threads.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 1024
#define LOAD_FACTOR_THRESHOLD 0.75

typedef enum {
    ESTABLISHED,
    TIME_WAIT,
    // Add other states as needed
} ConnectionState;

typedef struct {
    char client_ip[INET6_ADDRSTRLEN];
    int client_port;
    char server_ip[INET6_ADDRSTRLEN];
    int server_port;
    ConnectionState state;
} ConnectionMetadata;

typedef struct Entry {
    ConnectionMetadata metadata;
    struct Entry *next;
} Entry;

typedef struct {
    Entry **buckets;
    size_t size;
    size_t count;
    pthread_rwlock_t rwlock; // Read-write lock for bucket access
} ConnectionTable;

// Hash function
unsigned int hash(const char *ip, int port) {
    return (hash_string(ip) + port) % INITIAL_SIZE;
}

unsigned int hash_string(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

ConnectionTable* create_table() {
    ConnectionTable *table = malloc(sizeof(ConnectionTable));
    table->size = INITIAL_SIZE;
    table->count = 0;
    table->buckets = calloc(table->size, sizeof(Entry *));
    pthread_rwlock_init(&table->rwlock, NULL);
    return table;
}

void resize_table(ConnectionTable *table) {
    size_t new_size = table->size * 2;
    Entry **new_buckets = calloc(new_size, sizeof(Entry *));

    for (size_t i = 0; i < table->size; i++) {
        pthread_rwlock_rdlock(&table->rwlock);
        Entry *entry = table->buckets[i];

        while (entry) {
            size_t new_index = hash(entry->metadata.client_ip, entry->metadata.client_port) % new_size;

            Entry *next_entry = entry->next;
            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;
            entry = next_entry;
        }

        pthread_rwlock_unlock(&table->rwlock);
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

void insert_connection(ConnectionTable *table, ConnectionMetadata metadata) {
    if ((double)table->count / table->size > LOAD_FACTOR_THRESHOLD) {
        resize_table(table);
    }

    unsigned int index = hash(metadata.client_ip, metadata.client_port);

    pthread_rwlock_wrlock(&table->rwlock);
    Entry *entry = malloc(sizeof(Entry));
    entry->metadata = metadata;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    table->count++;
    pthread_rwlock_unlock(&table->rwlock);
}

void remove_connection(ConnectionTable *table, const char *client_ip, int client_port) {
    unsigned int index = hash(client_ip, client_port);

    pthread_rwlock_wrlock(&table->rwlock);
    Entry *entry = table->buckets[index];
    Entry *prev_entry = NULL;

    while (entry && 
           (strcmp(entry->metadata.client_ip, client_ip) != 0 || entry->metadata.client_port != client_port)) {
        prev_entry = entry;
        entry = entry->next;
    }

    if (entry) {
        if (prev_entry) {
            prev_entry->next = entry->next;
        } else {
            table->buckets[index] = entry->next;
        }
        free(entry);
        table->count--;
    }
    pthread_rwlock_unlock(&table->rwlock);
}

void iterate_connections(ConnectionTable *table, void (*callback)(ConnectionMetadata)) {
    for (size_t i = 0; i < table->size; i++) {
        pthread_rwlock_rdlock(&table->rwlock);
        Entry *entry = table->buckets[i];

        while (entry) {
            callback(entry->metadata);
            entry = entry->next;
        }

        pthread_rwlock_unlock(&table->rwlock);
    }
}

void clear_connections(ConnectionTable *table) {
    pthread_rwlock_wrlock(&table->rwlock);
    for (size_t i = 0; i < table->size; i++) {
        Entry *entry = table->buckets[i];
        while (entry) {
            Entry *temp = entry;
            entry = entry->next;
            free(temp);
        }
        table->buckets[i] = NULL;
    }
    table->count = 0;
    pthread_rwlock_unlock(&table->rwlock);
}

void free_table(ConnectionTable *table) {
    clear_connections(table);
    free(table->buckets);
    pthread_rwlock_destroy(&table->rwlock);
    free(table);
}
```

### Key Points:
- **Hash Table with Separate Chaining**: Used for efficient insertion, deletion, and lookup.
- **Dynamic Resizing**: Implemented to handle growing number of connections while maintaining performance.
- **Read-Write Locks**: Minimize contention by allowing concurrent reads but exclusive writes.
- **Iterators and Callbacks**: Allow flexible iteration over the collection.
- **Memory Management**: Ensures all allocated memory is freed properly.

This implementation provides a balance between efficiency, usability, maintainability, and scalability. The choice of data structures and synchronization mechanisms are justified based on expected workload characteristics, ensuring optimal performance under high-load conditions.']

['Below is a C implementation that meets your requirements for managing a dynamic list of `TID_MGMT_REQUEST_PDU_T` structures with thread safety, efficient resizing, and high-performance considerations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int transaction_id;
    char source_ip[16];
    char destination_ip[16];
    int priority_level;
} TID_MGMT_REQUEST_PDU_T;

typedef struct Node {
    TID_MGMT_REQUEST_PDU_T data;
    struct Node *next;
    struct Node *prev;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    size_t count;
    pthread_rwlock_t rwlock;
} TID_List;

TID_List* create_list() {
    TID_List *list = malloc(sizeof(TID_List));
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_rwlock_init(&list->rwlock, NULL);
    return list;
}

void destroy_list(TID_List *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

int insert_node(TID_List *list, TID_MGMT_REQUEST_PDU_T data) {
    if (list->count >= MAX_ELEMENTS) return -1;

    pthread_rwlock_wrlock(&list->rwlock);

    Node *new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_rwlock_unlock(&list->rwlock);
    return 0;
}

int remove_node(TID_List *list, int transaction_id) {
    pthread_rwlock_wrlock(&list->rwlock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->data.transaction_id == transaction_id) {
            if (current->prev != NULL) current->prev->next = current->next;
            else list->head = current->next;

            if (current->next != NULL) current->next->prev = current->prev;
            else list->tail = current->prev;

            free(current);
            list->count--;
            pthread_rwlock_unlock(&list->rwlock);
            return 0;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);
    return -1;
}

void iterate_forward(TID_List *list, void (*callback)(TID_MGMT_REQUEST_PDU_T)) {
    pthread_rwlock_rdlock(&list->rwlock);

    Node *current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

void iterate_reverse(TID_List *list, void (*callback)(TID_MGMT_REQUEST_PDU_T)) {
    pthread_rwlock_rdlock(&list->rwlock);

    Node *current = list->tail;
    while (current != NULL) {
        callback(current->data);
        current = current->prev;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

void print_pdu(TID_MGMT_REQUEST_PDU_T pdu) {
    printf("Transaction ID: %d, Source IP: %s, Destination IP: %s, Priority: %d\n",
           pdu.transaction_id, pdu.source_ip, pdu.destination_ip, pdu.priority_level);
}

// Example usage
int main() {
    TID_List *list = create_list();

    TID_MGMT_REQUEST_PDU_T pdu1 = {1, "192.168.0.1", "10.0.0.1", 5};
    insert_node(list, pdu1);

    iterate_forward(list, print_pdu);
    remove_node(list, 1);

    destroy_list(list);
    return 0;
}
```

### Key Considerations:
- **Data Structure**: A doubly linked list is used for efficient insertion and deletion operations. It allows traversal in both directions.
- **Synchronization**: `pthread_rwlock_t` is used to allow multiple readers or a single writer, reducing lock contention.
- **Memory Management**: Dynamic allocation ensures that memory usage scales with the number of elements, but care is taken to avoid exceeding 10,000 elements.
- **Concurrency**: The use of read-write locks allows for concurrent access while maintaining data integrity.
- **Scalability and Performance**: The list supports efficient iteration and modification operations, which are critical under heavy load conditions.

This implementation provides a balance between performance, concurrency, and memory usage, making it suitable for high-load environments.']

