    pthread_mutex_lock(&rnti_cache.lock);

    // Check if there's an available cached RNTI
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (rnti_cache.rnti[i] == 0) { // Assume 0 means unused slot
