['```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <stdio.h>

#define MAX_RNTI 65535 // Example maximum limit for RNTI values

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int successful_operations;
    int failed_operations;
    unsigned long random_seed;
} CRC_List;

// External logging function prototype
void log_message(const char* message);

CRC_List* create_list(unsigned long seed) {
    CRC_List* list = (CRC_List*)malloc(sizeof(CRC_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->successful_operations = 0;
    list->failed_operations = 0;
    list->random_seed = seed;

    return list;
}

void destroy_list(CRC_List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int validate_rnti(unsigned short rnti) {
    return rnti <= MAX_RNTI;
}

void add_pdu(CRC_List* list, unsigned long rx_ue_info_tag, unsigned short rnti) {
    if (!validate_rnti(rnti)) {
        log_message("Failed: Invalid RNTI value.");
        pthread_mutex_lock(&list->lock);
        list->failed_operations++;
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Failed: Memory allocation error.");
        pthread_mutex_lock(&list->lock);
        list->failed_operations++;
        pthread_mutex_unlock(&list->lock);
        return;
    }

    srand(list->random_seed + rnti); // Seed with RNTI for variance
    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.RNTI = rnti;
    new_node->data.crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    log_message("Success: PDU added.");
    pthread_mutex_lock(&list->lock);
    list->successful_operations++;
    pthread_mutex_unlock(&list->lock);
}

void print_statistics(CRC_List* list) {
    pthread_mutex_lock(&list->lock);
    printf("Successful operations: %d\n", list->successful_operations);
    printf("Failed operations: %d\n", list->failed_operations);
    pthread_mutex_unlock(&list->lock);
}
