        return NULL;
    }

    // Allocate memory for CRC indication structures
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(fetched_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate memory for PDU array");
        free(ue_info);
        return NULL;
    }

    // Populate PDU structures and ensure unique RNTI values
    int seen_rnti[100] = {0}; // Assuming maximum RNTI value is 99
    size_t valid_count = 0;

    for (size_t i = 0; i < fetched_count; ++i) {
        if (!seen_rnti[ue_info[i].rnti]) {
            seen_rnti[ue_info[i].rnti] = 1;
            pdu[valid_count].RX_UE_INFORMATION_TAG = ue_info[i].ue_info_tag;
            pdu[valid_count].RNTI = ue_info[i].rnti;
            pdu[valid_count].CRC_INDICATION_REL8_TAG = ue_info[i].crc_ind_rel8_tag;
            pdu[valid_count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            ++valid_count;
        }
    }

    if (valid_count < fetched_count) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = realloc(pdu, valid_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            perror("Failed to reallocate memory for PDU array");
            free(pdu);
            free(ue_info);
            return NULL;
        }
        pdu = new_pdu;
    }

    // Set up encryption using DES algorithm
    const EVP_CIPHER *cipher_type = EVP_des_ede3_cbc(); // Example: Triple DES in CBC mode
    if (!EVP_CipherInit_ex(*cipher_ctx, cipher_type, NULL, NULL, NULL, 1)) {
        perror("Failed to initialize encryption context");
        free(pdu);
        free(ue_info);
        return NULL;
    }

    // Return the allocated and prepared PDU array
    free(ue_info); // Free the temporary UE information memory
    return pdu;
}

