        if (rxTagSource == NULL || strlen(rxTagSource) != sizeof(pduArray[i].RX_UE_INFORMATION_TAG)) {
            strncpy((char*)pduArray[i].RX_UE_INFORMATION_TAG, DEFAULT_RX_TAG, sizeof(pduArray[i].RX_UE_INFORMATION_TAG));
