// Log message function with flexibility to log to console or file.
void logMessage(const char* format, ...) {
    FILE *logOutput = fopen(LOG_FILE, "a");
    if (!logOutput) {
        // If file logging fails, fallback to console logging
        logOutput = stdout;
    }

    va_list args;
    va_start(args, format);
    vfprintf(logOutput, format, args);
    va_end(args);

    if (logOutput != stdout) {
        fclose(logOutput);
    }
}

// Function to free the allocated memory for the array.
