int generate_random_rnti(uint32_t *rnti) {
    pthread_mutex_lock(&mutex);
    do {
        *rnti = rand() % (MAX_RNTI + 1);
    } while (*rnti == 0); // Assuming RNTI zero is not valid
    pthread_mutex_unlock(&mutex);
    return 0;
}

int validate_crc_flag(uint8_t crc_flag) {
    return (crc_flag == 0 || crc_flag == 1); // Example validation
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_list(size_t n, size_t *actual_count) {
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list) return NULL;

    uint32_t used_rntis[MAX_RNTI + 1] = {0};

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle allocation failure
            for (size_t j = 0; j < i; ++j) free(list[j]);
            free(list);
            *actual_count = 0;
            return NULL;
        }

        do {
            generate_random_rnti(&pdu->rnti);
        } while (used_rntis[pdu->rnti]);

        pthread_mutex_lock(&mutex);
        used_rntis[pdu->rnti] = 1;
        pthread_mutex_unlock(&mutex);

        pdu->rx_ue_information_tag.rnti = pdu->rnti; // Example initialization
        do {
            pdu->crc_indication_rel8_tag.crc_flag = rand() % 2;
        } while (!validate_crc_flag(pdu->crc_indication_rel8_tag.crc_flag));

        list[i] = pdu;
    }

    *actual_count = n;
    return list;
}

void free_nfa_pi_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (list[i]) free(list[i]);
    }
    free(list);
}
