Config load_config_from_xml(const char* filename) {
    xmlDoc *doc = NULL;
    xmlNode *root_element = NULL;
    Config config = {0, 0, 0, 0.0};

    doc = xmlReadFile(filename, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse configuration file\n");
        return config;
    }

    root_element = xmlDocGetRootElement(doc);

    for (xmlNode *node = root_element->children; node; node = node->next) {
        if (node->type == XML_ELEMENT_NODE) {
            if (strcmp((char *)node->name, "tile_size") == 0)
                config.tile_size = atoi((const char *)xmlNodeGetContent(node));
            else if (strcmp((char *)node->name, "world_width") == 0)
                config.world_width = atoi((const char *)xmlNodeGetContent(node));
            else if (strcmp((char *)node->name, "world_height") == 0)
                config.world_height = atoi((const char *)xmlNodeGetContent(node));
            else if (strcmp((char *)node->name, "camera_speed") == 0)
                config.camera_speed = atof((const char *)xmlNodeGetContent(node));
        }
    }

    xmlFreeDoc(doc);
    return config;
}

