    for (int i = 0; i < count; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand(); // Example tag generation
        pdu_list[i].RNTI = rand() % 10000; // Random RNTI

        if (camera_speed > 5.0f) { // High-speed bias logic
            pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 10 == 0);
        } else {
            pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 1);
        }
    }

    *actual_count = count;
    return pdu_list;
}

void check_for_xml_updates(const char* filename, Config* config) {
    static time_t last_mod_time = 0;

    struct stat file_stat;
    if (stat(filename, &file_stat) < 0) {
        fprintf(stderr, "Failed to get file status\n");
        return;
    }

    if (file_stat.st_mtime > last_mod_time) {
        *config = load_config_from_xml(filename);
        last_mod_time = file_stat.st_mtime;
    }
}

void handle_configuration(const char* config_file) {
