#define MAX_STRUCTS 10000
#define MEMORY_LIMIT (50 * 1024 * 1024) // 50MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

// Function to log statistics
void log_statistics(const char* message) {
    // Simulate logging to an external source
    printf("LOG: %s\n", message);
}

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        log_statistics("Failed allocation for DynamicList");
        return NULL;
    }

    list->data = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int add_to_list(DynamicList* list) {
    if (!list) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&list->mutex);
        log_statistics("Failed to add: List is full");
        return -1;
    }

    size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count + 1);

    if ((required_memory + list->data ? sizeof(NFAPI_CRC_INDICATION_PDU_T) : 0) > MEMORY_LIMIT) {
        pthread_mutex_unlock(&list->mutex);
        log_statistics("Failed to add: Memory limit exceeded");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(
        list->data, required_memory);

    if (!new_data) {
        pthread_mutex_unlock(&list->mutex);
        log_statistics("Failed allocation for new data");
        return -1;
    }

    list->data = new_data;

    NFAPI_CRC_INDICATION_PDU_T* last_element = &list->data[list->count++];
    last_element->RX_UE_INFORMATION_TAG = rand(); // Random value
    last_element->RNTI = rand();
    last_element->CRC_INDICATION_REL8_TAG = rand() % 256;
    last_element->CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

    pthread_mutex_unlock(&list->mutex);

    log_statistics("Successfully added a new element");

    return 0;
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    free(list->data);
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    DynamicList* list = create_dynamic_list();
    if (!list) return EXIT_FAILURE;

    for (int i = 0; i < MAX_STRUCTS + 5; ++i) { // Attempt to add more than max
        if (add_to_list(list) == -1) {
            printf("Addition failed at index %d\n", i);
        }
    }

    destroy_dynamic_list(list);

    return EXIT_SUCCESS;
}
