```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

// Constants for RNTI validation range
#define MIN_RNTI 0x0001
#define MAX_RNTI 0x7FFF

// Structure definitions
typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    uint32_t timestamp; // High-resolution timestamp
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *indicationList;
    size_t listSize;
} IndicationListResult;

// Thread-safe logging mechanism
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void threadSafeLog(const char *message) {
    pthread_mutex_lock(&logMutex);
    FILE *logFile = fopen("crc_log.txt", "a");
    if (logFile) {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);
    }
    pthread_mutex_unlock(&logMutex);
}

// Function to generate a high-resolution timestamp
uint32_t getHighResolutionTimestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint32_t)ts.tv_sec * 1000 + ts.tv_nsec / 1e6; // Convert to milliseconds
}

// Shuffle function for list shuffling
void shuffleArray(void *array, size_t nItems, size_t itemSize) {
    if (nItems > 1) {
        for (size_t i = nItems - 1; i > 0; --i) {
            size_t j = rand() % (i + 1);
            void *temp = malloc(itemSize);
            memcpy(temp, (char *)array + i * itemSize, itemSize);
            memcpy((char *)array + i * itemSize, (char *)array + j * itemSize, itemSize);
            memcpy((char *)array + j * itemSize, temp, itemSize);
            free(temp);
        }
    }
}

// Main function to populate the NFAPI_CRC_INDICATION_PDU_T list
IndicationListResult* populateNfarlcIndicationList(size_t count, int enableCrcFlag) {
    pthread_mutex_t allocMutex = PTHREAD_MUTEX_INITIALIZER;
    IndicationListResult *result = malloc(sizeof(IndicationListResult));
    if (!result) {
        threadSafeLog("Memory allocation for result structure failed.");
        return NULL;
    }

    result->indicationList = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result->indicationList) {
        free(result);
        threadSafeLog("Memory allocation for indication list failed.");
        return NULL;
    }

    pthread_mutex_lock(&allocMutex);
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *indication = &result->indicationList[i];

        // Generate RNTI within valid range
        uint16_t rnti = (rand() % (MAX_RNTI - MIN_RNTI + 1)) + MIN_RNTI;

        if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
            threadSafeLog("RNTI value out of range. Skipping entry.");
            continue;
        }

        // Set CRCFLAG based on enableCrcFlag
        indication->crcIndicationRel8Tag.CRCFLAG = enableCrcFlag ? (rand() % 2) : 0;

        // Set high-resolution timestamp
        indication->timestamp = getHighResolutionTimestamp();

        // Log the creation of each structure
        char logMessage[128];
        snprintf(logMessage, sizeof(logMessage), "Created NFAPI_CRC_INDICATION_PDU_T with RNTI: %u, CRCFLAG: %u", rnti, indication->crcIndicationRel8Tag.CRCFLAG);
        threadSafeLog(logMessage);
    }
    pthread_mutex_unlock(&allocMutex);

    // Shuffle the list to simulate random order
    shuffleArray(result->indicationList, count, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    result->listSize = count; // Actual size might be less if some entries were skipped

    return result;
}

// Function to free the allocated memory for the indication list
void freeIndicationList(IndicationListResult *result) {
    if (result) {
        free(result->indicationList);
        free(result);
    }
}
```

