['Below is a C implementation of a dynamic list manager for `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe operations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CAPACITY 1500

typedef struct {
    unsigned int CRCFLAG; // Randomly set CRC flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    char RNTI[16]; // Example length for RNTI
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    unsigned int rnti; // Assuming RNTI is stored as an integer for simplicity
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || list->size >= MAX_CAPACITY) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if (strcmp((*current)->data.ue_info.RNTI, element.ue_info.RNTI) == 0 &&
            (*current)->data.rnti == element.rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RNTI
        }
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    *current = new_node;
    new_node->data = element;
    new_node->next = NULL;

    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element(DynamicList* list, const char* rnti) {
    if (!list || !rnti) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if (strcmp((*current)->data.ue_info.RNTI, rnti) == 0) {
            Node* to_remove = *current;
            *current = (*current)->next;
            free(to_remove);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -2; // Not found
}

void iterate_list(DynamicList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int verify_list_integrity(DynamicList* list) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.crc_tag.CRCFLAG < 0 || 
            (*current)->data.crc_tag.CRCFLAG > 1) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Invalid CRCFLAG
        }

        Node** checker = &list->head;
        while (*checker && *checker != *current) {
            if (strcmp((*checker)->data.ue_info.RNTI, (*current)->data.ue_info.RNTI) == 0 &&
                (*checker)->data.rnti == (*current)->data.rnti) {
                pthread_mutex_unlock(&list->lock);
                return -3; // Duplicate RNTI found
            }
            checker = &(*checker)->next;
        }

        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void example_callback(NFAPI_CRC_INDICATION_PDU_T element) {
    printf("RNTI: %u, CRCFLAG: %u\n", element.rnti, element.crc_tag.CRCFLAG);
}
```

### Key Points:
- **Thread Safety**: The list uses a mutex to ensure thread-safe operations.
- **Memory Management**: Dynamic allocation and deallocation are handled carefully.
- **Duplicate Handling**: Duplicates are checked before adding new elements.
- **Integrity Verification**: Functionality is provided to verify the integrity of the list, checking for duplicates and valid CRCFLAG values.
- **Iteration**: A callback mechanism allows iteration over the list.']

