// Priority structure for priority queue
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int priority;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

PriorityQueue* create_priority_queue() {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
    return pq;
}

void enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->priority = priority;

    pthread_mutex_lock(&pq->lock);
    if (!pq->head || pq->head->priority < priority) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next && current->next->priority >= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&pq->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);
    if (!pq->head) {
        pthread_mutex_unlock(&pq->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0}; // Return an empty structure
    }
    Node* temp = pq->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    pq->head = pq->head->next;
    free(temp);
    pthread_mutex_unlock(&pq->lock);
    return data;
