// Define an AngularJS module for managing NFAPI CRC indication messages
angular.module('NFAPIManager', [])
  .service('CRCService', function($http) {
    const crcMessages = new Map();

    // Load initial CRC messages, potentially from a data source
    this.loadInitialData = async () => {
      try {
        const response = await $http.get('/api/crc-messages');
        response.data.forEach(message => crcMessages.set(message.id, message));
      } catch (error) {
        console.error('Error loading CRC messages:', error);
      }
    };

    // Validate CRC flags against reference values
    this.validateCRCFlag = async (id) => {
      try {
        const response = await $http.get(`/api/validate-crc/${id}`);
        const isValid = response.data.isValid;
        const message = crcMessages.get(id);

        if (message) {
          message.crcValidated = isValid;
        }

        return isValid;
      } catch (error) {
        console.error('Error validating CRC:', error);
        return false;
      }
    };

    // Retrieve a CRC message by ID
    this.getCRCMessageById = (id) => crcMessages.get(id);

    // Add or update a CRC indication message
    this.updateCRCMessage = (message) => crcMessages.set(message.id, message);
  })
  .controller('DialogController', function($scope, $timeout, CRCService, fieldIdentifiers) {
    let pendingUpdates = new Set();

    const refreshFields = async () => {
      const fieldsToRefresh = [];

      // Identify dialog fields matching predefined identifiers
      Object.keys($scope.dialogFields).forEach(fieldId => {
        if (fieldIdentifiers.includes(fieldId)) {
          fieldsToRefresh.push(fieldId);
        }
      });

      for (const fieldId of fieldsToRefresh) {
        const message = CRCService.getCRCMessageById(fieldId);

        if (message && !pendingUpdates.has(fieldId)) {
          pendingUpdates.add(fieldId);

          const isValid = await CRCService.validateCRCFlag(message.id);

          // Handle potential race conditions
          $timeout(() => {
            $scope.dialogFields[fieldId].crcStatus = isValid;
            pendingUpdates.delete(fieldId);
          });
        }
      }

      $timeout(refreshFields, 100); // Adjust timeout as necessary for performance
    };

    refreshFields(); // Start refreshing fields

    $scope.addFieldType = (newIdentifier) => {
      fieldIdentifiers.push(newIdentifier);
    };
  })
  .directive('crcField', function() {
    return {
      restrict: 'A',
      link: function(scope, element, attrs) {
        scope.$watch(attrs.crcField, function(newValue) {
          if (newValue !== undefined) {
            element.css({
              backgroundColor: newValue ? 'green' : 'red'
            });
          }
        }, true);
      }
    };
  });

// Example usage in HTML
