    UserConnectionList* list = (UserConnectionList*)malloc(sizeof(UserConnectionList));
    if (!list) {
        log_message("Memory allocation failed for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_duplicate(UserConnectionList* list, const char* user_id) {
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->record.USER_ID, user_id) == 0) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

int add_user_connection(UserConnectionList* list, USER_CONNECTION_RECORD new_record) {
    pthread_mutex_lock(&list->lock);

    if (is_duplicate(list, new_record.USER_ID)) {
        log_message("Duplicate USER_ID detected");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for new node");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }
    memcpy(&new_node->record, &new_record, sizeof(USER_CONNECTION_RECORD));
    new_node->next = list->head;
    list->head = new_node;

    log_message("User connection added");

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_user_connection(UserConnectionList* list, const char* user_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (strcmp(current->record.USER_ID, user_id) == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            log_message("User connection removed");
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    log_message("USER_ID not found for removal");
    pthread_mutex_unlock(&list->lock);
    return -1;
}

void check_for_leaks(UserConnectionList* list) {
