typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    time_t timestamp;
    unsigned int source_id;
    size_t data_length;
    void* payload;
} DATA_FRAME_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Simulate external data source availability
int is_data_source_available() {
    // Randomly simulate data source availability
    return rand() % 2;
}

void* fetch_payload(size_t length) {
    if (is_data_source_available()) {
        void* payload = malloc(length);
        if (payload) {
            memset(payload, rand() % 256, length); // Simulate valid data
            return payload;
        }
    }
    return NULL; // Fallback: no data available
}

int validate_payload(void* payload, size_t length) {
    // Simple checksum validation for demonstration
    unsigned char* p = (unsigned char*)payload;
    unsigned int sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += p[i];
    }
    return sum % 256 == 0;
}

void processUEIndications(NFAPI_CRC_INDICATION_PDU_T* indications, size_t num_ues,
                          DATA_FRAME_T* data_frames, size_t num_data_frames) {
    pthread_t threads[num_ues + num_data_frames];
    int thread_count = 0;

    // Process UE Indications
    for (size_t i = 0; i < num_ues; ++i) {
        pthread_create(&threads[thread_count++], NULL, (void*)[](void* arg) -> void* {
            NFAPI_CRC_INDICATION_PDU_T* indication = (NFAPI_CRC_INDICATION_PDU_T*)arg;
            pthread_mutex_lock(&lock);
            indication->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            pthread_mutex_unlock(&lock);
            return NULL;
        }, &indications[i]);
    }

    // Process Data Frames
    for (size_t i = 0; i < num_data_frames; ++i) {
        pthread_create(&threads[thread_count++], NULL, (void*)[](void* arg) -> void* {
            DATA_FRAME_T* frame = (DATA_FRAME_T*)arg;
            pthread_mutex_lock(&lock);
            frame->timestamp = time(NULL);
            frame->source_id = rand() % 1000;

            frame->payload = fetch_payload(frame->data_length);
            if (!frame->payload) {
                // Fallback: use default payload
                size_t default_length = 10;
                frame->payload = malloc(default_length);
                if (frame->payload) {
                    memset(frame->payload, 0, default_length);
                } else {
                    fprintf(stderr, "Failed to allocate memory for fallback payload\n");
                }
            }

            // Validate payload
            if (!validate_payload(frame->payload, frame->data_length)) {
                fprintf(stderr, "Payload validation failed\n");
                free(frame->payload);
                frame->payload = NULL;
            }
            pthread_mutex_unlock(&lock);
            return NULL;
        }, &data_frames[i]);
    }

    // Join threads
    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    for (size_t i = 0; i < num_data_frames; ++i) {
        if (data_frames[i].payload) {
            free(data_frames[i].payload);
        }
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t num_ues = 10;
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        fprintf(stderr, "Failed to allocate memory for indications\n");
        return EXIT_FAILURE;
    }

    size_t num_data_frames = 5;
    DATA_FRAME_T* data_frames = malloc(num_data_frames * sizeof(DATA_FRAME_T));
    if (!data_frames) {
        free(indications);
        fprintf(stderr, "Failed to allocate memory for data frames\n");
        return EXIT_FAILURE;
    }

    // Initialize data frames with random lengths
    for (size_t i = 0; i < num_data_frames; ++i) {
        data_frames[i].data_length = rand() % 100 + 1; // Random length between 1 and 100
    }

    processUEIndications(indications, num_ues, data_frames, num_data_frames);

    free(indications);
    free(data_frames);

    return EXIT_SUCCESS;
}
