} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    uint32_t fcs; // Frame Check Sequence
} MAC_PDU;

typedef struct {
    MAC_PDU *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    size_t total_bytes_allocated;
} MAC_PDU_Array;

// Mock checksum calculation function
uint32_t calculate_fcs(const uint8_t *data, size_t length) {
    // Simple placeholder checksum computation
    uint32_t fcs = 0;
    for (size_t i = 0; i < length; ++i) {
        fcs += data[i];
    }
    return fcs;
}

int validate_fcs(const MAC_PDU *pdu) {
    uint32_t computed_fcs = calculate_fcs(pdu->payload.data, pdu->header.length);
    return (computed_fcs == pdu->fcs);
}

void initialize_mac_pdu_array(MAC_PDU_Array *array) {
    array->array = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->total_bytes_allocated = 0;
}

int resize_mac_pdu_array(MAC_PDU_Array *array, size_t new_capacity) {
    MAC_PDU *new_array = realloc(array->array, new_capacity * sizeof(MAC_PDU));
    if (!new_array) return -1;

    memset(new_array + array->capacity, 0, (new_capacity - array->capacity) * sizeof(MAC_PDU));
    array->array = new_array;
    array->capacity = new_capacity;
    return 0;
}

int add_mac_pdu_segment(MAC_PDU_Array *array, const uint8_t *payload_data, size_t payload_length) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        if (resize_mac_pdu_array(array, array->capacity ? array->capacity * 2 : 1)) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    MAC_PDU *pdu = &array->array[array->count];
    size_t remaining_length = payload_length;

    while (remaining_length > 0) {
        size_t segment_size = (remaining_length > MAX_FRAME_SIZE) ? MAX_FRAME_SIZE : remaining_length;

        pdu->header.length = segment_size;
        pdu->payload.data = malloc(segment_size);
        if (!pdu->payload.data) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        memcpy(pdu->payload.data, payload_data + (payload_length - remaining_length), segment_size);
        pdu->fcs = calculate_fcs(pdu->payload.data, segment_size);

        array->total_bytes_allocated += sizeof(MAC_PDU) + segment_size;

        if (!validate_fcs(pdu)) {
            free(pdu->payload.data);
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        ++array->count;
        pdu = &array->array[array->count];

        remaining_length -= segment_size;
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_mac_pdu_array(MAC_PDU_Array *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].payload.data) {
            free(array->array[i].payload.data);
        }
    }

    free(array->array);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);

    array->array = NULL;
    array->count = 0;
    array->capacity = 0;
    array->total_bytes_allocated = 0;
}
