    MAC_PDU *new_array = (MAC_PDU *)realloc(mac_pdu_array->array, new_capacity * sizeof(MAC_PDU));
    if (new_array) {
        mac_pdu_array->array = new_array;
        mac_pdu_array->capacity = new_capacity;
    }
