// Add a frame to the dynamic array
int add_mac_pdu_frame(MAC_PDU_Array *mac_pdu_array, const uint8_t *payload_data, size_t payload_length, uint16_t frame_type) {
    pthread_mutex_lock(&mac_pdu_array->lock);

    if (mac_pdu_array->count == mac_pdu_array->capacity) {
        resize_mac_pdu_array(mac_pdu_array);
    }

    MAC_PDU &new_pdu = mac_pdu_array->array[mac_pdu_array->count];
    new_pdu.header.frame_type = frame_type;

    size_t max_frame_size;
    switch (frame_type) {
        case FRAME_TYPE_CONTROL:  max_frame_size = MAX_FRAME_SIZE_CONTROL; break;
        case FRAME_TYPE_DATA:     max_frame_size = MAX_FRAME_SIZE_DATA;    break;
        case FRAME_TYPE_MANAGEMENT: max_frame_size = MAX_FRAME_SIZE_MANAGEMENT; break;
        default: return -1; // Invalid frame type
    }

    size_t remaining_length = payload_length;
    while (remaining_length > 0) {
        size_t segment_length = remaining_length < max_frame_size ? remaining_length : max_frame_size;

        new_pdu.payload.data = (uint8_t *)malloc(segment_length);
        if (!new_pdu.payload.data) {
            pthread_mutex_unlock(&mac_pdu_array->lock);
            return -1; // Memory allocation failed
        }
        memcpy(new_pdu.payload.data, payload_data, segment_length);

        new_pdu.payload.length = segment_length;
        uint32_t checksum = calculate_checksum(new_pdu.payload.data, segment_length);
        if (checksum != 0) { // Assuming non-zero indicates an invalid checksum for illustration purposes
            free(new_pdu.payload.data);
            pthread_mutex_unlock(&mac_pdu_array->lock);
            return -1; // Checksum validation failed
        }

        mac_pdu_array->count++;
        payload_data += segment_length;
        remaining_length -= segment_length;

        if (remaining_length > 0) {
            resize_mac_pdu_array(mac_pdu_array); // Ensure enough space for the next frame
