    uint8_t *payload;
    size_t payload_len;
} MAC_PDU;

typedef struct {
    MAC_PDU **pdus;
    size_t count;
    pthread_mutex_t mutex;
    atomic_size_t total_bytes_allocated; // Requires C11 or GCC extension for atomic
} DynamicArray;

// Retry mechanism with exponential backoff
int retry_with_backoff(void (*operation)(void), int max_retries, unsigned int initial_backoff_ms) {
    int attempt = 0;
    while (attempt < max_retries) {
        operation();
        if (/* operation was successful */) return 0; // Replace with actual success condition

        sleep_ms(initial_backoff_ms * (1 << attempt)); // Exponential backoff
        ++attempt;
    }
    return -1;
}

// Helper to simulate delay, replace with a proper implementation.
void sleep_ms(unsigned int ms) {
    struct timespec req = {0};
    req.tv_sec = ms / 1000;
    req.tv_nsec = (ms % 1000) * 1000000L;
    nanosleep(&req, NULL);
}

// Initialize dynamic array for MAC_PDUs
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->mutex, NULL);
    array->pdus = calloc(initial_capacity, sizeof(MAC_PDU*));
    if (!array->pdus) {
        free(array);
        return NULL;
    }
    array->count = 0;
    atomic_store(&array->total_bytes_allocated, 0);

    return array;
}

// Function to segment payload into frames and store them
int segment_payload_and_store(DynamicArray *array, const uint8_t *payload, size_t payload_len, size_t max_frame_size) {
    pthread_mutex_lock(&array->mutex);

    // Check available space and handle fragmentation
    if (/* insufficient buffer condition */) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Error due to insufficient buffer space
    }

    size_t frames = (payload_len + max_frame_size - 1) / max_frame_size;
    for (size_t i = 0; i < frames; ++i) {
        size_t frame_payload_size = (i == frames - 1) ? (payload_len % max_frame_size) : max_frame_size;

        MAC_PDU *pdu = malloc(sizeof(MAC_PDU));
        if (!pdu) {
            pthread_mutex_unlock(&array->mutex);
            return -2; // Memory allocation failure
        }

        memset(pdu, 0, sizeof(MAC_PDU)); // Initialize header and allocate payload memory
        pdu->payload = malloc(frame_payload_size);
        if (!pdu->payload) {
            free(pdu);
            pthread_mutex_unlock(&array->mutex);
            return -2; // Memory allocation failure for payload
        }

        memcpy(pdu->payload, &payload[i * max_frame_size], frame_payload_size);
        pdu->payload_len = frame_payload_size;

        array->pdus[array->count++] = pdu;
        atomic_fetch_add(&array->total_bytes_allocated, sizeof(MAC_PDU) + frame_payload_size);

        // Logging
        printf("Frame %zu: Allocated memory for payload of size %zu\n", i, frame_payload_size);
    }

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Cleanup function to free dynamic array resources
void cleanup_dynamic_array(DynamicArray *array) {
    if (!array) return;

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i]->payload);
        free(array->pdus[i]);
    }

    free(array->pdus);
    atomic_store(&array->total_bytes_allocated, 0); // Reset total bytes allocated
    pthread_mutex_unlock(&array->mutex);

    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int main() {
    size_t max_frame_size = 128; // Example frame size

    DynamicArray *array = init_dynamic_array(10);
    if (!array) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    const uint8_t example_payload[] = { /* Some payload data */ };
    int status = segment_payload_and_store(array, example_payload, sizeof(example_payload), max_frame_size);
    if (status != 0) {
        fprintf(stderr, "Failed to segment and store payload\n");
        cleanup_dynamic_array(array);
        return EXIT_FAILURE;
    }

    // Perform other operations...

    cleanup_dynamic_array(array);
    return EXIT_SUCCESS;
}
