['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char* payload;
} DataPacket;

#define MAX_PACKETS 1000

DataPacket* packets[MAX_PACKETS];
int num_packets = 0;

void generate_pseudo_random_data(char *buffer, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        buffer[i] = rand() % 256;
    }
}

void initialize_packets(int count, int payload_size, unsigned int expiration_interval, const char* data_pattern) {
    srand(time(NULL));
    time_t current_time = time(NULL);

    for (int i = 0; i < count && num_packets < MAX_PACKETS; ++i) {
        DataPacket *packet = malloc(sizeof(DataPacket));
        if (!packet) break;

        packet->packet_id = rand() % 100000;
        packet->timestamp = current_time + (rand() % expiration_interval);
        packet->payload_size = payload_size;
        packet->payload = malloc(payload_size);

        if (packet->payload) {
            generate_pseudo_random_data(packet->payload, payload_size);
            packets[num_packets++] = packet;
        } else {
            free(packet);
        }
    }
}

void expire_packets(unsigned int expiration_interval) {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_packets;) {
        if (current_time - packets[i]->timestamp > expiration_interval) {
            free(packets[i]->payload);
            free(packets[i]);
            packets[i] = packets[--num_packets];
        } else {
            ++i;
        }
    }
}

void filter_packets(time_t min_timestamp, time_t max_timestamp, size_t min_payload_size) {
    for (int i = 0; i < num_packets;) {
        if ((packets[i]->timestamp < min_timestamp || packets[i]->timestamp > max_timestamp) ||
            packets[i]->payload_size < min_payload_size) {

            free(packets[i]->payload);
            free(packets[i]);
            packets[i] = packets[--num_packets];
        } else {
            ++i;
        }
    }
}

void cleanup() {
    for (int i = 0; i < num_packets; ++i) {
        free(packets[i]->payload);
        free(packets[i]);
    }
    num_packets = 0;
}
