#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    uint32_t RNTI;
    // Other members...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t CRCFLAG; // Assume this is a simple flag for demonstration
    // Other members...
