typedef struct {
    RX_UE_INFORMATION_TAG ueInformationTag;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

int generateUniqueRN(int *usedRNTIs, int size) {
    int rnti = rand() % (0x7FFF - 1) + 1; // RNTI range: [1, 32767]
    for (int i = 0; i < size; ++i) {
        if (usedRNTIs[i] == rnti) return generateUniqueRN(usedRNTIs, size);
    }
    return rnti;
}

NFAPI_CRC_INDICATION_PDU_T* populateNFAPICRCList(int n, unsigned int seed) {
    if (n > MAX_LIST_SIZE || n <= 0) return NULL;

    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int usedRNTIs[MAX_LIST_SIZE] = {0};

    for (int i = 0; i < n; ++i) {
        list[i].ueInformationTag.RNTI = generateUniqueRN(usedRNTIs, i);
        usedRNTIs[i] = list[i].ueInformationTag.RNTI;

        list[i].RNTI = list[i].ueInformationTag.RNTI;

        // Simulating delay from external sources
        struct timespec ts = {0};
        ts.tv_sec = 1; // 1 second for demonstration
        nanosleep(&ts, NULL);

        list[i].crcIndicationRel8Tag.CRCFLAG = rand() % 2;
    }

    return list;
}

void freeNFAPICRCList(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        free(list);
    }
}
```

