#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char UID[64];
    char IP[16];
    time_t lastActive;
} ConnectionStatus;

typedef struct Node {
    ConnectionStatus data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
} ConnectionList;

ConnectionList* createConnectionList() {
    ConnectionList* list = (ConnectionList*)malloc(sizeof(ConnectionList));
    list->head = NULL;
    list->size = 0;
    return list;
}

Node* findNode(ConnectionList* list, const char* UID) {
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->data.UID, UID) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void addOrUpdateConnection(ConnectionList* list, const char* UID, const char* IP, time_t lastActive) {
    Node* existingNode = findNode(list, UID);
    if (existingNode == NULL) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        strcpy(newNode->data.UID, UID);
        strcpy(newNode->data.IP, IP);
        newNode->data.lastActive = lastActive;
        newNode->next = list->head;
        list->head = newNode;
        list->size++;
    } else {
        existingNode->data.lastActive = lastActive;
        strcpy(existingNode->data.IP, IP);
    }
}

void removeConnection(ConnectionList* list, const char* UID) {
    Node *current = list->head, *prev = NULL;
    while (current != NULL && strcmp(current->data.UID, UID) != 0) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) return;

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;
}

void filterConnections(ConnectionList* list, time_t startTime, time_t endTime, void (*callback)(ConnectionStatus*)) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.lastActive >= startTime && current->data.lastActive <= endTime) {
            callback(&current->data);
        }
        current = current->next;
    }
}

void freeConnectionList(ConnectionList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

// Example callback function
void printConnectionStatus(ConnectionStatus* status) {
    printf("UID: %s, IP: %s, Last Active: %ld\n", status->UID, status->IP, status->lastActive);
}

int main() {
    ConnectionList* list = createConnectionList();

    // Example usage
    addOrUpdateConnection(list, "user123", "192.168.1.1", time(NULL));
    filterConnections(list, time(NULL) - 86400, time(NULL), printConnectionStatus);

    freeConnectionList(list);
    return 0;
}
