#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_PACKETS 1000

typedef struct {
    int id;
    time_t timestamp;
    size_t payload_size;
    unsigned char *payload;
    int processed;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    time_t expiration_interval;
    int verbosity;
} PacketManager;

void log_message(int verbosity, const char *message) {
    if (verbosity > 0) { // Adjust condition for verbosity levels
        printf("%s\n", message);
        // Additional file logging can be added here.
    }
}

int init_packet_manager(PacketManager *manager, size_t capacity, time_t interval, int verbosity) {
    manager->capacity = capacity;
    manager->count = 0;
    manager->expiration_interval = interval;
    manager->verbosity = verbosity;

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        log_message(1, "Mutex init failed");
        return -1;
    }

    for (size_t i = 0; i < capacity; ++i) {
        manager->packets[i] = NULL;
    }

    // Fetch initial configurations if needed
    // This could involve calling external data source API

    log_message(2, "PacketManager initialized");
    return 0;
}

int create_packet(PacketManager *manager, int id, size_t payload_size) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->packets[i]) {
            DataPacket *packet = malloc(sizeof(DataPacket));
            if (!packet) {
                log_message(1, "Memory allocation failed");
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }

            packet->id = id;
            packet->timestamp = time(NULL);
            packet->payload_size = payload_size;

            packet->payload = malloc(payload_size);
            if (!packet->payload) {
                log_message(1, "Memory allocation for payload failed");
                free(packet);
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }

            // Fill with pseudo-random data
            for (size_t j = 0; j < payload_size; ++j) {
                packet->payload[j] = rand() % 256;
            }

            packet->processed = 0;
            manager->packets[i] = packet;
            manager->count++;

            log_message(2, "Packet created");
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    // No space available
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void expire_packets(PacketManager *manager) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->packets[i]) {
            DataPacket *packet = manager->packets[i];
            if (difftime(now, packet->timestamp) >= manager->expiration_interval) {
                log_message(2, "Expiring packet");
                free(packet->payload);
                free(packet);
                manager->packets[i] = NULL;
                manager->count--;
            }
        }
    }

    // Compact the array
    size_t j = 0;
    for (size_t i = 0; i < manager->capacity && j < manager->count; ++i) {
        if (manager->packets[i]) {
            if (i != j) {
                manager->packets[j] = manager->packets[i];
                manager->packets[i] = NULL;
            }
            j++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void dynamic_config_update(PacketManager *manager, time_t new_interval, int new_verbosity) {
    pthread_mutex_lock(&manager->lock);
    manager->expiration_interval = new_interval;
    manager->verbosity = new_verbosity;
    pthread_mutex_unlock(&manager->lock);
}

void destroy_packet_manager(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->packets[i]) {
            free(manager->packets[i]->payload);
            free(manager->packets[i]);
        }
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    PacketManager manager;
    init_packet_manager(&manager, MAX_PACKETS, 60, 2); // 1-minute expiration

    create_packet(&manager, 1, 128); // Create a packet with id=1 and payload size of 128 bytes
    expire_packets(&manager);

    dynamic_config_update(&manager, 30, 1); // Update to 30-second expiration, lower verbosity

    destroy_packet_manager(&manager);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` ensures that the packet manager operations are thread-safe.
- **Memory Management**: Handles allocation failures and compacts expired packets for efficient memory usage.
- **Logging**: Supports different verbosity levels. Extendable to file logging if needed.
- **Dynamic Configuration**: Allows updates to expiration intervals and verbosity without restarting.
- **Expiration Logic**: Periodically checks and removes expired packets.

This is a foundational implementation; additional functionalities like fetching initial configurations, handling external data source interactions, and robust error handling can be layered on top. Comprehensive unit tests would also need to be developed for real-world use cases.']

