#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    unsigned int rnti;
    // Other fields as needed for RX_UE_INFORMATION_TAG
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned int crc_flag; // CRC flag value
    // Additional fields as required for REL8 tag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_STRUCTS];
    size_t count;
    pthread_mutex_t lock;
    int log_level;
    FILE* log_file;
} PoolManager;

PoolManager pool_manager;

void initialize_pool(PoolManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < MAX_STRUCTS; ++i) {
        manager->pool[i] = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(PoolManager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_STRUCTS) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        manager->pool[manager->count++] = pdu;
        pthread_mutex_unlock(&manager->lock);
        return pdu;
    } else {
        pthread_mutex_unlock(&manager->lock);
        return NULL; // Pool is full
    }
}

void free_pdu(PoolManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pool[i] == pdu) {
            free(pdu);
            memmove(&manager->pool[i], &manager->pool[i + 1], (manager->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void log_message(PoolManager *manager, int level, const char *message) {
    if (level >= manager->log_level) {
        if (manager->log_file) {
            fprintf(manager->log_file, "%s\n", message);
        } else {
            printf("%s\n", message);
        }
    }
}

void set_log_configuration(PoolManager *manager, int level, const char *file_path) {
    manager->log_level = level;
    if (file_path) {
        manager->log_file = fopen(file_path, "a");
        if (!manager->log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    } else {
        manager->log_file = NULL;
    }
}

void populate_nfa_structures(PoolManager *manager, RX_UE_INFORMATION_TAG rx_ue_info[], unsigned int rnti_array[], size_t num_entries) {
    srand(time(NULL));
    for (size_t i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(manager);
        if (pdu) {
            pdu->rx_ue_info = rx_ue_info[i];
            pdu->rnti = rnti_array[i];
            pdu->crc_ind_rel8.crc_flag = rand() % 2; // Randomly set CRC flag
            log_message(manager, LOG_LEVEL_INFO, "PDU populated successfully");
        } else {
            log_message(manager, LOG_LEVEL_ERROR, "Failed to allocate PDU - pool full or memory error");
        }
    }
}

int main() {
    initialize_pool(&pool_manager);
    set_log_configuration(&pool_manager, LOG_LEVEL_DEBUG, NULL);

    RX_UE_INFORMATION_TAG rx_ue_info[MAX_STRUCTS]; // Assume initialized elsewhere
    unsigned int rnti_array[MAX_STRUCTS];           // Assume initialized elsewhere

    populate_nfa_structures(&pool_manager, rx_ue_info, rnti_array, MAX_STRUCTS);

    pthread_mutex_destroy(&pool_manager.lock);
    if (pool_manager.log_file) {
        fclose(pool_manager.log_file);
    }

    return 0;
}
```

