#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double packet_loss_rate;
    double throughput; // in Mbps
    double latency;    // in ms
} NetworkInterfaceStats;

typedef struct {
    NetworkInterfaceStats *stats_array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicNetworkArray;

DynamicNetworkArray* create_dynamic_network_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicNetworkArray *array = malloc(sizeof(DynamicNetworkArray));
    array->stats_array = malloc(initial_capacity * sizeof(NetworkInterfaceStats));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_dynamic_network_array(DynamicNetworkArray *array) {
    if (array == NULL) return;

    pthread_mutex_destroy(&array->lock);
    free(array->stats_array);
    free(array);
}

int add_or_update_stats(DynamicNetworkArray *array, size_t index, 
                        double packet_loss_rate, double throughput, double latency) {
    if (array == NULL || index >= array->capacity) return -1;

    pthread_mutex_lock(&array->lock);

    // Expand capacity if needed
    if (index >= array->count && array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkInterfaceStats *new_array = realloc(array->stats_array, new_capacity * sizeof(NetworkInterfaceStats));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->stats_array = new_array;
        array->capacity = new_capacity;
    }

    // Add or update the stats
    if (index >= array->count) {
        array->count++;
    }
    NetworkInterfaceStats *stat = &array->stats_array[index];
    stat->packet_loss_rate = packet_loss_rate;
    stat->throughput = throughput;
    stat->latency = latency;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

double calculate_average_throughput(DynamicNetworkArray *array) {
    if (array == NULL || array->count == 0) return 0.0;

    double total_throughput = 0.0;
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        total_throughput += array->stats_array[i].throughput;
    }

    double average_throughput = total_throughput / array->count;

    pthread_mutex_unlock(&array->lock);
    return average_throughput;
}

// Example usage
int main() {
    DynamicNetworkArray *network_array = create_dynamic_network_array(4);

    add_or_update_stats(network_array, 0, 0.01, 100.5, 10.2);
    add_or_update_stats(network_array, 1, 0.02, 200.3, 15.6);

    printf("Average Throughput: %.2f Mbps\n", calculate_average_throughput(network_array));

    free_dynamic_network_array(network_array);
    return 0;
}
```

### Key Points:
