- **Concurrency**: Utilizes a mutex (`pthread_mutex_t`) for thread-safe operations on the data structure.
- **Performance and Scalability**: Optimized by doubling the capacity of the array when resizing, minimizing reallocations.
- **Edge Cases and Usability**: Handles null pointers and invalid indices gracefully. The interface is straightforward for adding/updating stats and calculating averages.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_PDU_COUNT 1000
#define ETH_HEADER_FCS_SIZE 8
#define SDU_MAX_LENGTH 127
#define PDU_MAX_SDU_TOTAL_LENGTH (1492 - ETH_HEADER_FCS_SIZE)

typedef struct {
    char data[SDU_MAX_LENGTH];
    size_t length;
} MAC_Service_Data_Unit;

typedef struct {
    uint32_t macHeader; // Placeholder for the actual header structure
    int pduType;        // Placeholder for PDU type, e.g., BCCH, PCCH, etc.
    MAC_Service_Data_Unit *sdus;
    size_t sduCount;
    size_t allocatedSdus;
    char metadata[256]; // User-defined metadata
} LTE_MAC_PDU;

typedef struct {
    LTE_MAC_PDU pdus[MAX_PDU_COUNT];
    size_t pduCount;
} PDU_Manager;

bool is_valid_sdu(const MAC_Service_Data_Unit *sdu) {
    return sdu->length > 0 && sdu->length <= SDU_MAX_LENGTH;
}

void add_sdu(LTE_MAC_PDU *pdu, const char *data, size_t length) {
    if (!is_valid_sdu((MAC_Service_Data_Unit *) data)) {
        fprintf(stderr, "Invalid SDU length: %zu\n", length);
        return;
    }

    size_t totalLength = 0;
    for (size_t i = 0; i < pdu->sduCount; ++i) {
        totalLength += pdu->sdus[i].length;
    }

    if (totalLength + length > PDU_MAX_SDU_TOTAL_LENGTH) {
        fprintf(stderr, "Total SDU length exceeds maximum allowed\n");
        return;
    }

    if (pdu->sduCount == pdu->allocatedSdus) {
        size_t newAllocated = pdu->allocatedSdus == 0 ? 4 : pdu->allocatedSdus * 2;
        MAC_Service_Data_Unit *newArray = realloc(pdu->sdus, newAllocated * sizeof(MAC_Service_Data_Unit));
        if (!newArray) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        pdu->sdus = newArray;
        pdu->allocatedSdus = newAllocated;
    }

    memcpy(&pdu->sdus[pdu->sduCount], data, sizeof(MAC_Service_Data_Unit));
    pdu->sdus[pdu->sduCount].length = length;
    ++pdu->sduCount;
}

bool add_pdu(PDU_Manager *manager, LTE_MAC_PDU *newPdu) {
    if (manager->pduCount >= MAX_PDU_COUNT) {
        fprintf(stderr, "Maximum number of PDUs reached\n");
        return false;
    }

    // Check for duplicate based on MAC Header or other unique identifiers
    for (size_t i = 0; i < manager->pduCount; ++i) {
        if (manager->pdus[i].macHeader == newPdu->macHeader) {
            fprintf(stderr, "Duplicate PDU with header: %u\n", newPdu->macHeader);
            return false;
        }
    }

    // Initialize SDU storage
    newPdu->sdus = malloc(4 * sizeof(MAC_Service_Data_Unit));
    if (!newPdu->sdus) {
        fprintf(stderr, "Failed to allocate memory for SDUs\n");
        return false;
    }
    newPdu->sduCount = 0;
    newPdu->allocatedSduns = 4;

    // Add PDU to manager
    manager->pdus[manager->pduCount++] = *newPdu;

    return true;
}

void free_pdu_resources(PDU_Manager *manager) {
    for (size_t i = 0; i < manager->pduCount; ++i) {
        if (manager->pdus[i].sdus) {
            free(manager->pdus[i].sdus);
        }
    }
}
```

This code defines a basic system to manage LTE MAC PDUs and their associated SDUs. It includes functions for adding SDUs, managing duplicate checks based on MAC headers, dynamic resizing of the SDU list, and handling potential errors. The `add_sdu` function ensures that each SDU added is unique within its PDU and adheres to length constraints, while `add_pdu` integrates new PDUs into a manager structure, ensuring no duplicates are added. The code supports user-defined metadata for each PDU.']

