CRCList* create_crc_list(unsigned int seed) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    srand(seed);

    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        list->entries[i] = NULL;
    }

    return list;
}

int generate_unique_rnti(unsigned int* rnti_set, unsigned int max_rnti) {
    while (1) {
        unsigned int rnti = rand() % max_rnti + 1; // Avoid zero
        if (!rnti_set[rnti]) {
            rnti_set[rnti] = 1;
            return rnti;
        }
    }
}

void free_crc_list(CRCList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int populate_crc_list(CRCList* list, size_t n, unsigned int max_rnti) {
    if (n > MAX_ENTRIES || !list) return -1;

    unsigned int rnti_set[MAX_ENTRIES] = {0};
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < n; ++i) {
