        entry->CRC_INDICATION_REL8_TAG = rand() % 1024; // Example range
        entry->CRCFLAG = rand() % 2;

        list->entries[list->count++] = entry;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int main(int argc, char* argv[]) {
