['Below is a C implementation that addresses the requirements specified for managing a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures with unique `RNTI` values, ensuring thread safety and memory efficiency:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    pthread_mutex_t lock;  // Mutex for thread safety per node
} Node;

// Function to create a new Node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

// Function to insert a unique RNTI into the linked list
bool insert_unique_rnti(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = *head;
    while (current != NULL) {
        pthread_mutex_lock(&current->lock);
        if (current->data.RNTI == data.RNTI) {
            // RNTI already exists
            pthread_mutex_unlock(&current->lock);
            return false;  // Duplicate found, insertion not performed
        }
        pthread_mutex_unlock(&current->lock);

        current = current->next;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        return false;  // Memory allocation failed
    }

    pthread_mutex_lock(&new_node->lock);
    new_node->next = *head;
    *head = new_node;

    return true;  // Insertion successful
}

// Function to free the linked list
void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next_node = current->next;
        pthread_mutex_destroy(&current->lock);
        free(current);
        current = next_node;
    }
}

// Example usage
int main() {
    Node* head = NULL;

    // Simulate insertion of elements
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand(),
            .RNTI = rand() % 65536,
            .CRC_INDICATION_REL8_TAG = rand() % 256,
            .CRCFLAG = rand() % 2
        };

        if (!insert_unique_rnti(&head, pdu)) {
            printf("Failed to insert or duplicate RNTI found: %u\n", pdu.RNTI);
        }
    }

    // Free the list after use
    free_list(head);

    return 0;
}
```

### Key Points:

1. **Thread Safety**: Each node has its own mutex lock, allowing fine-grained locking which is crucial for concurrent modifications in a multi-threaded environment.

2. **Memory Management**: Efficient memory allocation and deallocation are handled to ensure the function can manage up to 10,000 elements without excessive overhead.

3. **Duplicate Handling**: The function checks for existing `RNTI` values before insertion, ensuring uniqueness.

4. **Error Handling**: Memory allocation failures are checked and reported gracefully.

5. **Scalability**: The design supports scalability by using a singly-linked list with per-node locking to minimize contention and maximize performance under high load conditions.']

