#define MAX_API_RETRIES 3
#define API_RETRY_DELAY 1 // seconds

typedef struct {
    char uid[32];
    char ip_address[16];
    time_t last_active_timestamp;
} ConnectionStatus;

typedef struct Node {
    ConnectionStatus data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} ConnectionList;

ConnectionList* create_connection_list() {
    ConnectionList* list = malloc(sizeof(ConnectionList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void free_connection_list(ConnectionList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_or_update_entry(ConnectionList* list, const char* uid, const char* ip_address) {
    pthread_mutex_lock(&list->lock);

    Node** ptr = &list->head;
    while (*ptr != NULL) {
        Node* entry = *ptr;
        if (strcmp(entry->data.uid, uid) == 0) {
            strncpy(entry->data.ip_address, ip_address, sizeof(entry->data.ip_address));
            entry->data.last_active_timestamp = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return 1; // Updated existing entry
        }
        ptr = &entry->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    strncpy(new_node->data.uid, uid, sizeof(new_node->data.uid));
    strncpy(new_node->data.ip_address, ip_address, sizeof(new_node->data.ip_address));
    new_node->data.last_active_timestamp = time(NULL);
    new_node->next = NULL;
    *ptr = new_node;

    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0; // New entry added
}

