    for (int i = 0; i < MAX_API_RETRIES; ++i) {
        // Simulate API call with retry logic
        int status = simulate_network_call(api_endpoint);
        if (status == 0) { // Success
            return 1;
        }
        sleep(API_RETRY_DELAY); // Wait before next attempt
    }
    fprintf(stderr, "API query failed after retries\n");
    return -1; // Failed to update from API
}

void filter_and_report(ConnectionList* list, const char* uid, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if ((uid == NULL || strcmp(current->data.uid, uid) == 0)
            && (start_time <= current->data.last_active_timestamp && current->data.last_active_timestamp <= end_time)) {

            printf("UID: %s, IP: %s, Last Active: %ld\n",
                   current->data.uid,
                   current->data.ip_address,
                   current->data.last_active_timestamp);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void periodic_flush_and_compact(ConnectionList* list) {
    // Implement logic to remove outdated entries and compact memory
    pthread_mutex_lock(&list->lock);

    Node** ptr = &list->head;
    time_t now = time(NULL);
    while (*ptr != NULL) {
        Node* entry = *ptr;
        if (now - entry->data.last_active_timestamp > 3600) { // Example threshold: 1 hour
            Node* to_delete = entry;
            *ptr = entry->next;
            free(to_delete);
            list->count--;
        } else {
            ptr = &entry->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Simulate network call for demonstration purposes
int simulate_network_call(const char* api_endpoint) {
    // Placeholder: Replace with actual API interaction logic.
    return rand() % 2 == 0 ? 0 : -1; // Random success or failure
}

int main() {
    ConnectionList* list = create_connection_list();

    add_or_update_entry(list, "user123", "192.168.0.1");
    query_api_and_update(list, "http://api.example.com/status");

    filter_and_report(list, NULL, time(NULL) - 86400, time(NULL)); // Last 24 hours

    periodic_flush_and_compact(list);

    free_connection_list(list);

    return 0;
}
```

This code defines a `ConnectionList` structure to manage network connection status reports. It includes functions for adding/updating entries, querying an API with retry logic, filtering and reporting entries based on criteria, and periodically flushing outdated entries. Thread-safety is ensured using mutex locks.']

