    int getConfig(const std::string& key) const { return 0; } // Retrieve config
};

// Service for handling NFAPI_CRC_INDICATION_PDU_T structures.
class NFAPIService {
private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> processingQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::atomic<bool> running{true};
    ConfigManager configManager;

    void processPDU(NFAPI_CRC_INDICATION_PDU_T pdu) {
        // Validate and process PDU.
        log("Processing PDU...");
    }

    NFAPI_CRC_INDICATION_PDU_T createRandomPDU() {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);
        pdu.crc_indication_rel8_tag.CRCFLAG = dis(gen) ? true : false;
        return pdu;
    }

    void worker() {
        while (running.load()) {
            NFAPI_CRC_INDICATION_PDU_T pdu;

            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this]() { return !processingQueue.empty() || !running.load(); });

                if (!running.load()) break;
                pdu = processingQueue.front();
                processingQueue.pop();
            }

            try {
                processPDU(pdu);
            } catch (const std::exception& e) {
                log(std::string("Error processing PDU: ") + e.what());
            }
        }
    }

public:
    NFAPIService() {
        // Start worker threads.
        for (int i = 0; i < 4; ++i) { // Adjust thread count as needed
            std::thread(&NFAPIService::worker, this).detach();
        }
    }

    ~NFAPIService() {
        running.store(false);
        cv.notify_all();
    }

    void enqueuePDU(NFAPI_CRC_INDICATION_PDU_T pdu) {
        std::lock_guard<std::mutex> lock(queueMutex);
        processingQueue.push(pdu);
        cv.notify_one();
    }
};

int main() {
    NFAPIService service;

    // Simulate incoming data
    for (int i = 0; i < 100; ++i) {
        auto pdu = service.createRandomPDU();
        service.enqueuePDU(pdu);
        std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Control load
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    log("Service shutting down.");

    return 0;
}
