void init_dynamic_array(DynamicArray *arr, size_t initial_capacity) {
    arr->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->capacity = initial_capacity;
    arr->count = 0;
