    free(arr->array);
    arr->array = NULL;
    arr->capacity = 0;
    arr->count = 0;
}

// Helper function to resize the dynamic array when needed
static void ensure_capacity(DynamicArray *arr) {
    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity == 0 ? 1 : arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array) {
            arr->array = new_array;
            arr->capacity = new_capacity;
        } else {
            // Handle reallocation failure
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to add a new element to the array
void add_element(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T element) {
