    arr->array[arr->count++] = element;
}

// Function to remove an element by index from the array
int remove_element_by_index(DynamicArray *arr, size_t index) {
    if (index >= arr->count) return -1; // Invalid index

    for (size_t i = index; i < arr->count - 1; ++i) {
        arr->array[i] = arr->array[i + 1];
    }
    --arr->count;
    return 0;
}

// Function to update an element by index in the array
int update_element(DynamicArray *arr, size_t index, NFAPI_CRC_INDICATION_PDU_T new_value) {
    if (index >= arr->count) return -1; // Invalid index

    arr->array[index] = new_value;
    return 0;
}

// Example usage of the functions
