    init_dynamic_array(&arr, 4);

    NFAPI_CRC_INDICATION_PDU_T element1 = { .RX_UE_INFORMATION_TAG = 100, .RNTI = 200, .CRC_INDICATION_REL8_TAG = { .CRCFLAG = rand() % 2 } };
