#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int CELL_ID;
    int PCI;
    float RSRP_LEVEL;
} NR_CELL_INFO;

typedef struct {
    NR_CELL_INFO* cells;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} CellManager;

// Initialize the cell manager with an initial capacity
CellManager* init_cell_manager(size_t initial_capacity) {
    CellManager* manager = (CellManager*)malloc(sizeof(CellManager));
    if (!manager) return NULL;

    manager->cells = (NR_CELL_INFO*)calloc(initial_capacity, sizeof(NR_CELL_INFO));
    if (!manager->cells) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Resize the array when capacity is reached
int resize_array(CellManager* manager, size_t new_capacity) {
    NR_CELL_INFO* new_cells = (NR_CELL_INFO*)realloc(manager->cells, new_capacity * sizeof(NR_CELL_INFO));
    if (!new_cells) return -1;

    manager->cells = new_cells;
    manager->capacity = new_capacity;
    return 0;
}

// Add a new cell
int add_cell(CellManager* manager, int cell_id, int pci, float rsrp_level) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (resize_array(manager, new_capacity)) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    NR_CELL_INFO* cell = &manager->cells[manager->count++];
    cell->CELL_ID = cell_id;
    cell->PCI = pci;
    cell->RSRP_LEVEL = rsrp_level;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Remove a cell by CELL_ID
int remove_cell(CellManager* manager, int cell_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->cells[i].CELL_ID == cell_id) {
            memmove(&manager->cells[i], &manager->cells[i + 1], 
                    (manager->count - i - 1) * sizeof(NR_CELL_INFO));
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Cell not found
}

// Update an existing cell's information
int update_cell(CellManager* manager, int cell_id, int pci, float rsrp_level) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->cells[i].CELL_ID == cell_id) {
            manager->cells[i].PCI = pci;
            manager->cells[i].RSRP_LEVEL = rsrp_level;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Cell not found
}

// Free the resources allocated for the cell manager
void free_cell_manager(CellManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->cells);
        free(manager);
    }
}
