#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <errno.h>
#include <unistd.h>

#define MAX_INTERFACES 1024
#define RETRY_LIMIT 5

typedef struct {
    int id;
    char ip[16];
    char subnet_mask[16];
} NetworkInterface;

typedef struct {
    NetworkInterface interfaces[MAX_INTERFACES];
    pthread_mutex_t lock;
    size_t count;
    // Caching layer for network discovery results
    char cache_data[1024]; 
    time_t last_cache_update;
} NetworkManager;

NetworkManager *manager = NULL;

int hash_ip(const char *ip) {
    return inet_addr(ip);
}

int check_duplicate_ip(NetworkInterface *new_interface, NetworkManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->interfaces[i].ip, new_interface->ip) == 0) {
            return 1;
        }
    }
    return 0;
}

void retry_with_backoff(void (*operation)(NetworkManager *), NetworkManager *manager) {
    int attempts = 0;
    while (attempts < RETRY_LIMIT) {
        if ((*operation)(manager)) {
            return; // Success
        }
        sleep((1 << attempts)); // Exponential back-off
        attempts++;
    }
    fprintf(stderr, "Operation failed after %d retries\n", RETRY_LIMIT);
}

void add_interface(NetworkManager *manager, NetworkInterface new_interface) {
    pthread_mutex_lock(&manager->lock);

    if (check_duplicate_ip(&new_interface, manager)) {
        fprintf(stderr, "Duplicate IP address detected: %s\n", new_interface.ip);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    if (manager->count >= MAX_INTERFACES) {
        fprintf(stderr, "Maximum interfaces reached\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->interfaces[manager->count++] = new_interface;

    // Simulate network discovery service call with retry
    retry_with_backoff(network_discovery_operation, manager);

    pthread_mutex_unlock(&manager->lock);
}

void delete_interface(NetworkManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->interfaces[i].id == id) {
            memmove(&manager->interfaces[i], &manager->interfaces[i + 1],
                    (--manager->count - i) * sizeof(NetworkInterface));
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int network_discovery_operation(NetworkManager *manager) {
    // Simulate discovery service operation
    printf("Performing network discovery...\n");
    return rand() % 2; // Random success or failure for simulation
}

void init_manager(NetworkManager **manager) {
    *manager = (NetworkManager *)calloc(1, sizeof(NetworkManager));
    pthread_mutex_init(&(*manager)->lock, NULL);
    (*manager)->count = 0;
}

void cleanup_manager(NetworkManager *manager) {
    free(manager);
}

int main() {
    NetworkInterface ni1 = { .id = 1, .ip = "192.168.1.10", .subnet_mask = "255.255.255.0" };
    NetworkInterface ni2 = { .id = 2, .ip = "192.168.1.11", .subnet_mask = "255.255.255.0" };

    init_manager(&manager);

    add_interface(manager, ni1);
    add_interface(manager, ni2);

    delete_interface(manager, 1);

    cleanup_manager(manager);

    return 0;
}
```

