    pthread_mutex_init(&manager->mutex, NULL);
    manager->sequence_number = 0;
}

uint32_t getNextSequenceNumber(BufferManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    uint32_t seq_num = manager->sequence_number++;
    pthread_mutex_unlock(&manager->mutex);
    return seq_num;
}

void addToBuffer(BufferManager *manager, NFAPI_RX_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count < BUFFER_SIZE) {
