        free(manager->buffer[0]->pdu.payload);
        free(manager->buffer[0]);
        memmove(&manager->buffer[0], &manager->buffer[1], (BUFFER_SIZE - 1) * sizeof(NFAPI_RX_INDICATION_PDU_T *));
        manager->buffer[BUFFER_SIZE - 1] = pdu;
    }
    pthread_mutex_unlock(&manager->mutex);
}

