typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARN,
    LOG_ERROR
} LogLevel;

#define MAX_LOG_SIZE 256

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char message[MAX_LOG_SIZE];
    struct LogEntry *next;
} LogEntry;

typedef struct {
    size_t maxBufferSize;
    size_t maxEntries;
    LogEntry *head;
    LogEntry *tail;
} Logger;

Logger* create_logger(size_t maxBufferSize, size_t maxEntries) {
    Logger *logger = (Logger *)malloc(sizeof(Logger));
    if (!logger) return NULL;

    logger->maxBufferSize = maxBufferSize;
    logger->maxEntries = maxEntries;
    logger->head = logger->tail = NULL;

    return logger;
}

void free_logger(Logger *logger) {
    LogEntry *current = logger->head;
    while (current) {
        LogEntry *next = current->next;
        free(current);
        current = next;
    }
    free(logger);
}

int add_log_entry(Logger *logger, LogLevel level, const char *message) {
    if (!logger || !message || strlen(message) >= MAX_LOG_SIZE) return -1;

    size_t entrySize = sizeof(LogEntry) + (strlen(message) + 1);

    if (entrySize > logger->maxBufferSize) return -1;

    LogEntry *newEntry = (LogEntry *)malloc(entrySize);
    if (!newEntry) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    newEntry->timestamp = time(NULL);
    newEntry->level = level;
    strncpy(newEntry->message, message, MAX_LOG_SIZE - 1);

    if (logger->tail) {
        logger->tail->next = newEntry;
    } else {
        logger->head = newEntry;
    }
    logger->tail = newEntry;

    size_t currentSize = entrySize;
    LogEntry *current = logger->head;
    while (current && current->next) {
        current = current->next;
        currentSize += sizeof(LogEntry) + strlen(current->message) + 1;
    }

    while (currentSize > logger->maxBufferSize || current != NULL && --logger->maxEntries == 0) {
        LogEntry *toRemove = logger->head;
        if (toRemove) {
            logger->head = toRemove->next;
            free(toRemove);
            currentSize -= sizeof(LogEntry) + strlen(toRemove->message) + 1;
            if (!logger->head) logger->tail = NULL;
        }
    }

    return 0;
}

void log(Logger *logger, LogLevel level, const char *format, ...) {
    va_list args;
    va_start(args, format);

    char buffer[MAX_LOG_SIZE];
    vsnprintf(buffer, MAX_LOG_SIZE, format, args);
    va_end(args);

    add_log_entry(logger, level, buffer);
}

int main() {
    Logger *logger = create_logger(1024, 10); // Example configuration

    if (logger) {
        log(logger, LOG_INFO, "This is an info message.");
        log(logger, LOG_ERROR, "This is an error message.");

        free_logger(logger);
    }

    return 0;
}
