typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *cind_buf[MAX_EVENTS];
    RX_INDICATION_PAYLOAD *rind_buf[MAX_EVENTS];

    int cind_count;
    int rind_count;

    uint32_t next_sequence_number;
} EventBufferManager;

void init_event_buffer_manager(EventBufferManager *manager) {
    manager->cind_count = 0;
    manager->rind_count = 0;
    manager->next_sequence_number = (uint32_t)time(NULL); // Use current time as seed
}

int add_crc_indication_pdu(EventBufferManager *manager, uint16_t rnti) {
    if (manager->cind_count >= MAX_EVENTS) {
        return -1; // Buffer overflow
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        return -2; // Memory allocation failed
    }

    pdu->sequence_number = manager->next_sequence_number++;
    pdu->rnti = rnti;
    srand(pdu->sequence_number);
    pdu->crc_tag.crcflag = rand() % 2; // Randomly set CRC flag

    manager->cind_buf[manager->cind_count++] = pdu;

    return 0;
}

int add_rx_indication_payload(EventBufferManager *manager, uint16_t rnti, void* payload) {
    if (manager->rind_count >= MAX_EVENTS) {
        return -1; // Buffer overflow
    }

    RX_INDICATION_PAYLOAD *ind_payload = malloc(sizeof(RX_INDICATION_PAYLOAD));
    if (!ind_payload) {
        return -2; // Memory allocation failed
    }

    ind_payload->sequence_number = manager->next_sequence_number++;
    ind_payload->timestamp = (uint64_t)time(NULL); // Unique timestamp
    ind_payload->rnti = rnti;
    ind_payload->payload = payload;

    manager->rind_buf[manager->rind_count++] = ind_payload;

    return 0;
}

void free_event_buffer_manager(EventBufferManager *manager) {
    for (int i = 0; i < manager->cind_count; ++i) {
        free(manager->cind_buf[i]);
    }

    for (int i = 0; i < manager->rind_count; ++i) {
        free(manager->rind_buf[i]);
    }

    manager->cind_count = 0;
    manager->rind_count = 0;
}

void process_events(EventBufferManager *manager, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (int i = 0; i < manager->cind_count; ++i) {
        callback(manager->cind_buf[i]);
    }
}
