    log_status("Service started");
    send_notification("Service started");

    pthread_mutex_unlock(&cache_lock);
}

void stop_service(void) {
    pthread_mutex_lock(&cache_lock);

    free(service_data.data);
    service_data.data = NULL;
    service_data.count = 0;

    is_service_running = 0;
    log_status("Service stopped");
    send_notification("Service stopped");

    pthread_mutex_unlock(&cache_lock);
}

void restart_service(void) {
    stop_service();
    start_service();
}

void monitor_cpu_usage(void) {
