unsigned long hashRNTIAndIP(unsigned int rnti, struct in_addr ip) {
    unsigned char combined[5];
    memcpy(combined, &rnti, 4);
    combined[4] = ip.s_addr;
    return *(unsigned long *)combined;
}

// DNS resolution with caching and blocking control
struct in_addr resolveHostname(char *hostname) {
    pthread_mutex_lock(&globalMutex);

    // Check cache first
    for (int i = 0; i < MAX_HOSTNAMES; i++) {
        if (strcmp(dnsCache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&globalMutex);
            return dnsCache[i].ip;
        }
    }

    // Perform DNS resolution with non-blocking logic
    struct in_addr resolvedIP = { .s_addr = inet_addr(hostname) }; // Mocked for simplicity

    // Store result in cache
    for (int i = 0; i < MAX_HOSTNAMES; i++) {
        if (dnsCache[i].hostname[0] == '\0') {
            strncpy(dnsCache[i].hostname, hostname, sizeof(dnsCache[i].hostname) - 1);
            dnsCache[i].ip = resolvedIP;
            pthread_mutex_unlock(&globalMutex);
            return resolvedIP;
        }
    }

    pthread_mutex_unlock(&globalMutex);
    return resolvedIP; // In case of cache overflow or error
}

// Rate-limiting control mechanism (mock implementation)
void rateLimitingControl() {
    static int processedCount = 0;

    if (processedCount >= MAX_DNS_CONCURRENT_REQUESTS) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += DNS_BLOCK_TIMEOUT_MS / 1000;
        ts.tv_nsec += (DNS_BLOCK_TIMEOUT_MS % 1000) * 1000000;

        pthread_mutex_lock(&globalMutex);
        while (processedCount >= MAX_DNS_CONCURRENT_REQUESTS) {
            pthread_cond_timedwait(&conditionVariable, &globalMutex, &ts);
        }
        pthread_mutex_unlock(&globalMutex);
    }

    processedCount++;
}

// Main function implementation
NFAPI_CRC_INDICATION_PDU_T* createAndPopulateNFAPDUList(HostnameWeight hostnames[], int numHostnames) {
    NFAPI_CRC_INDICATION_PDU_T *pfduList = malloc(numHostnames * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pfduList) return NULL;

    // Synchronize with external network module
    synchronizeWithNetworkModule();

    for (int i = 0; i < numHostnames; i++) {
        rateLimitingControl();

        struct in_addr ip = resolveHostname(hostnames[i].hostname);
        unsigned int rnti = rand() % 10000; // Mocked RNTI generation

        if (!isValidRNTI(rnti)) {
            logMessage("Invalid RNTI encountered", 1);
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = &pfduList[i];
        pdu->rnti = rnti;

        unsigned long crcFlag = hashRNTIAndIP(rnti, ip);
        pdu->crc_indication_rel8_tag.crcflag = (unsigned char)(crcFlag & 0xFF);

        logMessage("Successfully populated NFAPI_CRC_INDICATION_PDU_T", 2);

        pthread_mutex_lock(&globalMutex);
        processedCount--;
        if (processedCount < MAX_DNS_CONCURRENT_REQUESTS) {
            pthread_cond_signal(&conditionVariable);
        }
        pthread_mutex_unlock(&globalMutex);
    }

    return pfduList;
}
