#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    int size;
} HashTable;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    int count;
} LinkedList;

// Function declarations
void initializeHashTable(HashTable* ht);
int hashFunction(uint16_t rnti, int tableSize);
void addEntry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T entry);
ListNode* findNodeByRNTI(LinkedList* list, uint16_t rnti);
void removeEntry(LinkedList* list, uint16_t rnti);
void insertIntoHashTable(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T entry);
NFAPI_CRC_INDICATION_PDU_T* lookupInHashTable(HashTable* ht, uint16_t rnti);

// Initialize hash table
void initializeHashTable(HashTable* ht) {
    ht->size = HASH_TABLE_SIZE;
    ht->table = (HashNode**)calloc(HASH_TABLE_SIZE, sizeof(HashNode*));
}

// Hash function for RNTI
int hashFunction(uint16_t rnti, int tableSize) {
    return rnti % tableSize;
}

// Add entry to the list in sorted order by timestamp
void addEntry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) exit(EXIT_FAILURE);

    newNode->data = entry;
    if (!list->head || list->head->data.timestamp > entry.timestamp) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        ListNode* current = list->head;
        while (current->next && current->next->data.timestamp <= entry.timestamp) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    list->count++;
}

// Find a node by RNTI in the linked list
ListNode* findNodeByRNTI(LinkedList* list, uint16_t rnti) {
    ListNode* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return current;
        current = current->next;
    }
    return NULL;
}

// Remove entry from the list by RNTI
void removeEntry(LinkedList* list, uint16_t rnti) {
    ListNode* prev = NULL;
    ListNode* current = list->head;

    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            free(current);
            list->count--;
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Insert entry into the hash table
void insertIntoHashTable(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T entry) {
    int index = hashFunction(entry.RNTI, ht->size);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) exit(EXIT_FAILURE);

    newNode->RNTI = entry.RNTI;
    newNode->data = entry;
    newNode->next = ht->table[index];
    ht->table[index] = newNode;
}

// Lookup entry in the hash table by RNTI
NFAPI_CRC_INDICATION_PDU_T* lookupInHashTable(HashTable* ht, uint16_t rnti) {
    int index = hashFunction(rnti, ht->size);
    HashNode* current = ht->table[index];

    while (current) {
        if (current->RNTI == rnti) return &current->data;
        current = current->next;
    }
    return NULL;
}

// Example usage
int main() {
    LinkedList list = {NULL, 0};
    HashTable ht;

    initializeHashTable(&ht);

    // Simulate adding entries
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.RX_UE_INFORMATION_TAG = rand();
        entry.RNTI = rand() % 1000;
        entry.CRCFLAG = rand() & 1;
        entry.timestamp = time(NULL);

        addEntry(&list, entry);
        insertIntoHashTable(&ht, entry);
    }

    // Simulate removal
    if (list.head) {
        removeEntry(&list, list.head->data.RNTI);
    }

    return 0;
}
