    RX_UE_INFORMATION_TAG info2 = { .RNTI = 1, .crc_indication_rel8_tag = {.CRCFLAG = 0} };
    RX_UE_INFORMATION_TAG info3 = { .RNTI = 2, .crc_indication_rel8_tag = {.CRCFLAG = 1} };

    insert_sorted(&list_head, info1);
    insert_sorted(&list_head, info2);
