    }

    free_list(list_head);
    return 0;
}

// Function to insert a node in sorted order
NFAPI_CRC_INDICATION_PDU_T* insert_sorted(NFAPI_CRC_INDICATION_PDU_T **head, RX_UE_INFORMATION_TAG info) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->rx_ue_information_tag = info;
    new_node->next = NULL;

    // Insert in sorted order
    if (*head == NULL || (*head)->rx_ue_information_tag.RNTI > info.RNTI) {
        new_node->next = *head;
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = *head;
        while (current->next != NULL && current->next->rx_ue_information_tag.RNTI < info.RNTI) {
            current = current->next;
        }
        if (current->next != NULL && current->next->rx_ue_information_tag.RNTI == info.RNTI) {
            free(new_node);
            return *head; // Duplicate RNTI
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    return *head;
}

// Function to print the list
void print_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        printf("RNTI: %lu, CRCFLAG: %d\n", current->rx_ue_information_tag.RNTI, current->rx_ue_information_tag.crc_indication_rel8_tag.CRCFLAG);
        current = current->next;
    }
}

// Function to validate unique RNTIs
int validate_unique_RNTIs(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL && current->next != NULL) {
        if (current->rx_ue_information_tag.RNTI == current->next->rx_ue_information_tag.RNTI) {
            return 0; // Duplicate found
        }
        current = current->next;
    }
    return 1; // All unique
}

// Function to free the list
void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next_node = current->next;
        free(current);
        current = next_node;
    }
}
