    size_t new_capacity = arr->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return;

    arr->data = new_data;
    arr->capacity = new_capacity;
}

