    queue->buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->size = 0;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->lock, NULL);
}

void free_crc_queue(CRC_Queue* queue) {
    free(queue->buffer);
    pthread_mutex_destroy(&queue->lock);
}

int validate_rnti(uint16_t rnti) {
