}

uint8_t generate_random_crc_flag() {
    srand(time(NULL)); // Ideally use a better random generator
    return rand() % 256; // Generate a random value for CRCFLAG
}

void add_pdu(CRC_Queue* queue, uint32_t rxUEInformationTag, uint16_t rnti) {
    if (!validate_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI: %u\n", rnti);
        return;
    }

    pthread_mutex_lock(&queue->lock);

    if (queue->size == queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_buffer = realloc(queue->buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&queue->lock);
            return;
        }
        queue->buffer = new_buffer;
        queue->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .rxUEInformationTag = rxUEInformationTag };
    pdu.crcIndicationRel8Tag.rnti = rnti;
    pdu.crcIndicationRel8Tag.crcFlag = generate_random_crc_flag();

    queue->buffer[queue->size++] = pdu;

    pthread_mutex_unlock(&queue->lock);
}

