<?php

session_start();

function authenticateUserWithOAuth2($clientId, $clientSecret, $redirectUri, $authUrl, $tokenUrl, $userInfoUrl) {
    // Step 1: Get authorization code
    if (!isset($_GET['code'])) {
        $params = [
            'response_type' => 'code',
            'client_id'     => $clientId,
            'redirect_uri'  => $redirectUri,
            'scope'         => '', // Define your scope here
        ];

        $authUrlWithParams = $authUrl . '?' . http_build_query($params);
        header('Location: ' . $authUrlWithParams);
        exit;
    }

    // Step 2: Exchange authorization code for access token
    $authorizationCode = $_GET['code'];
    $ch = curl_init();

    curl_setopt_array($ch, [
        CURLOPT_URL            => $tokenUrl,
        CURLOPT_POST           => true,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POSTFIELDS     => http_build_query([
            'grant_type'    => 'authorization_code',
            'client_id'     => $clientId,
            'client_secret' => $clientSecret,
            'code'          => $authorizationCode,
            'redirect_uri'  => $redirectUri,
        ]),
    ]);

    $response = curl_exec($ch);
    if ($response === false) {
        die('Error: "' . curl_error($ch) . '" - Code: ' . curl_errno($ch));
    }

    curl_close($ch);
    $tokenResponse = json_decode($response, true);

    // Step 3: Store the access token in a session variable
    $_SESSION['access_token'] = $tokenResponse['access_token'];

    // Step 4: Retrieve user information using the access token
    $userInfoCh = curl_init();

    curl_setopt_array($userInfoCh, [
        CURLOPT_URL            => $userInfoUrl,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HTTPHEADER     => ['Authorization: Bearer ' . $_SESSION['access_token']],
    ]);

    $userResponse = curl_exec($userInfoCh);
    if ($userResponse === false) {
        die('Error: "' . curl_error($userInfoCh) . '" - Code: ' . curl_errno($userInfoCh));
    }

    curl_close($userInfoCh);
    return json_decode($userResponse, true);
}

// C structure to manage session data
struct UserSessionData {
    char clientId[256];
    char clientSecret[256];
    char redirectUri[256];
    char authUrl[512];
    char tokenUrl[512];
    char userInfoUrl[512];
};

// Example usage
function exampleUsage() {
    struct UserSessionData sessionData = {
        .clientId     = "your-client-id",
        .clientSecret = "your-client-secret",
        .redirectUri  = "your-redirect-uri",
        .authUrl      = "https://provider.com/oauth2/auth",
        .tokenUrl     = "https://provider.com/oauth2/token",
        .userInfoUrl  = "https://provider.com/userinfo"
    };

    $userDetails = authenticateUserWithOAuth2(
        sessionData.clientId,
        sessionData.clientSecret,
        sessionData.redirectUri,
        sessionData.authUrl,
        sessionData.tokenUrl,
        sessionData.userInfoUrl
    );

    print_r($userDetails);
}

