    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    LTE_PUCCH_CONFIG_S pucch_configs[MAX_PUCCH_CONFIGS];
    MAC_TransportLayerStats mac_stats[MAX_STATS];
    pthread_mutex_t mutex;
    int pucch_count;
    int stats_count;
} DynamicArrayManager;

DynamicArrayManager* create_dynamic_array_manager(const char *env_var) {
    // Ensure environment variable for directory path exists
    char *dir_path = getenv(env_var);
    if (!dir_path) {
        dir_path = "/tmp/dynamic_arrays";
        if (mkdir(dir_path, 0755) != 0 && errno != EEXIST) {
            perror("Failed to create directory");
            return NULL;
        }
        setenv(env_var, dir_path, 1);
    }

    DynamicArrayManager *manager = malloc(sizeof(DynamicArrayManager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    memset(manager->pucch_configs, 0, sizeof(manager->pucch_configs));
    memset(manager->mac_stats, 0, sizeof(manager->mac_stats));
    manager->pucch_count = 0;
    manager->stats_count = 0;

    return manager;
}

int add_pucch_config(DynamicArrayManager *manager, LTE_PUCCH_CONFIG_S config) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->pucch_count >= MAX_PUCCH_CONFIGS) {
        pthread_mutex_unlock(&manager->mutex);
        fprintf(stderr, "PUCCH Config limit reached\n");
        return -1;
    }
    manager->pucch_configs[manager->pucch_count++] = config;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int add_mac_stats(DynamicArrayManager *manager, MAC_TransportLayerStats stats) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->stats_count >= MAX_STATS) {
        pthread_mutex_unlock(&manager->mutex);
        fprintf(stderr, "MAC Stats limit reached\n");
        return -1;
    }
    manager->mac_stats[manager->stats_count++] = stats;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T create_crc_indication_pdu(int rx_ue_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG = rand() % 65536; // Random CRC tag
    pdu.CRCFLAG = (rand() % 2) ? 1 : 0; // Random CRC flag
    return pdu;
}

void flush_data_to_disk(DynamicArrayManager *manager, const char *file_path) {
    pthread_mutex_lock(&manager->mutex);
    FILE *file = fopen(file_path, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    fwrite(manager->pucch_configs, sizeof(LTE_PUCCH_CONFIG_S), manager->pucch_count, file);
    fwrite(manager->mac_stats, sizeof(MAC_TransportLayerStats), manager->stats_count, file);
    fclose(file);
    pthread_mutex_unlock(&manager->mutex);
}

void cleanup_dynamic_array_manager(DynamicArrayManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}
