```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 5000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RNTI;
    int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    volatile size_t totalProcessed;
} PDU_List;

void log_message(const char *message) {
    printf("%s\n", message);
}

PDU_List* create_pdu_list(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_ELEMENTS) {
        log_message("Invalid initial capacity");
        return NULL;
    }

    PDU_List *list = (PDU_List *)malloc(sizeof(PDU_List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        perror("Failed to allocate memory for PDUs");
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    list->totalProcessed = 0;

    return list;
}

int resize_pdu_list(PDU_List *list) {
    size_t new_capacity = list->capacity < MAX_ELEMENTS ? list->capacity * 2 : MAX_ELEMENTS;

    NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) {
        perror("Failed to reallocate memory for PDUs");
        return -1;
    }

    list->pdus = new_pdus;
    list->capacity = new_capacity;

    return 0;
}

void add_pdu(PDU_List *list, unsigned long rnti, int rx_ue_tag) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity && resize_pdu_list(list) != 0) {
        log_message("Failed to allocate memory for more PDUs");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RNTI = rnti, .RX_UE_INFORMATION_TAG = rx_ue_tag };
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->pdus[list->count++] = pdu;
    list->totalProcessed++;

    pthread_mutex_unlock(&list->lock);
}

void clear_and_free_pdu_list(PDU_List *list) {
    if (list) {
        pthread_mutex_lock(&list->lock);

        free(list->pdus);
        pthread_mutex_unlock(&list->lock);

        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

size_t get_total_processed(const PDU_List *list) {
    return list ? list->totalProcessed : 0;
}

void iterate_pdus(PDU_List *list, void (*func)(const NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; i++) {
        func(&list->pdus[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand(time(NULL));

    PDU_List *pdu_list = create_pdu_list(10);
    if (!pdu_list) return 1;

    for (unsigned long rnti = 0; rnti < 100; rnti++) {
        add_pdu(pdu_list, rnti, rand() % 256);
    }

    log_message("Total CRC indications processed: ");
    printf("%zu\n", get_total_processed(pdu_list));

    iterate_pdus(pdu_list, [](const NFAPI_CRC_INDICATION_PDU_T *pdu) {
        printf("RNTI: %lu, RX Tag: %d, CRCFLAG: %d\n", pdu->RNTI, pdu->RX_UE_INFORMATION_TAG, pdu->CRCFLAG);
    });

    clear_and_free_pdu_list(pdu_list);

    return 0;
}
```

### Key Features:

- **Dynamic Memory Allocation**: Uses `malloc` and `realloc` to manage memory for PDU structures.
- **Concurrency Support**: Utilizes a mutex (`pthread_mutex_t`) to ensure thread-safe access.
- **Logging**: Simple logging function to print messages.
- **Error Handling**: Checks for allocation failures and logs errors.
- **Iterators**: Provides a way to iterate over the list of PDUs safely.
- **Scalability**: Dynamically resizes the array up to a maximum limit.
- **Performance Considerations**: Uses fine-grained locking to minimize contention.

This code is modular, allowing integration with larger systems and can be extended further as needed.']

