    pthread_mutex_init(&q->queue_mutex, NULL);
    pthread_cond_init(&q->not_empty, NULL);

    return q;
}

void destroy_queue(ThreadSafeQueue* q) {
    Node* current = q->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data); // Free the allocated structure
        pthread_mutex_destroy(&current->data->mutex);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&q->queue_mutex);
    pthread_cond_destroy(&q->not_empty);
    free(q);
}

