    new_node->data = item;
    new_node->next = NULL;

    pthread_mutex_lock(&q->queue_mutex);

    if (q->tail == NULL) {
        q->head = q->tail = new_node;
    } else {
        q->tail->next = new_node;
        q->tail = new_node;
    }

    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->queue_mutex);

    return true;
}

