['Below is an example implementation in C using POSIX threads and synchronization mechanisms like mutexes for thread safety. This code includes the core functionality described: adding new updates, updating existing ones, retrieving the latest status, handling concurrency, and maintaining a log of changes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct ErrorCode {
    char *code;
    struct ErrorCode *next;
} ErrorCode;

typedef struct InterfaceStatus {
    time_t timestamp;
    int interfaceID;
    unsigned int statusFlags;
    ErrorCode *errorCodes;
    struct InterfaceStatus *next;
} InterfaceStatus;

typedef struct {
    InterfaceStatus *head;
    pthread_mutex_t lock;
} StatusTracker;

// Function to initialize the StatusTracker
void initStatusTracker(StatusTracker *tracker) {
    tracker->head = NULL;
    pthread_mutex_init(&tracker->lock, NULL);
}

// Helper function to create a new error code node
ErrorCode* createErrorCodeNode(const char *code) {
    ErrorCode *node = (ErrorCode *)malloc(sizeof(ErrorCode));
    if (!node) return NULL;

    node->code = strdup(code); // Duplicate the string for safety
    node->next = NULL;
    return node;
}

// Function to add or update a status entry
void addOrUpdateStatus(StatusTracker *tracker, int interfaceID, unsigned int statusFlags, ErrorCode **errorCodes) {
    pthread_mutex_lock(&tracker->lock);

    InterfaceStatus *current = tracker->head, *prev = NULL;

    while (current && current->interfaceID != interfaceID) {
        prev = current;
        current = current->next;
    }

    time_t now = time(NULL);
    if (!current) { // New entry
        current = (InterfaceStatus *)malloc(sizeof(InterfaceStatus));
        if (!current) {
            pthread_mutex_unlock(&tracker->lock);
            return; // Failed to allocate memory
        }

        current->interfaceID = interfaceID;
        current->timestamp = now;
        current->statusFlags = statusFlags;
        current->errorCodes = NULL;

        ErrorCode *ecCurrent = errorCodes[0];
        while (ecCurrent) {
            ErrorCode *newEc = createErrorCodeNode(ecCurrent->code);
            if (!newEc) break; // Handle allocation failure
            newEc->next = current->errorCodes;
            current->errorCodes = newEc;
            ecCurrent = ecCurrent->next;
        }

        if (prev) {
            prev->next = current;
        } else {
            tracker->head = current;
        }
        current->next = NULL;

    } else { // Update existing entry
        current->timestamp = now;
        current->statusFlags = statusFlags;

        ErrorCode *currentEc = current->errorCodes, *prevEc = NULL;
        while (currentEc) {
            ErrorCode **ecCurrent = errorCodes;
            int found = 0;
            while (*ecCurrent) {
                if (!strcmp(currentEc->code, *ecCurrent)) {
                    found = 1;
                    break;
                }
                ecCurrent++;
            }

            if (!found) { // New error code
                ErrorCode *newEc = createErrorCodeNode(*errorCodes);
                if (!newEc) break; // Handle allocation failure

                newEc->next = currentEc;
                if (prevEc) {
                    prevEc->next = newEc;
                } else {
                    current->errorCodes = newEc;
                }
            } else { // Error code already exists
                free(currentEc->code);
                ErrorCode *temp = currentEc;
                currentEc = currentEc->next;
                if (prevEc) {
                    prevEc->next = currentEc;
                } else {
                    current->errorCodes = currentEc;
                }
                free(temp);
            }

            ecCurrent++;
            prevEc = currentEc ? currentEc : prevEc; // Move to next
        }
    }

    pthread_mutex_unlock(&tracker->lock);

    logStatusUpdate(interfaceID, statusFlags, errorCodes); // Logging mechanism
}

// Function to retrieve the latest status of an interface ID
InterfaceStatus* getStatus(StatusTracker *tracker, int interfaceID) {
    pthread_mutex_lock(&tracker->lock);

    InterfaceStatus *current = tracker->head;
    while (current && current->interfaceID != interfaceID) {
        current = current->next;
    }

    InterfaceStatus *result = current ? (InterfaceStatus *)malloc(sizeof(InterfaceStatus)) : NULL;
    if (result) {
        result->interfaceID = current->interfaceID;
        result->timestamp = current->timestamp;
        result->statusFlags = current->statusFlags;

        // Duplicate error codes for the returned structure
        ErrorCode *ecCurrent = current->errorCodes, *prevEc = NULL;
        result->errorCodes = NULL;
        while (ecCurrent) {
            ErrorCode *newEc = createErrorCodeNode(ecCurrent->code);
            if (!newEc) break; // Handle allocation failure

            newEc->next = result->errorCodes;
            result->errorCodes = newEc;

            prevEc = ecCurrent;
            ecCurrent = ecCurrent->next;
        }
    }

    pthread_mutex_unlock(&tracker->lock);

    return result;
}

// Dummy logging function, replace with actual implementation
void logStatusUpdate(int interfaceID, unsigned int statusFlags, ErrorCode **errorCodes) {
    printf("Logging update for Interface ID: %d\n", interfaceID);
}

// Cleanup function to free allocated memory
void cleanup(StatusTracker *tracker) {
    pthread_mutex_lock(&tracker->lock);

    InterfaceStatus *current = tracker->head;
    while (current) {
        ErrorCode *ecCurrent = current->errorCodes;
        while (ecCurrent) {
            ErrorCode *nextEc = ecCurrent->next;
            free(ecCurrent->code);
            free(ecCurrent);
            ecCurrent = nextEc;
        }

        InterfaceStatus *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&tracker->lock);
    pthread_mutex_destroy(&tracker->lock);
}
