- **Data Structures**: A linked list is used to manage the status updates for each network interface. Each node contains details about an interface's status, including a dynamic list of error codes.

- **Thread Safety**: Mutexes are employed to ensure that operations on shared data (like updating or adding new statuses) are thread-safe.

- **Error Code Management**: A linked list is used within each `InterfaceStatus` for managing the list of error codes associated with it. This allows dynamic additions and deletions of error codes during updates.

- **Logging Mechanism**: There's a placeholder function `logStatusUpdate` to illustrate where logging functionality would be integrated. You should replace this with your actual logging implementation.

- **Memory Management**: Functions like `addOrUpdateStatus` handle the allocation and deallocation of memory carefully, ensuring no leaks occur during operations.

This code provides a foundation for managing network interface statuses in a distributed system with considerations for concurrency, error handling, and modularity.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for error codes associated with an interface.
typedef struct ErrorCode {
    int code;
    char *message;
    struct ErrorCode *next;
} ErrorCode;

// Define the structure for network interface status update.
typedef struct StatusUpdate {
    time_t timestamp;
    int interfaceID;
    int statusFlags;
    ErrorCode *errorCodes;
    struct StatusUpdate *next;
} StatusUpdate;

// Node structure for LRU cache
typedef struct CacheNode {
    StatusUpdate *update;
    struct CacheNode *prev, *next;
} CacheNode;

// Cache structure with a fixed size and linked list for eviction.
typedef struct {
    int capacity;
    int count;
    CacheNode *head, *tail;
    pthread_mutex_t lock;
} LRUCache;

// Global list of status updates
StatusUpdate *statusUpdatesHead = NULL;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Function prototypes
void addOrUpdateStatusUpdate(int interfaceID, int statusFlags, ErrorCode *errorCodes);
StatusUpdate* getStatusUpdate(int interfaceID);
LRUCache* createCache(int capacity);
void putCache(LRUCache *cache, StatusUpdate *update);
StatusUpdate* getFromCache(LRUCache *cache, int interfaceID);

// Function to add or update a status update
void addOrUpdateStatusUpdate(int interfaceID, int statusFlags, ErrorCode *errorCodes) {
    pthread_rwlock_wrlock(&rwlock);

    StatusUpdate *current = statusUpdatesHead;
    while (current != NULL && current->interfaceID != interfaceID) {
        current = current->next;
    }

    time_t now = time(NULL);
    if (current == NULL) {
        // Add new update
        current = malloc(sizeof(StatusUpdate));
        current->timestamp = now;
        current->interfaceID = interfaceID;
        current->statusFlags = statusFlags;

        ErrorCode *headError = errorCodes; 
        while (headError != NULL && headError->next != NULL) {
            headError = headError->next;
        }
        current->errorCodes = errorCodes;

        current->next = statusUpdatesHead;
        statusUpdatesHead = current;
    } else {
        // Update existing update
        current->statusFlags = statusFlags;
        current->timestamp = now;

        ErrorCode *headError = errorCodes; 
        while (headError != NULL && headError->next != NULL) {
            headError = headError->next;
        }
        current->errorCodes = errorCodes;
    }

    pthread_rwlock_unlock(&rwlock);
}

// Function to retrieve a status update by interface ID
StatusUpdate* getStatusUpdate(int interfaceID) {
    pthread_rwlock_rdlock(&rwlock);

    StatusUpdate *current = statusUpdatesHead;
    while (current != NULL && current->interfaceID != interfaceID) {
        current = current->next;
    }

    pthread_rwlock_unlock(&rwlock);
    return current;
}

// Function to create a new LRU cache
LRUCache* createCache(int capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->count = 0;
    cache->head = NULL;
    cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Function to insert an update into the cache
void putCache(LRUCache *cache, StatusUpdate *update) {
    pthread_mutex_lock(&cache->lock);

    CacheNode **currentNode = &cache->head;

    while (*currentNode != NULL && (*currentNode)->update->interfaceID != update->interfaceID) {
        currentNode = &(*currentNode)->next;
    }

    if (*currentNode == NULL) {
        // Add new node
        CacheNode *newNode = malloc(sizeof(CacheNode));
        newNode->update = update;

        if (cache->count == cache->capacity) {
            // Evict the least recently used item
            CacheNode *oldTail = cache->tail;
            cache->tail = oldTail->prev;
            if (cache->tail != NULL) {
                cache->tail->next = NULL;
            }
            free(oldTail);
            cache->count--;
        }

        newNode->prev = NULL;
        newNode->next = cache->head;

        if (cache->head != NULL) {
            cache->head->prev = newNode;
        }

        cache->head = newNode;
        if (cache->tail == NULL) {
            cache->tail = newNode;
        }

        cache->count++;
    } else {
        // Move the accessed node to the head
        CacheNode *nodeToUpdate = *currentNode;

        if (nodeToUpdate != cache->head) {
            if (nodeToUpdate->prev != NULL) {
                nodeToUpdate->prev->next = nodeToUpdate->next;
            }
            if (nodeToUpdate->next != NULL) {
                nodeToUpdate->next->prev = nodeToUpdate->prev;
            }

            if (nodeToUpdate == cache->tail) {
                cache->tail = nodeToUpdate->prev;
            }

            nodeToUpdate->prev = NULL;
            nodeToUpdate->next = cache->head;

            if (cache->head != NULL) {
                cache->head->prev = nodeToUpdate;
            }
            cache->head = nodeToUpdate;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

// Function to retrieve an update from the cache
StatusUpdate* getFromCache(LRUCache *cache, int interfaceID) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *current = cache->head;

    while (current != NULL && current->update->interfaceID != interfaceID) {
        current = current->next;
    }

    if (current == NULL) {
        StatusUpdate *result = NULL;
        goto unlock_and_return;
    } else {
        // Move the accessed node to the head
        if (current != cache->head) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }

            if (current == cache->tail) {
                cache->tail = current->prev;
            }

            current->prev = NULL;
            current->next = cache->head;

            if (cache->head != NULL) {
                cache->head->prev = current;
            }
            cache->head = current;
        }

        StatusUpdate *result = current->update;
    unlock_and_return:
        pthread_mutex_unlock(&cache->lock);
        return result;
    }
}

// Main function for demonstration purposes (to be removed in production)
int main() {
    LRUCache *cache = createCache(100);

    ErrorCode err1 = {404, "Not Found", NULL};
    addOrUpdateStatusUpdate(1, 0, &err1);

    StatusUpdate *update = getStatusUpdate(1);
    if (update != NULL) {
        printf("Interface %d - Status: %d\n", update->interfaceID, update->statusFlags);
    }

    putCache(cache, update);

    StatusUpdate *cachedUpdate = getFromCache(cache, 1);
    if (cachedUpdate != NULL) {
        printf("Cached Interface %d - Status: %d\n", cachedUpdate->interfaceID, cachedUpdate->statusFlags);
    }

    // Free resources here as appropriate
    return 0;
}
