typedef enum { SUCCESS, FILE_ERROR, PARSE_ERROR, BUFFER_OVERFLOW, MEMORY_ERROR } StatusCode;

static pthread_mutex_t bufferMutex = PTHREAD_MUTEX_INITIALIZER;
static SensorConfigTag* targetBuffer = NULL;
static size_t bufferSize = 0;

int reloadConfigurationIfNeeded(const char* filePath) {
    // Implement logic to check if the file has changed and reload configuration
    return 1; // Return 1 if reloaded, 0 otherwise
}

StatusCode parseSensorFile(const char* filePath, SensorConfigTag** buffer, size_t* bufferSize, time_t threshold) {
    FILE* file = fopen(filePath, "r");
    if (!file) return FILE_ERROR;

    char line[256];
    *buffer = (SensorConfigTag*)malloc(MAX_BUFFER_SIZE * sizeof(SensorConfigTag));
    if (!*buffer) {
        fclose(file);
        return MEMORY_ERROR;
    }

    size_t count = 0;
    while (fgets(line, sizeof(line), file)) {
        SensorConfigTag tag;
        time_t timestamp;
        sscanf(line, "%49[^ ] %99[^\n] %ld", tag.tag, tag.value, &timestamp);

        if ((strcmp(tag.tag, "SENSOR_CONFIG_TAG") == 0 ||
             strcmp(tag.tag, "MEASUREMENT_UNIT_TAG") == 0 ||
             strcmp(tag.tag, "DATA_RATE_TAG") == 0) &&
            timestamp >= threshold) {

            (*buffer)[count++] = tag;
            if (count >= MAX_BUFFER_SIZE) break;
        }
    }

    fclose(file);
    *bufferSize = count;
    return (count > 0) ? SUCCESS : PARSE_ERROR;
}

StatusCode processSensorData(const char* filePath, size_t targetBufferSize, time_t timestampThreshold) {
    pthread_mutex_lock(&bufferMutex);

    if (reloadConfigurationIfNeeded(filePath)) {
        // Reload logic handled
    }

    StatusCode status = parseSensorFile(filePath, &targetBuffer, &bufferSize, timestampThreshold);
    if (status != SUCCESS) {
        free(targetBuffer);
        pthread_mutex_unlock(&bufferMutex);
        return status;
    }

    if (bufferSize > targetBufferSize) {
        // Handle buffer overflow: resize or truncate
        size_t newSize = bufferSize > targetBufferSize ? targetBufferSize : bufferSize;
        SensorConfigTag* newBuffer = (SensorConfigTag*)realloc(targetBuffer, newSize * sizeof(SensorConfigTag));
        if (!newBuffer) {
            free(targetBuffer);
            pthread_mutex_unlock(&bufferMutex);
            return MEMORY_ERROR;
        }
        targetBuffer = newBuffer;
        bufferSize = newSize;
    }

    // Log critical events
    printf("Buffer populated with %zu entries.\n", bufferSize);

    pthread_mutex_unlock(&bufferMutex);
    return SUCCESS;
}
