#define MAX_USERS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { SYNC, ASYNC } ProcessingMode;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int max_concurrent_sessions = MAX_USERS;
static void (*callback)(NFAPI_CRC_INDICATION_PDU_T*) = NULL;

void set_max_concurrent_sessions(int max_sessions) {
    pthread_mutex_lock(&lock);
    if (max_sessions > 0 && max_sessions <= MAX_USERS) {
        max_concurrent_sessions = max_sessions;
    }
    pthread_mutex_unlock(&lock);
}

int fetch_user_data(int index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simulate fetching user data
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 10000;

    return 0; // Success
}

void log_message(const char *message) {
    printf("%s\n", message);
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T **pdus, int num_users) {
    if (pdus && *pdus) {
        free(*pdus);
        *pdus = NULL;
        log_message("Memory freed successfully.");
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(int num_users, ProcessingMode mode, void (*cb)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&lock);

    if (num_users > max_concurrent_sessions) {
        log_message("Request exceeds maximum concurrent sessions.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    log_message("Memory allocated successfully.");

    for (int i = 0; i < num_users; ++i) {
        int fetch_success = fetch_user_data(i, &pdus[i]);
        if (fetch_success != 0) {
            cleanup(&pdus, num_users);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    if (mode == ASYNC && cb != NULL) {
        callback = cb;
        log_message("Async mode enabled with callback.");
        pthread_mutex_unlock(&lock);

        for (int i = 0; i < num_users; ++i) {
            (*callback)(&pdus[i]);
        }
    } else {
        log_message("Synchronous processing completed.");
        pthread_mutex_unlock(&lock);
    }

    return pdus;
}

void process_pdus(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Process the PDU
    printf("Processing PDU with RX_UE_INFORMATION_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG);
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* pdus = allocate_pdus(5000, SYNC, NULL);
    if (pdus) {
        for (int i = 0; i < 5000; ++i) {
            process_pdus(&pdus[i]);
        }
        cleanup(&pdus, 5000);
    }

    set_max_concurrent_sessions(8000);

    pdus = allocate_pdus(7000, ASYNC, process_pdus);
    if (pdus) {
        // In async mode, the callback will handle processing
        sleep(1); // Simulate wait time for async processing
        cleanup(&pdus, 7000);
    }

    return 0;
}
