int buffer_pool_index = 0;
pthread_mutex_t buffer_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Logging function with different verbosity levels
void log_message(int level, const char *message) {
    if (level <= LOG_LEVEL_INFO) {
        printf("%s\n", message);
    }
}

