    if (load_resource_bundle(argv[1], &num_items) != 0) {
        return EXIT_FAILURE;
    }

    init_session_array();

    char *buffer = get_buffer_from_pool();
    if (buffer) {
        strcpy(buffer, "Temporary data");
        release_buffer_to_pool(buffer);
    }

    log_message(LOG_LEVEL_INFO, "Application running successfully.");
    return EXIT_SUCCESS;
}
