int compare_pci(const void *a, const void *b) {
    const LteDlCipdu *pdu_a = a;
    const LteDlCipdu *pdu_b = b;
    return (pdu_a->pci - pdu_b->pci);
}

// Error logging function
void log_error(const char *message) {
