}

// Validate CIC indicator (dummy validation for demonstration)
bool validate_cic_indicator(unsigned char cic_flag) {
    // Implement real validation logic
    return true;  // Assume all indicators are valid for this example
}

typedef struct {
    LteDlCipdu *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PduList;

// Function to initialize the PDU list
bool init_pdu_list(PduList *list, size_t initial_capacity) {
    if (!list || initial_capacity == 0) return false;

    list->pdus = (LteDlCipdu *)malloc(initial_capacity * sizeof(LteDlCipdu));
    if (!list->pdus) {
        log_error("Failed to allocate memory for PDU list");
        return false;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return true;
}

// Function to add a new PDU to the list
bool add_pdu(PduList *list, int pci, unsigned char cic_flag) {
    if (!list || !validate_cic_indicator(cic_flag)) return false;

    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LteDlCipdu *new_pdus = (LteDlCipdu *)realloc(list->pdus, new_capacity * sizeof(LteDlCipdu));
        if (!new_pdus) {
            log_error("Failed to reallocate memory for PDU list");
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    LteDlCipdu *pdu = &list->pdus[list->count++];
    pdu->pci = pci;
    pdu->cic_flag = cic_flag;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to sort the list by PCI
void sort_pdu_list(PduList *list) {
    if (!list || !list->pdus) return;

    pthread_mutex_lock(&list->lock);

    qsort(list->pdus, list->count, sizeof(LteDlCipdu), compare_pci);

    pthread_mutex_unlock(&list->lock);
}

// Function to free the PDU list
void free_pdu_list(PduList *list) {
    if (!list) return;

    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    PduList pdu_list;
    if (!init_pdu_list(&pdu_list, 10)) {
        log_error("Initialization failed");
        return EXIT_FAILURE;
    }

    // Example usage: adding PDUs
    for (int i = 0; i < 10000; ++i) { // Add a lot of items
        int pci = rand() % 1024;       // Random PCI example
        unsigned char cic_flag = rand() % 256; // Random CIC flag
        if (!add_pdu(&pdu_list, pci, cic_flag)) {
            log_error("Failed to add PDU");
        }
    }

    sort_pdu_list(&pdu_list);

    // Cleanup
    free_pdu_list(&pdu_list);
    return EXIT_SUCCESS;
}
