LTE_UE_Context* add_ue_context(LTE_UE_Context_Collection* collection) {
    pthread_rwlock_wrlock(&collection->rwlock);

    if (collection->size == collection->capacity) {
        // Resize array when capacity is reached
        size_t new_capacity = collection->capacity * 2;
        LTE_UE_Context* new_ue_contexts = (LTE_UE_Context*)realloc(collection->ue_contexts, new_capacity * sizeof(LTE_UE_Context));
        if (!new_ue_contexts) {
            pthread_rwlock_unlock(&collection->rwlock);
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }
        collection->ue_contexts = new_ue_contexts;
        collection->capacity = new_capacity;
    }

    LTE_UE_Context* ue_context = &collection->ue_contexts[collection->size++];

    pthread_mutex_init(&ue_context->lock, NULL);

