    for (size_t i = 0; i < collection->size; ++i) {
        pthread_mutex_destroy(&collection->ue_contexts[i].lock);
    }

    free(collection->ue_contexts);
    pthread_rwlock_unlock(&collection->rwlock);

    pthread_rwlock_destroy(&collection->rwlock);
