#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example limit of 1MB

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t max_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->head = NULL;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    // Initialize the memory pool with pre-allocated nodes
    size_t node_size = sizeof(Node);
    char* mem_block = (char*)malloc(max_size);

    if (!mem_block) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < max_size / node_size; ++i) {
        Node* new_node = (Node*)(mem_block + i * node_size);
        new_node->next = pool->head;
        pool->head = new_node;
    }

    return pool;
}

void free_memory_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->head); // Free the entire block of memory
    free(pool);
}

Node* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (!pool->head) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // No available nodes
    }

    Node* node = pool->head;
    pool->head = node->next;
    pool->size++;

    pthread_mutex_unlock(&pool->lock);
    return node;
}

void deallocate_to_pool(MemoryPool* pool, Node* node) {
    pthread_mutex_lock(&pool->lock);

    node->next = pool->head;
    pool->head = node;
    pool->size--;

    pthread_mutex_unlock(&pool->lock);
}

bool is_unique(NFAPI_CRC_INDICATION_PDU_T new_pdu, Node** head) {
    for (Node* current = *head; current != NULL; current = current->next) {
        if ((current->data.RNTI == new_pdu.RNTI) && 
            (current->data.CRCFLAG == new_pdu.CRCFLAG)) {
            return false;
        }
    }
    return true;
}

void log_error(const char* message) {
    // Simplified logging function for demonstration
    fprintf(stderr, "ERROR: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pi_crc_list(int num_elements, size_t memory_limit,
                                                    bool output_compatible_format) {

    if (memory_limit > MAX_MEMORY_USAGE) {
        log_error("Memory limit exceeds maximum allowed usage.");
        return NULL;
    }

    MemoryPool* pool = create_memory_pool(memory_limit);
    if (!pool) {
        log_error("Failed to create memory pool.");
        return NULL;
    }

    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
    Node* head = NULL;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_elements; ++i) {
        Node* node = allocate_from_pool(pool);
        if (!node) {
            log_error("Failed to allocate from memory pool.");
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu.RNTI = rand() % 4096; // Example RNTI range
        pdu.CRCFLAG = rand() & 1;

        pthread_mutex_lock(&list_lock);

        if (is_unique(pdu, &head)) {
            node->data = pdu;
            node->next = head;
            head = node;
        } else {
            deallocate_to_pool(pool, node); // Ensure uniqueness
        }

        pthread_mutex_unlock(&list_lock);
    }

    // Convert linked list to array for external module compatibility if needed
    NFAPI_CRC_INDICATION_PDU_T* result_array = NULL;
    if (output_compatible_format) {
        int array_size = 0;
        Node* current = head;

        while (current) {
            array_size++;
            current = current->next;
        }

        result_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!result_array) {
            log_error("Failed to allocate memory for output array.");
            return NULL;
        }

        int index = 0;
        current = head;

        while (current) {
            result_array[index++] = current->data;
            Node* temp = current;
            current = current->next;
            deallocate_to_pool(pool, temp);
        }
    }

    free_memory_pool(pool);

    // Return the array or NULL if output_compatible_format is false
    return result_array;
}

int main() {
    int num_elements = 1000; // Example number of elements to generate
    size_t memory_limit = 1024 * 512; // Set memory limit (e.g., 512KB)
    bool compatible_output = true;

    NFAPI_CRC_INDICATION_PDU_T* list = generate_nfa_pi_crc_list(num_elements, memory_limit, compatible_output);

    if (list) {
        for (int i = 0; list[i].RNTI != 0 || list[i].CRCFLAG != 0; ++i) { // Assuming all RNTIs and CRCFLAGS are non-zero
            printf("RNTI: %u, CRCFLAG: %u\n", list[i].RNTI, list[i].CRCFLAG);
        }
        free(list);
    }

    return 0;
}
