#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint8_t RNTI[5];
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;  // Random flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    uint64_t count;
} LinkedList;

// Function prototypes
LinkedList* create_linked_list();
void destroy_linked_list(LinkedList* list);
int populate_linked_list(LinkedList* list, int num_elements);
int serialize_linked_list(const char* filename, const LinkedList* list);
int deserialize_linked_list(const char* filename, LinkedList* list);
int iterate_and_toggle_CRCFLAG(LinkedList* list);

// Function definitions
LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int populate_linked_list(LinkedList* list, int num_elements) {
    if (!list || num_elements <= 0) return -1;

    for (int i = 0; i < num_elements; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            destroy_linked_list(list);
            return -2;
        }

        // Populate with dummy data and validate
        memset(&new_node->data.ue_info.RNTI, 0x01, sizeof(new_node->data.ue_info.RNTI));  // Dummy RNTI
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 10000;
        new_node->data.CRCFLAG = rand() % 2;

        pthread_mutex_lock(&list->lock);
        new_node->next = list->head;
        list->head = new_node;
        ++(list->count);
        pthread_mutex_unlock(&list->lock);
    }

    return (int)list->count;
}

int serialize_linked_list(const char* filename, const LinkedList* list) {
    if (!filename || !list) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -2;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

int deserialize_linked_list(const char* filename, LinkedList* list) {
    if (!filename || !list) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -2;

    destroy_linked_list(list);

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fclose(file);
            return -3;
        }

        new_node->data = data;
        pthread_mutex_lock(&list->lock);
        new_node->next = list->head;
        list->head = new_node;
        ++(list->count);
        pthread_mutex_unlock(&list->lock);
    }

    fclose(file);
    return (int)list->count;
}

int iterate_and_toggle_CRCFLAG(LinkedList* list) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        current->data.CRCFLAG = !current->data.CRCFLAG;  // Toggle CRCFLAG
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int main() {
    LinkedList* list = create_linked_list();
    if (!list) {
        fprintf(stderr, "Failed to create linked list.\n");
        return -1;
    }

    int num_structs = populate_linked_list(list, 100);
    if (num_structs < 0) {
        destroy_linked_list(list);
        fprintf(stderr, "Failed to populate linked list.\n");
        return -2;
    }

    const char* filename = "linked_list.bin";
    serialize_linked_list(filename, list);

    LinkedList* new_list = create_linked_list();
    if (!new_list || deserialize_linked_list(filename, new_list) < 0) {
        destroy_linked_list(list);
        destroy_linked_list(new_list);
        fprintf(stderr, "Failed to deserialize linked list.\n");
        return -3;
    }

    printf("Number of structures in the linked list: %d\n", (int)new_list->count);

    iterate_and_toggle_CRCFLAG(new_list);

    destroy_linked_list(list);
    destroy_linked_list(new_list);

    return 0;
}
