#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_MEMORY_BUDGET 1024 * 1024 // Example: 1MB

typedef struct {
    uint16_t rnti;
    uint8_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used;
    size_t max_rntis;
    pthread_mutex_t lock;
    uint32_t memory_used;
} CRC_POOL;

CRC_POOL* create_crc_pool(size_t initial_size, size_t max_rntis) {
    CRC_POOL *crc_pool = (CRC_POOL *)malloc(sizeof(CRC_POOL));
    if (!crc_pool) return NULL;

    crc_pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_pool->pool) {
        free(crc_pool);
        return NULL;
    }

    crc_pool->pool_size = initial_size;
    crc_pool->used = 0;
    crc_pool->max_rntis = max_rntis;
    pthread_mutex_init(&crc_pool->lock, NULL);
    crc_pool->memory_used = initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return crc_pool;
}

void destroy_crc_pool(CRC_POOL *crc_pool) {
    if (!crc_pool) return;

    pthread_mutex_destroy(&crc_pool->lock);
    free(crc_pool->pool);
    free(crc_pool);
}

int add_crc_pdu(CRC_POOL *crc_pool, uint16_t rnti, uint8_t crcflag) {
    if (!crc_pool || crc_pool->memory_used >= MAX_MEMORY_BUDGET) return -1;

    pthread_mutex_lock(&crc_pool->lock);

    for (size_t i = 0; i < crc_pool->used; ++i) {
        if (crc_pool->pool[i].crc_tag.crcflag == crcflag &&
            crc_pool->pool[i].crc_tag.rnti == rnti) {
            pthread_mutex_unlock(&crc_pool->lock);
            return -1;
        }
    }

    if (crc_pool->used >= crc_pool->max_rntis) {
        pthread_mutex_unlock(&crc_pool->lock);
        return -1;
    }

    size_t index = crc_pool->used++;
    crc_pool->pool[index].crc_tag.rnti = rnti;
    crc_pool->pool[index].crc_tag.crcflag = crcflag;

    if (crc_pool->used > crc_pool->pool_size) {
        size_t new_size = crc_pool->pool_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crc_pool->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&crc_pool->lock);
            return -1;
        }
        crc_pool->pool = new_pool;
        crc_pool->pool_size = new_size;
        crc_pool->memory_used += (new_size - crc_pool->pool_size / 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_mutex_unlock(&crc_pool->lock);
    return 0;
}

void export_crc_pool(const CRC_POOL *crc_pool, const char *filename) {
    if (!crc_pool || !filename) return;

    FILE *file = fopen(filename, "w");
    if (!file) return;

    for (size_t i = 0; i < crc_pool->used; ++i) {
        fprintf(file, "RNTI: %u, CRCFLAG: %u\n", crc_pool->pool[i].crc_tag.rnti, crc_pool->pool[i].crc_tag.crcflag);
    }

    fclose(file);
}

int main() {
    CRC_POOL *crc_pool = create_crc_pool(10, 100);

    if (!crc_pool) {
        printf("Failed to create CRC pool\n");
        return -1;
    }

    for (uint16_t i = 0; i < 50; ++i) {
        uint8_t crcflag = rand() % 256;
        int result = add_crc_pdu(crc_pool, i, crcflag);
        if (result != 0) {
            printf("Failed to add CRC PDU\n");
            break;
        }
    }

    export_crc_pool(crc_pool, "crc_data.txt");

    destroy_crc_pool(crc_pool);

    return 0;
}
