    list->files = (FileMetadata**)calloc(capacity, sizeof(FileMetadata*));
    list->count = 0;
    list->capacity = capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_file_list(FileList* list, MemoryPool* pool) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->files[i]->identifier);
        free(list->files[i]->name);
        free(list->files[i]);
    }
    free(list->files);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_file_metadata(FileList* list, FileMetadata* metadata, MemoryPool* pool) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        FileMetadata** new_files = (FileMetadata**)realloc(list->files, new_capacity * sizeof(FileMetadata*));
        if (!new_files) {
            pthread_mutex_unlock(&list->lock);
            return; // Allocation failed
        }
        list->files = new_files;
        list->capacity = new_capacity;
    }

    metadata->identifier = strdup(metadata->name); // Simplified for example purposes
    list->files[list->count++] = metadata;

    pthread_mutex_unlock(&list->lock);
}

void rename_and_process_files(FileList* list, ExtensionSet* extensions, MemoryPool* pool) {
    for (size_t i = 0; i < list->count; ++i) {
        FileMetadata* file = list->files[i];

        char* sanitized_name = sanitize_filename(file->name, MAX_FILENAME_LENGTH);
        const char* new_ext = select_random_extension(extensions);

        size_t sequence = generate_sequence_from_size_time(file->size);
        snprintf(sanitized_name + strlen(sanitized_name) - 4, 12, "_%zu%s", sequence, new_ext); // Assuming .xxx extension

        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(pool);
        if (!pdu) continue; // Handle allocation failure
        pdu->RX_UE_INFORMATION_TAG = rand(); // Example assignment
        pdu->RNTI = rand() & 0xFFFF;
        pdu->CRCFLAG = rand() % 2;

        free(sanitized_name); // Free or handle as needed
    }
}

char* sanitize_filename(const char* original, size_t max_length) {
    static char buffer[MAX_FILENAME_LENGTH + 1];
    const char* invalid_chars = " <>:\"/\\|?*";
    char* sanitized = buffer;
    const char* src;

    for (src = original; *src && sanitized < &buffer[max_length - 1]; ++src, ++sanitized) {
        if (strchr(invalid_chars, *src)) {
            *sanitized = '_';
        } else {
            *sanitized = *src;
        }
    }

    if (sanitized >= &buffer[max_length]) {
        *--sanitized = '\0'; // Truncate to fit
    } else {
        *sanitized = '\0';
    }

    return buffer;
}

const char* select_random_extension(ExtensionSet* extensions) {
    int index = rand() % NUM_EXTENSIONS;
    return extensions->extensions[index];
}

uint32_t generate_sequence_from_size_time(size_t size) {
    uint64_t current_time_ms = (uint64_t)(time(NULL) * 1000);
    return ((current_time_ms & 0xFFFFFFFF) ^ (size & 0xFFFFFFFF));
}

int main() {
    srand(time(NULL));

    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), 1024); // Example setup
    if (!pool) return EXIT_FAILURE;

    FileList* fileList = create_file_list(10);
    if (!fileList) {
        destroy_memory_pool(pool);
        return EXIT_FAILURE;
    }

    ExtensionSet extensions = { (const char*[]){"txt", "jpg", "png", "gif"} };

    // Example metadata
    FileMetadata file1 = {"id1", "example_file_1.txt", 1024, time(NULL)};
    add_file_metadata(fileList, &file1, pool);

    rename_and_process_files(fileList, &extensions, pool);

    destroy_file_list(fileList, pool);
    destroy_memory_pool(pool);

    return EXIT_SUCCESS;
}
