uint32_t generate_sequence_number() {
    pthread_mutex_lock(&seq_manager.lock);
    uint64_t seq_num = seq_manager.sequence_number++;
    pthread_mutex_unlock(&seq_manager.lock);
    return (uint32_t)seq_num;
}

void process_event(uint64_t timestamp, NFAPI_CRC_INDICATION_PDU_T* crc_list, size_t* crc_count,
                   NFAPI_RX_INDICATION_PDU_T* rx_list, size_t* rx_count) {
    if (*crc_count >= MAX_STRUCTS || *rx_count >= MAX_STRUCTS) return;

    uint32_t rnti = rand() % 65536;
    uint32_t ue_tag = rand() % UINT32_MAX;

    // CRC Indication PDU
