    crc_list[*crc_count].RNTI = rnti;
    crc_list[*crc_count].CRC_INDICATION_REL8_TAG = rand() % 256;
    (*crc_count)++;

    // RX Indication PDU
    rx_list[*rx_count].RX_UE_INFORMATION_TAG = ue_tag;
    rx_list[*rx_count].RNTI = rnti;
    size_t payload_size = (rand() % MAX_PAYLOAD_SIZE) + 1;
    for (size_t i = 0; i < payload_size; ++i) {
        rx_list[*rx_count].rx_pdu.payload[i] = rand() % 256;
    }
    (*rx_count)++;
}

double calculate_average_time_difference(uint64_t* timestamps, size_t count) {
    if (count < 2) return 0.0;

    uint64_t total_diff = 0;
    for (size_t i = 1; i < count; ++i) {
        total_diff += timestamps[i] - timestamps[i - 1];
    }
    return (double)total_diff / (count - 1);
}

void manage_stream(uint64_t* timestamps, size_t timestamp_count,
                   NFAPI_CRC_INDICATION_PDU_T* crc_list, NFAPI_RX_INDICATION_PDU_T* rx_list) {
    size_t crc_count = 0;
    size_t rx_count = 0;

    for (size_t i = 0; i < timestamp_count; ++i) {
        process_event(timestamps[i], crc_list, &crc_count, rx_list, &rx_count);
    }

    double avg_time_diff = calculate_average_time_difference(timestamps, timestamp_count);
    printf("Average time difference: %f\n", avg_time_diff);
}

int main() {
    size_t num_events = 1000; // Example number of events
    uint64_t* timestamps = (uint64_t*)malloc(num_events * sizeof(uint64_t));
    NFAPI_CRC_INDICATION_PDU_T* crc_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_STRUCTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_RX_INDICATION_PDU_T* rx_list = (NFAPI_RX_INDICATION_PDU_T*)calloc(MAX_STRUCTS, sizeof(NFAPI_RX_INDICATION_PDU_T));

    if (!timestamps || !crc_list || !rx_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
