pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to populate the list of structures
int populate_nfa_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t max_structures, size_t byte_limit) {
    if (max_structures <= 0 || byte_limit <= 0) {
        fprintf(stderr, "Invalid parameters: M and L must be positive.\n");
        return -1;
    }

    // Calculate the maximum number of structures that can fit in the given memory
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t max_possible_structures = byte_limit / struct_size;

    pthread_mutex_lock(&list_mutex);

    // Adjust the number of structures to fit within the memory constraint
    size_t num_structures = (max_structures < max_possible_structures) ? max_structures : max_possible_structures;
    if (num_structures == 0) {
        fprintf(stderr, "No memory available for any structures.\n");
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    // Allocate memory for the list
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * struct_size);
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    // Populate the list with structures
    for (size_t i = 0; i < num_structures; ++i) {
