        // Set CRCFLAG randomly
        (*list)[i].crc_indication_rel8_tag.CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    pthread_mutex_unlock(&list_mutex);
    return 0;
}

// Example usage of the function
