LTE_PHY_RX_FRAME* InitializeLTEFrameData(int num_frames, int rf_chains_per_frame, 
                                         int symbols_per_rf_chain, int rssi_min, int rssi_max) {
    // Allocate memory for the frames
    LTE_PHY_RX_FRAME* frames = malloc(num_frames * sizeof(LTE_PHY_RX_FRAME));

    srand(time(NULL));  // Seed the random number generator

    for (int i = 0; i < num_frames; ++i) {
        for (int j = 0; j < rf_chains_per_frame; ++j) {
            LTE_PHY_RX_FRAME* frame = &frames[i];

            // Initialize PDU_TAG and RF_CHAIN_ID
            frame->PDU_TAG = rand() % 1000 + 1;  // Example logic for generating a PDU tag
            frame->RF_CHAIN_ID = j;
            frame->symbol_count = symbols_per_rf_chain;

            // Allocate memory for the symbols array
            frame->symbols = malloc(symbols_per_rf_chain * sizeof(LTE_PHY_RX_SYMBOL_TAG));

            for (int k = 0; k < symbols_per_rf_chain; ++k) {
                LTE_PHY_RX_SYMBOL_TAG* symbol = &frame->symbols[k];

                // Initialize OFDM_SYMBOL_INDEX and randomly generate RSSI
                symbol->OFDM_SYMBOL_INDEX = k;
                symbol->RSSI = rssi_min + (rand() % (rssi_max - rssi_min + 1));
            }
        }
    }

    return frames;  // Return the array of initialized frames
