public class SqlCommandCreator
{
    public static IDataReader CreateParameterizedSqlCommand(SqlConnection connection, 
                                                            string commandText, 
                                                            List<object> parameters)
    {
        using (SqlCommand command = new SqlCommand(commandText, connection))
        {
            // Add each parameter to the SQL command
            for (int i = 0; i < parameters.Count; i++)
            {
                SqlParameter param = new SqlParameter($"@p{i}", parameters[i]);
                command.Parameters.Add(param);
            }

            // Open the connection if it's not already open
            if (connection.State != ConnectionState.Open)
            {
                connection.Open();
            }

            return command.ExecuteReader(CommandBehavior.CloseConnection);  // Ensure the connection closes when done
        }
    }
}
