#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_POOL_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int ID; // Assume this is a valid tag
    int CRC32;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool[MAX_POOL_SIZE];
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memoryPool = {.count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};

void log_message(const char *message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t N) {
    pthread_mutex_lock(&memoryPool.lock);

    if (memoryPool.count + N > MAX_POOL_SIZE) {
        pthread_mutex_unlock(&memoryPool.lock);
        log_message("Memory pool capacity exceeded.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_unlock(&memoryPool.lock);
        log_message("Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].ID = rand() % 1000; // Assume valid tag
        array[i].CRC32 = rand(); // Random CRC value

        array[i].crcIndicationRel8Tag.RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].crcIndicationRel8Tag.RNTI = rand() % 100;

        array[i].crcIndicationRel8Tag.crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Random CRC flag

        memoryPool.pool[memoryPool.count++] = &array[i];
    }

    log_message("Memory allocated and initialized.");
    pthread_mutex_unlock(&memoryPool.lock);
    return array;
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    if (!array) return;

    pthread_mutex_lock(&memoryPool.lock);

    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < memoryPool.count; ++j) {
            if (memoryPool.pool[j] == &array[i]) {
                memoryPool.pool[j] = NULL;
                break;
            }
        }
    }

    memoryPool.count -= N;
    free(array);
    log_message("Memory deallocated.");
    pthread_mutex_unlock(&memoryPool.lock);
}

void validate_data(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        if (array[i].ID <= 0 || array[i].CRC32 <= 0 ||
            array[i].crcIndicationRel8Tag.RX_UE_INFORMATION_TAG <= 0 ||
            array[i].crcIndicationRel8Tag.RNTI <= 0) {
            log_message("Data validation failed.");
            exit(EXIT_FAILURE);
        }
    }
}

void initialize_random_seed() {
    srand(time(NULL));
}

int main() {
    initialize_random_seed();

    size_t N = 10; // Example user input
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_memory(N);

    if (array) {
        validate_data(array, N);
        // Use the array for further processing...
        free_memory(array, N);
    }

    return 0;
}
