// Pool allocation strategy
typedef struct {
    size_t element_size;
    size_t pool_size;
    void **pool;
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t pool_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->element_size = element_size;
    mp->pool_size = pool_size;
    mp->pool = (void**)calloc(pool_size, sizeof(void*));

    if (!mp->pool) {
        free(mp);
        log_error("Memory allocation failed for memory pool");
        return NULL;
    }

    for (size_t i = 0; i < pool_size; ++i) {
        mp->pool[i] = malloc(element_size);
        if (!mp->pool[i]) {
            log_error("Memory allocation failed in pool initialization");
            // Free previously allocated elements
            for (size_t j = 0; j < i; ++j)
                free(mp->pool[j]);
            free(mp->pool);
            free(mp);
            return NULL;
        }
    }

    return mp;
}

void destroy_memory_pool(MemoryPool* mp) {
    if (!mp) return;

    for (size_t i = 0; i < mp->pool_size; ++i)
        free(mp->pool[i]);
    free(mp->pool);
    free(mp);
}

typedef struct {
    pthread_mutex_t lock;
    MemoryPool *memory_pool;
} NFAPI_CRC_INDICATION_MANAGER_T;

NFAPI_CRC_INDICATION_MANAGER_T* create_manager(size_t num_structures) {
    NFAPI_CRC_INDICATION_MANAGER_T *manager = (NFAPI_CRC_INDICATION_MANAGER_T*)malloc(sizeof(NFAPI_CRC_INDICATION_MANAGER_T));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->memory_pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), num_structures);

    if (!manager->memory_pool) {
        log_error("Failed to create memory pool");
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_manager(NFAPI_CRC_INDICATION_MANAGER_T *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        destroy_memory_pool(manager->memory_pool);
        free(manager);
    }
}

int validate_structures(const NFAPI_CRC_INDICATION_PDU_T *structs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (structs[i].crc_tag.RX_UE_INFORMATION_TAG <= 0 || structs[i].crc_tag.RNTI <= 0) {
            log_error("Validation failed: Invalid RX_UE_INFORMATION_TAG or RNTI");
            return -1;
        }
    }
    return 0;
}

int manage_nfa_cris(NFAPI_CRC_INDICATION_MANAGER_T *manager, size_t num_structures, NFAPI_CRC_INDICATION_PDU_T **result) {
    if (!manager || !result || num_structures == 0 || num_structures > MAX_STRUCTURES) {
        log_error("Invalid parameters or exceeded maximum structures limit");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T *structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
    if (!structures) {
        log_error("Memory allocation failed for structures");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Populate the structures
    for (size_t i = 0; i < num_structures; ++i) {
        struct CRC_INDICATION_REL8_TAG *crc_tag = &structures[i].crc_tag;
        crc_tag->RX_UE_INFORMATION_TAG = rand() % 100 + 1; // Random positive value
        crc_tag->RNTI = rand() % 1000 + 1;                 // Random positive value
        structures[i].CRCFLAG = rand() % 2;                // Random binary value
    }

    int validation_status = validate_structures(structures, num_structures);
    if (validation_status != 0) {
        free(structures);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    *result = structures;
    pthread_mutex_unlock(&manager->lock);

    // Log successful management
    printf("Successfully managed %zu NFAPI_CRC_INDICATION_PDU_T structures\n", num_structures);

    return 0;
}

