#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFO;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_INFO ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned long total_crc_processed = 0;

// Function to generate a random value
int generate_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Thread-safe function to increment CRC processed count
void increment_crc_count(unsigned long *count) {
    pthread_mutex_lock(&lock);
    (*count)++;
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t n, int *status) {
    if (n <= 0) {
        printf("Warning: Invalid input value for N\n");
        *status = -1;
        return NULL;
    }

    size_t chunk_size = 10; // Start with a reasonable initial chunk size
    size_t current_size = chunk_size;
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        perror("Failed to allocate memory");
        *status = -2;
        return NULL;
    }

    size_t filled_count = 0;

    while (filled_count < n) {
        for (size_t i = filled_count; i < current_size && filled_count < n; ++i) {
            array[i].ue_info.RX_UE_INFORMATION_TAG = generate_random_value(1, 10000);
            array[i].ue_info.RNTI = generate_random_value(1, 5000);
            array[i].crc_tag.CRCFLAG = rand() % 2;
            increment_crc_count(&total_crc_processed);
        }

        filled_count = current_size;

        if (filled_count < n) {
            NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, (current_size + chunk_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!new_array) {
                perror("Failed to reallocate memory");
                free(array);
                *status = -3;
                return NULL;
            }

            array = new_array;
            current_size += chunk_size;
        }
    }

    *status = 0; // Success
    return array;
}

void cleanup_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int status;
    size_t n = 50; // Example: allocate for 50 instances
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_crc_pdu_array(n, &status);

    if (status == 0) {
        printf("Successfully allocated and filled array with %zu CRC indications.\n", n);
    } else {
        printf("Error allocating CRC indication array. Status code: %d\n", status);
    }

    cleanup_crc_pdu_array(array);

    return 0;
}
```

### Key Features:
- **Memory Management:** Uses `malloc` and `realloc` to handle dynamic memory allocation with chunking strategy.
- **Thread Safety:** Utilizes a mutex lock for safely incrementing the total count of CRC indications processed.
- **Error Handling:** Returns status codes to indicate success or specific errors, such as invalid input (`status = -1`) or memory allocation failure (`status = -2` or `-3`).
- **Scalability and Performance Optimization:** Starts with a chunk size for minimizing reallocations while ensuring dynamic scaling capability.
- **Random Value Generation:** Uses `rand()` to populate structure fields.
- **Resource Cleanup:** Provides a function to free allocated memory, preventing leaks.']

