// Assume these are defined elsewhere in your codebase.
typedef struct {
    int valid; // RX_UE_INFORMATION_TAG validity flag
} RX_UE_INFORMATION_TAG_T;

typedef unsigned short RNTI;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char current_name[256];
    size_t size;
    time_t last_modification_timestamp;
    char new_name[256]; // Buffer for the renamed file
} FILE_METADATA_T;

// Function prototypes
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_array(int n);
void process_files(FILE_METADATA_T* files, int count, const char** extensions, size_t ext_count);
char* generate_new_filename(const char* original_name, size_t size, time_t current_time, const char* extension);
int get_random_extension_index(const char** extensions, size_t ext_count);

// Global variables for thread safety
pthread_mutex_t crc_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t rename_mutex = PTHREAD_MUTEX_INITIALIZER;

volatile int total_crc_indications = 0;
volatile int successfully_renamed_files = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_array(int n) {
    if (n <= 0) {
        fprintf(stderr, "Warning: Invalid number of elements requested.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size_t chunk_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    while (!array && chunk_size > 0) {
        fprintf(stderr, "Memory allocation failed, retrying with smaller chunk...\n");
        array = malloc(chunk_size);
        chunk_size /= 2; // Reduce the size by half and try again
    }

    if (!array) {
        perror("Error: Failed to allocate memory for CRC indications after retries.");
        return NULL;
    }

    pthread_mutex_lock(&crc_mutex);
    total_crc_indications = n;

    for (int i = 0; i < n; ++i) {
        array[i].rx_ue_info_tag.valid = 1;
        array[i].rnti = rand() % 65535; // Random RNTI
        array[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    }
    pthread_mutex_unlock(&crc_mutex);

    return array;
}

void process_files(FILE_METADATA_T* files, int count, const char** extensions, size_t ext_count) {
    if (!files || count <= 0 || !extensions || ext_count == 0) {
        fprintf(stderr, "Warning: Invalid input parameters for file processing.\n");
        return;
    }

    time_t current_time = time(NULL);

    for (int i = 0; i < count; ++i) {
        const char* new_extension = extensions[get_random_extension_index(extensions, ext_count)];
        char* new_filename = generate_new_filename(files[i].current_name, files[i].size, current_time, new_extension);

        if (!new_filename) {
            fprintf(stderr, "Error: Failed to generate a new filename for %s.\n", files[i].current_name);
            continue;
        }

        // Simulating the file renaming
        strncpy(files[i].new_name, new_filename, sizeof(files[i].new_name));
        free(new_filename);

        pthread_mutex_lock(&rename_mutex);
        successfully_renamed_files++;
        pthread_mutex_unlock(&rename_mutex);
    }
}

char* generate_new_filename(const char* original_name, size_t size, time_t current_time, const char* extension) {
    if (!original_name || !extension) return NULL;

    char new_name[512];
    snprintf(new_name, sizeof(new_name), "%s_%zu_%ld.%s",
             original_name, size, (long)(current_time * 1000), extension);

    // Allocate memory for the new filename
    char* result = malloc(strlen(new_name) + 1);
    if (!result) {
        perror("Error: Failed to allocate memory for the new filename.");
        return NULL;
    }

    strcpy(result, new_name);
    return result;
}

int get_random_extension_index(const char** extensions, size_t ext_count) {
    return rand() % ext_count; // Randomly select an extension
}

// Example usage of functions and demonstration
int main() {
    const char* extensions[] = {"txt", "jpg", "png", "gif"};
    FILE_METADATA_T files[] = {
        {.current_name = "file1", .size = 1024, .last_modification_timestamp = time(NULL)},
        {.current_name = "file2", .size = 2048, .last_modification_timestamp = time(NULL)}
    };

    srand(time(NULL)); // Seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T* crc_array = allocate_crc_array(10);
    if (crc_array) {
        free(crc_array); // Free the allocated memory
    }

    process_files(files, 2, extensions, sizeof(extensions) / sizeof(extensions[0]));

    printf("Total CRC indications: %d\n", total_crc_indications);
    printf("Successfully renamed files: %d\n", successfully_renamed_files);

    return 0;
}
```

