    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list structure with thread safety features
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    bool detailed_logging;
} CRCList;

// Function to initialize the linked list
void initCRCList(CRCList* list, bool detailed_logging) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->detailed_logging = detailed_logging;
}

// Function to validate RNTI
bool isValidRNTI(int rnti, int min_rnti, int max_rnti) {
    if (rnti < min_rnti || rnti > max_rnti) {
        printf("Warning: Out-of-bounds RNTI %d\n", rnti);
        return false;
    }
    return true;
}

// Function to create a new list node
Node* createNode(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    newNode->data = pdu;
    newNode->next = NULL;
    return newNode;
}

// Function to add a new entry to the list
void addEntry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu, int min_rnti, int max_rnti) {
    if (!isValidRNTI(pdu.RNTI, min_rnti, max_rnti)) {
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* newNode = createNode(pdu);

    newNode->next = list->head;
    list->head = newNode;

    if (list->detailed_logging) {
        printf("Added entry: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               pdu.RTX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG, pdu.CRCFLAG);
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to clear the list
void clearList(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

// Function to destroy the list and its mutex
void destroyCRCList(CRCList* list) {
    clearList(list);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    CRCList crcList;
    int min_rnti = 0; // Define valid range for RNTI
    int max_rnti = 100;

    initCRCList(&crcList, true); // Enable detailed logging

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 100;
        pdu.RNTI = rand() % 200; // Some RNTIs may be out of bounds
        pdu.CRC_INDICATION_REL8_TAG = rand() % 50;
        pdu.CRCFLAG = rand() % 2 == 0;

        addEntry(&crcList, pdu, min_rnti, max_rnti);
    }

    destroyCRCList(&crcList);

    return 0;
}
