int add_bearer_to_ue(UEContext **head, int rnti, int bearerID);
int remove_bearer_from_ue(UEContext **head, int rnti, int bearerID);
int update_bearer_in_ue(UEContext **head, int rnti, int oldBearerID, int newBearerID);
void free_ue_contexts(UEContext *head);

// Add a new UE context
UEContext* add_ue_context(UEContext **head, int ueID, int rnti) {
    for (UEContext *current = *head; current != NULL; current = current->next) {
        if (current->rnti == rnti) return NULL; // RNTI must be unique
    }

    UEContext *new_ue = (UEContext*)malloc(sizeof(UEContext));
    if (!new_ue) return NULL;

    new_ue->ueID = ueID;
    new_ue->rnti = rnti;
    new_ue->bearers = NULL;
    new_ue->numBearers = 0;
    new_ue->next = *head;
    *head = new_ue;

    return new_ue;
}

// Add a bearer to an existing UE context
int add_bearer_to_ue(UEContext **head, int rnti, int bearerID) {
    for (UEContext *current = *head; current != NULL; current = current->next) {
        if (current->rnti == rnti) {
            BearerContext *newBearer = (BearerContext*)realloc(current->bearers, 
                sizeof(BearerContext) * (current->numBearers + 1));
            if (!newBearer) return -1;

            current->bearers = newBearer;
            current->bearers[current->numBearers].bearerID = bearerID;
            current->numBearers++;
            return 0; // Success
        }
    }

    return -1; // UE not found
}

// Remove a bearer from an existing UE context
int remove_bearer_from_ue(UEContext **head, int rnti, int bearerID) {
    for (UEContext *current = *head; current != NULL; current = current->next) {
        if (current->rnti == rnti) {
            for (size_t i = 0; i < current->numBearers; ++i) {
                if (current->bearers[i].bearerID == bearerID) {
                    memmove(&current->bearers[i], &current->bearers[i + 1],
                            sizeof(BearerContext) * (current->numBearers - i - 1));
                    current->numBearers--;

                    BearerContext *newBearers = realloc(current->bearers, 
                        sizeof(BearerContext) * current->numBearers);
                    if (!newBearers && current->numBearers > 0) {
                        return -1;
                    }
                    current->bearers = newBearers;

                    return 0; // Success
                }
            }
        }
    }

    return -1; // UE or bearer not found
}

// Update a bearer ID within an existing UE context
int update_bearer_in_ue(UEContext **head, int rnti, int oldBearerID, int newBearerID) {
    for (UEContext *current = *head; current != NULL; current = current->next) {
        if (current->rnti == rnti) {
            for (size_t i = 0; i < current->numBearers; ++i) {
                if (current->bearers[i].bearerID == oldBearerID) {
                    current->bearers[i].bearerID = newBearerID;
                    return 0; // Success
                }
            }
        }
    }

    return -1; // UE or bearer not found
}

// Free all UE contexts
void free_ue_contexts(UEContext *head) {
    while (head != NULL) {
        UEContext *temp = head;
        head = head->next;

        free(temp->bearers);
        free(temp);
    }
}
