#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListElement {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListElement* next;
} ListElement;

typedef struct {
    ListElement* head;
    pthread_mutex_t lock;
    size_t count;
    size_t successful_operations;
    size_t failed_operations;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->successful_operations = 0;
    list->failed_operations = 0;
    return list;
}

void destroy_list(DynamicList* list) {
    ListElement* current = list->head;
    while (current != NULL) {
        ListElement* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!list || list->count >= MAX_ENTRIES) return 0;

    ListElement* new_element = malloc(sizeof(ListElement));
    if (!new_element) {
        pthread_mutex_lock(&list->lock);
        list->failed_operations++;
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    new_element->data = entry;
    new_element->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_element->next = list->head;
    list->head = new_element;
    list->count++;
    list->successful_operations++;
    pthread_mutex_unlock(&list->lock);

    return 1;
}

int update_entry(DynamicList* list, unsigned short rnti, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!list) return 0;

    pthread_mutex_lock(&list->lock);
    ListElement* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            current->data = entry;
            list->successful_operations++;
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
        current = current->next;
    }

    list->failed_operations++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(DynamicList* list, unsigned short rnti) {
    if (!list) return 0;

    pthread_mutex_lock(&list->lock);
    ListElement *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        list->failed_operations++;
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    list->count--;
    list->successful_operations++;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

void print_stats(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    printf("Successful operations: %zu\n", list->successful_operations);
    printf("Failed operations: %zu\n", list->failed_operations);
    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicList* list = create_list();
    if (!list) return 1;

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T entry = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = 67890 };
    entry.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    add_entry(list, entry);
    update_entry(list, entry.RNTI, (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = 2, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = 11111});
    remove_entry(list, entry.RNTI);

    print_stats(list);
    destroy_list(list);

    return 0;
}
