    size_t capacity;
    size_t count;
    uint32_t targetCRCFlagCount;
} NFManager;

// Initialize the array with a given number of elements `N`
int initializeArray(NFManager *manager, size_t N) {
    if (manager == NULL || N == 0) return -1; // Error checking

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->array == NULL) return -2; // Allocation failed

    manager->capacity = N;
    manager->count = 0;
    manager->targetCRCFlagCount = 0;

    for (size_t i = 0; i < N; ++i) {
        manager->array[i].crcTag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        if (manager->array[i].crcTag.CRCFLAG == 1) {
            manager->targetCRCFlagCount++;
        }
    }

    return 0;
}

// Partial update of a structure at index `idx` without reallocating the entire array
int partialUpdate(NFManager *manager, size_t idx, uint32_t newCRCFlag) {
    if (manager == NULL || idx >= manager->capacity) return -1; // Error checking

    NFAPI_CRC_INDICATION_PDU_T *structure = &manager->array[idx];
    uint32_t oldCRCFlag = structure->crcTag.CRCFLAG;

    if (oldCRCFlag != newCRCFlag) {
        structure->crcTag.CRCFLAG = newCRCFlag;
        manager->targetCRCFlagCount += (newCRCFlag == 1) ? 1 : -1;
    }

    return 0;
}

// Free the allocated memory
void freeArray(NFManager *manager) {
    if (manager != NULL && manager->array != NULL) {
        free(manager->array);
        manager->array = NULL;
        manager->capacity = 0;
        manager->count = 0;
    }
}

