#define MAX_THREADS 10
#define LIST_SIZE 100

NFAPI_CRC_INDICATION_PDU_T* pdu_list[LIST_SIZE];
pthread_mutex_t list_mutexes[LIST_SIZE];

void initialize_list() {
    for (int i = 0; i < LIST_SIZE; ++i) {
        pthread_mutex_init(&list_mutexes[i], NULL);
        pdu_list[i] = NULL;
    }
}

void free_resources() {
    for (int i = 0; i < LIST_SIZE; ++i) {
        if (pdu_list[i]) {
            free(pdu_list[i]);
        }
        pthread_mutex_destroy(&list_mutexes[i]);
    }
}

void populate_pdu(int index, UE_TAG_INFO* ue_info, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memcpy(pdu->ue_info.ue_information_tag, ue_info->ue_information_tag, sizeof(ue_info->ue_information_tag));
    pdu->rnti = rnti;
    pdu->crc_indication.crcflag = rand() % 2;  // Random CRC flag

    pthread_mutex_lock(&list_mutexes[index]);
    pdu_list[index] = pdu;
    printf("Thread %ld populated index %d with RNTI: %u, CRC Flag: %u\n", pthread_self(), index, rnti, pdu->crc_indication.crcflag);
    pthread_mutex_unlock(&list_mutexes[index]);
}

void* thread_func(void* arg) {
    int thread_id = *(int*)arg;
    UE_TAG_INFO ue_info;
    uint16_t rnti = rand() % 65536;

    // Populate UE information tag randomly for demonstration
    memset(ue_info.ue_information_tag, (rand() % 256), sizeof(ue_info.ue_information_tag));

    int index = thread_id % LIST_SIZE;
    populate_pdu(index, &ue_info, rnti);

    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    initialize_list();

    for (int i = 0; i < MAX_THREADS; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, thread_func, &thread_ids[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Validate data integrity
    for (int i = 0; i < LIST_SIZE; ++i) {
        if (pdu_list[i]) {
            printf("Validated index %d, RNTI: %u, CRC Flag: %u\n", i, pdu_list[i]->rnti, pdu_list[i]->crc_indication.crcflag);
        }
    }

    free_resources();
    return 0;
}
