    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}

double get_average_packet_loss(DynamicArray *array) {
    if (!array || array->loss_window_count == 0) return -1.0;

    pthread_mutex_lock(&array->lock);

    double average = (double)array->total_loss / array->loss_window_count;

    pthread_mutex_unlock(&array->lock);
    return average;
}

double get_average_latency(DynamicArray *array) {
    if (!array || array->latency_window_count == 0) return -1.0;

    pthread_mutex_lock(&array->lock);

    double average = (double)array->total_latency / array->latency_window_count;

    pthread_mutex_unlock(&array->lock);
    return average;
}

int resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    if (!array || new_capacity <= array->capacity) return -1;

    NR_PHY_RX_CONTEXT *new_contexts = realloc(array->contexts, new_capacity * sizeof(NR_PHY_RX_CONTEXT));
    if (!new_contexts) return -1;

    array->contexts = new_contexts;
    array->capacity = new_capacity;

    return 0;
}
```

