// Global variables for managing the buffer and valid count
LTE_DL_FRAME_BUFFER *frameBuffer = NULL;
int frameCount = 0;
int errorThreshold = 0;
int validFrameCount = 0;

void initFrameBuffer(int N, int newErrorThreshold) {
    if (N <= 0 || newErrorThreshold < 0) return;

    // Update threshold
    errorThreshold = newErrorThreshold;

    // Allocate or reallocate buffer
    LTE_DL_FRAME_BUFFER *newBuffer = realloc(frameBuffer, sizeof(LTE_DL_FRAME_BUFFER) * N);
    if (!newBuffer) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    frameBuffer = newBuffer;
    frameCount = N;

    // Initialize frames
    for (int i = 0; i < N; ++i) {
        // Simulating initialization of PHYSICAL_LAYER_FRAME_DATA
        memset(&frameBuffer[i].frameData, 0, sizeof(PHYSICAL_LAYER_FRAME_DATA));

        // Example logic to set FRAME_ERROR_FLAG based on errorThreshold
        frameBuffer[i].context.frameErrorFlag = (rand() % 100) < errorThreshold;
    }

    // Recalculate validFrameCount
    validFrameCount = 0;
    for (int i = 0; i < N; ++i) {
        if (frameBuffer[i].context.frameErrorFlag == ((errorThreshold > 50) ? 1 : 0)) {
            ++validFrameCount;
        }
    }
}

void updateFrameData(int index, const unsigned char *newData) {
    if (index < 0 || index >= frameCount || newData == NULL) return;

    // Copy new data atomically to prevent concurrent issues
    memcpy(&frameBuffer[index].frameData.data, newData, sizeof(frameBuffer[index].frameData.data));

    // Check if the error flag matches threshold after update
    int shouldSetError = (rand() % 100) < errorThreshold;
    if (frameBuffer[index].context.frameErrorFlag != shouldSetError) {
        frameBuffer[index].context.frameErrorFlag = shouldSetError;

        // Adjust validFrameCount based on new state
        if (shouldSetError == ((errorThreshold > 50) ? 1 : 0)) {
            ++validFrameCount;
        } else {
            --validFrameCount;
        }
    }
}

int getValidFrameCount() {
    return validFrameCount;
}

void freeFrameBuffer() {
    free(frameBuffer);
    frameBuffer = NULL;
    frameCount = 0;
    validFrameCount = 0;
}
```

