} NFAPI_CRC_INDICATION_PDU_T;

#define POOL_SIZE 10000
#define MAX_POOL_ELEMENTS 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool[POOL_SIZE];
    int count;
    pthread_mutex_t lock;
} PduPool;

PduPool pdu_pool = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

int initialize_pdu_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) return -1;
        pdu_pool.pool[i] = pdu;
    }
    return 0;
}

void finalize_pdu_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        free(pdu_pool.pool[i]);
    }
}

int add_pdu_to_pool(RX_UE_INFORMATION_TAG rx_ue_information_tag, int rnti) {
    pthread_mutex_lock(&pdu_pool.lock);

    if (pdu_pool.count >= MAX_POOL_ELEMENTS) {
        fprintf(stderr, "PDU pool is full.\n");
        pthread_mutex_unlock(&pdu_pool.lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = pdu_pool.pool[pdu_pool.count++];
    pdu->rx_ue_information_tag.RNTI = rnti;

    // Set CRCFLAG randomly
    pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2;

    // Record creation timestamp
    pdu->creation_timestamp = time(NULL);

    const char* log_message = "PDU created";
    log_pdu_creation(log_message);

    pthread_mutex_unlock(&pdu_pool.lock);
    return 0;
}

int main() {
    initialize_logging_system();
    if (initialize_pdu_pool() != 0) {
        fprintf(stderr, "Failed to initialize PDU pool.\n");
        exit(EXIT_FAILURE);
    }

    // Example usage
    RX_UE_INFORMATION_TAG rx_ue_info = {.RNTI = 1234};
    for (int i = 0; i < 10; ++i) {
        add_pdu_to_pool(rx_ue_info, rx_ue_info.RNTI + i);
    }

    finalize_pdu_pool();
    dlclose(logging_system.handle);

    return 0;
}
```

