    int successful_ops;
    int failed_ops;
    unsigned long last_sync_time;
} ListManager;

static void init_db(sqlite3** db) {
    if (sqlite3_open("nfa_data.db", db)) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(*db));
        exit(1);
    }
    const char* sql = "CREATE TABLE IF NOT EXISTS NFAPI_CRC_INDICATION_PDU ("
                      "RNTI INTEGER PRIMARY KEY,"
                      "RX_UE_INFORMATION_TAG BLOB,"
                      "CRC_INDICATION_REL8_TAG INTEGER,"
                      "CRCFLAG INTEGER);";
    if (sqlite3_exec(*db, sql, 0, 0, 0) != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(*db));
        exit(1);
    }
}

ListManager* create_manager() {
    ListManager* manager = (ListManager*)calloc(1, sizeof(ListManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    init_db(&manager->db);

    // Initialize last_sync_time
    time_t now;
    time(&now);
    manager->last_sync_time = now;

    return manager;
}

void destroy_manager(ListManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    sqlite3_close(manager->db);
    free(manager);
}

int add_entry(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!manager || !entry) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for RNTI collision
    Node* current = manager->head;
    while (current) {
        if (current->data.RNTI == entry.RNTI) {
            pthread_mutex_unlock(&manager->lock);
            return -2;  // Entry already exists
        }
        current = current->next;
    }

    // Allocate new node and add to list
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&manager->lock);
        manager->failed_ops++;
        return -3;  // Memory allocation failed
    }

    memcpy(&newNode->data, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = manager->head;
    manager->head = newNode;

    pthread_mutex_unlock(&manager->lock);
    manager->successful_ops++;
    return 0; // Success
}

int update_entry(ListManager* manager, int rnti, NFAPI_CRC_INDICATION_PDU_T updated_entry) {
    if (!manager || !updated_entry) return -1;

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            memcpy(&current->data, &updated_entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&manager->lock);
            manager->successful_ops++;
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return -2;  // Entry not found
}

int remove_entry(ListManager* manager, int rnti) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) prev->next = current->next;
            else manager->head = current->next;

            free(current);
            pthread_mutex_unlock(&manager->lock);
            manager->successful_ops++;
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return -2;  // Entry not found
}

void sync_data(ListManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    time_t now;
    time(&now);
    if (difftime(now, manager->last_sync_time) < 10) {  // Synchronization interval: 10 seconds
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    sqlite3_stmt* stmt;
    const char* sql = "INSERT OR REPLACE INTO NFAPI_CRC_INDICATION_PDU (RNTI, RX_UE_INFORMATION_TAG, CRC_INDICATION_REL8_TAG, CRCFLAG) VALUES (?, ?, ?, ?);";

    if (sqlite3_prepare_v2(manager->db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(manager->db));
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Node* current = manager->head;
    while (current) {
        if (sqlite3_bind_int(stmt, 1, current->data.RNTI) != SQLITE_OK ||
            sqlite3_bind_blob(stmt, 2, &current->data.RX_UE_INFORMATION_TAG, sizeof(current->data.RX_UE_INFORMATION_TAG), NULL) != SQLITE_OK ||
            sqlite3_bind_int(stmt, 3, current->data.CRC_INDICATION_REL8_TAG) != SQLITE_OK ||
            sqlite3_bind_int(stmt, 4, current->data.CRCFLAG) != SQLITE_OK) {
            fprintf(stderr, "Failed to bind parameters: %s\n", sqlite3_errmsg(manager->db));
            break;
        }

        if (sqlite3_step(stmt) != SQLITE_DONE) {
            fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(manager->db));
            break;
        }

        sqlite3_reset(stmt);
        current = current->next;
    }

    sqlite3_finalize(stmt);
    manager->last_sync_time = now;

    pthread_mutex_unlock(&manager->lock);
}

void* monitor_performance(void* arg) {
    while (1) {
        ListManager* manager = (ListManager*)arg;
        if (!manager) break;

        sleep(5);  // Monitoring interval: 5 seconds

        pthread_mutex_lock(&manager->lock);
        printf("Successful operations: %d, Failed operations: %d\n", manager->successful_ops, manager->failed_ops);
        pthread_mutex_unlock(&manager->lock);
    }
    return NULL;
}

int main() {
    ListManager* manager = create_manager();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T entry1 = {1234, {0}, 5678, rand() % 2};
    add_entry(manager, entry1);

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_performance, manager);

    sleep(60);  // Run the example for a minute

    destroy_manager(manager);
    pthread_cancel(monitor_thread);
    pthread_join(monitor_thread, NULL);

    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` to ensure thread safety.
- **Resource Management**: Simple custom allocation through dynamic memory allocation with error handling for failures.
- **Performance Monitoring**: Basic operation counters and periodic monitoring using a separate thread.
- **Data Validation**: Checks for valid inputs before processing.
- **Data Persistence**: Integrates SQLite for data persistence, ensuring atomic updates via transactions (implicitly handled by `INSERT OR REPLACE`).
- **Scalability & Configuration Management**: These aspects are more complex to implement in a small example. However, the architecture allows for horizontal scaling and configuration parameters can be added as needed.

This code is a simplified representation of how one might approach such a task while considering all specified requirements.']

