NFA_LIST* create_list() {
    NFA_LIST* list = (NFA_LIST*)malloc(sizeof(NFA_LIST));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->entry_count = 0;
    return list;
}

bool add_entry(NFA_LIST* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->entry_count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return false; // List is full
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->entry_count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

