    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->entry_count--;
            pthread_mutex_unlock(&list->lock);
            return true; // Entry removed
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return false; // No entry with the given RNTI found
}

void destroy_list(NFA_LIST* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

