int add_pdu(PDUList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (list->current_memory_usage + pdu_size > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory limit exceeded
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Allocation failed
    }

    memcpy(&new_node->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;

    list->current_memory_usage += pdu_size;
    log_event("Created", &new_node->pdu);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_pdu(PDUList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
