    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (memcmp(&current->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            log_event("Destroyed", &current->pdu);
            size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

            if (prev == NULL) { // Remove head
                list->head = current->next;
            } else {
                prev->next = current->next;
            }

            list->current_memory_usage -= pdu_size;
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_pdu_list(PDUList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        log_event("Destroyed", &current->pdu);
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
