// Function to initialize and populate the array of NFAPI_RRC_PDU_T structures
NFAPI_RRC_PDU_T* initialize_nfa_rcc_pdu_array(int count, int* error) {
    *error = 0;
    if (count <= 0) {
        *error = -1; // Invalid number of PDUs requested
        return NULL;
    }

    NFAPI_RRC_PDU_T* pdu_array = (NFAPI_RRC_PDU_T*)malloc(count * sizeof(NFAPI_RRC_PDU_T));
    if (!pdu_array) {
        *error = -2; // Memory allocation failed for PDU array
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        pdu_array[i].rx_csi_report.harq_feedback = rand() % 256;
        pdu_array[i].rx_csi_report.csi_report = rand() % 256;
        pdu_array[i].rx_cqi_report.cqi_report = rand() % 16;
    }

    return pdu_array;
}

// Function to initialize and manage the UCI buffer
UCI_Buffer* create_uci_buffer(size_t initial_size, int* error) {
    *error = 0;

    if (initial_size == 0 || initial_size > MAX_UCI_SIZE) {
        *error = -3; // Invalid buffer size requested
        return NULL;
    }

    UCI_Buffer* uci_buffer = (UCI_Buffer*)malloc(sizeof(UCI_Buffer));
    if (!uci_buffer) {
        *error = -4; // Memory allocation failed for UCI Buffer structure
        return NULL;
    }

    uci_buffer->buffer = (char*)calloc(initial_size, sizeof(char));
    if (!uci_buffer->buffer) {
        free(uci_buffer);
        *error = -5; // Memory allocation failed for UCI buffer data
        return NULL;
    }

    uci_buffer->size = initial_size;
    return uci_buffer;
}

// Function to validate the UCI buffer before transmission
