        return 0; // Invalid buffer
    }

    // Example validation: Ensure no part of the buffer is uninitialized (zero)
    for (size_t i = 0; i < uci_buffer->size; ++i) {
        if (uci_buffer->buffer[i] == '\0') {
            return 0; // Buffer contains uninitialized data
        }
    }

    return 1; // Buffer is valid
}

// Function to free the UCI buffer resources
