#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

typedef struct {
    double timestamp;
    int frame_id;
    float signal_strength;
    float error_rate;
} FrameMetaData;

struct MemoryStruct {
    char *memory;
    size_t size;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        printf("Not enough memory\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = '\0';

    return realsize;
}

FrameMetaData* load_and_filter_frames(const char *url, float signal_threshold, int *num_frames) {
    CURL *curl_handle;
    CURLcode res;

    struct MemoryStruct chunk;
    chunk.memory = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl_handle = curl_easy_init();

    if(curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, url);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl_handle);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            free(chunk.memory);
            curl_easy_cleanup(curl_handle);
            curl_global_cleanup();
            return NULL;
        }

        char *line = strtok(chunk.memory, "\n");
        int capacity = 10;
        FrameMetaData *frames = malloc(capacity * sizeof(FrameMetaData));
        int frame_count = 0;

        while(line) {
            if(frame_count >= capacity) {
                capacity *= 2;
                frames = realloc(frames, capacity * sizeof(FrameMetaData));
            }

            char *token = strtok(line, ",");
            double timestamp = atof(token);
            token = strtok(NULL, ",");
            int frame_id = atoi(token);
            token = strtok(NULL, ",");
            float signal_strength = atof(token);
            token = strtok(NULL, ",");
            float error_rate = atof(token);

            if(signal_strength >= signal_threshold) {
                frames[frame_count].timestamp = timestamp;
                frames[frame_count].frame_id = frame_id;
                frames[frame_count].signal_strength = signal_strength;
                frames[frame_count].error_rate = error_rate;
                frame_count++;
            }

            line = strtok(NULL, "\n");
        }

        *num_frames = frame_count;
        free(chunk.memory);
        curl_easy_cleanup(curl_handle);
    } else {
        fprintf(stderr, "Error initializing curl\n");
    }

    curl_global_cleanup();
    return frames;
}

void free_frame_data(FrameMetaData *frames) {
    if (frames) {
        free(frames);
    }
}
```

### Key Points:
- **Network Handling**: Uses libcurl to fetch data with error handling for network issues.
- **Memory Management**: Dynamically allocates memory and resizes as needed, freeing allocated resources after use.
- **Performance Optimization**: Efficiently parses CSV lines using `strtok`, filters on-the-fly to reduce memory usage.
- **Modularity & Maintainability**: Functions are separated by purpose (loading data vs. cleaning up), making it easier to adapt or extend.
- **Error Handling**: Provides feedback for network errors and potential memory allocation failures.']

