#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Use an appropriate type for RNTI
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head[MAX_ELEMENTS];
    pthread_mutex_t lock;
    int size;
} DynamicArray;

void initDynamicArray(DynamicArray* array) {
    memset(array->head, 0, sizeof(Node*) * MAX_ELEMENTS);
    pthread_mutex_init(&array->lock, NULL);
    array->size = 0;
}

int hashRNTI(unsigned long rnti) {
    return (rnti % MAX_ELEMENTS);
}

NFAPI_CRC_INDICATION_PDU_T* getElement(DynamicArray* array, unsigned long rnti) {
    int index = hashRNTI(rnti);
    pthread_mutex_lock(&array->lock);
    Node* current = array->head[index];

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&array->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL; // Element not found
}

void addOrUpdateElement(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T newElement) {
    int index = hashRNTI(newElement.RNTI);
    pthread_mutex_lock(&array->lock);

    Node** ptr = &array->head[index];
    while (*ptr != NULL) {
        if ((*ptr)->data.RNTI == newElement.RNTI) {
            (*ptr)->data = newElement;
            break;
        }
        ptr = &(*ptr)->next;
    }

    if (*ptr == NULL && array->size < MAX_ELEMENTS) {
        *ptr = (Node*)malloc(sizeof(Node));
        if (*ptr != NULL) {
            (*ptr)->data = newElement;
            (*ptr)->next = NULL;
            array->size++;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void freeDynamicArray(DynamicArray* array) {
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        Node* current = array->head[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    pthread_mutex_destroy(&array->lock);
}

// Example usage
int main() {
    DynamicArray array;
    initDynamicArray(&array);

    NFAPI_CRC_INDICATION_PDU_T element = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = { .CRCFLAG = (unsigned char)rand() % 256 } };
    addOrUpdateElement(&array, element);

    NFAPI_CRC_INDICATION_PDU_T* retrieved = getElement(&array, 12345);
    if (retrieved != NULL) {
        printf("Retrieved CRCFLAG: %d\n", retrieved->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    freeDynamicArray(&array);

    return 0;
}
```

This code defines a dynamic array using a hash table with separate chaining to manage `NFAPI_CRC_INDICATION_PDU_T` structures. It uses mutexes for thread safety and provides functions for initialization, adding/updating elements, retrieving elements by `RNTI`, and freeing allocated resources.']

