// Function to initialize RRC contexts
LTE_RRC_MESSAGE_T* initialize_rrc_contexts(size_t num_entries, LTE_RRC_UE_CONTEXT* initial_ue_context_data, 
                                           LTE_RRC_CU_CAPOFSET_CONFIG* initial_cu_capofset_config) {
    if (num_entries <= 0) {
        log_error("Invalid number of entries.");
        return NULL;
    }

    size_t capacity = INITIAL_SIZE;
    LTE_RRC_MESSAGE_T *rrc_contexts = malloc(capacity * sizeof(LTE_RRC_MESSAGE_T));

    if (!rrc_contexts) {
        log_error("Memory allocation failed for RRC contexts.");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_entries && i < capacity; ++i) {
        rrc_contexts[i].ue_context.some_field = initial_ue_context_data ? initial_ue_context_data[i].some_field : -1;

        if (rrc_contexts[i].ue_context.some_field == -1) {
            log_error("Received invalid UE context data.");
            free(rrc_contexts);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        rrc_contexts[i].cu_capofset_config.config_value = initial_cu_capofset_config ? 
                                                          initial_cu_capofset_config[i].config_value : -1;

        if (rrc_contexts[i].cu_capofset_config.config_value == -1) {
            log_error("Received invalid CU CAP offset config data.");
            free(rrc_contexts);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    // Handle case where num_entries > INITIAL_SIZE
    if (num_entries > capacity) {
        size_t new_capacity = capacity * 2;
        LTE_RRC_MESSAGE_T* resized_rrc_contexts = realloc(rrc_contexts, new_capacity * sizeof(LTE_RRC_MESSAGE_T));

        if (!resized_rrc_contexts) {
            log_error("Memory reallocation failed for RRC contexts.");
            free(rrc_contexts);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        rrc_contexts = resized_rrc_contexts;

        for (size_t i = capacity; i < num_entries && i < new_capacity; ++i) {
            rrc_contexts[i].ue_context.some_field = initial_ue_context_data ? initial_ue_context_data[i].some_field : -1;

            if (rrc_contexts[i].ue_context.some_field == -1) {
                log_error("Received invalid UE context data during reallocation.");
                free(rrc_contexts);
                pthread_mutex_unlock(&lock);
                return NULL;
            }

            rrc_contexts[i].cu_capofset_config.config_value = initial_cu_capofset_config ? 
                                                              initial_cu_capofset_config[i].config_value : -1;

            if (rrc_contexts[i].cu_capofset_config.config_value == -1) {
                log_error("Received invalid CU CAP offset config data during reallocation.");
                free(rrc_contexts);
                pthread_mutex_unlock(&lock);
                return NULL;
            }
        }

        capacity = new_capacity;
    }

    pthread_mutex_unlock(&lock);

    // Return the populated array
    return rrc_contexts;
}

// Function to free allocated resources
void free_rrc_contexts(LTE_RRC_MESSAGE_T* rrc_contexts) {
    if (rrc_contexts) {
        free(rrc_contexts);
    }
}
