#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a type alias for convenience
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure representing the dynamic list with necessary metadata
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries; // Dynamic array of entries
    size_t capacity;                     // Maximum number of entries
    size_t count;                        // Current number of entries
    pthread_mutex_t lock;                // Mutex for thread safety
} DynamicList;

// Function to create a new dynamic list with specified maximum capacity
DynamicList* create_list(size_t max_capacity) {
    if (max_capacity == 0) return NULL;

    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->entries = calloc(max_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->capacity = max_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Helper function to check if an entry exists based on RX_UE_INFORMATION_TAG and RNTI
int entry_exists(DynamicList* list, unsigned int rx_ue_info_tag, unsigned int rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = &list->entries[i];
        if (entry->RX_UE_INFORMATION_TAG == rx_ue_info_tag && 
            entry->RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

// Function to add a new entry
int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->lock);

    if (entry_exists(list, new_entry.RX_UE_INFORMATION_TAG, new_entry.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate entry
    }

    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    list->entries[list->count++] = new_entry;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Function to retrieve the number of entries
size_t get_count(DynamicList* list) {
    size_t count;

    pthread_mutex_lock(&list->lock);
    count = list->count;
    pthread_mutex_unlock(&list->lock);

    return count;
}

// Function to remove a specific entry by RX_UE_INFORMATION_TAG and RNTI
int remove_entry(DynamicList* list, unsigned int rx_ue_info_tag, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RX_UE_INFORMATION_TAG == rx_ue_info_tag &&
            list->entries[i].RNTI == rnti) {

            memmove(&list->entries[i], &list->entries[i + 1],
                    (--list->count - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

// Function to compute the checksum of all entries
unsigned int compute_checksum(DynamicList* list) {
    unsigned int checksum = 0;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = &list->entries[i];
        checksum ^= entry->RX_UE_INFORMATION_TAG;
        checksum ^= entry->RNTI;
        checksum ^= entry->CRC_INDICATION_REL8_TAG.CRCFLAG;
    }

    pthread_mutex_unlock(&list->lock);

    return checksum;
}

// Function to destroy the dynamic list and free allocated memory
void destroy_list(DynamicList* list) {
    if (!list) return;

    free(list->entries);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
