```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024
#define CLEANUP_INTERVAL 300 // in seconds (5 minutes)
#define CRCFLAG_MAX 1

typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int IDLE;
    int IN_SYNC;
    int OUT_OF_SYNC;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG info_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    unsigned char crcflag; // 0 or 1
    time_t timestamp;
    size_t ref_count;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
HashTable* create_hash_table();
int hash_function(int rnti);
void insert_node(HashTable *table, NFAPI_CRC_INDICATION_PDU_T *node);
NFAPI_CRC_INDICATION_PDU_T* find_node(HashTable *table, int rnti);
void delete_node(HashTable *table, int rnti);
void cleanup_unused_nodes(HashTable *table);
void log_system_status(const char *message);

// Create hash table
HashTable* create_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(HASH_TABLE_SIZE, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Hash function
int hash_function(int rnti) {
    return rnti % HASH_TABLE_SIZE;
}

// Insert node into hash table
void insert_node(HashTable *table, NFAPI_CRC_INDICATION_PDU_T *node) {
    int index = hash_function(node->rnti);
    pthread_mutex_lock(&table->lock);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        log_system_status("Memory allocation failed for new node.");
        return;
    }
    new_node->data = node;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->lock);
}

// Find node by RNTI
NFAPI_CRC_INDICATION_PDU_T* find_node(HashTable *table, int rnti) {
    int index = hash_function(rnti);
    Node *current;

    pthread_mutex_lock(&table->lock);

    for (current = table->buckets[index]; current != NULL; current = current->next) {
        if (current->data && current->data->rnti == rnti) {
            current->data->timestamp = time(NULL); // Update timestamp
            pthread_mutex_unlock(&table->lock);
            return current->data;
        }
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Delete node by RNTI
void delete_node(HashTable *table, int rnti) {
    int index = hash_function(rnti);
    Node *current, *prev;

    pthread_mutex_lock(&table->lock);

    for (prev = NULL, current = table->buckets[index]; current != NULL; prev = current, current = current->next) {
        if (current->data && current->data->rnti == rnti) {
            if (prev) prev->next = current->next;
            else table->buckets[index] = current->next;

            free(current->data);
            free(current);
            pthread_mutex_unlock(&table->lock);
            return;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Cleanup unused nodes
void cleanup_unused_nodes(HashTable *table) {
    int i;
    Node *current, *prev;
    time_t now = time(NULL);

    pthread_mutex_lock(&table->lock);

    for (i = 0; i < HASH_TABLE_SIZE; ++i) {
        for (prev = NULL, current = table->buckets[i]; current != NULL; ) {
            if ((now - current->data->timestamp) > CLEANUP_INTERVAL) {
                Node *temp = current;
                current = current->next;

                if (temp->data) free(temp->data);
                if (prev) prev->next = current;
                else table->buckets[i] = current;

                free(temp);
            } else {
                prev = current;
                current = current->next;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Log system status
void log_system_status(const char *message) {
    printf("[LOG]: %s\n", message);
}

// Main function for testing
int main() {
    HashTable *table = create_hash_table();
    if (!table) {
        fprintf(stderr, "Failed to create hash table.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for node.\n");
        return EXIT_FAILURE;
    }

    node->rnti = 12345;
    node->timestamp = time(NULL);
    node->ref_count = 1;
    node->crcflag = rand() % CRCFLAG_MAX;

    insert_node(table, node);

    NFAPI_CRC_INDICATION_PDU_T *found = find_node(table, 12345);
    if (found) {
        printf("Node found with RNTI: %d\n", found->rnti);
    } else {
        printf("Node not found.\n");
    }

    cleanup_unused_nodes(table);

    delete_node(table, 12345);
    free(table->buckets);
    free(table);

    return EXIT_SUCCESS;
}
```

### Key Features:
