void init_dynamic_list(DynamicList* list, size_t initialCapacity) {
    if (list == NULL || initialCapacity == 0) return;

    list->pool = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
    list->errorFlag = 0;
}

void free_dynamic_list(DynamicList* list) {
    if (list == NULL) return;

    free(list->pool);
    pthread_mutex_destroy(&list->lock);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list == NULL || list->size >= list->capacity) {
        // Handle potential error
        pthread_mutex_lock(&list->lock);
        if (list->size < list->capacity) {  // Re-check inside the lock
            list->errorFlag = 1;
        }
        pthread_mutex_unlock(&list->lock);
        return -1; // Indicate failure to add element due to capacity issues or memory allocation error
    }

    pthread_mutex_lock(&list->lock);

    if (list->size < list->capacity) {
        list->pool[list->size] = element;
        list->size++;
        // Log the added element using existing logging framework, e.g., log_element_added(element);
    } else {
        list->errorFlag = 1; // Set error flag if unable to add
    }

    pthread_mutex_unlock(&list->lock);

    return 0; // Indicate success or failure (-1) appropriately
}

void expand_pool(DynamicList* list, size_t newCapacity) {
    if (newCapacity <= list->capacity) return;

    NFAPI_CRC_INDICATION_PDU_T* newPool = realloc(list->pool, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newPool) {
        pthread_mutex_lock(&list->lock);
        list->errorFlag = 1;
        pthread_mutex_unlock(&list->lock);
        return;
    }

    pthread_mutex_lock(&list->lock);

    list->pool = newPool;
    list->capacity = newCapacity;

    pthread_mutex_unlock(&list->lock);
}

// Example of using the dynamic list
int main() {
    DynamicList myList;
    init_dynamic_list(&myList, 100); // Start with a capacity of 100

    NFAPI_CRC_INDICATION_PDU_T element = { .exampleField = 42 };

    if (add_element(&myList, element) != 0) {
        printf("Error adding element.\n");
    }

    expand_pool(&myList, 200); // Expand the pool to accommodate more elements

    free_dynamic_list(&myList);
    return 0;
}
