    if (N <= 0 || N > 10000) {
        printf("Number of elements should be between 1 and 10,000.\n");
        return NULL;
    }

    // Memory pool setup for reduced fragmentation
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
