    int successfully_allocated_count = 0;

    srand(seed); // Seed for reproducibility

    for (int i = 0; i < N; ++i) {
        int RX_UE_TAG = get_RX_UE_INFORMATION_TAG();
        int rnti = get_RNTI();

        if (RX_UE_TAG == -1 || rnti == -1) { // Simulate data not available
            printf("Data source delay simulated. Retrying...\n");
            time_t start_time = time(NULL);
            while (time(NULL) - start_time < 2 && (RX_UE_TAG == -1 || rnti == -1)) {
                RX_UE_TAG = get_RX_UE_INFORMATION_TAG();
                rnti = get_RNTI();
            }
        }

        if (RX_UE_TAG != -1 && rnti != -1) {
            pdu_array[i].RX_UE_INFORMATION_TAG = RX_UE_TAG;
            pdu_array[i].RNTI = rnti;
            pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            successfully_allocated_count++;
        }
    }

    // Shuffle the array based on seed
    for (int i = N - 1; i > 0; --i) {
        int j = rand_r(&seed) % (i + 1);
        NFAPI_CRC_INDICATION_PDU_T temp = pdu_array[i];
        pdu_array[i] = pdu_array[j];
        pdu_array[j] = temp;
    }

    printf("Successfully allocated structures: %d\n", successfully_allocated_count);

    return pdu_array; // Return the pointer to dynamically allocated array
}

int main() {
    int N = 5000; // Example size, can be any number between 1 and 10000.
    int seed = time(NULL); // Use current time as a seed for shuffling.

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_and_initialize_pdu_array(N, seed);

    if (pdu_array) {
        // Use the allocated array...

        free(pdu_array);  // Free memory when done
    }

    return 0;
}
