#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Initialize linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Deallocate the entire linked list
void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

// Add a node to the linked list
int addNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Random number generator for CRCFLAG
unsigned char generateRandomCRCFLAG() {
    return rand() % 256; // Simulate a random value between 0 and 255
}

// Function to create and manage linked list with given parameters
int constructLinkedList(LinkedList* list, int n) {
    if (!list || n <= 0) return -1;

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        pdu.RNTI = rand() % 10000; // Example value
        pdu.CRC_INDICATION_REL8_TAG = rand() % 500; // Example value
        pdu.CRCFLAG = generateRandomCRCFLAG();

        if (addNode(list, pdu) != 0) {
            return -1; // Error handling for memory allocation failure
        }
    }

    return 0;
}

// Unit tests to validate implementation
void testLinkedList() {
    LinkedList list;
    initLinkedList(&list);

    int n = 10000; // Number of nodes
    if (constructLinkedList(&list, n) != 0) {
        printf("Failed to construct linked list\n");
        freeLinkedList(&list);
        return;
    }

    Node* current = list.head;
    for (int i = 0; i < n && current != NULL; ++i) {
        // Validate node contents
        if (current->data.RX_UE_INFORMATION_TAG < 0 ||
            current->data.RNTI < 0 || 
            current->data.CRC_INDICATION_REL8_TAG < 0 ||
            current->data.CRCFLAG > 255) {
                printf("Invalid data in linked list\n");
                freeLinkedList(&list);
                return;
        }
        current = current->next;
    }

    if (current != NULL) {
        printf("More nodes than expected\n");
    } else {
        printf("Linked list validated successfully with %d nodes.\n", n);
    }

    freeLinkedList(&list);
}

int main() {
    testLinkedList();
    return 0;
}
```

### Explanation

- **Thread Safety**: A `pthread_mutex_t` lock is used to ensure thread safety when modifying the linked list.

