#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HASH_TABLE_SIZE 101 // Choose a prime number for better distribution

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned long RNTI; // Unique identifier
    // Other fields can be added here as needed
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct NFAPI_CRC_INDICATION_PDU_T *next; // Pointer to next node in linked list
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashTableEntry {
    unsigned long rnti;
    NFAPI_CRC_INDICATION_PDU_T *node;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **buckets;
    size_t size;
} HashTable;

unsigned long hash_function(unsigned long rnti, size_t table_size) {
    return rnti % table_size;
}

HashTable* create_hash_table(size_t size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (HashTableEntry **)calloc(table->size, sizeof(HashTableEntry *));
    return table;
}

void free_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    free(node);
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashTableEntry *entry = table->buckets[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free_node(temp->node);
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(unsigned long rnti, int crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->ue_info.RNTI = rnti;
    new_node->crc_indication.CRCFLAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

int insert_node(HashTable *table, unsigned long rnti, int crc_flag) {
    unsigned long index = hash_function(rnti, table->size);
    HashTableEntry *entry = table->buckets[index];

    while (entry) {
        if (entry->rnti == rnti) {
            return 0; // RNTI already exists
        }
        entry = entry->next;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(rnti, crc_flag);
    HashTableEntry *new_entry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
    new_entry->rnti = rnti;
    new_entry->node = new_node;
    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;

    return 1; // Successfully inserted
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_node(HashTable *table, unsigned long rnti) {
    unsigned long index = hash_function(rnti, table->size);
    HashTableEntry *entry = table->buckets[index];

    while (entry) {
        if (entry->rnti == rnti) {
            return entry->node;
        }
        entry = entry->next;
    }

    return NULL; // Not found
}

int remove_node(HashTable *table, unsigned long rnti) {
    unsigned long index = hash_function(rnti, table->size);
    HashTableEntry *entry = table->buckets[index];
    HashTableEntry *prev_entry = NULL;

    while (entry) {
        if (entry->rnti == rnti) {
            if (prev_entry) {
                prev_entry->next = entry->next;
            } else {
                table->buckets[index] = entry->next;
            }
            free_node(entry->node);
            free(entry);
            return 1; // Successfully removed
        }
        prev_entry = entry;
        entry = entry->next;
    }

    return 0; // Not found
}

void iterate_nodes(HashTable *table, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    for (size_t i = 0; i < table->size; ++i) {
        HashTableEntry *entry = table->buckets[i];
        while (entry) {
            callback(entry->node);
            entry = entry->next;
        }
    }
}

// Example usage
void print_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    if (node) {
        printf("RNTI: %lu, CRCFLAG: %d\n", node->ue_info.RNTI, node->crc_indication.CRCFLAG);
    }
}

int main() {
    HashTable *table = create_hash_table(HASH_TABLE_SIZE);

    insert_node(table, 12345, rand() % 2); // Randomly set CRCFLAG
    insert_node(table, 67890, rand() % 2);

    NFAPI_CRC_INDICATION_PDU_T *node = retrieve_node(table, 12345);
    print_node(node);

    iterate_nodes(table, print_node);

    remove_node(table, 12345);

    destroy_hash_table(table);
    return 0;
}
```

This code provides a basic implementation of the specified requirements. It uses a hash table to manage RNTI uniqueness and supports insertion, retrieval, and removal operations efficiently. The `iterate_nodes` function allows for iteration over all nodes in the hash table, providing flexibility for further processing.']

