        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_MEMORY_USAGE 1024 * 1024 // Maximum memory size
#define PREDEFINED_TIME_WINDOW_MS 1000

typedef struct Node {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    time_t timestamp;
    struct Node* next;
} TagNode;

// Global lock-free pool of available tags using a circular buffer
#define POOL_SIZE 256
static atomic_uint_fast64_t tag_pool[POOL_SIZE];
static pthread_mutex_t tag_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function declarations
void initialize_tag_pool();
int is_duplicate(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI);
NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdu_array(size_t count, uint64_t seed, size_t max_size);
void serialize_pdu_array(const NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t count, uint8_t** out_data, size_t* out_size);

// Initialize the tag pool
void initialize_tag_pool() {
    pthread_mutex_lock(&tag_pool_mutex);
    for (size_t i = 0; i < POOL_SIZE; ++i) {
        atomic_store(&tag_pool[i], (uint64_t){.val = time(NULL)});
    }
    pthread_mutex_unlock(&tag_pool_mutex);
}

// Check for duplicates within a predefined time window
int is_duplicate(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&tag_pool_mutex);
    time_t current_time = time(NULL);

    for (size_t i = 0; i < POOL_SIZE; ++i) {
        uint64_t stored_value = atomic_load(&tag_pool[i]);
        uint32_t stored_tag = (uint32_t)(stored_value >> 32);
        uint16_t stored_rnti = (uint16_t)(stored_value & 0xFFFF);

        if ((stored_tag == RX_UE_INFORMATION_TAG || stored_rnti == RNTI) &&
            (current_time - (time_t)stored_value < PREDEFINED_TIME_WINDOW_MS)) {
            pthread_mutex_unlock(&tag_pool_mutex);
            return 1;
        }
    }

    // Add new entry to the pool
    uint64_t new_value = ((uint64_t)(RX_UE_INFORMATION_TAG) << 32) | RNTI;
    atomic_store(&tag_pool[time(NULL) % POOL_SIZE], new_value);

    pthread_mutex_unlock(&tag_pool_mutex);
    return 0;
}

// Allocate and populate PDU array
NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdu_array(size_t count, uint64_t seed, size_t max_size) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array || (count * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > max_size) {
        free(pdu_array);
        return NULL;
    }

    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        uint32_t RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        uint16_t RNTI = rand() % UINT16_MAX;

        if (is_duplicate(RX_UE_INFORMATION_TAG, RNTI)) {
            free(pdu_array);
            return NULL;
        }

        pdu_array[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu_array[i].RNTI = RNTI;
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Pseudo-random CRC flag
    }

    return pdu_array;
}

// Serialize the PDU array into binary format
void serialize_pdu_array(const NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t count, uint8_t** out_data, size_t* out_size) {
    *out_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *out_data = malloc(*out_size);

    if (*out_data != NULL) {
        memcpy(*out_data, pdu_array, *out_size);
    }
}

