#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} List;

// Function to create a new list
List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to check if an element exists
bool exists_in_list(const List* list, int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            current->data.RNTI == RNTI) {
            return true;
        }
        current = current->next;
    }
    return false;
}

// Function to add an element to the list
bool add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_ELEMENTS) return false;

    // Validate RNTI range
    if (data.RNTI < 1 || data.RNTI > 65535) return false;

    pthread_mutex_lock(&list->lock);

    // Check for duplicates
    if (exists_in_list(list, data.RX_UE_INFORMATION_TAG, data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to free the list
void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage function
int main() {
    List* nfa_list = create_list();
    if (!nfa_list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

