```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 50000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
    struct RX_UE_INFORMATION_TAG *RX_INFO; // Assume defined elsewhere
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    unsigned int key;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

#define HASH_TABLE_SIZE 50000

Node** hashTable = NULL;
pthread_mutex_t mutexes[HASH_TABLE_SIZE];

unsigned int hash(unsigned int rnti) {
    return rnti % HASH_TABLE_SIZE;
}

void initializeHashTable() {
    hashTable = (Node**)malloc(HASH_TABLE_SIZE * sizeof(Node*));
    memset(hashTable, 0, HASH_TABLE_SIZE * sizeof(Node*));

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

void freeHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* current = hashTable[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(hashTable);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&mutexes + i);
    }
}

void addOrUpdateElement(unsigned int rnti, NFAPI_CRC_INDICATION_PDU_T data) {
    unsigned int index = hash(rnti);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->key = rnti;
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&mutexes + index);

    // Update or Add
    if (hashTable[index] == NULL) {
        hashTable[index] = newNode;
    } else {
        Node* current = hashTable[index];
        while (current != NULL) {
            if (current->key == rnti) {
                current->data = data;  // Update existing entry
                free(newNode);
                break;
            }
            if (current->next == NULL) break;
            current = current->next;
        }
        if (current->key != rnti) {  // Add new entry at the end of list
            current->next = newNode;
        }
    }

    pthread_mutex_unlock(&mutexes + index);
}

NFAPI_CRC_INDICATION_PDU_T* getElement(unsigned int rnti) {
    unsigned int index = hash(rnti);
    pthread_mutex_lock(&mutexes + index);

    Node* current = hashTable[index];
    while (current != NULL) {
        if (current->key == rnti) {
            pthread_mutex_unlock(&mutexes + index);
            return &(current->data);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mutexes + index);
    return NULL; // Not found
}

int main() {
    initializeHashTable();

    CRC_INDICATION_REL8_TAG crcTag1 = { .CRCFLAG = 1 };
    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RNTI = 12345, .RX_INFO = NULL };

    addOrUpdateElement(pdu1.RNTI, pdu1);

    NFAPI_CRC_INDICATION_PDU_T* retrievedPDU = getElement(12345);
    if (retrievedPDU != NULL) {
        printf("Retrieved CRCFLAG: %d\n", retrievedPDU->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    freeHashTable();
    return 0;
}
```

