#include <pthread.h>
#include <time.h>

// Define the structure for cryptographic algorithms
typedef struct {
    char *name;
    void (*function_ptr)(void);
    unsigned int unique_id;
} CryptoAlgorithm;

// Define the structure for CRC indication PDU
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to load libraries and retrieve cryptographic algorithms
CryptoAlgorithm* load_crypto_algorithms(const char **libraries, size_t lib_count, size_t *count) {
    pthread_mutex_lock(&mutex);

    // Allocate space for potential maximum number of algorithms
    CryptoAlgorithm *algorithms = calloc(1000, sizeof(CryptoAlgorithm));
    if (!algorithms) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    unsigned int unique_id = 1;
    size_t index = 0;

    for (size_t i = 0; i < lib_count; ++i) {
        void *handle = dlopen(libraries[i], RTLD_NOW);
        if (!handle) {
            fprintf(stderr, "Failed to load library %s: %s\n", libraries[i], dlerror());
            continue;
        }

        while (1) {
            char func_name[256];
            snprintf(func_name, sizeof(func_name), "crypto_func_%u", unique_id);

            void *func_ptr = dlsym(handle, func_name);
            if (!func_ptr) {
                break; // No more functions with this pattern
            }

            char *error;
            if ((error = dlerror()) != NULL) {
                fprintf(stderr, "Failed to load symbol %s: %s\n", func_name, error);
                continue;
            }

            algorithms[index].name = strdup(func_name);
            algorithms[index].function_ptr = func_ptr;
            algorithms[index].unique_id = unique_id++;

            index++;
        }

        dlclose(handle);
    }

    *count = index;
    pthread_mutex_unlock(&mutex);

    // Reallocate to the exact number of loaded algorithms
    algorithms = realloc(algorithms, index * sizeof(CryptoAlgorithm));
    return algorithms;
}

// Function to generate NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_crc_pdu(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1024;
        pdus[i].RNTI = rand() % 1024;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set CRCFLAG
    }

    return pdus;
}

// Example usage
int main(int argc, char *argv[]) {
    const char *libraries[] = {"libcrypto1.so", "libcrypto2.so"};
    size_t lib_count = sizeof(libraries) / sizeof(libraries[0]);
    size_t algo_count;

    CryptoAlgorithm *algorithms = load_crypto_algorithms(libraries, lib_count, &algo_count);
    if (!algorithms) {
        fprintf(stderr, "Failed to load cryptographic algorithms\n");
        return EXIT_FAILURE;
    }

    printf("Loaded %zu cryptographic algorithms:\n", algo_count);
    for (size_t i = 0; i < algo_count; ++i) {
        printf("Name: %s, Unique ID: %u\n", algorithms[i].name, algorithms[i].unique_id);
        free(algorithms[i].name); // Free allocated strings
    }
    free(algorithms);

    size_t pdu_count = 10;
    NFAPI_CRC_INDICATION_PDU_T *pdus = generate_crc_pdu(pdu_count);
    if (!pdus) {
        fprintf(stderr, "Failed to generate CRC PDUs\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < pdu_count; ++i) {
        printf("PDU %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n",
               i, pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI, pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
    free(pdus);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: A mutex is used to ensure thread safety when loading libraries and algorithms.
- **Dynamic Loading**: Uses `dlopen` and `dlsym` for dynamic library handling.
- **Memory Management**: Allocates memory dynamically and ensures it's freed appropriately.
- **Error Handling**: Provides clear error messages for debugging.
- **Random Generation**: Utilizes `rand()` to generate random values for CRC flags.
- **Scalability**: Efficiently manages resources, even under high load.']

