    FILE *file = fopen(filename, "r");
    if (!file) return;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key && value) {
            options[*option_count].key = strdup(key);
            options[*option_count].value = strdup(value);
            (*option_count)++;
        }
    }

    fclose(file);
}

