        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-c config_file] [-o output_file] [-v verbosity_level]\n", argv[0]);
            return 0;
        } else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            *config_file = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            *output_file = argv[++i];
        } else if (strcmp(argv[i], "-v") == 0 && i + 1 < argc) {
            *verbosity_level = atoi(argv[++i]);
        }
    }

    return 1;
}

void log_message(const char *message, int level, const char *log_file) {
    FILE *file = fopen(log_file, "a");
    if (!file) return;

    fprintf(file, "[%d] %s\n", level, message);
    fclose(file);
}

int main(int argc, char *argv[]) {
