        log_message("Failed to initialize cache");
        return -1;
    }
    cache->count = 0;
    cache->capacity = initial_capacity;
    return 0;
}

void cache_free(CRCIndicationCache *cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        free_pdu(&cache->data[i]);
    }
    free(cache->data);
    pthread_mutex_destroy(&cache->lock);
    log_message("Cache freed successfully");
}

int cache_add(CRCIndicationCache *cache, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&cache->lock);

    if (cache->count >= cache->capacity) {
        size_t new_capacity = cache->capacity * 2;
        if (new_capacity > MAX_CACHE_SIZE) {
            log_message("Cache capacity exceeded");
            pthread_mutex_unlock(&cache->lock);
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(cache->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            log_message("Failed to resize cache");
            pthread_mutex_unlock(&cache->lock);
            return -1;
        }

        cache->data = new_data;
        cache->capacity = new_capacity;
    }

    cache->data[cache->count++] = pdu;

    pthread_mutex_unlock(&cache->lock);
    log_message("PDU added to cache");
    return 0;
}

void manage_pdus(size_t N, uint32_t base_tag) {
    CRCIndicationCache cache;
    if (cache_init(&cache, 10)) return; // Initial capacity set to 10

    for (size_t i = 0; i < N; ++i) {
        uint32_t tag = base_tag + i;
        uint16_t rnti = rand() % 65536;
        uint8_t crc_tag = rand() % 256;

        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(tag, rnti, crc_tag);
        if (!pdu) continue; // Handle memory allocation failure

        cache_add(&cache, *pdu);
    }

    cache_free(&cache);
}

// Unit tests (simplified example)
void test_manage_pdus() {
    manage_pdus(5, 1000); // Test with small N
    manage_pdus(100, 2000); // Test with larger N
    manage_pdus(0, 3000); // Edge case: N = 0

    log_message("Unit tests completed");
}

int main() {
    srand(time(NULL)); // Seed random number generator
    test_manage_pdus();
    return 0;
}
```

