// Hash function to check for RNTI uniqueness
bool is_rnti_unique(uint16_t rnti, uint16_t *rnti_set, int size) {
    for (int i = 0; i < size; ++i) {
        if (rnti_set[i] == rnti) {
            return false;
        }
    }
    return true;
}

// Add element to the list
