    for (int i = 0; i < MAX_ELEMENTS && !is_rnti_unique(new_data.RNTI, list->rnti_set, list->size); ++i) {
        log_message("Duplicate RNTI detected. Retrying...");
        usleep(100000); // Backoff strategy: wait for 100ms
    }

    if (!is_rnti_unique(new_data.RNTI, list->rnti_set, list->size)) {
        log_message("Failed to add element due to duplicate RNTI after retries.");
        return false;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed.");
        return false;
    }

    new_node->data = new_data;
    new_node->next = list->head;
    list->head = new_node;
    list->rnti_set[list->size++] = new_data.RNTI;

    log_message("Element added successfully.");

    return true;
}

// Remove element from the list
void remove_element(List* list, uint16_t rnti) {
    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        log_message("Element with RNTI not found.");
        return;
    }

    if (prev == NULL) { // Removing head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    for (int i = 0; i < list->size; ++i) {
        if (list->rnti_set[i] == rnti) {
            memmove(&list->rnti_set[i], &list->rnti_set[i + 1], sizeof(uint16_t) * (list->size - i - 1));
            break;
        }
    }

    free(current);
    --list->size;

    log_message("Element removed successfully.");
}

// Initialize the list
void initialize_list(List* list) {
    list->head = NULL;
    list->size = 0;
    memset(list->rnti_set, 0, sizeof(list->rnti_set));
    log_message("List initialized.");
}

// Free memory of the list
