    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random CRCFLAG
int generate_random_crcflag() {
    return rand() % 2;  // Randomly 0 or 1
}

// Thread-safe function to create and populate NFAPI structures.
void* populate_nfa_structures(void* arg) {
    int num_structures = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_structures; ++i) {
        structures[i].rx_ue_info_tag.RNTI = rand(); // Example random value
        structures[i].rnti = rand();
        structures[i].crc_indication_rel8_tag.CRCFLAG = generate_random_crcflag();
    }

    pthread_exit((void*)structures);
}

// Function to read configuration file and extract number of structures.
int get_num_structures_from_config(const char* config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) return -1;

    int num_structures = 0;
    fscanf(file, "%d", &num_structures);
    fclose(file);

    return num_structures;
}

// Main function with command line parsing and multi-threading logic.
int main(int argc, char *argv[]) {
    srand(time(NULL));

    const char* config_file = NULL;
    const char* output_file = "output.txt";
    int verbosity_level = 0;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"config", required_argument, 0, 'c'},
        {"output", required_argument, 0, 'o'},
        {"verbosity", required_argument, 0, 'v'},
        {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "hc:o:v:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s --config <file> --output <file> --verbosity <level>\n", argv[0]);
                return 0;
            case 'c':
                config_file = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'v':
                verbosity_level = atoi(optarg);
                break;
            default:
                printf("Usage: %s --config <file> --output <file> --verbosity <level>\n", argv[0]);
                return 1;
        }
    }

    if (!config_file) {
        printf("Configuration file must be specified.\n");
        return 1;
    }

    int num_structures = get_num_structures_from_config(config_file);
    if (num_structures <= 0) {
        fprintf(stderr, "Invalid number of structures in config file.\n");
        return 1;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, populate_nfa_structures, &num_structures);
    void* result;
    pthread_join(thread_id, &result);

    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)result;

    FILE *output = fopen(output_file, "w");
    if (!output) {
        perror("Failed to open output file");
        free(structures);
        return 1;
    }

    for (int i = 0; i < num_structures; ++i) {
        fprintf(output, "RNTI: %d, CRCFLAG: %d\n", structures[i].rnti, structures[i].crc_indication_rel8_tag.CRCFLAG);
    }

    fclose(output);
    free(structures);

    printf("Processing completed. Output written to %s\n", output_file);

    return 0;
}
