using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Threading;

public class ConfigurationManager
{
    private readonly string _filePath;
    private readonly ConcurrentDictionary<string, string> _settingsCache;
    private static readonly ReaderWriterLockSlim _cacheLock = new();

    public ConfigurationManager(string filePath)
    {
        _filePath = filePath ?? throw new ArgumentNullException(nameof(filePath));
        _settingsCache = new ConcurrentDictionary<string, string>();

        LoadSettings();
    }

    private void LoadSettings()
    {
        try
        {
            if (!File.Exists(_filePath))
                return;

            var settingsJson = File.ReadAllText(_filePath);
            var settingsDict = JsonSerializer.Deserialize<Dictionary<string, string>>(settingsJson) ?? new Dictionary<string, string>();

            foreach (var kvp in settingsDict)
            {
                _settingsCache[kvp.Key] = kvp.Value;
            }
        }
        catch (Exception ex)
        {
            // Log the exception using an existing logging framework
            Console.WriteLine($"Error loading settings: {ex.Message}");
        }
    }

    public string GetSetting(string key)
    {
        if (_settingsCache.TryGetValue(key, out var value))
        {
            return value;
        }

        throw new KeyNotFoundException($"The setting with key '{key}' was not found.");
    }

    public void UpdateSetting(string key, string newValue)
    {
        try
        {
            using (var writeLock = _cacheLock.WriteLock())
            {
                if (_settingsCache.ContainsKey(key))
                    _settingsCache[key] = newValue;
                else
                    _settingsCache.TryAdd(key, newValue);

                SaveSettings();
            }
        }
        catch (Exception ex)
        {
            // Log the exception using an existing logging framework
            Console.WriteLine($"Error updating setting: {ex.Message}");
        }
    }

    private void SaveSettings()
    {
        try
        {
            var settingsJson = JsonSerializer.Serialize(_settingsCache);
            File.WriteAllText(_filePath, settingsJson);

            // Log saving operation for auditing purposes
            Console.WriteLine("Settings saved.");
        }
        catch (Exception ex)
        {
            // Log the exception using an existing logging framework
            Console.WriteLine($"Error saving settings: {ex.Message}");
        }
    }

    public IEnumerable<KeyValuePair<string, string>> GetAllSettings()
    {
        return _settingsCache;
    }

    public override string ToString()
    {
        using (_cacheLock.ReadLock())
        {
            return JsonSerializer.Serialize(_settingsCache);
        }
    }
}

