#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Assume 0 or 1 based on probability threshold
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_crc_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t num_elements, double crc_probability_threshold, int *error_code) {
    if (num_elements <= 0) {
        *array = NULL;
        *error_code = -1; // Invalid input size
        return;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        *error_code = -2; // Memory allocation failed
        return;
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_elements; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100;     // Simulate UE information tag lookup
        (*array)[i].RNTI = rand() % 1000;                     // Simulate RNTI lookup
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 50;    // Arbitrary value for CRC indication

        // Set the CRCFLAG based on probability threshold
        double random_value = (double)rand() / RAND_MAX;
        if (random_value < crc_probability_threshold) {
            (*array)[i].CRCFLAG = 1; // Mark as valid CRC flag based on probability
        } else {
            (*array)[i].CRCFLAG = 0;
        }
    }

    *error_code = 0; // Success
}

void deallocate_crc_array(NFAPI_CRC_INDICATION_PDU_T **array) {
    if (array && *array) {
        free(*array);
        *array = NULL;
    }
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T *crcArray = NULL;
    int errorCode;

    size_t numElements = 1000; // Example size
    double crcProbabilityThreshold = 0.5; // Example probability threshold

    initialize_crc_array(&crcArray, numElements, crcProbabilityThreshold, &errorCode);

    if (errorCode != 0) {
        printf("Error initializing CRC array: %d\n", errorCode);
        return -1;
    }

    // Process the array...

    deallocate_crc_array(&crcArray);

    return 0;
}
```

