#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NUM_PDUS 1024

typedef struct {
    int TX_RLC_PDU_TAG;
    unsigned int SEQUENCE_NUMBER;
    unsigned long TRANSMITTED_BLOCK_COUNTER;
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T* pdus[MAX_NUM_PDUS];
    size_t count;
} PduManager;

// Initialize the PDU manager
void initPduManager(PduManager* manager) {
    manager->count = 0;
    memset(manager->pdus, 0, sizeof(manager->pdus));
}

// Free all allocated PDUs
void freePdus(PduManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdus[i]);
    }
    manager->count = 0;
}

// Validate a PDU structure
int validatePdu(const MAC_PDU_T* pdu) {
    if (!pdu) return 0;
    return pdu->TX_RLC_PDU_TAG != 0 &&
           pdu->SEQUENCE_NUMBER > 0 &&
           pdu->TRANSMITTED_BLOCK_COUNTER >= 0;
}

// Add a PDU to the manager
int addPdu(PduManager* manager, MAC_PDU_T* pdu) {
    if (manager->count >= MAX_NUM_PDUS || !validatePdu(pdu)) return -1;

    MAC_PDU_T* new_pdu = malloc(sizeof(MAC_PDU_T));
    if (!new_pdu) return -2; // Memory allocation failure

    memcpy(new_pdu, pdu, sizeof(MAC_PDU_T));

    manager->pdus[manager->count++] = new_pdu;
    return 0;
}

// Retrieve a PDU by index
MAC_PDU_T* getPdu(PduManager* manager, size_t index) {
    if (index >= manager->count) return NULL;
    return manager->pdus[index];
}

// Example usage
int main() {
    PduManager manager;
    initPduManager(&manager);

    MAC_PDU_T pdu = {1, 100, 2000};
    if (addPdu(&manager, &pdu) != 0) {
        fprintf(stderr, "Failed to add PDU\n");
    }

    MAC_PDU_T* retrieved_pdu = getPdu(&manager, 0);
    if (retrieved_pdu && validatePdu(retrieved_pdu)) {
        printf("Retrieved PDU: %d, %u, %lu\n",
               retrieved_pdu->TX_RLC_PDU_TAG,
               retrieved_pdu->SEQUENCE_NUMBER,
               retrieved_pdu->TRANSMITTED_BLOCK_COUNTER);
    } else {
        fprintf(stderr, "Failed to retrieve valid PDU\n");
    }

    freePdus(&manager);
    return 0;
}
