#define MAX_CONNECTIONS 50000

typedef struct {
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    uint16_t PORT_NUMBER;
    int CONN_STATE; // e.g., 0 for closed, 1 for open
} TCP_CONNECTION_INFO;

typedef struct {
    TCP_CONNECTION_INFO connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    size_t count;
} ConnectionManager;

typedef struct {
    char *config_data;
    size_t config_size;
} Config;

#define LOG_LEVEL_ERROR 0
#define LOG_LEVEL_WARN 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_DEBUG 3

int log_level = LOG_LEVEL_INFO; // Default logging level

void log_message(int level, const char *message) {
    if (level <= log_level) {
        printf("%s\n", message);
    }
}

ConnectionManager* create_connection_manager() {
    ConnectionManager *manager = (ConnectionManager *)malloc(sizeof(ConnectionManager));
    if (!manager) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for connection manager");
        return NULL;
    }

    memset(manager->connections, 0, sizeof(manager->connections));
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;

    log_message(LOG_LEVEL_INFO, "Connection manager created successfully");

    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager);

    log_message(LOG_LEVEL_INFO, "Connection manager destroyed");
}

int add_connection(ConnectionManager *manager, const TCP_CONNECTION_INFO *info) {
    if (!manager || !info) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&manager->lock);
        log_message(LOG_LEVEL_WARN, "Connection limit reached");
        return -2;
    }

    manager->connections[manager->count++] = *info;
    pthread_mutex_unlock(&manager->lock);

    log_message(LOG_LEVEL_DEBUG, "Connection added successfully");

    return 0;
}

Config* load_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_message(LOG_LEVEL_ERROR, "Failed to open configuration file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t config_size = ftell(file);
    rewind(file);

    Config *config = (Config *)malloc(sizeof(Config));
    if (!config) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for config");
        fclose(file);
        return NULL;
    }

    config->config_data = (char *)malloc(config_size + 1);
    if (!config->config_data) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for config data");
        free(config);
        fclose(file);
        return NULL;
    }

