    size_t buffer_size;
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    int max_events_per_sec;
} EventLogManager;

int load_config(const char* path, int *max_events_per_sec) {
    FILE *file = fopen(path, "r");
    if (!file) return -1;

    fscanf(file, "%d", max_events_per_sec);
    fclose(file);

    return 0;
}

EventLogManager* init_event_log_manager(size_t buffer_size, const char* config_path) {
    int max_events_per_sec = 0;
    if (load_config(config_path, &max_events_per_sec) != 0) {
        fprintf(stderr, "Failed to load configuration.\n");
        return NULL;
    }

    EventLogManager *manager = malloc(sizeof(EventLogManager));
    manager->buffer = malloc(buffer_size * sizeof(NFhabi_Event_Record_T));
    if (!manager->buffer) {
        free(manager);
        perror("Memory allocation failed for event buffer");
        return NULL;
    }

    manager->buffer_size = buffer_size;
    manager->head = 0;
    manager->tail = 0;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->not_full, NULL);
    pthread_cond_init(&manager->not_empty, NULL);
    manager->max_events_per_sec = max_events_per_sec;

    return manager;
}

int log_event(EventLogManager *manager, NFhabi_Event_Record_T event) {
    pthread_mutex_lock(&manager->lock);

    while (manager->count == manager->buffer_size) {
        pthread_cond_wait(&manager->not_full, &manager->lock);
    }

    manager->buffer[manager->tail] = event;
    manager->tail = (manager->tail + 1) % manager->buffer_size;
    manager->count++;

    pthread_cond_signal(&manager->not_empty);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

NFhabi_Event_Record_T* get_event(EventLogManager *manager, int timeout_ms) {
    NFhabi_Event_Record_T *event = NULL;

    pthread_mutex_lock(&manager->lock);

    while (manager->count == 0) {
        if (pthread_cond_timedwait(&manager->not_empty, &manager->lock,
            &(struct timespec){ .tv_sec = time(NULL) + timeout_ms / 1000, .tv_nsec = (timeout_ms % 1000) * 1000000 }) != 0) {
            pthread_mutex_unlock(&manager->lock);
            return NULL;
        }
    }

    event = &manager->buffer[manager->head];
    manager->head = (manager->head + 1) % manager->buffer_size;
    manager->count--;

    pthread_cond_signal(&manager->not_full);
    pthread_mutex_unlock(&manager->lock);

    return event;
}

void free_event_log_manager(EventLogManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->not_full);
    pthread_cond_destroy(&manager->not_empty);

    free(manager->buffer);
    free(manager);
}
