    pthread_mutex_t lock;
    int log_level;  // Configurable logging level
} CRCList;

void initialize_crc_list(CRCList* list, int log_level) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->log_level = log_level;
}

void free_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

int is_valid_rnti(uint16_t rnti) {
    return rnti <= 65535;
}

void log_message(CRCList* list, const char* message) {
    if (list->log_level > 0) { // Assuming 1 or higher means logging
        printf("%s\n", message);
    }
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        log_message(NULL, "Memory allocation failed");
        return NULL;
    }
    node->data = pdu;
    node->next = NULL;
    return node;
}

void add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(pdu);
    if (new_node) {
        new_node->next = list->head;
        list->head = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void populate_crc_list(CRCList* list, int n) {
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Randomly setting this
        pdu.RNTI = rand() % 70000; // Generates random RNTI, some may be invalid

        if (!is_valid_rnti(pdu.RNTI)) {
            char log[100];
            snprintf(log, sizeof(log), "Invalid RNTI: %u", pdu.RNTI);
            log_message(list, log);
            continue;
        }

        pdu.CRCFLAG = rand() % 2; // Randomly setting CRCFLAG as 0 or 1
        add_to_crc_list(list, pdu);

        // Simulate backpressure handling
        if (i % 100 == 0) {
            usleep(1000); // Sleep for 1ms to simulate backpressure handling
        }
    }
}

void* thread_safe_function(void* arg) {
    CRCList* list = (CRCList*)arg;
    populate_crc_list(list, 10000);
    return NULL;
}

int main() {
    const int log_level = 1; // Set desired logging level here
    CRCList crc_list;

    initialize_crc_list(&crc_list, log_level);

    pthread_t threads[4];  // Example with 4 concurrent threads
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_safe_function, &crc_list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_crc_list(&crc_list);

    return 0;
}
