    CHANNEL_MEASUREMENT channel_measurement;
    int frame_number;
    int time_slot_index;
    struct LTE_DL_FRAME_MSG *prev;
    struct LTE_DL_FRAME_MSG *next;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *head;
    LTE_DL_FRAME_MSG *tail;
    pthread_mutex_t lock; // Mutex for thread safety
} DoublyLinkedList;

// Initialize the doubly linked list
void init_list(DoublyLinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to create a new frame message node
LTE_DL_FRAME_MSG* create_frame_msg(int frame_number, int time_slot_index, CHANNEL_MEASUREMENT measurement) {
    LTE_DL_FRAME_MSG *new_node = (LTE_DL_FRAME_MSG*)malloc(sizeof(LTE_DL_FRAME_MSG));
    if (!new_node) return NULL;

    new_node->frame_number = frame_number;
    new_node->time_slot_index = time_slot_index;
    new_node->channel_measurement.measurement_value = measurement.measurement_value;
    new_node->prev = NULL;
    new_node->next = NULL;

    // Initialize other fields with default values or from external source
    // Example: new_node->phy_params.frequency = fetch_frequency_from_source();

    return new_node;
}

// Insert a frame message into the list in ascending order by identifiers
void insert_frame_msg(DoublyLinkedList *list, LTE_DL_FRAME_MSG *node) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || (list->head->frame_number > node->frame_number ||
                        (list->head->frame_number == node->frame_number &&
                         list->head->time_slot_index > node->time_slot_index))) {
        // Insert at head
        node->next = list->head;
        if (list->head) list->head->prev = node;
        list->head = node;
        if (!list->tail) list->tail = node;
    } else {
        LTE_DL_FRAME_MSG *current = list->head;
        while (current->next && 
               (current->next->frame_number < node->frame_number ||
                (current->next->frame_number == node->frame_number &&
                 current->next->time_slot_index <= node->time_slot_index))) {
            current = current->next;
        }
        // Insert after current
        node->next = current->next;
        if (current->next) current->next->prev = node;
        current->next = node;
        node->prev = current;

        if (!node->next) list->tail = node; // Update tail if necessary
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the linked list and retrieve all channel measurements
void get_all_channel_measurements(DoublyLinkedList *list, CHANNEL_MEASUREMENT **measurements, int *count) {
    pthread_mutex_lock(&list->lock);

    LTE_DL_FRAME_MSG *current = list->head;
    while (current) {
        if (*measurements == NULL) { // Initial allocation
            *measurements = malloc(sizeof(CHANNEL_MEASUREMENT));
        } else { // Reallocate for additional measurements
            *measurements = realloc(*measurements, (*count + 1) * sizeof(CHANNEL_MEASUREMENT));
        }
        if (!*measurements) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }

        (*measurements)[*count] = current->channel_measurement;
        (*count)++;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example function to simulate real-time updates from an external data source
void update_phy_params(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    LTE_DL_FRAME_MSG *current = list->head;
    while (current) {
        // Simulate fetching updated PHY_PARAMS from the external source
        // Example: current->phy_params.frequency = fetch_frequency_from_source();

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup function to free memory used by the list
void cleanup_list(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    LTE_DL_FRAME_MSG *current = list->head;
    while (current) {
        LTE_DL_FRAME_MSG *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    DoublyLinkedList list;
    init_list(&list);

    // Simulate adding frame messages with random measurements
    for (int i = 0; i < 10; ++i) {
        CHANNEL_MEASUREMENT measurement = { rand() % 100 };
        LTE_DL_FRAME_MSG *frame_msg = create_frame_msg(i, rand() % 10, measurement);
        if (frame_msg) {
            insert_frame_msg(&list, frame_msg);
        } else {
            printf("Failed to allocate memory for frame message\n");
        }
    }

    // Retrieve all channel measurements
    CHANNEL_MEASUREMENT *measurements = NULL;
    int count = 0;
    get_all_channel_measurements(&list, &measurements, &count);

    if (measurements) {
        for (int i = 0; i < count; ++i) {
            printf("Measurement %d: %d\n", i, measurements[i].measurement_value);
        }
        free(measurements);
    }

    // Simulate updating PHY_PARAMS
    update_phy_params(&list);

    cleanup_list(&list);
    return 0;
}
