}

int compare_frame_info(const LTE_DL_FRAME_MSG *a, const LTE_DL_FRAME_MSG *b) {
    if (a->dl_frame_info.frame_number != b->dl_frame_info.frame_number)
        return a->dl_frame_info.frame_number - b->dl_frame_info.frame_number;
    return a->dl_frame_info.time_slot_index - b->dl_frame_info.time_slot_index;
}

int insert_sorted(DoublyLinkedList *list, LTE_DL_FRAME_MSG *new_node) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || compare_frame_info(new_node, list->head) < 0) {
        new_node->next = list->head;
        if (list->head) list->head->prev = new_node;
        list->head = new_node;
        if (!list->tail) list->tail = new_node;
    } else {
        LTE_DL_FRAME_MSG *current = list->head;
        while (current->next && compare_frame_info(current->next, new_node) < 0)
            current = current->next;

        new_node->next = current->next;
        if (current->next) current->next->prev = new_node;
        current->next = new_node;
        new_node->prev = current;

        if (!new_node->next) list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

LTE_DL_FRAME_MSG* create_frame_msg(int frame_number, int time_slot_index) {
    LTE_DL_FRAME_MSG *node = (LTE_DL_FRAME_MSG*)malloc(sizeof(LTE_DL_FRAME_MSG));
    if (!node) return NULL;

    node->dl_frame_info.frame_number = frame_number;
    node->dl_frame_info.time_slot_index = time_slot_index;
    node->phy_params = (PHY_PARAMS){};
    node->channel_measurement.measurement_value = (double)(rand() % 100); // Example range [0, 99]
    node->prev = node->next = NULL;

    return node;
}

void free_list(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    LTE_DL_FRAME_MSG *current = list->head;
    while (current) {
        LTE_DL_FRAME_MSG *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

typedef struct {
    int transaction_id;
    double weighted_sum;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction *transactions;
    size_t count;
    pthread_mutex_t lock;
} TransactionProcessor;

TransactionProcessor* init_processor() {
    TransactionProcessor *processor = (TransactionProcessor*)malloc(sizeof(TransactionProcessor));
    if (!processor) return NULL;

    processor->transactions = NULL;
    processor->count = 0;
    pthread_mutex_init(&processor->lock, NULL);
    return processor;
}

void process_transaction(TransactionProcessor *processor, int transaction_id, double weighted_sum) {
    pthread_mutex_lock(&processor->lock);

    // Filter criteria: example age limit (e.g., 3 seconds)
    time_t current_time = time(NULL);
    size_t i = 0;
    while (i < processor->count && (current_time - processor->transactions[i].timestamp) <= 3) {
        if ((processor->transactions[i].weighted_sum < weighted_sum) ||
            ((processor->transactions[i].weighted_sum == weighted_sum) &&
             (processor->transactions[i].transaction_id > transaction_id))) {

            // Shift elements to remove old or lower priority transactions
            for (size_t j = i; j < processor->count - 1; ++j) {
                processor->transactions[j] = processor->transactions[j + 1];
            }
            --processor->count;
        } else {
            ++i;
        }
    }

    // Add new transaction if there's space or it has higher priority
    if (processor->count < 1000 || i < processor->count) { // Example max size of transactions array
        if (processor->count == 1000) {
            free(processor->transactions);
        }
        processor->transactions = (Transaction*)realloc(processor->transactions, sizeof(Transaction) * (processor->count + 1));
        processor->transactions[processor->count].transaction_id = transaction_id;
        processor->transactions[processor->count].weighted_sum = weighted_sum;
        processor->transactions[processor->count].timestamp = current_time;
        ++processor->count;
    }

    pthread_mutex_unlock(&processor->lock);
}

void get_max_weighted_transaction(TransactionProcessor *processor, int *max_id, double *max_weight) {
    pthread_mutex_lock(&processor->lock);

    if (processor->count == 0) {
        *max_id = -1;
        *max_weight = 0.0;
    } else {
        *max_id = processor->transactions[0].transaction_id;
        *max_weight = processor->transactions[0].weighted_sum;
    }

    pthread_mutex_unlock(&processor->lock);
}

void free_processor(TransactionProcessor *processor) {
    pthread_mutex_lock(&processor->lock);
    if (processor->transactions) {
        free(processor->transactions);
    }
    pthread_mutex_unlock(&processor->lock);

    pthread_mutex_destroy(&processor->lock);
    free(processor);
}
