// Memory pool for reusing memory blocks
#define MEMORY_POOL_SIZE 1000
NFAPI_CRC_INDICATION_PDU_T memoryPool[MEMORY_POOL_SIZE];
int poolIndex = 0;

// Function to generate random CRCFLAG
void setRandomCRCFlag(CRC_INDICATION_REL8_TAG *tag) {
