}

// Check validity of RX_UE_INFORMATION_TAG and RNTI
int isValidTag(int rxUeInformationTag, int rnti) {
    return (rxUeInformationTag >= 0 && rxUeInformationTag <= 1000) && 
           (rnti > 0 && rnti < 65536); // Example ranges
}

// Check if RNTI already exists in the list
int rntiExists(int rnti) {
    struct ListNode *current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) return 1;
        current = current->next;
    }
    return 0;
}

// Log error message with timestamp
void logError(const char *message) {
    time_t now = time(NULL);
    printf("%s: %s\n", ctime(&now), message);
}

// Function to manage dynamically resizable linked list
int manageNfaPduList(int N, int (*rxUeInformationTag)(void), int (*rnti)(void)) {
    if (poolIndex + N > MEMORY_POOL_SIZE) {
        logError("Memory pool exhausted");
        return -1;
    }

    pthread_mutex_lock(&list_lock);

    for (int i = 0; i < N; ++i) {
        int tag = rxUeInformationTag();
        int currentRnti = rnti();

        if (!isValidTag(tag, currentRnti)) {
            logError("Invalid RX_UE_INFORMATION_TAG or RNTI");
            continue;
        }

        if (rntiExists(currentRnti)) {
            logError("Duplicate RNTI encountered");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T *newNode = &memoryPool[poolIndex++];
        newNode->rxUeInformationTag = tag;
        newNode->rnti = currentRnti;
        setRandomCRCFlag(&newNode->crcIndicationRel8);

        struct ListNode *node = malloc(sizeof(struct ListNode));
        if (node == NULL) {
            logError("Memory allocation failed for new list node");
            continue;
        }

        node->data = *newNode;
        node->next = head;
        head = node;
    }

    pthread_mutex_unlock(&list_lock);

    return 0; // Success
}

