} PDUSession;

typedef struct SessionContextNode {
    unsigned long imsi;
    PDUSession *pdusession;
    struct SMMessageList {
        SMMessage message;
        struct SMMessageList *next;
    } *sm_messages;
    struct SessionContextNode *next;
} SessionContextNode;

// Function to initialize a new session context
SessionContextNode* init_session_context(unsigned long imsi, PDUSession *pdusession) {
    // Allocate memory for the session context node
    SessionContextNode *node = (SessionContextNode*) malloc(sizeof(SessionContextNode));
    if (!node) {
        perror("Failed to allocate memory for session context");
        return NULL;
    }

    node->imsi = imsi;
    node->pdusession = pdusession;
    node->sm_messages = NULL;
    node->next = NULL;

    return node;
}

// Function to add an SMMessage to a SessionContext
void add_sm_message(SessionContextNode *context, const char *sm_pdu, int status_flag) {
    if (!context || !sm_pdu) return;

    // Allocate memory for the new message and link it into the list
    struct SMMessageList *new_msg = (struct SMMessageList*) malloc(sizeof(struct SMMessageList));
    if (!new_msg) {
        perror("Failed to allocate memory for SMMessage");
        return;
    }

    new_msg->message.sm_pdu = strdup(sm_pdu);  // Copy PDU content
    if (!new_msg->message.sm_pdu) {
        free(new_msg);
        perror("Failed to duplicate SM-PDU string");
        return;
    }

    new_msg->message.timestamp = time(NULL);
    new_msg->message.status_flag = status_flag;

    // Insert at head for efficient insertion and retrieval
    new_msg->next = context->sm_messages;
    context->sm_messages = new_msg;
}

// Function to initialize PDUSession
PDUSession* init_pdusession(unsigned long session_id, const char *s_nssai, int pdusession_state) {
    // Allocate memory for the PDU Session
    PDUSession *pdusession = (PDUSession*) malloc(sizeof(PDUSession));
    if (!pdusession) {
        perror("Failed to allocate memory for PDUSession");
        return NULL;
    }

    pdusession->session_id = session_id;
    strncpy(pdusession->s_nssai, s_nssai, sizeof(pdusession->s_nssai) - 1);
    pdusession->pdusession_state = pdusession_state;

    return pdusession;
}

// Example function to clean up and free resources
void cleanup_session_context(SessionContextNode *head) {
    SessionContextNode *current = head, *temp;

    while (current) {
        // Free SM messages in each session context node
        struct SMMessageList *sm_message_current = current->sm_messages, *sm_temp;

        while (sm_message_current) {
            sm_temp = sm_message_current->next;
            free(sm_message_current->message.sm_pdu);
            free(sm_message_current);
            sm_message_current = sm_temp;
        }

        temp = current->next;
        if (current->pdusession) {
            free(current->pdusession);  // Free PDUSession
        }
        free(current);  // Free session context node
        current = temp;
    }
}

// Sample usage and testing of functions
int main() {
    unsigned long imsi = 1234567890UL;

    PDUSession *pdusession = init_pdusession(1, "5G-NR-01", 0);
    if (!pdusession) return EXIT_FAILURE;

    SessionContextNode *session_list_head = init_session_context(imsi, pdusession);
    if (!session_list_head) {
        free(pdusession);
        return EXIT_FAILURE;
    }

    add_sm_message(session_list_head, "Sample SM-PDU 1", 1);
    add_sm_message(session_list_head, "Sample SM-PDU 2", 0);

    // Cleanup resources
    cleanup_session_context(session_list_head);

    return 0;
}
