```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    // Example fields; adjust as needed.
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    int CRCFLAG;
} NFAPI_RX_FRAME_INFO;

typedef struct {
    NFAPI_RX_FRAME_INFO* frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} FrameArray;

// Initialize the dynamic array
void initFrameArray(FrameArray* array) {
    array->frames = (NFAPI_RX_FRAME_INFO*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_RX_FRAME_INFO));
    if (!array->frames) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
}

// Resize the dynamic array
void resizeFrameArray(FrameArray* array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_RX_FRAME_INFO* new_frames = (NFAPI_RX_FRAME_INFO*)realloc(array->frames, new_capacity * sizeof(NFAPI_RX_FRAME_INFO));
    if (!new_frames) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    array->frames = new_frames;
    array->capacity = new_capacity;
}

// Insert a frame into the dynamic array
void insertFrame(FrameArray* array, NFAPI_RX_FRAME_INFO frame) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        resizeFrameArray(array);
    }

    array->frames[array->size] = frame;
    array->size++;

    pthread_mutex_unlock(&array->lock);
}

// Retrieve a frame by index
NFAPI_RX_FRAME_INFO getFrame(FrameArray* array, size_t index) {
    pthread_mutex_lock(&array->lock);

    NFAPI_RX_FRAME_INFO frame = {0};
    if (index < array->size) {
        frame = array->frames[index];
    }

    pthread_mutex_unlock(&array->lock);
    return frame;
}

// Free the dynamic array
void freeFrameArray(FrameArray* array) {
    pthread_mutex_lock(&array->lock);

    free(array->frames);
    array->frames = NULL;
    array->capacity = 0;
    array->size = 0;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Example usage
int main() {
    FrameArray frameArray;
    initFrameArray(&frameArray);

    for (int i = 0; i < 20; ++i) {
        NFAPI_RX_FRAME_INFO frame = { .crc_tag = { .RX_UE_INFORMATION_TAG = i, .RNTI = i * 10 }, .CRCFLAG = rand() % 2 };
        insertFrame(&frameArray, frame);
    }

    for (size_t i = 0; i < frameArray.size; ++i) {
        NFAPI_RX_FRAME_INFO frame = getFrame(&frameArray, i);
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
               frame.crc_tag.RX_UE_INFORMATION_TAG, 
               frame.crc_tag.RNTI, 
               frame.CRCFLAG);
    }

    freeFrameArray(&frameArray);

    return 0;
}
```

### Key Points:
