u_char* resolve_dns_and_fetch_ue_info(const char *hostname, size_t n) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    struct hostent *he;
    u_char *ip_addresses = NULL;
    size_t ip_count = 0;
    NFAPI_CRC_INDICATION_PDU_T *ue_array = NULL;

    // Lock for thread safety
    pthread_mutex_lock(&mutex);

    // DNS resolution
    if ((he = gethostbyname(hostname)) == NULL) {
        herror("DNS Resolution");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Allocate memory for IP addresses
    ip_count = he->h_length * he->h_addr_list[0][1];
    ip_addresses = (u_char *)malloc(ip_count);

    if (!ip_addresses) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Copy IP addresses
    memcpy(ip_addresses, he->h_addr_list[0], ip_count);

    // Simulate fetching UE information with variable latency and error handling
    ue_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ue_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(ip_addresses);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Simulate fetching and populating UE information
