#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the structure as per task description
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 16

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safe access
    unsigned short *rnti_set; // Bitmap to quickly check RNTI presence
} CRCList;

// Utility function to resize the array if needed
static void ensure_capacity(CRCList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }

        list->capacity = new_capacity;
        list->array = new_array;

        // Resize rnti_set for larger capacity
        unsigned short *new_rnti_set = realloc(list->rnti_set, (list->capacity / 16 + 1) * sizeof(unsigned short));

        if (!new_rnti_set) {
            perror("Failed to reallocate memory for RNTI set");
            exit(EXIT_FAILURE);
        }

        list->rnti_set = new_rnti_set;
    }
}

// Initialize the CRCList structure
void init_crc_list(CRCList *list, size_t initial_capacity) {
    list->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;

    // Initialize the RNTI set for fast lookup
    list->rnti_set = calloc((initial_capacity / 16 + 1), sizeof(unsigned short));
    if (!list->rnti_set) {
        perror("Failed to allocate memory for RNTI set");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&list->lock, NULL);
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T ensuring unique RNTIs
int add_crc_pdu(CRCList *list, unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&list->lock);

    size_t index = list->size;

    if (index >= list->capacity / 16) {
        ensure_capacity(list);
    }

    // Check for duplicate RNTI using bitmap for efficiency
    unsigned short bit_index = RNTI / 16;
    unsigned char bit_position = RNTI % 16;

    if ((list->rnti_set[bit_index] & (1 << bit_position)) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate RNTI found
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &list->array[index];
    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly setting CRCFLAG

    // Mark the RNTI as present in the bitmap
    list->rnti_set[bit_index] |= (1 << bit_position);

    list->size++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Clean up resources allocated by CRCList
void free_crc_list(CRCList *list) {
    free(list->array);
    free(list->rnti_set);
    pthread_mutex_destroy(&list->lock);
}
```

### Explanation of Design Decisions:

1. **Memory Management**:
   - The `ensure_capacity` function doubles the capacity when needed to minimize reallocations, which helps in reducing fragmentation and overhead.
   - A bitmap (`rnti_set`) is used for fast RNTI checks, balancing space usage against speed.

2. **Concurrency Control**:
   - A single `pthread_mutex_t` lock ensures thread safety during modifications (additions) by serializing access to the list.
   - This solution balances simplicity and efficiency under high contention scenarios where more fine-grained locks might not yield significant benefits due to potential increased complexity.

3. **Trade-offs**:
   - Using a mutex is straightforward but can become a bottleneck under extremely high loads, which could be mitigated by using finer-grained locking or lock-free structures, at the cost of increased implementation complexity.
   - The bitmap for RNTI checking provides O(1) lookup time with minimal memory overhead.

4. **Scalability**:
   - The design is scalable due to dynamic resizing and efficient duplicate checks, making it suitable for high-load conditions where both concurrency and large data volumes are expected.']

