    size_t capacity;
    size_t size;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->capacity = initial_capacity;
    list->size = 0;
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    return list;
}

void resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return;

    list->data = new_data;
    list->capacity = new_capacity;
}

void add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&lock);

    if (list->size == list->capacity) {
        resize_dynamic_list(list, list->capacity * 2);
    }

    list->data[list->size++] = item;
    pthread_mutex_unlock(&lock);

    // Log the addition
    printf("Added: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u\n",
           item.RX_UE_INFORMATION_TAG, item.RNTI, item.CRC_INDICATION_REL8_TAG.CRCFLAG);
}

void initialize_and_populate_list(DynamicList *list, size_t N) {
    time_t start_time = time(NULL);

    for (size_t i = 0; i < N; ++i) {
        // Rate limiting: allow a maximum of MAX_ALLOCATIONS_PER_SECOND per second
        if ((time(NULL) - start_time) >= 1) {
            start_time = time(NULL);
        }

        while ((NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)) == NULL) {
            // Handle memory allocation failure by waiting and retrying
            usleep(1000);  // Sleep for 1ms before retrying
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand() % 256,  // Random tag generation example
            .RNTI = rand() % 65536,
            .CRC_INDICATION_REL8_TAG = { .CRCFLAG = rand() & 0xFF }
        };

        add_to_list(list, pdu);
    }
}

void free_dynamic_list(DynamicList *list) {
    if (list) {
        free(list->data);
        free(list);
    }
}

void reset_allocator_state(DynamicList **list) {
    pthread_mutex_lock(&lock);

    if (*list) {
        free_dynamic_list(*list);
    }

    *list = create_dynamic_list(10);  // Reinitialize with a default capacity

    pthread_mutex_unlock(&lock);
}

int main() {
    DynamicList *pdu_list = create_dynamic_list(10);

    if (!pdu_list) {
        fprintf(stderr, "Failed to initialize the list\n");
        return EXIT_FAILURE;
    }

    initialize_and_populate_list(pdu_list, 50);

    free_dynamic_list(pdu_list);
    return 0;
}
