['Below is a C implementation that meets the specified requirements using mutexes for thread safety, a sorted linked list for quick lookups, and a secondary list for tracking duplicates.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set between 0 and 1.
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SortedList;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DuplicateList;

// Function to initialize a sorted list
void init_sorted_list(SortedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to initialize the duplicate list
void init_duplicate_list(DuplicateList* dup_list) {
    dup_list->head = NULL;
    pthread_mutex_init(&dup_list->lock, NULL);
}

// Helper function to insert in sorted order
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

void insert_sorted(SortedList* list, Node* new_node) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || list->head->data.RNTI > new_node->data.RNTI) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next && current->next->data.RNTI < new_node->data.RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to check for duplicates and handle them
int is_duplicate(SortedList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 1; // Duplicate found
        current = current->next;
    }
    return 0;
}

void insert_duplicate(DuplicateList* dup_list, Node* new_node) {
    pthread_mutex_lock(&dup_list->lock);

    new_node->next = dup_list->head;
    dup_list->head = new_node;

    pthread_mutex_unlock(&dup_list->lock);
}

// Function to manage CRC indication PDU
Node* manage_crc_indication(SortedList* list, DuplicateList* dup_list) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Initialize with random values for demonstration purposes
    pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu.RNTI = rand() % 10000 + 1; // Ensure RNTI is non-zero
    pdu.CRC_INDICATION_REL8_TAG = rand() % 10;
    pdu.CRCFLAG = rand() % 2;
    pdu.timestamp = time(NULL);

    Node* new_node = create_node(pdu);
    if (!new_node) return NULL;

    if (is_duplicate(list, pdu.RNTI)) {
        insert_duplicate(dup_list, new_node); // Handle duplicate RNTI
    } else {
        insert_sorted(list, new_node);
    }

    return new_node;
}

// Function for periodic garbage collection
void garbage_collect(SortedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    // Example condition: remove nodes older than 1 hour (adjust as needed)
    time_t current_time = time(NULL);
    while (current != NULL) {
        if (difftime(current_time, current->data.timestamp) > 3600) { // 1 hour
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            Node* to_free = current;
            current = current->next;
            free(to_free);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    SortedList list;
    DuplicateList dup_list;

    init_sorted_list(&list);
    init_duplicate_list(&dup_list);

    // Example usage: Add 10 elements
    for (int i = 0; i < 10; ++i) {
        manage_crc_indication(&list, &dup_list);
    }

    // Periodic garbage collection
    garbage_collect(&list);

    // Cleanup
    pthread_mutex_destroy(&list.lock);
    pthread_mutex_destroy(&dup_list.lock);

    return 0;
}
```

