    struct Node* next;
} Node;

typedef struct {
    atomic_uintptr_t head;
    atomic_uintptr_t tail;
    pthread_mutex_t lock;
} ConcurrentList;

void init_list(ConcurrentList* list) {
    uintptr_t dummy_node = (uintptr_t)malloc(sizeof(Node));
    ((Node*)dummy_node)->next = NULL;
    atomic_store(&list->head, dummy_node);
    atomic_store(&list->tail, dummy_node);
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(ConcurrentList* list) {
    Node* current = (Node*)atomic_load(&list->head);
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

bool add_pdu(ConcurrentList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return false;

    new_node->data = pdu;
    new_node->next = NULL;

    uintptr_t tail;
    do {
        tail = atomic_load(&list->tail);
    } while (!atomic_compare_exchange_weak(&list->tail, &tail, (uintptr_t)new_node));

    Node* last = (Node*)atomic_load(&list->head);
    if (((Node*)tail)->next == NULL) {
        ((Node*)tail)->next = (Node*)new_node;
    }
    return true;
}

bool remove_pdu(ConcurrentList* list, int RNTI) {
    uintptr_t prev_ptr = atomic_load(&list->head);
    Node* prev = (Node*)prev_ptr;
    Node* current;

    while ((uintptr_t)(current = prev->next)) {
        if (current->data.RNTI == RNTI) {
            uintptr_t next_ptr = (uintptr_t)current->next;
            atomic_store(&prev->next, (Node*)next_ptr);
            free(current);
            return true;
        }
        prev = current;
    }
    return false;
}

void iterate_list(ConcurrentList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = (Node*)atomic_load(&list->head);
    while ((uintptr_t)current->next != atomic_load(&list->tail)) {
        current = current->next;
        callback(&current->data);
    }
}

void free_list(ConcurrentList* list) {
    destroy_list(list);
}
