#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16

typedef struct {
    // Example structure members
    unsigned int RNTI;
    unsigned int valid; // Assume this indicates a valid RX_UE_INFORMATION_TAG
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CRCList;

// Function to create a new list
CRCList* create_crc_list() {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL; // Handle allocation failure

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to resize the list
int resize_crc_list(CRCList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1; // Handle allocation failure

    list->data = new_data;
    list->capacity = new_capacity;

    return 0;
}

// Function to add an element
int add_crc_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || !pdu.valid) return -1; // Validate input

    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        int result = resize_crc_list(list);
        if (result != 0) {
            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }

    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to free the list
void destroy_crc_list(CRCList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);

    free(list);
}
```

