#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <errno.h>

#define INITIAL_CAPACITY 1000
#define MAX_CAPACITY 100000
#define ELEMENT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define THRESHOLD_PERCENTAGE 95

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    atomic_size_t count;
} DynamicArray;

pthread_mutex_t resize_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_array(DynamicArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->elements = malloc(array->capacity * ELEMENT_SIZE);
    if (!array->elements) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void resize_array_if_needed(DynamicArray *array) {
    pthread_mutex_lock(&resize_lock);

    size_t current_count = atomic_load(&array->count);
    size_t threshold_capacity = array->capacity * THRESHOLD_PERCENTAGE / 100;

    if (current_count >= threshold_capacity && array->capacity < MAX_CAPACITY) {
        size_t new_capacity = array->capacity * 2;
        if (new_capacity > MAX_CAPACITY) {
            new_capacity = MAX_CAPACITY;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(array->elements, new_capacity * ELEMENT_SIZE);
        if (!new_elements) {
            perror("Failed to resize array");
            exit(EXIT_FAILURE);
        }

        array->elements = new_elements;
        array->capacity = new_capacity;
    }

    pthread_mutex_unlock(&resize_lock);
}

int add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    resize_array_if_needed(array);

    size_t index = atomic_load(&array->count);

    if (index >= array->capacity) {
        return -ENOMEM;
    }

    memcpy(&array->elements[index], &element, ELEMENT_SIZE);
    atomic_fetch_add(&array->count, 1);

    return 0; // Success
}

void remove_element(DynamicArray *array, size_t index) {
    if (index < atomic_load(&array->count)) {
        memmove(&array->elements[index],
                &array->elements[index + 1],
                (atomic_fetch_sub(&array->count, 1) - index) * ELEMENT_SIZE);
    }
}

void free_array(DynamicArray *array) {
    if (array && array->elements) {
        free(array->elements);
        array->elements = NULL;
        array->capacity = 0;
        atomic_store(&array->count, 0);
    }
}

// Example serialization function
int serialize_elements(const DynamicArray *array, const char *file_path) {
    size_t count = atomic_load(&array->count);
    FILE *file = fopen(file_path, "wb");

    if (!file) {
        perror("Failed to open file for writing");
        return errno;
    }

    if (fwrite(array->elements, ELEMENT_SIZE, count, file) != count) {
        perror("Serialization failed");
        fclose(file);
        return errno;
    }

    fclose(file);
    return 0; // Success
}

// Example deserialization function
int deserialize_elements(DynamicArray *array, const char *file_path) {
    FILE *file = fopen(file_path, "rb");

    if (!file) {
        perror("Failed to open file for reading");
        return errno;
    }

    fseek(file, 0, SEEK_END);
    size_t count = ftell(file) / ELEMENT_SIZE;
    rewind(file);

    if (count > array->capacity) {
        free(array->elements);
        array->elements = malloc(count * ELEMENT_SIZE);
        if (!array->elements) {
            perror("Failed to allocate memory during deserialization");
            fclose(file);
            return errno;
        }
        array->capacity = count;
    }

    if (fread(array->elements, ELEMENT_SIZE, count, file) != count) {
        perror("Deserialization failed");
        fclose(file);
        free(array->elements); // Clean up
        array->elements = NULL;
        array->capacity = 0;
        atomic_store(&array->count, 0);
        return errno;
    }

    atomic_store(&array->count, count);
    fclose(file);
    return 0; // Success
}

```

### Key Points:
1. **Thread-Safety**: The code uses `pthread_mutex` for resizing the array to prevent race conditions during memory reallocation.
2. **Atomic Operations**: Atomic operations (`atomic_size_t`) are used for updating the count of elements, providing lock-free reads and writes where possible.
3. **Dynamic Resizing**: When 95% capacity is reached, the array resizes itself while maintaining thread safety with a mutex lock around the resizing logic.
4. **Serialization/Deserialization**: Basic file I/O operations ensure data can be serialized to disk and deserialized back into memory, including handling of file errors.
5. **Error Handling**: Includes checks for allocation failures, file access issues, etc., ensuring robust operation in face of common runtime errors.

This implementation prioritizes simplicity while addressing concurrency, scalability, and error management as specified in your requirements. Adjustments may be necessary to fit specific use cases or platform constraints.']

