    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PDU_Manager;

PDU_Manager* initialize_pdu_manager() {
    PDU_Manager *manager = (PDU_Manager *)malloc(sizeof(PDU_Manager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;

    manager->pdus = (LTE_DL_CCCH_MESSAGE_TYPE_UL *)calloc(manager->capacity, sizeof(LTE_DL_CCCH_MESSAGE_TYPE_UL));
    if (!manager->pdus) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int add_pdu(PDU_Manager *manager, int s1_ue_context_id, const char *nas_message, double dl_ambr) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;

        LTE_DL_CCCH_MESSAGE_TYPE_UL *new_pdus = (LTE_DL_CCCH_MESSAGE_TYPE_UL *)realloc(manager->pdus, new_capacity * sizeof(LTE_DL_CCCH_MESSAGE_TYPE_UL));
        if (!new_pdus) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }

        manager->pdus = new_pdus;
        manager->capacity = new_capacity;
    }

    LTE_DL_CCCH_MESSAGE_TYPE_UL *pdu = &manager->pdus[manager->count++];
    pdu->s1_ue_context_id = s1_ue_context_id;
    pdu->nas_message = strdup(nas_message);
    if (!pdu->nas_message) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failure for NAS message
    }
    pdu->dl_ambr = dl_ambr;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

LTE_DL_CCCH_MESSAGE_TYPE_UL* get_pdu(PDU_Manager *manager, size_t index) {
    if (index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);
    LTE_DL_CCCH_MESSAGE_TYPE_UL *pdu = &manager->pdus[index];
    pthread_mutex_unlock(&manager->lock);

    return pdu;
}

void free_pdu_manager(PDU_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdus[i].nas_message);
    }

    free(manager->pdus);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);

    free(manager);
}

int main() {
    PDU_Manager *manager = initialize_pdu_manager();
    if (!manager) {
        printf("Failed to initialize PDU manager.\n");
        return 1;
    }

    int result = add_pdu(manager, 123, "Example NAS Message", 5000.0);
    if (result != 0) {
        printf("Failed to add PDU: %d\n", result);
        free_pdu_manager(manager);
        return 1;
    }

    LTE_DL_CCCH_MESSAGE_TYPE_UL *pdu = get_pdu(manager, 0);
    if (pdu) {
        printf("PDU - S1 UE Context ID: %d, NAS Message: %s, DL AMBR: %.2f\n",
               pdu->s1_ue_context_id, pdu->nas_message, pdu->dl_ambr);
    }

    free_pdu_manager(manager);

    return 0;
}
