['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    uint32_t RNTI;
    int CRCFLAG;
    time_t timestamp;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

typedef struct SecondaryList {
    Node* head;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SecondaryList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for primary list\n");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

SecondaryList* createSecondaryList(size_t capacity) {
    SecondaryList* secList = (SecondaryList*)malloc(sizeof(SecondaryList));
    if (!secList) {
        fprintf(stderr, "Memory allocation failed for secondary list\n");
        return NULL;
    }
    secList->head = NULL;
    secList->capacity = capacity;
    secList->count = 0;
    pthread_mutex_init(&secList->lock, NULL);
    return secList;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for node\n");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertToList(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node** current = &list->head;

    while (*current) {
        if ((*current)->data.crcIndication.RNTI == data.crcIndication.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return; // Duplicate RNTI, not inserted
        }
        current = &(*current)->next;
    }

    Node* newNode = createNode(data);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    *current = newNode;
    pthread_mutex_unlock(&list->lock);
}

void insertToSecondaryList(SecondaryList* secList, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&secList->lock);

    if (secList->count >= secList->capacity) {
        size_t newCapacity = secList->capacity * 2;
        // Handle resizing logic here
        pthread_mutex_unlock(&secList->lock);
        fprintf(stderr, "Secondary list capacity exceeded\n");
        return;
    }

    Node** current = &secList->head;

    while (*current) {
        current = &(*current)->next;
    }

    Node* newNode = createNode(data);
    if (!newNode) {
        pthread_mutex_unlock(&secList->lock);
        return;
    }

    *current = newNode;
    secList->count++;
    pthread_mutex_unlock(&secList->lock);
}

int serializeLinkedList(const LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int deserializeLinkedList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insertToList(list, data);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void freeSecondaryList(SecondaryList* secList) {
    pthread_mutex_lock(&secList->lock);

    Node* current = secList->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&secList->lock);
    pthread_mutex_destroy(&secList->lock);
    free(secList);
}

int main() {
    LinkedList* list = createLinkedList();
    SecondaryList* secList = createSecondaryList(1000);

    if (!list || !secList) return -1;

    srand(time(NULL));
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand();
        data.crcIndication.RNTI = rand() % 100000 + 1;
        data.crcIndication.CRCFLAG = rand() % 2;
        data.crcIndication.timestamp = time(NULL);

        insertToList(list, data);
    }

    serializeLinkedList(list, "list_data.bin");
    deserializeLinkedList(list, "list_data.bin");

    freeLinkedList(list);
    freeSecondaryList(secList);

    return 0;
}
```

