typedef struct {
    time_t timestamp;
    size_t length;
    char *data;
} Packet;

// Function to generate random packet data of a given length.
char* generate_random_data(size_t length) {
    char *data = (char*)malloc(length);
    if (!data) return NULL;  // Handle memory allocation failure.

    for (size_t i = 0; i < length; ++i) {
        data[i] = rand() % 256;  // Generate random byte values.
    }

    return data;
}

// Function to manage the dynamically allocated array of packets.
int populate_packets(Packet **packets, size_t *num_packets, size_t max_packet_size, size_t max_num_packets) {
    if (!packets || !num_packets || *num_packets > 0) {
        // Initial check and validation for input parameters.
        return -1;
    }

    srand((unsigned int)time(NULL));  // Seed random number generator.

    for (size_t i = 0; i < max_num_packets; ++i) {
        size_t packet_length = rand() % (max_packet_size + 1);  // Random length up to max_packet_size.

        Packet *new_packet = (Packet*)malloc(sizeof(Packet));
        if (!new_packet) return -2;  // Handle memory allocation failure.

        new_packet->timestamp = time(NULL);
        new_packet->length = packet_length;
        new_packet->data = generate_random_data(packet_length);

        if (!new_packet->data) {
            free(new_packet);  // Clean up in case of data generation failure.
            return -3;  // Indicate error on data allocation failure.
        }

        *packets = (Packet*)realloc(*packets, sizeof(Packet) * (*num_packets + 1));
        if (!*packets) {
            free(new_packet->data);
            free(new_packet);  // Clean up in case of reallocation failure.
            return -4;
        }

        (*packets)[*num_packets] = *new_packet;  // Add the packet to the array.
        ++(*num_packets);

        free(new_packet);  // Free temporary allocation after copying data.
    }

    return 0;  // Success
}

int main() {
    Packet *packet_array = NULL;
    size_t num_packets = 0;

    const size_t MAX_PACKET_SIZE = 1024;
    const size_t MAX_NUM_PACKETS = 100;

    int result = populate_packets(&packet_array, &num_packets, MAX_PACKET_SIZE, MAX_NUM_PACKETS);
