#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Simulated external logging mechanism
void log_message(const char *message) {
    printf("%s\n", message);
}

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Simulated memory pool for efficient allocation
#define POOL_SIZE 1024

typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode *free_list;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
        if (!node) return; // Handle allocation failure
        node->next = memory_pool.free_list;
        memory_pool.free_list = node;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    MemoryPoolNode *node = memory_pool.free_list;
    if (!node) {
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL; // Pool exhausted
    }
    NFAPI_CRC_INDICATION_PDU_T *data_ptr = &node->data;
    memory_pool.free_list = node->next;
    pthread_mutex_unlock(&memory_pool.lock);
    return data_ptr;
}

void deallocate_to_pool(NFAPI_CRC_INDICATION_PDU_T *data) {
    MemoryPoolNode *node = (MemoryPoolNode *)(((char*)data) - offsetof(MemoryPoolNode, data));
    pthread_mutex_lock(&memory_pool.lock);
    node->next = memory_pool.free_list;
    memory_pool.free_list = node;
    pthread_mutex_unlock(&memory_pool.lock);
}

void create_and_process_crc_indications(size_t N) {
    if (N == 0) return;

    NFAPI_CRC_INDICATION_PDU_T *indication_list[N];
    size_t processed_count = 0;
    time_t start_time = time(NULL);

    for (size_t i = 0; i < N; ++i) {
        indication_list[i] = allocate_from_pool();
        if (!indication_list[i]) continue;

        indication_list[i]->RX_UE_INFORMATION_TAG = rand(); // Example assignment
        indication_list[i]->RNTI = rand() & 0xFFFF;
        indication_list[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

        processed_count++;
    }

    size_t failed_logs = 0;

    for (size_t i = 0; i < N && indication_list[i]; ++i) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Processed element %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%hu, CRCFLAG=%hhu",
                 i + 1, indication_list[i]->RX_UE_INFORMATION_TAG, indication_list[i]->RNTI,
                 indication_list[i]->CRC_INDICATION_REL8_TAG.CRCFLAG);

        int retries = 0;
        while (retries < 3) {
            if (log_message(log_msg)) {
                break; // Successful logging
            }
            retries++;
        }

        if (retries == 3) {
            failed_logs++;
        }

        deallocate_to_pool(indication_list[i]);
    }

    time_t end_time = time(NULL);
    log_message("Completed processing CRC indications");

    if (failed_logs > 0) {
        char error_msg[128];
        snprintf(error_msg, sizeof(error_msg), "Failed to write %zu logs successfully", failed_logs);
        log_message(error_msg);
    }

    double duration = difftime(end_time, start_time);
    char summary_msg[128];
    snprintf(summary_msg, sizeof(summary_msg),
             "Processed %zu elements in %.2f seconds", processed_count, duration);
    log_message(summary_msg);
}

int main() {
    srand(time(NULL));
    init_memory_pool();

    create_and_process_crc_indications(1000); // Example usage

    return 0;
}
