['Below is a C implementation for managing and populating a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures while ensuring thread safety and unique RNTI values:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ATTEMPTS 5
#define LIST_CAPACITY_INITIAL 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->elements = malloc(LIST_CAPACITY_INITIAL * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = LIST_CAPACITY_INITIAL;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

bool is_rnti_unique(DynamicList* list, unsigned long rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

void expand_list_if_needed(DynamicList* list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) return; // Handle reallocation failure gracefully

        list->elements = new_elements;
        list->capacity = new_capacity;
    }
}

bool add_crc_indication_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    for (int attempt = 0; attempt < MAX_ATTEMPTS; ++attempt) {
        if (is_rnti_unique(list, pdu.RNTI)) {
            expand_list_if_needed(list);

            list->elements[list->size] = pdu;
            list->size++;

            pthread_mutex_unlock(&list->mutex);
            return true;
        } else {
            pdu.RNTI += 1; // Attempt to fix the RNTI by incrementing
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return false;
}

void free_dynamic_list(DynamicList* list) {
    if (list) {
        if (list->elements) free(list->elements);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int main() {
    DynamicList* list = create_dynamic_list();
    if (!list) return EXIT_FAILURE;

    for (size_t i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Random RX tag
        pdu.RNTI = rand() % 100000 + 1; // Random RNTI
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2 == 0;

        if (!add_crc_indication_pdu(list, pdu)) {
            printf("Failed to add PDU with RNTI: %lu\n", pdu.RNTI);
        }
    }

    free_dynamic_list(list);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` for locking during list modifications.
- **Dynamic Resizing**: The list expands its capacity when needed.
- **Unique RNTI Handling**: Checks and adjusts RNTIs to ensure uniqueness.
- **Error Handling**: Gracefully handles memory allocation failures.']

