    RX_UE_INFORMATION_TAG rxUeInformationTag;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    LTE_PHY_LAYER_CONFIG_T phyLayerConfig;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void fetch_BWP_configuration(int *config);
int is_network_available();
void log_message(const char *message);

#define MAX_PCI 503 // Maximum PCI value for a given frequency band
#define MAX_RETRIES 3

pthread_mutex_t network_rate_limit_lock = PTHREAD_MUTEX_INITIALIZER;
int requests_made_in_last_minute = 0;

NFAPI_CRC_INDICATION_PDU_T* generate_NFAPICRCINDICATIONPDU(unsigned int num_pdus, int frequency_band) {
    if (!is_network_available()) {
        log_message("Network unavailable. Aborting operation.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdulist = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdulist) {
        log_message("Memory allocation failed.");
        return NULL;
    }

    int pcis[MAX_PCI + 1] = {0}; // Track used PCIs
    srand(time(NULL));

    for (unsigned int i = 0; i < num_pdus; ++i) {
        // Generate unique PCI
        int pci = rand() % MAX_PCI + 1;
        while (pcis[pci]) {
            pci = rand() % MAX_PCI + 1;
        }
        pcis[pci] = 1;

        // Fetch BWP configuration with retry logic and rate limiting
        int bwp_config = -1;
        for (int attempt = 0; attempt < MAX_RETRIES && bwp_config == -1; ++attempt) {
            pthread_mutex_lock(&network_rate_limit_lock);
            if (requests_made_in_last_minute >= 60) {
                log_message("Rate limit reached, sleeping...");
                sleep(60); // Wait for the minute to reset
                requests_made_in_last_minute = 0;
            }
            fetch_BWP_configuration(&bwp_config);
            requests_made_in_last_minute++;
            pthread_mutex_unlock(&network_rate_limit_lock);

            if (bwp_config == -1) {
                log_message("Failed to fetch BWP configuration, retrying...");
                sleep(1); // Backoff before retry
            }
        }

        // Populate PDU structure
        pdulist[i].rxUeInformationTag.RNTI = rand(); // Example RNTI generation
        pdulist[i].RNTI = rand();
        pdulist[i].crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Random CRCFLAG
        pdulist[i].phyLayerConfig.PCI = pci;
        pdulist[i].phyLayerConfig.BWPartConfig = bwp_config;
        pdulist[i].phyLayerConfig.CRSPowerSetting = rand(); // Example CRS power setting

    }

    return pdulist;
}

// Mock implementations of external dependencies
void fetch_BWP_configuration(int *config) {
    // Simulate network latency and possible failure
    sleep(1);
    if (rand() % 5 == 0) { // Randomly simulate a failure
        *config = -1; 
    } else {
        *config = rand() % 10 + 1;
    }
}

int is_network_available() {
    return rand() % 2 != 0; // Simulate network availability randomly
}

void log_message(const char *message) {
    printf("%s\n", message);
}
