#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    char session_id[256];
    time_t timestamp;
    size_t bytes_received;
    size_t bytes_sent;
} SessionStats;

typedef struct {
    SessionStats *sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} StatsManager;

#define INITIAL_CAPACITY 10

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

StatsManager* create_stats_manager() {
    StatsManager *manager = (StatsManager*)malloc(sizeof(StatsManager));
    if (!manager) return NULL;

    manager->sessions = (SessionStats*)calloc(INITIAL_CAPACITY, sizeof(SessionStats));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);

    log_message("StatsManager created.");
    return manager;
}

void destroy_stats_manager(StatsManager *manager) {
    if (!manager) return;

    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    log_message("StatsManager destroyed.");
}

static void resize_sessions(StatsManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    SessionStats *new_sessions = (SessionStats*)realloc(manager->sessions, new_capacity * sizeof(SessionStats));
    if (!new_sessions) return;

    manager->sessions = new_sessions;
    manager->capacity = new_capacity;

    log_message("Dynamic array resized.");
}

void add_or_update_session(StatsManager *manager, const char *session_id, size_t bytes_received, size_t bytes_sent) {
    if (!manager || !session_id) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) {
            manager->sessions[i].bytes_received += bytes_received;
            manager->sessions[i].bytes_sent += bytes_sent;
            manager->sessions[i].timestamp = time(NULL);
            log_message("Session updated.");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->count == manager->capacity) {
        resize_sessions(manager);
    }

    strncpy(manager->sessions[manager->count].session_id, session_id, sizeof(manager->sessions[0].session_id) - 1);
    manager->sessions[manager->count].bytes_received = bytes_received;
    manager->sessions[manager->count].bytes_sent = bytes_sent;
    manager->sessions[manager->count].timestamp = time(NULL);

    log_message("New session added.");
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

size_t calculate_total_bytes(StatsManager *manager) {
    if (!manager) return 0;

    size_t total_received = 0;
    size_t total_sent = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        total_received += manager->sessions[i].bytes_received;
        total_sent += manager->sessions[i].bytes_sent;
    }

    log_message("Total bytes calculated.");
    return total_received + total_sent;
}

void reset_statistics(StatsManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        manager->sessions[i].bytes_received = 0;
        manager->sessions[i].bytes_sent = 0;
    }

    log_message("Statistics reset.");
    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    StatsManager *manager = create_stats_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create stats manager.\n");
        return EXIT_FAILURE;
    }

    add_or_update_session(manager, "session1", 100, 150);
    add_or_update_session(manager, "session2", 200, 250);

    size_t total_bytes = calculate_total_bytes(manager);
    printf("Total bytes exchanged: %zu\n", total_bytes);

    reset_statistics(manager);

    destroy_stats_manager(manager);
    return EXIT_SUCCESS;
}
