class Session {
    constructor(id) {
        this.id = id;
        this.timestamps = [];
        this.bytesReceived = 0;
        this.bytesSent = 0;
    }

    updateMetrics(timestamp, bytesReceived, bytesSent) {
        this.timestamps.push(timestamp);
        this.bytesReceived += bytesReceived;
        this.bytesSent += bytesSent;
    }
}

class SessionManager {
    constructor() {
        this.sessions = new Map();
        this.lock = new AsyncLock(); // Simulating a thread-safe lock
    }

    async addOrUpdateSession(id, timestamp, bytesReceived, bytesSent) {
        await this.lock.acquire(`session-${id}`, async () => {
            let session = this.sessions.get(id);
            if (!session) {
                session = new Session(id);
                this.sessions.set(id, session);
            }
            session.updateMetrics(timestamp, bytesReceived, bytesSent);
        });
    }

    getTotalBytes() {
        return Array.from(this.sessions.values()).reduce((total, session) => {
            return total + session.bytesReceived + session.bytesSent;
        }, 0);
    }

    async logData(loggingSystem) {
        await this.lock.acquire('logging', async () => {
            const data = Array.from(this.sessions.entries())
                .map(([id, session]) => ({
                    id,
                    timestamps: session.timestamps,
                    bytesReceived: session.bytesReceived,
                    bytesSent: session.bytesSent
                }));

            // Assuming loggingSystem is an object with a method `log`
            await loggingSystem.log(data);
        });
    }
}

// Example usage of the SessionManager class
const manager = new SessionManager();
manager.addOrUpdateSession('session1', Date.now(), 100, 200);

class AsyncLock {
    constructor() {
        this.locks = new Map();
    }

    async acquire(id, task) {
        if (!this.locks.has(id)) {
            this.locks.set(id, Promise.resolve());
        }

        const unlock = () => {
            let chain = this.locks.get(id);
            this.locks.set(id, chain.then(() => undefined));
            return chain;
        };

        await this.locks.get(id);
        try {
            await task();
        } finally {
            unlock();
        }
    }
}

