#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_RETRIES 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

void log_message(const char* message) {
    // Simulated logging function with retry logic
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (simulate_logging_system_availability()) {
            printf("%s\n", message);
            return;
        }
        retries++;
        sleep(1);  // Wait before retrying
    }
    buffer_message_locally(message);
}

void buffer_message_locally(const char* message) {
    // Simulated local buffering of messages
    static FILE *buffer_file = NULL;
    if (!buffer_file) {
        buffer_file = fopen("log_buffer.txt", "a");
    }
    if (buffer_file) {
        fprintf(buffer_file, "%s\n", message);
        fflush(buffer_file);
    }
}

int simulate_logging_system_availability() {
    // Simulate network/system availability for logging
    return rand() % 2;  // Randomly simulates success or failure
}

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        log_message("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_rnti_exists(List* list, int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void insert_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Failed to allocate memory for node");
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T create_crc_indication(int index) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = index;
    pdu.RNTI = rand() % 1000;  // Random RNTI
    pdu.CRCFLAG = rand() % 2;  // Random CRC flag (0 or 1)
    return pdu;
}

void create_and_process_crc_indications(int N) {
    if (N <= 0) {
        log_message("Invalid number of elements");
        return;
    }

    List* crc_list = create_list();
    if (!crc_list) {
        log_message("Failed to create CRC list");
        return;
    }

    clock_t start_time = clock();

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = create_crc_indication(i);
        if (!is_rnti_exists(crc_list, pdu.RNTI)) {
            insert_list(crc_list, pdu);
        } else {
            log_message("Duplicate RNTI found");
        }
    }

    clock_t end_time = clock();
    double duration = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "Processed %d elements in %.2f seconds", N, duration);
    log_message(log_buffer);

    free_list(crc_list);
}

int main() {
    srand(time(NULL));  // Seed the random number generator
    create_and_process_crc_indications(10);  // Example usage with 10 elements
    return 0;
}
