    manager->ue_states = (UEState**)calloc(INITIAL_CAPACITY, sizeof(UEState*));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

// Function to resize the UEStateManager
void resize_UEStateManager(UEStateManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    UEState **new_states = (UEState**)realloc(manager->ue_states, new_capacity * sizeof(UEState*));
    if (new_states) {
        memset(new_states + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(UEState*));
        manager->ue_states = new_states;
        manager->capacity = new_capacity;
    }
}

// Function to add a UEState
int add_UEStateManager(UEStateManager *manager, int ue_id, int rnti, int cell_id) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->capacity) {
        resize_UEStateManager(manager);
    }

    UEState *ue_state = (UEState*)malloc(sizeof(UEState));
    if (!ue_state) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Memory allocation failed
    }

    ue_state->ue_id = ue_id;
    ue_state->rnti = rnti;
    ue_state->cell_id = cell_id;
    ue_state->measurement_report = (MeasurementReport*)malloc(sizeof(MeasurementReport));
    if (!ue_state->measurement_report) {
        free(ue_state);
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Memory allocation failed
    }

    manager->ue_states[manager->count++] = ue_state;

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

// Function to safely fetch a UEState by index
UEState* get_UEStateManager(UEStateManager *manager, size_t index) {
    if (index >= manager->count) {
        return NULL; // Index out of bounds
    }
    pthread_mutex_lock(&manager->mutex);
    UEState *ue_state = manager->ue_states[index];
    pthread_mutex_unlock(&manager->mutex);
    return ue_state;
}

// Function to free a MeasurementReport safely
void freeMeasurementReport(MeasurementReport *report) {
    if (report) {
        // Perform any necessary cleanup for the report here
        free(report);
    }
}

// Function to delete a UEState by index
int remove_UEStateManager(UEStateManager *manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->count) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Index out of bounds
    }

    freeMeasurementReport(manager->ue_states[index]->measurement_report);
    free(manager->ue_states[index]);
    memmove(&manager->ue_states[index], &manager->ue_states[index + 1],
            (manager->count - index - 1) * sizeof(UEState*));
    manager->count--;

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

// Function to clean up the UEStateManager
void cleanup_UEStateManager(UEStateManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        freeMeasurementReport(manager->ue_states[i]->measurement_report);
        free(manager->ue_states[i]);
    }

    free(manager->ue_states);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

