['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE_MB 1
#define MEMORY_PER_STRUCTURE_BYTES (1000 * 1024)
#define CACHE_SIZE 256

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int memory_usage_bytes;
    unsigned int rnti_cache[CACHE_SIZE];
    int cache_index;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->memory_usage_bytes = 0;
    memset(list->rnti_cache, 0, sizeof(list->rnti_cache));
    list->cache_index = 0;
    return list;
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_rnti_cached(LinkedList* list, unsigned int rnti) {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (list->rnti_cache[i] == rnti) return 1;
    }
    if (list->cache_index < CACHE_SIZE) {
        list->rnti_cache[list->cache_index++] = rnti;
    } else {
        for (int i = 0; i < CACHE_SIZE - 1; ++i) {
            list->rnti_cache[i] = list->rnti_cache[i + 1];
        }
        list->rnti_cache[CACHE_SIZE - 1] = rnti;
    }
    return 0;
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    for (int attempt = 0; attempt < 10; ++attempt) {
        if (is_rnti_cached(list, data.RNTI)) {
            printf("Duplicate RNTI detected. Retrying...\n");
            pthread_mutex_unlock(&list->lock);
            usleep(100000); // Sleep for 100ms to handle network latency
            continue;
        }

        Node* current = list->head;
        while (current) {
            if (current->data.RNTI == data.RNTI) {
                printf("Duplicate RNTI detected. Retrying...\n");
                pthread_mutex_unlock(&list->lock);
                usleep(100000); // Sleep for 100ms to handle network latency
                attempt++;
                continue;
            }
            current = current->next;
        }

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = list->head;
        list->head = new_node;

        list->memory_usage_bytes += sizeof(Node);
        if (list->memory_usage_bytes > MEMORY_PER_STRUCTURE_BYTES) {
            printf("Memory limit exceeded. Logging event.\n");
            // Log the memory usage event
            free(new_node); // Rollback allocation
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->cache_index = (list->cache_index + 1) % CACHE_SIZE;
        list->rnti_cache[list->cache_index] = data.RNTI;

        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    pthread_mutex_unlock(&list->lock);
    printf("Failed to insert after retries.\n");
    return -1;
}

void populate_list(LinkedList* list, unsigned int num_structures) {
    srand(time(NULL));
    for (unsigned int i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        // Simulate fetching RX_UE_INFORMATION_TAG and CRCFLAG from external service
        data.RX_UE_INFORMATION_TAG = rand() % 1000000;
        data.RNTI = rand() % 10000 + 1; // Ensure RNTI is non-zero
        data.CRC_INDICATION_REL8_TAG = rand() & 0xFF;
        data.CRCFLAG = rand() & 1;

        if (insert_node(list, data) != 0) {
            printf("Error inserting structure %u.\n", i);
        }
    }
}

int main() {
    LinkedList* list = create_list();
    if (!list) {
        printf("Failed to create linked list.\n");
        return -1;
    }

    populate_list(list, 1000);

    free_list(list);
    return 0;
}
```']

