#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UE_COUNT 10000 // Configurable maximum number of UE context entries
#define DEFAULT_QOS_FLOW_COUNT 10

typedef struct {
    int flow_id;
    char qos_parameters[256];
} QoS_FLOW_T;

typedef struct {
    int ue_identifier;
    char ip_address[16]; // Assuming IPv4 address
    QoS_FLOW_T *qos_flows;
    size_t qos_flow_count;
    size_t max_qos_flow_capacity;
} UE_CONTEXT_DATA_T;

typedef struct {
    UE_CONTEXT_DATA_T *ue_contexts[MAX_UE_COUNT];
    size_t ue_count;
    int max_ue_capacity;
} UE_MANAGER_T;

// Initialize UE Manager
void init_ue_manager(UE_MANAGER_T *manager, size_t max_ue_capacity) {
    manager->ue_count = 0;
    manager->max_ue_capacity = max_ue_capacity;
}

// Log error message
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Add a new UE context data
int add_ue_context(UE_MANAGER_T *manager, int ue_identifier, const char *ip_address) {
    if (manager->ue_count >= manager->max_ue_capacity) {
        log_error("Maximum number of UE contexts reached.");
        return -1;
    }

    UE_CONTEXT_DATA_T *new_ue = malloc(sizeof(UE_CONTEXT_DATA_T));
    if (!new_ue) {
        log_error("Memory allocation for UE context failed.");
        return -1;
    }

    new_ue->ue_identifier = ue_identifier;
    strncpy(new_ue->ip_address, ip_address, sizeof(new_ue->ip_address) - 1);
    new_ue->ip_address[sizeof(new_ue->ip_address) - 1] = '\0';

    new_ue->qos_flows = malloc(DEFAULT_QOS_FLOW_COUNT * sizeof(QoS_FLOW_T));
    if (!new_ue->qos_flows) {
        free(new_ue);
        log_error("Memory allocation for QoS flows failed.");
        return -1;
    }

    new_ue->qos_flow_count = 0;
    new_ue->max_qos_flow_capacity = DEFAULT_QOS_FLOW_COUNT;

    manager->ue_contexts[manager->ue_count++] = new_ue;
    return 0; // Success
}

// Add a QoS flow to an existing UE context
int add_qos_flow_to_ue(UE_MANAGER_T *manager, int ue_identifier, int flow_id) {
    for (size_t i = 0; i < manager->ue_count; ++i) {
        if (manager->ue_contexts[i]->ue_identifier == ue_identifier) {
            if (manager->ue_contexts[i]->qos_flow_count >= manager->ue_contexts[i]->max_qos_flow_capacity) {
                size_t new_capacity = manager->ue_contexts[i]->max_qos_flow_capacity * 2;
                QoS_FLOW_T *new_flows = realloc(manager->ue_contexts[i]->qos_flows, new_capacity * sizeof(QoS_FLOW_T));
                if (!new_flows) {
                    log_error("Memory reallocation for QoS flows failed.");
                    return -1;
                }
                manager->ue_contexts[i]->qos_flows = new_flows;
                manager->ue_contexts[i]->max_qos_flow_capacity = new_capacity;
            }

            // Ensure unique flow_id
            for (size_t j = 0; j < manager->ue_contexts[i]->qos_flow_count; ++j) {
                if (manager->ue_contexts[i]->qos_flows[j].flow_id == flow_id) {
                    log_error("QoS flow ID collision detected.");
                    return -1;
                }
            }

            QoS_FLOW_T *new_flow = &manager->ue_contexts[i]->qos_flows[manager->ue_contexts[i]->qos_flow_count++];
            new_flow->flow_id = flow_id;
            strcpy(new_flow->qos_parameters, "default"); // Initialize with default parameters

            return 0; // Success
        }
    }

    log_error("UE identifier not found.");
    return -1;
}

// Cleanup UE Manager
void cleanup_ue_manager(UE_MANAGER_T *manager) {
    for (size_t i = 0; i < manager->ue_count; ++i) {
        free(manager->ue_contexts[i]->qos_flows);
        free(manager->ue_contexts[i]);
    }
    memset(manager, 0, sizeof(UE_MANAGER_T));
}

int main() {
    UE_MANAGER_T ue_manager;
    init_ue_manager(&ue_manager, MAX_UE_COUNT);

    if (add_ue_context(&ue_manager, 1, "192.168.0.1") == 0) {
        add_qos_flow_to_ue(&ue_manager, 1, 100);
    }

    cleanup_ue_manager(&ue_manager);
    return 0;
}
