        log_message("ERROR", "Mutex init failed");
        return -1;
    }
    manager->structures = NULL;
    manager->count = 0;
    return 0;
}

int populate_structures(CRC_Structure_Manager* manager, int num_structs, int seed) {
    size_t required_memory = num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (required_memory > MAX_MEMORY_LIMIT) {
        log_message("ERROR", "Memory limit exceeded");
        return -1;
    }

    pthread_mutex_lock(&manager->mutex);
    manager->structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_memory);

    if (!manager->structures) {
        log_message("ERROR", "Out of memory");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    for (int i = 0; i < num_structs; ++i) {
        manager->structures[i] = create_structure(seed, i);
    }
    manager->count = num_structs;

    log_message("INFO", "Structures populated successfully");
    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

void cleanup_manager(CRC_Structure_Manager* manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->structures) {
        free(manager->structures);
        manager->structures = NULL;
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);

    pthread_mutex_destroy(&manager->mutex);
}

int main() {
    CRC_Structure_Manager manager;

    if (initialize_manager(&manager) != 0) return -1;

    int num_structs = MAX_STRUCTS; // Use maximum possible based on memory limit
    int seed = time(NULL); // Example of using current time as a seed

    if (populate_structures(&manager, num_structs, seed) == 0) {
        log_message("INFO", "Operation completed successfully");
    }

    cleanup_manager(&manager);
    return 0;
}
