bool validate_rnti(uint16_t rnti) {
    return (rnti >= MIN_RNTI && rnti <= MAX_RNTI);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pdu_list(size_t n, int *error_code) {
    if (n == 0 || error_code == NULL) {
        *error_code = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        *error_code = -2;  // Memory allocation failure
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < n; ++i) {
        uint16_t rnti = rand() % ((MAX_RNTI + 1) - MIN_RNTI) + MIN_RNTI;

        if (!validate_rnti(rnti)) {
            LOG_INVALID_RNTI(rnti);
            continue;
        }

        pthread_mutex_lock(&mutex);

        pdu_list[i].ue_info.RNTI = rnti;
        pdu_list[i].crc_ind_rel8.CRCFLAG = rand() % 2;

        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
    *error_code = 0; // Success
    return pdu_list;
}

void free_nfa_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    if (pdu_list) {
        free(pdu_list);
    }
}
