#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define constants for the priority levels.
#define PRIORITY_HIGH 0
#define PRIORITY_MEDIUM 1
#define PRIORITY_LOW 2

typedef struct {
    int valid;
    char rx_ue_information_tag[256];
    char rnti[10];
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T ue_info;
    char crc_indication_rel8_tag[256];
    unsigned long crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Priority Queue Node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int priority;
    struct Node* next;
} Node;

// Priority Queue Structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

// Function prototypes
PriorityQueue* create_priority_queue();
void enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data, int priority);
NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* pq);
void free_priority_queue(PriorityQueue* pq);

// CRC Indication Manager Structure
typedef struct {
    PriorityQueue* queue;
    pthread_mutex_t mutex;
} CRCIndicationManager;

CRCIndicationManager* initialize_crc_manager() {
    CRCIndicationManager* manager = (CRCIndicationManager*)malloc(sizeof(CRCIndicationManager));
    if (!manager) return NULL;

    manager->queue = create_priority_queue();
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void free_crc_manager(CRCIndicationManager* manager) {
    if (manager) {
        free_priority_queue(manager->queue);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

PriorityQueue* create_priority_queue() {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (!pq) return NULL;

    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);

    return pq;
}

void enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = data;
    new_node->priority = priority;
    new_node->next = NULL;

    pthread_mutex_lock(&pq->lock);

    // Insert node in the correct position based on priority
    Node** current = &(pq->head);
    while (*current && (*current)->priority <= priority) {
        current = &((*current)->next);
    }

    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&pq->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* pq) {
    NFAPI_CRC_INDICATION_PDU_T data = {0};

    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL) {
        pthread_mutex_unlock(&pq->lock);
        return data;
    }

    Node* temp = pq->head;
    data = temp->data;
    pq->head = pq->head->next;

    free(temp);

    pthread_mutex_unlock(&pq->lock);

    return data;
}

void free_priority_queue(PriorityQueue* pq) {
    if (pq) {
        Node* current = pq->head;
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
        pthread_mutex_destroy(&pq->lock);
        free(pq);
    }
}

// External interface for synchronous query
NFAPI_CRC_INDICATION_PDU_T get_next_crc_indication(CRCIndicationManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    NFAPI_CRC_INDICATION_PDU_T data = dequeue(manager->queue);

    pthread_mutex_unlock(&manager->mutex);

    return data;
}

// External interface for asynchronous query (callback mechanism)
typedef void (*Callback)(NFAPI_CRC_INDICATION_PDU_T data);

void async_get_crc_indication(CRCIndicationManager* manager, Callback callback) {
    NFAPI_CRC_INDICATION_PDU_T data = get_next_crc_indication(manager);

    if (data.crcflag != 0) { // Assuming valid CRCFLAG is non-zero
        pthread_t thread;
        void* result;

        // Allocate memory for the data to be passed into the callback
        NFAPI_CRC_INDICATION_PDU_T *callback_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (callback_data) {
            *callback_data = data;

            pthread_create(&thread, NULL, (void *(*)(void *))callback, callback_data);
            pthread_join(thread, &result); // Ensure thread completion
            free(callback_data);
        }
    }
}

// Example usage of async_get_crc_indication with a simple callback function
void example_callback(NFAPI_CRC_INDICATION_PDU_T* data) {
    printf("Callback: RX UE Info Tag = %s\n", data->ue_info.rx_ue_information_tag);
}

int main() {
    CRCIndicationManager* manager = initialize_crc_manager();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .valid = 1, .crcflag = 123 };
    strcpy(pdu1.ue_info.rx_ue_information_tag, "Tag1");
    strcpy(pdu1.crc_indication_rel8_tag, "Rel8_Tag1");

    enqueue(manager->queue, pdu1, PRIORITY_HIGH);

    async_get_crc_indication(manager, example_callback);

    free_crc_manager(manager);

    return 0;
}
