#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_PACKETS 1000

typedef struct {
    uint64_t timestamp;
    int sensor_id;
    float readings[10]; // Example size, adjust based on actual usage
} SensorPacket;

typedef struct {
    SensorPacket *packets[MAX_PACKETS];
    int front;
    int rear;
    int count;
} RingBuffer;

RingBuffer* createRingBuffer() {
    RingBuffer *buffer = (RingBuffer*)malloc(sizeof(RingBuffer));
    buffer->front = 0;
    buffer->rear = -1;
    buffer->count = 0;
    return buffer;
}

int isFull(RingBuffer *buffer) {
    return buffer->count == MAX_PACKETS;
}

int isEmpty(RingBuffer *buffer) {
    return buffer->count == 0;
}

void enqueue(RingBuffer *buffer, SensorPacket *packet) {
    if (isFull(buffer)) {
        // Handle overflow scenario: remove oldest packet
        free(buffer->packets[buffer->front]);
        buffer->front = (buffer->front + 1) % MAX_PACKETS;
    }
    buffer->rear = (buffer->rear + 1) % MAX_PACKETS;
    buffer->packets[buffer->rear] = packet;
    buffer->count++;
}

SensorPacket* dequeue(RingBuffer *buffer) {
    if (isEmpty(buffer)) return NULL;
    SensorPacket *packet = buffer->packets[buffer->front];
    buffer->front = (buffer->front + 1) % MAX_PACKETS;
    buffer->count--;
    return packet;
}

void freeRingBuffer(RingBuffer *buffer) {
    while (!isEmpty(buffer)) {
        free(dequeue(buffer));
    }
    free(buffer);
}

SensorPacket* streamlinedDataProcessor(int socket_fd, int max_packets) {
    RingBuffer *buffer = createRingBuffer();

    char buffer[1024]; // Adjust based on expected packet size
    SensorPacket *packet;

    while (1) { // Replace with a proper loop condition or termination signal
