        if (bytes_received > 0) {
            packet = (SensorPacket*)malloc(sizeof(SensorPacket));

            // Parse the data from the received buffer into SensorPacket
            // Example parsing logic
            memcpy(&packet->timestamp, buffer, sizeof(packet->timestamp));
            memcpy(&packet->sensor_id, buffer + sizeof(packet->timestamp), sizeof(packet->sensor_id));
            memcpy(packet->readings, buffer + sizeof(packet->timestamp) + sizeof(packet->sensor_id), 10 * sizeof(float));

            enqueue(buffer, packet);
        } else if (bytes_received == 0 || (bytes_received < 0 && errno != EAGAIN)) {
            // Handle disconnection or error
            break;
        }

        // Add logic to process buffer and interact with the data pipeline
    }

    freeRingBuffer(buffer);

    return dequeue(buffer); // Example, adjust based on actual use case
}

