async function eventDrivenLogger(eventSource) {
    let loggedEventsCount = 0;

    const logEvent = async (eventData) => {
        try {
            await fetch('https://central.logging.service/log', {
                method: 'POST',
                body: JSON.stringify(eventData),
                headers: { 'Content-Type': 'application/json' }
            });
            loggedEventsCount++;
        } catch (error) {
            console.error("Logging failed, retrying...", error);
            setTimeout(() => logEvent(eventData), 1000); // Retry with backoff
        }
    };

    eventSource.onmessage = async function(event) {
        try {
            const eventData = JSON.parse(event.data);

            await logEvent(eventData);

        } catch (error) {
            console.error("Error processing event", error);
        }
    };

    return new Promise((resolve, reject) => {
        setTimeout(() => resolve(loggedEventsCount), 10000); // Timeout for demonstration
    });
}

