        log_operation("Failed to allocate memory for PDU array");
        pthread_mutex_unlock(&pdu_mutex);
        return;
    }

    pdu_count = initial_size;

    // Initialize the structures with default values
    for (size_t i = 0; i < pdu_count; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Example value
        pdu_array[i].RNTI = rand();                           // Random RNTI
        memset(pdu_array[i].CRC_INDICATION_REL8_TAG, 0, sizeof(pdu_array[i].CRC_INDICATION_REL8_TAG)); // Default tag
        pdu_array[i].CRCFLAG = calculate_crcflag(pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI, pdu_array[i].CRC_INDICATION_REL8_TAG);
    }

    log_operation("PDU array initialized successfully");
    pthread_mutex_unlock(&pdu_mutex);
}

void update_pdu(int index, uint16_t rx_tag, uint32_t rnti, const uint8_t *crc_tag) {
    if (index < 0 || index >= pdu_count) {
        log_operation("Invalid PDU index for update");
        return;
    }

    pthread_mutex_lock(&pdu_mutex);

    pdu_array[index].RX_UE_INFORMATION_TAG = rx_tag;
    pdu_array[index].RNTI = rnti;
    memcpy(pdu_array[index].CRC_INDICATION_REL8_TAG, crc_tag, sizeof(pdu_array[index].CRC_INDICATION_REL8_TAG));
    pdu_array[index].CRCFLAG = calculate_crcflag(rx_tag, rnti, crc_tag);

    log_operation("PDU updated successfully");

    pthread_mutex_unlock(&pdu_mutex);
}

size_t get_pdu_count() {
    size_t count;
    pthread_mutex_lock(&pdu_mutex);
    count = pdu_count;
    pthread_mutex_unlock(&pdu_mutex);
    return count;
}

void iterate_and_update_crcflags(int (*criteria)(uint16_t, uint32_t, const uint8_t *)) {
    for (size_t i = 0; i < pdu_count; ++i) {
        if (criteria(pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI, pdu_array[i].CRC_INDICATION_REL8_TAG)) {
            pthread_mutex_lock(&pdu_mutex);
            pdu_array[i].CRCFLAG = calculate_crcflag(pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI, pdu_array[i].CRC_INDICATION_REL8_TAG);
            pthread_mutex_unlock(&pdu_mutex);
        }
    }
}

void cleanup_unused_pdus() {
    // Implement cleanup logic based on application-specific criteria
    // For now, we'll assume a placeholder function that marks unused PDUs for example purposes.
    log_operation("Cleanup of unused PDU structures");
}

int main() {
    initialize_pdu_array(100);  // Start with an initial size

    // Example usage and test
    uint8_t crc_tag_example[4] = {0xAA, 0xBB, 0xCC, 0xDD};
    update_pdu(5, 12345, 67890, crc_tag_example);

