        pthread_mutex_lock(&pool_mutex);

        while (pool_size == 0) {
            pthread_cond_wait(&data_ready_cond, &pool_mutex);
        }

        for (int i = 0; i < pool_size; ++i) {
            if (pool[i] != NULL && /* some condition to check completeness */) {
                notify_callback(pool[i]);
            }
        }

        pthread_mutex_unlock(&pool_mutex);
    }
}

void initialize_notifier_thread() {
