typedef struct {
    size_t min_payload_size[3]; // Assuming 3 types: TYPE_A, TYPE_B, TYPE_C
} Config;

Config config = {{10, 20, 30}}; // Example sizes

int log_message(const char *message) {
    printf("LOG: %s\n", message);
    return 0;
}

int validate_config() {
    if (config.min_payload_size[TYPE_A] <= 0 || 
        config.min_payload_size[TYPE_B] <= 0 ||
        config.min_payload_size[TYPE_C] <= 0) {
        log_message("Invalid configuration: Payload sizes must be positive.");
        return -1;
    }
    return 0;
}

int initialize_nfa_rrc_messages(NFAPI_RRC_MESSAGE_T *messages, size_t n) {
    if (validate_config() != 0) {
        return -1; // Configuration validation failed
    }

    for (size_t i = 0; i < n; ++i) {
        RRC_MESSAGE_TYPE type = (RRC_MESSAGE_TYPE)(rand() % 3); // Example random assignment

        size_t required_size = config.min_payload_size[type];

        messages[i].type = type;
        messages[i].buffer = malloc(required_size);

        if (!messages[i].buffer) {
            log_message("Buffer allocation failed.");
            return -1; // Allocation failure
        }

        memset(messages[i].buffer, 0, required_size); // Initialize buffer to zero

        // Example integrity check: ensure buffer is not null and properly sized
        if (messages[i].buffer == NULL || messages[i].buffer_size != required_size) {
            free(messages[i].buffer);
            log_message("Buffer integrity validation failed.");
            return -1;
        }

        messages[i].buffer_size = required_size;

        // Example logging of successful allocation
