SessionManager* createSessionManager(size_t initialCapacity) {
    SessionManager* manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = calloc(initialCapacity, sizeof(UESessionRecord*));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }
    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroySessionManager(SessionManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]->radioLinks);
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addSession(SessionManager* manager, int ueid, RadioLink* radioLinks, size_t numRadioLinks) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        UESessionRecord** newSessions = realloc(manager->sessions, newCapacity * sizeof(UESessionRecord*));
        if (!newSessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    }

    UESessionRecord* session = malloc(sizeof(UESessionRecord));
    if (!session) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }
    session->UEID = ueid;
    session->radioLinks = malloc(numRadioLinks * sizeof(RadioLink));
    if (!session->radioLinks) {
        free(session);
        pthread_mutex_unlock(&manager->lock);
        return -3; // Memory allocation failed
    }
    for (size_t i = 0; i < numRadioLinks; ++i) {
        session->radioLinks[i] = radioLinks[i]; // Assuming shallow copy is acceptable
    }
    session->numRadioLinks = numRadioLinks;
    session->timestamp = time(NULL);
    session->status = 1; // Active

    manager->sessions[manager->count++] = session;

    pthread_mutex_unlock(&manager->lock);

    // Optionally batch process and update NMS here, with error handling for connectivity issues
    return 0;
}

int removeSession(SessionManager* manager, int ueid) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->UEID == ueid) {
            free(manager->sessions[i]->radioLinks);
            free(manager->sessions[i]);

            // Shift remaining sessions
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(UESessionRecord*));
            manager->count--;

            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

int updateSessionStatus(SessionManager* manager, int ueid, int newStatus) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->UEID == ueid) {
            manager->sessions[i]->status = newStatus;

            // Optionally batch process and update NMS here, with error handling for connectivity issues
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

