typedef struct {
    time_t timestamp;
    char event_type[50];
    int unique_id;
    char metadata[256];
} NetworkEventLog;

typedef struct {
    NetworkEventLog *logs;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventLogManager;

// Function prototypes
int init_log_manager(EventLogManager *manager, size_t initial_capacity);
int add_event(EventLogManager *manager, NetworkEventLog event);
int remove_event_by_id(EventLogManager *manager, int unique_id);
int get_events_by_date_range(EventLogManager *manager, time_t start, time_t end, NetworkEventLog **events_out, size_t *count_out);
int get_events_by_type(EventLogManager *manager, const char *event_type, NetworkEventLog **events_out, size_t *count_out);
void export_to_json(const NetworkEventLog *logs, size_t count, FILE *file);
void export_to_csv(const NetworkEventLog *logs, size_t count, FILE *file);

// Implementations
int init_log_manager(EventLogManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->logs = (NetworkEventLog *)malloc(initial_capacity * sizeof(NetworkEventLog));
    if (!manager->logs) return -1;
    return 0;
}

int add_event(EventLogManager *manager, NetworkEventLog event) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkEventLog *new_logs = realloc(manager->logs, new_capacity * sizeof(NetworkEventLog));
        if (!new_logs) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->logs = new_logs;
        manager->capacity = new_capacity;
    }

    memcpy(&manager->logs[manager->size], &event, sizeof(NetworkEventLog));
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_event_by_id(EventLogManager *manager, int unique_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->logs[i].unique_id == unique_id) {
            memmove(&manager->logs[i], &manager->logs[i + 1], (manager->size - i - 1) * sizeof(NetworkEventLog));
            manager->size--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int get_events_by_date_range(EventLogManager *manager, time_t start, time_t end, NetworkEventLog **events_out, size_t *count_out) {
    pthread_mutex_lock(&manager->lock);

    size_t count = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->logs[i].timestamp >= start && manager->logs[i].timestamp <= end) {
            count++;
        }
    }

    *events_out = (NetworkEventLog *)malloc(count * sizeof(NetworkEventLog));
    if (!*events_out) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t j = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->logs[i].timestamp >= start && manager->logs[i].timestamp <= end) {
            (*events_out)[j++] = manager->logs[i];
        }
    }

    *count_out = count;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int get_events_by_type(EventLogManager *manager, const char *event_type, NetworkEventLog **events_out, size_t *count_out) {
    pthread_mutex_lock(&manager->lock);

    size_t count = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->logs[i].event_type, event_type) == 0) {
            count++;
        }
    }

    *events_out = (NetworkEventLog *)malloc(count * sizeof(NetworkEventLog));
    if (!*events_out) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t j = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->logs[i].event_type, event_type) == 0) {
            (*events_out)[j++] = manager->logs[i];
        }
    }

    *count_out = count;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void export_to_json(const NetworkEventLog *logs, size_t count, FILE *file) {
    fprintf(file, "[\n");
    for (size_t i = 0; i < count; ++i) {
        if (i > 0) fprintf(file, ",\n");
        fprintf(file, "  { \"timestamp\": %ld, \"event_type\": \"%s\", \"unique_id\": %d, \"metadata\": \"%s\" }",
                logs[i].timestamp, logs[i].event_type, logs[i].unique_id, logs[i].metadata);
    }
    fprintf(file, "\n]");
}

void export_to_csv(const NetworkEventLog *logs, size_t count, FILE *file) {
    for (size_t i = 0; i < count; ++i) {
        if (i > 0) fprintf(file, "\n");
        fprintf(file, "\"%ld\",\"%s\",%d,\"%s\"", logs[i].timestamp, logs[i].event_type, logs[i].unique_id, logs[i].metadata);
    }
}

void cleanup_log_manager(EventLogManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->logs);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
