```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_EVENTS 100

typedef struct {
    uint32_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    time_t timestamp;
    char event_type[50];
    int unique_id;
    NFAPI_CRC_INDICATION_PDU_T *crc_data;
    size_t crc_count;
    // Additional fields can be added here
} NetworkEventLogEntry;

typedef struct Node {
    NetworkEventLogEntry *entry;
    int priority; // Lower number indicates higher priority
    struct Node* next;
} PriorityQueueNode;

typedef struct {
    PriorityQueueNode* head;
    pthread_mutex_t lock;
} Priority_Queue;

typedef struct {
    NetworkEventLogEntry **events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventLogManager;

// Function prototypes
void initialize_priority_queue(Priority_Queue *queue);
int priority_compare(const void *a, const void *b);
PriorityQueueNode* create_node(NetworkEventLogEntry *entry, int priority);
void enqueue(Priority_Queue *queue, NetworkEventLogEntry *entry, int priority);
NetworkEventLogEntry* dequeue(Priority_Queue *queue);
void initialize_event_log_manager(EventLogManager *manager);
int add_event(EventLogManager *manager, const char *event_type, int unique_id, NFAPI_CRC_INDICATION_PDU_T *crc_data, size_t crc_count);
void free_event_log_manager(EventLogManager *manager);
NetworkEventLogEntry* query_event(const EventLogManager *manager, int unique_id);

// Priority Queue Functions
void initialize_priority_queue(Priority_Queue *queue) {
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
}

int priority_compare(const void *a, const void *b) {
    PriorityQueueNode* nodeA = *(PriorityQueueNode**)a;
    PriorityQueueNode* nodeB = *(PriorityQueueNode**)b;
    return nodeA->priority - nodeB->priority;
}

PriorityQueueNode* create_node(NetworkEventLogEntry *entry, int priority) {
    PriorityQueueNode* new_node = (PriorityQueueNode*)malloc(sizeof(PriorityQueueNode));
    if (!new_node) {
        perror("Failed to allocate memory for queue node");
        exit(EXIT_FAILURE);
    }
    new_node->entry = entry;
    new_node->priority = priority;
    new_node->next = NULL;
    return new_node;
}

void enqueue(Priority_Queue *queue, NetworkEventLogEntry *entry, int priority) {
    pthread_mutex_lock(&queue->lock);
    PriorityQueueNode* new_node = create_node(entry, priority);

    if (!queue->head || queue->head->priority > priority) {
        new_node->next = queue->head;
        queue->head = new_node;
    } else {
        PriorityQueueNode *current = queue->head;
        while (current->next && current->next->priority <= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&queue->lock);
}

NetworkEventLogEntry* dequeue(Priority_Queue *queue) {
    pthread_mutex_lock(&queue->lock);
    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }
    PriorityQueueNode* temp = queue->head;
    NetworkEventLogEntry* entry = temp->entry;
    queue->head = queue->head->next;
    free(temp);
    pthread_mutex_unlock(&queue->lock);
    return entry;
}

// Event Log Manager Functions
void initialize_event_log_manager(EventLogManager *manager) {
    manager->events = (NetworkEventLogEntry**)malloc(MAX_EVENTS * sizeof(NetworkEventLogEntry*));
    if (!manager->events) {
        perror("Failed to allocate memory for event log");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = MAX_EVENTS;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_event(EventLogManager *manager, const char *event_type, int unique_id, NFAPI_CRC_INDICATION_PDU_T *crc_data, size_t crc_count) {
    if (manager->count >= manager->capacity) {
        // Resize array
        size_t new_capacity = manager->capacity * 2;
        NetworkEventLogEntry** new_events = realloc(manager->events, new_capacity * sizeof(NetworkEventLogEntry*));
        if (!new_events) {
            perror("Failed to resize event log");
            return -1;
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    NetworkEventLogEntry *entry = (NetworkEventLogEntry*)malloc(sizeof(NetworkEventLogEntry));
    if (!entry) {
        perror("Failed to allocate memory for network event");
        return -1;
    }

    entry->timestamp = time(NULL);
    strncpy(entry->event_type, event_type, sizeof(entry->event_type) - 1);
    entry->unique_id = unique_id;
    entry->crc_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(crc_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry->crc_data) {
        perror("Failed to allocate memory for CRC data");
        free(entry);
        return -1;
    }
    memcpy(entry->crc_data, crc_data, crc_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    entry->crc_count = crc_count;

    pthread_mutex_lock(&manager->lock);
    manager->events[manager->count++] = entry;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void free_event_log_manager(EventLogManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]) {
            free(manager->events[i]->crc_data);
            free(manager->events[i]);
        }
    }
    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
}

NetworkEventLogEntry* query_event(const EventLogManager *manager, int unique_id) {
    pthread_mutex_lock((pthread_mutex_t*)&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i] && manager->events[i]->unique_id == unique_id) {
            NetworkEventLogEntry* entry = manager->events[i];
            pthread_mutex_unlock((pthread_mutex_t*)&manager->lock);
            return entry;
        }
    }
    pthread_mutex_unlock((pthread_mutex_t*)&manager->lock);
    return NULL;
}

// Example usage
int main() {
    EventLogManager manager;
    initialize_event_log_manager(&manager);

    NFAPI_CRC_INDICATION_PDU_T crc_data[2] = {{.crc_flag = 1}, {.crc_flag = 0}};
    add_event(&manager, "NetworkEvent", 101, crc_data, 2);

    NetworkEventLogEntry* queried_entry = query_event(&manager, 101);
    if (queried_entry) {
        printf("Queried Event: %s\n", queried_entry->event_type);
    }

    free_event_log_manager(&manager);
    return 0;
}
```

### Key Features:
- **Dynamic Array**: The `EventLogManager` manages a dynamic array of event log entries, resizing as needed.
- **Priority Queue**: A priority queue is implemented to handle urgent data first.
- **Thread Safety**: Mutex locks ensure thread-safe operations on shared resources.
- **Memory Management**: Memory allocation and deallocation are handled carefully to prevent leaks.
- **Extendability**: The structure can be easily extended with additional fields as needed.

This code provides a solid foundation for managing network event log entries efficiently, with room for future enhancements.']

