#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENT_TYPE_LENGTH 50
#define MAX_METADATA_LENGTH 256

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct NetworkEventLog {
    time_t timestamp;
    EventType eventType;
    char uniqueID[64];
    char metadata[MAX_METADATA_LENGTH];
    int priority; // For prioritization logic
    struct NetworkEventLog *next;
} NetworkEventLog;

typedef struct {
    NetworkEventLog *head;
    pthread_mutex_t lock;
} LogManager;

// Function declarations
LogManager* create_log_manager();
void destroy_log_manager(LogManager *manager);
int add_event(LogManager *manager, time_t timestamp, EventType eventType, const char *uniqueID, const char *metadata, int priority);
NetworkEventLog* find_event_by_id(const LogManager *manager, const char *uniqueID);
int remove_event(LogManager *manager, const char *uniqueID);
void export_logs_to_json(const LogManager *manager, const char *filename);
void export_logs_to_csv(const LogManager *manager, const char *filename);
void retrieve_logs_by_date_range(const LogManager *manager, time_t start, time_t end, NetworkEventLog **results, int *count);
void retrieve_logs_by_event_type(const LogManager *manager, EventType eventType, NetworkEventLog **results, int *count);

// Function implementations
LogManager* create_log_manager() {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    if (!manager) return NULL;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_log_manager(LogManager *manager) {
    NetworkEventLog *current = manager->head;
    while (current) {
        NetworkEventLog *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_event(LogManager *manager, time_t timestamp, EventType eventType, const char *uniqueID, const char *metadata, int priority) {
    NetworkEventLog *newEntry = (NetworkEventLog *)malloc(sizeof(NetworkEventLog));
    if (!newEntry) return -1;

    newEntry->timestamp = timestamp;
    newEntry->eventType = eventType;
    strncpy(newEntry->uniqueID, uniqueID, sizeof(newEntry->uniqueID));
    strncpy(newEntry->metadata, metadata, MAX_METADATA_LENGTH);
    newEntry->priority = priority;
    newEntry->next = NULL;

    pthread_mutex_lock(&manager->lock);

    if (!manager->head || manager->head->timestamp > timestamp) {
        newEntry->next = manager->head;
        manager->head = newEntry;
    } else {
        NetworkEventLog *current = manager->head;
        while (current->next && current->next->timestamp <= timestamp) {
            if (strcmp(current->uniqueID, uniqueID) == 0) { // Duplicate check
                free(newEntry);
                pthread_mutex_unlock(&manager->lock);
                return -2; // Duplicate entry
            }
            current = current->next;
        }
        newEntry->next = current->next;
        current->next = newEntry;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NetworkEventLog* find_event_by_id(const LogManager *manager, const char *uniqueID) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    NetworkEventLog *current = manager->head;
    while (current) {
        if (strcmp(current->uniqueID, uniqueID) == 0) {
            pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
    return NULL;
}

int remove_event(LogManager *manager, const char *uniqueID) {
    pthread_mutex_lock(&manager->lock);

    NetworkEventLog **current = &(manager->head);
    while (*current) {
        if (strcmp((*current)->uniqueID, uniqueID) == 0) {
            NetworkEventLog *toDelete = *current;
            *current = toDelete->next;
            free(toDelete);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Not found
}

void export_logs_to_json(const LogManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    NetworkEventLog *current = manager->head;
    fprintf(file, "[\n");
    while (current) {
        fprintf(file, "{ \"timestamp\": \"%ld\", \"eventType\": %d, \"uniqueID\": \"%s\", \"metadata\": \"%s\" }\n",
                current->timestamp, current->eventType, current->uniqueID, current->metadata);
        current = current->next;
    }
    fprintf(file, "]\n");

    fclose(file);
    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
}

void export_logs_to_csv(const LogManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    fprintf(file, "timestamp,eventType,uniqueID,metadata\n");

    NetworkEventLog *current = manager->head;
    while (current) {
        fprintf(file, "%ld,%d,%s,\"%s\"\n", current->timestamp, current->eventType, current->uniqueID, current->metadata);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
}

void retrieve_logs_by_date_range(const LogManager *manager, time_t start, time_t end, NetworkEventLog **results, int *count) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    NetworkEventLog dummyHead = {0};
    NetworkEventLog *current = &dummyHead;
    *results = NULL;
    *count = 0;

    NetworkEventLog *iter = manager->head;
    while (iter) {
        if (iter->timestamp >= start && iter->timestamp <= end) {
            current->next = iter;
            current = current->next;
            (*count)++;
        }
        iter = iter->next;
    }

    current->next = NULL; // End the list
    *results = dummyHead.next;

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
}

void retrieve_logs_by_event_type(const LogManager *manager, EventType eventType, NetworkEventLog **results, int *count) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    NetworkEventLog dummyHead = {0};
    NetworkEventLog *current = &dummyHead;
    *results = NULL;
    *count = 0;

    NetworkEventLog *iter = manager->head;
    while (iter) {
        if (iter->eventType == eventType) {
            current->next = iter;
            current = current->next;
            (*count)++;
        }
        iter = iter->next;
    }

    current->next = NULL; // End the list
    *results = dummyHead.next;

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
}

// Example usage
int main() {
    LogManager *manager = create_log_manager();
    if (!manager) return -1;

    add_event(manager, time(NULL), EVENT_TYPE_A, "12345", "Sample metadata A", 1);

    NetworkEventLog *events;
    int count;
    retrieve_logs_by_date_range(manager, time(NULL) - 3600, time(NULL), &events, &count);

    for (int i = 0; i < count; ++i) {
        printf("Timestamp: %ld, Event Type: %d, Unique ID: %s\n", events[i].timestamp, events[i].eventType, events[i].uniqueID);
        events[i] = *events[i].next;
    }

    destroy_log_manager(manager);

    return 0;
}
