#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for Network Event Log Entry
typedef struct {
    time_t timestamp;
    int eventType;
    char eventMessage[256];
} NetworkEventLogEntry;

// Dynamic array manager
typedef struct {
    NetworkEventLogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;  // Mutex for thread safety
} EventLogManager;

// Function prototypes
void init_event_log_manager(EventLogManager *manager, size_t initial_capacity);
void destroy_event_log_manager(EventLogManager *manager);
int add_network_event(EventLogManager *manager, int eventType, const char *eventMessage);
void generate_synthetic_data(EventLogManager *manager, size_t num_events);

// Initialization function
void init_event_log_manager(EventLogManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->entries = malloc(sizeof(NetworkEventLogEntry) * initial_capacity);
    if (manager->entries == NULL) {
        perror("Failed to allocate memory for event log entries");
        exit(EXIT_FAILURE);
    }
}

// Destroy function
void destroy_event_log_manager(EventLogManager *manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager->entries);
}

// Add network event with thread safety and dynamic resizing
int add_network_event(EventLogManager *manager, int eventType, const char *eventMessage) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {  // Resize if needed
        size_t new_capacity = manager->capacity * 2;
        NetworkEventLogEntry *new_entries = realloc(manager->entries, sizeof(NetworkEventLogEntry) * new_capacity);
        if (!new_entries) {
            perror("Failed to reallocate memory for event log entries");
            pthread_mutex_unlock(&manager->mutex);
            return -1;  // Return error
        }
        manager->capacity = new_capacity;
        manager->entries = new_entries;
    }

    NetworkEventLogEntry *entry = &manager->entries[manager->count++];
    entry->timestamp = time(NULL);  // Set current timestamp
    entry->eventType = eventType;
    strncpy(entry->eventMessage, eventMessage, sizeof(entry->eventMessage) - 1);
    entry->eventMessage[sizeof(entry->eventMessage) - 1] = '\0';

    pthread_mutex_unlock(&manager->mutex);
    return 0;  // Success
}

// Generate synthetic data for testing purposes
void generate_synthetic_data(EventLogManager *manager, size_t num_events) {
    const char *messages[] = {"Packet received", "Connection established", "Data transmitted", "Error occurred"};
    int num_message_types = sizeof(messages) / sizeof(messages[0]);

    for (size_t i = 0; i < num_events; ++i) {
        int eventType = rand() % num_message_types;
        const char *eventMessage = messages[eventType];

        if (add_network_event(manager, eventType, eventMessage) != 0) {
            fprintf(stderr, "Failed to add network event\n");
            break; // Exit on failure
        }
    }
}

// Example usage
int main() {
    EventLogManager manager;
    init_event_log_manager(&manager, 10);  // Initial capacity of 10

    generate_synthetic_data(&manager, 50);  // Generate 50 synthetic events

    for (size_t i = 0; i < manager.count; ++i) {
        printf("Timestamp: %ld, Event Type: %d, Message: %s\n",
               manager.entries[i].timestamp,
               manager.entries[i].eventType,
               manager.entries[i].eventMessage);
    }

    destroy_event_log_manager(&manager);  // Clean up resources
    return 0;
}
