#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG; // Placeholder for actual type
    int RNTI;                   // Placeholder for actual type
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int allocate_nfa_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t max_structures, size_t buffer_size_limit, FILE *log_file, unsigned char enable_logging) {
    if (max_structures == 0 || array == NULL) return -1;

    pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for the array of structures
    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*array == NULL) {
        if (enable_logging && log_file) {
            pthread_mutex_lock(&log_mutex);
            fprintf(log_file, "Memory allocation failed.\n");
            pthread_mutex_unlock(&log_mutex);
        }
        return -1;
    }

    int last_crc_flag = -2;  // Initialize to a value different from possible CRC_FLAG values (0 or 1)
    size_t count = 0;

    for (size_t i = 0; i < max_structures && count * sizeof(NFAPI_CRC_INDICATION_PDU_T) <= buffer_size_limit; ++i, ++count) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand(); // Replace with actual logic
        (*array)[i].RNTI = rand();                  // Replace with actual logic
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Example range

        int crc_flag;
        do {
            crc_flag = rand() % 2;  // Randomly set CRCFLAG as 0 or 1
        } while (crc_flag == last_crc_flag); // Ensure no two consecutive structures have the same CRCFLAG

        last_crc_flag = crc_flag;

        if (enable_logging && log_file) {
            pthread_mutex_lock(&log_mutex);
            fprintf(log_file, "Structure %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
                    i, (*array)[i].RX_UE_INFORMATION_TAG, (*array)[i].RNTI,
                    (*array)[i].CRC_INDICATION_REL8_TAG, crc_flag);
            pthread_mutex_unlock(&log_mutex);
        }
    }

    // Check if memory allocation for all requested structures succeeded
    if (count < max_structures) {
        free(*array);
        *array = NULL;
        if (enable_logging && log_file) {
            pthread_mutex_lock(&log_mutex);
            fprintf(log_file, "Could not allocate enough memory within buffer size limit.\n");
            pthread_mutex_unlock(&log_mutex);
        }
        return -1;
    }

    // Successfully created 'count' structures
    return count;
}

int main() {
    FILE *log = fopen("debug.log", "w");
    if (!log) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t max_structures = 1000;
    size_t buffer_size_limit = 1024 * 1024; // 1MB
    unsigned char enable_logging = 1;

    int created_structures_count = allocate_nfa_crc_pdu_array(&array, max_structures, buffer_size_limit, log, enable_logging);

    if (created_structures_count == -1) {
        fprintf(stderr, "Failed to allocate and initialize structures.\n");
    } else {
        printf("Successfully created %d structures.\n", created_structures_count);
    }

    // Clean up
    free(array);
    fclose(log);

    return EXIT_SUCCESS;
}
