#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>
#include <stdio.h>
#include <time.h>

#define MAX_LIST_SIZE 1024

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    atomic_uint count;
    Node* head;
    pthread_mutex_t lock;
    size_t max_size;
} ThreadSafeList;

ThreadSafeList* create_list(size_t max_size) {
    ThreadSafeList* list = (ThreadSafeList*)malloc(sizeof(ThreadSafeList));
    list->count = ATOMIC_VAR_INIT(0);
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size = max_size;
    return list;
}

void destroy_list(ThreadSafeList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void append_to_list(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (atomic_load(&list->count) >= list->max_size) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = item;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    atomic_fetch_add(&list->count, 1);
    pthread_mutex_unlock(&list->lock);

    // Logging
    printf("Item appended. Current count: %u\n", atomic_load(&list->count));
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG = rand() & 0x01; // Random CRCFLAG
    return pdu;
}

void* thread_function(void* arg) {
    ThreadSafeList* list = (ThreadSafeList*)arg;
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        append_to_list(list, pdu);
    }
    return NULL;
}

void populate_list_with_threads(ThreadSafeList* list, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, list);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL));
    ThreadSafeList* list = create_list(MAX_LIST_SIZE);

    populate_list_with_threads(list, 4); // Example with 4 threads

    destroy_list(list);
    return 0;
}
