#define CHUNK_SIZE 1000

int allocate_and_initialize_pdu_array(NFAPI_CRC_INDICATION_PDU_T **pduArray) {
    if (!pduArray) return -1; // Invalid pointer argument

    *pduArray = NULL;
    int totalAllocated = 0;

    srand((unsigned int)time(NULL));

    for (int i = 0; i < MAX_STRUCTURES; i += CHUNK_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *chunk = malloc(CHUNK_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!chunk) {
            // Allocation failed, clean up previously allocated memory
            for (int j = 0; j < totalAllocated; j += CHUNK_SIZE) {
                free(*pduArray + j);
            }
            free(*pduArray);
            *pduArray = NULL;

            printf("Error: Memory allocation failed at chunk %d.\n", i / CHUNK_SIZE + 1);
            return -2; // Allocation failure
        }

        int validChunk = 1;

        for (int j = 0; j < CHUNK_SIZE && (i + j) < MAX_STRUCTURES; ++j) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = chunk + j;

            pdu->RX_UE_INFORMATION_TAG = rand() % 10000;
            pdu->RNTI = rand() % 10000;
            pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
            pdu->CRCFLAG = rand() % 2; // Randomly set to 0 or 1

            // Simulate potential validation failure
            if (pdu->RX_UE_INFORMATION_TAG < 0) {
                validChunk = 0;
                break;
            }
        }

        if (!validChunk) {
            free(chunk);
            for (int j = 0; j < totalAllocated; j += CHUNK_SIZE) {
                free(*pduArray + j);
            }
            free(*pduArray);
            *pduArray = NULL;

            printf("Error: Initialization failed at chunk %d.\n", i / CHUNK_SIZE + 1);
            return -3; // Initialization failure
        }

        if (*pduArray == NULL) {
            *pduArray = chunk;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*pduArray, (totalAllocated + CHUNK_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!temp) {
                free(chunk);
                for (int j = 0; j < totalAllocated; j += CHUNK_SIZE) {
                    free(*pduArray + j);
                }
                free(*pduArray);
                *pduArray = NULL;

                printf("Error: Memory reallocation failed at chunk %d.\n", i / CHUNK_SIZE + 1);
                return -2;
            }

            *pduArray = temp;
        }

        totalAllocated += (CHUNK_SIZE < (MAX_STRUCTURES - i) ? CHUNK_SIZE : MAX_STRUCTURES - i);

        printf("Chunk %d allocated and initialized successfully.\n", (i / CHUNK_SIZE) + 1);
    }

    printf("Total structures allocated: %d\n", totalAllocated);
    return totalAllocated; // Success
}

// Example usage
