struct Node* create_nfaapi_crc_list(size_t size, uint32_t seed) {
    if (size > 1024) {
        return NULL;
    }

    struct Node* head = NULL;
    struct Node** current = &head;

    for (size_t i = 0; i < size; ++i) {
        // Allocate memory for the new node
        struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
        if (!newNode) {
            // Free already allocated nodes in case of failure
            while (head != NULL) {
                struct Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        // Allocate memory for the data structure
        newNode->data.crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG_T*)malloc(sizeof(CRC_INDICATION_REL8_TAG_T));
        if (!newNode->data.crc_indication_rel8_tag) {
            free(newNode);
            while (*current != NULL) {
                struct Node* temp = *current;
                *current = (*current)->next;
                free(temp);
            }
            return NULL;
        }

        // Initialize the data
        initialize_crc_flag(newNode->data.crc_indication_rel8_tag, seed);

        // Link the new node into the list
        newNode->next = NULL;
        *current = newNode;
        current = &newNode->next;
    }

    return head;
}

