    const uint32_t a = 1664525;
    const uint32_t c = 1013904223;
    *seed = (a * (*seed) + c) & 0xFFFFFFFF;
    return *seed;
}

// Function to free the list
void free_nfaapi_crc_list(struct Node* head) {
    struct Node* current = head;
    while (current != NULL) {
        struct Node* next = current->next;
        if (current->data.crc_indication_rel8_tag) {
            free(current->data.crc_indication_rel8_tag);
        }
        free(current);
        current = next;
    }
}

