import time
import random

#define MAX_STRUCTS 1000 // Threshold before resizing
#define INITIAL_SIZE 10
#define ERROR_CODE_NULL_POINTER -1
#define ERROR_CODE_MEMORY_ALLOCATION_FAILED -2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG; 
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_list() {
    return NULL;
}

int validate_tags(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Assume validation logic for RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
    return (pdu.RX_UE_INFORMATION_TAG != 0 && pdu.CRCFLAG != -1);
}

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, int rnti) {
    pdu->RX_UE_INFORMATION_TAG = random.randint(1, 1000); // Replace with actual logic
    pdu->RNTI = rnti;
    pdu->CRCFLAG = (random.randint(0, 1) == 0) ? 0 : 1; // Randomly set CRCFLAG
}

Node* resize_list(Node *head, int new_size) {
    Node *new_head = create_list();
    Node *current = head;

    while (current != NULL && new_size > 0) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) return NULL;

        new_node->data = current->data;
        new_node->next = new_head;

        new_head = new_node;
        current = current->next;
        --new_size;
    }

    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return new_head;
}

int add_pdu_to_list(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_tags(pdu)) {
        return ERROR_CODE_NULL_POINTER;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        return ERROR_CODE_MEMORY_ALLOCATION_FAILED;
    }

    new_node->data = pdu;
    new_node->next = *head;
    *head = new_node;

    return 0; // Success
}

int process_crc_indications(int N) {
    int success_count = 0, failure_count = 0;
    Node* list = create_list();

    if (N <= 0) return ERROR_CODE_NULL_POINTER;

    for (int i = 1; i <= N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        initialize_pdu(&pdu, i);

        int result = add_pdu_to_list(&list, pdu);
        if (result == 0) {
            success_count++;
        } else {
            failure_count++;
            printf("Failed to allocate memory for PDU %d.\n", i);
            break;
        }

        // Resize list if it exceeds the threshold
        int count = 0;
        Node* current = list;
        while (current) {
            ++count;
            current = current->next;
        }

        if (count > MAX_STRUCTS) {
            printf("Resizing list...\n");
            list = resize_list(list, 2 * MAX_STRUCTS);
            if (!list) {
                failure_count += count; // All prior added PDUs are considered failures
                break;
            }
        }
    }

    printf("Total Valid CRC Indications: %d\n", success_count);
    printf("Total Invalid or Failed CRC Indications: %d\n", failure_count);

    // Free list
    Node* current = list;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return 0; // End of processing
}

int main() {
    int N;
    printf("Enter the number of CRC indications to process: ");
    scanf("%d", &N);

    int result = process_crc_indications(N);
    if (result != 0) {
        printf("An error occurred during processing.\n");
    }

    return result;
}
