}

// Create an initial packet list
PHY_LAYER_PACKET_T* create_packet_list(int capacity) {
    PHY_LAYER_PACKET_T *packets = (PHY_LAYER_PACKET_T *)malloc(capacity * sizeof(PHY_LAYER_PACKET_T));
    if (!packets) {
        return NULL;
    }

    for (int i = 0; i < capacity; ++i) {
        packets[i].PACKET_HEADER = NULL;
        memset(packets[i].SOURCE_MAC_ADDRESS, 0, sizeof(packets[i].SOURCE_MAC_ADDRESS));
        memset(packets[i].DESTINATION_MAC_ADDRESS, 0, sizeof(packets[i].DESTINATION_MAC_ADDRESS));
        packets[i].CHECKSUM_VALIDATION_STATUS = 0;
    }

    return packets;
}

// Add a new packet to the list with dynamic resizing if needed
int add_packet(PHY_LAYER_PACKET_T **packets, int *size, int *capacity, const PHY_LAYER_PACKET_T *new_packet) {
    // Check if we need to resize
    if (*size >= *capacity) {
        int new_capacity = (*capacity == 0) ? INITIAL_CAPACITY : (*capacity * 2);
        PHY_LAYER_PACKET_T *temp_packets = (PHY_LAYER_PACKET_T *)realloc(*packets, new_capacity * sizeof(PHY_LAYER_PACKET_T));
        if (!temp_packets) {
            return 0; // Handle reallocation failure
        }

        for (int i = *size; i < new_capacity; ++i) {
            temp_packets[i].PACKET_HEADER = NULL;
            memset(temp_packets[i].SOURCE_MAC_ADDRESS, 0, sizeof(temp_packets[i].SOURCE_MAC_ADDRESS));
            memset(temp_packets[i].DESTINATION_MAC_ADDRESS, 0, sizeof(temp_packets[i].DESTINATION_MAC_ADDRESS));
            temp_packets[i].CHECKSUM_VALIDATION_STATUS = 0;
        }

        *packets = temp_packets;
        *capacity = new_capacity;
    }

    // Copy data into the list
    memcpy(&(*packets)[*size], new_packet, sizeof(PHY_LAYER_PACKET_T));
    (*size)++;

    return 1;
}

// Log error messages (mock function)
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
