```c
#include <stdio.h>
#include <stdlib.h>
import stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define MAX_MESSAGES 10000

typedef struct {
    int id;
    char data[256]; // Example field, adjust according to actual structure
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *logfile;
} MessageManager;

// Initialize the message manager
void initMessageManager(MessageManager *manager) {
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->messages = malloc(manager->capacity * sizeof(NFAPI_MESSAGE_T));
    if (!manager->messages) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);
    manager->logfile = fopen("message_log.txt", "a+");
    if (!manager->logfile) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

// Resize the internal array
void resize(MessageManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_MESSAGE_T *new_messages = realloc(manager->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
    if (!new_messages) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    manager->messages = new_messages;
    manager->capacity = new_capacity;
}

// Insert a message
void insertMessage(MessageManager *manager, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize(manager);
    }
    manager->messages[manager->count++] = message;

    // Periodically flush to log file
    if (manager->count % 100 == 0 || manager->count == MAX_MESSAGES) {
        for (size_t i = 0; i < manager->count; ++i) {
            fprintf(manager->logfile, "ID: %d, Data: %s\n", manager->messages[i].id, manager->messages[i].data);
        }
        fflush(manager->logfile);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Serialize messages to disk
void serializeMessages(MessageManager *manager) {
    FILE *file = fopen("messages.bin", "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }
    fwrite(manager->messages, sizeof(NFAPI_MESSAGE_T), manager->count, file);
    fclose(file);
}

// Deserialize messages from disk
void deserializeMessages(MessageManager *manager) {
    FILE *file = fopen("messages.bin", "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }
    size_t count = fread(manager->messages, sizeof(NFAPI_MESSAGE_T), manager->capacity, file);
    manager->count = count;
    fclose(file);
}

// Clean up resources
void cleanupMessageManager(MessageManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->messages);
    if (manager->logfile) {
        fclose(manager->logfile);
    }
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Dynamic Resizing**: Doubles the capacity when needed to minimize fragmentation and allocation overhead.
- **Periodic Flushing**: Writes unsent messages to a log file every 100 inserts or at maximum capacity.
- **Serialization/Deserialization**: Saves and loads message data from disk for offline access.
- **Error Handling**: Includes basic error handling for memory and file operations.

This implementation provides a foundation for managing messages with thread safety, efficient resizing, and persistence. Adjust the structure fields and logic as needed to fit your specific use case.']

