"CREATE TABLE IF NOT EXISTS traffic_events (" \
"id INTEGER PRIMARY KEY AUTOINCREMENT," \
"timestamp INTEGER NOT NULL," \
"cell_identity INTEGER NOT NULL," \
"signal_strength REAL NOT NULL," \
"ue_id INTEGER NOT NULL," \
"transmission_power INTEGER NOT NULL);";

// Initialize the TrafficManager
void initializeTrafficManager(TrafficManager *manager, const char *db_path) {
    pthread_mutex_init(&manager->db_lock, NULL);
    manager->event_list.count = 0;
    manager->event_list.capacity = 10000; // Initial capacity
    manager->event_list.ues = malloc(manager->event_list.capacity * sizeof(UE_Information));

    if (sqlite3_open(db_path, &manager->db) != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(manager->db));
        exit(EXIT_FAILURE);
    }
    char* errMsg = NULL;
    if (sqlite3_exec(manager->db, createSchemaSQL, 0, 0, &errMsg) != SQLITE_OK) {
        fprintf(stderr, "Failed to execute schema SQL: %s\n", errMsg);
        sqlite3_free(errMsg);
        exit(EXIT_FAILURE);
    }
}

// Free resources held by TrafficManager
void destroyTrafficManager(TrafficManager *manager) {
    free(manager->event_list.ues);
    pthread_mutex_destroy(&manager->db_lock);
    sqlite3_close(manager->db);
}

// Process a single event and store it in the database
int processEvent(TrafficManager *manager, UE_Information event) {
    if (manager->event_list.count >= manager->event_list.capacity) {
        size_t new_capacity = manager->event_list.capacity * 2;
        UE_Information* temp = realloc(manager->event_list.ues, new_capacity * sizeof(UE_Information));
        if (!temp) return -1; // Failed to allocate memory
        manager->event_list.ues = temp;
        manager->event_list.capacity = new_capacity;
    }
    manager->event_list.ues[manager->event_list.count++] = event;

    pthread_mutex_lock(&manager->db_lock);
    int status = storeEventInDB(manager->db, &event);
    pthread_mutex_unlock(&manager->db_lock);

    return status;
}

// Store a single event in the SQLite database
