    char sql[256];
    sprintf(sql, "INSERT INTO traffic_events (timestamp, cell_identity, signal_strength, ue_id, transmission_power) VALUES (%ld, %d, %.2f, %d, %d);",
            event->timestamp, event->cell_identity, event->signal_strength, event->ue_id, event->transmission_power);
    char* errMsg = NULL;
    int rc = sqlite3_exec(db, sql, 0, 0, &errMsg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", errMsg);
        sqlite3_free(errMsg);
        return -1;
    }
    return 0;
}

// Worker thread function for processing events
void *threadFunction(void *arg) {
    TrafficManager *manager = (TrafficManager *)arg;

    // Simulate receiving events and process them
    while (1) {
        UE_Information event;
        // Assuming some mechanism to populate 'event' data, e.g., from a network socket or file

        if (processEvent(manager, event) != 0) {
            fprintf(stderr, "Failed to process an event\n");
        }

        usleep(10000000 / MAX_EVENTS_PER_SECOND); // Sleep for approximately the time of 1/100000 second
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    TrafficManager manager;

    initializeTrafficManager(&manager, "traffic_events.db");

    pthread_t threads[MAX_EVENTS_PER_SECOND];

    // Create a thread pool to handle events concurrently
    for (int i = 0; i < MAX_EVENTS_PER_SECOND; ++i) {
        if (pthread_create(&threads[i], NULL, threadFunction, &manager) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }

    // Join threads before exiting
    for (int i = 0; i < MAX_EVENTS_PER_SECOND; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroyTrafficManager(&manager);

    return 0;
}
```

