```c
#include <stdio.h>
#include <stdlib.h>
import pthread.h  // For threading

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned long CRC_INDICATION_REL8_TAG;  // Assuming this is a numeric tag for simplicity
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread safety
} NodeList;

// Function prototypes
void initializeList(NodeList *list);
NFAPI_CRC_INDICATION_PDU_T createRandomEntry();
Node* findNode(NodeList *list, int RX_UE_INFORMATION_TAG, int RNTI);
int updateEntry(NodeList *list, int methodType, NFAPI_CRC_INDICATION_PDU_T entry);
int deleteEntry(NodeList *list, int methodType, int RX_UE_INFORMATION_TAG, int RNTI);

void initializeList(NodeList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);  // Initialize the mutex
}

NFAPI_CRC_INDICATION_PDU_T createRandomEntry() {
    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.RX_UE_INFORMATION_TAG = rand();  // Unique tag generation
    entry.RNTI = rand();
    entry.CRC_INDICATION_REL8_TAG = rand();
    entry.CRCFLAG = rand() % 2;  // Random boolean value
    return entry;
}

Node* findNode(NodeList *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);  // Lock the mutex for thread safety
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            current->data.RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int updateEntry(NodeList *list, int methodType, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (methodType != HTTP_PUT_METHOD_CODE) {  // Assume you have a defined constant for PUT
        return -1;  // Invalid method type
    }

    pthread_mutex_lock(&list->lock);
    Node* node = findNode(list, entry.RX_UE_INFORMATION_TAG, entry.RNTI);

    if (node == NULL) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return -1;  // Memory allocation failed
        }
        newNode->data = entry;
        newNode->next = list->head;
        list->head = newNode;
    } else {
        node->data = entry;  // Update existing data
    }

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

int deleteEntry(NodeList *list, int methodType, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (methodType != HTTP_DELETE_METHOD_CODE) {  // Assume you have a defined constant for DELETE
        return -1;  // Invalid method type
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            current->data.RNTI == RNTI) {
            if (prev == NULL) {  // Head of the list
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;  // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;  // Node not found
}

void cleanupList(NodeList *list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);  // Destroy the mutex
}

// You can add logging and error handling as required.
