pthread_mutex_t crc_count_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned long total_crc_indications = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_crf_array(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t chunks = (n + CHUNK_SIZE - 1) / CHUNK_SIZE; // Calculate number of required chunks
    for (size_t i = 0; i < chunks; ++i) {
        size_t current_chunk_size = (i == chunks - 1) ? (n % CHUNK_SIZE) : CHUNK_SIZE;
        if (current_chunk_size == 0) continue;

        NFAPI_CRC_INDICATION_PDU_T *chunk = malloc(current_chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!chunk) {
            // Free previously allocated memory in case of failure
            free(array);
            return NULL;
        }
        array = realloc(array, (i + 1) * current_chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array) {
            free(chunk);  // Prevent memory leak
            return NULL;
        }

        for (size_t j = 0; j < current_chunk_size; ++j) {
            array[i * CHUNK_SIZE + j].RNTI = rand();
            snprintf(array[i * CHUNK_SIZE + j].RX_UE_INFORMATION_TAG, sizeof(array[i * CHUNK_SIZE + j].RX_UE_INFORMATION_TAG), "TAG_%zu", i * CHUNK_SIZE + j);
            array[i * CHUNK_SIZE + j].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }
    }

    return array;
}

void process_crc_indications(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T* crc_array = allocate_crf_array(n);
    if (!crc_array) {
        fprintf(stderr, "Failed to allocate memory for CRC indications.\n");
        return;
    }

    pthread_mutex_lock(&crc_count_lock);
    total_crc_indications += n;
    pthread_mutex_unlock(&crc_count_lock);

    // Process the array (e.g., send data, etc.)

    free(crc_array);  // Free allocated memory after processing
}

void rename_files(FileMetadata *files, size_t file_count) {
    if (!files) return;

    time_t current_time = time(NULL);
    srand((unsigned int)current_time);

    for (size_t i = 0; i < file_count; ++i) {
        char new_name[MAX_FILENAME_LENGTH + 1];
        snprintf(new_name, sizeof(new_name), "%zu_%zd_%ld_", rand(), files[i].size, (long)time(NULL));

        // Sanitize the name
        for (char *p = new_name; *p && strlen(p) < MAX_FILENAME_LENGTH - 4; ++p) {
            if (*p == ' ' || ispunct(*p))
                *p = '_';
        }

        int ext_index = rand() % FILE_EXTENSIONS_COUNT;
        snprintf(new_name + strlen(new_name), sizeof(new_name) - strlen(new_name),
                 ".%s", EXTENSIONS[ext_index]);

        // Truncate if necessary
        if (strlen(new_name) > MAX_FILENAME_LENGTH)
            new_name[MAX_FILENAME_LENGTH] = '\0';

        strncpy(files[i].name, new_name, sizeof(files[i].name));
    }
}

const char* append_slash_if_possible(const char *input_str, size_t limit) {
