["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2
#define MAX_IP_LENGTH 15

typedef struct {
    int CONNECTION_ID;
    char REMOTE_IP[MAX_IP_LENGTH + 1];
    int LOCAL_PORT;
    long BYTES_SENT;
    long BYTES_RECEIVED;
    time_t LAST_ACTIVITY_TIMESTAMP;
} TCP_CONNECTION_STATS;

typedef struct {
    TCP_CONNECTION_STATS *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    long total_bytes_sent;
    long total_bytes_received;
} ConnectionStatsManager;

void sanitize_ip(char *ip) {
    for (size_t i = 0; ip[i] != '\0' && i < MAX_IP_LENGTH; ++i) {
        if (!isalnum(ip[i]) && ip[i] != '.') {
            ip[i] = '_';
        }
    }
    ip[MAX_IP_LENGTH] = '\0'; // Ensure truncation
}

ConnectionStatsManager* create_manager() {
    ConnectionStatsManager *manager = malloc(sizeof(ConnectionStatsManager));
    manager->connections = calloc(INITIAL_SIZE, sizeof(TCP_CONNECTION_STATS));
    manager->capacity = INITIAL_SIZE;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_bytes_sent = 0;
    manager->total_bytes_received = 0;

    return manager;
}

void destroy_manager(ConnectionStatsManager *manager) {
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_connection(ConnectionStatsManager *manager, int conn_id, const char *remote_ip, int local_port,
                   long bytes_sent, long bytes_received, time_t last_activity_timestamp) {

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * GROWTH_FACTOR;
        TCP_CONNECTION_STATS *new_connections = realloc(manager->connections, new_capacity * sizeof(TCP_CONNECTION_STATS));
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Failed to allocate memory
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    TCP_CONNECTION_STATS *connection = &manager->connections[manager->count];

    connection->CONNECTION_ID = conn_id;
    strncpy(connection->REMOTE_IP, remote_ip, MAX_IP_LENGTH);
    sanitize_ip(connection->REMOTE_IP); // Sanitize IP address
    connection->LOCAL_PORT = local_port;
    connection->BYTES_SENT = bytes_sent;
    connection->BYTES_RECEIVED = bytes_received;
    connection->LAST_ACTIVITY_TIMESTAMP = last_activity_timestamp;

    manager->count++;
    manager->total_bytes_sent += bytes_sent;
    manager->total_bytes_received += bytes_received;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void update_connection(ConnectionStatsManager *manager, int conn_id, long new_bytes_sent,
                       long new_bytes_received) {

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].CONNECTION_ID == conn_id) {
            manager->total_bytes_sent += new_bytes_sent - manager->connections[i].BYTES_SENT;
            manager->total_bytes_received += new_bytes_received - manager->connections[i].BYTES_RECEIVED;

            manager->connections[i].BYTES_SENT = new_bytes_sent;
            manager->connections[i].BYTES_RECEIVED = new_bytes_received;
            manager->connections[i].LAST_ACTIVITY_TIMESTAMP = time(NULL);

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

long get_total_bytes_sent(ConnectionStatsManager *manager) {
    long total;

    pthread_mutex_lock(&manager->lock);
    total = manager->total_bytes_sent;
    pthread_mutex_unlock(&manager->lock);

    return total;
}

long get_total_bytes_received(ConnectionStatsManager *manager) {
    long total;

    pthread_mutex_lock(&manager->lock);
    total = manager->total_bytes_received;
    pthread_mutex_unlock(&manager->lock);

    return total;
}
```

This implementation includes a dynamic memory allocation strategy using an initial size and growth factor to reduce reallocations. It employs mutexes for thread-safe operations, ensuring concurrent access is handled efficiently. The IP addresses are sanitized to comply with network standards, and the manager tracks total bytes sent/received across all connections, allowing efficient reporting under high concurrency conditions."]

