NFAPI_CRC_INDICATION_PDU_T* generateNfareHashes(int N) {
    if (N <= 0) return NULL; // Edge case for invalid input

    NFAPI_CRC_INDICATION_PDU_T *hashArray = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!hashArray) return NULL;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; ++i) {
        hashArray[i].RX_UE_INFORMATION_TAG = rand(); // Random tag
        hashArray[i].RNTI = rand(); // Random RNTI

        int CRCFLAG = rand() % 2; // Random boolean value for CRCFLAG
        hashArray[i].CRC_INDICATION_REL8_TAG[0] = (unsigned char)CRCFLAG;

        unsigned char dataToHash[sizeof(NFAPI_CRC_INDICATION_PDU_T) - sizeof(hashArray[i].MD5_HASH)];
        memcpy(dataToHash, &hashArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T) - sizeof(hashArray[i].MD5_HASH));

        MD5(dataToHash, sizeof(dataToHash), hashArray[i].MD5_HASH);
