} SessionManager;

int is_unique_session_id(SessionManager *manager, const char *sessionId) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].sessionId, sessionId) == 0) {
            return 0; // Not unique
        }
    }
    return 1; // Unique
}

