    strcpy(session->userPreferences, "[Simulated User Preferences]");
    session->connectionDuration = rand() % 3600 + 1; // Random duration between 1 and 3600 seconds
    session->dataUsage = rand() % 1000 + 1; // Random data usage between 1 and 1000 MB
    session->lastActiveTimestamp = time(NULL);

    snprintf(session->userProfileTag, sizeof(session->userProfileTag), "User-%lu", rand());
    session->isActive = (rand() % 2 == 0) ? 1 : 0;
    session->sessionExpirationTimer = time(NULL) + (rand() % 86400); // Random expiration in the next day
    session->expirationFlag = 0; // Initially not expired

    if (difftime(session->sessionExpirationTimer, time(NULL)) < 3600) { // If less than an hour to expire
        session->expirationFlag = 1;
    }
}

void resize_session_array(SessionManager *manager, size_t new_capacity) {
    SessionData *new_sessions = realloc(manager->sessions, new_capacity * sizeof(SessionData));
    if (new_sessions == NULL) {
        perror("Failed to allocate memory for sessions");
        exit(EXIT_FAILURE);
    }

    manager->capacity = new_capacity;
    manager->sessions = new_sessions;
}

void add_session_data(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_session_array(manager, manager->capacity ? manager->capacity * 2 : 4);
    }

    SessionData *session = &manager->sessions[manager->count];
    initialize_session_data(session);

    // Ensure session ID is unique
    while (!is_unique_session_id(manager, session->sessionId)) {
        initialize_session_data(session); // Reinitialize if not unique
    }

    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

void free_sessions(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->sessions);
    manager->sessions = NULL;
    manager->capacity = 0;
    manager->count = 0;

    pthread_mutex_unlock(&manager->lock);
}

SessionManager* create_session_manager() {
    SessionManager *manager = malloc(sizeof(SessionManager));
    if (!manager) {
        perror("Failed to allocate memory for session manager");
        exit(EXIT_FAILURE);
    }

    manager->sessions = NULL;
    manager->capacity = 0;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    free_sessions(manager);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
