        printf("User Profile Tag: %s\n", manager->sessions[i].userProfileTag);
        printf("Is Active: %d\n", manager->sessions[i].isActive);
        printf("Session Expiration Timer: %ld\n", manager->sessions[i].sessionExpirationTimer);
        printf("Expiration Flag: %d\n", manager->sessions[i].expirationFlag);
        printf("\n");
    }

    destroy_session_manager(manager);

    return 0;
}
