['```python
from concurrent.futures import ThreadPoolExecutor
import threading
import time
import hashlib
import random

class SessionManager:
    def __init__(self):
        self.lock = threading.Lock()
        self.sessions = {}
        self.executor = ThreadPoolExecutor(max_workers=10)

    def _generate_session_id(self, user_data):
        return hashlib.sha256(user_data.encode()).hexdigest()

    def create_session(self, user_data):
        session_id = self._generate_session_id(user_data)
        with self.lock:
            if session_id not in self.sessions:
                self.sessions[session_id] = {
                    "user_data": user_data,
                    "created_at": time.time(),
                    "last_updated": time.time()
                }
        return session_id

    def update_session(self, session_id, updates):
        with self.lock:
            if session_id in self.sessions:
                self.sessions[session_id].update(updates)
                self.sessions[session_id]['last_updated'] = time.time()

    def delete_session(self, session_id):
        with self.lock:
            if session_id in self.sessions:
                del self.sessions[session_id]

    def get_session(self, session_id):
        with self.lock:
            return self.sessions.get(session_id)

class DistributedSessionManager:
    def __init__(self, nodes_count=5):
        self.nodes = [SessionManager() for _ in range(nodes_count)]
        self.node_locks = [threading.Lock() for _ in range(nodes_count)]

    def _get_node(self, session_id):
        return int(hashlib.sha256(session_id.encode()).hexdigest(), 16) % len(self.nodes)

    def create_session(self, user_data):
        session_id = hashlib.sha256(user_data.encode()).hexdigest()
        node_index = self._get_node(session_id)
        with self.node_locks[node_index]:
            return self.nodes[node_index].create_session(user_data)

    def update_session(self, session_id, updates):
        node_index = self._get_node(session_id)
        with self.node_locks[node_index]:
            self.nodes[node_index].update_session(session_id, updates)

    def delete_session(self, session_id):
        node_index = self._get_node(session_id)
        with self.node_locks[node_index]:
            self.nodes[node_index].delete_session(session_id)

    def get_session(self, session_id):
        node_index = self._get_node(session_id)
        with self.node_locks[node_index]:
            return self.nodes[node_index].get_session(session_id)

# Example usage
if __name__ == "__main__":
    dsm = DistributedSessionManager(nodes_count=10)

    user_data = "user1234"
    session_id = dsm.create_session(user_data)
    print("Created Session ID:", session_id)

    updates = {"device_info": "mobile", "preferences": {"theme": "dark"}}
    dsm.update_session(session_id, updates)

    session = dsm.get_session(session_id)
    print("Session Data:", session)

    dsm.delete_session(session_id)
    print("Deleted Session ID:", session_id)
```

### Key Features

- **Horizontal Scalability**: The system is designed to scale by increasing the number of `DistributedSessionManager` nodes.

- **Consistency and Load Distribution**: Sessions are distributed across multiple nodes using a consistent hashing mechanism, ensuring even load distribution.

- **Fault Tolerance**: Each node manages its sessions independently. In production, additional replication strategies should be implemented for data resilience.

- **Resource Management**: Efficient locking mechanisms minimize contention and ensure thread safety without significant overhead.

- **Integration and Monitoring**: Integration with external systems and monitoring would require additional components (e.g., message brokers, logging frameworks) not shown here but can be added as needed.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_MEMORY_BUDGET 1024 * 1024 // 1MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
    uint32_t max_rntis;
    uint32_t max_crcflags;
} PDU_POOL;

PDU_POOL* create_pdu_pool(size_t initial_capacity, uint32_t max_rntis, uint32_t max_crcflags) {
    PDU_POOL* pool = (PDU_POOL*)malloc(sizeof(PDU_POOL));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->max_rntis = max_rntis;
    pool->max_crcflags = max_crcflags;

    size_t budget_size = INITIAL_MEMORY_BUDGET;
    if (budget_size < sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity) {
        initial_capacity = budget_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    srand(time(NULL));  // Seed for random number generation
    return pool;
}

int add_pdu(PDU_POOL* pool, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used >= pool->capacity || 
        pool->max_rntis == 0 || pool->max_crcflags == 0) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full or no more unique RNTIs/CRCFLAGS allowed
    }

    uint16_t rnti = rand() % (UINT16_MAX + 1); 
    int crcflag = rand() & 1;

    for (size_t i = 0; i < pool->used; ++i) {
        if ((pool->pool[i].RNTI == rnti && pool->pool[i].CRCFLAG == crcflag) ||
            !is_unique_rnti(pool, rnti)) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // RNTI or CRCFLAG combination already exists
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pool[pool->used++];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = rnti;
    pdu->CRCFLAG = crcflag;

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

int is_unique_rnti(PDU_POOL* pool, uint16_t rnti) {
    for (size_t i = 0; i < pool->used; ++i) {
        if (pool->pool[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void resize_pdu_pool(PDU_POOL* pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->lock);

    size_t budget_size = INITIAL_MEMORY_BUDGET;
    if (budget_size < sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity) {
        pthread_mutex_unlock(&pool->lock);
        return; // Cannot resize beyond memory budget
    }

    NFAPI_CRC_INDICATION_PDU_T* temp_pool = 
        (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);

    if (!temp_pool) {
        pthread_mutex_unlock(&pool->lock);
        return; // Resize failed due to memory constraints
    }

    pool->pool = temp_pool;
    pool->capacity = new_capacity;

    pthread_mutex_unlock(&pool->lock);
}

void export_pdu_list(const PDU_POOL* pool, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return; // Failed to open file

    for (size_t i = 0; i < pool->used; ++i) {
        fprintf(file, "%d,%u,%d\n", 
            pool->pool[i].RX_UE_INFORMATION_TAG,
            pool->pool[i].RNTI,
            pool->pool[i].CRCFLAG);
    }

    fclose(file);
}

void free_pdu_pool(PDU_POOL* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
    free(pool);
}
