#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRC_INDICATION_REL8_TAG;
        char CRCFLAG; // 'Y' or 'N'
    } CRC_Data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head[MAX_ENTRIES];
    pthread_mutex_t lock;
} DynamicArray;

unsigned int hash(unsigned int RNTI) {
    return RNTI % MAX_ENTRIES;
}

int crcflag_rand() {
    return (rand() % 2 == 0) ? 'Y' : 'N';
}

DynamicArray* create_dynamic_array() {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    pthread_mutex_init(&arr->lock, NULL);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        arr->head[i] = NULL;
    }
    return arr;
}

void destroy_dynamic_array(DynamicArray* arr) {
    Node *node, *tmp;
    for (int i = 0; i < MAX_ENTRIES; i++) {
        node = arr->head[i];
        while (node != NULL) {
            tmp = node;
            node = node->next;
            free(tmp);
        }
    }
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

void add_or_update_entry(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T entry) {
    unsigned int index = hash(entry.RNTI);
    Node *node, *prev = NULL;

    pthread_mutex_lock(&arr->lock);

    for (node = arr->head[index]; node != NULL; prev = node, node = node->next) {
        if (node->data.RNTI == entry.RNTI) {
            node->data = entry;
            pthread_mutex_unlock(&arr->lock);
            return;
        }
    }

    node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    node->data = entry;
    node->next = arr->head[index];
    arr->head[index] = node;

    pthread_mutex_unlock(&arr->lock);
}

void remove_entry(DynamicArray* arr, unsigned int RNTI) {
    unsigned int index = hash(RNTI);
    Node *node, *prev = NULL;

    pthread_mutex_lock(&arr->lock);

    for (node = arr->head[index]; node != NULL; prev = node, node = node->next) {
        if (node->data.RNTI == RNTI) {
            if (prev) {
                prev->next = node->next;
            } else {
                arr->head[index] = node->next;
            }
            free(node);
            pthread_mutex_unlock(&arr->lock);
            return;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

int validate_array(DynamicArray* arr) {
    int valid = 1;

    pthread_mutex_lock(&arr->lock);

    for (int i = 0; i < MAX_ENTRIES && valid; i++) {
        Node *node = arr->head[i];
        while (node != NULL) {
            if (node->data.CRC_Data.CRCFLAG != crcflag_rand()) {
                fprintf(stderr, "Data inconsistency found at RNTI %u\n", node->data.RNTI);
                valid = 0;
            }
            node = node->next;
        }
    }

    pthread_mutex_unlock(&arr->lock);

    return valid;
}

// Example usage of the functions
int main() {
    DynamicArray* array = create_dynamic_array();

    NFAPI_CRC_INDICATION_PDU_T entry1 = {1, 1001, {10, crcflag_rand()}};
    NFAPI_CRC_INDICATION_PDU_T entry2 = {2, 1002, {20, crcflag_rand()}};

    add_or_update_entry(array, entry1);
    add_or_update_entry(array, entry2);

    if (validate_array(array)) {
        printf("Data structure is valid.\n");
    } else {
        printf("Data structure validation failed.\n");
    }

    remove_entry(array, 1001);

    destroy_dynamic_array(array);
    return 0;
}
