typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* crc_list_create() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }

    return list;
}

void crc_list_destroy(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int crc_list_add(CRCList* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    // Check for duplicates
    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && 
            current->RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Element already exists
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU* new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = list->head;

    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void crc_list_log(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRCFLAG: %d\n",
            current->RNTI,
            current->RX_UE_INFORMATION_TAG,
            current->CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

