    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t count;
    size_t capacity;
} DynamicArray;

// Function prototypes
int add_element(DynamicArray *array, const NFAPI_CRC_INDICATION_PDU_T *new_elem);
NFAPI_CRC_INDICATION_PDU_T* get_element(const DynamicArray *array, size_t index);
void free_array(DynamicArray *array);

int is_valid_rnti(uint16_t rnti) {
    return rnti > 0 && rnti <= 503; // Example valid range
}

int find_index_by_rnti(const DynamicArray *array, uint16_t rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].RNTI == rnti) {
            return i;
        }
    }
    return -1;
}

int add_element(DynamicArray *array, const NFAPI_CRC_INDICATION_PDU_T *new_elem) {
    if (!is_valid_rnti(new_elem->RNTI)) {
        return -1; // Invalid RNTI
    }

    int index = find_index_by_rnti(array, new_elem->RNTI);
    if (index != -1) {
        return 0; // Duplicate RNTI found
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 4 : array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            return -1; // Memory allocation failed
        }
        array->elements = new_elements;
        array->capacity = new_capacity;
    }

    array->elements[array->count++] = *new_elem;
    return 1; // Element added successfully
}

NFAPI_CRC_INDICATION_PDU_T* get_element(const DynamicArray *array, size_t index) {
    if (index < array->count) {
        return &array->elements[index];
    }
    return NULL; // Index out of bounds
}

void free_array(DynamicArray *array) {
    free(array->elements);
    array->elements = NULL;
    array->count = 0;
    array->capacity = 0;
}

// Example usage with random CRCFLAG and seeded RNG for reproducibility
int main() {
    srand(42); // Seed for reproducibility

    DynamicArray array = { .elements = NULL, .count = 0, .capacity = 0 };

    NFAPI_CRC_INDICATION_PDU_T elem;
    elem.RX_UE_INFORMATION_TAG = rand() % 100; // Example tag
    elem.CRC_INDICATION_REL8_TAG = rand() % 10; // Example CRC tag

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
