int resolve_hostname(const char *hostname, struct in_addr *ip) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gethostbyname2_r(hostname, AF_INET, &hinfo, buf, sizeof(buf), &hp, &err)) {
            if (err == HOST_NOT_FOUND || err == TRY_AGAIN) {
                usleep(TIMEOUT * 1000000); // wait before retry
                retries++;
                continue;
            }
            return -1; // Other errors
        }
        break;
    }
    if (!hp) return -2; // Host not resolved after retries
    memcpy(ip, hinfo.h_addr_list[0], sizeof(struct in_addr));
    return 0;
}

