#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define a structure for PagingIndication.
typedef struct {
    time_t timestamp;
    int pagingStatus; // 0 = inactive, 1 = active
} PagingIndication;

// Define a structure for UserSession.
typedef struct UserSession {
    char *imsi;
    char *rnti;
    int bearerContextTag;
    PagingIndication *pagingIndication;
    struct UserSession *next;
} UserSession;

// Linked list and its mutex for concurrent access
UserSession *head = NULL;
pthread_mutex_t headLock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new UserSession node.
UserSession* createUserSession(const char *imsi, const char *rnti, int bearerContextTag) {
    UserSession *newSession = (UserSession*)malloc(sizeof(UserSession));
    if (!newSession) return NULL;

    // Allocate and copy IMSI
    newSession->imsi = strdup(imsi);
    if (!newSession->imsi) {
        free(newSession);
        return NULL;
    }

    // Allocate and copy RNTI
    newSession->rnti = strdup(rnti);
    if (!newSession->rnti) {
        free(newSession->imsi);
        free(newSession);
        return NULL;
    }

    newSession->bearerContextTag = bearerContextTag;

    // Initialize PagingIndication with current time and inactive status
    newSession->pagingIndication = (PagingIndication*)malloc(sizeof(PagingIndication));
    if (!newSession->pagingIndication) {
        free(newSession->imsi);
        free(newSession->rnti);
        free(newSession);
        return NULL;
    }

    newSession->pagingIndication->timestamp = time(NULL);
    newSession->pagingIndication->pagingStatus = 0;

    // Initialize the next pointer
    newSession->next = NULL;
    return newSession;
}

// Function to add a session safely in a concurrent environment.
void addUserSession(const char *imsi, const char *rnti, int bearerContextTag) {
    UserSession *newSession = createUserSession(imsi, rnti, bearerContextTag);
    if (!newSession) return;

    pthread_mutex_lock(&headLock);

    newSession->next = head;
    head = newSession;

    pthread_mutex_unlock(&headLock);
}

// Function to update paging status for a given IMSI.
void updatePagingStatus(const char *imsi, int isActive) {
    pthread_mutex_lock(&headLock);

    UserSession *current = head;
    while (current) {
        if (strcmp(current->imsi, imsi) == 0) {
            current->pagingIndication->timestamp = time(NULL);
            current->pagingIndication->pagingStatus = isActive ? 1 : 0;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&headLock);
}

// Periodic cleanup of inactive sessions.
void* sessionCleanup(void *arg) {
    while (1) {
        sleep(60); // Cleanup every minute

        pthread_mutex_lock(&headLock);

        UserSession **current = &head, *temp;

        while (*current) {
            if ((*current)->pagingIndication->pagingStatus == 0 &&
                difftime(time(NULL), (*current)->pagingIndication->timestamp) > 300) { // Inactive for more than 5 minutes
                temp = *current;
                *current = (*current)->next;

                free(temp->imsi);
                free(temp->rnti);
                free(temp->pagingIndication);
                free(temp);

            } else {
                current = &(*current)->next;
            }
        }

        pthread_mutex_unlock(&headLock);
    }

    return NULL;
}

// Function to initialize the session management and start cleanup thread.
void initSessionManagement() {
    pthread_t cleanupThread;

    // Start the periodic cleanup thread
    if (pthread_create(&cleanupThread, NULL, sessionCleanup, NULL) != 0) {
        perror("Failed to create session cleanup thread");
    }
}

// Main function for demonstration purposes.
int main() {
    initSessionManagement();

    addUserSession("123456789012345", "00112233445566", 1);
    updatePagingStatus("123456789012345", 1);

    // Simulate application running
    sleep(10); 

    return 0;
}
```

This code provides a linked list management system for `UserSession` structures with concurrent read and write capabilities, periodic cleanup of inactive sessions, and robust memory handling. The implementation uses mutexes to ensure thread safety during modifications of the linked list and includes dynamic resource allocation strategies to handle potential failures gracefully.']

