#define MAX_ELEMENTS 10000000

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void initialize_logging() {
    log_file = fopen("crc_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void finalize_logging() {
    if (log_file) {
        fclose(log_file);
    }
}

int generate_random_crcflag() {
    return rand() % 256;
}

int is_unique(NFAPI_CRC_INDICATION_PDU_T *list, int count, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    for (int i = 0; i < count; i++) {
        if ((list[i].RX_UE_INFORMATION_TAG == new_pdu.RX_UE_INFORMATION_TAG && list[i].RNTI == new_pdu.RNTI) ||
            list[i].RNTI == new_pdu.RNTI) {
            return 0;
        }
    }
    return 1;
}

void log_crcflag_distribution(unsigned char crcflag) {
    pthread_mutex_lock(&mutex);
    if (log_file) {
        fprintf(log_file, "CRCFLAG: %d\n", crcflag);
    }
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* manage_nfa_list(int n, int *status) {
    if (!n || n > MAX_ELEMENTS) {
        *status = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        *status = -2;
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; ) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000000;
        pdu.RNTI = rand() % 1000000;

        if (!is_unique(list, i, pdu)) continue;

        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();
        list[i++] = pdu;

        log_crcflag_distribution(pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    *status = 0;
    return list;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        free(list);
    }
}

int main() {
    initialize_logging();

    int status;
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = manage_nfa_list(1000000, &status);

    if (status == 0 && nfa_list) {
        // Process the list
        free_nfa_list(nfa_list);
    } else {
        fprintf(stderr, "Error managing NFA list: %d\n", status);
    }

    finalize_logging();
    return 0;
}
