typedef struct {
    int RNTI;
    int CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    // Other fields...
} RX_UE_INFORMATION_TAG;

