    RX_UE_INFORMATION_TAG ue_info_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDUS];
    size_t count;
    pthread_mutex_t lock;
} PDU_Manager;

void init_pdu_manager(PDU_Manager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_pdu(PDU_Manager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_PDUS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No space
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdus[i]->rnti == pdu->rnti) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate RNTI in list
        }
        if (i > 0 && manager->pdus[i-1]->rnti == pdu->rnti) {
            pthread_mutex_unlock(&manager->lock);
            return -3; // Consecutive PDUs with same RNTI
        }
    }

    manager->pdus[manager->count++] = pdu;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    srand((unsigned int)time(NULL));
    pdu->ue_info_tag.RX_UE_INFORMATION_TAG = rand();
    pdu->rnti = rand() % 10000; // Example range
    pdu->crc_tag.CRCFLAG = rand() & 1;
}

void cleanup_pdu_manager(PDU_Manager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdus[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}
