### Network Configuration Manager

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    char ip_address[16];
    char subnet_mask[16];
} Network_Interface;

typedef struct Node {
    Network_Interface iface;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} Network_Config_Manager;

void init_network_config_manager(Network_Config_Manager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

int is_ip_duplicate(Network_Config_Manager *manager, const char *ip_address) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current) {
        if (strcmp(current->iface.ip_address, ip_address) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return 1; // Duplicate found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_network_interface(Network_Config_Manager *manager, Network_Interface iface) {
    if (is_ip_duplicate(manager, iface.ip_address)) {
        return -1; // Duplicate IP address
    }

    Node *new_node = malloc(sizeof(Node));
    new_node->iface = iface;
    new_node->next = NULL;

    pthread_mutex_lock(&manager->lock);

    new_node->next = manager->head;
    manager->head = new_node;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void remove_network_interface(Network_Config_Manager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    Node **current = &manager->head;
    while (*current) {
        if ((*current)->iface.id == id) {
            Node *to_delete = *current;
            *current = (*current)->next;
            free(to_delete);
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_network_config_manager(Network_Config_Manager *manager) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current) {
        Node *to_delete = current;
        current = current->next;
        free(to_delete);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
```

