['Below is a C code implementation for initializing and populating a doubly-linked list with `DataPacket` structures. The function handles concurrent insertions, ensures unique packet IDs, and manages memory allocation efficiently.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MIN_BUFFER_CAPACITY 128

typedef struct DataPacket {
    int packet_id;
    char *payload;
    size_t payload_size;
    time_t timestamp;
    struct DataPacket *prev;
    struct DataPacket *next;
} DataPacket;

typedef struct {
    DataPacket *head;
    pthread_mutex_t lock;
} DoublyLinkedList;

DataPacket* create_packet(int packet_id, const char *data, size_t data_size) {
    if (data_size < MIN_BUFFER_CAPACITY)
        data_size = MIN_BUFFER_CAPACITY;

    DataPacket *packet = malloc(sizeof(DataPacket));
    if (!packet) return NULL;

    packet->packet_id = packet_id;
    packet->payload = malloc(data_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    memcpy(packet->payload, data, data_size);
    packet->payload_size = data_size;
    packet->timestamp = time(NULL);
    packet->prev = packet->next = NULL;

    return packet;
}

int insert_packet(DoublyLinkedList *list, DataPacket *packet) {
    pthread_mutex_lock(&list->lock);

    DataPacket **current = &list->head;
    while (*current) {
        if ((*current)->packet_id == packet->packet_id) {
            // Duplicate found; find a new position
            current = &(*current)->next;
            continue;
        }
        if ((*current)->timestamp > packet->timestamp)
            break;
        current = &(*current)->next;
    }

    packet->next = *current;
    packet->prev = (*current) ? (*current)->prev : NULL;

    if (packet->prev)
        packet->prev->next = packet;
    else
        list->head = packet; // Insert at head

    if (packet->next)
        packet->next->prev = packet;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

DoublyLinkedList* initialize_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }

    return list;
}

void destroy_list(DoublyLinkedList *list) {
    DataPacket *current = list->head;
    while (current) {
        DataPacket *next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    DoublyLinkedList *packet_list = initialize_list();
    if (!packet_list) {
        fprintf(stderr, "Failed to initialize list\n");
        return 1;
    }

    const char *data = "Example payload data";
    DataPacket *new_packet = create_packet(1, data, strlen(data));
    if (new_packet)
        insert_packet(packet_list, new_packet);

    // Additional packet operations...

    destroy_list(packet_list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex is used to protect the list during insertion.
- **Unique Packet IDs**: The function checks for duplicate `packet_id` and repositions if necessary without altering existing order.
- **Dynamic Allocation**: Payloads are allocated with a minimum capacity, handling memory allocation failures gracefully.']

