#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    int packetCount;
    unsigned long byteCount;
    time_t lastUpdateTimestamp;
} NetworkFlowRecord;

typedef struct {
    NetworkFlowRecord* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicNetworkFlowArray;

void initDynamicNetworkFlowArray(DynamicNetworkFlowArray* array, size_t initialCapacity) {
    array->records = (NetworkFlowRecord*)malloc(initialCapacity * sizeof(NetworkFlowRecord));
    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void resizeIfNeeded(DynamicNetworkFlowArray* array) {
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NetworkFlowRecord* newRecords = (NetworkFlowRecord*)realloc(array->records, newCapacity * sizeof(NetworkFlowRecord));
        if (newRecords != NULL) {
            array->records = newRecords;
            array->capacity = newCapacity;
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Failed to resize dynamic network flow array\n");
            exit(EXIT_FAILURE);
        }
    }
}

void addOrUpdateNetworkFlowRecord(DynamicNetworkFlowArray* array, const char* sourceIP, const char* destinationIP, int packetCount, unsigned long byteCount) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (strcmp(array->records[i].sourceIP, sourceIP) == 0 && strcmp(array->records[i].destinationIP, destinationIP) == 0) {
            array->records[i].packetCount += packetCount;
            array->records[i].byteCount += byteCount;
            array->records[i].lastUpdateTimestamp = time(NULL);
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    resizeIfNeeded(array);

    NetworkFlowRecord newRecord;
    strncpy(newRecord.sourceIP, sourceIP, sizeof(newRecord.sourceIP) - 1);
    strncpy(newRecord.destinationIP, destinationIP, sizeof(newRecord.destinationIP) - 1);
    newRecord.packetCount = packetCount;
    newRecord.byteCount = byteCount;
    newRecord.lastUpdateTimestamp = time(NULL);

    array->records[array->count++] = newRecord;

    pthread_mutex_unlock(&array->lock);
}

void freeDynamicNetworkFlowArray(DynamicNetworkFlowArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->records);
}

unsigned long getTotalBytesTransferred(const DynamicNetworkFlowArray* array) {
    unsigned long totalBytes = 0;
    for (size_t i = 0; i < array->count; ++i) {
        totalBytes += array->records[i].byteCount;
    }
    return totalBytes;
}

double getAveragePacketRate(const DynamicNetworkFlowArray* array, time_t startTime, time_t endTime) {
    double totalPackets = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i].lastUpdateTimestamp >= startTime && array->records[i].lastUpdateTimestamp <= endTime) {
            totalPackets += array->records[i].packetCount;
        }
    }
    double timeWindowInSeconds = difftime(endTime, startTime);
    return timeWindowInSeconds > 0 ? totalPackets / timeWindowInSeconds : 0.0;
}

// Example usage
int main() {
    DynamicNetworkFlowArray flowArray;
    initDynamicNetworkFlowArray(&flowArray, 10);

    addOrUpdateNetworkFlowRecord(&flowArray, "192.168.1.1", "192.168.1.2", 100, 5000);
    addOrUpdateNetworkFlowRecord(&flowArray, "192.168.1.3", "192.168.1.4", 200, 10000);

    printf("Total Bytes Transferred: %lu\n", getTotalBytesTransferred(&flowArray));

    time_t now = time(NULL);
    double avgPacketRate = getAveragePacketRate(&flowArray, now - 3600, now);
    printf("Average Packet Rate over last hour: %.2f packets/second\n", avgPacketRate);

    freeDynamicNetworkFlowArray(&flowArray);

    return 0;
}
