    pthread_cond_t cond;
    int size;
    int max_size;
    long added_count;
    long removed_count;
    time_t last_check;
} PduList;

PduList pdu_list = {NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0, MAX_LIST_SIZE, 0, 0, time(NULL)};

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Dummy validation logic
    return (pdu->RNTI != 0 && pdu->RX_UE_INFORMATION_TAG != 0);
}

void log_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu, const char* message) {
    printf("PDU Log - RNTI: %d, RX UE TAG: %d, CRC REL8 TAG: %d, CRCFLAG: %d - %s\n",
           pdu->RNTI, pdu->RX_UE_INFORMATION_TAG, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG, message);
}

void adjust_max_size() {
    // Example logic to dynamically adjust the max size
    time_t now = time(NULL);
    if (difftime(now, pdu_list.last_check) >= 1) { // Every second
        pthread_mutex_lock(&pdu_list.lock);
        if ((pdu_list.added_count - pdu_list.removed_count) > (pdu_list.max_size * 0.8)) {
            pdu_list.max_size *= 2; // Double the size if close to capacity
        } else if (pdu_list.size < (pdu_list.max_size / 4)) {
            pdu_list.max_size /= 2; // Halve the size if underutilized
        }
        pdu_list.last_check = now;
        pthread_mutex_unlock(&pdu_list.lock);
    }
}

void* process_pdu_batch(void* arg) {
    while (1) {
        PduNode* node = NULL;

        pthread_mutex_lock(&pdu_list.lock);
        adjust_max_size();

        if (pdu_list.size > 0) {
            node = pdu_list.head;
            pdu_list.head = node->next;
            --(pdu_list.size);

            if (!validate_pdu(&node->pdu)) {
                log_pdu(&node->pdu, "Invalid PDU - Excluded");
                free(node);
                ++(pdu_list.removed_count);
                pthread_cond_signal(&pdu_list.cond);
            } else {
                node->pdu.CRCFLAG = 1; // Example flag setting based on RNTI presence
                log_pdu(&node->pdu, "Valid PDU - Included");

                // Serialized downstream transmission logic here

                free(node);
                ++(pdu_list.removed_count);
            }
        } else {
            pthread_cond_wait(&pdu_list.cond, &pdu_list.lock);
        }

        pthread_mutex_unlock(&pdu_list.lock);

        usleep(1000); // Simulate processing delay
    }
    return NULL;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!validate_pdu(pdu)) {
        log_pdu(pdu, "Invalid PDU - Not Added");
        return;
    }

    pthread_mutex_lock(&pdu_list.lock);
    adjust_max_size();

    if (pdu_list.size < pdu_list.max_size) {
        PduNode* new_node = malloc(sizeof(PduNode));
        if (new_node == NULL) {
            log_pdu(pdu, "Memory allocation failed - Not Added");
            pthread_mutex_unlock(&pdu_list.lock);
            return;
        }

        new_node->pdu = *pdu;
        new_node->next = pdu_list.head;
        pdu_list.head = new_node;
        ++(pdu_list.size);

        log_pdu(pdu, "Valid PDU - Added");
        ++(pdu_list.added_count);
    } else {
        log_pdu(pdu, "List Full - Not Added");
    }

    pthread_cond_signal(&pdu_list.cond);
    pthread_mutex_unlock(&pdu_list.lock);
}

int main() {
    pthread_t threads[4];

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, process_pdu_batch, NULL) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    // Simulate adding PDUs
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {rand(), rand(), rand(), 0};
        add_pdu(&pdu);
        usleep(100); // Adjust to simulate load
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
