NFAPI_CRC_INDICATION_PDU_T* populateNfarlcIndicationList(size_t count, int disable_crc_flag_setting) {
    if (count == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *indication_list = 
        (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!indication_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        indication_list[i].timestamp = time(NULL);

        // Generate RNTI
        uint16_t rnti = rand() % 0x7FFF + 1;
        if (rnti == 0 || rnti > 0x7FFF) {
            log_failure("Invalid RNTI generated");
            continue; // Skip this iteration on failure
        }
        indication_list[i].crc_indication_rel8_tag.rnti = rnti;

        // Set CRC_FLAG based on the flag parameter
        if (!disable_crc_flag_setting) {
            indication_list[i].crc_indication_rel8_tag.crc_flag = rand() & 1;
        }

        // Log creation
        pthread_mutex_lock(&log_mutex);
        FILE *logfile = fopen("indication_log.txt", "a");
        if (logfile) {
            fprintf(logfile, "Created structure with RNTI: %04X, Timestamp: %ld\n",
                    indication_list[i].crc_indication_rel8_tag.rnti,
                    indication_list[i].timestamp);
            fclose(logfile);
        } else {
            perror("Failed to open log file");
        }
        pthread_mutex_unlock(&log_mutex);

        // Simulate other fields initialization
    }

    shuffle_array((NFAPI_CRC_INDICATION_PDU_T **) &indication_list, count);

    return indication_list;
}

void shuffle_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t n) {
    for (size_t i = n - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        NFAPI_CRC_INDICATION_PDU_T *temp = array[j];
        array[j] = array[i];
        array[i] = temp;
    }
}

void log_failure(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        perror("Failed to open error log file");
    }
}
