    crcflag: bool,
}

impl NFAPI_CRC_INDICATION_PDU_T {
    fn new(rx_ue_information_tag: u16, rnti: u32, crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG) -> Self {
