            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag,
        }
    }
}

#[derive(Parser)]
struct Cli {
    iterations: u64,
    seed: u64,
    file_path: String,
}

async fn generate_pdu(seed: u64, id: usize) -> Result<NFAPI_CRC_INDICATION_PDU_T, &'static str> {
    let mut rng = StdRng::seed_from_u64(seed + id as u64);
    let rx_ue_information_tag = rng.next_u16();
    let rnti = rng.next_u32();
    let crcflag: bool = rng.next_u8() % 2 == 0;

    Ok(NFAPI_CRC_INDICATION_PDU_T::new(rx_ue_information_tag, rnti, CRC_INDICATION_REL8_TAG { crcflag }))
}

async fn execute_with_retry<F, Fut, T>(mut f: F) -> Result<T, &'static str>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<T, &'static str>>,
{
    let mut delay = Duration::from_millis(10);
    loop {
        match f().await {
            Ok(result) => return Ok(result),
            Err(_) => {
                time::sleep(delay).await;
                delay *= 2; // Exponential backoff
                if delay > Duration::from_secs(1) {
                    break;
                }
            }
        }
    }
    Err("Operation failed after retries")
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    if cli.iterations == 0 || cli.seed == 0 {
        eprintln!("Invalid arguments: N and seed must be positive integers.");
        return Ok(());
    }

    let mut handles = vec![];

    for i in 0..cli.iterations {
        let seed_clone = cli.seed;
        let handle = task::spawn_blocking(move || {
            execute_with_retry(|| async move { generate_pdu(seed_clone, i).await }).await
        });
        handles.push(handle);
    }

    let mut results = Vec::new();
    for handle in handles {
        if let Ok(result) = handle.await {
            match result {
                Ok(pdu) => results.push(pdu),
                Err(e) => eprintln!("Error generating PDU: {}", e),
            }
        }
    }

    let file = File::create(&cli.file_path)?;
    let writer = bincode::serde_futures::Serializer::new(file);
    for pdu in &results {
        writer.serialize(pdu).await?;
    }

    Ok(())
}
