#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for a packet.
typedef struct {
    unsigned int pid;
    time_t timestamp;
    char *payload;
} NICPPacket;

// Define a node in the linked list.
typedef struct PacketNode {
    NICPPacket packet;
    struct PacketNode *next;
} PacketNode;

// Define a structure for managing packets with a mutex and head of the list.
typedef struct {
    PacketNode *head;
    pthread_mutex_t lock;
    unsigned int max_age; // Maximum age in seconds before cleanup
} PacketManager;

// Function to create a new packet manager.
PacketManager* create_packet_manager(unsigned int max_age) {
    PacketManager *manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_age = max_age;
    return manager;
}

// Function to create a new packet.
static PacketNode* create_packet_node(unsigned int pid, const char *payload) {
    PacketNode *node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!node) return NULL;

    node->packet.pid = pid;
    node->packet.timestamp = time(NULL);
    node->packet.payload = strdup(payload); // Duplicate payload
    node->next = NULL;
    return node;
}

// Function to add or update a packet.
void manage_packet(PacketManager *manager, unsigned int pid, const char *payload) {
    pthread_mutex_lock(&manager->lock);

    PacketNode **current = &manager->head;
    while (*current) {
        if ((*current)->packet.pid == pid) {
            // Update existing packet
            free((*current)->packet.payload);
            (*current)->packet.timestamp = time(NULL);
            (*current)->packet.payload = strdup(payload);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        current = &(*current)->next;
    }

    // Add new packet
    PacketNode *new_node = create_packet_node(pid, payload);
    if (new_node) {
        new_node->next = manager->head;
        manager->head = new_node;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a packet by PID.
NICPPacket* get_packet(PacketManager *manager, unsigned int pid) {
    pthread_mutex_lock(&manager->lock);

    PacketNode *current = manager->head;
    while (current) {
        if (current->packet.pid == pid) {
            NICPPacket *result = &current->packet;
            pthread_mutex_unlock(&manager->lock);
            return result; // Caller must not free the payload
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to periodically clean up unused packets.
void cleanup_packets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);

    PacketNode **current = &manager->head;
    time_t now = time(NULL);
    while (*current) {
        if (difftime(now, (*current)->packet.timestamp) > manager->max_age) {
            PacketNode *to_delete = *current;
            *current = to_delete->next;
            free(to_delete->packet.payload);
            free(to_delete);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to destroy the packet manager and free all resources.
void destroy_packet_manager(PacketManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    PacketNode *current = manager->head;
    while (current) {
        PacketNode *next = current->next;
        free(current->packet.payload);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage function.
void example_usage() {
    PacketManager *manager = create_packet_manager(60); // 1 minute age threshold

    manage_packet(manager, 1, "Hello, World!");
    NICPPacket *packet = get_packet(manager, 1);
    if (packet) printf("Packet PID: %u, Payload: %s\n", packet->pid, packet->payload);

    cleanup_packets(manager); // Clean up old packets

    destroy_packet_manager(manager);
}

int main() {
    example_usage();
    return 0;
}
```

This code provides a basic implementation of the task using a linked list to manage NICP packets. It includes thread-safe operations with mutexes, memory management for payloads, and periodic cleanup based on packet age. The design allows efficient addition and retrieval by PID while handling concurrency concerns.']

