```c
#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    uint32_t PDU_SESSION_ID;
    uint8_t RX_TX_FLAG;
    uint16_t SRB_INDEX;
    time_t timestamp;
} MAC_RX_BUFFER_T;

typedef struct Node {
    MAC_RX_BUFFER_T data;
    _Atomic(struct Node*) next;
} Node;

#define LIST_CAPACITY 100

typedef struct {
    _Atomic(Node*) head;
    _Atomic(Node*) tail;
    size_t count;
} LockFreeList;

LockFreeList* create_lock_free_list() {
    LockFreeList* list = (LockFreeList*)malloc(sizeof(LockFreeList));
    if (!list) return NULL;

    Node* dummy_head = (Node*)calloc(1, sizeof(Node));
    if (!dummy_head) {
        free(list);
        return NULL;
    }

    atomic_store(&list->head, dummy_head);
    atomic_store(&list->tail, dummy_head);
    atomic_store(&list->count, 0);

    return list;
}

int add_to_list(LockFreeList* list, MAC_RX_BUFFER_T buffer) {
    if (!list || !buffer.PDU_SESSION_ID) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = buffer;
    atomic_init(&new_node->next, NULL);

    Node* tail;
    Node* prev_tail;

    do {
        prev_tail = atomic_load(&list->tail);
        tail = atomic_load(&prev_tail->next);

        if (tail) {  // If the list is not empty
            if (!atomic_compare_exchange_weak(&list->tail, &prev_tail, tail)) continue;
        }

        if (time(NULL) - prev_tail->data.timestamp > LIST_CAPACITY) {
            Node* node_to_remove = prev_tail;
            atomic_store(&prev_tail->next, new_node);
            atomic_store(&list->tail, new_node);

            free(node_to_remove);
        } else {
            atomic_store(&prev_tail->next, new_node);
            atomic_compare_exchange_weak(&list->tail, &prev_tail, new_node);
        }

    } while (!atomic_compare_exchange_weak(&list->head, &prev_tail, new_node));

    atomic_fetch_add(&list->count, 1);

    return 0;
}

int remove_from_list(LockFreeList* list, uint32_t PDU_SESSION_ID) {
    if (!list || !PDU_SESSION_ID) return -1;

    Node* prev = NULL;
    Node* current = atomic_load(&list->head);

    while (current && current->next) {
        prev = current;
        current = atomic_load(&current->next);

        if (current->data.PDU_SESSION_ID == PDU_SESSION_ID) {
            Node* next_node = atomic_load(&current->next);

            if (!atomic_compare_exchange_weak(&prev->next, &current, next_node)) continue;

            free(current);
            atomic_fetch_sub(&list->count, 1);

            return 0;
        }
    }

    return -1;
}

void free_list(LockFreeList* list) {
    if (!list) return;

    Node* current = atomic_load(&list->head);
    while (current) {
        Node* next = atomic_load(&current->next);
        free(current);
        current = next;
    }

    free(list);
}

int main() {
    LockFreeList* list = create_lock_free_list();
    if (!list) {
        printf("Failed to create list.\n");
        return -1;
    }

    MAC_RX_BUFFER_T buffer = { .PDU_SESSION_ID = 123, .RX_TX_FLAG = 0x01, .SRB_INDEX = 2, .timestamp = time(NULL) };
    if (add_to_list(list, buffer) != 0) {
        printf("Failed to add item.\n");
    }

    remove_from_list(list, 123);

    free_list(list);
    return 0;
}
```

This code implements a lock-free singly linked list with basic operations: adding and removing `MAC_RX_BUFFER_T` structures. It uses atomic operations for thread safety without locks or mutexes. The list automatically evicts the oldest entry when it reaches capacity, maintaining order based on timestamps (FIFO policy). Error handling is included for memory allocation failures.']

