// Function prototypes
int insert_pdu(NFAPI_CRC_INDICATION_PDU_T** array, size_t* current_size, size_t index, NFAPI_CRC_INDICATION_PDU_T new_pdu);
void log_error(const char *message);

int main() {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
    size_t current_size = 0;

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    new_pdu.RNTI = rand(); // Random RNTI for demonstration
    new_pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

    if (insert_pdu(&pdu_array, &current_size, current_size, new_pdu) != 0) {
        log_error("Failed to insert PDU");
    }

    // Free allocated memory
    free(pdu_array);

    return 0;
}

int insert_pdu(NFAPI_CRC_INDICATION_PDU_T** array, size_t* current_size, size_t index, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    if (*current_size >= MAX_SIZE) {
        log_error("Array has reached maximum capacity");
        return -1;
    }

    if (index > *current_size) {
        log_error("Index out of bounds");
        return -1;
    }

    // Check for RNTI uniqueness
    for (size_t i = 0; i < index; ++i) {
        if ((*array)[i].RNTI == new_pdu.RNTI) {
            log_error("Duplicate RNTI encountered");
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(*array, (*current_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (temp_array == NULL) {
        log_error("Memory allocation failed");
        return -1;
    }

    // Shift elements to make space for the new PDU
    memmove(temp_array + index + 1, temp_array + index, (*current_size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Insert the new PDU
    temp_array[index] = new_pdu;

    *array = temp_array;
    ++(*current_size);

    return 0;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
