```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_MESSAGES 1000

typedef struct {
    int message_type;
    char security_context[256];
} LTE_ENB_EMM_MESSAGE_T;

typedef struct Node {
    LTE_ENB_EMM_MESSAGE_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MessageList;

void init_message_list(MessageList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int validate_message(LTE_ENB_EMM_MESSAGE_T* message) {
    // Implement validation logic
    return 1; // Assume valid for now
}

void add_message(MessageList* list, LTE_ENB_EMM_MESSAGE_T* message) {
    if (!validate_message(message)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = *message;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void remove_message(MessageList* list, int message_type) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.message_type != message_type) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(MessageList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(LTE_ENB_EMM_MESSAGE_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

int deserialize_list(MessageList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    LTE_ENB_EMM_MESSAGE_T message;
    size_t count = 0;

    while (fread(&message, sizeof(LTE_ENB_EMM_MESSAGE_T), 1, file)) {
        add_message(list, &message);
        count++;
    }

    fclose(file);

    // Handle partial writes or corrupted data by returning the number of messages read
    return count;
}

void free_list(MessageList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
```

