}

// Function to initialize and configure EMM message list
LTE_ENB_EMM_MESSAGE_T* init_emm_message_list(size_t count, int* initialized_count) {
    *initialized_count = 0;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    LTE_ENB_EMM_MESSAGE_T* emm_message_list = malloc(count * sizeof(LTE_ENB_EMM_MESSAGE_T));
    if (!emm_message_list) {
        log_error("Failed to allocate memory for EMM message list.");
        return NULL;
    }

    pthread_t threads[2];
    size_t i;

    // Thread function to initialize EMM messages
    void* init_emm_messages(void* arg) {
        LTE_ENB_EMM_MESSAGE_T* list = (LTE_ENB_EMM_MESSAGE_T*)arg;
        for (i = 0; i < count; ++i) {
            pthread_mutex_lock(&mutex);
            if (*initialized_count >= count) {
                pthread_mutex_unlock(&mutex);
                break;
            }

            LTE_ENB_EMM_MESSAGE_T* message = &list[*initialized_count];
            message->type = EMM_AUTHENTICATION_REQUEST + (i % 2); // Example logic
            snprintf(message->security_context, sizeof(message->security_context), "Context_%zu", i);

            if (validate_emm_message(message)) {
                (*initialized_count)++;
            } else {
                log_error("Invalid EMM message detected.");
            }

            pthread_mutex_unlock(&mutex);
        }
        return NULL;
    }

    // Start threads
    for (i = 0; i < 2; ++i) {
        if (pthread_create(&threads[i], NULL, init_emm_messages, emm_message_list)) {
            log_error("Failed to create thread.");
            free(emm_message_list);
            return NULL;
        }
    }

    // Join threads
    for (i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Log final status
    log_debug("EMM message list initialized.");

    return emm_message_list;
}

// Function to deallocate EMM message list
void free_emm_message_list(LTE_ENB_EMM_MESSAGE_T* emm_message_list) {
    if (emm_message_list) {
        free(emm_message_list);
        log_debug("EMM message list deallocated.");
    }
}

