        sleep(5); // Run cleanup periodically

        pthread_mutex_lock(&crc_list.mutex);

        if (crc_list.count > 0) {
            NFAPI_CRC_INDICATION_PDU_T** curr = &crc_list.head;

            while (*curr) {
                NFAPI_CRC_INDICATION_PDU_T* entry = *curr;
                if ((time(NULL) - entry->timestamp) > 60) { // Example cleanup condition
                    *curr = entry->next;
                    free(entry);
                    crc_list.count--;
                    log_creation("Cleaned up an old CRC indication structure.");
                } else {
                    curr = &entry->next;
                }
            }
        }

        pthread_mutex_unlock(&crc_list.mutex);
    }
}

int main() {
    srand(time(NULL));

    // Create worker threads for adding new structures
    pthread_t add_threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&add_threads[i], NULL, add_crc_indication, NULL);
    }

    // Start a cleanup thread
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_crc_indications, NULL);

    for (int i = 0; i < 10; ++i) {
        pthread_join(add_threads[i], NULL);
    }
    pthread_cancel(cleanup_thread); // Stop the cleanup thread gracefully

    return 0;
}
