int read_yaml_config(const char* filename, size_t* num_pdus, int* seed_value, char** output_file, int* log_level) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    yaml_parser_t parser;
    yaml_event_t event;

    if (!yaml_parser_initialize(&parser))
        goto error;

    yaml_parser_set_input_file(&parser, file);

    while (1) {
        if (!yaml_parser_parse(&parser, &event))
            goto error;

        // Parse YAML for required values
        if (event.type == YAML_SCALAR_EVENT && strcmp((char*)event.data.scalar.value, "num_pdus") == 0) {
            yaml_parser_parse(&parser, &event);
            *num_pdus = strtoul((char*)event.data.scalar.value, NULL, 10);
        } else if (event.type == YAML_SCALAR_EVENT && strcmp((char*)event.data.scalar.value, "seed_value") == 0) {
            yaml_parser_parse(&parser, &event);
            *seed_value = strtol((char*)event.data.scalar.value, NULL, 10);
        } else if (event.type == YAML_SCALAR_EVENT && strcmp((char*)event.data.scalar.value, "output_file") == 0) {
            yaml_parser_parse(&parser, &event);
            *output_file = strdup((char*)event.data.scalar.value);
        } else if (event.type == YAML_SCALAR_EVENT && strcmp((char*)event.data.scalar.value, "log_level") == 0) {
            yaml_parser_parse(&parser, &event);
            *log_level = strtol((char*)event.data.scalar.value, NULL, 10);
        }

        if (event.type == YAML_STREAM_END_EVENT)
            break;

        yaml_event_delete(&event);
    }

    yaml_event_delete(&event);
    yaml_parser_delete(&parser);
    fclose(file);

    return 0;
error:
    yaml_event_delete(&event);
    yaml_parser_delete(&parser);
    fclose(file);
    return -1;
}

