        lte_emm->records[i] = (Record){.offset = lte_emm->offsets[i].offset, .key = lte_emm->keys[i].key, .value = rand_value};
    }

    pthread_mutex_unlock(&lte_emm->lock);
    fclose(file);

    // Simulated logging and monitoring
