    return lte_emm;
}

void free_dynamic_list(LTE_ENB_EMM_MESSAGE_T *lte_emm) {
    if (lte_emm) {
        pthread_mutex_lock(&lte_emm->lock);

        free(lte_emm->records);
        free(lte_emm->keys);
        free(lte_emm->offsets);

