PduManager* create_pdu_manager() {
    PduManager *manager = (PduManager*)malloc(sizeof(PduManager));
    if (!manager) return NULL;

    memset(manager->pdus, 0, sizeof(manager->pdus));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int calculate_crc_flag(uint16_t rnti, size_t index) {
    // Example algorithm for CRC flag calculation
    return (rnti ^ index) & 0xFFFF;
}

int populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint16_t rnti, size_t index) {
    if (!pdu || rnti == 0) return -1; // Error handling

    pdu->ueInfo.rnti = rnti;
    pdu->ueInfo.crcTag.crcFlag = calculate_crc_flag(rnti, index);

    return 0;
}

int add_pdu(PduManager *manager, uint16_t rnti) {
    if (!manager || manager->count >= MAX_PDU) return -1; // Error handling

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    int result = populate_pdu(pdu, rnti, manager->count);
    if (result == 0) {
        manager->pdus[manager->count++] = pdu;
    } else {
        free(pdu); // Clean up on error
    }

    pthread_mutex_unlock(&manager->lock);
    return result;
}

void free_pdu_manager(PduManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdus[i]);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    PduManager *manager = create_pdu_manager();
    if (!manager) {
        printf("Failed to create pdu manager.\n");
        return -1;
    }

    // Example usage: Populate with RNTI values
    for (uint16_t rnti = 1; rnti <= 10000; ++rnti) {
        add_pdu(manager, rnti);
    }

    free_pdu_manager(manager);
