    ListNode *new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->packet = malloc(sizeof(DataPacket));
    if (!new_node->packet) {
        free(new_node);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    time(&new_node->packet->timestamp);
    generate_payload(new_node->packet, MAX_PAYLOAD_SIZE);
    new_node->packet->packet_id = packet_id;

    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

void expire_packets() {
    pthread_mutex_lock(&lock);

    time_t now;
    time(&now);

    ListNode *current = head;
    ListNode *prev = NULL;

    while (current) {
        if (difftime(now, current->packet->timestamp) > EXPIRATION_INTERVAL_SECONDS) {
            ListNode *to_delete = current;
            current = current->next;
            free(to_delete->packet->payload);
            free(to_delete->packet);
            free(to_delete);

            if (prev) {
                prev->next = current;
            } else {
                head = current;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&lock);
}

void *periodic_expiration(void *arg) {
    while (1) {
        expire_packets();
        sleep(EXPIRATION_INTERVAL_SECONDS);
    }
    return NULL;
}

void filter_and_process_packets(time_t start_time, time_t end_time, size_t min_size) {
    pthread_mutex_lock(&lock);

    ListNode *current = head;

    while (current) {
        if (current->packet->timestamp >= start_time &&
            current->packet->timestamp <= end_time &&
            strlen((char *)current->packet->payload) >= min_size) {
            // Process packet
            printf("Processing Packet ID: %u\n", current->packet->packet_id);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void update_payload_pattern() {
    pthread_mutex_lock(&lock);

    ListNode *current = head;

    while (current) {
        generate_payload(current->packet, MAX_PAYLOAD_SIZE); // Update with new pattern
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    pthread_t expiration_thread;

    if (pthread_create(&expiration_thread, NULL, periodic_expiration, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    // Simulate adding packets
    add_packet(1);
    sleep(2);
    add_packet(2);

    // Simulate filtering and processing
    filter_and_process_packets(time(NULL) - 100, time(NULL), 50);

    pthread_join(expiration_thread, NULL);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Thread Safety**: Uses mutex locks to ensure thread-safe operations on the linked list.
- **Periodic Expiration**: A separate thread periodically checks and removes expired packets.
- **Payload Generation**: Simulates payload generation with pseudo-random data and tags.
- **Filtering Mechanism**: Allows filtering based on timestamp range and minimum payload size.
- **Dynamic Updates**: Supports updating payloads with new patterns without full re-initialization.

### Considerations:
- **Memory Management**: Ensures no memory leaks by freeing allocated memory for expired packets.
- **Performance**: Uses a linked list for simplicity, but can be replaced with a hash map for faster lookups if needed.
- **Concurrency**: Minimizes contention by using locks only when necessary.
- **Logging and Configuration**: Basic logging is implemented; extend as needed.

This implementation provides a robust foundation for managing `DataPacket` structures in a real-time data processing application.']

