}

int insert_tdd_info(TDDInfoArray *array, NFAPI_L1_TDD_INFO_T info) {
    if (array->size == array->capacity) {
        if (resize_array(array, array->capacity * 2) != SUCCESS) {
            fprintf(stderr, "Failed to resize array\n");
            return FAILURE;
        }
    }

    // Assuming a valid check is performed on `info` before insertion
    array->data[array->size++] = info;

    return SUCCESS;
}

int remove_tdd_info(TDDInfoArray *array, unsigned int RNTI) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == RNTI) {
            memmove(&array->data[i], &array->data[i + 1], sizeof(NFAPI_L1_TDD_INFO_T) * (array->size - i - 1));
            array->size--;

            // Shrink capacity if necessary
            if (array->capacity > 4 && array->size <= array->capacity / 4) {
                resize_array(array, array->capacity / 2);
            }

            return SUCCESS;
        }
    }
    fprintf(stderr, "RNTI not found\n");
    return FAILURE;
}

NFAPI_L1_TDD_INFO_T* lookup_tdd_info(TDDInfoArray *array, unsigned int RNTI) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == RNTI) {
            return &array->data[i];
        }
    }
    fprintf(stderr, "RNTI not found\n");
    return NULL;
}

int resize_array(TDDInfoArray *array, size_t new_capacity) {
    NFAPI_L1_TDD_INFO_T *new_data = (NFAPI_L1_TDD_INFO_T *)realloc(array->data, new_capacity * sizeof(NFAPI_L1_TDD_INFO_T));
    if (!new_data) return FAILURE;

    array->capacity = new_capacity;
    memset(&new_data[array->size], 0, (array->capacity - array->size) * sizeof(NFAPI_L1_TDD_INFO_T));

    array->data = new_data;
    return SUCCESS;
}

void free_resources(TDDInfoArray *array) {
    if (array) {
        if (array->data) free(array->data);
        free(array);
    }
}
