    NFAPI_CRC_INDICATION_PDU_T data;
    int priority;  // Lower value means higher priority
    struct pqNode* next;
} PQNode;

// Priority Queue Structure
typedef struct {
    PQNode* head;
    pthread_mutex_t lock;
} PriorityQueue;

// Function Prototypes
void initializePriorityQueue(PriorityQueue* queue);
PQNode* createNode(const NFAPI_CRC_INDICATION_PDU_T data, int priority);
bool isEmpty(PriorityQueue* queue);
void enqueue(PriorityQueue* queue, const NFAPI_CRC_INDICATION_PDU_T data, int priority);
NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* queue);
void processPDU(NFAPI_CRC_INDICATION_PDU_T* pdu);
void cleanupPriorityQueue(PriorityQueue* queue);

// Initialize a Priority Queue
void initializePriorityQueue(PriorityQueue* queue) {
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
}

// Create a new Node for the Priority Queue
PQNode* createNode(const NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    PQNode* newNode = (PQNode*)malloc(sizeof(PQNode));
    if (!newNode) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->priority = priority;
    newNode->next = NULL;
    return newNode;
}

// Check if the Priority Queue is empty
bool isEmpty(PriorityQueue* queue) {
    return queue->head == NULL;
}

// Add a new node to the Priority Queue
void enqueue(PriorityQueue* queue, const NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    pthread_mutex_lock(&queue->lock);

    PQNode* newNode = createNode(data, priority);

    if (isEmpty(queue) || queue->head->priority > priority) {
        newNode->next = queue->head;
        queue->head = newNode;
    } else {
        PQNode* current = queue->head;
        while (current->next != NULL && current->next->priority <= priority) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&queue->lock);
}

// Remove and return the node with highest priority from the Priority Queue
NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* queue) {
    pthread_mutex_lock(&queue->lock);

    if (isEmpty(queue)) {
        perror("Priority Queue is empty");
        exit(EXIT_FAILURE);
    }

    PQNode* temp = queue->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;

    queue->head = queue->head->next;
    free(temp);

    pthread_mutex_unlock(&queue->lock);
    return data;
}

