}

// Cleanup the Priority Queue and free memory
void cleanupPriorityQueue(PriorityQueue* queue) {
    PQNode* current = queue->head;
    while (current != NULL) {
        PQNode* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->lock);
}

// Main function to test the Priority Queue implementation
