    initializePriorityQueue(&queue);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{0}, 100, {10}, true};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {{0}, 200, {20}, false};

