#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_NFAPIS 100 // Maximum number of NFAPI instances

typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    int crcflag; // Dynamically set
    time_t timestamp; // For prioritization
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* nfapi_array;
    size_t count;
    size_t capacity;
    size_t memory_quota;
    pthread_rwlock_t rwlock;
    PriorityQueue priority_queue;
    void (*extension_loader)(void); // Function pointer for extensions
} NFAPIManager;

// Priority Queue Functions
static Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

static void enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL || data.timestamp < pq->head->data.timestamp) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next != NULL && current->next->data.timestamp <= data.timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq->lock);
}

static NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL) {
        pthread_mutex_unlock(&pq->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0}; // Return empty structure
    }

    Node* temp = pq->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    pq->head = pq->head->next;

    free(temp);

    pthread_mutex_unlock(&pq->lock);
    return data;
}

// NFAPIManager Functions
int initialize_nfapi_manager(NFAPIManager* manager, size_t initial_capacity, size_t memory_quota, void (*extension_loader)(void)) {
    if (!manager) return -1;

    manager->nfapi_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->nfapi_array) return -1;

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->memory_quota = memory_quota;

    pthread_rwlock_init(&manager->rwlock, NULL);
    pthread_mutex_init(&manager->priority_queue.lock, NULL);

    manager->priority_queue.head = NULL;
    manager->extension_loader = extension_loader;

    return 0;
}

int add_nfapi_crc(NFAPIManager* manager, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!manager || manager->count >= manager->capacity) return -1;

    pthread_rwlock_wrlock(&manager->rwlock);

    if ((manager->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T) > manager->memory_quota) {
        pthread_rwlock_unlock(&manager->rwlock);
        return -2; // Memory quota exceeded
    }

    data.timestamp = time(NULL); // Assign current timestamp
    enqueue(&manager->priority_queue, data);

    manager->nfapi_array[manager->count++] = data;

    if (data.rnti == 0) { // Example validation check
        pthread_rwlock_unlock(&manager->rwlock);
        return -3; // Validation error
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T process_next_crc(NFAPIManager* manager) {
    NFAPI_CRC_INDICATION_PDU_T data = dequeue(&manager->priority_queue);
    if (data.rx_ue_information_tag == 0 && data.rnti == 0) return (NFAPI_CRC_INDICATION_PDU_T){0}; // Empty structure

    pthread_rwlock_rdlock(&manager->rwlock);
    printf("Processing CRC: RX UE Information Tag = %u, RNTI = %u\n", data.rx_ue_information_tag, data.rnti);
    pthread_rwlock_unlock(&manager->rwlock);

    return data;
}

void cleanup_nfapi_manager(NFAPIManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(create_node(manager->nfapi_array[i])); // Free each node in the queue
    }

    pthread_rwlock_destroy(&manager->rwlock);
    pthread_mutex_destroy(&manager->priority_queue.lock);

    free(manager->nfapi_array);
}

void extension_loader_example(void) {
    printf("Extension loader executed.\n");
}

// Example usage
int main() {
    NFAPIManager manager;
    initialize_nfapi_manager(&manager, 10, 1024 * 1024, extension_loader_example); // Initialize with capacity and memory quota

    NFAPI_CRC_INDICATION_PDU_T example_data = {1, 2, 3, 0}; // Example data
    add_nfapi_crc(&manager, example_data);

    while (process_next_crc(&manager).rx_ue_information_tag != 0) {}

    cleanup_nfapi_manager(&manager);
    return 0;
}
