#include <stdlib.h>
import time

typedef struct {
    int TX_POWER_LEVEL_TAG;
    float SINR_MEASUREMENT_TAG;
    double RB利用率;
} PHY_STATS_PDU_T;

typedef struct Node {
    PHY_STATS_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(PHY_STATS_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

Node* append_node(Node* head, PHY_STATS_PDU_T pdu) {
    if (!head) return create_node(pdu);

    Node* current = head;
    while (current->next != NULL)
        current = current->next;

    Node* new_node = create_node(pdu);
    current->next = new_node;
    return head;
}

Node* initialize_dynamic_array(int initial_size, PHY_STATS_PDU_T (*data_source)(int)) {
    Node* head = NULL;
    for (int i = 0; i < initial_size; ++i) {
        PHY_STATS_PDU_T pdu = data_source(i);
        if (pdu.TX_POWER_LEVEL_TAG == -1 || pdu.SINR_MEASUREMENT_TAG == -1.0f || pdu.RB利用率 == -1.0) {
            // Handle potential failure in data acquisition
            fprintf(stderr, "Data acquisition failed for index %d\n", i);
            continue;
        }
        head = append_node(head, pdu);
    }
    return head;
}

// Simulated external data source function
PHY_STATS_PDU_T simulate_data_source(int index) {
    // Example logic to simulate real-time measurements
    PHY_STATS_PDU_T pdu;
    if (index % 10 == 0) { // Simulate occasional failure
        pdu.TX_POWER_LEVEL_TAG = -1; 
        pdu.SINR_MEASUREMENT_TAG = -1.0f;
        pdu.RB利用率 = -1.0;
    } else {
        pdu.TX_POWER_LEVEL_TAG = index * 2;
        pdu.SINR_MEASUREMENT_TAG = index * 0.5 + (rand() % 10) / 10.0f;
        pdu.RB利用率 = (index * 3.14 + time.time()) / 100.0;
    }
    return pdu;
}

int main() {
    int initial_size = 20; // Example size
    Node* dynamic_array = initialize_dynamic_array(initial_size, simulate_data_source);

    // Usage example
    Node* current = dynamic_array;
    while (current) {
        printf("TX: %d, SINR: %.2f, RB利用率: %.2lf\n", 
               current->data.TX_POWER_LEVEL_TAG, 
               current->data.SINR_MEASUREMENT_TAG,
               current->data.RB利用率);
        current = current->next;
    }

    // Cleanup
    free_list(&dynamic_array);

    return 0;
}
