#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int count;
} LinkedList;

int log_error(const char* message, const char* file, int line) {
    FILE* log_file = fopen("error.log", "a");
    if (log_file) {
        fprintf(log_file, "[%s] Error at %s:%d - %s\n", __TIME__, file, line, message);
        fclose(log_file);
    }
    return -1;
}

unsigned char predefined_crc_algorithm(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Dummy CRC algorithm for demonstration purposes
    unsigned char crc = (pdu->RX_UE_INFORMATION_TAG + pdu->RNTI + pdu->CRC_INDICATION_REL8_TAG) % 256;
    return crc;
}

int is_rnti_unique(LinkedList* list, int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int validate_crc_flag(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    unsigned char calculated_crc = predefined_crc_algorithm(pdu);
    return (calculated_crc == pdu->CRCFLAG);
}

LinkedList* create_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) {
        log_error("Failed to allocate memory for linked list", __FILE__, __LINE__);
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(list, pdu.RNTI)) {
        return -1; // RNTI not unique
    }

    if (!validate_crc_flag(&pdu)) {
        log_error("CRC validation failed", __FILE__, __LINE__);
        return -2; // CRC validation failed
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        log_error("Reached maximum number of entries", __FILE__, __LINE__);
        return -3; // Maximum entries reached
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_error("Failed to allocate memory for new node", __FILE__, __LINE__);
        return -4; // Memory allocation failed
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int main() {
    LinkedList* list = create_list();
    if (!list) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 456, .CRC_INDICATION_REL8_TAG = 789 };
    pdu.CRCFLAG = predefined_crc_algorithm(&pdu);

    int result = add_entry(list, pdu);
    if (result != 0) {
        log_error("Failed to add entry", __FILE__, __LINE__);
    }

    destroy_list(list);
    return 0;
}
