#define MAX_RNTI 16383
#define RANGE_MIN 0
#define RANGE_MAX 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    long offset;
    int key;
    struct Node* next;
} Node;

// Priority Queue for real-time data processing
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

void initializePriorityQueue(PriorityQueue* pq) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
}

void freeNode(Node* node) {
    if (node) {
        free(node);
    }
}

int popPriorityQueue(PriorityQueue* pq, long* offset, int* key) {
    pthread_mutex_lock(&pq->lock);
    if (!pq->head) {
        pthread_mutex_unlock(&pq->lock);
        return 0;
    }

    Node* temp = pq->head;
    *offset = temp->offset;
    *key = temp->key;
    pq->head = temp->next;

    freeNode(temp);
    pthread_mutex_unlock(&pq->lock);
    return 1;
}

void pushPriorityQueue(PriorityQueue* pq, long offset, int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    newNode->offset = offset;
    newNode->key = key;
    newNode->next = NULL;

    pthread_mutex_lock(&pq->lock);

    if (!pq->head || pq->head->key > key) {
        newNode->next = pq->head;
        pq->head = newNode;
    } else {
        Node* current = pq->head;
        while (current->next && current->next->key <= key) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&pq->lock);
}

void freePriorityQueue(PriorityQueue* pq) {
    Node* current = pq->head;
    while (current) {
        Node* next = current->next;
        freeNode(current);
        current = next;
    }
    pthread_mutex_destroy(&pq->lock);
}

int isValidRNTI(int rnti) {
    return rnti >= 1 && rnti <= MAX_RNTI;
}

void logInvalidRNTI(int rnti) {
    fprintf(stderr, "Invalid RNTI: %d\n", rnti);
}

