void initializeAndProcessCRCIndications(NFAPI_CRC_INDICATION_PDU_T* indications, size_t numIndications,
                                        long* offsets, int* keys, size_t numOffsetsKeys,
                                        const char* inputFilePath, const char* outputFilePath) {
    if (!indications || !offsets || !keys || numIndications == 0 || numOffsetsKeys == 0) return;

    srand(time(NULL));

    PriorityQueue pq;
    initializePriorityQueue(&pq);

    for (size_t i = 0; i < numIndications; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example value
        indications[i].RNTI = rand() % (MAX_RNTI + 1);
        if (!isValidRNTI(indications[i].RNTI)) {
            logInvalidRNTI(indications[i].RNTI);
            continue;
        }
        indications[i].CRCFLAG = indications[i].RNTI % 2;

        long offset = rand() % (RANGE_MAX - RANGE_MIN + 1) + RANGE_MIN;
        int key = rand() % (RANGE_MAX - RANGE_MIN + 1) + RANGE_MIN;
        pushPriorityQueue(&pq, offset, key);
    }

    for (size_t i = 0; i < numOffsetsKeys; ++i) {
        if (popPriorityQueue(&pq, &offsets[i], &keys[i])) {
            printf("Offset: %ld, Key: %d\n", offsets[i], keys[i]);
        }
    }

    freePriorityQueue(&pq);

    convertFileToTargetFormat(inputFilePath, outputFilePath);
}
