    pq->head = NULL;
    return pq;
}

void push(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T pdu, float signal_strength) {
    Node* start = newNode(pdu, signal_strength);

    // Special case: the head of list has lesser priority
    if (pq->head == NULL || start->priority > pq->head->priority) {
        start->next = pq->head;
        pq->head = start;
    } else {
        Node* current = pq->head;

        while (current->next != NULL && current->next->priority >= start->priority)
            current = current->next;

        // Insert the new node at the correct position
        start->next = current->next;
        current->next = start;
    }
}

// Function to process events from the priority queue
void processPriorityQueue(PriorityQueue* pq) {
    Node* temp;

    while (pq->head != NULL) {
        temp = pq->head;
        pq->head = pq->head->next;

        // Process the node's data
        handleEvent(temp->data);

        free(temp);
    }
}

