    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

// Function to initialize the dynamic list
void init_dynamic_list(DynamicList* list, size_t initial_capacity) {
    list->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to safely add an element to the dynamic list
int add_to_list(DynamicList* list, const NFAPI_CRC_INDICATION_PDU_T* new_element) {
    if (list->size >= MAX_LIST_SIZE) return -1; // Exceeded max capacity

    pthread_mutex_lock(&list->lock);

    // Check for consecutive RNTI duplication
    if (list->size > 0 && list->array[list->size - 1].RNTI == new_element->RNTI) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Consecutive RNTI duplication detected
    }

    if (list->size >= list->capacity) { // Resize array if necessary
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Memory allocation failure
        }
        list->array = temp_array;
        list->capacity = new_capacity;
    }

    // Assign a random CRCFLAG and add the element to the list
    new_element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256; // Random CRCFLAG between 0 and 255

    list->array[list->size++] = *new_element;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the dynamic list
void free_dynamic_list(DynamicList* list) {
    pthread_mutex_destroy(&list->lock);
    free(list->array);
}
