// Thread-safe array manager structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** array;
    size_t size;
    pthread_mutex_t lock;
} CRCManager;

CRCManager* createCRCManager(size_t initialSize) {
    CRCManager* manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->size = initialSize;
    for (size_t i = 0; i < initialSize; ++i) {
        manager->array[i] = NULL;
    }

    return manager;
}

void destroyCRCManager(CRCManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->array[i]);
    }
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

bool addCRCIndication(CRCManager* manager, unsigned int rxTag, unsigned short rnti) {
    if (!isValidRNTI(rnti)) {
        logError("Invalid RNTI");
        return false;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i] && manager->array[i]->tag.RNTI == rnti) {
            logError("Duplicate RNTI found, skipping addition");
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* newEntry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newEntry) {
        logError("Memory allocation failed");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    newEntry->length = sizeof(CRC_INDICATION_REL8_TAG_T);
    newEntry->tag.RX_UE_INFORMATION_TAG = rxTag;
    newEntry->tag.RNTI = rnti;

    for (size_t i = 0; i < manager->size; ++i) {
        if (!manager->array[i]) {
            manager->array[i] = newEntry;
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    // If no space, need to resize
    size_t newSize = manager->size * 2;
    NFAPI_CRC_INDICATION_PDU_T** newArray = (NFAPI_CRC_INDICATION_PDU_T**)realloc(manager->array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!newArray) {
        free(newEntry);
        logError("Memory allocation failed during resize");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    manager->array = newArray;
    for (size_t i = manager->size; i < newSize; ++i) {
        manager->array[i] = NULL;
    }

    manager->array[manager->size] = newEntry;
    manager->size = newSize;

    pthread_mutex_unlock(&manager->lock);
    return true;
}

// Example usage
int main() {
    CRCManager* manager = createCRCManager(10);

    if (!addCRCIndication(manager, 12345, 100)) {
        logError("Failed to add CRC indication");
    }

    // Add more indications...

    destroyCRCManager(manager);
    return 0;
}
