        if (!is_rnti_valid(rnti, NULL)) {
            printf("Duplicate or invalid RNTI detected: %d\n", rnti);
        } else {
            printf("Invalid RNTI range: %d\n", rnti);
        }
        return false;
    }

    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        resize_crc_array(manager);
        if (manager->array == NULL) {
            pthread_mutex_unlock(&manager->mutex);
            return false; // Memory reallocation failed
        }
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu = {{rnti, rand() % 2}, rx_ue_info_tag};
    manager->array[manager->size++] = new_pdu;
    manager->successful_additions++;

    pthread_mutex_unlock(&manager->mutex);
    return true;
}

void free_crc_array_manager(CRCArrayManager *manager) {
    if (manager && manager->is_initialized) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager->array);
        manager->is_initialized = false;
    }
