#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <string.h>

#define MAX_ENTRIES 1000
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_MANAGER;

// Logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

NFAPI_CRC_MANAGER* create_crc_manager() {
    NFAPI_CRC_MANAGER *manager = (NFAPI_CRC_MANAGER*)malloc(sizeof(NFAPI_CRC_MANAGER));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }

    manager->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ENTRIES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->entries) {
        perror("Failed to allocate memory for entries");
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

bool validate_rnti(uint16_t rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

int add_crc_entry(NFAPI_CRC_MANAGER *manager, uint16_t rx_ue_tag, uint16_t rnti, uint8_t crc_flag) {
    if (!validate_rnti(rnti)) {
        log_message("Invalid RNTI value");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].RNTI == rnti) {
            log_message("Duplicate RNTI found, skipping entry");
            pthread_mutex_unlock(&manager->lock);
            return -2;
        }
    }

    if (manager->count >= MAX_ENTRIES) {
        log_message("Maximum entries reached, consider overflow strategy");
        pthread_mutex_unlock(&manager->lock);
        return -3;
    }

    manager->entries[manager->count].RX_UE_INFORMATION_TAG = rx_ue_tag;
    manager->entries[manager->count].RNTI = rnti;
    manager->entries[manager->count].CRCFLAG = crc_flag;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void serialize_crc_manager(const NFAPI_CRC_MANAGER *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->count, file);

    fclose(file);
}

bool deserialize_crc_manager(NFAPI_CRC_MANAGER *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return false;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    manager->entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->entries, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->entries) {
        perror("Failed to reallocate memory during deserialization");
        fclose(file);
        return false;
    }

    fread(manager->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    manager->count = count;

    pthread_mutex_lock(&manager->lock);  // Lock while accessing shared data
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    return true;
}

void destroy_crc_manager(NFAPI_CRC_MANAGER *manager) {
    if (manager) {
        free(manager->entries);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
