#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int minInt;
    int maxInt;
    float minFloat;
    float maxFloat;
} RandomValueGeneratorConfig;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Custom random value generator class
typedef struct {
    RandomValueGeneratorConfig config;
    unsigned int seed;
} RandomValueGenerator;

int initRandomValueGenerator(RandomValueGenerator *rng, int minInt, int maxInt, float minFloat, float maxFloat) {
    pthread_mutex_lock(&mutex);
    rng->config.minInt = minInt;
    rng->config.maxInt = maxInt;
    rng->config.minFloat = minFloat;
    rng->config.maxFloat = maxFloat;
    rng->seed = time(NULL);
    pthread_mutex_unlock(&mutex);
    return 0;
}

int getRandomInteger(RandomValueGenerator *rng) {
    pthread_mutex_lock(&mutex);
    rng->seed ^= rng->seed << 13;
    rng->seed ^= rng->seed >> 17;
    rng->seed ^= rng->seed << 5;
    int randomInt = (rng->config.minInt + (rand_r(&(rng->seed)) % (rng->config.maxInt - rng->config.minInt + 1)));
    pthread_mutex_unlock(&mutex);
    return randomInt;
}

float getRandomFloat(RandomValueGenerator *rng) {
    pthread_mutex_lock(&mutex);
    float scale = ((float)(rand_r(&(rng->seed))) / RAND_MAX);
    float range = (rng->config.maxFloat - rng->config.minFloat);
    float randomFloat = rng->config.minFloat + scale * range;
    pthread_mutex_unlock(&mutex);
    return randomFloat;
}

char* toString(RandomValueGenerator *rng) {
    static char str[100];
    snprintf(str, sizeof(str), "Int: [%d, %d], Float: [%f, %f]", rng->config.minInt, rng->config.maxInt, rng->config.minFloat, rng->config.maxFloat);
    return str;
}

// Function to create and populate the list
NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationList(size_t N, RandomValueGenerator *rng) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    int lastRNTI = -1;
    for (size_t i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = getRandomInteger(rng);
        do {
            list[i].RNTI = getRandomInteger(rng);
        } while (list[i].RNTI == lastRNTI); // Ensure no consecutive elements have the same RNTI
        list[i].CRC_INDICATION_REL8_TAG = (int)getRandomFloat(rng) + 1; // Ensuring it's a positive integer
        list[i].CRCFLAG = rand() % 2;
        lastRNTI = list[i].RNTI;
    }
    return list;
}

// Example usage
int main() {
    RandomValueGenerator rng;
    initRandomValueGenerator(&rng, 1, 1000, 10.0f, 20.0f);

    size_t N = 100000; // Maximum value as per requirement
    NFAPI_CRC_INDICATION_PDU_T *list = createNFAPICRCIndicationList(N, &rng);

    if (list) {
        printf("Random Value Generator Range: %s\n", toString(&rng));
        free(list);
    }

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutex locks are used to ensure thread safety during random number generation.
- **Memory Management**: Memory is dynamically allocated for the list, and freed after use.
- **Performance**: Efficient random number generation with `rand_r` ensures repeatability in multithreaded environments.
- **Non-repeating RNTI**: Ensures no two consecutive elements have the same RNTI.']

