#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>

#define MAX_ELEMENTS 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    size_t max_elements;
    void (*log_func)(const char* message);
} CRCIndicationList;

void log_message(const char* message) {
    // Placeholder for integration with existing logging framework
    printf("%s\n", message);
}

bool get_random_crcflag() {
    return rand() % 2 == 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = rand(); // Randomly set
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = get_random_crcflag();

    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) free(pdu);
}

int add_to_list(CRCIndicationList *list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    while (list->count >= list->max_elements) {
        pthread_cond_wait(&list->cond_var, &list->lock);
    }

    if (list->count > 0 && list->elements[list->count - 1].RNTI == rnti) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Consecutive RNTIs cannot be the same
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(rnti);
    if (!pdu) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    list->elements[list->count++] = *pdu;
    free_pdu(pdu);

    pthread_cond_signal(&list->cond_var);
    list->log_func("PDU added successfully");

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void initialize_list(CRCIndicationList *list, size_t max_elements, void (*log_func)(const char*)) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) exit(EXIT_FAILURE);

    list->count = 0;
    list->max_elements = max_elements;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->log_func = log_func;
}

void cleanup_list(CRCIndicationList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free_pdu(&(list->elements[i]));
    }
    free(list->elements);

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
}

int main() {
    CRCIndicationList list;
    initialize_list(&list, MAX_ELEMENTS, log_message);

    // Example usage
    add_to_list(&list, 1);
    add_to_list(&list, 2);
    add_to_list(&list, 1); // This should fail due to consecutive RNTI

    cleanup_list(&list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses mutex and condition variable to ensure thread-safe operations.
- **Logging**: Integrates with a logging function for tracking operations.
- **Error Handling**: Handles memory allocation failures and prevents adding elements with consecutive RNTIs.
- **Concurrency Management**: Waits when the list is full, signaling when space is available.
- **Dynamic Allocation**: Manages dynamic memory for PDU structures.']

