    return min + rand() % (max - min + 1);
}

// Function to check if RNTI already exists in the list
int rnti_exists(Node* head, int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return 1;
        current = current->next;
    }
    return 0;
}

// Function to manage memory usage
void log_memory_usage() {
    fprintf(stderr, "Excessive memory usage detected.\n");
}

// Function to create and populate the linked list
Node* create_and_populate_list(int num_elements) {
    srand(time(NULL));
    Node* head = NULL;
    Node** current = &head;

    while (num_elements--) {
        int attempts = 0;
        int rnti;
        do {
            if (attempts++ > 10) {
                fprintf(stderr, "Failed to insert structure with unique RNTI after 10 attempts.\n");
                continue; // Skip this iteration
            }
            rnti = rand_int(1, 10000);
        } while (rnti_exists(head, rnti));

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        new_node->data.RX_UE_INFORMATION_TAG = rand_int(1, 1000);
        new_node->data.RNTI = rnti;
        new_node->data.CRC_INDICATION_REL8_TAG = rand_int(1, 500);
        new_node->data.CRCFLAG = rand() % 2;

        *current = new_node;
        current = &new_node->next;
    }

    // Memory usage limit check
    Node* temp = head;
    size_t total_memory_used = 0;
    while (temp) {
        total_memory_used += sizeof(Node);
        if (total_memory_used > (1000000 * ((Node*)head + 1000 - head))) { // Check for 1 MB per 1000 nodes
            log_memory_usage();
        }
        temp = temp->next;
    }

    return head;
}

// Function to execute a parameterized SQL query
void execute_query(const char* username, const char* password, int supervisor_id) {
    MYSQL *conn;
    MYSQL_STMT *stmt;
    MYSQL_BIND bind[1];
    my_bool is_null[1] = {0};
    unsigned long length[1];
    int param_id;

    char query[] = "SELECT employee_name, city, address FROM employees WHERE supervisor_id = ?";

    conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", username, password, "database_name", 3306, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        exit(EXIT_FAILURE);
    }

    stmt = mysql_stmt_init(conn);
    if (!stmt) {
        fprintf(stderr, "Could not initialize statement: %s\n", mysql_error(conn));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    if (mysql_stmt_prepare(stmt, query, strlen(query))) {
        fprintf(stderr, "Statement preparation failed: %s\n", mysql_stmt_error(stmt));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    param_id = 1;
    memset(bind, 0, sizeof(bind));

    bind[0].buffer_type = MYSQL_TYPE_LONG;
    bind[0].buffer = (char *)&supervisor_id;
    bind[0].is_null = &is_null[0];
    bind[0].length = &length[0];

    if (mysql_stmt_bind_param(stmt, bind)) {
        fprintf(stderr, "Parameter binding failed: %s\n", mysql_stmt_error(stmt));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    printf("Executing query: %s\n", query);

    if (mysql_stmt_execute(stmt)) {
        fprintf(stderr, "Statement execution failed: %s\n", mysql_stmt_error(stmt));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    MYSQL_RES *result = mysql_stmt_result_metadata(stmt);
    MYSQL_BIND result_bind[3];
    char **row = malloc(3 * sizeof(char*));
    unsigned long *lengths = malloc(3 * sizeof(unsigned long));

    for (int i = 0; i < 3; ++i) {
        row[i] = malloc(255);
        lengths[i] = 0;
        memset(&result_bind[i], 0, sizeof(MYSQL_BIND));
        result_bind[i].buffer_type = MYSQL_TYPE_STRING;
        result_bind[i].buffer = (char*)row[i];
        result_bind[i].buffer_length = 255;
        result_bind[i].length = &lengths[i];
    }

    if (mysql_stmt_bind_result(stmt, result_bind)) {
        fprintf(stderr, "Result binding failed: %s\n", mysql_stmt_error(stmt));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    printf("Query Results:\n");
    while (!mysql_stmt_fetch(stmt)) {
        for (int i = 0; i < 3; ++i) {
            row[i][lengths[i]] = '\0';
        }
        printf("Employee: %s, City: %s, Address: %s\n", row[0], row[1], row[2]);
    }

    for (int i = 0; i < 3; ++i) {
        free(row[i]);
    }
    free(row);
    free(lengths);

    mysql_stmt_close(stmt);
    mysql_close(conn);
}

// Main function to demonstrate functionality
int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <username> <password> <supervisor_id>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int supervisor_id = atoi(argv[3]);

    Node* list_head = create_and_populate_list(500); // Example with 500 elements

    execute_query(argv[1], argv[2], supervisor_id);

    // Free the linked list
    while (list_head) {
        Node* temp = list_head;
        list_head = list_head->next;
        free(temp);
    }

    return EXIT_SUCCESS;
}
```

