        (*bufferArray)[i].pdu.data = (unsigned char *)malloc((*bufferArray)[i].pdu.length);

        if ((*bufferArray)[i].pdu.data == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free((*bufferArray)[j].pdu.data);  // Free previously allocated buffers
            }
            free(*bufferArray);
            pthread_mutex_unlock(&lock);
            return -1;  // Memory allocation failed for PDU data
        }

        // Validate the MAC_RX_PDU (example validation logic)
        if ((*bufferArray)[i].pdu.length > 0 && (*bufferArray)[i].pdu.data != NULL) {
            (*bufferArray)[i].valid = 1;
        }
    }

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

void free_mac_rx_buffer_array(MAC_RX_BUFFER *bufferArray, size_t numBuffers) {
