#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define INITIAL_CAPACITY 10000
#define MAX_CAPACITY 100000
#define GROWTH_FACTOR 1.5

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcTag;
    _Atomic int CRCFLAG; // Atomic to ensure thread safety
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_rwlock_init(&array->lock, NULL);
}

void resizeDynamicArray(DynamicArray *array) {
    size_t new_capacity = (size_t)(array->capacity * GROWTH_FACTOR);
    if (new_capacity > MAX_CAPACITY) {
        new_capacity = MAX_CAPACITY;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void addElement(DynamicArray *array, const NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_rwlock_wrlock(&array->lock);

    if (array->count >= array->capacity * 0.95) {
        resizeDynamicArray(array);
    }

    memcpy(&array->data[array->count], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    atomic_store_explicit(&array->data[array->count].crcTag.CRCFLAG, rand() % 2, memory_order_relaxed);

    array->count++;

    pthread_rwlock_unlock(&array->lock);
}

void removeElement(DynamicArray *array, size_t index) {
    if (index >= array->count) return;

    pthread_rwlock_wrlock(&array->lock);

    memmove(&array->data[index], &array->data[index + 1], (array->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count--;

    pthread_rwlock_unlock(&array->lock);
}

size_t getActiveCount(const DynamicArray *array) {
    size_t count;
    pthread_rwlock_rdlock(&array->lock);
    count = array->count;
    pthread_rwlock_unlock(&array->lock);
    return count;
}

void freeDynamicArray(DynamicArray *array) {
    free(array->data);
    pthread_rwlock_destroy(&array->lock);
}

// Serialization and deserialization functions
int serializeArray(const DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_rwlock_rdlock(&array->lock);
    fwrite(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->count, file);
    pthread_rwlock_unlock(&array->lock);

    fclose(file);
    return 0;
}

int deserializeArray(DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t new_count = fread(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->capacity, file);
    if (new_count > array->capacity) {
        fclose(file);
        return -2; // Capacity exceeded
    }

    pthread_rwlock_wrlock(&array->lock);
    fread(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_count, file);
    array->count = new_count;
    pthread_rwlock_unlock(&array->lock);

    fclose(file);
    return 0;
}

// Example usage
int main() {
    DynamicArray array;
    initDynamicArray(&array);

    // Add elements and perform operations...

    freeDynamicArray(&array);
    return 0;
}
```

