    RX_UE_INFORMATION_TAG rx_ue_info;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create a new node for the linked list.
NFAPI_CRC_INDICATION_PDU_T* create_node(unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->RNTI = rnti;
    // Set a random CRCFLAG value.
    new_node->rx_ue_info.crc_tag.CRCFLAG = rand() % 2;  // Randomly setting to 0 or 1
    new_node->next = NULL;

    return new_node;
}

// Function to insert a node into the linked list ensuring uniqueness of RNTI.
bool insert_unique(NFAPI_CRC_INDICATION_PDU_T** head, unsigned int rnti) {
    if (!head) return false;

    // Check for existing RNTI
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            printf("Warning: Duplicate RNTI %u encountered. Insertion skipped.\n", rnti);
            return false;  // Duplicate found, do not insert
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(rnti);
    if (!new_node) {
        printf("Error: Memory allocation failed for RNTI %u.\n", rnti);
        return false;  // Failed to allocate memory
    }

    // Insert the new node at the beginning of the list
    new_node->next = *head;
    *head = new_node;

    return true;
}

// Function to iterate over the linked list and print all elements.
void print_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %d\n", current->RNTI, current->rx_ue_info.crc_tag.CRCFLAG);
        current = current->next;
    }
}

// Function to free the linked list.
void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    srand(time(NULL));  // Seed the random number generator
    NFAPI_CRC_INDICATION_PDU_T* list_head = NULL;

    // Example of inserting nodes into the linked list.
    insert_unique(&list_head, 1001);
    insert_unique(&list_head, 1002);
    insert_unique(&list_head, 1001);  // Duplicate RNTI

    print_list(list_head);

    free_list(list_head);
    return 0;
}
```

