} Event;

// Mutex for synchronizing access to the event log
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
Event *event_log[MAX_EVENTS];
int current_event_count = 0;

typedef struct {
    int min_threshold;
    int max_threshold;
    // More configuration settings can be added here
} LogConfig;

LogConfig log_config = {100, 5000}; // Example thresholds

// Simulated external data store interface
void store_event(Event *event) {
    // Placeholder for storing event in an external data store
}

Event* lookup_event(int event_id) {
    // Placeholder for looking up an event from the external data store
    return NULL;
}

// Function to log a new event
int log_event(int event_id, char status_flag) {
    pthread_mutex_lock(&log_mutex);

    if (current_event_count >= MAX_EVENTS) {
        fprintf(stderr, "Event log is full\n");
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    Event *new_event = malloc(sizeof(Event));
    new_event->timestamp = time(NULL);
    new_event->event_id = event_id;
    new_event->status_flag = status_flag;

    // Offload to external store if above threshold
    if (current_event_count > log_config.max_threshold) {
        store_event(new_event);
    } else {
        event_log[current_event_count++] = new_event;
    }

    pthread_mutex_unlock(&log_mutex);
    return 0;
}

// Function to read an event by ID, prioritizing external data store
Event* get_event(int event_id) {
    Event *event = lookup_event(event_id);
    if (event == NULL) {
        pthread_mutex_lock(&log_mutex);
        for (int i = 0; i < current_event_count; i++) {
            if (event_log[i]->event_id == event_id) {
                // Optionally move to external store based on thresholds
                if (current_event_count > log_config.min_threshold && 
                    current_event_count <= log_config.max_threshold) {
                    store_event(event_log[i]);
                    free(event_log[i]);
                    memmove(&event_log[i], &event_log[i + 1], sizeof(Event*) * (current_event_count - i - 1));
                    current_event_count--;
                }
                event = event_log[i];
                break;
            }
        }
        pthread_mutex_unlock(&log_mutex);
    }
    return event;
}

// Function to dynamically update logging configuration
void update_logging_thresholds(int min, int max) {
    log_config.min_threshold = min;
    log_config.max_threshold = max;
}

int main() {
    // Example usage

    // Update thresholds based on load conditions
    update_logging_thresholds(200, 4000);

    // Log events (this would typically be done by multiple threads)
    for (int i = 0; i < 10000; i++) {
        log_event(i, 'U');
    }

    // Retrieve event
    Event *retrieved_event = get_event(500);
    if (retrieved_event) {
        printf("Event ID: %d, Status: %c\n", retrieved_event->event_id, retrieved_event->status_flag);
        free(retrieved_event);  // Free memory after use
    }

    return 0;
}
