        if (seenRNTIs[rnti] != 0) {
            char msg[100];
            snprintf(msg, sizeof(msg), "Duplicate RNTI found: %u", rnti);
            logError(msg);
            continue;
        }

        seenRNTIs[rnti] = 1;

        pduList[validCount].ueInfoTag = ueInfoTag;
        pduList[validCount].RNTI = rnti;
        pduList[validCount].crcIndication.CRCFLAG = crcFlag;

        validCount++;
    }

    *resultCount = validCount;
    return pduList;
}

void freeNFAPICRCIndicationPdu(NFAPI_CRC_INDICATION_PDU_T* pduList) {
