        while (pq_size(pq)) {
            pthread_mutex_lock(&queue_mutex);
            NFAPI_CRC_INDICATION_PDU_T *item = pq_dequeue(pq);
            if (!item) {
                pthread_mutex_unlock(&queue_mutex);
                break;
            }
            // Process the item
            pthread_mutex_unlock(&queue_mutex);
        }
        return NULL;
    }

    // Create worker threads
    for (int i = 0; i < 2; ++i) {
        if (pthread_create(&threads[i], NULL, process_data, NULL)) {
            fprintf(stderr, "Failed to create thread\n");
            pq_free(pq);
            free(crcArray);
            free(urgentQueue->data);
            return -1;
