#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure as per the description
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Callback function type for processing each PDU
typedef void (*PDU_PROCESS_CALLBACK)(NFAPI_CRC_INDICATION_PDU_T *pdu);

// Node structure for a linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

// List management structure
typedef struct {
    ListNode* head;
    size_t size;
    pthread_mutex_t lock; // For thread safety
    uint16_t last_rnti;   // To ensure no consecutive RNTIs are the same
} PDUList;

// Function prototypes
PDUList* initialize_list(size_t max_threshold);
void add_pdu(PDUList* list, PDU_PROCESS_CALLBACK callback, size_t max_threshold);
void free_list(PDUList* list);
static void generate_random_crcflag(bool *crc_flag);
static bool is_valid_crc(NFAPI_CRC_INDICATION_PDU_T pdu);
static uint16_t get_random_rnti(uint16_t last_rnti);

// Initialize the PDU List
PDUList* initialize_list(size_t max_threshold) {
    PDUList* list = (PDUList*)malloc(sizeof(PDUList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->last_rnti = 0;

    return list;
}

// Add a PDU to the list with constraints
void add_pdu(PDUList* list, PDU_PROCESS_CALLBACK callback, size_t max_threshold) {
    if (pthread_mutex_lock(&list->lock)) {
        perror("Mutex lock failed");
        exit(EXIT_FAILURE);
    }

    if (list->size >= max_threshold) {
        printf("Max threshold reached.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % 0xFFFF;

    // Generate a unique RNTI
    pdu.RNTI = get_random_rnti(list->last_rnti);

    generate_random_crcflag(&pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);

    if (!is_valid_crc(pdu)) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    list->last_rnti = pdu.RNTI;

    if (callback) {
        callback(&pdu);
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the dynamically allocated list
void free_list(PDUList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Generate a random CRC flag
static void generate_random_crcflag(bool *crc_flag) {
    static bool cached_flag = false; // Simple cache for demonstration
    *crc_flag = rand() % 2 == 0 ? !cached_flag : cached_flag;
    cached_flag = *crc_flag; // Update cache
}

// Validate CRC (dummy validation)
static bool is_valid_crc(NFAPI_CRC_INDICATION_PDU_T pdu) {
    return true; // Assume valid for this example
}

// Generate a random RNTI ensuring it's not the same as last
static uint16_t get_random_rnti(uint16_t last_rnti) {
    uint16_t rnti;
    do {
        rnti = rand() % 0xFFFF;
    } while (rnti == last_rnti);

    return rnti;
}

// Example callback function
void process_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Processing PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

// Unit test for demonstration
int main() {
    const size_t max_threshold = 10000;

    PDUList* list = initialize_list(max_threshold);

    // Add PDUs with a callback to process each one
    for (size_t i = 0; i < max_threshold + 10; ++i) { // Testing beyond threshold
        add_pdu(list, process_pdu, max_threshold);
    }

    free_list(list);

    return 0;
}
