// Resize the connection pool
void resize_connection_pool(ConnectionPool* pool, size_t new_capacity) {
    TCP_CONNECTION* new_connections = (TCP_CONNECTION*)realloc(pool->connections, new_capacity * sizeof(TCP_CONNECTION));
    if (!new_connections) exit(EXIT_FAILURE);
    pool->capacity = new_capacity;
    pool->connections = new_connections;
}

// Add a connection to the pool
int add_connection(ConnectionPool* pool, TCP_CONNECTION conn) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity) {
        resize_connection_pool(pool, pool->capacity * 2);
    }

    memcpy(&pool->connections[pool->size++], &conn, sizeof(TCP_CONNECTION));
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Remove a connection from the pool
int remove_connection(ConnectionPool* pool, int connection_id) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->connections[i].connection_id == connection_id) {
            memmove(&pool->connections[i], &pool->connections[i + 1], (pool->size - i - 1) * sizeof(TCP_CONNECTION));
            --pool->size;
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1;
}

// Process each connection using a callback
void process_connections(ConnectionPool* pool, ConnectionCallback callback) {
    for (size_t i = 0; i < pool->size; ++i) {
        callback(&pool->connections[i]);
    }
}

// Adjust timeouts dynamically based on network conditions
