// Assume these structures and functions are defined elsewhere
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { LOG_SUCCESS, LOG_FAILURE } LogStatus;
void log_event(const char *event, int value);
LogStatus attempt_log(const char *event, int value);

// Memory pool structure
#define POOL_SIZE 1024

typedef struct {
    size_t element_size;
    void *pool;
    pthread_mutex_t lock;
    size_t free_index;
} MemoryPool;

void init_memory_pool(MemoryPool *mp, size_t element_size) {
    mp->element_size = element_size;
    mp->pool = malloc(POOL_SIZE * element_size);
    pthread_mutex_init(&mp->lock, NULL);
    mp->free_index = 0;
}

void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_index < POOL_SIZE) {
        void *element = ((char*)mp->pool) + mp->free_index * mp->element_size;
        mp->free_index++;
        pthread_mutex_unlock(&mp->lock);
        return element;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

void reset_memory_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    mp->free_index = 0;
    pthread_mutex_unlock(&mp->lock);
}

// Global variables for logging
#define MAX_LOG_BUFFER_SIZE 10
typedef struct {
    char buffer[MAX_LOG_BUFFER_SIZE][256];
    int count;
} LogBuffer;

LogBuffer log_buffer = {{0}};
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void buffered_log(const char *event, int value) {
    pthread_mutex_lock(&log_lock);
    if (log_buffer.count < MAX_LOG_BUFFER_SIZE) {
        snprintf(log_buffer.buffer[log_buffer.count++], sizeof(log_buffer.buffer[0]), "%s: %d", event, value);
    }
    pthread_mutex_unlock(&log_lock);
}

void flush_logs() {
    pthread_mutex_lock(&log_lock);
    for (int i = 0; i < log_buffer.count; ++i) {
        while (attempt_log(log_buffer.buffer[i], 0) == LOG_FAILURE);
    }
    memset(log_buffer.buffer, 0, sizeof(log_buffer.buffer));
    log_buffer.count = 0;
    pthread_mutex_unlock(&log_lock);
}

// Main function
void create_and_process_crc_indications(size_t N) {
    if (N <= 0) return;

    MemoryPool pool;
    init_memory_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    NFAPI_CRC_INDICATION_PDU_T *indication_list[N];
    uint32_t start_time = clock();

    for (size_t i = 0; i < N; ++i) {
        void *pdu = allocate_from_pool(&pool);
        if (!pdu) break;

        indication_list[i] = pdu;
        ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->RX_UE_INFORMATION_TAG = rand();
        ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->RNTI = rand() & 0xFFFF;
        ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        buffered_log("Element processed", i + 1);
    }

    uint32_t end_time = clock();
    double duration = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    flush_logs();

    log_event("Processing complete", N);
    if (N != sizeof(indication_list) / sizeof(indication_list[0])) {
        buffered_log("Error: Allocation failed", 1);
    }

    printf("Processed %zu elements in %.2f seconds.\n", N, duration);

    reset_memory_pool(&pool);
}
