typedef struct {
    uint32_t source_ip;
    uint32_t dest_ip;
    uint16_t source_port;
    uint16_t dest_port;
    uint8_t protocol_type;
    size_t payload_length;
    uint8_t* payload_data;
    uint16_t checksum;
} NetworkPacket;

uint16_t calculate_checksum(NetworkPacket *packet) {
    // Simple checksum calculation (modify for different protocols as needed)
    uint32_t sum = packet->source_ip + packet->dest_ip +
                   packet->source_port + packet->dest_port +
                   packet->protocol_type + packet->payload_length;
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~sum;
}

void populate_packet(NetworkPacket *packet, uint32_t src_ip, uint32_t dest_ip,
                     uint16_t src_port, uint16_t dest_port, uint8_t protocol_type,
                     size_t payload_length, const uint8_t* data) {
    packet->source_ip = src_ip;
    packet->dest_ip = dest_ip;
    packet->source_port = src_port;
    packet->dest_port = dest_port;
    packet->protocol_type = protocol_type;
    packet->payload_length = payload_length;
    packet->payload_data = malloc(payload_length);
    if (packet->payload_data) {
        memcpy(packet->payload_data, data, payload_length);
