                      uint16_t dest_port, int protocol_type, const unsigned char *data, 
                      size_t data_length, Config config) {
    Packet *packet = malloc(sizeof(Packet));
    if (!packet) return NULL;

    packet->payload = malloc(data_length);
    if (!packet->payload) {
        free(packet);
        return NULL;
