#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 0x7FF // Example RNTI limit (11 bits)
#define RETRY_LIMIT 3
#define THREAD_COUNT 4

typedef struct {
    uint16_t rnti;
    int rx_ue_information_tag;
    int crc_indication_rel8_tag;
    int crcflag; // Assuming CRCFLAG is an integer for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

// Mock function to simulate external API call
int fetch_initial_ue_info(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate network latency and failure
    return rand() % 2; // Random success or failure
}

void generate_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->crcflag = rand() % 2;
}

int validate_rnti(uint16_t rnti, uint16_t* existing_rntis, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (existing_rntis[i] == rnti)
            return 0;
    }
    return 1;
}

void* generate_pdu(void* arg) {
    int n = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    uint16_t existing_rntis[n];
    memset(existing_rntis, 0, sizeof(uint16_t) * n);

    for (int i = 0; i < n; ++i) {
        int retries = 0;
        while (retries < RETRY_LIMIT) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = &pdus[i];
            uint16_t rnti;

            do {
                rnti = rand() % MAX_RNTI;
            } while (!validate_rnti(rnti, existing_rntis, i));

            pdu->rnti = rnti;
            existing_rntis[i] = rnti;
            pdu->rx_ue_information_tag = rand(); // Simulated tag
            pdu->crc_indication_rel8_tag = rand(); // Simulated tag

            if (fetch_initial_ue_info(pdu)) {
                generate_crc_flag(pdu);
                break;
            }
            retries++;
        }

        if (retries == RETRY_LIMIT) {
            fprintf(stderr, "Failed to fetch UE info for RNTI: %u\n", rnti);
            pdus[i].rnti = 0; // Indicate failure
        }
    }

    *(NFAPI_CRC_INDICATION_PDU_T**)arg = pdus;
    return NULL;
}

void create_pdus(int n) {
    pthread_t threads[THREAD_COUNT];
    int segment_size = (n + THREAD_COUNT - 1) / THREAD_COUNT;
    int* segment_sizes = malloc(THREAD_COUNT * sizeof(int));

    for (int i = 0; i < THREAD_COUNT; ++i) {
        segment_sizes[i] = (i == THREAD_COUNT - 1) ? (n - i * segment_size) : segment_size;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus[THREAD_COUNT];

    for (int i = 0; i < THREAD_COUNT; ++i) {
        pthread_create(&threads[i], NULL, generate_pdu, &segment_sizes[i]);
    }

    for (int i = 0; i < THREAD_COUNT; ++i) {
        pthread_join(threads[i], NULL);
        pdus[i] = *(NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * segment_sizes[i]);
    }

    // Free resources and handle results
    for (int i = 0; i < THREAD_COUNT; ++i) {
        free(pdus[i]);
    }
    free(segment_sizes);
}

int main() {
    srand(time(NULL));
    int n = 100; // Example size
    create_pdus(n);
    return 0;
}
