#include <time.h>

#define MAX_RNTI 65535
#define RETRY_LIMIT 3
#define BACKOFF_TIME 1000 // in milliseconds

typedef struct {
    unsigned short RNTI;
    char RX_UE_INFORMATION_TAG[32];
    char CRC_INDICATION_REL8_TAG[32];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

