    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST;

// Mock API call simulation
int fetch_initial_ue_info(NFAPI_CRC_INDICATION_PDU_T *entry) {
    // Simulate network latency and failure
    if (rand() % 10 < 2) return -1; // 20% chance of failure
    snprintf(entry->RX_UE_INFORMATION_TAG, sizeof(entry->RX_UE_INFORMATION_TAG), "UE_INFO_%d", rand());
    snprintf(entry->CRC_INDICATION_REL8_TAG, sizeof(entry->CRC_INDICATION_REL8_TAG), "CRC_TAG_%d", rand());
    entry->CRCFLAG = rand() % 2;
    return 0; // Success
}

void *populate_nfa_list(void *arg) {
    NFAPI_CRC_LIST *list = (NFAPI_CRC_LIST *)arg;
    unsigned short rnti_set[MAX_RNTI + 1] = {0};
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        int retries = 0;
        NFAPI_CRC_INDICATION_PDU_T *entry = &list->data[i];

        while (retries < RETRY_LIMIT) {
            if (fetch_initial_ue_info(entry) == 0) {
                entry->RNTI = rand() % MAX_RNTI + 1;

                // Ensure unique RNTI
                if (!rnti_set[entry->RNTI]) {
                    rnti_set[entry->RNTI] = 1;
                    break;
                }
            }
            retries++;
            usleep(BACKOFF_TIME * 1000); // Exponential backoff can be implemented here
        }

        if (retries == RETRY_LIMIT) {
            fprintf(stderr, "Failed to fetch UE info for entry %zu after %d retries.\n", i, retries);
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_LIST *generate_nfa_list(size_t n) {
    NFAPI_CRC_LIST *list = (NFAPI_CRC_LIST *)malloc(sizeof(NFAPI_CRC_LIST));
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = n;
    pthread_mutex_init(&list->mutex, NULL);

    // Create threads for parallel processing
    const size_t num_threads = 4; // Example partitioning strategy
    size_t chunk_size = (n + num_threads - 1) / num_threads;
    pthread_t threads[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        NFAPI_CRC_LIST *sublist = malloc(sizeof(NFAPI_CRC_LIST));
        sublist->data = &list->data[i * chunk_size];
        sublist->size = ((i + 1) * chunk_size < n) ? chunk_size : (n - i * chunk_size);
        pthread_create(&threads[i], NULL, populate_nfa_list, sublist);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return list;
}

void free_nfa_list(NFAPI_CRC_LIST *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
