        free(list->elements[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_unique(UE_INFO info, NFAPIDataList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->elements[i]->ue_info.RX_UE_INFORMATION_TAG == info.RX_UE_INFORMATION_TAG &&
            list->elements[i]->ue_info.RNTI == info.RNTI) {
            return 0;
        }
    }
    return 1;
}

int populate_nfapi_list(NFAPIDataList* list, int retry_limit) {
    if (!list) return -1;

    srand(time(NULL));

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        int attempt = 0;
        while (attempt <= retry_limit) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu) {
                log_error("Memory allocation failed");
                continue;
            }

            do {
                pdu->ue_info.RX_UE_INFORMATION_TAG = rand() % 1000000; // Example range
                pdu->ue_info.RNTI = rand() % 10000; // Example range
            } while (!is_unique(pdu->ue_info, list));

            pdu->CRC_INDICATION_REL8_TAG = rand(); // Random CRC tag
            pdu->CRCFLAG = rand() & 1; // Random CRC flag

            pthread_mutex_lock(&list->lock);
            if (list->count < MAX_ELEMENTS) {
                list->elements[list->count++] = pdu;
                pthread_mutex_unlock(&list->lock);
                break;
            } else {
                pthread_mutex_unlock(&list->lock);
                free(pdu);
                log_error("Exceeded maximum number of elements");
            }

            if (++attempt > retry_limit) {
                log_error("Failed to populate element after retries");
                free(pdu);
                exponential_backoff(attempt);
            }
        }
    }

    return 0;
}

void log_error(const char* message) {
    // Asynchronous logging placeholder
    printf("ERROR: %s\n", message); // Replace with non-blocking logging mechanism
}

unsigned int generate_unique_id() {
    // Simple unique ID generation logic, can be extended as needed
    static unsigned int id = 0;
    return ++id;
}

void exponential_backoff(int attempt) {
    int delay = BACKOFF_INITIAL_DELAY_MS * (1 << attempt);
    usleep(delay * 1000); // Convert ms to us for usleep
}

int main() {
    NFAPIDataList* list = create_nfa_data_list();
    if (!list) {
        log_error("Failed to initialize NFAPIDataList");
        return -1;
    }

    populate_nfapi_list(list, RETRY_LIMIT);

    destroy_nfa_data_list(list);
    return 0;
}
