#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>  // For close()

#define MAX_CONNECTIONS 10000

typedef struct {
    int socket_fd;
    char local_ip[INET_ADDRSTRLEN];
    unsigned short local_port;
    char remote_ip[INET_ADDRSTRLEN];
    unsigned short remote_port;
} TcpConnection;

typedef struct Node {
    TcpConnection connection;
    struct Node *next;
} Node;

Node* head = NULL;

int is_unique(const char* ip, unsigned short port) {
    Node* current = head;
    while (current != NULL) {
        if ((strcmp(current->connection.remote_ip, ip) == 0) &&
            (current->connection.remote_port == port)) {
            return 0; // Not unique
        }
        current = current->next;
    }
    return 1; // Unique
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    // Integrate with network analytics tool here
}

TcpConnection* create_connection(int socket_fd, const char* local_ip, unsigned short local_port,
                                 const char* remote_ip, unsigned short remote_port) {
    if (!is_unique(remote_ip, remote_port)) {
        log_error("Duplicate connection detected. Updating existing entry.");
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        log_error("Memory allocation failed for new TCP connection.");
        return NULL;
    }

    new_node->connection.socket_fd = socket_fd;
    strncpy(new_node->connection.local_ip, local_ip, INET_ADDRSTRLEN);
    new_node->connection.local_port = local_port;
    strncpy(new_node->connection.remote_ip, remote_ip, INET_ADDRSTRLEN);
    new_node->connection.remote_port = remote_port;

    // Insert at head for fast access
    new_node->next = head;
    head = new_node;

    return &(new_node->connection);
}

void remove_connection(int socket_fd) {
    Node *current = head, *prev = NULL;
    while (current != NULL && current->connection.socket_fd != socket_fd) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return; // Socket not found

    if (prev == NULL) { // Head node
        head = current->next;
    } else {
        prev->next = current->next;
    }

    close(current->connection.socket_fd);
    free(current);
}

void destroy_connections() {
    Node *current = head, *tmp;
    while (current != NULL) {
        tmp = current;
        current = current->next;
        close(tmp->connection.socket_fd);
        free(tmp);
    }
    head = NULL;
}
