        for (size_t i = 0; i < container->count; ++i) {
            free(container->elements[i]);
        }
        free(container->elements);
    }
}

int populate_container(NFAPICRCContainer *container, int max_retries) {
    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < container->count; ++i) {
        if (!is_unique(container, rand() % 100000, rand() % 50000)) { // Example tag and rnti generation
