        } else {
            NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(rand() % 100000, rand() % 50000, rand() % 10);
            if (!pdu) return -1; // Memory allocation failure

            pthread_mutex_lock(&container->mutex);
            container->elements[i] = pdu;
            pthread_mutex_unlock(&container->mutex);
        }
    }

    return 0;
}

void initialize_container(NFAPICRCContainer *container, size_t count) {
    container->count = (count > max_elements) ? max_elements : count;
    container->elements = (NFAPI_CRC_INDICATION_PDU_T **)malloc(container->count * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!container->elements) {
        log_error("Memory allocation failed for container");
        return;
    }
    memset(container->elements, 0, container->count * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    pthread_mutex_init(&container->mutex, NULL);
}

