#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>

#define MAX_PDUS 1024

typedef struct {
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int priority;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    size_t count;
} RadioNode;

// Global list of radio nodes
#define MAX_NODES 64
RadioNode radio_nodes[MAX_NODES];
size_t node_count = 0;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Utility function to generate a random boolean value
bool generate_random_crcflag() {
    return rand() % 2 == 0;
}

// Function to add a new PDU ensuring no two consecutive PDUs share the same RNTI
void add_pdu_to_node(RadioNode *node, uint16_t rnti) {
    pthread_mutex_lock(&node->lock);

    // Ensure no two consecutive PDUs have the same RNTI
    if (node->count > 0 && node->pdus[node->count - 1].RNTI == rnti) {
        pthread_mutex_unlock(&node->lock);
        return;
    }

    // Add new PDU
    node->pdus[node->count].RNTI = rnti;
    node->pdus[node->count].CRCFLAG = generate_random_crcflag();
    node->count++;

    // Signal that a new PDU is available
    pthread_cond_signal(&node->cond_var);

    pthread_mutex_unlock(&node->lock);
}

// Thread function to manage PDUs for each radio node
void* pdu_management_thread(void *arg) {
    RadioNode *node = (RadioNode*) arg;

    while (true) {
        pthread_mutex_lock(&node->lock);

        // Wait until there is a new PDU to process or the condition changes
        while (node->count == 0) {
            pthread_cond_wait(&node->cond_var, &node->lock);
        }

        // Process PDUs here (e.g., send over network, log data)
        for (size_t i = 0; i < node->count; ++i) {
            printf("Processing PDU with RNTI: %u, CRCFLAG: %d\n",
                   node->pdus[i].RNTI, node->pdus[i].CRCFLAG);
        }

        // Clear processed PDUs
        node->count = 0;

        pthread_mutex_unlock(&node->lock);
    }
}

// Function to initialize a radio node
void init_radio_node(RadioNode *node, int priority) {
    pthread_mutex_init(&node->lock, NULL);
    pthread_cond_init(&node->cond_var, NULL);
    node->priority = priority;
    node->count = 0;

    // Add the node to global list
    pthread_mutex_lock(&global_lock);
    if (node_count < MAX_NODES) {
        radio_nodes[node_count++] = *node;
    }
    pthread_mutex_unlock(&global_lock);

    // Start PDU management thread for this node
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, pdu_management_thread, node);
}

// Function to dynamically add a new radio node
void add_radio_node(int priority) {
    if (node_count < MAX_NODES) {
        RadioNode *new_node = &radio_nodes[node_count++];
        init_radio_node(new_node, priority);
    } else {
        printf("Maximum number of nodes reached.\n");
    }
}

// Main function for demonstration purposes
int main() {
    srand(time(NULL));

    // Initialize some radio nodes
    add_radio_node(1);
    add_radio_node(2);

    // Simulate adding PDUs to a node (in practice, this would be based on real events)
    uint16_t rnti_values[] = {1001, 1002, 1003};
    for (int i = 0; i < 10; ++i) {
        add_pdu_to_node(&radio_nodes[0], rnti_values[i % 3]);
        usleep(100000); // Simulate time delay
    }

    // Main thread should ideally wait or perform other tasks
    while (true) {
        sleep(1);
    }

    return 0;
}
```

### Key Features:
- **Concurrency**: Each radio node has its own mutex and condition variable to manage PDUs.
- **Priority Handling**: Nodes can be initialized with a priority, which could be used for further enhancements like scheduling or resource allocation.
- **Dynamic Scaling**: New nodes can be added dynamically using `add_radio_node`.
- **Efficient Memory Usage**: Uses fixed-size arrays for PDUs to avoid dynamic memory allocation issues.
- **Backpressure Mechanism**: The condition variable ensures that threads wait when there are no PDUs to process, preventing busy-waiting and reducing CPU usage.

### Integration Considerations:
- Ensure logging is integrated where the `printf` statements are.
- Adapt the number of concurrent nodes (`MAX_NODES`) based on system capabilities.
- Use real-time metrics libraries for detailed monitoring if needed.']

