#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_NF_API_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) {
        perror("Failed to allocate memory for dynamic array");
        return NULL;
    }
    pthread_mutex_init(&da->lock, NULL);
    da->array = NULL;
    da->count = 0;
    da->capacity = 0;
    return da;
}

bool is_unique(DynamicArray* da, int RX_UE_INFORMATION_TAG, int RNTI) {
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG ||
            da->array[i].RNTI == RNTI) {
            return false;
        }
    }
    return true;
}

bool add_pdu(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);

    if (da->count >= MAX_NF_API_SIZE || !is_unique(da, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI)) {
        pthread_mutex_unlock(&da->lock);
        return false;
    }

    if (da->capacity == 0) {
        da->capacity = 1;
    } else if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        if (new_capacity < da->capacity || new_capacity > MAX_NF_API_SIZE) {
            pthread_mutex_unlock(&da->lock);
            fprintf(stderr, "Capacity overflow or exceeded maximum size\n");
            return false;
        }
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            perror("Failed to reallocate memory for dynamic array");
            return false;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->count++] = pdu;

    pthread_mutex_unlock(&da->lock);
    return true;
}

void free_dynamic_array(DynamicArray* da) {
    if (da) {
        pthread_mutex_destroy(&da->lock);
        free(da->array);
        free(da);
    }
}

int main() {
    DynamicArray* da = init_dynamic_array();
    if (!da) {
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRC_INDICATION_REL8_TAG = {.CRCFLAG = true} };

    if (add_pdu(da, pdu)) {
        printf("PDU added successfully\n");
    } else {
        printf("Failed to add PDU\n");
    }

    free_dynamic_array(da);
    return EXIT_SUCCESS;
}
