#define MAX_N 10000 // Predefined maximum size
#define LOG_FILE "memory_log.txt"

typedef struct {
    int field1;
    char data[256];
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_array(size_t N) {
    if (N <= 0 || N > MAX_N) {
        log_memory_usage("Invalid request: N is out of bounds.");
        return NULL;
    }

    pthread_mutex_lock(&memory_mutex);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_memory_usage("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T array.");
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }

    // Initialize allocated memory to zero
    memset(array, 0, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    size_t used_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated %zu bytes for %zu elements.", used_memory, N);
    log_memory_usage(log_message);

    pthread_mutex_unlock(&memory_mutex);

    return array;
}

void deallocate_nfa_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (!array) {
        return;
    }

    pthread_mutex_lock(&memory_mutex);

    free(array);
    log_memory_usage("Deallocated memory for NFAPI_CRC_INDICATION_PDU_T array.");

    pthread_mutex_unlock(&memory_mutex);
}

int main() {
