#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_SRS_CONFIG 10

typedef struct {
    int valid;
    uint32_t lte_phy_layer_tag;
} LTE_PHYSICAL_LAYER_TAG;

typedef struct {
    int srs_config_id; // Unique ID for SRS configuration
    // Additional SRS parameters can be added here
} SRS_Configuration;

typedef struct {
    LTE_PHYSICAL_LAYER_TAG tag;
    SRS_Configuration srs_config;
    float transmit_power_level;
} LTE_PHY_FRAME;

typedef struct {
    LTE_PHY_FRAME *frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} FrameManager;

// Function prototypes
FrameManager* create_frame_manager(size_t initial_capacity);
void destroy_frame_manager(FrameManager *manager);
int add_frame(FrameManager *manager, const LTE_PHYSICAL_LAYER_TAG tag, const SRS_Configuration srs_config, float power_level);
LTE_PHY_FRAME* get_next_frame_to_transmit(const FrameManager *manager);
void backpressure_mechanism(FrameManager *manager);

// Create a frame manager with initial capacity
FrameManager* create_frame_manager(size_t initial_capacity) {
    FrameManager *manager = (FrameManager *)malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = (LTE_PHY_FRAME *)calloc(initial_capacity, sizeof(LTE_PHY_FRAME));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Destroy a frame manager and release resources
void destroy_frame_manager(FrameManager *manager) {
    if (!manager) return;

    free(manager->frames);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Add a frame to the manager ensuring no consecutive frames share the same SRS configuration
int add_frame(FrameManager *manager, const LTE_PHYSICAL_LAYER_TAG tag, const SRS_Configuration srs_config, float power_level) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for available space and ensure no consecutive frames have the same SRS configuration
    size_t i;
    int can_add = 1;

    if (manager->count > 0 && manager->frames[manager->count - 1].srs_config.srs_config_id == srs_config.srs_config_id) {
        can_add = 0; // Consecutive frame with same SRS config detected
    }

    if (can_add && manager->count < manager->capacity) {
        manager->frames[manager->count] = (LTE_PHY_FRAME){
            .tag = tag,
            .srs_config = srs_config,
            .transmit_power_level = power_level
        };
        manager->count++;
    } else if (!can_add) {
        backpressure_mechanism(manager);
    }

    pthread_mutex_unlock(&manager->lock);

    return can_add ? 0 : -1;
}

// Retrieve the next frame to transmit, ensuring no two consecutive frames share the same SRS config
LTE_PHY_FRAME* get_next_frame_to_transmit(const FrameManager *manager) {
    if (!manager || manager->count == 0) return NULL;

    pthread_mutex_lock(&manager->lock);

    // Logic to determine the next frame to send, respecting constraints
    for (size_t i = 1; i < manager->count; ++i) {
        if (manager->frames[i].srs_config.srs_config_id != manager->frames[i - 1].srs_config.srs_config_id) {
            LTE_PHY_FRAME *frame_to_send = &manager->frames[i];
            // Shift frames left
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->frames[j] = manager->frames[j + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return frame_to_send;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return NULL; // No valid frame found
}

// Implement backpressure to manage high processing rates and prevent buffer overflow
void backpressure_mechanism(FrameManager *manager) {
    if (!manager) return;

    printf("Backpressure activated. Adjusting frame generation rate.\n");
    // Logic to reduce the frame generation rate or notify upstream components
    // Could include logging, notifications, or dynamic adjustments
}

// Example usage and documentation placeholder
