#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    double timestamp;
    char frame_id[64];
    float signal_strength;
    float error_rate;
} FrameMetaData;

// Structure to hold retrieved data
typedef struct {
    size_t size;
    FrameMetaData *data;
    pthread_mutex_t lock;  // Mutex for thread safety
} MetaDataCache;

// Function prototypes
static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata);
void fetch_csv_data(const char *url, MetaDataCache *cache);
void parse_csv_line(const char *line, FrameMetaData *meta);
void update_cache(MetaDataCache *cache, const FrameMetaData *new_meta);
void free_metadata_cache(MetaDataCache *cache);

int main() {
    const char *csv_url = "https://example.com/data.csv";
    MetaDataCache cache = {0, NULL, PTHREAD_MUTEX_INITIALIZER};

    fetch_csv_data(csv_url, &cache);

    // Use the data...

    free_metadata_cache(&cache);
    return 0;
}

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    char **data = (char **)userdata;
    size_t new_len = strlen(*data) + size * nmemb + 1; 
    *data = realloc(*data, new_len);
    if (*data == NULL) return 0;

    memcpy(*data + strlen(*data), ptr, size * nmemb);
    (*data)[new_len - 1] = '\0';
    return size * nmemb;
}

void fetch_csv_data(const char *url, MetaDataCache *cache) {
    CURL *curl;
    CURLcode res;
    char *response_data = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response_data);

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Parse CSV data
            char *line = strtok(response_data, "\n");
            while (line) {
                FrameMetaData meta;
                parse_csv_line(line, &meta);
                update_cache(cache, &meta);
                line = strtok(NULL, "\n");
            }
        }

        curl_easy_cleanup(curl);
    }

    if (response_data) free(response_data);
    curl_global_cleanup();
}

void parse_csv_line(const char *line, FrameMetaData *meta) {
    sscanf(line, "%lf,%63[^,],%f,%f", &meta->timestamp, meta->frame_id, &meta->signal_strength, &meta->error_rate);
}

void update_cache(MetaDataCache *cache, const FrameMetaData *new_meta) {
    pthread_mutex_lock(&cache->lock);

    cache->data = realloc(cache->data, (cache->size + 1) * sizeof(FrameMetaData));
    if (cache->data == NULL) {
        perror("Failed to reallocate memory for new metadata");
        exit(EXIT_FAILURE);
    }

    memcpy(&cache->data[cache->size], new_meta, sizeof(FrameMetaData));
    cache->size++;

    pthread_mutex_unlock(&cache->lock);
}

void free_metadata_cache(MetaDataCache *cache) {
    pthread_mutex_lock(&cache->lock);

    free(cache->data);

    pthread_mutex_unlock(&cache->lock);
}
```

This code sets up a function to manage a dynamically allocated array of `FrameMetaData` structures. It fetches CSV data from a URL, parses it into structured metadata, and updates a cache while ensuring thread safety with mutex locks. The implementation also includes comprehensive error handling for memory allocation failures and network errors using libcurl. 

Note: The example assumes the CSV format is straightforward (e.g., timestamp, frame_id, signal_strength, error_rate). For real-world applications, additional validation might be required to handle unexpected or corrupt data gracefully.']

