['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int SUBSCRIPTION_ID;
    time_t TIMESTAMP;
    unsigned int CHANNEL_ACCESS_REQUEST_TAG;
} PHY_CHANNEL_ACCESS_INFO_T;

typedef struct Node {
    PHY_CHANNEL_ACCESS_INFO_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    pthread_mutex_t lock;
} ChannelAccessList;

int isTimestampValid(time_t timestamp) {
    return (timestamp != ((time_t)-1));
}

ChannelAccessList* createChannelAccessList() {
    ChannelAccessList* list = (ChannelAccessList*)malloc(sizeof(ChannelAccessList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for ChannelAccessList\n");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int addChannelAccessInfo(ChannelAccessList* list, PHY_CHANNEL_ACCESS_INFO_T info) {
    if (list->size >= MAX_STRUCTURES) {
        fprintf(stderr, "Maximum number of structures reached\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;

    while (*current) {
        Node* entry = *current;

        if (entry->data.SUBSCRIPTION_ID == info.SUBSCRIPTION_ID ||
            entry->data.TIMESTAMP == info.TIMESTAMP) {
            fprintf(stderr, "Duplicate SUBSCRIPTION_ID or TIMESTAMP detected\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        current = &entry->next;
    }

    if (!isTimestampValid(info.TIMESTAMP)) {
        fprintf(stderr, "Invalid timestamp detected\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for new node\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newNode->data = info;
    newNode->next = NULL;

    *current = newNode;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    printf("Added: SUBSCRIPTION_ID=%d, TIMESTAMP=%ld\n", info.SUBSCRIPTION_ID, info.TIMESTAMP);
    return 0;
}

void freeChannelAccessList(ChannelAccessList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    ChannelAccessList* channelList = createChannelAccessList();
    if (!channelList) return 1;

    srand(time(NULL));

    for (int i = 0; i < MAX_STRUCTURES + 10; ++i) {
        PHY_CHANNEL_ACCESS_INFO_T info;
        info.SUBSCRIPTION_ID = rand() % 10000;
        info.TIMESTAMP = time(NULL) + (rand() % 100);
        info.CHANNEL_ACCESS_REQUEST_TAG = rand();

        addChannelAccessInfo(channelList, info);
    }

    freeChannelAccessList(channelList);

    return 0;
}
```']

