#define MAX_STREAMS 10

typedef struct {
    uint32_t data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int stream_id;
    int valid_count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* filtered_data;
    pthread_mutex_t lock;
} StreamData;

static void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

void* process_stream(void* arg);

StreamData streams[MAX_STREAMS];

uint32_t generate_rx_ue_information_tag(int stream_id, int index) {
    time_t now = time(NULL);
    pthread_mutex_lock(&streams[stream_id].lock);
    uint32_t tag = (now << 16) | (stream_id << 8) | index;
    pthread_mutex_unlock(&streams[stream_id].lock);
    return tag;
}

uint16_t calculate_rnti(int stream_id, int index) {
    srand(time(NULL) ^ stream_id ^ index); // Seed based on unique parameters
    uint16_t rnti = rand() & 0xFFFF; // Ensure it's a 16-bit value
    return rnti;
}

void process_data_chunk(StreamData* stream_data, const int *data_chunk, size_t length) {
    pthread_mutex_lock(&stream_data->lock);

    for (size_t i = 0; i < length; ++i) {
        if (data_chunk[i] % 3 == 0) {
            if (stream_data->valid_count >= stream_data->capacity) {
                size_t new_capacity = stream_data->capacity > 0 ? stream_data->capacity * 2 : 4;
                NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(stream_data->filtered_data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!new_array) {
                    pthread_mutex_unlock(&stream_data->lock);
                    error_exit("Failed to allocate memory");
                }
                stream_data->capacity = new_capacity;
                stream_data->filtered_data = new_array;
            }

            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.data = data_chunk[i];

            uint32_t tag = generate_rx_ue_information_tag(stream_data->stream_id, stream_data->valid_count);
            uint16_t rnti = calculate_rnti(stream_data->stream_id, (int)stream_data->valid_count);

            // Populate the structure as needed
            printf("Stream %d: PDU Data=%u, Tag=0x%X, RNTI=0x%04X\n", 
                   stream_data->stream_id, pdu.data, tag, rnti);

            stream_data->filtered_data[stream_data->valid_count++] = pdu;
        }
    }

    pthread_mutex_unlock(&stream_data->lock);
}

void* process_stream(void *arg) {
    int stream_id = *(int*)arg;
    StreamData *stream_data = &streams[stream_id];

    // Simulate reading data from a source
    const size_t chunk_size = 1000;
    while (1) {
        int *data_chunk = malloc(chunk_size * sizeof(int));
        if (!data_chunk) error_exit("Memory allocation failed");

        // Populate data_chunk with sample integers for demonstration purposes
        for (size_t i = 0; i < chunk_size; ++i)
            data_chunk[i] = rand() % 100;

        process_data_chunk(stream_data, data_chunk, chunk_size);
        free(data_chunk);

        if (rand() % 5 == 0) break; // Simulate end of stream condition
    }

    pthread_mutex_lock(&stream_data->lock);
    NFAPI_CRC_INDICATION_PDU_T* final_data = realloc(stream_data->filtered_data, 
                                                     stream_data->valid_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!final_data && stream_data->valid_count > 0) {
        free(stream_data->filtered_data);
        stream_data->filtered_data = NULL;
    } else {
        stream_data->filtered_data = final_data;
        stream_data->capacity = stream_data->valid_count;
    }
    pthread_mutex_unlock(&stream_data->lock);

    return NULL;
}

int main() {
    pthread_t threads[MAX_STREAMS];

    for (int i = 0; i < MAX_STREAMS; ++i) {
        streams[i].stream_id = i;
        streams[i].valid_count = 0;
        streams[i].capacity = 0;
        streams[i].filtered_data = NULL;
        if (pthread_mutex_init(&streams[i].lock, NULL) != 0)
            error_exit("Mutex init failed");
    }

    for (int i = 0; i < MAX_STREAMS; ++i) {
        int* stream_id_ptr = malloc(sizeof(int));
        *stream_id_ptr = i;
        if (pthread_create(&threads[i], NULL, process_stream, (void*)stream_id_ptr) != 0)
            error_exit("Thread creation failed");
    }

    for (int i = 0; i < MAX_STREAMS; ++i) {
        pthread_join(threads[i], NULL);
        free(streams[i].filtered_data);
        pthread_mutex_destroy(&streams[i].lock);
    }

    return 0;
}
```

This code simulates concurrent processing of multiple data streams, filtering integers divisible by 3 and storing them in dynamically allocated arrays. It includes mechanisms for thread safety, unique tag generation, and resource management.']

