#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int key; // Using RNTI as key
    NFAPI_CRC_INDICATION_PDU_T value;
    struct Node* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
} CustomHashTable;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
CustomHashTable hashTable;
NFAPI_CRC_INDICATION_PDU_T* dynamicArray[MAX_ELEMENTS];
size_t arraySize = 0;

unsigned int hashFunction(int key) {
    return key % hashTable.capacity;
}

void initializeHashTable(size_t capacity) {
    hashTable.capacity = capacity;
    hashTable.buckets = (HashNode**)calloc(capacity, sizeof(HashNode*));
}

void freeHashTable() {
    for (size_t i = 0; i < hashTable.capacity; ++i) {
        HashNode* entry = hashTable.buckets[i];
        while (entry != NULL) {
            HashNode* prev = entry;
            entry = entry->next;
            free(prev);
        }
    }
    free(hashTable.buckets);
}

HashNode* findInHashTable(int key) {
    unsigned int index = hashFunction(key);
    HashNode* entry = hashTable.buckets[index];
    while (entry != NULL && entry->key != key) {
        entry = entry->next;
    }
    return entry;
}

void insertIntoHashTable(NFAPI_CRC_INDICATION_PDU_T value, int key) {
    unsigned int index = hashFunction(key);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->key = key;
    newNode->value = value;
    newNode->next = hashTable.buckets[index];
    hashTable.buckets[index] = newNode;
}

void insertIntoArray(NFAPI_CRC_INDICATION_PDU_T* newElement) {
    if (!newElement || arraySize >= MAX_ELEMENTS) return;

    pthread_mutex_lock(&lock);
    dynamicArray[arraySize++] = newElement;

    // Update Hash Table
    insertIntoHashTable(*newElement, newElement->RNTI);

    pthread_mutex_unlock(&lock);
}

int validateStructure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (!structure || structure->RX_UE_INFORMATION_TAG < 0 ||
        structure->RNTI < 0 || structure->CRC_INDICATION_REL8_TAG < 0)
        return -1;
    return 0;
}

int insertStructure(NFAPI_CRC_INDICATION_PDU_T* newElement) {
    if (validateStructure(newElement)) {
        fprintf(stderr, "Invalid structure detected\n");
        return -1;
    }

    pthread_mutex_lock(&lock);
    HashNode* existing = findInHashTable(newElement->RNTI);
    if (existing) {
        *existing = *newElement; // Update existing
    } else {
        insertIntoArray(newElement); // Insert new
    }
    pthread_mutex_unlock(&lock);

    return 0;
}

void serializeArray(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&arraySize, sizeof(size_t), 1, file);
    fwrite(dynamicArray, sizeof(NFAPI_CRC_INDICATION_PDU_T*), arraySize, file);

    fclose(file);
}

void deserializeArray(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fread(&arraySize, sizeof(size_t), 1, file);
    dynamicArray = (NFAPI_CRC_INDICATION_PDU_T**)malloc(arraySize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    fread(dynamicArray, sizeof(NFAPI_CRC_INDICATION_PDU_T*), arraySize, file);

    fclose(file);
}

int main() {
    initializeHashTable(256); // Example capacity

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1001, 2};
    insertStructure(&pdu);

    serializeArray("data.bin");
    deserializeArray("data.bin");

    freeHashTable();
    free(dynamicArray);

    return 0;
}
