typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    sqlite3* db;
    const char* dsn; // Data Source Name or connection string
} ConnectionInfo;

typedef struct IDataReader IDataReader; // Forward declaration

IDataReader* process_and_query_db(const ConnectionInfo* db_conn, const char* sql_command, int N) {
    if (!db_conn || !sql_command || N <= 0) return NULL;

    sqlite3* db = db_conn->db;
    if (sqlite3_open_v2(db_conn->dsn, &db, SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE, NULL) != SQLITE_OK) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        sqlite3_close(db);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand(); // Example of random generation
        pdu_list[i].RNTI = rand();
        pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG 0 or 1
    }

    char* errMsg = NULL;
    sqlite3_stmt* stmt;

    if (sqlite3_prepare_v2(db, sql_command, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
        free(pdu_list);
        sqlite3_close(db);
        return NULL;
    }

    int batch_size = 100; // Adjust based on testing
    for (int i = 0; i < N; ++i) {
        if (sqlite3_bind_int(stmt, 1, pdu_list[i].RX_UE_INFORMATION_TAG) != SQLITE_OK ||
            sqlite3_bind_int(stmt, 2, pdu_list[i].RNTI) != SQLITE_OK ||
            sqlite3_bind_int(stmt, 3, pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG) != SQLITE_OK) {
            fprintf(stderr, "Failed to bind parameters: %s\n", sqlite3_errmsg(db));
            break;
        }

        if (i > 0 && i % batch_size == 0 || i == N - 1) {
            if (sqlite3_step(stmt) != SQLITE_DONE) {
                fprintf(stderr, "Execution failed: %s\n", sqlite3_errmsg(db));
                break;
            }
            sqlite3_reset(stmt);
        } else {
            if (sqlite3_step(stmt) != SQLITE_DONE) {
                fprintf(stderr, "Execution failed: %s\n", sqlite3_errmsg(db));
                break;
            }
        }
    }

    sqlite3_finalize(stmt);
    free(pdu_list);

    // Optional: Implement caching strategy here if needed

    // Return a dummy IDataReader* for example purposes
    return NULL; 
}

// Example unit test function (more comprehensive tests are recommended)
