// Function to generate NFAPI_CRC_INDICATION_PDU_T structures
void generateNFACRCIndications(std::vector<NFAPI_CRC_INDICATION_PDU_T>& indications) {
    std::mutex indicationMutex;

    auto generateRandomCRCFLAG = []() -> bool {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        return gen() % 2 == 0; // Randomly returns true or false
    };

    std::lock_guard<std::mutex> lock(indicationMutex);

    for (size_t i = 0; i < indications.size(); ++i) {
        indications[i].ue_info_tag = RX_UE_INFORMATION_TAG{};
        indications[i].rnti = RNTI{};
        indications[i].crc_indication_rel8_tag.CRCFLAG = generateRandomCRCFLAG();
    }
}

// Function to select an attack with cooldown management
void selectAttack(int characterEnergy) {
    std::lock_guard<std::mutex> lock(attackMutex);

    int selectedAttack;

    // Determine available attacks based on cooldowns and energy
    for (int i = 0; i < 4; ++i) {
        auto now = std::chrono::steady_clock::now();
        if (cooldownEndTimes[i] <= now && characterEnergy >= attackCooldownSeconds[i]) {
            selectedAttack = i;
            break;
        }
    }

    // If no valid attack is found, retry after a short delay
    if (selectedAttack == 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        selectAttack(characterEnergy);
        return;
    }

    // Update last selected attack and its cooldown end time
    lastSelectedAttack = selectedAttack;
    cooldownEndTimes[selectedAttack] = std::chrono::steady_clock::now() + 
                                       std::chrono::seconds(attackCooldownSeconds[selectedAttack]);

    // Print the selected attack number to the console
    std::cout << "Selected Attack: " << selectedAttack + 1 << std::endl;
