import time

typedef struct {
    unsigned int timestamp;
    unsigned int messageID;
    size_t payloadLength;
} MessageHeader;

typedef struct {
    MessageHeader header;
    char* dataBuffer; // Dynamically allocated based on payloadLength
} CustomMessage;

typedef struct {
    CustomMessage** messages;
    size_t capacity;
    size_t count;
} DynamicArray;

// External Data Source Simulation
CustomMessage fetchInitialTemplateFromDataSource(unsigned int messageID) {
    // Simulate fetching from an external source
    printf("Fetching initial template for Message ID: %u\n", messageID);
    CustomMessage msg;
    msg.header.timestamp = (unsigned int)time(NULL);
    msg.header.messageID = messageID;
    msg.header.payloadLength = 256; // Example payload size
    msg.dataBuffer = malloc(msg.header.payloadLength * sizeof(char));
    if (!msg.dataBuffer) {
        fprintf(stderr, "Failed to allocate memory for data buffer.\n");
        exit(EXIT_FAILURE);
    }
    printf("Template fetched with payload length: %zu\n", msg.header.payloadLength);
    return msg;
}

// Initialize Dynamic Array
int initializeDynamicArray(DynamicArray* array, size_t initialCapacity) {
    if (!array) return -1;

    array->messages = malloc(initialCapacity * sizeof(CustomMessage*));
    if (!array->messages) return -1; // Memory allocation failed

    array->capacity = initialCapacity;
    array->count = 0;
    printf("DynamicArray initialized with capacity: %zu\n", initialCapacity);
    return 0;
}

// Resize Dynamic Array
int resizeDynamicArray(DynamicArray* array, size_t newCapacity) {
    if (!array || !array->messages) return -1;

    CustomMessage** newMessages = realloc(array->messages, newCapacity * sizeof(CustomMessage*));
    if (!newMessages) return -1; // Memory allocation failed

    array->messages = newMessages;
    array->capacity = newCapacity;
    printf("DynamicArray resized to capacity: %zu\n", newCapacity);
    return 0;
}

// Add a New Message
int addMessage(DynamicArray* array, unsigned int messageID) {
    if (!array || array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2 + 1; // Increase capacity and handle zero initial case
        int resizeStatus = resizeDynamicArray(array, newCapacity);
        if (resizeStatus == -1) return -1;
    }

    CustomMessage* msg = &fetchInitialTemplateFromDataSource(messageID); // Simulate external fetch

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i]->header.messageID == messageID) {
            free(array->messages[i]->dataBuffer);
            *array->messages[i] = *msg;
            printf("Message ID: %u updated.\n", messageID);
            return 0;
        }
    }

    array->messages[array->count++] = msg; // Add the new message
    printf("New message added with Message ID: %u\n", messageID);
    return 0;
}

// Retrieve a Message by ID
CustomMessage* getMessageByID(DynamicArray* array, unsigned int messageID) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i]->header.messageID == messageID)
            return array->messages[i];
    }
    printf("Message ID: %u not found.\n", messageID);
    return NULL;
}

// Clean Up Dynamic Array
void cleanupDynamicArray(DynamicArray* array) {
    if (!array || !array->messages) return;

    for (size_t i = 0; i < array->count; ++i) {
        free(array->messages[i]->dataBuffer);
        free(array->messages[i]);
    }
    free(array->messages);
    printf("DynamicArray cleaned up.\n");
}

// Main Function (Example Usage)
int main() {
    DynamicArray array;
    initializeDynamicArray(&array, 2);

    addMessage(&array, 101);
    addMessage(&array, 102);
    addMessage(&array, 103); // Triggers resize

    CustomMessage* msg = getMessageByID(&array, 102);
    if (msg) printf("Retrieved Message ID: %u\n", msg->header.messageID);

    cleanupDynamicArray(&array);
    return 0;
}
