typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} DynamicList;

// Function to initialize the dynamic list
void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
}

// Function to destroy the dynamic list and free memory
void destroyDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data.RX_UE_INFORMATION_TAG);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Function to add a new element to the dynamic list
void addElement(DynamicList* list, const NFAPI_CRC_INDICATION_PDU_T* element) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure

    newNode->data = *element;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Function to fetch an element by index
NFAPI_CRC_INDICATION_PDU_T* getElement(DynamicList* list, size_t index) {
    if (index >= list->size) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    if (current == NULL) return NULL;

    return &current->data;
}

// Function to simulate fetching and populating data from an external source
void fetchDataFromExternalSource(DynamicList* list, size_t count) {
