```cpp
#include <iostream>
#include <random>
#include <thread>
#include <mutex>
#include <vector>
#include <chrono>
#include <atomic>

// Mock structures to represent the game elements.
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

struct AttackDetails {
    std::string animation;
    std::string soundEffect;
    std::string visualEffect;
    std::function<bool()> preconditionCheck;
    std::chrono::milliseconds cooldown;
    std::atomic<std::chrono::steady_clock::time_point> lastUsedTime;
};

class AttackManager {
public:
    AttackManager() {
        // Initialize attacks with mock data.
        initializeAttacks();
    }

    void selectAttack() {
        std::lock_guard<std::mutex> lock(mutex_);

        auto now = std::chrono::steady_clock::now();

        for (auto& attack : attacks_) {
            if (canUseAttack(attack, now)) {
                executeAttack(attack);
                logAttackDetails(1);  // Log successful attempt.
                return;
            }
        }

        std::cout << "No attack available due to cooldown or unmet preconditions." << std::endl;
        logAttackDetails(0);  // Log failed attempt.
    }

private:
    void initializeAttacks() {
        attacks_.emplace_back({"Animation1", "Sound1", "Effect1",
                               [] { return true; },      // Example precondition
                               std::chrono::milliseconds(500),
                               std::chrono::steady_clock::time_point()});

        attacks_.emplace_back({"Animation2", "Sound2", "Effect2",
                               [] { return false; },     // Blocked by condition
                               std::chrono::milliseconds(1000),
                               std::chrono::steady_clock::time_point()});

        attacks_.emplace_back({"Animation3", "Sound3", "Effect3",
                               [] { return true; },      // Another example precondition
                               std::chrono::milliseconds(300),
                               std::chrono::steady_clock::time_point()});

        attacks_.emplace_back({"Animation4", "Sound4", "Effect4",
                               [] { return true; },
                               std::chrono::milliseconds(700),
                               std::chrono::steady_clock::time_point()});
    }

    bool canUseAttack(const AttackDetails& attack, const auto& now) {
        if (attack.preconditionCheck()) {
            auto elapsed = now - attack.lastUsedTime;
            return elapsed >= attack.cooldown;
        }
        return false;
    }

    void executeAttack(AttackDetails& attack) {
        // Simulate external dependency integration.
        std::cout << "Executing Attack with Animation: "
                  << attack.animation 
                  << ", Sound: " << attack.soundEffect
                  << ", Visual Effect: " << attack.visualEffect << "\n";

        // Update the last used time of this attack.
        attack.lastUsedTime = std::chrono::steady_clock::now();
    }

    void logAttackDetails(int success) {
        // Placeholder for logging mechanism.
        static int totalAttempts = 0;
        static int successfulAttempts = 0;

        totalAttempts++;
        if (success) {
            successfulAttempts++;
        }

        std::cout << "Total Attempts: " << totalAttempts
                  << ", Successful Attempts: " << successfulAttempts << "\n";
    }

    std::mutex mutex_;
    std::vector<AttackDetails> attacks_;
};

// Example of usage in a multithreaded environment.
int main() {
    AttackManager attackManager;

    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back([&attackManager]() {
            while (true) {
                attackManager.selectAttack();
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        });
    }

    for (auto& t : threads) {
        if (t.joinable()) {
            t.detach();  // Detach the thread since we don't join here.
        }
    }

    // Keep main alive to see some output.
    std::this_thread::sleep_for(std::chrono::seconds(5));

    return 0;
}
```

This code defines a `AttackManager` class that handles attack selection, precondition checks, cooldown management, and logging. It uses thread-safe mechanisms (`std::mutex`) to prevent race conditions during concurrent access by multiple threads. The implementation also includes mock data for animations, sound effects, and visual effects while allowing easy extension of new attacks through modular design.']

