#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol_type; // e.g., 6 for TCP, 17 for UDP
    size_t packet_size;
    double flow_duration;
} TrafficEvent;

// Mutex for thread-safe operations on the dynamic array
pthread_mutex_t events_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
} EventLog;

// Function to initialize an event log
void init_event_log(EventLog *log, size_t initial_capacity) {
    pthread_mutex_lock(&events_mutex);
    log->events = (TrafficEvent *)malloc(initial_capacity * sizeof(TrafficEvent));
    if (!log->events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
    log->capacity = initial_capacity;
    log->count = 0;
    pthread_mutex_unlock(&events_mutex);
}

// Function to add a new event
void add_event(EventLog *log, TrafficEvent event) {
    pthread_mutex_lock(&events_mutex);

    if (log->count >= log->capacity) {
        size_t new_capacity = log->capacity * 2;
        TrafficEvent *new_events = (TrafficEvent *)realloc(log->events, new_capacity * sizeof(TrafficEvent));
        if (!new_events) {
            perror("Failed to reallocate memory for events");
            pthread_mutex_unlock(&events_mutex);
            exit(EXIT_FAILURE);
        }
        log->events = new_events;
        log->capacity = new_capacity;
    }

    log->events[log->count++] = event;

    pthread_mutex_unlock(&events_mutex);
}

// Function to update an existing event by IP pair
void update_event(EventLog *log, const char *source_ip, const char *destination_ip, TrafficEvent updated_event) {
    pthread_mutex_lock(&events_mutex);

    for (size_t i = 0; i < log->count; ++i) {
        if (strcmp(log->events[i].source_ip, source_ip) == 0 &&
            strcmp(log->events[i].destination_ip, destination_ip) == 0) {

            log->events[i] = updated_event;
            pthread_mutex_unlock(&events_mutex);
            return;
        }
    }

    pthread_mutex_unlock(&events_mutex);
}

// Function to search for events within a specified time range
void search_events(EventLog *log, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&events_mutex);

    for (size_t i = 0; i < log->count; ++i) {
        if (log->events[i].timestamp >= start_time && log->events[i].timestamp <= end_time) {
            printf("Event found: %ld, %s -> %s\n", log->events[i].timestamp,
                   log->events[i].source_ip, log->events[i].destination_ip);
        }
    }

    pthread_mutex_unlock(&events_mutex);
}

// Function to free the event log
void free_event_log(EventLog *log) {
    pthread_mutex_lock(&events_mutex);

    if (log->events) {
        free(log->events);
        log->events = NULL;
    }
    log->capacity = 0;
    log->count = 0;

    pthread_mutex_unlock(&events_mutex);
}

// Example usage
int main() {
    EventLog log;
    init_event_log(&log, 10);

    TrafficEvent event1 = {time(NULL), "192.168.1.1", "192.168.1.2", 6, 1024, 0.5};
    add_event(&log, event1);

    // Update the event
    TrafficEvent updated_event1 = {time(NULL) + 60, "192.168.1.1", "192.168.1.2", 6, 2048, 1.0};
    update_event(&log, "192.168.1.1", "192.168.1.2", updated_event1);

    // Search events
    search_events(&log, time(NULL) - 120, time(NULL));

    free_event_log(&log);

    return 0;
}
```

