void initialize_pdu_collection(PduCollection *collection);
int add_or_update_pdu(PduCollection *collection, uint16_t rnti, NR_RLC_PDU pdu);
NR_RLC_PDU* find_pdu(PduCollection *collection, uint16_t rnti);
void iterate_and_process_pdus(PduCollection *collection, void (*process)(NR_RLC_PDU *));
void dynamic_resize(PduCollection *collection);

