    collection->capacity = INITIAL_SIZE;
    collection->count = 0;
    collection->pdus = malloc(sizeof(NR_RLC_PDU) * collection->capacity);
    pthread_mutex_init(&collection->lock, NULL);
}

int add_or_update_pdu(PduCollection *collection, uint16_t rnti, NR_RLC_PDU pdu) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->pdus[i].ue_info.RNTI == rnti) {
            memcpy(&collection->pdus[i], &pdu, sizeof(NR_RLC_PDU));
            pthread_mutex_unlock(&collection->lock);
            return 1; // Updated existing
        }
    }

    if (collection->count >= collection->capacity) {
        dynamic_resize(collection);
    }

    pdu.ue_info.RNTI = rnti;
    pdu.crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG for demonstration

    collection->pdus[collection->count++] = pdu;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Added new
}

NR_RLC_PDU* find_pdu(PduCollection *collection, uint16_t rnti) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->pdus[i].ue_info.RNTI == rnti) {
            NR_RLC_PDU *result = &collection->pdus[i];
            pthread_mutex_unlock(&collection->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Not found
}

void iterate_and_process_pdus(PduCollection *collection, void (*process)(NR_RLC_PDU *)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        process(&collection->pdus[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

void dynamic_resize(PduCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    NR_RLC_PDU *new_pdus = realloc(collection->pdus, sizeof(NR_RLC_PDU) * new_capacity);

    if (new_pdus) {
        collection->pdus = new_pdus;
        collection->capacity = new_capacity;
    } else {
        // Handle allocation failure appropriately
        fprintf(stderr, "Failed to resize PDU collection\n");
        exit(EXIT_FAILURE);
    }
}

// Example usage of processing function
void process_pdu(NR_RLC_PDU *pdu) {
    // Example operation: print the RNTI and CRCFLAG
    printf("RNTI: %u, CRCFLAG: %d\n", pdu->ue_info.RNTI, pdu->crc_tag.CRCFLAG);
}

// Cleanup function to free allocated resources
void cleanup_pdu_collection(PduCollection *collection) {
    free(collection->pdus);
    pthread_mutex_destroy(&collection->lock);
}
