['Below is an implementation in C that addresses your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_STRUCTURES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_List;

void init_list(NFAPI_List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(NFAPI_List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

NFAPI_List* create_nfa_list() {
    NFAPI_List* list = (NFAPI_List*)malloc(sizeof(NFAPI_List));
    init_list(list);
    return list;
}

int add_structure(NFAPI_List* list) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Maximum structure limit reached.\n");
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    srand((unsigned int)time(NULL) ^ pthread_self());
    NFAPI_CRC_INDICATION_PDU_T* new_data = &new_node->data;

    do {
        new_data->RX_UE_INFORMATION_TAG = rand();
        new_data->RNTI = (uint16_t)(rand() % 65536);
    } while ((list->count > 0) && (list->tail->data.RNTI == new_data->RNTI));

    new_data->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void print_list(NFAPI_List* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }
}

void free_list(NFAPI_List* list) {
    destroy_list(list);
    free(list);
}

int main() {
    NFAPI_List* nfa_list = create_nfa_list();

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        add_structure(nfa_list);
    }

    print_list(nfa_list);
    free_list(nfa_list);

    return 0;
}
```

### Key Points:
- **Thread Safety:** The list operations are protected with a mutex to ensure thread safety.
- **Random Number Generation:** Uses `srand` seeded with the current time and thread ID for randomness.
- **Dynamic List Management:** A linked list is used to allow dynamic resizing without memory fragmentation.
- **Error Handling:** Checks for memory allocation failures and maximum structure limits.
- **Logging:** Error messages are logged using `fprintf`.

This implementation balances between memory usage, performance, and scalability while ensuring thread safety.']

