#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_FILES 1024

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol_type; // e.g., TCP = 6, UDP = 17
    size_t packet_size;
} NetworkEvent;

typedef struct {
    char name[256];
    size_t size;
    time_t last_modified;
} FileMetadata;

typedef struct {
    NetworkEvent *events;
    size_t event_count;
    size_t capacity;
    pthread_mutex_t mutex;
    int crc_indications;
    int renamed_files;
} EventManager;

EventManager event_manager;

void init_event_manager() {
    event_manager.events = NULL;
    event_manager.event_count = 0;
    event_manager.capacity = 0;
    if (pthread_mutex_init(&event_manager.mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        exit(EXIT_FAILURE);
    }
    event_manager.crc_indications = 0;
    event_manager.renamed_files = 0;
}

void free_event_manager() {
    pthread_mutex_destroy(&event_manager.mutex);
    free(event_manager.events);
}

int add_or_update_event(time_t timestamp, const char *src_ip, const char *dst_ip,
                        int protocol_type, size_t packet_size) {
    pthread_mutex_lock(&event_manager.mutex);

    // Search for existing event
    NetworkEvent *found = NULL;
    for (size_t i = 0; i < event_manager.event_count; ++i) {
        if (strcmp(event_manager.events[i].source_ip, src_ip) == 0 &&
            strcmp(event_manager.events[i].destination_ip, dst_ip) == 0) {
            found = &event_manager.events[i];
            break;
        }
    }

    // If not found, add new event
    if (!found && event_manager.event_count >= event_manager.capacity) {
        size_t new_capacity = (event_manager.capacity + 1) * 2; // Double the capacity
        NetworkEvent *new_events = realloc(event_manager.events, new_capacity * sizeof(NetworkEvent));

        if (!new_events) {
            fprintf(stderr, "Failed to reallocate memory: %s\n", strerror(errno));
            pthread_mutex_unlock(&event_manager.mutex);
            return -1;
        }

        event_manager.events = new_events;
        event_manager.capacity = new_capacity;
    }

    if (!found) {
        found = &event_manager.events[event_manager.event_count++];
    }

    // Update or set the event
    found->timestamp = timestamp;
    strncpy(found->source_ip, src_ip, sizeof(found->source_ip));
    strncpy(found->destination_ip, dst_ip, sizeof(found->destination_ip));
    found->protocol_type = protocol_type;
    found->packet_size = packet_size;

    pthread_mutex_unlock(&event_manager.mutex);
    return 0;
}

NetworkEvent* search_events_by_time_range(time_t start, time_t end) {
    pthread_mutex_lock(&event_manager.mutex);

    size_t count = event_manager.event_count;
    NetworkEvent *results = malloc(count * sizeof(NetworkEvent));

    if (!results) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        pthread_mutex_unlock(&event_manager.mutex);
        return NULL;
    }

    size_t result_count = 0;
    for (size_t i = 0; i < count; ++i) {
        if (event_manager.events[i].timestamp >= start && event_manager.events[i].timestamp <= end) {
            results[result_count++] = event_manager.events[i];
        }
    }

    pthread_mutex_unlock(&event_manager.mutex);
    return realloc(results, result_count * sizeof(NetworkEvent));
}

void rename_file(FileMetadata *metadata) {
    pthread_mutex_lock(&event_manager.mutex);

    const char *extensions[] = {"txt", "jpg", "png", "gif"};
    int ext_len = 4;
    const size_t extension_size = 4;

    time_t now = time(NULL);
    srand((unsigned int)now);
    int rand_ext_index = rand() % (sizeof(extensions) / sizeof(extensions[0]));

    char new_name[256];
    snprintf(new_name, sizeof(new_name), "%s_%zu_%ld.%s", metadata->name,
             metadata->size, (long)(now * 1000), extensions[rand_ext_index]);

    strncpy(metadata->name, new_name, sizeof(metadata->name));

    event_manager.renamed_files++;

    pthread_mutex_unlock(&event_manager.mutex);
}

void process_files(FileMetadata files[], size_t n) {
    if (n <= 0) {
        fprintf(stderr, "Invalid number of files: %zu\n", n);
        return;
    }

    for (size_t i = 0; i < n && i < MAX_FILES; ++i) {
        rename_file(&files[i]);
    }
}

void log_metrics() {
    pthread_mutex_lock(&event_manager.mutex);

    printf("Total CRC indications: %d\n", event_manager.crc_indications);
    printf("Total renamed files: %d\n", event_manager.renamed_files);

    pthread_mutex_unlock(&event_manager.mutex);
}

int main() {
    init_event_manager();

    // Example usage
    FileMetadata files[] = {{"file1", 1024, time(NULL)}, {"file2", 2048, time(NULL)}};
    process_files(files, sizeof(files) / sizeof(files[0]));

    log_metrics();
    free_event_manager();

    return 0;
}
```

### Key Points:
