typedef struct {
    uint16_t UE_CONTEXT_TAG;
    uint8_t RRC_PDU_TAG;
    uint32_t PDCP_PDU_SIZE; // Size of the payload in bytes
    uint8_t *payload;       // Optional payload data
} NFAPI_RRC_CU_UP_PDU_T;

typedef struct {
    size_t count;
    NFAPI_RRC_CU_UP_PDU_T *array;
} NFAPI_RRC_CU_UP_PDU_Array;

// Function prototypes
NFAPI_RRC_CU_UP_PDU_Array* create_array(size_t initial_size);
void free_array(NFAPI_RRC_CU_UP_PDU_Array *nfa_array);
int serialize_to_file(const char *filename, const NFAPI_RRC_CU_UP_PDU_Array *nfa_array);
int deserialize_from_file(const char *filename, NFAPI_RRC_CU_UP_PDU_Array *nfa_array);
void update_payload_size(NFAPI_RRC_CU_UP_PDU_Array *nfa_array, size_t index, uint32_t new_size);

NFAPI_RRC_CU_UP_PDU_Array* create_array(size_t initial_size) {
    NFAPI_RRC_CU_UP_PDU_Array *nfa_array = malloc(sizeof(NFAPI_RRC_CU_UP_PDU_Array));
    if (!nfa_array) return NULL;

    nfa_array->count = 0;
    nfa_array->array = malloc(initial_size * sizeof(NFAPI_RRC_CU_UP_PDU_T));
    if (!nfa_array->array) {
        free(nfa_array);
        return NULL;
    }

    return nfa_array;
}

void free_array(NFAPI_RRC_CU_UP_PDU_Array *nfa_array) {
    if (nfa_array) {
        for (size_t i = 0; i < nfa_array->count; ++i) {
            free(nfa_array->array[i].payload);
        }
        free(nfa_array->array);
        free(nfa_array);
    }
}

int serialize_to_file(const char *filename, const NFAPI_RRC_CU_UP_PDU_Array *nfa_array) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    uint16_t version = 1; // Version for future compatibility
    fwrite(&version, sizeof(version), 1, file);
    fwrite(&nfa_array->count, sizeof(nfa_array->count), 1, file);

    for (size_t i = 0; i < nfa_array->count; ++i) {
        const NFAPI_RRC_CU_UP_PDU_T *pdu = &nfa_array->array[i];
        fwrite(&pdu->UE_CONTEXT_TAG, sizeof(pdu->UE_CONTEXT_TAG), 1, file);
        fwrite(&pdu->RRC_PDU_TAG, sizeof(pdu->RRC_PDU_TAG), 1, file);
        fwrite(&pdu->PDCP_PDU_SIZE, sizeof(pdu->PDCP_PDU_SIZE), 1, file);

        if (pdu->payload) {
            fwrite(pdu->payload, pdu->PDCP_PDU_SIZE, 1, file);
        }
    }

    fclose(file);
    return 0;
}

int deserialize_from_file(const char *filename, NFAPI_RRC_CU_UP_PDU_Array *nfa_array) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    uint16_t version;
    fread(&version, sizeof(version), 1, file);
    if (version != 1) return -2; // Unsupported version

    fread(&nfa_array->count, sizeof(nfa_array->count), 1, file);

    nfa_array->array = realloc(nfa_array->array, nfa_array->count * sizeof(NFAPI_RRC_CU_UP_PDU_T));
    if (!nfa_array->array) {
        fclose(file);
        return -3;
    }

    for (size_t i = 0; i < nfa_array->count; ++i) {
        NFAPI_RRC_CU_UP_PDU_T *pdu = &nfa_array->array[i];
        fread(&pdu->UE_CONTEXT_TAG, sizeof(pdu->UE_CONTEXT_TAG), 1, file);
        fread(&pdu->RRC_PDU_TAG, sizeof(pdu->RRC_PDU_TAG), 1, file);
        fread(&pdu->PDCP_PDU_SIZE, sizeof(pdu->PDCP_PDU_SIZE), 1, file);

        if (pdu->PDCP_PDU_SIZE > 0) {
            pdu->payload = malloc(pdu->PDCP_PDU_SIZE);
            if (!pdu->payload) {
                fclose(file);
                return -4; // Memory allocation failed
            }
            fread(pdu->payload, pdu->PDCP_PDU_SIZE, 1, file);
        } else {
            pdu->payload = NULL;
        }
    }

    fclose(file);
    return 0;
}

void update_payload_size(NFAPI_RRC_CU_UP_PDU_Array *nfa_array, size_t index, uint32_t new_size) {
    if (index < nfa_array->count) {
        NFAPI_RRC_CU_UP_PDU_T *pdu = &nfa_array->array[index];

        // Reallocate payload with the new size
        uint8_t *new_payload = realloc(pdu->payload, new_size);
        if (!new_payload && new_size > 0) {
            return; // Allocation failed, handle as needed
        }

        pdu->payload = new_payload;
        pdu->PDCP_PDU_SIZE = new_size;
    }
}
