#define INITIAL_CAPACITY 16

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRCFLAG;
    time_t timestamp; // For automatic cleanup
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

// Hash function for uniqueness check
uint32_t hash(uint32_t tag, uint32_t rnti) {
    return (tag ^ rnti) % 0x7FFFFFFF; // Simple XOR-based hash
}

// Check uniqueness using linear search
int is_unique(DynamicList *list, uint32_t tag, uint32_t rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RX_UE_INFORMATION_TAG == tag && 
            list->entries[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

// Resize the dynamic array
void resize(DynamicList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, 
                                                      sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (new_entries) {
        list->entries = new_entries;
        list->capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Add a new entry
int add_entry(DynamicList *list, uint32_t tag, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);

    if (!is_unique(list, tag, rnti)) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    if (list->count == list->capacity) {
        resize(list, list->capacity * 2);
    }

    NFAPI_CRC_INDICATION_PDU_T new_entry = {tag, rnti, hash(tag, rnti), time(NULL)};
    list->entries[list->count++] = new_entry;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

// Remove an entry
int remove_entry(DynamicList *list, uint32_t tag, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RX_UE_INFORMATION_TAG == tag && 
            list->entries[i].RNTI == rnti) {

            memmove(&list->entries[i], &list->entries[i + 1],
                    sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - i - 1));
            --list->count;

            if (list->count > INITIAL_CAPACITY && list->capacity > INITIAL_CAPACITY * 2) {
                resize(list, list->capacity / 2);
            }

            pthread_mutex_unlock(&list->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Serialize the list to a binary file
void serialize(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    fclose(file);
}

// Deserialize the list from a binary file
void deserialize(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    fread(&list->count, sizeof(size_t), 1, file);
    resize(list, list->count);

    fread(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    fclose(file);
}

// Periodic cleanup of old entries
void periodic_cleanup(DynamicList *list, time_t threshold) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count;) {
        if (time(NULL) - list->entries[i].timestamp > threshold) {
            memmove(&list->entries[i], &list->entries[i + 1],
                    sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - i - 1));
            --list->count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Initialize the dynamic list
void init_list(DynamicList *list) {
    list->entries = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Destroy the dynamic list
void destroy_list(DynamicList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}
