    }

    // Join with timeout
    do {
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - start.tv_sec) + (double)(now.tv_nsec - start.tv_nsec) / 1e9;

        if (elapsed > TIMEOUT_SECONDS) {
            pthread_cancel(thread_id);
            fprintf(stderr, "Operation timed out\n");
            return NULL;
        }
