// Define a node in our priority queue
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the priority queue structure
typedef struct PriorityQueue {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread-safe access
} PriorityQueue;

PriorityQueue* create_priority_queue() {
    PriorityQueue* pq = malloc(sizeof(PriorityQueue));
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
    return pq;
}

void enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL || pq->head->data.priority < data.priority) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next != NULL && current->next->data.priority >= data.priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL) {
        pthread_mutex_unlock(&pq->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0};  // Return a default value
    }

    Node* temp = pq->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    pq->head = pq->head->next;
    free(temp);

    pthread_mutex_unlock(&pq->lock);
    return data;
}

