```javascript
/**
 * Copies a specified number of bytes from a list of buffered data chunks into a new buffer.
 *
 * @param {Array<Buffer>} buffers - An array of Buffer objects containing data chunks.
 * @param {number} numBytesToCopy - The total number of bytes to copy from the buffers.
 * @returns {Buffer} A new buffer containing the copied data.
 */
function copyFromBuffers(buffers, numBytesToCopy) {
    if (!Array.isArray(buffers)) throw new Error('Input must be an array of Buffer objects.');
    if (typeof numBytesToCopy !== 'number' || numBytesToCopy < 0) throw new Error('Number of bytes to copy must be a non-negative integer.');

    let totalCopied = 0;
    const resultBuffer = Buffer.allocUnsafe(numBytesToCopy); // Allocate buffer without zero-filling for performance

    buffers.forEach(buffer => {
        if (!Buffer.isBuffer(buffer)) throw new Error('All elements in the input array must be Buffer objects.');

        const bytesAvailable = Math.min(buffer.length, numBytesToCopy - totalCopied);
        if (bytesAvailable > 0) {
            buffer.copy(resultBuffer, totalCopied, 0, bytesAvailable); // Copy data
            totalCopied += bytesAvailable;
        }
    });

    return resultBuffer.slice(0, totalCopied); // Return only the filled portion
}
