    free(manager);
}

int add_or_update_cell(CellManager *manager, int ci, PHY_LAYER_STATS_T *new_stats, size_t stats_count) {
    if (!manager || !new_stats) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->max_cells) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Error: Max cells limit reached
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->cells[i].ci == ci) {
            free(manager->cells[i].phy_stats);
            manager->cells[i].phy_stats = malloc(stats_count * sizeof(PHY_LAYER_STATS_T));
            if (!manager->cells[i].phy_stats) {
                pthread_mutex_unlock(&manager->lock);
                return -3; // Error: Memory allocation failed
            }
            memcpy(manager->cells[i].phy_stats, new_stats, stats_count * sizeof(PHY_LAYER_STATS_T));
            manager->cells[i].phy_stats_count = stats_count;
            pthread_mutex_unlock(&manager->lock);

            if (stats_count > manager->log_threshold) {
                printf("Cell ID %d updated with %zu statistics\n", ci, stats_count);
            }
            return 0; // Success: Cell updated
        }
    }

    LTE_RRC_CELLS_T new_cell = {ci, malloc(stats_count * sizeof(PHY_LAYER_STATS_T)), stats_count};
    memcpy(new_cell.phy_stats, new_stats, stats_count * sizeof(PHY_LAYER_STATS_T));
    manager->cells[manager->count++] = new_cell;

    pthread_mutex_unlock(&manager->lock);

    if (stats_count > manager->log_threshold) {
        printf("Cell ID %d added with %zu statistics\n", ci, stats_count);
    }
    return 0; // Success: Cell added
}

PHY_LAYER_STATS_T* get_cell_stats(CellManager *manager, int ci, size_t *count) {
    if (!manager || !count) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->cells[i].ci == ci) {
            *count = manager->cells[i].phy_stats_count;
            PHY_LAYER_STATS_T *stats = malloc(*count * sizeof(PHY_LAYER_STATS_T));
            if (!stats) {
                pthread_mutex_unlock(&manager->lock);
                return NULL; // Error: Memory allocation failed
            }
            memcpy(stats, manager->cells[i].phy_stats, *count * sizeof(PHY_LAYER_STATS_T));

            pthread_mutex_unlock(&manager->lock);

            printf("Cell ID %d retrieved with %zu statistics\n", ci, *count);
            return stats;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Error: Cell not found
}

void set_max_cells(CellManager *manager, size_t max_cells) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    manager->max_cells = max_cells;
    if (manager->count > max_cells) {
        for (size_t i = max_cells; i < manager->count; ++i) {
            free(manager->cells[i].phy_stats);
        }
        manager->count = max_cells;
    }

    pthread_mutex_unlock(&manager->lock);
}

void set_log_threshold(CellManager *manager, int log_threshold) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    manager->log_threshold = log_threshold;

    pthread_mutex_unlock(&manager->lock);
}
