    }

    size_t node_count = 0;
    NFAPI_CRC_INDICATION_PDU_T data;

    Node dummy_head;
    Node* tail = &dummy_head;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Memory allocation failed during deserialization");
