        new_node->data = data;
        new_node->next = NULL;

        tail->next = new_node;
        tail = new_node;
        node_count++;
    }

    fclose(file);
    printf("Deserialized %zu nodes from the file.\n", node_count);

    Node* head = dummy_head.next;
    free(dummy_head.next);  // Free temporary dummy node
    return head;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    *head = NULL;
}

