// Define the structure as per the given requirements
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRC_VALID;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
} ListNode;

// Structure to manage the linked list with a mutex for thread safety
typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
} CRCLinkedList;

// Initialize the linked list structure
void initCRCList(CRCLinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Insert function to maintain order based on RNTI values
void insertInOrder(CRCLinkedList *list, NFAPI_CRC_INDICATION_PDU_T packet) {
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) return;

    new_node->data = packet;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head || list->head->data.RNTI > packet.RNTI) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        ListNode *current = list->head;
        while (current->next && current->next->data.RNTI < packet.RNTI) {
            current = current->next;
        }
        if (current->next && current->next->data.RNTI == packet.RNTI) {
            // Handle duplicate RNTI entries
            free(new_node);
        } else {
            new_node->next = current->next;
            current->next = new_node;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to process incoming data packets
void processDataPacket(CRCLinkedList *list, NFAPI_CRC_INDICATION_PDU_T packet) {
    if (packet.CRC_VALID) {
        insertInOrder(list, packet);
    } else {
        // Log invalid CRC packets for debugging
        printf("Invalid CRC packet with RNTI: %u\n", packet.RNTI);
    }
}

// Function to handle data ingestion from an external stream
void ingestData(CRCLinkedList *list) {
    while (true) {  // Simulate continuous data stream processing
        NFAPI_CRC_INDICATION_PDU_T packet;
        // Populate the packet with incoming data here
        processDataPacket(list, packet);
    }
}

// Main function to demonstrate usage
int main() {
    CRCLinkedList list;
    initCRCList(&list);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void *(*)(void *))ingestData, &list) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Join the thread for demonstration; in a real application, this might be different
    pthread_join(thread_id, NULL);

    return EXIT_SUCCESS;
}
