}

// Function to destroy the list and free memory
void destroyCRCList(CRCList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Function to validate a new PDU
int validatePDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
