        fprintf(stderr, "Invalid PDU structure\n");
        free(pdu);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    pdu->next = list->head;
    list->head = pdu;
    list->size++;

    // Check performance threshold
    if (list->size > PERFORMANCE_THRESHOLD) {
        removeLeastRecentlyUsed(list);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to remove the least recently used PDU
void removeLeastRecentlyUsed(CRCList* list) {
    if (list->head == NULL || list->size <= PERFORMANCE_THRESHOLD) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;
    while (current->next != NULL) {
        prev = current;
        current = current->next;
    }

    if (prev != NULL) {
        free(current);
        prev->next = NULL;
    } else {
        // Only one element in the list
        NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }

    list->size--;
}

// Function to serialize the list (for demonstration purposes, using simple string format)
char* serializeCRCList(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    size_t buffer_size = 1024; // Example buffer size
    char* buffer = malloc(buffer_size);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for serialization\n");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        snprintf(buffer, buffer_size, "%lu,%u,%d;", 
