        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return buffer;
}

// Function to deserialize the list
int deserializeCRCList(CRCList* list, const char* data) {
    pthread_mutex_lock(&list->lock);

    destroyCRCList(list); // Clear existing list

    char* token = strtok(strdup(data), ";");
    while (token != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Failed to allocate memory for deserialization\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        sscanf(token, "%lu,%u,%d", &pdu->rx_ue_information_tag, &pdu->rnti, &pdu->crc_indication_rel8_tag.CRCFLAG);
        insertPDU(list, pdu);

        token = strtok(NULL, ";");
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Example usage
