#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define BUFFER_SIZE 256
#define STRING_LENGTH 64
#define RANDOM_RANGE 100

typedef struct {
    int value;
    char *buffer;
} Record;

typedef struct CRC_INDICATION_PDU_T {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned long CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t count;
    size_t max_size;
    long *offsets;
    int *keys;
    Record **records;
} LinkedListManager;

void initialize_manager(LinkedListManager *manager, size_t max_size) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->head = NULL;
    manager->count = 0;
    manager->max_size = max_size;
    manager->offsets = malloc(max_size * sizeof(long));
    manager->keys = malloc(max_size * sizeof(int));
    manager->records = calloc(max_size, sizeof(Record *));
}

void cleanup_manager(LinkedListManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    free(manager->offsets);
    free(manager->keys);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i]) {
            free(manager->records[i]->buffer);
            free(manager->records[i]);
        }
    }
    free(manager->records);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length) {
        --length;
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof charset - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    }
}

void reset_string(char *str, size_t length) {
    memset(str, '0', length);
    str[length - 1] = '\0';
}

void add_crc_indication(LinkedListManager *manager) {
    if (manager->count >= manager->max_size) return;

    pthread_mutex_lock(&manager->mutex);

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->RX_UE_INFORMATION_TAG = rand();
    new_node->RNTI = rand();
    new_node->CRC_INDICATION_REL8_TAG = rand();
    new_node->CRCFLAG = rand() % 2;
    new_node->next = manager->head;
    manager->head = new_node;

    manager->offsets[manager->count] = rand();
    manager->keys[manager->count] = rand() % RANDOM_RANGE;

    Record *record = malloc(sizeof(Record));
    record->buffer = malloc(BUFFER_SIZE);
    generate_random_string(record->buffer, STRING_LENGTH);
    record->value = rand() % RANDOM_RANGE;
    manager->records[manager->count] = record;

    if (manager->count % 10 == 0) {
        for (size_t i = 0; i < manager->count; ++i) {
            reset_string(manager->records[i]->buffer, STRING_LENGTH);
        }
    }

    manager->count++;

    pthread_mutex_unlock(&manager->mutex);
}

int main() {
    srand(time(NULL));
    LinkedListManager manager;
    initialize_manager(&manager, MAX_ENTRIES);

    // Simulate adding entries
    for (int i = 0; i < 2000; ++i) {
        add_crc_indication(&manager);
    }

    cleanup_manager(&manager);
    return 0;
}
```

