    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_LIST_SIZE 500000
#define MEMORY_POOL_SIZE 1024

typedef struct MemoryPool {
    size_t block_size;
    size_t pool_size;
    void* memory;
    char* free_blocks;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct ThreadSafeList {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_rwlock_t list_lock;
    MemoryPool mem_pool;
    size_t current_size;
} ThreadSafeList;

// Function prototypes
ThreadSafeList* create_thread_safe_list(size_t block_size, size_t pool_size);
void destroy_thread_safe_list(ThreadSafeList *list);
int insert_sorted(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T *node);
void cleanup_excess_elements(ThreadSafeList *list);
void verify_integrity(ThreadSafeList *list);

// Memory Pool functions
static void* memory_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    char *free_index = memchr(pool->free_blocks, '1', pool->pool_size);
    if (!free_index) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    *free_index = '0';
    pthread_mutex_unlock(&pool->lock);
    return (char*)pool->memory + free_index - pool->free_blocks;
}

static void memory_pool_init(MemoryPool *pool, size_t block_size, size_t pool_size) {
    pool->block_size = block_size;
    pool->pool_size = pool_size;
    pthread_mutex_init(&pool->lock, NULL);
    pool->memory = malloc(pool->block_size * pool_size);
    pool->free_blocks = calloc(pool_size, sizeof(char));
    for (size_t i = 0; i < pool_size; ++i) {
        pool->free_blocks[i] = '1';
    }
}

// Linked List functions
ThreadSafeList* create_thread_safe_list(size_t block_size, size_t pool_size) {
    ThreadSafeList *list = malloc(sizeof(ThreadSafeList));
    pthread_rwlock_init(&list->list_lock, NULL);
    memory_pool_init(&list->mem_pool, block_size, pool_size);
    list->head = NULL;
    list->current_size = 0;
    return list;
}

void destroy_thread_safe_list(ThreadSafeList *list) {
    NFAPI_CRC_INDICATION_PDU_T *node = list->head;
    while (node) {
        NFAPI_CRC_INDICATION_PDU_T *next = node->next;
        free(node);
        node = next;
    }
    pthread_rwlock_destroy(&list->list_lock);
    free(list->mem_pool.memory);
    free(list->mem_pool.free_blocks);
    pthread_mutex_destroy(&list->mem_pool.lock);
    free(list);
}

int insert_sorted(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_rwlock_wrlock(&list->list_lock);

    if (!list->head || list->head->RNTI > node->RNTI) {
        node->next = list->head;
        list->head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next && current->next->RNTI <= node->RNTI) {
            current = current->next;
        }
        node->next = current->next;
        current->next = node;
    }

    list->current_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (list->current_size > MAX_LIST_SIZE) {
        cleanup_excess_elements(list);
    }

    pthread_rwlock_unlock(&list->list_lock);
    return 0;
}

void cleanup_excess_elements(ThreadSafeList *list) {
    // Implement LRU cleanup logic here
    pthread_rwlock_wrlock(&list->list_lock);

    while (list->current_size > MAX_LIST_SIZE && list->head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->current_size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_rwlock_unlock(&list->list_lock);
}

void verify_integrity(ThreadSafeList *list) {
    pthread_rwlock_rdlock(&list->list_lock);

    NFAPI_CRC_INDICATION_PDU_T *node = list->head;
    while (node && node->next) {
        if (node->RNTI > node->next->RNTI) {
            fprintf(stderr, "List integrity issue: RNTI order violation.\n");
            // Additional logging and repair logic
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&list->list_lock);
}

// Example usage
int main() {
    ThreadSafeList *list = create_thread_safe_list(sizeof(NFAPI_CRC_INDICATION_PDU_T), MEMORY_POOL_SIZE);

    for (int i = 0; i < 100000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        node->RX_UE_INFORMATION_TAG = rand();
        node->RNTI = rand() % 65536;
        node->crc_tag.CRCFLAG = rand() & 1;
        insert_sorted(list, node);
    }

    verify_integrity(list);

    destroy_thread_safe_list(list);
    return 0;
}
