    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t maxEntries;
    pthread_mutex_t listLock;
    pthread_cond_t condVar;
} CRCIndicationList;

// Initialize the CRC indication list
CRCIndicationList* initCrcIndicationList(size_t initialMaxEntries) {
    CRCIndictionList *list = (CRCIndicationList *)malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;

    list->head = NULL;
    list->maxEntries = initialMaxEntries;
    pthread_mutex_init(&list->listLock, NULL);
    pthread_cond_init(&list->condVar, NULL);

    return list;
}

// Free the CRC indication list
void freeCrcIndicationList(CRCIndicationList *list) {
    if (!list) return;

    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        pthread_mutex_destroy(&current->data->lock);
        free(current->data);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->listLock);
    pthread_cond_destroy(&list->condVar);
    free(list);
}

// Get or create a CRC indication PDU
NFAPI_CRC_INDICATION_PDU_T* getOrCreatePdu(CRCIndicationList *list) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->listLock);

    Node *current = list->head;
    while (current) {
        if (!pthread_mutex_trylock(&current->data->lock)) { // Try to lock without blocking
            current->data->isActive = 1;
            pthread_mutex_unlock(&list->listLock);
            return current->data; // Reuse existing entry
        }
        current = current->next;
    }

    if (list->head && list->maxEntries > 0) {
        size_t count = 0;
        Node *prev = NULL, *iter = list->head;

        while (iter && count < list->maxEntries - 1) {
            prev = iter;
            iter = iter->next;
            count++;
        }

        if (count >= list->maxEntries) {
            // Remove the oldest inactive entry
            pthread_mutex_lock(&prev->data->lock);
            Node *oldNode = prev->next;
            prev->next = oldNode->next;
            pthread_mutex_unlock(&list->listLock);

            pthread_mutex_destroy(&oldNode->data->lock);
            free(oldNode->data);
            free(oldNode);
        }
    }

    // Allocate new entry if needed
    NFAPI_CRC_INDICATION_PDU_T *newPdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newPdu) {
        pthread_mutex_unlock(&list->listLock);
        return NULL;
    }

    newPdu->isActive = 1;
    pthread_mutex_init(&newPdu->lock, NULL);

    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data = newPdu;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->listLock);
    return newPdu;
}

// Set a random CRCFLAG
