```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int crc_validity_flag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Custom memory pool
#define POOL_SIZE 1024 * 1024 // Example size, adjust as needed

char memory_pool[POOL_SIZE];
size_t offset = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* custom_alloc(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[offset];
    offset += size;
    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

void custom_free(void* /*ptr*/) {
    // No-op for fixed-size pool
}

typedef struct {
    Node* head;
    pthread_mutex_t list_mutex;
} CRCList;

CRCList crc_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

void insert_crc_indication(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)custom_alloc(sizeof(Node));
    if (!new_node) return; // Handle allocation failure

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&crc_list.list_mutex);

    if (!crc_list.head || crc_list.head->data.RNTI > pdu.RNTI) {
        new_node->next = crc_list.head;
        crc_list.head = new_node;
    } else {
        Node* current = crc_list.head;
        while (current->next && current->next->data.RNTI < pdu.RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&crc_list.list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* find_crc_indication(uint16_t rnti, uint8_t tag) {
    pthread_mutex_lock(&crc_list.list_mutex);

    Node* current = crc_list.head;
    while (current) {
        if (current->data.RNTI == rnti && current->data.CRC_INDICATION_REL8_TAG == tag) {
            pthread_mutex_unlock(&crc_list.list_mutex);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&crc_list.list_mutex);
    return NULL;
}

void free_crc_list() {
    pthread_mutex_lock(&crc_list.list_mutex);

    Node* current = crc_list.head;
    while (current) {
        Node* next = current->next;
        custom_free(current);
        current = next;
    }

    crc_list.head = NULL;
    pthread_mutex_unlock(&crc_list.list_mutex);
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 100, 2, 1};
    insert_crc_indication(pdu1);

    NFAPI_CRC_INDICATION_PDU_T* found_pdu = find_crc_indication(100, 2);
    if (found_pdu) {
        printf("Found PDU with RNTI: %u\n", found_pdu->RNTI);
    }

    free_crc_list();
    return 0;
}
```

