void initialize_pool(ConnectionPool *pool, int max_nfa_entries, int max_packet_captures) {
    if (max_nfa_entries > MAX_NFAPI_ENTRIES || max_packet_captures > MAX_PACKET_CAPTURES) {
        fprintf(stderr, "Configuration exceeds predefined limits\n");
        exit(EXIT_FAILURE);
    }

