        exit(EXIT_FAILURE);
    }

    pool->packet_captures = malloc(max_packet_captures * sizeof(NetworkPacketCapture));
    if (!pool->packet_captures) {
        free(pool->nfa_entries);
        perror("Failed to allocate memory for packet captures");
        exit(EXIT_FAILURE);
    }

    pool->max_nfa_entries = max_nfa_entries;
    pool->max_packet_captures = max_packet_captures;
    pool->nfa_count = 0;
    pool->packet_count = 0;

    srand((unsigned)time(NULL));
}

void populate_nfa_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    entry->valid_RX_UE_INFORMATION_TAG = rand() % 2;
    entry->RNTI = rand();
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;
}

void populate_packet_capture(NetworkPacketCapture *capture) {
    capture->timestamp = time(NULL);
    capture->packet_length = (rand() % PACKET_DATA_SIZE) + 1;
    capture->data_ptr = malloc(capture->packet_length);

    if (!capture->data_ptr) {
        fprintf(stderr, "Failed to allocate memory for packet data\n");
        exit(EXIT_FAILURE);
    }

    randBytes(capture->data_ptr, capture->packet_length);
}

void randBytes(unsigned char *buf, size_t len) {
    for (size_t i = 0; i < len; ++i)
        buf[i] = rand() % 256;
}

void handle_dynamic_config(ConnectionPool *pool, int new_max_nfa_entries, int new_max_packet_captures) {
    if (new_max_nfa_entries > MAX_NFAPI_ENTRIES || new_max_packet_captures > MAX_PACKET_CAPTURES) {
        fprintf(stderr, "New configuration exceeds predefined limits\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *temp_nfa = realloc(pool->nfa_entries, new_max_nfa_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_nfa) {
        perror("Failed to reallocate memory for NFAPI entries");
        return;
    }

    NetworkPacketCapture *temp_packet = realloc(pool->packet_captures, new_max_packet_captures * sizeof(NetworkPacketCapture));
    if (!temp_packet) {
        free(temp_nfa);
        perror("Failed to reallocate memory for packet captures");
        return;
    }

    pool->nfa_entries = temp_nfa;
    pool->packet_captures = temp_packet;
    pool->max_nfa_entries = new_max_nfa_entries;
    pool->max_packet_captures = new_max_packet_captures;
}

void cleanup_pool(ConnectionPool *pool) {
    for (int i = 0; i < pool->packet_count; ++i)
        free(pool->packet_captures[i].data_ptr);

    free(pool->nfa_entries);
    free(pool->packet_captures);
}

