    int rx_ue_context;
} UE_CONTEXT;

typedef struct {
    UE_CONTEXT tx_ue_context;
    UE_CONTEXT rx_ue_context;
    int tx_power_level;
} LTE_PHY_TX_RX_CONTEXT;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int calculate_memory_size(size_t n) {
    size_t context_size = sizeof(LTE_PHY_TX_RX_CONTEXT);
    return (n * context_size);
}

void* initialize_lte_phy_tx_rx_contexts(int N, size_t max_memory_limit) {
    pthread_mutex_lock(&lock);

    if (calculate_memory_size(N) > max_memory_limit) {
        printf("Memory limit exceeded.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    LTE_PHY_TX_RX_CONTEXT *contexts = malloc(calculate_memory_size(N));
    if (!contexts) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        contexts[i].tx_ue_context.tx_ue_context = i + 1; // Example initialization
        contexts[i].rx_ue_context.rx_ue_context = i + 2; // Example initialization
        contexts[i].tx_power_level = TX_POWER_LEVEL_MIN + rand() % (TX_POWER_LEVEL_MAX - TX_POWER_LEVEL_MIN + 1);
    }

    pthread_mutex_unlock(&lock);
    return contexts;
}

void free_lte_phy_tx_rx_contexts(LTE_PHY_TX_RX_CONTEXT *contexts) {
    if (contexts) {
        pthread_mutex_lock(&lock);
        free(contexts);
        pthread_mutex_unlock(&lock);
    }
}
