    char header[HEADER_SIZE];
    unsigned char *payload;
    size_t payload_size;
    char metadata[METADATA_SIZE];
} Packet;

typedef struct {
    Packet **packets;
    size_t count;
    size_t capacity;
} PacketList;

// Function to calculate aligned memory size
size_t align_memory(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

// Initialize packet list with dynamic array of packets.
PacketList* initialize_packet_list(size_t initial_capacity, size_t payload_alignment) {
    PacketList *packet_list = malloc(sizeof(PacketList));
    if (!packet_list) return NULL;

    packet_list->packets = calloc(initial_capacity, sizeof(Packet *));
    if (!packet_list->packets) {
        free(packet_list);
        return NULL;
    }

    packet_list->count = 0;
    packet_list->capacity = initial_capacity;
    srand((unsigned int)time(NULL)); // Seed for random number generation

    size_t payload_size;
    unsigned char *payload;

    for (size_t i = 0; i < MAX_PACKETS && packet_list->count < initial_capacity; ++i) {
        // Randomly determine the size of payload
        payload_size = rand() % 1024 + 1; // Payload between 1 and 1024 bytes

        // Align the payload size
        payload_size = align_memory(payload_size, payload_alignment);

        // Allocate memory for aligned payload
        payload = malloc(payload_size);
        if (!payload) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        // Fill header and metadata with random data
        for (int j = 0; j < HEADER_SIZE; ++j) packet_list->packets[packet_list->count]->header[j] = rand() % 256;
        for (int j = 0; j < METADATA_SIZE; ++j) packet_list->packets[packet_list->count]->metadata[j] = rand() % 256;

        // Fill payload with random data
        for (size_t k = 0; k < payload_size; ++k) {
            payload[k] = rand() % 256;
        }

        // Create a new packet and assign it to the list
        Packet *packet = malloc(sizeof(Packet));
        if (!packet) {
            fprintf(stderr, "Memory allocation failed\n");
            free(payload);
            break;
        }
        packet->payload = payload;
        packet->payload_size = payload_size;

        // Resize the array if necessary
        if (packet_list->count == packet_list->capacity) {
            size_t new_capacity = packet_list->capacity * 2;
            Packet **new_packets = realloc(packet_list->packets, new_capacity * sizeof(Packet *));
            if (!new_packets) {
                fprintf(stderr, "Memory allocation failed\n");
                break;
            }
            packet_list->packets = new_packets;
            packet_list->capacity = new_capacity;
        }

        // Add the packet to the list
        packet_list->packets[packet_list->count++] = packet;
    }

    return packet_list;
}

// Free resources allocated by initialize_packet_list.
void free_packet_list(PacketList *packet_list) {
    if (!packet_list) return;

    for (size_t i = 0; i < packet_list->count; ++i) {
        Packet *packet = packet_list->packets[i];
        if (packet) {
            free(packet->payload);
            free(packet);
        }
    }

    free(packet_list->packets);
    free(packet_list);
}

int main() {
