        return -1;
    }
    memcpy(copy, transaction, sizeof(Transaction));

    array->transactions[array->size++] = copy;

    log_transaction(transaction); // Log the transaction

    pthread_mutex_unlock(&array->lock);

    return 0; // Success
}

// Remove a transaction by ID
int remove_transaction_by_id(TransactionArray *array, int transaction_id) {
    if (!array) return -1;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->transactions[i]->transaction_id == transaction_id) {
            free(array->transactions[i]);

            // Shift remaining transactions
            memmove(&array->transactions[i], &array->transactions[i + 1],
                    (array->size - i - 1) * sizeof(Transaction *));

            array->size--;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
