#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_SYSTEM_LIMIT 1000000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    uint32_t rolling_checksum;
    pthread_mutex_t lock;
} SynchronizationContext;

#define BATCH_SIZE 1000

SynchronizationContext* create_sync_context(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_SYSTEM_LIMIT) {
        return NULL;
    }

    SynchronizationContext *context = malloc(sizeof(SynchronizationContext));
    if (!context) {
        perror("Failed to allocate synchronization context");
        return NULL;
    }

    context->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!context->array) {
        free(context);
        perror("Failed to allocate array for synchronization context");
        return NULL;
    }

    context->count = 0;
    context->capacity = initial_capacity;
    context->rolling_checksum = 0;
    pthread_mutex_init(&context->lock, NULL);

    return context;
}

int add_pdu(SynchronizationContext *ctx) {
    if (!ctx || ctx->count >= MAX_SYSTEM_LIMIT) {
        return -1; // Error: invalid context or limit exceeded
    }

    if (ctx->capacity <= ctx->count) {
        size_t new_capacity = ctx->capacity + BATCH_SIZE;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(ctx->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            return -1; // Error: failed to reallocate
        }
        ctx->array = new_array;
        ctx->capacity = new_capacity;
    }

    pthread_mutex_lock(&ctx->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = &ctx->array[ctx->count++];
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    ctx->rolling_checksum ^= (uint32_t)pdu->CRC_INDICATION_REL8_TAG.CRCFLAG; // Simple XOR for checksum update

    pthread_mutex_unlock(&ctx->lock);

    return 0; // Success
}

void remove_pdu(SynchronizationContext *ctx, size_t index) {
    if (!ctx || index >= ctx->count) {
        return;
    }

    pthread_mutex_lock(&ctx->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = &ctx->array[index];
    ctx->rolling_checksum ^= (uint32_t)pdu->CRC_INDICATION_REL8_TAG.CRCFLAG; // Reverse checksum update

    memmove(&ctx->array[index], &ctx->array[index + 1],
            (ctx->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    ctx->count--;

    pthread_mutex_unlock(&ctx->lock);
}

void destroy_sync_context(SynchronizationContext *ctx) {
    if (!ctx) return;

    free(ctx->array);
    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
}
