NFAPI_CRC_INDICATION_PDU_T* manage_dynamic_array(int states[], int num_states, void* fsa, int last_state, int perf_threshold, size_t memory_budget) {
    if (memory_budget > MAX_MEMORY_BUDGET) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t array_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_states;

    if (array_size > memory_budget) {
        failure_count++;
        return NULL;
    }

    pthread_mutex_lock(&lock);
    clock_t start_time = clock();

    array = malloc(array_size);
    if (!array) {
        failure_count++;
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    log_allocation(array_size);

    for (int i = 0; i < num_states; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &array[i];
        entry->RX_UE_INFORMATION_TAG = states[i]; // Assuming valid RX_UE_INFORMATION_TAG
        entry->RNTI = states[i];

        if (entry->RNTI < 0 || entry->RNTI > 10000) { // Example range check for RNTI
            failure_count++;
            continue;
        }

        memset(entry->CRC_INDICATION_REL8_TAG, 0, sizeof(entry->CRC_INDICATION_REL8_TAG));

        int rnti_parity = entry->RNTI % 2;
        entry->CRC_INDICATION_REL8_TAG[0] = rnti_parity; // Set CRCFLAG based on RNTI parity

        allocation_count++;
    }

    clock_t end_time = clock();
    double time_spent = (double)(end_time - start_time) / CLOCKS_PER_SEC * 1000;

    if (time_spent > perf_threshold) {
        free(array);
        log_deallocation(array, array_size);
        failure_count++;
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pthread_mutex_unlock(&lock);

    return array;
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T *array, size_t num_states) {
    if (array) {
        size_t array_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_states;
        free(array);
        log_deallocation(array, array_size);
    }
}
