LogMessageList* create_log_message_list(size_t initial_capacity, int max_capacity) {
    LogMessageList *list = (LogMessageList *)malloc(sizeof(LogMessageList));
    list->messages = (LTE_ENB_LOG_MESSAGE **)calloc(initial_capacity, sizeof(LTE_ENB_LOG_MESSAGE *));
    list->count = 0;
