    for (size_t i = 0; i < list->count; ++i) {
        free(list->messages[i]->message);
        free(list->messages[i]);
    }
    free(list->messages);

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list->);
}

