    pthread_mutex_lock(&list->lock);

    while (list->count >= list->capacity) {
        if (list->max_capacity > 0 && list->count >= list->max_capacity) {
            pthread_cond_wait(&list->cond, &list->lock);
            continue;
        }
        size_t new_capacity = list->capacity * 2;
