        if (!new_messages) {
            pthread_mutex_unlock(&list->lock);
            list->failure_count++;
            return -1;
        }
        list->messages = new_messages;
        list->capacity = new_capacity;
    }

    LTE_ENB_LOG_MESSAGE *log_msg_copy = (LTE_ENB_LOG_MESSAGE *)malloc(sizeof(LTE_ENB_LOG_MESSAGE));
    if (!log_msg_copy) {
        pthread_mutex_unlock(&list->lock);
        list->failure_count++;
        return -1;
    }
    log_msg_copy->id = msg->id;
    size_t message_length = strlen(msg->message) + 1;
    log_msg_copy->message = (char *)malloc(message_length * sizeof(char));
    if (!log_msg_copy->message) {
        free(log_msg_copy);
        pthread_mutex_unlock(&list->lock);
        list->failure_count++;
        return -1;
    }
    strncpy(log_msg_copy->message, msg->message, message_length);

    list->messages[list->count++] = log_msg_copy;
    list->successful_allocations++;

    pthread_cond_broadcast(&list->cond);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void process_log_messages(LogMessageList *list) {
