    new_node->next = head;
    return new_node;
}

void insert_to_hash(HashTable* table, unsigned int rnti, NFAPI_CRC_INDICATION_PDU_T data) {
    size_t index = hash(rnti, table->size);
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    if (!new_node) return;

    new_node->data = data;
    pthread_mutex_lock(&table->lock);
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);
}

void flush_list(struct Node* head, HashTable* hash_table) {
    struct Node* current = head;
    while (current) {
        struct Node* next = current->next;
        unsigned int rnti = current->data.RNTI;
        size_t index = hash(rnti, hash_table->size);

        pthread_mutex_lock(&hash_table->lock);
        // Remove from hash table
        struct Node** bucket = &hash_table->buckets[index];
        while (*bucket) {
            if ((*bucket)->data.RNTI == rnti) {
                *bucket = (*bucket)->next;
                break;
            }
            bucket = &(*bucket)->next;
        }
        pthread_mutex_unlock(&hash_table->lock);

        free(current);
        current = next;
    }

    // Clear hash table
    for (size_t i = 0; i < hash_table->size; ++i) {
        pthread_mutex_lock(&hash_table->lock);
        struct Node* node = hash_table->buckets[i];
        while (node) {
            struct Node* temp = node;
            node = node->next;
            free(temp);
        }
        hash_table->buckets[i] = NULL;
        pthread_mutex_unlock(&hash_table->lock);
    }
}

struct Node* manage_nfa_list(size_t max_count, size_t batch_size) {
    if (max_count == 0 || batch_size == 0) return NULL;

    struct Node* head = NULL;
    HashTable* hash_table = create_hash_table(1024); // Example size
    if (!hash_table) return NULL;

    for (size_t i = 0; i < max_count; i += batch_size) {
        size_t current_batch_size = (i + batch_size > max_count) ? max_count - i : batch_size;

        struct Node* prev_head = head;
        for (size_t j = 0; j < current_batch_size; ++j) {
            NFAPI_CRC_INDICATION_PDU_T data;
            data.RX_UE_INFORMATION_TAG = rand(); // Simulate setting
