void log_pdu_validation(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("PDU Validated: RX_UE_INFORMATION_TAG=%d, RNTI=0x%X, CRCFLAG=%d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
}

int validate_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Example validation: Ensure RNTI is non-zero
    return pdu->RNTI != 0;
}

void add_pdu_to_list(List* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->size >= MAX_LIST_SIZE) {
        printf("List is full. Cannot add more PDUs.\n");
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return;
    }

    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;

    log_pdu_creation(pdu);
    log_pdu_validation(pdu);

    pthread_mutex_unlock(&list->lock);
}

void remove_pdu_from_list(List* list) {
    if (!list->head) {
        printf("List is empty. Cannot remove any PDUs.\n");
        return;
    }

    Node* temp = list->head;
    list->head = list->head->next;

    if (!list->head) {
        list->tail = NULL;
    }

    free(temp);
    list->size--;

    pthread_mutex_unlock(&list->lock);
}

void process_pdu_batch(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        // Simulate serialized downstream transmission
        printf("Transmitting PDU: RX_UE_INFORMATION_TAG=%d, RNTI=0x%X, CRCFLAG=%d\n",
               current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRCFLAG);

        Node* to_remove = current;
        current = current->next;
        free(to_remove);
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}

void* pdu_management_thread(void* arg) {
