        if (validate_pdu(&pdu)) {
            add_pdu_to_list(list, &pdu);
        } else {
            printf("PDU failed validation and was not added.\n");
        }

        // Simulate batch processing
        if (list->size >= MAX_LIST_SIZE / 2) {
            process_pdu_batch(list);
        }

        usleep(1000); // Control throughput
    }

    return NULL;
}

int main() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, pdu_management_thread, &list)) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

