        (*indicationList)[i].RX_UE_INFORMATION_TAG |= ((unsigned long long)timestamp << 48);
    }

    return 0;
}

// Validation function to ensure integrity of the list
int validateIndications(NFAPI_CRC_INDICATION_PDU_T *indicationList, int N) {
    if (indicationList == NULL || N <= 0) {
        fprintf(stderr, "Invalid input parameters for validation.\n");
        return -1;
    }

    unsigned int rntiCount[MAX_RNTI + 1] = {0}; // Track occurrences of RNTIs
    for (int i = 0; i < N; ++i) {
        if (indicationList[i].RNTI > MAX_RNTI) {
            fprintf(stderr, "RNTI exceeds maximum value at index %d.\n", i);
            return -1;
        }
        rntiCount[indicationList[i].RNTI]++;
    }

    for (int j = 0; j <= MAX_RNTI; ++j) {
        if (rntiCount[j] > 1) {
            fprintf(stderr, "Duplicate RNTI found: %u.\n", j);
            return -1;
        }
    }

