void pruneSessions(UeSessionData* sessions, int* totalSessions) {
    for (int i = 0; i < *totalSessions; ++i) {
        if (!sessions[i].isValid) {
            free(sessions[i].measurementReports);
            memmove(&sessions[i], &sessions[i + 1], sizeof(UeSessionData) * (*totalSessions - i - 1));
            --(*totalSessions);
            --i;
        }
    }
}

void initializeUeSessions(int numNewSessions, UeSessionData** sessions, int* totalSessions) {
    if (numNewSessions <= 0 || !sessions || !totalSessions) return;

    // Resize the array if needed
    *sessions = realloc(*sessions, (*totalSessions + numNewSessions) * sizeof(UeSessionData));
    if (!*sessions) {
        perror("Failed to allocate memory for sessions");
        exit(EXIT_FAILURE);
