};

typedef struct {
    struct Node* head;
    pthread_mutex_t lock;
    size_t count;
} LinkedList;

// Function prototypes
LinkedList* create_list();
int append_entry(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* entry);
void log_creation(const char* message);
void free_list(LinkedList* list);
size_t get_total_entries(const LinkedList* list);
