        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

// Append a new entry to the linked list
int append_entry(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!entry) {
        log_creation("Invalid entry: Entry is NULL");
        return -1;
    }

    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    if (!new_node) {
        perror("Failed to allocate memory for a new node");
        return -2;
    }

    // Populate the new node
    memcpy(&new_node->data, entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    log_creation("Node created and added to the list");
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Log creation messages
void log_creation(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Free the linked list
void free_list(LinkedList* list) {
    struct Node* current = list->head;
    while (current) {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Get total number of entries in the linked list
