    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return count;
}

// Calculate the sum of all CRCINDICATIONREL8TAG values
uint32_t get_sum_of_crc_tags(const LinkedList* list) {
    uint32_t sum = 0;
    struct Node* current = list->head;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    while (current) {
        if ((current->data.CRCINDICATIONREL8TAG > 0) && 
            (current->data.RNTI != 0)) { // Validate RNTI
            sum += current->data.CRCINDICATIONREL8TAG;
        }
        current = current->next;
    }
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);

    return sum;
}

// Serialize the list to a file
void serialize_to_file(const LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    struct Node* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);

    fclose(file);
}

// Deserialize the list from a file
int deserialize_from_file(LinkedList** list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return -1;
    }

    free_list(*list);
    *list = create_list();

    NFAPI_CRC_INDICATION_PDU_T entry;
    while (fread(&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        append_entry(*list, &entry);
    }

    fclose(file);
    return 0;
}

// Monitor performance of list operations
void monitor_performance(void (*operation)(LinkedList*, void*), LinkedList* list, void* arg) {
    clock_t start = clock();
    operation(list, arg);
    clock_t end = clock();

    double time_taken_ms = ((double)(end - start)) * 1000.0 / CLOCKS_PER_SEC;
    if (time_taken_ms > MAX_LATENCY_MS) {
        fprintf(stderr, "Operation exceeded latency threshold: %f ms\n", time_taken_ms);
    }
}

// Periodic update from external data source
void periodic_update(LinkedList* list) {
