['Below is a C implementation for managing a list of `NFAPI_CRC_INDICATION_PDU_T` structures, considering the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 16383 // Example range for RNTI values

typedef struct {
    int valid;
    char rnti[MAX_RNTI];
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned short crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfoTag;
    unsigned long rnti;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int validate_rnti(unsigned long rnti) {
    return rnti > 0 && rnti < MAX_RNTI;
}

int is_unique_rnti(List* list, unsigned long rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.rnti == rnti) {
            return 0; // Not unique
        }
        current = current->next;
    }
    return 1; // Unique
}

int add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!validate_rnti(pdu.rnti)) {
        fprintf(stderr, "Invalid RNTI value: %lu\n", pdu.rnti);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (!is_unique_rnti(list, pdu.rnti)) {
        fprintf(stderr, "Duplicate RNTI value: %lu\n", pdu.rnti);
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void generate_random_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->crcTag.crcFlag = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

size_t get_entry_count(List* list) {
    pthread_mutex_lock(&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

void iterate_list(const List* list, void (*process)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = list->head;
    while (current) {
        process(&current->data);
        current = current->next;
    }
}

void print_pdu_info(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RNTI: %lu, CRCFLAG: %u\n", pdu->rnti, pdu->crcTag.crcFlag);
}

int main() {
    List* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return -1;
    }

    for (unsigned long i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .ueInfoTag = {.valid = 1}, .rnti = rand() % MAX_RNTI };
        generate_random_crc(&pdu);

        int result = add_pdu(list, pdu);
        if (result != 0) {
            fprintf(stderr, "Failed to add PDU with RNTI: %lu\n", pdu.rnti);
        }
    }

    printf("Total entries: %zu\n", get_entry_count(list));
    iterate_list(list, print_pdu_info);

    free_list(list);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Error Handling**: Logs errors for invalid RNTI values and memory allocation failures.
- **Efficiency**: Uses a linked list for dynamic management, allowing efficient iteration and insertion.
- **Random CRC Generation**: Randomly sets the `crcFlag` for each PDU.
- **Scalability**: Designed to handle large numbers of entries with minimal performance degradation.
- **Resource Management**: Frees allocated memory properly to avoid leaks.']

