#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 5000
#define STORAGE_FILE "nfa_crc_data.bin"
#define CHECKSUM_SIZE sizeof(uint32_t)

typedef struct {
    // Define the structure fields here
    int example_field;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
} NFALIST_T;

uint32_t calculate_checksum(void *data, size_t size);
void log_error(const char* message);

NFALIST_T* create_list() {
    NFALIST_T *list = (NFALIST_T *)malloc(sizeof(NFALIST_T));
    if (!list) return NULL;

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        list->elements[i] = NULL;
    }
    return list;
}

void destroy_list(NFALIST_T *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_element(NFALIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (!list || !element) return;

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS) {
        log_error("List is full. Dropping new element.");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->lock);

    // Optionally serialize to storage after adding
    serialize_list_to_storage(list);
}

NFAPI_CRC_INDICATION_PDU_T* remove_element(NFALIST_T *list, size_t index) {
    if (!list || index >= list->count) return NULL;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *element = list->elements[index];
    memmove(&list->elements[index], &list->elements[index + 1],
            (list->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    --list->count;

    pthread_mutex_unlock(&list->lock);

    // Optionally serialize to storage after removing
    serialize_list_to_storage(list);

    return element;
}

int serialize_list_to_storage(NFALIST_T *list) {
    if (!list) return -1;

    FILE *file = fopen(STORAGE_FILE, "wb");
    if (!file) return -1;

    uint32_t checksum = 0;
    size_t data_size = list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    fwrite(&list->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < list->count; ++i) {
        if (!list->elements[i]) continue;
        fwrite(list->elements[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);

        checksum ^= calculate_checksum(list->elements[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    fwrite(&checksum, CHECKSUM_SIZE, 1, file);

    fclose(file);
    return 0;
}

int deserialize_list_from_storage(NFALIST_T *list) {
    if (!list) return -1;

    FILE *file = fopen(STORAGE_FILE, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > MAX_ELEMENTS) {
        log_error("Deserialized list exceeds maximum allowed elements.");
        fclose(file);
        return -1;
    }

    uint32_t checksum = 0, stored_checksum;

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!element) {
            log_error("Memory allocation failed during deserialization.");
            fclose(file);
            return -1;
        }

        fread(element, sizeof(NFAPI_CRC_INDIGATION_PDU_T), 1, file);

        list->elements[i] = element;
        checksum ^= calculate_checksum(element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    fread(&stored_checksum, CHECKSUM_SIZE, 1, file);

    if (checksum != stored_checksum) {
        log_error("Checksum mismatch. Data may be corrupted.");
        fclose(file);
        return -1;
    }

    list->count = count;
    fclose(file);
    return 0;
}

uint32_t calculate_checksum(void *data, size_t size) {
    uint8_t *bytes = (uint8_t *)data;
    uint32_t checksum = 0;

    for (size_t i = 0; i < size; ++i) {
        checksum ^= bytes[i];
    }

    return checksum;
}

void log_error(const char* message) {
    // Implement error logging
    fprintf(stderr, "Error: %s\n", message);
}
