int validateList(NFAPI_CRC_INDICATION_PDU_T* list, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (list[i].ueInfoTag.rnti <= 0 || 
            list[i].rnti < 1 ||
            list[i].crcIndicationRel8Tag.crcFlag > 1) {
            return -1;
        }
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* generateNFAPICRCList(int N, Config_T* config) {
    if (config == NULL || N <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize the list in parallel
    void* threadFunc(void* arg) {
        int start = *(int*)arg;
        for (int i = start; i < N; i += NUM_THREADS) {
            list[i].ueInfoTag.rnti = 1; // Example placeholder value
            list[i].rnti = rand() % (config->maxRNTI - config->minRNTI + 1) + config->minRNTI;
            double randomValue = ((double)rand()) / RAND_MAX;
            list[i].crcIndicationRel8Tag.crcFlag = (randomValue < config->crcFlagProbability) ? 1 : 0;
        }
        return NULL;
    }

    pthread_t threads[NUM_THREADS];
    int threadStartIndices[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        threadStartIndices[i] = i;
        if (pthread_create(&threads[i], NULL, threadFunc, &threadStartIndices[i])) {
            fprintf(stderr, "Error creating thread.\n");
            free(list);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    int validationStatus = validateList(list, N);
    if (validationStatus != 0) {
        fprintf(stderr, "Validation failed.\n");
        free(list);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pthread_mutex_unlock(&lock);

    // Placeholder for logging
    printf("NFAPI_CRC_INDICATION_PDU_T list generated successfully with %d elements.\n", N);

    return list;
}

void freeNFAPICRCList(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list != NULL) {
        free(list);
    }
}
