    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_structure_array(NFAPI_CRC_INDICATION_PDU_T *structures, int size) {
    if (!structures || size <= 0 || size > MAX_STRUCTURES) return -1;

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
