uint8_t custom_checksum(uint32_t info, uint16_t rnti) {
    return (info ^ rnti) & 0xFF; // Example checksum logic
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
} DynamicList;

int resize_dynamic_list(DynamicList *list, size_t new_size) {
    if (new_size > MAX_STRUCTURES) return -1;

    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return -1; // Memory allocation failure

    list->data = temp;
    memset((char *)list->data + list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T), 0, (new_size - list->size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = new_size;

    return 0;
}

int add_structure(DynamicList *list, uint32_t rx_ue_info_tag, uint16_t rnti) {
    if (!list || list->size == MAX_STRUCTURES) return -1; // List is full or invalid

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].ue_info.RNTI == rnti) return -2; // RNTI already exists
    }

    size_t new_size = list->size + 1;

    if (new_size > list->size && resize_dynamic_list(list, new_size) != 0) {
        return -3; // Resize failed
    }

    NFAPI_CRC_INDICATION_PDU_T *new_entry = &list->data[list->size - 1];
    new_entry->ue_info.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_entry->ue_info.RNTI = rnti;
    new_entry->crc_tag.CRC_FLAG = custom_checksum(rx_ue_info_tag, rnti);

    return 0; // Success
}

size_t get_current_size(const DynamicList *list) {
    if (!list) return (size_t)-1;
    return list->size;
}

void free_dynamic_list(DynamicList *list) {
    if (list && list->data) {
        free(list->data);
        list->data = NULL;
        list->size = 0;
    }
}

// Usage example:
