#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define HASH_TABLE_SIZE 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} UE_IDENTIFIER;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    time_t timestamp;
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
} ListNode;

// Hash function for uniqueness check
unsigned int hash_function(unsigned int rx_ue, unsigned int rnti) {
    return (rx_ue ^ rnti) % HASH_TABLE_SIZE;
}

// Custom logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

typedef struct {
    UE_IDENTIFIER key;
    ListNode *node;
} HashTableEntry;

typedef struct {
    HashTableEntry table[HASH_TABLE_SIZE];
    int count;
} HashTable;

HashTable* create_hash_table() {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        ht->table[i].key.RX_UE_INFORMATION_TAG = 0;
        ht->table[i].key.RNTI = 0;
        ht->table[i].node = NULL;
    }
    ht->count = 0;
    return ht;
}

void free_hash_table(HashTable *ht) {
    if (!ht) return;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        ListNode *current = ht->table[i].node;
        while (current) {
            ListNode *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(ht);
}

int insert_crc_indication(HashTable *ht, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!ht) return -1;

    unsigned int hash_idx = hash_function(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);

    // Check for uniqueness
    UE_IDENTIFIER key = {pdu.RX_UE_INFORMATION_TAG, pdu.RNTI};
    HashTableEntry *entry = &ht->table[hash_idx];

    if (entry->key.RX_UE_INFORMATION_TAG == key.RX_UE_INFORMATION_TAG &&
        entry->key.RNTI == key.RNTI) {
        log_message("Duplicate entry. Insertion failed.");
        return -2;
    }

    // Allocate memory for new node
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) {
        log_message("Memory allocation failure.");
        return -1;
    }

    new_node->data = pdu;
    new_node->next = entry->node;
    entry->node = new_node;

    // Update hash table key
    entry->key.RX_UE_INFORMATION_TAG = key.RX_UE_INFORMATION_TAG;
    entry->key.RNTI = key.RNTI;

    ht->count++;
    log_message("Insertion successful.");
    return 0;
}

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return;

    pdu->timestamp = time(NULL);
    pdu->RX_UE_INFORMATION_TAG = rand() % 10000; // Example random generation
    pdu->RNTI = rand() % 10000;
    pdu->crc_indication_rel8_tag.CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1
}

void test_crc_insertion() {
    HashTable *ht = create_hash_table();
    if (!ht) {
        log_message("Failed to initialize hash table.");
        return;
    }

    for (int i = 0; i < 10000; ++i) { // Test with up to 10,000 entries
        NFAPI_CRC_INDICATION_PDU_T pdu;
        initialize_pdu(&pdu);
        int result = insert_crc_indication(ht, pdu);

        if (result == -1 || result == -2) {
            break; // Stop on memory allocation failure or duplicate entry
        }
    }

    log_message("Test completed.");
    free_hash_table(ht);
}

int main() {
    srand(time(NULL));
    test_crc_insertion();
    return 0;
}
```

This code manages a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures, ensures uniqueness using a hash table, and includes robust error handling for memory allocation failures. The function is designed to handle up to 10,000 entries efficiently, with considerations for high-throughput operations.']

