#define INITIAL_CAPACITY 10

typedef struct {
    int protocol_type;
    size_t payload_size;
    void *payload_data;
} LTE_RRC_MSG;

typedef struct {
    int UE_ID;
    LTE_RRC_MSG **messages;
    size_t message_count;
    size_t capacity;
} LTE_RRC_UE_CONTEXT;

typedef struct {
    LTE_RRC_UE_CONTEXT **contexts;
    size_t context_count;
    size_t capacity;
    pthread_mutex_t lock;  // To handle concurrent access
} LTE_RRC_Context_Manager;

// Function prototypes
LTE_RRC_Context_Manager* initialize_context_manager();
void cleanup_context_manager(LTE_RRC_Context_Manager *manager);
int add_ue_context(LTE_RRC_Context_Manager *manager, int UE_ID);
int add_message_to_ue_context(LTE_RRC_Context_Manager *manager, int UE_ID, LTE_RRC_MSG *message);
void validate_integrity(LTE_RRC_Context_Manager *manager);

LTE_RRC_Context_Manager* initialize_context_manager() {
    LTE_RRC_Context_Manager *manager = (LTE_RRC_Context_Manager*)malloc(sizeof(LTE_RRC_Context_Manager));
    if (!manager) return NULL;

    manager->contexts = (LTE_RRC_UE_CONTEXT**)calloc(INITIAL_CAPACITY, sizeof(LTE_RRC_UE_CONTEXT*));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }

    manager->context_count = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void cleanup_context_manager(LTE_RRC_Context_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->context_count; ++i) {
        LTE_RRC_UE_CONTEXT *ue_context = manager->contexts[i];
        for (size_t j = 0; j < ue_context->message_count; ++j) {
            free(ue_context->messages[j]->payload_data);
            free(ue_context->messages[j]);
        }
        free(ue_context->messages);
        free(ue_context);
    }

    free(manager->contexts);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_ue_context(LTE_RRC_Context_Manager *manager, int UE_ID) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    // Resize the context array if necessary
    if (manager->context_count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_RRC_UE_CONTEXT **new_contexts = (LTE_RRC_UE_CONTEXT**)realloc(manager->contexts, new_capacity * sizeof(LTE_RRC_UE_CONTEXT*));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    // Add a new UE context
    LTE_RRC_UE_CONTEXT *ue_context = (LTE_RRC_UE_CONTEXT*)malloc(sizeof(LTE_RRC_UE_CONTEXT));
    if (!ue_context) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    ue_context->UE_ID = UE_ID;
    ue_context->messages = NULL;
    ue_context->message_count = 0;
    ue_context->capacity = 0;

    manager->contexts[manager->context_count++] = ue_context;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_message_to_ue_context(LTE_RRC_Context_Manager *manager, int UE_ID, LTE_RRC_MSG *message) {
    if (!manager || !message) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->context_count; ++i) {
        LTE_RRC_UE_CONTEXT *ue_context = manager->contexts[i];
        if (ue_context->UE_ID == UE_ID) {
            // Resize the messages array if necessary
            if (ue_context->message_count == ue_context->capacity) {
                size_t new_capacity = ue_context->capacity ? ue_context->capacity * 2 : 1;
                LTE_RRC_MSG **new_messages = (LTE_RRC_MSG**)realloc(ue_context->messages, new_capacity * sizeof(LTE_RRC_MSG*));
                if (!new_messages) {
                    pthread_mutex_unlock(&manager->lock);
                    return -1;
                }
                ue_context->messages = new_messages;
                ue_context->capacity = new_capacity;
            }

            // Duplicate and assign message
            LTE_RRC_MSG *new_message = (LTE_RRC_MSG*)malloc(sizeof(LTE_RRC_MSG));
            if (!new_message) {
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }

            new_message->protocol_type = message->protocol_type;
            new_message->payload_size = message->payload_size;

            // Allocate and copy payload data
            void *data_copy = malloc(message->payload_size);
            if (!data_copy) {
                free(new_message);
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }
            memcpy(data_copy, message->payload_data, message->payload_size);
            new_message->payload_data = data_copy;

            ue_context->messages[ue_context->message_count++] = new_message;

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // UE_ID not found
}

void validate_integrity(LTE_RRC_Context_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->context_count; ++i) {
        LTE_RRC_UE_CONTEXT *ue_context = manager->contexts[i];

        // Validate UE context
        if (!ue_context || ue_context->UE_ID < 0) continue;

        // Validate messages within the UE context
        for (size_t j = 0; j < ue_context->message_count; ++j) {
            LTE_RRC_MSG *msg = ue_context->messages[j];

            if (!msg || msg->payload_size > MAX_PAYLOAD_SIZE || !msg->payload_data) {
                fprintf(stderr, "Data integrity issue detected at UE_ID %d, message index %zu\n", 
                        ue_context->UE_ID, j);
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
