    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        int resize_status = resize_array(array, new_capacity);
        if (resize_status != 0) {
            pthread_mutex_unlock(&array->lock);
            LOG_ERROR("Failed to resize array");
            return -1;
        }
    }

    array->frames[array->count++] = frame;

    pthread_mutex_unlock(&array->lock);

    LOG_INFO("Frame added, total count: %zu", array->count);

    return 0;
}

// Free dynamic array
void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    pthread_mutex_destroy(&array->lock);
    free(array->frames);
    free(array);

    LOG_INFO("DynamicArray freed");
}

// Function to process frames (example)
void process_frames(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        // Process each frame
        // Example: Log processing
        LOG_INFO("Processing frame %zu", i);
    }
}

// Main function to demonstrate usage
int main() {
    DynamicArray *array = init_dynamic_array(10);

    if (!array) return 1;

    LTE_PHY_RX_FRAME frame;
    for (size_t i = 0; i < 25; ++i) { // Simulate adding more frames than initial capacity
        add_frame(array, frame);
    }

    process_frames(array);

    free_dynamic_array(array);

    return 0;
}
