#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

#define MAX_RNTI 65535

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef uint16_t RX_UE_INFORMATION_TAG;
typedef uint16_t RNTI;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int used[MAX_RNTI + 1];
    pthread_mutex_t lock;
} RntiHashTable;

RntiHashTable rnti_hash_table = {.lock = PTHREAD_MUTEX_INITIALIZER};

int is_rnti_used(RNTI rnti) {
    pthread_mutex_lock(&rnti_hash_table.lock);
    int result = rnti_hash_table.used[rnti];
    pthread_mutex_unlock(&rnti_hash_table.lock);
    return result;
}

void mark_rnti_as_used(RNTI rnti) {
    pthread_mutex_lock(&rnti_hash_table.lock);
    rnti_hash_table.used[rnti] = 1;
    pthread_mutex_unlock(&rnti_hash_table.lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_doubly_linked_list(size_t count) {
    if (count == 0) return NULL;

    // Initialize RNTI hash table
    memset(rnti_hash_table.used, 0, sizeof(rnti_hash_table.used));

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    for (size_t i = 0; i < count; ++i) {
        // Generate unique RNTI
        RNTI rnti;
        int valid_rnti = 0;
        while (!valid_rnti) {
            rnti = rand() % (MAX_RNTI + 1);
            if (!is_rnti_used(rnti)) {
                mark_rnti_as_used(rnti);
                valid_rnti = 1;
            }
        }

        // Allocate new node
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            perror("Failed to allocate memory");
            break; // Handle memory allocation failure appropriately
        }

        // Populate the structure with random values
        new_node->rx_ue_information_tag = rand();
        new_node->rnti = rnti;
        new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2;

        new_node->prev = tail;
        new_node->next = NULL;

        // Link the new node into the list
        if (tail) {
            tail->next = new_node;
        } else {
            head = new_node; // First element
        }
        tail = new_node;
    }

    return head;
}

void free_doubly_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    const size_t list_size = 50000; // Example size
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* head = create_doubly_linked_list(list_size);

    if (head) {
        // List created successfully, use it as needed

        free_doubly_linked_list(head);
    }

    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex is used to synchronize access to the RNTI hash table.
- **RNTI Uniqueness**: The `is_rnti_used` and `mark_rnti_as_used` functions ensure that each `RNTI` is unique across all operations.
- **Performance**: Using a fixed-size array for RNTI tracking provides O(1) complexity for lookups and insertions, optimizing performance under concurrency.
- **Scalability**: The function handles up to 50,000 elements efficiently and can be extended with additional fields by modifying the `NFAPI_CRC_INDICATION_PDU_T` structure.
- **Memory Management**: Proper memory allocation and deallocation are handled to avoid leaks.']

