    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int max_size;
    unsigned long pdus_added;
    unsigned long pdus_removed;
    time_t last_time_check;
    float rolling_avg_add;
    float rolling_avg_remove;
} PDUList;

// Function prototypes
void initialize_list(PDUList* list);
int add_pdu(PDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T remove_pdu(PDUList* list);
void log_pdu_creation(NFAPI_CRC_INDICATION_PDU_T pdu);
void log_pdu_validation(NFAPI_CRC_INDICATION_PDU_T pdu);
void adjust_max_size(PDUList* list);

// Initialize the PDU List
void initialize_list(PDUList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size = INITIAL_MAX_SIZE;
    list->pdus_added = 0;
    list->pdus_removed = 0;
    list->last_time_check = time(NULL);
    list->rolling_avg_add = 0.0f;
    list->rolling_avg_remove = 0.0f;
}

// Add a PDU to the list
int add_pdu(PDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    // Log PDU creation
    log_pdu_creation(pdu);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed for PDU\n");
        return -1;
    }

    memcpy(&(new_node->pdu), &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;

    // Update rolling average and count
    unsigned long current_time = time(NULL);
    if (current_time - list->last_time_check >= 1) {
        float elapsed_seconds = difftime(current_time, list->last_time_check);
        list->rolling_avg_add = ((list->rolling_avg_add * list->pdus_added) + 1) / (list->pdus_added + 1) / elapsed_seconds;
        list->rolling_avg_remove = ((list->rolling_avg_remove * list->pdus_removed) + 0) / (list->pdus_removed + 1) / elapsed_seconds;
        list->last_time_check = current_time;
    }
    list->pdus_added++;

    // Adjust max size based on system load
    adjust_max_size(list);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove a PDU from the list (FIFO)
NFAPI_CRC_INDICATION_PDU_T remove_pdu(PDUList* list) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Attempted to remove PDU from an empty list\n");
        return (NFAPI_CRC_INDICATION_PDU_T){0};
    }

    Node* temp = list->head;
    NFAPI_CRC_INDICATION_PDU_T pdu = temp->pdu;

    // Log PDU validation
    log_pdu_validation(pdu);

    list->head = list->head->next;
    free(temp);

    // Update rolling average and count
    unsigned long current_time = time(NULL);
    if (current_time - list->last_time_check >= 1) {
        float elapsed_seconds = difftime(current_time, list->last_time_check);
        list->rolling_avg_remove = ((list->rolling_avg_remove * list->pdus_removed) + 1) / (list->pdus_removed + 1) / elapsed_seconds;
        list->last_time_check = current_time;
    }
    list->pdus_removed++;

    pthread_mutex_unlock(&list->lock);
    return pdu;
}

// Log PDU creation
