}

// Log PDU validation
void log_pdu_validation(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("PDU Validated for Removal: RX_UE_INFORMATION_TAG=%d, RNTI=0x%08X\n", pdu.valid_RX_UE_INFORMATION_TAG, pdu.RNTI);
}

// Adjust the maximum list size dynamically
void adjust_max_size(PDUList* list) {
    // Simplified logic for dynamic adjustment
    if (list->pdus_added > 2 * list->max_size || list->pdus_removed < list->max_size / 4) {
        list->max_size = (list->max_size * 3) / 2; // Increase size
    } else if (list->pdus_removed > list->max_size) {
        list->max_size = list->max_size / 2; // Decrease size
    }
}

int main() {
    PDUList pdu_list;
    initialize_list(&pdu_list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T example_pdu = {1, 12345, {0}};
    add_pdu(&pdu_list, example_pdu);
    remove_pdu(&pdu_list);

    return 0;
}
```

