```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_MAX_SIZE 1000
#define LOG_BUFFER_SIZE 1024

typedef struct {
    int ue_id;
    int serving_cell_id;
    int rlf_count;
} RLF_Event;

typedef struct {
    int ue_id;
    int serving_cell_id;
    RLF_Event *rlf_events;
    size_t rlf_event_count;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    time_t last_log_time;
    char log_buffer[LOG_BUFFER_SIZE];
} UE_Context_List;

void initialize_context_list(UE_Context_List *list, size_t initial_capacity) {
    list->contexts = malloc(initial_capacity * sizeof(LTE_UE_Context));
    if (!list->contexts) {
        perror("Failed to allocate memory for context list");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    time(&(list->last_log_time));
}

void log_context_event(const char *event) {
    time_t current_time;
    time(&current_time);
    if (difftime(current_time, list.last_log_time) >= 1.0) {
        snprintf(list.log_buffer, LOG_BUFFER_SIZE, "%s", event);
        printf("%s\n", list.log_buffer);
        list.last_log_time = current_time;
    }
}

void add_ue_context(UE_Context_List *list, LTE_UE_Context context) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_UE_Context *new_contexts = realloc(list->contexts, new_capacity * sizeof(LTE_UE_Context));
        if (!new_contexts) {
            log_context_event("Memory allocation failed while resizing context list");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }

    list->contexts[list->count++] = context;
    snprintf(list.log_buffer, LOG_BUFFER_SIZE, "Added UE Context: UE-ID %d", context.ue_id);
    log_context_event(list.log_buffer);

    pthread_mutex_unlock(&list->lock);
}

void remove_ue_context(UE_Context_List *list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i].ue_id == ue_id) {
            snprintf(list.log_buffer, LOG_BUFFER_SIZE, "Removed UE Context: UE-ID %d", ue_id);
            log_context_event(list.log_buffer);

            memmove(&list->contexts[i], &list->contexts[i + 1], (list->count - i - 1) * sizeof(LTE_UE_Context));
            list->count--;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void adjust_max_list_size(UE_Context_List *list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);

    if (new_capacity > list->capacity) {
        LTE_UE_Context *new_contexts = realloc(list->contexts, new_capacity * sizeof(LTE_UE_Context));
        if (!new_contexts) {
            log_context_event("Memory allocation failed while adjusting context list size");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_context_list(UE_Context_List *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->contexts[i].rlf_events);
    }
    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

int main() {
    UE_Context_List context_list;
    initialize_context_list(&context_list, INITIAL_MAX_SIZE);

    // Example usage
    LTE_UE_Context new_context = {1, 100, NULL, 0};
    add_ue_context(&context_list, new_context);
    remove_ue_context(&context_list, 1);

    adjust_max_list_size(&context_list, 2000);

    free_context_list(&context_list);
    return 0;
}
```

This code provides a basic framework for managing LTE UE Contexts with considerations for thread safety, logging, and dynamic resizing. It uses a mutex to ensure safe concurrent access and logs events periodically. Memory management is handled carefully to avoid leaks, and the system can dynamically adjust its capacity based on load.']

