#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    unsigned int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe list management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} NFALIST_T;

void init_nfa_list(NFALIST_T *list, size_t initial_capacity) {
    pthread_mutex_init(&list->mutex, NULL);
    list->capacity = initial_capacity;
    list->count = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
}

void destroy_nfa_list(NFALIST_T *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->count = 0;
}

int add_pdu(NFALIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->count++] = pdu;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0xFF; // Random CRCFLAG
    return pdu;
}

void serialize_nfa_list(NFALIST_T *list, const char *file_path, const char *format) {
    pthread_mutex_lock(&list->mutex);

    FILE *fp = fopen(file_path, format == "json" ? "w" : "wb");
    if (!fp) {
        perror("Failed to open file");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (strcmp(format, "json") == 0) {
        fprintf(fp, "[\n");
        for (size_t i = 0; i < list->count; ++i) {
            fprintf(fp, "  {\"RX_UE_INFORMATION_TAG\": %u, \"RNTI\": %u, \"CRCFLAG\": %u}%s\n",
                    list->data[i].RX_UE_INFORMATION_TAG,
