```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RNTI;
    // Add other fields as necessary
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    // Add other fields as necessary
} CRC_INDICATION_REL8;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    int rnti;
    CRC_INDICATION_REL8 crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool add_pdu_safe(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* current = list->tail;

    while (current && current != NULL) {
        if (current->data.rnti == pdu.rnti) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    new_node->data = pdu;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return true;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int rnti, int crc_tag) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.ue_info.RNTI = rnti;
    pdu.rnti = rnti;
    pdu.crc_info.CRC_INDICATION_REL8_TAG = crc_tag;
    pdu.crc_info.CRCFLAG = rand() % 2 == 0; // Randomly set CRCFLAG
    return pdu;
}

void update_list_from_source(List* list, int num_items) {
    for (int i = 0; i < num_items; ++i) {
        int rnti = rand() % 10000; // Simulated real-time RNTI update
        int crc_tag = rand() % 100;
        NFAPI_CRC_INDICATION_PDU_T pdu = create_pdu(rnti, crc_tag);
        add_pdu_safe(list, pdu);
    }
}

int main() {
    srand(time(NULL));
    List* list = create_list();

    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    update_list_from_source(list, 100);

    // Simulate concurrent updates
    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, (void*)update_list_from_source, (void*)list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_list(list);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on the list.
- **No Consecutive Same RNTI**: Validates that no two consecutive elements have the same RNTI before adding a new element.
- **Dynamic List Management**: Efficiently manages memory with minimal allocations and handles dynamic updates.
- **Concurrency Support**: Demonstrates handling concurrent updates to the list using multiple threads. 

This code ensures stability under high load conditions, adheres to performance constraints, and supports scalability by dynamically managing resources.']

