    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
} CRCList;

CRCList* create_crc_list(size_t initial_capacity) {
    CRCList *list = malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    return list;
}

void destroy_crc_list(CRCList *list) {
    if (list) {
        pthread_mutex_lock(&list_mutex);
        free(list->data);
        pthread_mutex_unlock(&list_mutex);

        free(list);
    }
}

int add_to_crc_list(CRCList *list, const NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list_mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list_mutex);
            return -1; // Memory allocation failure
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    memcpy(&list->data[list->count], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count++;

    pthread_mutex_unlock(&list_mutex);
    return 0; // Success
}

void log_message(const char *message) {
    static FILE *log_file = NULL;
    static time_t last_rotation_time = 0;

    if (!log_file || (time(NULL) - last_rotation_time > 86400)) {
        char filename[256];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        snprintf(filename, sizeof(filename), "logs/crc_log_%04d%02d%02d.log",
                 tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday);

        if (log_file) fclose(log_file);

        log_file = fopen(filename, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", filename);
            return;
        }

        last_rotation_time = now;

        // Rotate old logs
        for (int i = 6; i > 0; --i) {
            char src[256], dest[256];
            snprintf(src, sizeof(src), "logs/crc_log_%04d%02d%02d.log", tm_info->tm_year + 1900,
                     tm_info->tm_mon + 1 - (i-1 < i ? i : 30), tm_info->tm_mday - (i > 1 ? 7 * (i - 1) : 0));
            snprintf(dest, sizeof(dest), "logs/crc_log_%04d%02d%02d.log", tm_info->tm_year + 1900,
                     tm_info->tm_mon + 1 - i, tm_info->tm_mday - (7 * i));

            if (rename(src, dest) != 0 && errno != ENOENT) {
                perror("Log rotation failed");
            }
        }
    }

    fprintf(log_file, "%s\n", message);
}

void serialize_crc_list(CRCList *list, const char *filename, int binary_format) {
    pthread_mutex_lock(&list_mutex);

    FILE *file = fopen(filename, binary_format ? "wb" : "w");
    if (!file) {
        log_message("Failed to open file for serialization.");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    if (binary_format) {
        fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    } else {
        struct json_object *jlist = json_array_new();
        for (size_t i = 0; i < list->count; ++i) {
            // Assuming functions to convert structure fields to JSON values
            struct json_object *jitem = json_object_new_object();
            json_object_object_add(jitem, "ue_info", json_from_ue_info(list->data[i].ue_info));
            json_object_object_add(jitem, "rnti", json_from_rnti(list->data[i].rnti));
            json_object_object_add(jitem, "crc_tag", json_from_crc_tag(list->data[i].crc_tag));
            json_array_put(jlist, jitem);
        }
        const char *json_str = json_object_to_json_string_ext(jlist, JSON_C_TO_STRING_PLAIN);
        fprintf(file, "%s\n", json_str);
        json_object_put(jlist);  // Free JSON object
    }

    fclose(file);
    pthread_mutex_unlock(&list_mutex);
}

void deserialize_crc_list(CRCList *list, const char *filename, int binary_format) {
    pthread_mutex_lock(&list_mutex);

    FILE *file = fopen(filename, binary_format ? "rb" : "r");
    if (!file) {
        log_message("Failed to open file for deserialization.");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    size_t read_count;
    if (binary_format) {
        read_count = fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->capacity, file);
        list->count = read_count;
    } else {
        struct json_object *jlist;
        char buffer[4096];

        size_t len = fread(buffer, 1, sizeof(buffer) - 1, file);
        if (len == 0 || ferror(file)) {
            log_message("Failed to read JSON data.");
            fclose(file);
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        buffer[len] = '\0';
        jlist = json_tokener_parse(buffer);

        int array_length = json_object_array_length(jlist);
        if (array_length > list->capacity) {
            log_message("Exceeds initial capacity, resizing required.");
            // Resize logic here
        }

        for (int i = 0; i < array_length && i < list->count; ++i) {
            struct json_object *jitem = json_object_array_get_idx(jlist, i);
            // Assuming functions to convert JSON values to structure fields
            NFAPI_CRC_INDICATION_PDU_T item;
            json_to_ue_info(json_object_object_get(jitem, "ue_info"), &item.ue_info);
            json_to_rnti(json_object_object_get(jitem, "rnti"), &item.rnti);
            json_to_crc_tag(json_object_object_get(jitem, "crc_tag"), &item.crc_tag);

            memcpy(&list->data[i], &item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        list->count = array_length;
        json_object_put(jlist);  // Free JSON object
    }

    fclose(file);
    pthread_mutex_unlock(&list_mutex);
}

void paginate_crc_list(CRCList *list, size_t page_num) {
    pthread_mutex_lock(&list_mutex);

    if (page_num * PAGE_SIZE >= list->count) {
        log_message("Page number out of bounds.");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    for (size_t i = 0; i < PAGE_SIZE && page_num * PAGE_SIZE + i < list->count; ++i) {
