    if (list->monitoringEnabled) {
        pthread_create(&list->monitorThread, NULL, monitorMemoryUsage, list);
    }
}

// Add a new PDU to the priority queue
void addPDU(PDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu, int priority) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure

    newNode->pdu = pdu;
    newNode->priority = priority;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL || list->head->priority < priority) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->priority >= priority) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

// Remove the highest priority PDU
NFAPI_CRC_INDICATION_PDU_T removeHighestPriorityPDU(PDUList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0}; // Return an empty structure
    }

    Node* temp = list->head;
    NFAPI_CRC_INDICATION_PDU_T pdu = temp->pdu;
    list->head = list->head->next;
    free(temp);

    list->count--;
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

// Monitor memory usage
void* monitorMemoryUsage(void* arg) {
    PDUList* list = (PDUList*)arg;

    while (!list->terminateMonitor) {
        size_t memUsed = 0;
        pthread_mutex_lock(&list->lock);
        Node* current = list->head;
        while (current != NULL) {
            memUsed += sizeof(Node);
            current = current->next;
        }
        pthread_mutex_unlock(&list->lock);

        printf("Memory Usage: %zu bytes\n", memUsed);

        // Sleep or wait for some time before the next check
        sleep(5); // 5-second interval
    }

    return NULL;
}

