// Cleanup function
void cleanupPDUList(PDUList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);

    if (list->monitoringEnabled) {
        list->terminateMonitor = 1;
        pthread_join(list->monitorThread, NULL);
    }

    pthread_mutex_destroy(&list->lock);
}

