        boost::asio::ip::tcp::resolver resolver(ioService_);
        auto endpoints = resolver.resolve(host, port);
        boost::asio::async_connect(socket_, endpoints,
            [this](boost::system::error_code ec, boost::asio::ip::tcp::resolver::iterator) {
                if (!ec) {
                    request_("/path", "HTTP/1.0\r\nHost: " + host + "\r\n\r\n");
                } else {
                    logEvent("Connection failed: " + ec.message());
                }
            });
    }

private:
    void request(const std::string& target, const std::string& message) {
        boost::asio::async_write(socket_, boost::asio::buffer(message),
            [this](boost::system::error_code ec, std::size_t /*length*/) {
                if (!ec) {
                    boost::array<char, 128> buffer;
                    socket_.read_some(boost::asio::buffer(buffer), [this](boost::system::error_code ec, std::size_t length) {
                        if (!ec) {
                            logEvent(std::string(buffer.data(), length));
                        }
                    });
