void init_list(LinkedList* list) {
    if (!list) return;
    list->head = NULL;
    list->size = 0;
    memset(list->rnti_set, 0, sizeof(list->rnti_set));
    pthread_mutex_init(&list->lock, NULL);
}

int is_rnti_unique(LinkedList* list, uint16_t rnti) {
    return !list->rnti_set[rnti];
}

void set_rnti_in_list(LinkedList* list, uint16_t rnti) {
    if (rnti < 65536) {
        list->rnti_set[rnti] = 1;
    }
}

void unset_rnti_in_list(LinkedList* list, uint16_t rnti) {
    if (rnti < 65536) {
        list->rnti_set[rnti] = 0;
    }
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data, size_t position) {
    pthread_mutex_lock(&list->lock);

    if (!list || !is_rnti_unique(list, new_data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    *new_node = (Node){.data = new_data, .next = NULL};

    if (position == 0 || !list->head) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        for (size_t i = 1; i < position && current->next; i++) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    set_rnti_in_list(list, new_data.RNTI);
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void resize_if_needed(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size < THRESHOLD) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    while (current && current->next) {
        if (!is_rnti_unique(list, current->next->data.RNTI)) {
            Node* to_remove = current->next;
            current->next = current->next->next;
            unset_rnti_in_list(list, to_remove->data.RNTI);
            free(to_remove);
            list->size--;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        unset_rnti_in_list(list, current->data.RNTI);
        free(current);
        current = next;
    }

    list->head = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    LinkedList list;
    init_list(&list);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 101 };

    add_node(&list, pdu1, 0);
    add_node(&list, pdu2, 1);

    resize_if_needed(&list);
    destroy_list(&list);

    return 0;
}
