```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    unsigned long minRNTI;
    unsigned long maxRNTI;
    double crcFlagProbability;
    pthread_mutex_t lock;
    Node* head;
    Node* tail;
} CRCLinkedListConfig;

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    *node = (Node){.data = *data, .next = NULL};
    return node;
}

void free_list(Node* head) {
    Node* tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

void initialize_list(CRCLinkedListConfig* config) {
    pthread_mutex_init(&config->lock, NULL);
    config->head = NULL;
    config->tail = NULL;
}

unsigned long generate_random_rnti(unsigned long min, unsigned long max) {
    return (rand() % (max - min + 1)) + min;
}

int random_crcflag(double probability) {
    double rand_val = ((double)rand()) / RAND_MAX;
    return rand_val < probability ? 1 : 0;
}

int insert_unique_rnti(CRCLinkedListConfig* config, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&config->lock);

    Node* current = config->head;
    while (current != NULL) {
        if (current->data.RNTI == data.RNTI) {
            printf("Warning: Duplicate RNTI %lu encountered.\n", data.RNTI);
            pthread_mutex_unlock(&config->lock);
            return 0; // Duplicate found, skip insertion
        }
        current = current->next;
    }

    Node* new_node = create_node(&data);
    if (!new_node) {
        pthread_mutex_unlock(&config->lock);
        return -1; // Memory allocation failed
    }

    if (config->tail == NULL) {
        config->head = config->tail = new_node;
    } else {
        config->tail->next = new_node;
        config->tail = new_node;
    }

    pthread_mutex_unlock(&config->lock);
    return 1; // Insertion successful
}

void populate_list(CRCLinkedListConfig* config, int N) {
    srand(time(NULL));
    unsigned long rnti_set[10000] = {0}; // Assuming a max of 10,000 unique RNTI values

    for (int i = 0; i < N; ++i) {
        unsigned long rnti;
        do {
            rnti = generate_random_rnti(config->minRNTI, config->maxRNTI);
        } while (rnti_set[rnti % 10000] == rnti); // Ensure uniqueness

        rnti_set[rnti % 10000] = rnti;

        NFAPI_CRC_INDICATION_PDU_T data = {
            .RX_UE_INFORMATION_TAG = rand(), // Simulate tag generation
            .RNTI = rnti,
            .CRC_INDICATION_REL8_TAG = rand(),
            .CRCFLAG = random_crcflag(config->crcFlagProbability)
        };

        insert_unique_rnti(config, data);
    }
}

void iterate_and_print(CRCLinkedListConfig* config) {
    pthread_mutex_lock(&config->lock);

    Node* current = config->head;
    while (current != NULL) {
        printf("RNTI: %lu, CRCFLAG: %d\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&config->lock);
}

void cleanup(CRCLinkedListConfig* config) {
    free_list(config->head);
    pthread_mutex_destroy(&config->lock);
}
