    va_end(args);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pi_crc_indication_pdu(unsigned long RNTI, size_t estimated_size) {
    if (estimated_size > MAX_STRUCTURES) {
        estimated_size = MAX_STRUCTURES;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    for (size_t attempt = 1; attempt <= 2; ++attempt) { // Try allocation once and consider one reallocation
        array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(estimated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!array) {
            LOG_ERROR("Memory allocation failed on attempt %zu", attempt);
            continue;
        }

        // Initialize the structures
        for (size_t i = 0; i < estimated_size; ++i) {
            array[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag initialization
            array[i].RNTI = RNTI;
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)
        }

        // Validation: Ensure all RX_UE_INFORMATION_TAG values are unique
        int *tag_count = (int *)calloc(estimated_size + 1, sizeof(int)); 
        if (!tag_count) {
            free(array);
            LOG_ERROR("Memory allocation for tag count array failed");
            return NULL;
        }

        int is_valid = 1; // Assume valid until proven otherwise
        for (size_t i = 0; i < estimated_size; ++i) {
            if (++tag_count[array[i].RX_UE_INFORMATION_TAG] > 1) {
                LOG_ERROR("Duplicate RX_UE_INFORMATION_TAG detected: %d", array[i].RX_UE_INFORMATION_TAG);
                is_valid = 0;
                break;
            }
        }

        free(tag_count);

        if (is_valid) {
            LOG_INFO("Successfully allocated and initialized %zu structures.", estimated_size);
            return array; // Return the successfully allocated and validated array
        } else {
            free(array); // Cleanup on invalid case
            estimated_size *= 2;
            if (estimated_size > MAX_STRUCTURES) {
                estimated_size = MAX_STRUCTURES;
            }
            LOG_INFO("Retrying allocation with increased size: %zu", estimated_size);
        }
    }

    LOG_ERROR("Failed to allocate memory after retrying.");
    return NULL; // Indicate failure
}

int main() {
    unsigned long rnti_value = 12345; // Example RNTI value for testing

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = allocate_nfa_pi_crc_indication_pdu(rnti_value, 5000);

    if (pdu_array) {
        // Use the allocated array
        free(pdu_array); // Remember to free memory when done
    }

    return 0;
}
