Result create_nfaapi_crc_indication_pdu_list(int N, Config config) {
    Result result;
    pthread_t threads[config.thread_pool_size];
    size_t batch_size = (size_t)N / config.thread_pool_size;

    // Allocate memory with custom allocator
    pthread_mutex_lock(&allocator_lock);
    result.pdu_list = custom_allocator(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&allocator_lock);

    if (!result.pdu_list) {
