        return (Result){NULL, 0};
    }

    // Initialize structures in batches
    for (size_t i = 0; i < config.thread_pool_size; ++i) {
        size_t start_index = i * batch_size;
        size_t end_index = (i == config.thread_pool_size - 1) ? N : start_index + batch_size;

        pthread_create(&threads[i], NULL, [](void* arg) -> void* {
            Config* cfg = (Config*)arg;
            size_t start = *(size_t*)((char*)arg + sizeof(Config));
            size_t end = *((size_t*)((char*)arg + sizeof(Config) + sizeof(size_t)));

            for (size_t j = start; j < end; ++j) {
