                pdu->rnti = (rand() % (cfg->max_rnti - cfg->min_rnti + 1)) + cfg->min_rnti;
                pdu->crc_indication_rel8_tag.crc_flag =
                    ((double)rand() / RAND_MAX < cfg->crc_flag_probability);

                // Log and retry mechanism for failed writes
                if (!write_to_external_library(pdu)) {
                    log_failed_write(j);
                    retry_write(pdu, j);  // Assume this function retries writing
                }
            }
            return NULL;
        }, malloc(sizeof(Config) + 2 * sizeof(size_t)), free);

        *(Config*)((char*)threads[i] + sizeof(pthread_t)) = config;
        *((size_t*)((char*)threads[i] + sizeof(pthread_t) + sizeof(Config))) = start_index;
        *((size_t*)((char*)threads[i] + sizeof(pthread_t) + sizeof(Config) + sizeof(size_t))) = end_index;
    }

    for (size_t i = 0; i < config.thread_pool_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Validate the integrity of the list
    if (!validate_pdu_list(result.pdu_list, N)) {
        fprintf(stderr, "Validation failed\n");
        custom_free(result.pdu_list);
        return (Result){NULL, 0};
    }

    result.count = N;
    return result;
}

int main() {
