            log_warning("Timeout reached during PDU generation");
            break;
        }

        unsigned short rx_ue_tag = rand() % MAX_RXTAG + 1;
        unsigned short rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;

        if (!validate_rx_ue_info(rx_ue_tag)) {
            log_warning("Invalid RX_UE_INFORMATION_TAG");
            continue;
        }

        if (!validate_rnti(rnti)) {
            log_warning("Invalid RNTI");
            continue;
        }

        pthread_mutex_lock(&lock);
        pdus[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
        pdus[i].RNTI = rnti;
        if (enable_crc_flag_setting) {
            pdus[i].crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        } else {
            pdus[i].crc_tag.CRCFLAG = 0; // Disable CRC flag setting
        }
        pthread_mutex_unlock(&lock);
    }

    *error_code = 0;
    return pdus;
}

void destroy_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (pdus) {
        free(pdus);
    }
}
