import pthread.h

// Define structure for transmission parameters
typedef struct {
    int header;
    char* tx_mode;
    char* modulation_scheme;
} TX_MESSAGE_PDU;

// Node structure for linked list
typedef struct Node {
    TX_MESSAGE_PDU data;
    struct Node* next;
} Node;

// Structure to manage the dynamic list with thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MessageList;

// Function prototypes
void initMessageList(MessageList* list);
int addMessagePDU(MessageList* list, TX_MESSAGE_PDU pdu);
TX_MESSAGE_PDU* getFirstValidMessage(MessageList* list);

// Initialize the message list and mutex
void initMessageList(MessageList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Validate transmission parameters
int validateParameters(TX_MESSAGE_PDU pdu) {
    // Implement validation logic (e.g., check ranges or specific values)
    if (pdu.header < 0 || pdu.header > 255) return 0; // Example constraint
    if (!pdu.tx_mode || !*pdu.tx_mode) return 0;
    if (!pdu.modulation_scheme || !*pdu.modulation_scheme) return 0;
    return 1;
}

// Add a new TX_MESSAGE_PDU to the list with validation and thread-safety
int addMessagePDU(MessageList* list, TX_MESSAGE_PDU pdu) {
    // Acquire mutex for thread safety
    pthread_mutex_lock(&list->lock);

    if (!validateParameters(pdu)) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Invalid parameters, do not add to the list
    }

    // Allocate new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Memory allocation failure
    }
    newNode->data = pdu;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 1; // Success
}

// Retrieve the first valid message from the list, ensuring thread safety
TX_MESSAGE_PDU* getFirstValidMessage(MessageList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && !validateParameters(current->data)) {
        current = current->next; // Skip invalid messages
    }

    TX_MESSAGE_PDU* result = NULL;
    if (current) {
        result = &current->data;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

// Example usage of the list management system
int main() {
    MessageList messageList;
    initMessageList(&messageList);

    TX_MESSAGE_PDU pdu1 = { .header = 100, .tx_mode = "ModeA", .modulation_scheme = "SchemeX" };
    addMessagePDU(&messageList, pdu1);

    // Retrieve first valid PDU
    TX_MESSAGE_PDU* message = getFirstValidMessage(&messageList);
    if (message) {
        printf("Retrieved Message - Header: %d\n", message->header);
    } else {
        printf("No valid messages found.\n");
    }

    return 0;
}
```

