typedef struct Node {
    void *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    int max_size;
    int current_size;
} ConnectionPool;

ConnectionPool create_connection_pool(int max_size) {
    ConnectionPool pool = {NULL, max_size, 0};
    return pool;
}

void destroy_connection_pool(ConnectionPool *pool) {
    Node *current = pool->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}

Node* allocate_from_pool(ConnectionPool *pool, size_t data_size) {
    if (pool->current_size < pool->max_size) {
        Node *node = (Node *)malloc(sizeof(Node));
        node->data = malloc(data_size);
        node->next = pool->head;
        pool->head = node;
        pool->current_size++;
        return node;
    }
    return NULL; // Pool is full
}

void deallocate_from_pool(ConnectionPool *pool, Node *node) {
    if (pool->head == node) {
        pool->head = node->next;
    } else {
        Node *current = pool->head;
        while (current && current->next != node) {
            current = current->next;
        }
        if (current) {
            current->next = node->next;
        }
    }
    free(node->data);
    free(node);
    pool->current_size--;
}

