#define MAX_PDCP_SN 1023
#define MAX_MAC_HEADER 255
#define LOG_ERROR(fmt, ...) printf("ERROR: " fmt "\n", ##__VA_ARGS__)
#define LOG_WARNING(fmt, ...) printf("WARNING: " fmt "\n", ##__VA_ARGS__)

typedef struct {
    uint8_t mac_header;
} MAC_HEADER;

typedef struct {
    uint16_t pdcp_sn;
} PDCP_SN;

typedef struct {
    bool ack_request;
} MAC_DATA_PDU;

typedef struct {
