    PDCP_SN sn;
    MAC_DATA_PDU data_pdu;
} MAC_PDU;

typedef struct {
    MAC_PDU *pdus;
    size_t count;
    pthread_mutex_t mutex;
} MAC_PDU_LIST;

void log_error(const char* message) {
    // Integrate with centralized logging system
    LOG_ERROR("%s", message);
}

bool validate_mac_header(uint8_t header) {
    return header <= MAX_MAC_HEADER;
}

bool validate_pdcp_sn(uint16_t sn) {
    return sn <= MAX_PDCP_SN;
}

MAC_PDU_LIST* create_pdu_list(int M, bool enable_ack_flag, int max_processing_time_ms, size_t max_size) {
    if (M <= 0 || max_processing_time_ms <= 0 || max_size == 0) {
        log_error("Invalid parameters");
        return NULL;
    }

    MAC_PDU_LIST *list = malloc(sizeof(MAC_PDU_LIST));
    if (!list) {
        log_error("Memory allocation failed for PDU list structure");
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;

    // Calculate the actual size to allocate based on M and max_size
    size_t num_pdus = (M < max_size) ? M : max_size;
    list->pdus = malloc(num_pdus * sizeof(MAC_PDU));
    if (!list->pdus) {
        log_error("Memory allocation failed for PDUs");
        free(list);
        return NULL;
    }

    clock_t start_time = clock();

    for (size_t i = 0; i < num_pdus; ++i) {
        // Check timeout
        clock_t current_time = clock();
        double elapsed_ms = (double)(current_time - start_time) * 1000 / CLOCKS_PER_SEC;
        if (elapsed_ms >= max_processing_time_ms) {
            log_warning("Processing time exceeded");
            break;
        }

        MAC_PDU *pdu = &list->pdus[i];

        // Generate random values for validation
        pdu->header.mac_header = rand() % 256; 
        pdu->sn.pdcp_sn = rand() % 65536;

        if (!validate_mac_header(pdu->header.mac_header)) {
            log_warning("Invalid MAC header");
            continue;
        }

        if (!validate_pdcp_sn(pdu->sn.pdcp_sn)) {
            log_warning("Invalid PDCP SN");
            continue;
        }

        // Set ACK_REQUEST based on parameter
        pdu->data_pdu.ack_request = enable_ack_flag ? rand() % 2 : false;

        pthread_mutex_lock(&list->mutex);
        list->count++;
        pthread_mutex_unlock(&list->mutex);
    }

    return list;
}

void destroy_pdu_list(MAC_PDU_LIST *list) {
    if (list) {
        free(list->pdus);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}
