    uint8_t SFI;
    char PDU_CONTENT[256];
    bool CONTENT_VALIDITY_FLAG;
} NR_PDU_T;

typedef struct Node {
    NR_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t lock;
} PDU_List;

// Function prototypes
PDU_List* create_pdu_list(int max_capacity);
int add_pdu(PDU_List* list, bool enable_validity_flag);
void destroy_pdu_list(PDU_List** list);
bool is_within_bounds(uint8_t TXUEINFO_TAG, uint8_t SFI);
void log_error(const char* message);

// Create a PDU list with a specified maximum capacity
PDU_List* create_pdu_list(int max_capacity) {
    if (max_capacity <= 0) return NULL;

    PDU_List* list = (PDU_List*)malloc(sizeof(PDU_List));
    if (!list) {
        log_error("Failed to allocate memory for PDU List");
        return NULL;
    }

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Add a new PDU to the list
int add_pdu(PDU_List* list, bool enable_validity_flag) {
    if (!list || list->count >= max_capacity) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for PDU node");
        return -1;
    }

    // Randomly set TXUEINFO_TAG, SFI, and CONTENT_VALIDITY_FLAG
    srand(time(NULL));
    NR_PDU_T pdu = { .TXUEINFO_TAG = rand() % 256,
                     .SFI = rand() % 16,
                     .CONTENT_VALIDITY_FLAG = enable_validity_flag ? (rand() % 2) : false };

    // Validate the TXUEINFO_TAG and SFI
    if (!is_within_bounds(pdu.TXUEINFO_TAG, pdu.SFI)) {
        free(new_node);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Destroy the PDU list and free resources
void destroy_pdu_list(PDU_List** list) {
    if (!list || !*list) return;

    Node* current = (*list)->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&(*list)->lock);
    free(*list);
    *list = NULL;
}

// Check if TXUEINFO_TAG and SFI are within bounds
bool is_within_bounds(uint8_t TXUEINFO_TAG, uint8_t SFI) {
    return (TXUEINFO_TAG <= MAX_TXUEINFO_TAG && SFI <= MAX_SFI);
}

// Log errors or warnings
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
```

### Key Points:

1. **Dynamic Allocation**: The list is dynamically allocated and managed using a linked list structure.
