3. **Concurrency**: Thread safety is ensured with mutex locks (`pthread_mutex_t`) around critical sections.
4. **Logging**: Simple error logging via `stderr`.
5. **Graceful Handling**: The function handles memory allocation failures and validation errors gracefully, returning appropriate error codes.

This code provides a robust starting point for managing PDUs dynamically while ensuring thread safety and efficient resource usage. Adjustments may be needed based on specific system requirements or constraints.']

['Here's a C implementation using a dynamically allocated array with linked list characteristics for efficiently managing `TrafficEvent` structures:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned int Timestamp;
    char Source[16];
    char Destination[16];
    int PacketSize;
} TrafficEvent;

typedef struct Node {
    TrafficEvent data;
    struct Node* next;
} Node;

Node* head = NULL;
int eventCount = 0;
const int MAX_EVENTS = 10000;

void initializeEvents() {
    head = NULL;
    eventCount = 0;
}

void addEvent(unsigned int timestamp, const char* source, const char* destination, int packetSize) {
    if (eventCount >= MAX_EVENTS) return; // Limit reached

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data.Timestamp = timestamp;
    snprintf(newNode->data.Source, sizeof(newNode->data.Source), "%s", source);
    snprintf(newNode->data.Destination, sizeof(newNode->data.Destination), "%s", destination);
    newNode->data.PacketSize = packetSize;
    newNode->next = head;
    head = newNode;

    eventCount++;
}

void removeEvent() {
    if (head == NULL) return; // No events to remove

    Node* temp = head;
    head = head->next;
    free(temp);

    eventCount--;
}

int getTotalEvents() const {
    return eventCount;
}

float calculateAveragePacketSize() const {
    if (eventCount == 0) return 0.0;

    float totalPacketSize = 0.0;
    Node* current = head;

    while (current != NULL) {
        totalPacketSize += current->data.PacketSize;
        current = current->next;
    }

    return totalPacketSize / eventCount;
}

void freeEvents() {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
    eventCount = 0;
}

int main() {
    initializeEvents();

    addEvent(1, "192.168.0.1", "192.168.0.2", 500);
    addEvent(2, "192.168.0.3", "192.168.0.4", 300);

    printf("Total Events: %d\n", getTotalEvents());
    printf("Average Packet Size: %.2f\n", calculateAveragePacketSize());

    removeEvent();
    printf("Total Events after removal: %d\n", getTotalEvents());

    freeEvents();

    return 0;
}
```

### Key Points:
- The linked list allows efficient insertions and deletions, addressing the need for frequent updates without reallocation.
- Memory usage is optimized by dynamically allocating memory only as needed.
- Operations like adding and removing events are performed in constant time \(O(1)\).
- Calculating the average packet size involves a linear traversal of the list, which is efficient given the problem constraints.']

