// Initialize a memory pool
void initMemoryPool(MemoryPool* mp, size_t block_size, size_t num_blocks) {
    mp->block_size = block_size;
    mp->num_blocks = num_blocks;
    mp->pool = (unsigned char*)malloc(block_size * num_blocks);
    mp->free_index = 0;
}

// Allocate memory from the pool
void* allocateFromPool(MemoryPool* mp, size_t size) {
    if (size > mp->block_size || atomic_fetch_add(&mp->free_index, 1) >= mp->num_blocks)
        return NULL; // Pool exhausted

    void* block = mp->pool + (atomic_load(&mp->free_index) - 1) * mp->block_size;
    memset(block, 0, size); // Clear memory
    return block;
}

// Deallocate is not necessary for fixed-size pool allocations

// Initialize the message manager
void initMessageManager(MessageManager* mm, void (*validate)(TX_MESSAGE_PDU*)) {
    atomic_init(&mm->size, 0);
    mm->head = NULL;
    pthread_mutex_init(&mm->lock, NULL);
    mm->validate = validate;
}

// Validate and add a message to the list
int addMessage(MessageManager* mm, TX_MESSAGE_PDU* msg) {
    if (!mm->validate || !mm->validate(msg))
        return -1; // Validation failed

    MessageNode* newNode = (MessageNode*)allocateFromPool(&globalMemoryPool, sizeof(MessageNode));
    if (!newNode)
        return -2; // Memory allocation failed

    memcpy(&newNode->message, msg, sizeof(TX_MESSAGE_PDU));
    pthread_mutex_lock(&mm->lock);
    newNode->next = mm->head;
    mm->head = newNode;
    atomic_fetch_add(&mm->size, 1);
    pthread_mutex_unlock(&mm->lock);

    return 0; // Success
}

// Free all messages in the list (for cleanup)
void freeMessages(MessageManager* mm) {
    pthread_mutex_lock(&mm->lock);
    MessageNode* current = mm->head;
    while (current) {
        MessageNode* temp = current;
        current = current->next;
        // No explicit free needed for pool allocations
    }
    mm->head = NULL;
    atomic_init(&mm->size, 0);
    pthread_mutex_unlock(&mm->lock);
}

// Example validation function
void exampleValidation(TX_MESSAGE_PDU* msg) {
    if (msg->header < 0 || strlen(msg->transmission_mode) == 0)
        return; // Invalid message
    // Additional checks can be added here
}

// Global memory pool for the messages
MemoryPool globalMemoryPool;

int main() {
    initMessageManager(&globalMsgManager, exampleValidation);
    initMemoryPool(&globalMemoryPool, sizeof(MessageNode), 100); // Example initialization

    TX_MESSAGE_PDU msg = {1, "ModeA", "MCS1"};
    addMessage(&globalMsgManager, &msg);

    freeMessages(&globalMsgManager);
    return 0;
}

// Define the global message manager
MessageManager globalMsgManager;

