typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    uint32_t rollingChecksum;
} LinkedList;

uint32_t generateRandomCRCFLAG() {
    return rand() % 256; // Random value between 0 and 255
}

bool isUnique(LinkedList* list, uint32_t tag, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == tag && current->data.RNTI == rnti) {
            return false;
        }
        current = current->next;
    }
    return true;
}

void logMessage(const char* message) {
    printf("%s\n", message); // Replace with actual logging
}

void updateRollingChecksum(LinkedList* list, uint8_t crcFlag, bool add) {
    if (add) {
        list->rollingChecksum += crcFlag;
    } else {
        list->rollingChecksum -= crcFlag;
    }
}

void initializeList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->rollingChecksum = 0;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        logMessage("Memory allocation failed for new node");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

bool insertEntry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T newData) {
    pthread_mutex_lock(&list->lock);

    if (!isUnique(list, newData.RX_UE_INFORMATION_TAG, newData.RNTI)) {
        logMessage("Duplicate entry detected");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* newNode = createNode(newData);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    newNode->next = list->head;
    list->head = newNode;

    updateRollingChecksum(list, newData.CRCFLAG, true);

    logMessage("Entry inserted successfully");
    pthread_mutex_unlock(&list->lock);
    return true;
}

void removeEntry(LinkedList* list, uint32_t tag, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && 
           (current->data.RX_UE_INFORMATION_TAG != tag || current->data.RNTI != rnti)) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return; // Entry not found
    }

    if (prev == NULL) { // Head needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    updateRollingChecksum(list, current->data.CRCFLAG, false);

    free(current);
    logMessage("Entry removed successfully");

    pthread_mutex_unlock(&list->lock);
}

void destroyList(LinkedList* list) {
    Node *current = list->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
}

int main() {
    LinkedList list;
    initializeList(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (uint32_t i = 0; i < MAX_ENTRIES; ++i) {
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 65535; // RNTI is typically a 16-bit value
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = generateRandomCRCFLAG();

        if (!insertEntry(&list, pdu)) {
            logMessage("Failed to insert entry");
        }
    }

    destroyList(&list);
    return 0;
}
