        log_message(list, "Reached maximum capacity. Cannot insert more nodes.");
        return -1;
    }

    if (!is_rnti_unique(list, new_data.RNTI)) {
        log_message(list, "RNTI is not unique. Insertion failed.");
        return -2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message(list, "Memory allocation failed for new node.");
        return -3;
    }

    memcpy(&new_node->data, &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Record RNTI to prevent duplicates
    list->rnti_set[list->size] = new_node->data.RNTI;

    new_node->next = list->head;
