void initializePduArray(size_t size) {
    pthread_mutex_lock(&mutex);
    if (currentSize < size) {
        NFAPI_CRC_INDICATION_STRUCT_T *newArray = realloc(pduArray, size * sizeof(NFAPI_CRC_INDICATION_STRUCT_T));
        if (newArray == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            exit(EXIT_FAILURE);
