            pduArray[i].pdu.crcTag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        }
        currentSize = size;
    }
    pthread_mutex_unlock(&mutex);
}

void freePduArray() {
    pthread_mutex_lock(&mutex);
    if (pduArray != NULL) {
        free(pduArray);
        pduArray = NULL;
    }
    currentSize = 0;
    pthread_mutex_unlock(&mutex);
}

