    initializePduArray(10);
    assert(currentSize == 10);

    for (size_t i = 0; i < 10; ++i) {
        assert(pduArray[i].pdu.crcTag.CRCFLAG == 0 || pduArray[i].pdu.crcTag.CRCFLAG == 1);
    }

    freePduArray();
    assert(currentSize == 0);
}

void testReallocation() {
    initializePduArray(20);
    assert(currentSize == 20);

    initializePduArray(30); // Test reallocation
    assert(currentSize == 30);

    for (size_t i = 20; i < 30; ++i) {
        assert(pduArray[i].pdu.crcTag.CRCFLAG == 0 || pduArray[i].pdu.crcTag.CRCFLAG == 1);
    }

    freePduArray();
}

void testConcurrency() {
    #define THREAD_COUNT 5
    pthread_t threads[THREAD_COUNT];

    for (int i = 0; i < THREAD_COUNT; ++i) {
        if (pthread_create(&threads[i], NULL, (void*(*)(void*))initializePduArray, (void*)(size_t)MAX_PDUS)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < THREAD_COUNT; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            exit(EXIT_FAILURE);
        }
    }

    freePduArray();
}

int main() {
