#define HASH_TABLE_SIZE 1024

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    time_t last_accessed; // For garbage collection
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    pthread_mutex_t lock;
    unsigned int rnti_hash_table[HASH_TABLE_SIZE];
} CRC_Indication_List;

unsigned int hash_rnti(unsigned int RNTI) {
    return RNTI % HASH_TABLE_SIZE;
}

int is_rnti_unique(CRC_Indication_List *list, unsigned int RNTI) {
    unsigned int index = hash_rnti(RNTI);
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (list->rnti_hash_table[(index + i) % HASH_TABLE_SIZE] == RNTI)
            return 0;
    }
    return 1;
}

void add_rnti_to_hash(CRC_Indication_List *list, unsigned int RNTI) {
    unsigned int index = hash_rnti(RNTI);
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (list->rnti_hash_table[(index + i) % HASH_TABLE_SIZE] == 0) {
            list->rnti_hash_table[(index + i) % HASH_TABLE_SIZE] = RNTI;
            break;
        }
    }
}

void remove_rnti_from_hash(CRC_Indication_List *list, unsigned int RNTI) {
    unsigned int index = hash_rnti(RNTI);
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (list->rnti_hash_table[(index + i) % HASH_TABLE_SIZE] == RNTI) {
            list->rnti_hash_table[(index + i) % HASH_TABLE_SIZE] = 0;
            break;
        }
    }
}

CRC_Indication_List* create_list() {
    CRC_Indication_List *list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;

    memset(list, 0, sizeof(CRC_Indication_List));
    pthread_mutex_init(&list->lock, NULL);
    memset(list->rnti_hash_table, 0, sizeof(list->rnti_hash_table));

    return list;
}

int insert_at_head(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, new_node->RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // RNTI not unique
    }

    new_node->next = list->head;
    list->head = new_node;

    if (list->tail == NULL) {
        list->tail = new_node;
    }

    add_rnti_to_hash(list, new_node->RNTI);
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

int insert_at_tail(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, new_node->RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // RNTI not unique
    }

    new_node->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    add_rnti_to_hash(list, new_node->RNTI);
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int rx_ue_tag, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) return NULL;

    new_pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_pdu->RNTI = rnti;
    new_pdu->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    time(&new_pdu->last_accessed);

    return new_pdu;
}

void garbage_collect(CRC_Indication_List *list, time_t current_time) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T **current = &list->head;
    while (*current) {
        if (difftime(current_time, (*current)->last_accessed) > 3600) { // 1-hour inactivity
            NFAPI_CRC_INDICATION_PDU_T *to_remove = *current;
            *current = to_remove->next;

            remove_rnti_from_hash(list, to_remove->RNTI);
            free(to_remove);

            if (*current == NULL && list->tail == to_remove) {
                list->tail = NULL; // If the tail was removed
            }
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int serialize_list(CRC_Indication_List *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    fwrite(&list->head, sizeof(NFAPI_CRC_INDICATION_PDU_T*), 1, file);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        size_t write_result = fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (write_result != 1) {
            pthread_mutex_unlock(&list->lock);
            fclose(file);
            return -2; // Write error
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_list(const char *filename, CRC_Indication_List *list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    NFAPI_CRC_INDICATION_PDU_T **head_p = &list->head;
    fread(head_p, sizeof(NFAPI_CRC_INDICATION_PDU_T*), 1, file);

    NFAPI_CRC_INDICATION_PDU_T *current = *head_p;
    while (fread(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) break;

        memcpy(new_node, current, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = NULL;

        add_rnti_to_hash(list, new_node->RNTI);
        *head_p = new_node; // Point head_p to the newly created node
        head_p = &new_node->next;

        current = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    fclose(file);

    return list->head;
}

void free_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *to_free = current;
        current = current->next;
        remove_rnti_from_hash(list, to_free->RNTI);
        free(to_free);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
