    unsigned int rnti;
    NFAPI_RX_PAYLOAD payload;
} NFAPI_RX_PDU_T;

#define INITIAL_CAPACITY 16

typedef struct {
    NFAPI_RX_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_create() {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    da->array = calloc(da->capacity, sizeof(NFAPI_RX_PDU_T));
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void dynamic_array_free(DynamicArray *da) {
    for (size_t i = 0; i < da->size; ++i) {
        free(da->array[i].payload.tag);
        free(da->array[i].payload.payload_data);
    }
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

static void ensure_capacity(DynamicArray *da) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_RX_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_RX_PDU_T));
        if (!new_array) return; // Handle allocation failure gracefully
        da->array = new_array;
        da->capacity = new_capacity;
    }
}

void dynamic_array_add(DynamicArray *da, unsigned int rnti, char *tag, void *payload_data) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].rnti == rnti) {
            free(da->array[i].payload.tag);
            free(da->array[i].payload.payload_data);
            break;
        }
    }

    ensure_capacity(da);

    da->array[da->size].rnti = rnti;
    da->array[da->size].payload.tag = strdup(tag);
    da->array[da->size].payload.payload_data = malloc(payload_data ? strlen((char *)payload_data) + 1 : 0);
    if (payload_data && da->array[da->size].payload.payload_data) {
        memcpy(da->array[da->size].payload.payload_data, payload_data, strlen((char *)payload_data) + 1);
    }

    ++da->size;
    pthread_mutex_unlock(&da->lock);
}

NFAPI_RX_PDU_T* dynamic_array_get_by_rnti(DynamicArray *da, unsigned int rnti) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].rnti == rnti) {
            NFAPI_RX_PDU_T *result = &da->array[i];
            pthread_mutex_unlock(&da->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return NULL;
}

void dynamic_array_update(DynamicArray *da, unsigned int rnti, char *new_tag, void *new_payload_data) {
    NFAPI_RX_PDU_T *entry = dynamic_array_get_by_rnti(da, rnti);

    if (entry != NULL) {
        pthread_mutex_lock(&da->lock);

        free(entry->payload.tag);
        entry->payload.tag = strdup(new_tag);

        free(entry->payload.payload_data);
        entry->payload.payload_data = malloc(new_payload_data ? strlen((char *)new_payload_data) + 1 : 0);
        if (new_payload_data && entry->payload.payload_data) {
            memcpy(entry->payload.payload_data, new_payload_data, strlen((char *)new_payload_data) + 1);
        }

        pthread_mutex_unlock(&da->lock);
    }
}

int main() {
    DynamicArray *da = dynamic_array_create();

    // Example usage:
    char payload[] = "Example Payload Data";
    dynamic_array_add(da, 1234, "Initial Tag", payload);

    NFAPI_RX_PDU_T *entry = dynamic_array_get_by_rnti(da, 1234);
    if (entry) {
        printf("RNTI: %u, Tag: %s\n", entry->rnti, entry->payload.tag);
    }

    dynamic_array_update(da, 1234, "Updated Tag", "New Payload Data");

    entry = dynamic_array_get_by_rnti(da, 1234);
    if (entry) {
        printf("RNTI: %u, Tag: %s\n", entry->rnti, entry->payload.tag);
    }

    dynamic_array_free(da);

    return 0;
}
