#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_SIZE 1000
#define MAX_STRUCTURES 10000
#define FUTURE_MAX_STRUCTURES 50000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

DynamicArray* allocate_dynamic_array(size_t initial_capacity) {
    DynamicArray *dynamicArray = (DynamicArray*) malloc(sizeof(DynamicArray));
    if (!dynamicArray) {
        log_error("Failed to allocate memory for DynamicArray");
        return NULL;
    }

    dynamicArray->array = (NFAPI_CRC_INDICATION_PDU_T*) calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamicArray->array) {
        free(dynamicArray);
        log_error("Failed to allocate memory for initial array");
        return NULL;
    }

    dynamicArray->capacity = initial_capacity;
    pthread_mutex_init(&dynamicArray->lock, NULL);

    return dynamicArray;
}

int resize_dynamic_array(DynamicArray *dynamicArray, size_t new_capacity) {
    if (new_capacity > FUTURE_MAX_STRUCTURES) {
        log_error("Requested capacity exceeds the theoretical limit");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dynamicArray->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_error("Failed to reallocate memory for array");
        return -1;
    }

    dynamicArray->array = new_array;
    dynamicArray->capacity = new_capacity;

