```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    int socket_fd;
    struct sockaddr_storage peer_addr;
    time_t last_activity;
} ConnectionMetadata;

typedef struct {
    ConnectionMetadata *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double activity_threshold; // in seconds
} ConnectionManager;

ConnectionManager* create_connection_manager(size_t initial_capacity, double threshold) {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->connections = calloc(initial_capacity, sizeof(ConnectionMetadata));
    if (!manager->connections) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->activity_threshold = threshold;

    return manager;
}

int add_connection(ConnectionManager *manager, int socket_fd, struct sockaddr_storage *peer_addr) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        ConnectionMetadata *new_connections = realloc(manager->connections, new_capacity * sizeof(ConnectionMetadata));
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    ConnectionMetadata new_conn = {socket_fd, *(struct sockaddr_storage*)peer_addr, time(NULL)};
    manager->connections[manager->count++] = new_conn;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int remove_inactive_connections(ConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    size_t current_index = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if ((time(NULL) - manager->connections[i].last_activity) > manager->activity_threshold) {
            // Close the socket to prevent resource leaks
            close(manager->connections[i].socket_fd);

            // Shift elements down in the array
            memmove(&manager->connections[current_index], &manager->connections[i], (manager->count - i - 1) * sizeof(ConnectionMetadata));
            manager->count--;
        } else {
            current_index++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int update_activity(ConnectionManager *manager, int socket_fd) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].socket_fd == socket_fd) {
            manager->connections[i].last_activity = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Connection not found
}

void adjust_threshold(ConnectionManager *manager, double new_threshold) {
    pthread_mutex_lock(&manager->lock);

    manager->activity_threshold = new_threshold;

    pthread_mutex_unlock(&manager->lock);
}

void free_connection_manager(ConnectionManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        close(manager->connections[i].socket_fd);
    }

    free(manager->connections);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` for locking to ensure thread safety.
- **Dynamic Memory Management**: Resizes the array when capacity is exceeded, minimizing fragmentation.
- **Error Handling**: Returns error codes for memory allocation failures and missing connections.
- **Activity Threshold Adjustment**: Allows dynamic adjustment of inactivity threshold based on network conditions.
- **Logging**: For simplicity, logging isn't included but can be added with minimal performance impact using conditional compilation or lightweight logging frameworks.

This implementation is designed to handle high concurrency efficiently while ensuring safe access to connection metadata. Adjust the `MAX_CONNECTIONS` constant and initial capacity as needed for your specific use case."]

