#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    uint16_t* hash_table;
} CRCList;

uint32_t hash_function(uint16_t rnti, size_t table_size) {
    return (uint32_t)rnti % table_size;
}

CRCList* create_crc_list(size_t table_size) {
    CRCList* list = malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->hash_table = calloc(table_size, sizeof(uint16_t));
    if (!list->hash_table) {
        free(list);
        return NULL;
    }

    return list;
}

int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    size_t hash_index = hash_function(pdu.RNTI, list->count + 1);
    if (list->hash_table[hash_index] == pdu.RNTI) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate RNTI
    }
    list->hash_table[hash_index] = pdu.RNTI;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void update_crc_flags(CRCList* list, uint16_t rnti_condition) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti_condition) {
            // Atomic update of CRCFLAG
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = 1; // Example condition
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int compare_rnti(const void* a, const void* b) {
    Node* node_a = *(Node**)a;
    Node* node_b = *(Node**)b;
    return (node_a->data.RNTI - node_b->data.RNTI);
}

void sort_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    size_t count = 0;
    Node* current = list->head;
    while (current) {
        count++;
        current = current->next;
    }

    Node** array = malloc(count * sizeof(Node*));
    if (!array) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    current = list->head;
    size_t i = 0;
    while (current) {
        array[i++] = current;
        current = current->next;
    }

    qsort(array, count, sizeof(Node*), compare_rnti);

    Node dummy;
    list->head = &dummy;
    for (size_t j = 0; j < count; ++j) {
        array[j]->next = list->head->next;
        list->head->next = array[j];
    }
    free(array);

    pthread_mutex_unlock(&list->lock);
}

void destroy_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    free(list->hash_table);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    CRCList* list = create_crc_list(10); // Example size
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRC_INDICATION_REL8_TAG = {.CRCFLAG = 0} };
    add_to_crc_list(list, pdu);

    update_crc_flags(list, 100);
    sort_crc_list(list);

    destroy_crc_list(list);
    return 0;
}
```

This code provides a thread-safe implementation of a dynamic list for managing `NFAPI_CRC_INDICATION_PDU_T` structures. It includes memory management, atomic updates, and sorting by `RNTI`. The hash table ensures no duplicate `RNTI` entries.']

