char* process_directory_path(const char *dirPath, size_t max_size, bool safe_mode, const char *baseDir) {
    if (max_size == 0 || dirPath == NULL || baseDir == NULL) {
        return NULL;
    }

    size_t baseLen = strlen(baseDir);
    size_t dirLen = strlen(dirPath);

    // Check if dirPath is absolute
    bool isAbsolute = dirPath[0] == '/';

    char *resolvedPath = NULL;
    size_t totalSize;

    if (safe_mode) {
        // Resolve path safely with dynamic allocation
        if (!isAbsolute && baseDir[baseLen - 1] != '/') {
            totalSize = baseLen + dirLen + 2; // base + '/' + dir + '\0'
        } else {
            totalSize = baseLen + dirLen + 1; // base + dir + '\0'
        }

        if (totalSize > max_size) {
            return NULL;
        }

        resolvedPath = malloc(totalSize);
        if (!resolvedPath) {
            return NULL;
        }

        if (!isAbsolute && baseDir[baseLen - 1] != '/') {
            snprintf(resolvedPath, totalSize, "%s/%s/", baseDir, dirPath);
        } else {
            snprintf(resolvedPath, totalSize, "%s%s", baseDir, dirPath);
        }

    } else {
        // Unsafe mode: attempt in-place resolution
        if (!isAbsolute && baseDir[baseLen - 1] != '/') {
            totalSize = baseLen + dirLen + 2; // base + '/' + dir + '\0'
        } else {
            totalSize = baseLen + dirLen + 1; // base + dir + '\0'
        }

        if (totalSize > max_size) {
            return ERROR_OVERFLOW;
        }

        char tempPath[PATH_MAX];
        if (!isAbsolute && baseDir[baseLen - 1] != '/') {
            snprintf(tempPath, sizeof(tempPath), "%s/%s/", baseDir, dirPath);
        } else {
            snprintf(tempPath, sizeof(tempPath), "%s%s", baseDir, dirPath);
        }

        strncpy(dirPath, tempPath, max_size - 1);
        dirPath[max_size - 1] = '\0';
    }

    return resolvedPath ? resolvedPath : (char *)dirPath;
}
