    private String handleTagType2(int rnti, boolean crcFlag) {
        // Analyze and format weaknesses based on tag type 2
        return "Tag Type 2 - RNTI: " + rnti + ", CRC Flag: " + crcFlag;
    }

    private String handleTagType3(int rnti, boolean crcFlag) {
        // Analyze and format weaknesses based on tag type 3
        return "Tag Type 3 - RNTI: " + rnti + ", CRC Flag: " + crcFlag;
    }
