#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UES 1000
#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    int ueIdentity;
    int rnti;
    int qosFlowCount;
} QoSParameters;

typedef struct {
    int buffer_size;
    void *dataBuffer; // Dynamic data buffer for transmission
    pthread_mutex_t lock; // Mutex to handle concurrent access
} LTEUEContext;

typedef struct {
    LTEUEContext contexts[MAX_UES];
    size_t count;
    pthread_rwlock_t list_lock; // Read-write lock for UE context list management
} NetworkInterface;

void initializeNetworkInterface(NetworkInterface *network) {
    network->count = 0;
    pthread_rwlock_init(&network->list_lock, NULL);
    for (size_t i = 0; i < MAX_UES; ++i) {
        pthread_mutex_init(&network->contexts[i].lock, NULL);
    }
}

int addLTEUEContext(NetworkInterface *network, int ueIdentity, int rnti, QoSParameters qosParams) {
    if (network->count >= MAX_UES) return -1;

    pthread_rwlock_wrlock(&network->list_lock);

    LTEUEContext *context = &network->contexts[network->count];
    context->buffer_size = INITIAL_BUFFER_SIZE;
    context->dataBuffer = malloc(context->buffer_size);
    if (context->dataBuffer == NULL) {
        pthread_rwlock_unlock(&network->list_lock);
        return -1; // Memory allocation failure
    }

    context->ueIdentity = ueIdentity;
    context->rnti = rnti;

    pthread_mutex_init(&context->lock, NULL);

    network->count++;
    pthread_rwlock_unlock(&network->list_lock);

    adjustBufferBasedOnTraffic(context, qosParams); // Initial adjustment based on QoS parameters
    return 0;
}

void adjustBufferBasedOnTraffic(LTEUEContext *context, QoSParameters qosParams) {
    pthread_mutex_lock(&context->lock);

    int newSize = INITIAL_BUFFER_SIZE + (qosParams.qosFlowCount * 512); // Example logic to increase buffer size
    if (newSize > context->buffer_size) {
        void *newBuffer = realloc(context->dataBuffer, newSize);
        if (newBuffer != NULL) {
            context->dataBuffer = newBuffer;
            context->buffer_size = newSize;
        }
    }

    pthread_mutex_unlock(&context->lock);
}

void removeLTEUEContext(NetworkInterface *network, int rnti) {
    pthread_rwlock_wrlock(&network->list_lock);

    for (size_t i = 0; i < network->count; ++i) {
        LTEUEContext *context = &network->contexts[i];
        if (pthread_mutex_trylock(&context->lock) == 0) { // Check if context can be locked
            pthread_mutex_unlock(&context->lock); // Unlock immediately after check

            pthread_rwlock_rdlock(&network->list_lock);
            for (size_t j = i; j < network->count - 1; ++j) {
                network->contexts[j] = network->contexts[j + 1];
            }
            context->buffer_size = INITIAL_BUFFER_SIZE;
            free(context->dataBuffer);
            context->dataBuffer = NULL;
            --network->count;
            pthread_rwlock_unlock(&network->list_lock);

            pthread_mutex_destroy(&context->lock); // Destroy the mutex
            break; // Remove only one UE per call for simplicity
        }
    }

    pthread_rwlock_unlock(&network->list_lock);
}

void freeNetworkInterface(NetworkInterface *network) {
    pthread_rwlock_wrlock(&network->list_lock);

    for (size_t i = 0; i < network->count; ++i) {
        LTEUEContext *context = &network->contexts[i];
        pthread_mutex_destroy(&context->lock);
        if (context->dataBuffer != NULL) {
            free(context->dataBuffer);
            context->dataBuffer = NULL;
        }
    }

    network->count = 0;
    pthread_rwlock_unlock(&network->list_lock);
    pthread_rwlock_destroy(&network->list_lock);

    for (size_t i = 0; i < MAX_UES; ++i) {
        pthread_mutex_destroy(&network->contexts[i].lock);
    }
}

// Example usage
int main() {
    NetworkInterface network;
    initializeNetworkInterface(&network);

    QoSParameters qosParams = { .qosFlowCount = 2 };
    addLTEUEContext(&network, 12345, 67890, qosParams);

    removeLTEUEContext(&network, 67890);
    freeNetworkInterface(&network);

    return 0;
}
