    RX_UE_INFORMATION_TAG ueInfoTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Hash table structure
#define HASH_TABLE_SIZE 1024
Node* hashTable[HASH_TABLE_SIZE];
pthread_mutex_t hashMutexes[HASH_TABLE_SIZE];

// Bloom filter (simplified)
unsigned int bloomFilter[HASH_TABLE_SIZE / 32];

// Comparator function for sorting by RNTI
int compareByRNTI(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pduA = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pduB = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return pduA->ueInfoTag.rnti - pduB->ueInfoTag.rnti;
}

// Hash function
unsigned int hashRNTI(uint16_t rnti) {
    return rnti % HASH_TABLE_SIZE;
}

// Initialize the system
void initializeSystem() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
        pthread_mutex_init(&hashMutexes[i], NULL);
    }
    memset(bloomFilter, 0, sizeof(bloomFilter));
}

// Add a new PDU to the list
void addPDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu->ueInfoTag.valid || pdu->ueInfoTag.rnti == 0) return;

    unsigned int index = hashRNTI(pdu->ueInfoTag.rnti);
    pthread_mutex_lock(&hashMutexes[index]);

    // Check for duplicates
    Node* current = hashTable[index];
    while (current) {
        if (current->data.ueInfoTag.rnti == pdu->ueInfoTag.rnti) {
            pthread_mutex_unlock(&hashMutexes[index]);
            return; // Duplicate RNTI found, do not add
        }
        current = current->next;
    }

    // Add new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&hashMutexes[index]);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    newNode->data = *pdu;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;

    // Set a random CRC flag
    newNode->data.crcIndicationRel8Tag.crcFlag = rand() % 2;

    pthread_mutex_unlock(&hashMutexes[index]);
}

// Update CRCFLAG based on conditions
void updateCRCFlags(void (*condition)(NFAPI_CRC_INDICATION_PDU_T*), void (*update)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&hashMutexes[i]);
        Node* current = hashTable[i];
        while (current) {
            if (condition(current->data)) {
                update(current->data);
            }
            current = current->next;
        }
        pthread_mutex_unlock(&hashMutexes[i]);
    }
}

// HTTP interface pseudo-code
void handleHTTPPutRequest(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    addPDU(pdu);
    // Respond with success or error
}

void handleHTTPDeleteRequest(uint16_t rnti) {
    unsigned int index = hashRNTI(rnti);
    pthread_mutex_lock(&hashMutexes[index]);

    Node **current = &hashTable[index], *temp;
    while (*current) {
        if ((*current)->data.ueInfoTag.rnti == rnti) {
            temp = *current;
            *current = (*current)->next;
            free(temp);
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&hashMutexes[index]);
}

// Health check endpoint pseudo-code
