#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char **data;
    size_t num_columns;
} DataRow;

void free_data_row(DataRow *row) {
    for (size_t i = 0; i < row->num_columns; ++i) {
        if (row->data[i]) {
            free(row->data[i]);
        }
    }
    free(row->data);
}

double moving_average(double *values, size_t length, size_t window_size) {
    double sum = 0.0;
    for (size_t i = 0; i < length && i < window_size; ++i) {
        sum += values[i];
    }

    double average = sum / (window_size > 0 ? (double)window_size : 1);

    for (size_t i = window_size; i < length; ++i) {
        sum += values[i] - (values[i - window_size] >= 0 ? values[i - window_size] : 0);
        average = sum / (window_size > 0 ? (double)window_size : 1);
    }

    return average;
}

void process_sales_data(const char *filename, size_t moving_average_window_size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open file");
        exit(EXIT_FAILURE);
    }

    DataRow *rows = NULL;
    size_t row_count = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        size_t num_columns = 1;

        // Count columns
        while (token) {
            ++num_columns;
            token = strtok(NULL, ",");
        }

        // Allocate or reallocate data row
        DataRow *new_row = realloc(rows, (row_count + 1) * sizeof(DataRow));
        if (!new_row) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        rows = new_row;

        // Reinitialize tokenization
        strcpy(line, line); // Reset line for strtok
        DataRow row;
        row.num_columns = num_columns;
        row.data = malloc(num_columns * sizeof(char *));
        if (!row.data) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        token = strtok(line, ",");
        size_t col_index = 0;
        while (token) {
            char *cell_data = strdup(token ? token : "0");
            row.data[col_index++] = cell_data;
            token = strtok(NULL, ",");
        }

        // Append to rows
        rows[row_count] = row;

        ++row_count;
    }

    fclose(file);

    for (size_t i = 0; i < row_count; ++i) {
        double *values = malloc(rows[i].num_columns * sizeof(double));
        if (!values) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        // Convert to numbers, treating empty strings as zero
        for (size_t j = 0; j < rows[i].num_columns; ++j) {
            values[j] = rows[i].data[j] ? atof(rows[i].data[j]) : 0.0;
        }

        double avg = moving_average(values, rows[i].num_columns, moving_average_window_size);
        printf("Row %zu: Moving Average = %.2f\n", i + 1, avg);

        free(values);
    }

    for (size_t i = 0; i < row_count; ++i) {
        free_data_row(&rows[i]);
    }

    free(rows);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <csv_file> <moving_average_window_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    size_t moving_average_window_size = strtoul(argv[2], NULL, 10);

    process_sales_data(filename, moving_average_window_size);

    return EXIT_SUCCESS;
}
