    L2_MESSAGE_TAG l2_message_tag;
} NFAPI_L2_MESSAGE_PDU_T;

// Node structure for linked list
typedef struct Node {
    NFAPI_L2_MESSAGE_PDU_T data;
    struct Node* next;
} Node;

// List structure with mutex and head pointer
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} MessageList;

// Hash table entry for unique PCI tracking
typedef struct HashEntry {
    int pci;
    bool in_use;
    struct HashEntry* next;
} HashEntry;

#define HASH_TABLE_SIZE 1024

HashEntry* hash_table[HASH_TABLE_SIZE];

unsigned int hash_function(int pci) {
    return pci % HASH_TABLE_SIZE;
}

bool insert_hash_entry(int pci) {
    unsigned int index = hash_function(pci);
    HashEntry* entry = hash_table[index];

    while (entry != NULL) {
        if (entry->pci == pci && entry->in_use) {
            return false; // PCI already exists
        }
        entry = entry->next;
    }

    // Create new entry
    entry = malloc(sizeof(HashEntry));
    if (!entry) return false;

    entry->pci = pci;
    entry->in_use = true;
    entry->next = hash_table[index];
    hash_table[index] = entry;

    return true;
}

bool delete_hash_entry(int pci) {
    unsigned int index = hash_function(pci);
    HashEntry* entry = hash_table[index];
    HashEntry* prev = NULL;

    while (entry != NULL) {
        if (entry->pci == pci && entry->in_use) {
            if (prev) {
                prev->next = entry->next;
            } else {
                hash_table[index] = entry->next;
            }
            free(entry);
            return true;
        }
        prev = entry;
        entry = entry->next;
    }

    return false;
}

MessageList* create_message_list() {
    MessageList* list = malloc(sizeof(MessageList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;

    // Initialize hash table
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }

    return list;
}

void destroy_message_list(MessageList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);

    // Clean up hash table
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashEntry* entry = hash_table[i];
        while (entry != NULL) {
            HashEntry* temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(list);
}

bool add_to_list(MessageList* list, NFAPI_L2_MESSAGE_PDU_T pdu) {
    if (!list || !insert_hash_entry(pdu.PCI)) return false;

    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        delete_hash_entry(pdu.PCI);
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

void update_preamble_flags(MessageList* list, int pci_condition) {
    if (!list) return;

    Node* current = list->head;
    while (current != NULL) {
        // Perform atomic update based on PCI condition
        if (current->data.PCI == pci_condition) {
            pthread_mutex_lock(&list->lock);  // Ensure atomicity for this update
            current->data.l2_message_tag.PREAMBLE_FLAG = /* new value */;
            pthread_mutex_unlock(&list->lock);
        }
        current = current->next;
    }
}

void sort_by_pci(MessageList* list) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    // Simple insertion sort for demonstration purposes
    Node *sorted = NULL, *current = list->head, *next_node = NULL;

    while (current != NULL) {
        next_node = current->next;

        if (!sorted || sorted->data.PCI >= current->data.PCI) {
            current->next = sorted;
            sorted = current;
        } else {
            Node* temp = sorted;
            while (temp->next && temp->next->data.PCI < current->data.PCI) {
                temp = temp->next;
            }
            current->next = temp->next;
            temp->next = current;
        }

        current = next_node;
    }

    list->head = sorted;

    pthread_mutex_unlock(&list->lock);
}

int main() {
    // Example usage
    MessageList* msg_list = create_message_list();
    if (!msg_list) return -1;

    NFAPI_L2_MESSAGE_PDU_T pdu = { .PCI = 10 }; // Populate with actual data
    add_to_list(msg_list, pdu);

    update_preamble_flags(msg_list, 10);
    sort_by_pci(msg_list);

    destroy_message_list(msg_list);
    return 0;
}
```

