    entry.CRCFLAG = (rand() % 100 < 50); // Example: 50% chance

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = entry;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry_by_rnti(CRCList* list, int rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void iterate_and_apply(CRCList* list, void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !operation) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        operation(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

