    if (current != NULL) {
        // Validate and update the configuration
        current->config = new_config; // Add validation logic here
    } else {
        printf("Cell ID not found for update.\n");
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_configuration(DynamicList* list, int cell_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->config.cell_id != cell_id) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }

    pthread_mutex_unlock(&list->lock);
}

void process_external_update(DynamicList* list, LTE_ENB_NODE_CONFIG_T config) {
    // Simulate processing delay or dropped messages
    update_configuration(list, config.cell_id, config); // Add error handling
