// Global dynamic list and mutex for thread safety
#define MAX_ENTRIES 10000
NFAPI_CRC_INDICATION_PDU_T *nfa_list = NULL;
size_t nfa_count = 0;
pthread_mutex_t lock;

// Function prototypes
void initialize_list();
int add_entry(const UE_INFORMATION *ue_info, int crc_flag);
int update_entry(unsigned long rnti, const UE_INFORMATION *ue_info, int crc_flag);
int remove_entry(unsigned long rnti);
void cleanup_list();

// Initialize the list
void initialize_list() {
    nfa_list = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ENTRIES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&lock, NULL);
}

// Add a new entry to the list
int add_entry(const UE_INFORMATION *ue_info, int crc_flag) {
    pthread_mutex_lock(&lock);

    if (nfa_count >= MAX_ENTRIES) {
        printf("Max capacity reached.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    for (size_t i = 0; i < nfa_count; ++i) {
        if (nfa_list[i].ue_info.RNTI == ue_info->RNTI) {
            printf("Entry already exists. Use update_entry instead.\n");
            pthread_mutex_unlock(&lock);
            return -2;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &nfa_list[nfa_count++];
    entry->ue_info.RNTI = ue_info->RNTI;
    strncpy(entry->ue_info.RX_UE_INFORMATION_TAG, ue_info->RX_UE_INFORMATION_TAG, sizeof(entry->ue_info.RX_UE_INFORMATION_TAG) - 1);
    entry->crc_indication_rel8.CRCFLAG = crc_flag;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Update an existing entry in the list
int update_entry(unsigned long rnti, const UE_INFORMATION *ue_info, int crc_flag) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < nfa_count; ++i) {
        if (nfa_list[i].ue_info.RNTI == rnti) {
            strncpy(nfa_list[i].ue_info.RX_UE_INFORMATION_TAG, ue_info->RX_UE_INFORMATION_TAG, sizeof(nfa_list[i].ue_info.RX_UE_INFORMATION_TAG) - 1);
            nfa_list[i].crc_indication_rel8.CRCFLAG = crc_flag;
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    printf("Entry not found.\n");
    pthread_mutex_unlock(&lock);
    return -1;
}

// Remove an entry from the list
int remove_entry(unsigned long rnti) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < nfa_count; ++i) {
        if (nfa_list[i].ue_info.RNTI == rnti) {
            memmove(&nfa_list[i], &nfa_list[i + 1], (nfa_count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            nfa_count--;
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    printf("Entry not found.\n");
    pthread_mutex_unlock(&lock);
    return -1;
}

// Clean up the list
void cleanup_list() {
    free(nfa_list);
    nfa_list = NULL;
    pthread_mutex_destroy(&lock);
}

int main() {
    initialize_list();

    // Example usage
    UE_INFORMATION ue_info = {12345, "ExampleTag"};
    add_entry(&ue_info, rand() % 2); // Random CRCFLAG for demonstration

    update_entry(12345, &(UE_INFORMATION){12345, "UpdatedTag"}, rand() % 2);
    remove_entry(12345);

    cleanup_list();
    return 0;
}
