#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

typedef struct Packet {
    uint32_t source_ip;
    uint32_t dest_ip;
    uint16_t source_port;
    uint16_t dest_port;
    uint8_t protocol_type; // e.g., 6 for TCP, 17 for UDP
    size_t payload_size;
    void* payload;
    uint16_t checksum;
    struct Packet* next;
} Packet;

typedef struct Queue {
    Packet* head;
    Packet* tail;
    size_t max_payload_size;
    size_t current_length;
    pthread_mutex_t lock;
} Queue;

uint16_t calculate_checksum(void* data, size_t len) {
    uint32_t sum = 0;
    uint8_t *ptr = (uint8_t*)data;
    while (len > 1) {
        sum += *(uint16_t *)ptr;
        ptr += 2;
        if ((sum & 0xFFFF0000) != 0)
            sum = (sum & 0x0000FFFF) + (sum >> 16);
        len -= 2;
    }
    if (len > 0)
        sum += *(uint8_t*)ptr;
    while ((sum >> 16) != 0)
        sum = (sum & 0xFFFF) + (sum >> 16);
    return ~sum;
}

Queue* create_queue(size_t max_payload_size) {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;

    queue->head = queue->tail = NULL;
    queue->max_payload_size = max_payload_size;
    queue->current_length = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

int enqueue_packet(Queue* queue, uint32_t src_ip, uint32_t dest_ip,
                   uint16_t src_port, uint16_t dest_port, 
                   uint8_t protocol_type, void* payload_data, size_t payload_size) {
    pthread_mutex_lock(&queue->lock);

    if (payload_size > queue->max_payload_size || !payload_data) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Invalid payload size or data
    }

    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) {
        pthread_mutex_unlock(&queue->lock);
        return -2; // Memory allocation failure
    }

    new_packet->source_ip = src_ip;
    new_packet->dest_ip = dest_ip;
    new_packet->source_port = src_port;
    new_packet->dest_port = dest_port;
    new_packet->protocol_type = protocol_type;
    new_packet->payload_size = payload_size;
    new_packet->payload = malloc(payload_size);
    if (!new_packet->payload) {
        free(new_packet);
        pthread_mutex_unlock(&queue->lock);
        return -2; // Memory allocation failure
    }

    memcpy(new_packet->payload, payload_data, payload_size);

    new_packet->checksum = calculate_checksum(payload_data, payload_size);
    new_packet->next = NULL;

    if (!queue->head) {
        queue->head = queue->tail = new_packet;
    } else {
        queue->tail->next = new_packet;
        queue->tail = new_packet;
    }

    queue->current_length++;

    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

Packet* dequeue_packet(Queue* queue) {
    pthread_mutex_lock(&queue->lock);

    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }

    Packet* packet = queue->head;
    queue->head = packet->next;

    if (!queue->head)
        queue->tail = NULL;

    queue->current_length--;

    pthread_mutex_unlock(&queue->lock);

    // Validate checksum
    uint16_t computed_checksum = calculate_checksum(packet->payload, packet->payload_size);
    if (computed_checksum != packet->checksum) {
        free(packet->payload);
        free(packet);
        return NULL; // Checksum mismatch, drop the packet
    }

    return packet;
}

void free_queue(Queue* queue) {
    pthread_mutex_lock(&queue->lock);

    Packet* current = queue->head;
    while (current) {
        Packet* next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }

    queue->head = queue->tail = NULL;
    queue->current_length = 0;

    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);

    free(queue);
}
