    char SourceAddress[16];
    char DestinationAddress[16];
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficFlowManager;

// Initialize the manager with a given number of elements
int initTrafficFlowManager(TrafficFlowManager *manager, size_t initialCapacity) {
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        return -1; // Mutex initialization failed
    }

    manager->capacity = initialCapacity;
    manager->size = 0;

    manager->flows = malloc(manager->capacity * sizeof(TrafficFlow));
    if (!manager->flows) {
        pthread_mutex_destroy(&manager->lock);
        return -2; // Memory allocation failed
    }

    return 0; // Success
}

// Resize the array when necessary
int resizeTrafficFlowManager(TrafficFlowManager *manager, size_t newCapacity) {
    TrafficFlow *newFlows = realloc(manager->flows, newCapacity * sizeof(TrafficFlow));
    if (!newFlows) {
        return -1; // Re-allocation failed
    }

    manager->flows = newFlows;
    manager->capacity = newCapacity;

    return 0; // Success
}

// Add a flow to the array with error handling and concurrency support
int addTrafficFlow(TrafficFlowManager *manager, int flowID, const char *sourceAddress, const char *destinationAddress) {
    if (flowID < 1 || flowID > 1000000) { // Example valid range check for FlowID
        return -3; // Invalid FlowID
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        int result = resizeTrafficFlowManager(manager, newCapacity);
        if (result != 0) {
            pthread_mutex_unlock(&manager->lock);
            return -4; // Resizing failed
        }
    }

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->flows[i].FlowID == flowID) {
            pthread_mutex_unlock(&manager->lock);
            return -5; // Duplicate FlowID
        }
    }

    TrafficFlow newFlow;
    newFlow.FlowID = flowID;
    snprintf(newFlow.SourceAddress, sizeof(newFlow.SourceAddress), "%s", sourceAddress);
    snprintf(newFlow.DestinationAddress, sizeof(newFlow.DestinationAddress), "%s", destinationAddress);

    manager->flows[manager->size++] = newFlow;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Free resources used by the manager
void freeTrafficFlowManager(TrafficFlowManager *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->flows);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
