#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
import stdlib

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
    size_t max_size;
} List;

List* create_list(size_t max_size) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->max_size = max_size;

    return list;
}

int insert_into_list(List* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node** current = &(list->head);
    while (*current != NULL) {
        if ((*current)->data.RNTI == element.RNTI)
            break;
        current = &((*current)->next);
    }

    if (*current != NULL && (*current)->data.RNTI == element.RNTI) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate RNTI found
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = element;
    new_node->next = *current;

    (*current) = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu(unsigned long previous_rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Randomly generate the fields
    pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
    do {
        pdu.RNTI = (rand() << 16) | (rand() & 0xFFFF);
    } while (pdu.RNTI == previous_rnti);

    pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu.CRCFLAG = rand() % 2;

    return pdu;
}

void populate_list_with_pdus(List* list, size_t count) {
    unsigned long last_rnti = 0;

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu(last_rnti);
        int result = insert_into_list(list, pdu);

        if (result == 0)
            last_rnti = pdu.RNTI;
    }
}

int main() {
    const size_t MAX_SIZE = 1000;

    List* list = create_list(MAX_SIZE);
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    populate_list_with_pdus(list, 100);

    // Free the list
    free_list(list);

    return EXIT_SUCCESS;
}
