void db_save_entry(NFAPI_CRC_INDICATION_PDU_T* entry);

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Thread-safe linked list to manage CRC indications.
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCIndicationList;

CRCIndicationList* create_list() {
    CRCIndicationList* list = nms_malloc(sizeof(CRCIndicationList));
    if (!list) {
        log_error("Failed to allocate memory for CRCIndicationList.");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(CRCIndicationList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        nms_free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    nms_free(list);
}

int add_entry(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!list) return -1;

    Node* new_node = nms_malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for new node.");
        return -2;
    }

    pthread_mutex_lock(&list->lock);
    memcpy(&(new_node->data), &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add to the front of the list
    new_node->next = list->head;
    list->head = new_node;

    db_save_entry(&(new_node->data));  // Persist in database

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(CRCIndicationList* list, int rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {  // Entry not found
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    if (prev == NULL) {  // Remove head node
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    nms_free(current);  // Free the memory of the removed node

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void print_entries(CRCIndicationList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        printf("RNTI: %d, Data: %s\n", current->data.rnti, current->data.data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    CRCIndicationList* list = create_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T entry1 = { .rnti = 123, .data = "First Entry" };
    NFAPI_CRC_INDICATION_PDU_T entry2 = { .rnti = 456, .data = "Second Entry" };

    add_entry(list, entry1);
    add_entry(list, entry2);

    print_entries(list);

    remove_entry(list, 123);
    print_entries(list);

    destroy_list(list);
    return 0;
}
