int fetch_and_validate_rnti(uint16_t *rnti, const uint16_t *whitelist, size_t whitelist_size) {
    // Simulate fetching RNTI with potential network latency
    sleep(1);  // Mock delay for network call

    // Randomly generate an RNTI value (in a real scenario this would be fetched from an external source)
    *rnti = rand() % 65536;

