    for (size_t i = 0; i < whitelist_size; ++i) {
        if (*rnti == whitelist[i]) {
            return 1; // Valid RNTI
        }
    }

    return 0; // Invalid RNTI
}

// Initialize the connection status list
void init_connection_status_list(ConnectionStatusList *list, size_t initial_capacity) {
    list->reports = (ConnectionStatusReport *)malloc(initial_capacity * sizeof(ConnectionStatusReport));
    if (!list->reports) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new connection status report
void add_connection_status(ConnectionStatusList *list, uint64_t uid, const char *ip) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        ConnectionStatusReport *new_reports = realloc(list->reports, new_capacity * sizeof(ConnectionStatusReport));
        if (!new_reports) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        list->reports = new_reports;
        list->capacity = new_capacity;
    }

    ConnectionStatusReport report = { .UID = uid, .last_active_session = time(NULL) };
    strncpy(report.IP, ip, sizeof(report.IP) - 1);

    // Check for duplicates and add if unique
    int is_duplicate = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->reports[i].UID == uid) {
            is_duplicate = 1;
            break;
        }
    }

    if (!is_duplicate) {
        list->reports[list->count++] = report;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to dynamically allocate and initialize NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_pdu_array(const uint16_t *whitelist, size_t whitelist_size) {
