    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand(); // Randomly set
        if (fetch_and_validate_rnti(&array[i].RNTI, whitelist, whitelist_size)) {
            array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
            array[i].CRCFLAG = rand() & 1; // Randomly 0 or 1
        } else {
            i--; // Retry if RNTI is invalid
        }
    }

    return array;
}

