['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CHANNELS 50000

typedef struct {
    int CHANNEL_ID;
    int SUBFRAME_NUMBER;
} TRANSPORT_CHANNEL_INFO_TAG;

typedef struct {
    char modulation_scheme[20];
    float coding_rate;
} TRANSPORT_FORMAT_TAG;

typedef struct {
    TRANSPORT_CHANNEL_INFO_TAG info_tag;
    TRANSPORT_FORMAT_TAG format_tag;
} PHY_TRANSPORT_CHANNEL_PDU_T;

typedef struct {
    PHY_TRANSPORT_CHANNEL_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} ChannelPool;

ChannelPool* init_channel_pool(size_t initial_size) {
    if (initial_size > MAX_CHANNELS) {
        fprintf(stderr, "Requested size exceeds maximum limit\n");
        return NULL;
    }

    ChannelPool *channel_pool = (ChannelPool *)malloc(sizeof(ChannelPool));
    if (!channel_pool) {
        log_error("Failed to allocate memory for channel pool\n");
        return NULL;
    }

    pthread_mutex_init(&channel_pool->lock, NULL);

    channel_pool->pool_size = initial_size;
    channel_pool->pool = (PHY_TRANSPORT_CHANNEL_PDU_T *)calloc(initial_size, sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
    if (!channel_pool->pool) {
        log_error("Failed to allocate memory for channel pool data\n");
        free(channel_pool);
        pthread_mutex_destroy(&channel_pool->lock);
        return NULL;
    }

    return channel_pool;
}

void release_channel_pool(ChannelPool *channel_pool) {
    if (channel_pool) {
        pthread_mutex_lock(&channel_pool->lock);

        if (channel_pool->pool) {
            free(channel_pool->pool);
        }

        pthread_mutex_unlock(&channel_pool->lock);
        pthread_mutex_destroy(&channel_pool->lock);
        free(channel_pool);
    }
}

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

PHY_TRANSPORT_CHANNEL_PDU_T* acquire_channel(ChannelPool *channel_pool, int channel_id, int subframe_number,
                                            const char *modulation_scheme, float coding_rate) {
    PHY_TRANSPORT_CHANNEL_PDU_T *pdu = NULL;

    pthread_mutex_lock(&channel_pool->lock);

    for (size_t i = 0; i < channel_pool->pool_size; ++i) {
        if (channel_pool->pool[i].info_tag.CHANNEL_ID == -1) { // Assuming -1 means available
            pdu = &channel_pool->pool[i];
            break;
        }
    }

    if (!pdu && channel_pool->pool_size < MAX_CHANNELS) {
        size_t new_size = channel_pool->pool_size * 2;
        PHY_TRANSPORT_CHANNEL_PDU_T *new_pool = realloc(channel_pool->pool, new_size * sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
        if (new_pool) {
            for (size_t i = channel_pool->pool_size; i < new_size; ++i) {
                new_pool[i].info_tag.CHANNEL_ID = -1; // Mark as available
            }
            channel_pool->pool_size = new_size;
            channel_pool->pool = new_pool;
            pdu = &channel_pool->pool[channel_pool->pool_size / 2];
        } else {
            log_error("Failed to reallocate memory for channel pool expansion\n");
        }
    }

    if (pdu) {
        pdu->info_tag.CHANNEL_ID = channel_id;
        pdu->info_tag.SUBFRAME_NUMBER = subframe_number;
        strncpy(pdu->format_tag.modulation_scheme, modulation_scheme, sizeof(pdu->format_tag.modulation_scheme) - 1);
        pdu->format_tag.coding_rate = coding_rate;
    }

    pthread_mutex_unlock(&channel_pool->lock);

    return pdu;
}

int main() {
    ChannelPool *pool = init_channel_pool(1000); // Initialize with a reasonable starting size
    if (!pool) {
        return EXIT_FAILURE;
    }

    PHY_TRANSPORT_CHANNEL_PDU_T *pdu = acquire_channel(pool, 1, 10, "QPSK", 0.75);
    if (pdu) {
        printf("Acquired channel: ID=%d, Subframe=%d\n", pdu->info_tag.CHANNEL_ID, pdu->info_tag.SUBFRAME_NUMBER);
    }

    release_channel_pool(pool);
    return EXIT_SUCCESS;
}
```

This code provides a robust foundation for managing a pool of `PHY_TRANSPORT_CHANNEL_PDU_T` structures. It includes dynamic memory allocation with error handling and logging, thread-safe access using mutexes, and efficient memory management strategies to handle up to 50,000 structures while allowing scalability.']

