```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_INTERFACES 1024

typedef struct {
    char id[64];
    char ipAddress[16];
    char subnetMask[16];
} NetworkInterface;

typedef struct {
    NetworkInterface interfaces[MAX_INTERFACES];
    int count;
    pthread_mutex_t lock;
    // Cache and other variables for network discovery service, etc.
} NetworkConfigManager;

NetworkConfigManager* create_network_config_manager() {
    NetworkConfigManager *manager = malloc(sizeof(NetworkConfigManager));
    if (!manager) return NULL;

    memset(manager->interfaces, 0, sizeof(manager->interfaces));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    // Initialize cache and other components here

    return manager;
}

int add_interface(NetworkConfigManager *manager, const char* id, const char* ipAddress, const char* subnetMask) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_INTERFACES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No space
    }

    for (int i = 0; i < manager->count; ++i) {
        if (!strcmp(manager->interfaces[i].ipAddress, ipAddress)) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate IP address
        }
    }

    strncpy(manager->interfaces[manager->count].id, id, sizeof(manager->interfaces[manager->count].id));
    strncpy(manager->interfaces[manager->count].ipAddress, ipAddress, sizeof(manager->interfaces[manager->count].ipAddress));
    strncpy(manager->interfaces[manager->count].subnetMask, subnetMask, sizeof(manager->interfaces[manager->count].subnetMask));

    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    // Integrate with network discovery service and retry logic

    return 0; // Success
}

int remove_interface(NetworkConfigManager *manager, const char* id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (!strcmp(manager->interfaces[i].id, id)) {
            memmove(&manager->interfaces[i], &manager->interfaces[i + 1], 
                    sizeof(NetworkInterface) * (manager->count - i - 1));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Not found
}

void free_network_config_manager(NetworkConfigManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
