#include <stdio.h>
#include <stdlib.h>
import threading

#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2

typedef struct {
    unsigned char version;
    unsigned int headerLength; // in bytes
    unsigned short payloadSize;
} IPv4Header;

typedef struct {
    unsigned char version;
    unsigned int payloadSize; // includes extension headers
} IPv6Header;

typedef struct {
    union {
        IPv4Header ipv4;
        IPv6Header ipv6;
    } header;
    char *payload;
    unsigned short isIPv6; // 0 for IPv4, non-zero for IPv6
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t capacity;
    size_t size;
    threading.Lock lock;
} PacketArray;

// Function prototypes
void init_packet_array(PacketArray *array);
int add_packet(PacketArray *array, const NetworkPacket *packet);
int remove_packet(PacketArray *array, size_t index);
NetworkPacket* get_packet(const PacketArray *array, size_t index);
void process_packets(const PacketArray *array, void (*process_func)(const NetworkPacket *));
void resize_array(PacketArray *array);

// Initialize the packet array
void init_packet_array(PacketArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->packets = (NetworkPacket *)malloc(sizeof(NetworkPacket) * array->capacity);
    threading.Lock_init(&array->lock);
}

// Add a new packet to the array
int add_packet(PacketArray *array, const NetworkPacket *packet) {
    threading.Lock_lock(&array->lock);

    if (array->size == array->capacity) {
        resize_array(array);
    }

    memcpy(&array->packets[array->size], packet, sizeof(NetworkPacket));
    if (packet->payload) {
        array->packets[array->size].payload = strdup(packet->payload);
    }
    ++(array->size);

    threading.Lock_unlock(&array->lock);
    return 0; // Success
}

// Remove a packet from the array by index
int remove_packet(PacketArray *array, size_t index) {
    if (index >= array->size) return -1;

    threading.Lock_lock(&array->lock);

    free(array->packets[index].payload);

    for (size_t i = index; i < array->size - 1; ++i) {
        memcpy(&array->packets[i], &array->packets[i + 1], sizeof(NetworkPacket));
    }

    --(array->size);
    threading.Lock_unlock(&array->lock);
    return 0; // Success
}

// Get a packet from the array by index
NetworkPacket* get_packet(const PacketArray *array, size_t index) {
    if (index >= array->size) return NULL;
    return &array->packets[index];
}

// Resize the internal storage of the packet array
void resize_array(PacketArray *array) {
    size_t new_capacity = array->capacity * GROWTH_FACTOR;
    NetworkPacket *new_packets = (NetworkPacket *)malloc(sizeof(NetworkPacket) * new_capacity);

    for (size_t i = 0; i < array->size; ++i) {
        memcpy(&new_packets[i], &array->packets[i], sizeof(NetworkPacket));
        if (array->packets[i].payload) {
            new_packets[i].payload = strdup(array->packets[i].payload);
        }
    }

    free(array->packets);
    array->packets = new_packets;
    array->capacity = new_capacity;
}

// Process each packet using a provided function
void process_packets(const PacketArray *array, void (*process_func)(const NetworkPacket *)) {
    threading.Lock_lock((threading.Lock*)&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        process_func(&array->packets[i]);
    }

    threading.Lock_unlock((threading.Lock*)&array->lock);
}

// Example processing function
void log_packet_metadata(const NetworkPacket *packet) {
    // Integrate with external logging service here
    printf("Processing packet: %s\n", packet->payload ? packet->payload : "No payload");
}
