    clock_gettime(CLOCK_REALTIME, &ts);
    return (unsigned long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

int fill_buffer(unsigned char *buffer, size_t size, unsigned long seed) {
    srand(seed ^ (intptr_t)buffer);
    for (size_t i = 0; i < size; ++i) {
        buffer[i] = rand() % 256;
    }
    return 1;
}

