        strlen((char*)frame->phy_rlc_rx_frame.RLC_AM_PDU) != BUFFER_SIZE ||
        strlen((char*)frame->phy_rlc_rx_frame.RLC_PDCP_PDU) != BUFFER_SIZE) {
        fprintf(stderr, "Buffer validation failed: Buffer size mismatch\n");
        return 0;
    }
    return 1;
