    LTE_PHY_RX_FRAME* new_frame = (LTE_PHY_RX_FRAME*)malloc(sizeof(LTE_PHY_RX_FRAME));
    if (!new_frame) {
        fprintf(stderr, "Memory allocation failed for LTE_PHY_RX_FRAME\n");
        return 0;
    }

    memset(new_frame, 0, sizeof(LTE_PHY_RX_FRAME));

    new_frame->phy_rlc_rx_frame.MAC_PDU = (unsigned char*)malloc(BUFFER_SIZE);
    new_frame->phy_rlc_rx_frame.RLC_AM_PDU = (unsigned char*)malloc(BUFFER_SIZE);
    new_frame->phy_rlc_rx_frame.RLC_PDCP_PDU = (unsigned char*)malloc(BUFFER_SIZE);

    if (!new_frame->phy_rlc_rx_frame.MAC_PDU || !new_frame->phy_rlc_rx_frame.RLC_AM_PDU || !new_frame->phy_rlc_rx_frame.RLC_PDCP_PDU) {
        fprintf(stderr, "Memory allocation failed for buffers\n");
        free(new_frame);
        return 0;
    }

    fill_buffer(new_frame->phy_rlc_rx_frame.MAC_PDU, BUFFER_SIZE, seed);
    fill_buffer(new_frame->phy_rlc_rx_frame.RLC_AM_PDU, BUFFER_SIZE, seed);
    fill_buffer(new_frame->phy_rlc_rx_frame.RLC_PDCP_PDU, BUFFER_SIZE, seed);

    if (!validate_frame(new_frame)) {
        free(new_frame->phy_rlc_rx_frame.MAC_PDU);
        free(new_frame->phy_rlc_rx_frame.RLC_AM_PDU);
        free(new_frame->phy_rlc_rx_frame.RLC_PDCP_PDU);
        free(new_frame);
        return 0;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for Node\n");
        free(new_frame->phy_rlc_rx_frame.MAC_PDU);
        free(new_frame->phy_rlc_rx_frame.RLC_AM_PDU);
        free(new_frame->phy_rlc_rx_frame.RLC_PDCP_PDU);
        free(new_frame);
        return 0;
    }

    new_node->frame = *new_frame;
    new_node->next = head;
    head = new_node;

    log_message("Successfully added LTE_PHY_RX_FRAME to list");
    return 1;
}

void cleanup_list() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->frame.phy_rlc_rx_frame.MAC_PDU);
        free(current->frame.phy_rlc_rx_frame.RLC_AM_PDU);
        free(current->frame.phy_rlc_rx_frame.RLC_PDCP_PDU);
        free(current);
        current = next;
    }
}

int main() {
    // Example usage
    if (add_lte_phy_rx_frame_to_list()) {
        log_message("Frame added successfully");
    } else {
        log_message("Failed to add frame");
    }

    cleanup_list();
    return 0;
}
