        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->count = 0;
    da->capacity = initialCapacity;
}

// Function to destroy the dynamic array
void freeDynamicArray(DynamicArray *da) {
    free(da->array);
    da->array = NULL;
    da->count = 0;
    da->capacity = 0;
}

// Function to resize the dynamic array
static void ensureCapacity(DynamicArray *da, size_t minCapacity) {
    if (minCapacity > da->capacity) {
        size_t newCapacity = da->capacity == 0 ? 1 : da->capacity * 2;
        while (newCapacity < minCapacity) {
            newCapacity *= 2;
        }

        NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*) realloc(da->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        da->array = newArray;
        da->capacity = newCapacity;
    }
}

// Function to add a new element
void addElement(DynamicArray *da, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    ensureCapacity(da, da->count + 1);

    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].crcTag.RNTI == RNTI) {
            // Update existing element
            da->array[i].crcTag.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            da->array[i].crcTag.RNTI = RNTI;
            da->array[i].CRCFLAG = rand() % 256; // Randomly set CRCFLAG between 0 and 255
            return;
        }
    }

    // Add new element
    da->array[da->count].crcTag.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    da->array[da->count].crcTag.RNTI = RNTI;
    da->array[da->count].CRCFLAG = rand() % 256; // Randomly set CRCFLAG between 0 and 255
    ++da->count;
}

// Function to retrieve an element by RNTI
bool getElementByRNTI(DynamicArray *da, unsigned int RNTI, NFAPI_CRC_INDICATION_PDU_T *result) {
    if (!da || !result) return false;

    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].crcTag.RNTI == RNTI) {
            *result = da->array[i];
            return true;
        }
    }

    return false;
}

// Example of usage
int main() {
    DynamicArray da;
    initDynamicArray(&da, 10);

    addElement(&da, 1234, 5678);
    NFAPI_CRC_INDICATION_PDU_T result;

    if (getElementByRNTI(&da, 5678, &result)) {
        printf("Found: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n", 
               result.crcTag.RX_UE_INFORMATION_TAG, result.crcTag.RNTI, result.CRCFLAG);
    } else {
        printf("Element not found\n");
    }

    freeDynamicArray(&da);

    return 0;
}
