['Below is the implementation of a dynamic array for managing `TrafficEvent` structures in C. This code includes initialization, adding, removing, and retrieving events, while ensuring efficient memory management and thread safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct {
    long timestamp;
    EventType eventType;
    char metadata[256];  // Large metadata field
} TrafficEvent;

typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread safety
} TrafficArray;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

TrafficArray* initTrafficArray() {
    TrafficArray *array = (TrafficArray *)malloc(sizeof(TrafficArray));
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->events = (TrafficEvent *)malloc(array->capacity * sizeof(TrafficEvent));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resizeTrafficArray(TrafficArray *array) {
    size_t new_capacity = array->capacity * GROWTH_FACTOR;
    TrafficEvent *new_events = (TrafficEvent *)realloc(array->events, new_capacity * sizeof(TrafficEvent));
    if (new_events != NULL) {
        array->events = new_events;
        array->capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Failed to resize the traffic array.\n");
        exit(EXIT_FAILURE);
    }
}

void addTrafficEvent(TrafficArray *array, TrafficEvent event) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resizeTrafficArray(array);
    }

    array->events[array->count++] = event;

    pthread_mutex_unlock(&array->lock);
}

void removeTrafficEvent(TrafficArray *array, size_t index) {
    if (index >= array->count) {
        return;  // Invalid index
    }

    pthread_mutex_lock(&array->lock);

    memmove(&array->events[index], &array->events[index + 1], (array->count - index - 1) * sizeof(TrafficEvent));
    array->count--;

    pthread_mutex_unlock(&array->lock);
}

TrafficEvent* getTrafficEvent(TrafficArray *array, size_t index) {
    if (index >= array->count) {
        return NULL;  // Invalid index
    }

    pthread_mutex_lock(&array->lock);

    TrafficEvent *event = &array->events[index];

    pthread_mutex_unlock(&array->lock);
    return event;
}

void freeTrafficArray(TrafficArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->events);
    free(array);
}

// Example usage
int main() {
    TrafficArray *trafficArray = initTrafficArray();

    for (size_t i = 0; i < 20; ++i) {
        TrafficEvent event = { .timestamp = i, .eventType = EVENT_TYPE_A };
        snprintf(event.metadata, sizeof(event.metadata), "Metadata for event %zu", i);
        addTrafficEvent(trafficArray, event);
    }

    TrafficEvent *retrievedEvent = getTrafficEvent(trafficArray, 5);
    if (retrievedEvent) {
        printf("Retrieved Event: Timestamp=%ld, Type=%d\n", retrievedEvent->timestamp, retrievedEvent->eventType);
    }

    removeTrafficEvent(trafficArray, 5);

    freeTrafficArray(trafficArray);
    return 0;
}
```

### Key Features:
- **Dynamic Resizing**: The array doubles its capacity when full, ensuring efficient growth.
- **Thread Safety**: Uses a mutex to protect shared data structures during concurrent access.
- **Memory Management**: Efficiently reallocates memory and handles allocation failures gracefully.
- **Error Handling**: Checks for invalid indices in remove and get operations.']

['Here is an example implementation of a C function that manages a dynamically allocated array and a thread-safe linked list for `NFAPI_CRC_INDICATION_PDU_T` structures as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_ELEMENTS 100000

typedef struct {
    // Assuming these are defined elsewhere with appropriate data types.
    uint16_t RNTI;
    uint8_t CRCFLAG; 
} NFAPI_CRC_INDICATION_PDU_T;

