typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ThreadSafeList;

ThreadSafeList list = {NULL, PTHREAD_MUTEX_INITIALIZER};

void init_list(ThreadSafeList* list) {
    list->head = NULL;
}

bool add_element(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        if (current->pdu.RNTI == pdu.RNTI) {
            printf("Warning: Duplicate RNTI encountered. Skipping insertion.\n");
            pthread_mutex_unlock(&list.lock);
            return false;
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list.lock);
        fprintf(stderr, "Memory allocation failed\n");
        return false;
    }

    memcpy(&new_node->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list.head;
    list.head = new_node;

    pthread_mutex_unlock(&list.lock);
    return true;
}

bool update_element(uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        if (current->pdu.RNTI == rnti) {
            memcpy(&current->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list.lock);
            return true;
        }
        current = current->next;
    }

    printf("Warning: RNTI not found. Inserting as new element.\n");
    if (!add_element(pdu)) {
        pthread_mutex_unlock(&list.lock);
        return false;
    }

    pthread_mutex_unlock(&list.lock);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_element(uint16_t rnti) {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        if (current->pdu.RNTI == rnti) {
            pthread_mutex_unlock(&list.lock);
            return &current->pdu;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list.lock);
    return NULL;
}

void iterate_and_print() {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %d\n", current->pdu.RNTI, current->pdu.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list.lock);
}

void cleanup_list() {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list.head = NULL;
    pthread_mutex_unlock(&list.lock);
}

// Assume this function is used to handle incoming data streams
void process_data_stream(void (*data_callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    // Implementation of handling incoming data stream with callback
}

int main() {
    init_list(&list);

    // Example usage and testing

    NFAPI_CRC_INDICATION_PDU_T pdu = {1234, 1}; // Example RNTI and CRCFLAG
    add_element(pdu);

    pdu.CRCFLAG = 0; // Update example
    update_element(1234, pdu);

    NFAPI_CRC_INDICATION_PDU_T* retrieved_pdu = retrieve_element(1234);
    if (retrieved_pdu) {
        printf("Retrieved RNTI: %u, CRCFLAG: %d\n", retrieved_pdu->RNTI, retrieved_pdu->CRCFLAG);
    }

    iterate_and_print();
    cleanup_list();

    return 0;
}
```

### Key Points:

- **Thread Safety**: A mutex lock ensures thread-safe operations on the linked list.
- **Unique RNTIs**: The function checks for duplicate `RNTI` values and logs a warning if a duplicate is found.
- **Memory Management**: Proper allocation and deallocation of nodes are handled to avoid memory leaks.
- **Data Processing Integration**: A placeholder for handling incoming data streams indicates integration with external processing pipelines.
- **Scalability Considerations**: The design can handle up to 100,000 elements efficiently by using a linked list and ensuring thread safety.

This code provides a robust starting point for managing `NFAPI_CRC_INDICATION_PDU_T` structures in a concurrent environment.']

