typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Comparator function for sorting based on TIMESTAMP
int compare_timestamp(const void* a, const void* b) {
    NR_UE_MEASUREMENT_REPORT_PDU* pduA = (NR_UE_MEASUREMENT_REPORT_PDU*)a;
    NR_UE_MEASUREMENT_REPORT_PDU* pduB = (NR_UE_MEASUREMENT_REPORT_PDU*)b;
    return (int)(pduA->TIMESTAMP - pduB->TIMESTAMP);
}

// Function to verify the integrity of each structure
int verify_structure(NR_UE_MEASUREMENT_REPORT_PDU* pdu) {
    // Example validation: Ensure TIMESTAMP is set and within a reasonable range
    if (pdu == NULL || pdu->TIMESTAMP < 0) return 0;
    return 1;
}

// Function to manage dynamic array of NR UE Measurement Report PDU structures
NR_UE_MEASUREMENT_REPORT_PDU* manage_ue_measurement_report_array(size_t max_count, unsigned int target_rnti) {
    NR_UE_MEASUREMENT_REPORT_PDU* array = NULL;
    size_t count = 0;
    time_t current_time;

    while (count < max_count) {
        for (int attempt = 0; attempt < MAX_RETRY_ATTEMPTS; ++attempt) {
            NR_UE_MEASUREMENT_REPORT_PDU* temp_array = realloc(array, sizeof(NR_UE_MEASUREMENT_REPORT_PDU) * (count + 1));
            if (temp_array != NULL) {
                array = temp_array;
                break;
            } else {
                printf("Allocation failed, attempt %d\n", attempt + 1);
                if (attempt < MAX_RETRY_ATTEMPTS - 1) {
                    struct timespec sleep_time = {RETRY_INTERVAL_MS / 1000, (RETRY_INTERVAL_MS * 1000) % 1000000};
                    nanosleep(&sleep_time, NULL);
                }
            }
        }

        if (array == NULL) return NULL; // Allocation failed after retries

        NR_UE_MEASUREMENT_REPORT_PDU* pdu = &array[count];
        pdu->MEASUREMENT_REPORT_TAG = rand();
        pdu->RNTI = rand() % 1000;
        current_time = time(NULL);
        pdu->TIMESTAMP = current_time;

        if (!verify_structure(pdu)) {
            printf("Structure verification failed for index %zu\n", count);
            free(array);
            return NULL;
        }

        ++count;
    }

    // Sorting based on TIMESTAMP
    qsort(array, count, sizeof(NR_UE_MEASUREMENT_REPORT_PDU), compare_timestamp);

    // Filtering by RNTI if needed
    if (target_rnti != 0) {
        size_t new_count = 0;
        for (size_t i = 0; i < count; ++i) {
            if (array[i].RNTI == target_rnti) {
                if (new_count == 0) {
                    array = realloc(array, sizeof(NR_UE_MEASUREMENT_REPORT_PDU));
                } else {
                    NR_UE_MEASUREMENT_REPORT_PDU* temp_array = realloc(array, sizeof(NR_UE_MEASUREMENT_REPORT_PDU) * (new_count + 1));
                    if (temp_array != NULL) {
                        array = temp_array;
                    } else {
                        free(array);
                        return NULL; // Allocation failed
                    }
                }
                array[new_count++] = array[i];
            }
        }
        count = new_count;
    }

    return array;
}

// Example usage
int main() {
    NR_UE_MEASUREMENT_REPORT_PDU* report_array = manage_ue_measurement_report_array(10, 0);
    if (report_array != NULL) {
        for (size_t i = 0; i < 10; ++i) {
            printf("RNTI: %u, TIMESTAMP: %ld\n", report_array[i].RNTI, report_array[i].TIMESTAMP);
        }
        free(report_array);
    } else {
        printf("Failed to allocate memory for measurement reports.\n");
    }
    return 0;
}
