}

void garbage_collect(List* list, size_t threshold) {
    pthread_mutex_lock(&list->lock);

    if (list->size < threshold) return;

    Node** current = &list->head;
    while (*current && list->size > threshold) {
        Node* temp = *current;
        *current = (*current)->next;
        free(temp);
        list->size--;
    }

