#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS = 0,
    ERROR_MEMORY_ALLOCATION_FAILED,
    ERROR_INVALID_INPUT
} ErrorCode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    printf("%s\n", message);
}

ErrorCode resize_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t *current_size) {
    size_t new_size = (*current_size) * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array) {
        log_message("Memory allocation failed during resize.");
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    *current_size = new_size;
    *array = new_array;
    log_message("Array resized successfully.");
    return SUCCESS;
}

ErrorCode manage_crc_indications(
    NFAPI_CRC_INDICATION_PDU_T **array,
    size_t initial_size,
    int *ue_tags,
    unsigned int *rnti_tags,
    int *crc_flags,
    size_t num_entries) {

    pthread_mutex_lock(&lock);

    if (!array || !ue_tags || !rnti_tags || !crc_flags || num_entries == 0) {
        log_message("Invalid input parameters.");
        pthread_mutex_unlock(&lock);
        return ERROR_INVALID_INPUT;
    }

    *array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        log_message("Initial memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    size_t current_size = initial_size;
    size_t count = 0;

    for (size_t i = 0; i < num_entries; ++i) {
        if (count >= current_size) {
            ErrorCode resize_result = resize_array(array, &current_size);
            if (resize_result != SUCCESS) {
                free(*array);
                pthread_mutex_unlock(&lock);
                return resize_result;
            }
        }

        unsigned int rnti = rnti_tags[i];
        for (size_t j = 0; j < count; ++j) {
            if ((*array)[j].RNTI == rnti) {
                log_message("Duplicate RNTI found, skipping entry.");
                continue;
            }
        }

        (*array)[count].RX_UE_INFORMATION_TAG = ue_tags[i];
        (*array)[count].RNTI = rnti;
        (*array)[count].CRC_INDICATION_REL8_TAG = crc_flags[i];

        ++count;
    }

    pthread_mutex_unlock(&lock);
    return SUCCESS;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *crc_array = NULL;
    int ue_tags[] = {1, 2, 3};
    unsigned int rnti_tags[] = {1001, 1002, 1003};
    int crc_flags[] = {10, 20, 30};

    ErrorCode result = manage_crc_indications(&crc_array, 2, ue_tags, rnti_tags, crc_flags, 3);

    if (result == SUCCESS) {
        for (size_t i = 0; i < 3; ++i) {
            printf("Entry %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%u, CRC_INDICATION_REL8_TAG=%d\n",
                   i, crc_array[i].RX_UE_INFORMATION_TAG, crc_array[i].RNTI, crc_array[i].CRC_INDICATION_REL8_TAG);
        }
    } else {
        printf("Error occurred: %d\n", result);
    }

    free(crc_array);
    return 0;
}
