void log_error(const char* message);

// Non-blocking random number generator using PCG
uint64_t pcg32_random_r(uint64_t* state) {
    uint64_t x = *state;
    x ^= x >> 18;                
    x *= 0x6C8E9CF570932BD5ULL; 
    *state = x;                  
    return (x >> 27) + (x << 37);
}

int is_error(uint32_t packet_size, uint8_t frame_type) {
    static uint64_t rng_state = time(NULL); // Seed with current time
    float error_rate = config.base_error_rate;

    // Adjust error rate logarithmically based on packet size and type B frames
    if (frame_type == 0x02) { // Assuming Type B is represented by 0x02
        error_rate += log2f(packet_size + 1) * config.error_scaling_factor;
    }

    float random_value = pcg32_random_r(&rng_state);
    return (random_value / UINT64_MAX) < error_rate;
}

void populateNFARxIndications(NFAPI_CRC_INDICATION_PDU_T* indications, size_t num_frames,
                              uint16_t rnti_start, uint8_t frame_type_pattern) {
