        indication->RNTI = rnti_start + (i % 1000); // Example RNTI cycling pattern
        indication->CRC_INDICATION_REL8_TAG = frame_type_pattern;

        uint32_t packet_size = rand() % config.max_frame_size; // Simulated random packet size

        // Determine CRCFLAG based on error simulation logic
        if (is_error(packet_size, frame_type_pattern)) {
            indication->CRCFLAG = 1;
