#define MAX_FRAMES 10000000
#define FRAME_TYPE_A 0
#define FRAME_TYPE_B 1

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    double loadFactor;     // Simulated real-time network load
    double signalStrength; // Simulated real-time signal strength
    int maxPacketSize;     // Maximum allowable packet size for the system
} NetworkConditions;

pthread_mutex_t lock;

// Function to simulate error rate based on frame type and size
double calculateErrorRate(int frameType, uint16_t PacketSize, NetworkConditions conditions) {
    double baseProbability = (frameType == FRAME_TYPE_A) ? 0.01 : 0.02;
    double scalingFactor = log(PacketSize + 1) / log(conditions.maxPacketSize + 1);
    return baseProbability * scalingFactor * conditions.loadFactor / conditions.signalStrength;
}

// Function to populate NFAPI_CRC_INDICATION_PDU_T structures
void populateNFARxIndications(NFAPI_CRC_INDICATION_PDU_T* frameArray, size_t numFrames, NetworkConditions conditions) {
    if (frameArray == NULL || numFrames > MAX_FRAMES) return;

    pthread_mutex_lock(&lock);

    srand(time(NULL));
    for (size_t i = 0; i < numFrames; ++i) {
        uint16_t PacketSize = rand() % conditions.maxPacketSize + 1;
        int frameType = rand() % 2; // Randomly choose between FRAME_TYPE_A and FRAME_TYPE_B

        double errorRate = calculateErrorRate(frameType, PacketSize, conditions);
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = (uint16_t)rand(),
            .RNTI = (uint16_t)rand(),
            .CRC_INDICATION_REL8_TAG = frameType + 1,
            .CRCFLAG = ((double)rand() / RAND_MAX < errorRate) ? 0xFF : 0x00
        };

        // Check if PacketSize exceeds max allowed size and handle gracefully
        if (PacketSize > conditions.maxPacketSize) {
            fprintf(stderr, "Error: Packet size %u exceeds maximum limit.\n", PacketSize);
            continue; // Skip this iteration or handle error as needed
        }

        frameArray[i] = pdu;
    }

    pthread_mutex_unlock(&lock);

    printf("Populated %zu frames with simulated conditions.\n", numFrames);
}

// Function to log performance metrics and errors (minimal impact design)
void logPerformanceMetrics(size_t numFrames, NetworkConditions conditions) {
    static FILE *logFile = NULL;

    if (!logFile) {
        logFile = fopen("performance_log.txt", "a");
        if (!logFile) return;
    }

    fprintf(logFile, "Logged %zu frames processed under load %.2f and signal strength %.2f\n",
            numFrames, conditions.loadFactor, conditions.signalStrength);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    NetworkConditions currentConditions = {0.75, 1.5, 1500}; // Example conditions
    size_t framesToProcess = 100000; // Number of frames to process

    NFAPI_CRC_INDICATION_PDU_T* frameArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(framesToProcess * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!frameArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    populateNFARxIndications(frameArray, framesToProcess, currentConditions);
    logPerformanceMetrics(framesToProcess, currentConditions);

    free(frameArray);
    pthread_mutex_destroy(&lock);

    return 0;
}
