    pthread_mutex_init(&da->lock, NULL);
    da->capacity = 10; // Initial capacity
    da->size = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Destroy the dynamic array and free resources
void destroy_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

// Resize the internal storage when needed
static void resize_if_needed(DynamicArray* da) {
    if (da->size >= da->capacity) {
        da->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array != NULL) {
            pthread_mutex_lock(&da->lock);
            da->array = new_array;
            pthread_mutex_unlock(&da->lock);
        } else {
            fprintf(stderr, "Memory allocation failed during resize.\n");
            exit(EXIT_FAILURE); // Handle allocation failure appropriately in a real system
        }
    }
}

// Add an element to the dynamic array
int add_element(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);
    resize_if_needed(da);
    da->array[da->size++] = element;
    pthread_mutex_unlock(&da->lock);
    return 0; // Return an error code if needed
}

// Retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T get_element(const DynamicArray* da, size_t index) {
    if (index >= da->size) {
        fprintf(stderr, "Index out of bounds.\n");
        exit(EXIT_FAILURE); // Handle out-of-bounds access appropriately
    }
    pthread_mutex_lock(&da->lock);
    NFAPI_CRC_INDICATION_PDU_T element = da->array[index];
    pthread_mutex_unlock(&da->lock);
    return element;
}

// Remove an element by index
int remove_element(DynamicArray* da, size_t index) {
    if (index >= da->size) {
        fprintf(stderr, "Index out of bounds.\n");
        return -1; // Return error code for invalid operation
    }
    pthread_mutex_lock(&da->lock);
    memmove(&da->array[index], &da->array[index + 1], (da->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size--;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

// Example usage
