// Error codes
#define SUCCESS 0
#define MEM_ALLOC_FAILURE -1
#define DUPLICATE_RNTI -2
#define INDEX_OUT_OF_BOUNDS -3

typedef struct {
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG; // Assuming a simple integer for the flag, can be adapted as needed.
} CRC_INDICATION_REL8_TAG;

