    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// List structure with thread lock for synchronization
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFList;

NFList* create_list() {
    NFList* list = (NFList*)malloc(sizeof(NFList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_element(NFList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list) return MEM_ALLOC_FAILURE;

    pthread_mutex_lock(&list->lock);

    // Check for duplicate RNTI
    Node* current = list->head;
    while (current) {
        if (current->data.ue_info.RNTI == element.ue_info.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return DUPLICATE_RNTI;
        }
        current = current->next;
    }

    // Add new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return MEM_ALLOC_FAILURE;
    }
    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return SUCCESS;
}

int update_element_by_rnti(NFList* list, int rnti, NFAPI_CRC_INDICATION_PDU_T updated_element) {
    if (!list) return MEM_ALLOC_FAILURE;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.ue_info.RNTI == rnti) {
            current->data = updated_element;
            pthread_mutex_unlock(&list->lock);
            return SUCCESS;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return INDEX_OUT_OF_BOUNDS;
}

int remove_element_by_index(NFList* list, int index) {
    if (!list || index < 0) return INDEX_OUT_OF_BOUNDS;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    for (int i = 0; current && i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return INDEX_OUT_OF_BOUNDS;
    }

    if (!prev) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
    return SUCCESS;
}

void destroy_list(NFList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void log_error(int error_code) {
    // Simple logging implementation, can be extended with file I/O or other logging mechanisms
    switch (error_code) {
        case MEM_ALLOC_FAILURE:
            printf("Error: Memory allocation failure\n");
            break;
        case DUPLICATE_RNTI:
            printf("Error: Duplicate RNTI detected\n");
            break;
        case INDEX_OUT_OF_BOUNDS:
            printf("Error: Index out of bounds\n");
            break;
        default:
            printf("Unknown error occurred\n");
    }
}

// Example usage
int main() {
    NFList* list = create_list();
    if (!list) {
        log_error(MEM_ALLOC_FAILURE);
        return MEM_ALLOC_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T element1 = { .ue_info = { .RNTI = 123 }, .crc_ind_tag = { .CRCFLAG = 0 } };
    int result = add_element(list, element1);
    if (result != SUCCESS) log_error(result);

    // Add more elements and perform updates/removals as needed

    destroy_list(list);
    return 0;
}
