    dyn_array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dyn_array->capacity = initial_capacity;
    dyn_array->count = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);
    return dyn_array;
}

// Resize the dynamic array
void resize_dynamic_array(DynamicArray *dyn_array) {
    size_t new_capacity = dyn_array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }
}

// Add element to the dynamic array
void add_element(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&dyn_array->lock);
    if (dyn_array->count == dyn_array->capacity) {
        resize_dynamic_array(dyn_array);
    }
    dyn_array->array[dyn_array->count++] = element;
    pthread_mutex_unlock(&dyn_array->lock);
}

// Retrieve element by index
NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray *dyn_array, size_t index) {
    if (index >= dyn_array->count) return NULL;
    return &dyn_array->array[index];
}

// Remove element by index
void remove_element(DynamicArray *dyn_array, size_t index) {
    pthread_mutex_lock(&dyn_array->lock);
    if (index < dyn_array->count) {
        for (size_t i = index; i < dyn_array->count - 1; ++i) {
            dyn_array->array[i] = dyn_array->array[i + 1];
        }
        --dyn_array->count;
    }
    pthread_mutex_unlock(&dyn_array->lock);
}

// Free dynamic array resources
void free_dynamic_array(DynamicArray *dyn_array) {
    pthread_mutex_destroy(&dyn_array->lock);
    free(dyn_array->array);
    free(dyn_array);
}
```

