#include <stdio.h>
#include <stdlib.h>
import stdlib.h> // Include standard library functions

#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_ENTRIES 5000

typedef struct {
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
} IP_Pair;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG; // Assuming CRCFLAG is a single byte
} CRC_INDICATION_REL8_TAG;

typedef struct {
    IP_Pair ip_pair;
    CRC_INDICATION_REL8_TAG crc_indication;
} TCP_CONNECTION_RECORD;

typedef struct {
    TCP_CONNECTION_RECORD *records;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

int compare_ip_pairs(const void *a, const void *b) {
    IP_Pair *ip_a = (IP_Pair *)a;
    IP_Pair *ip_b = (IP_Pair *)b;
    return strcmp(ip_a->SOURCE_IP, ip_b->SOURCE_IP) == 0 &&
           strcmp(ip_a->DESTINATION_IP, ip_b->DESTINATION_IP) == 0;
}

int ip_pair_exists(DynamicArray *array, const IP_Pair *new_ip) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (compare_ip_pairs(&array->records[i].ip_pair, new_ip) == 0) {
            pthread_mutex_unlock(&array->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void add_tcp_connection_record(DynamicArray *array, const TCP_CONNECTION_RECORD *record) {
    if (ip_pair_exists(array, &record->ip_pair)) {
        return; // Duplicate entry
    }

    pthread_mutex_lock(&array->lock);

    if (array->count < MAX_ENTRIES) {
        array->records = realloc(array->records, (array->count + 1) * sizeof(TCP_CONNECTION_RECORD));
        if (array->records == NULL) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&array->lock);
            exit(EXIT_FAILURE);
        }
        memcpy(&array->records[array->count], record, sizeof(TCP_CONNECTION_RECORD));
        array->count++;
    } else {
        // Handle max entries reached
        fprintf(stderr, "Maximum number of TCP connection records reached.\n");
    }

    pthread_mutex_unlock(&array->lock);
}

void serialize_dynamic_array(const DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&array->lock);

    fwrite(&array->count, sizeof(size_t), 1, file);
    fwrite(array->records, sizeof(TCP_CONNECTION_RECORD), array->count, file);

    pthread_mutex_unlock(&array->lock);
    fclose(file);
}

void deserialize_dynamic_array(DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&array->lock);

    fread(&array->count, sizeof(size_t), 1, file);
    array->records = realloc(array->records, array->count * sizeof(TCP_CONNECTION_RECORD));
    if (array->records == NULL) {
        perror("Failed to allocate memory");
        fclose(file);
        pthread_mutex_unlock(&array->lock);
        exit(EXIT_FAILURE);
    }
    fread(array->records, sizeof(TCP_CONNECTION_RECORD), array->count, file);

    pthread_mutex_unlock(&array->lock);
    fclose(file);
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->records);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

DynamicArray* create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    array->records = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void populate_record(TCP_CONNECTION_RECORD *record) {
    snprintf(record->ip_pair.SOURCE_IP, sizeof(record->ip_pair.SOURCE_IP), "192.168.1.%d", rand() % 255);
    snprintf(record->ip_pair.DESTINATION_IP, sizeof(record->ip_pair.DESTINATION_IP), "10.0.0.%d", rand() % 255);
    record->crc_indication.RX_UE_INFORMATION_TAG = rand();
    record->crc_indication.RNTI = rand();
    record->crc_indication.CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1
}

int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicArray *array = create_dynamic_array();

    for (size_t i = 0; i < 10000; ++i) { // Example population loop
        TCP_CONNECTION_RECORD record;
        populate_record(&record);
        add_tcp_connection_record(array, &record);
    }

    serialize_dynamic_array(array, "tcp_connections.bin");
    free_dynamic_array(array);

    DynamicArray *new_array = create_dynamic_array();
    deserialize_dynamic_array(new_array, "tcp_connections.bin");

    // Use new_array as needed...

    free_dynamic_array(new_array);

    return 0;
}
```

