}

LTE_PHY_Layer_Cfg_T* initialize_phy_layer_config(int band, size_t numConfigs) {
    LTE_PHY_Layer_Cfg_T *configList = malloc(numConfigs * sizeof(LTE_PHY_Layer_Cfg_T));
    if (!configList) {
        log_error("Memory allocation for PHY layer config list failed");
        return NULL;
    }

    int bwpConfig, success = 0;
    for (int attempt = 0; attempt < MAX_RETRIES && !success; ++attempt) {
        if (fetch_BWP_config(band, &bwpConfig)) {
