#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Logger interface
void log_info(const char *message) {
    printf("[INFO] %s\n", message);
}

void log_error(const char *message) {
    printf("[ERROR] %s\n", message);
}

// Memory pool structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool global_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool(size_t initial_capacity) {
    pthread_mutex_lock(&global_pool.lock);
    if (global_pool.pool == NULL) {
        global_pool.pool = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (global_pool.pool == NULL) {
            log_error("Failed to allocate memory pool.");
            pthread_mutex_unlock(&global_pool.lock);
            exit(EXIT_FAILURE);
        }
        global_pool.capacity = initial_capacity;
    }
    pthread_mutex_unlock(&global_pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(size_t count, int *status) {
    if (count > MAX_STRUCTURES) {
        *status = -1; // Error: too many structures
        return NULL;
    }

    pthread_mutex_lock(&global_pool.lock);

    if (global_pool.capacity < global_pool.count + count) {
        size_t new_capacity = global_pool.capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(global_pool.pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pool == NULL) {
            log_error("Failed to reallocate memory pool.");
            *status = -1; // Error: allocation failed
            pthread_mutex_unlock(&global_pool.lock);
            return NULL;
        }
        global_pool.pool = new_pool;
        global_pool.capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *allocated_structures = &global_pool.pool[global_pool.count];
    global_pool.count += count;

    pthread_mutex_unlock(&global_pool.lock);

    *status = 0; // Success
    return allocated_structures;
}

void deallocate_memory_pool() {
    pthread_mutex_lock(&global_pool.lock);
    free(global_pool.pool);
    global_pool.pool = NULL;
    global_pool.capacity = 0;
    global_pool.count = 0;
    pthread_mutex_unlock(&global_pool.lock);
}

int populate_structures(NFAPI_CRC_INDICATION_PDU_T *structures, size_t count, unsigned int seed) {
    if (count == 0 || structures == NULL) return -1;

    srand(seed);
    int sum_rnti = 0;

    for (size_t i = 0; i < count; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 100;
        structures[i].RNTI = rand() % 1024;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 50;

        sum_rnti += structures[i].RNTI;
    }

    int crc_flag = (sum_rnti & 1) ? 1 : 0; // Parity check

    for (size_t i = 0; i < count; ++i) {
        structures[i].RX_UE_INFORMATION_TAG ^= crc_flag;
    }

    return 0;
}

int create_and_populate_structures(size_t max_count, unsigned int seed, int *status) {
    initialize_memory_pool(10); // Initial capacity

    size_t count = (max_count > MAX_STRUCTURES) ? MAX_STRUCTURES : max_count;

    NFAPI_CRC_INDICATION_PDU_T *structures = allocate_from_pool(count, status);
    if (*status != 0) return -1; // Allocation failed

    int result = populate_structures(structures, count, seed);
    if (result != 0) {
        log_error("Failed to populate structures.");
        deallocate_memory_pool();
        *status = -2; // Error: population failed
        return -1;
    }

    log_info("Structures created and populated successfully.");

    return 0;
}

void cleanup() {
    deallocate_memory_pool();
}

// Example unit test function
void run_tests() {
    int status;

    printf("Running tests...\n");

    // Test case: Normal operation
    if (create_and_populate_structures(10, 12345, &status) == 0) {
        log_info("Test passed: Normal operation.");
    } else {
        log_error("Test failed: Normal operation.");
    }

    // Test case: Exceeding max structures
    if (create_and_populate_structures(MAX_STRUCTURES + 1, 12345, &status) != 0) {
        log_info("Test passed: Exceeding max structures.");
    } else {
        log_error("Test failed: Exceeded max structures but succeeded.");
    }

    // Test case: Zero count
    if (create_and_populate_structures(0, 12345, &status) != 0) {
        log_info("Test passed: Zero count.");
    } else {
        log_error("Test failed: Zero count but succeeded.");
    }

    cleanup();
}

int main() {
    run_tests();
    return 0;
}
