    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_ARRAY_SIZE 10
#define RESIZE_FACTOR 2

int allocate_and_initialize_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t *size, unsigned int seed, int threshold) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    if (!array || !size) {
        pthread_mutex_unlock(&lock);
        return -1; // Invalid parameters
    }

    *size = INITIAL_ARRAY_SIZE;
    srand(seed);

    while (1) {
        *array = realloc(*array, (*size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*array) {
            pthread_mutex_unlock(&lock);
            return -2; // Memory allocation failed
        }

        int rnti_sum = 0;
        for (size_t i = 0; i < *size; ++i) {
            (*array)[i].RX_UE_INFORMATION_TAG = rand() % 256;
            (*array)[i].RNTI = rand() % 65536;
            (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 1024;

            rnti_sum += (*array)[i].RNTI;
        }

        int parity = (rnti_sum & 1) ? 1 : 0; // Check the parity of the sum
        for (size_t i = 0; i < *size; ++i) {
            (*array)[i].CRCFLAG = parity;
        }

        if (rnti_sum <= threshold) {
            pthread_mutex_unlock(&lock);
            return 0; // Successfully initialized and array size is within the threshold
        }

        // Resize the array if the sum exceeds the threshold
        *size *= RESIZE_FACTOR;

        fprintf(stderr, "RNTI sum exceeded threshold. Resizing array to %zu.\n", *size);
    }

    pthread_mutex_unlock(&lock);
}

void free_array(NFAPI_CRC_INDICATION_PDU_T **array) {
    if (array && *array) {
        free(*array);
        *array = NULL;
    }
}
