#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[10];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random integer in range [min, max]
int rand_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(size_t count) {
    pthread_mutex_lock(&mutex);

    // Allocate memory for the array on the heap
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Array to track used RX_UE_INFORMATION_TAGs
    int tag_used[MAX_RNTI] = {0};

    for (size_t i = 0; i < count; ++i) {
        do {
            pdus[i].RX_UE_INFORMATION_TAG = rand_range(1, MAX_RNTI);
        } while (tag_used[pdus[i].RX_UE_INFORMATION_TAG - 1]);

        tag_used[pdus[i].RX_UE_INFORMATION_TAG - 1] = 1;

        do {
            pdus[i].RNTI = rand_range(1, MAX_RNTI);
        } while (tag_used[pdus[i].RNTI - 1]); // Ensure RNTI is unique if tag duplication occurs

        for (int j = 0; j < sizeof(pdus[i].CRC_INDICATION_REL8_TAG); ++j) {
            pdus[i].CRC_INDICATION_REL8_TAG[j] = rand_range(0, 255);
        }

        pdus[i].CRCFLAG = rand() & 1;
    }

    pthread_mutex_unlock(&mutex);

    return pdus;
}

// Function to free the allocated memory
void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (pdus) {
        free(pdus);
    }
}

