// Function prototype for initialization and configuration
NFAPI_UL_TDD_PARAMS* initializeAndConfigureNfapiUldParams(int numCells);

// Mutex for thread safety
pthread_mutex_t initMutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_UL_TDD_PARAMS* initializeAndConfigureNfapiUldParams(int numCells) {
    if (numCells <= 0) {
        fprintf(stderr, "Invalid number of cells. Must be greater than zero.\n");
        return NULL;
    }

    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&initMutex);

    NFAPI_UL_TDD_PARAMS* paramsArray = malloc(numCells * sizeof(NFAPI_UL_TDD_PARAMS));
    if (!paramsArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&initMutex);
        return NULL;
    }

    for (int i = 0; i < numCells; ++i) {
        paramsArray[i].CELL_ID = i + 1;
        paramsArray[i].TX_POWER_LEVEL = rand() % (MAX_TX_POWER_LEVEL + 1); // Randomize within valid range
        paramsArray[i].RX_SINR = rand() % (MIN_RX_SINR + 100) - 20;       // Randomize within valid range
    }

    // Unlock the mutex after initialization is complete
    pthread_mutex_unlock(&initMutex);

    return paramsArray;
}

