    LTE_PHY_MEASUREMENTS_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_array(DynamicArray *arr) {
    arr->size = 0;
    arr->capacity = MAX_MEASUREMENTS;
    arr->array = (LTE_PHY_MEASUREMENTS_T *)malloc(arr->capacity * sizeof(LTE_PHY_MEASUREMENTS_T));
    pthread_mutex_init(&arr->lock, NULL);
}

void free_array(DynamicArray *arr) {
    free(arr->array);
    pthread_mutex_destroy(&arr->lock);
}

int add_measurement(DynamicArray *arr, LTE_PHY_MEASUREMENTS_T measurement) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Capacity reached
    }

    arr->array[arr->size++] = measurement;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int remove_measurement(DynamicArray *arr, int id) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].id == id) {
            memmove(&arr->array[i], &arr->array[i + 1], (arr->size - i - 1) * sizeof(LTE_PHY_MEASUREMENTS_T));
            --arr->size;
            pthread_mutex_unlock(&arr->lock);
            return 0; // Successfully removed
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return -1; // Measurement not found
}

int update_measurement(DynamicArray *arr, int id, double new_value) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].id == id) {
            arr->array[i].value = new_value;
            pthread_mutex_unlock(&arr->lock);
            return 0; // Successfully updated
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return -1; // Measurement not found
}

