['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define CHECKSUM_BASE 65521

typedef struct DataPacket {
    unsigned int packet_id;
    size_t data_length;
    time_t timestamp;
    unsigned long checksum;
    struct DataPacket *next;
} DataPacket;

typedef struct {
    DataPacket *head;
    pthread_mutex_t lock;
} PacketCollection;

unsigned long adler32(const void *data, size_t length) {
    const unsigned char *buf = data;
    unsigned long a = 1, b = 0;
    while (length >= 16) {
        for (size_t i = 0; i < 16; i++) {
            a += buf[i];
            b += a;
        }
        length -= 16;
        buf += 16;
    }

    while (length--) {
        a += *buf++;
        b += a;
    }

    a %= CHECKSUM_BASE;
    b %= CHECKSUM_BASE;

    return (b << 16) | a;
}

void init_packet_collection(PacketCollection *collection) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
}

int add_packet(PacketCollection *collection, unsigned int packet_id, const void *data, size_t data_length) {
    if (!collection || !data) return -1;

    pthread_mutex_lock(&collection->lock);

    DataPacket *new_packet = malloc(sizeof(DataPacket));
    if (!new_packet) {
        pthread_mutex_unlock(&collection->lock);
        return -2;
    }

    new_packet->packet_id = packet_id;
    new_packet->data_length = data_length;
    new_packet->timestamp = time(NULL);
    new_packet->checksum = adler32(data, data_length);

    // Insert at the head for fast insertion
    new_packet->next = collection->head;
    collection->head = new_packet;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int retrieve_packet(PacketCollection *collection, unsigned int packet_id, void **data) {
    if (!collection || !data) return -1;

    pthread_mutex_lock(&collection->lock);

    DataPacket *current = collection->head;
    while (current) {
        if (current->packet_id == packet_id) {
            // Validate checksum
            unsigned long calculated_checksum = adler32(current + 1, current->data_length);
            if (calculated_checksum != current->checksum) {
                pthread_mutex_unlock(&collection->lock);
                return -3;
            }

            *data = malloc(current->data_length);
            if (!*data) {
                pthread_mutex_unlock(&collection->lock);
                return -4;
            }
            memcpy(*data, current + 1, current->data_length);

            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return -5;
}

void free_packet_collection(PacketCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    DataPacket *current = collection->head;
    while (current) {
        DataPacket *temp = current;
        current = current->next;
        free(temp);
    }

    collection->head = NULL;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}
```']

