#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define INITIAL_CAPACITY 16
#define INACTIVE_THRESHOLD 60 // seconds

typedef struct {
    uint64_t connection_id;
    char peer_ip[16];
    uint16_t port;
    time_t last_activity;
} TCP_CONNECTION_RECORD;

typedef struct {
    TCP_CONNECTION_RECORD *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConnectionList;

ConnectionList* create_connection_list() {
    ConnectionList *list = malloc(sizeof(ConnectionList));
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->records = calloc(list->capacity, sizeof(TCP_CONNECTION_RECORD));
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void resize_connection_list(ConnectionList *list) {
    size_t new_capacity = list->capacity * 2;
    TCP_CONNECTION_RECORD *new_records = realloc(list->records, new_capacity * sizeof(TCP_CONNECTION_RECORD));
    if (new_records) {
        list->records = new_records;
        list->capacity = new_capacity;
    }
}

void add_connection(ConnectionList *list, uint64_t connection_id, const char *peer_ip, uint16_t port) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        resize_connection_list(list);
    }

    TCP_CONNECTION_RECORD *record = &list->records[list->count++];
    record->connection_id = connection_id;
    strncpy(record->peer_ip, peer_ip, sizeof(record->peer_ip));
    record->port = port;
    record->last_activity = time(NULL);

    // Log creation
    printf("Connection %llu created\n", (unsigned long long)record->connection_id);

    pthread_mutex_unlock(&list->lock);
}

void update_connection(ConnectionList *list, uint64_t connection_id, const char *peer_ip, uint16_t port) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].connection_id == connection_id) {
            strncpy(list->records[i].peer_ip, peer_ip, sizeof(list->records[i].peer_ip));
            list->records[i].port = port;
            list->records[i].last_activity = time(NULL);

            // Log modification
            printf("Connection %llu updated\n", (unsigned long long)connection_id);
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_inactive_connections(ConnectionList *list) {
    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);

    size_t i = 0;
    while (i < list->count) {
        if (now - list->records[i].last_activity > INACTIVE_THRESHOLD) {
            // Log expiration
            printf("Connection %llu expired\n", (unsigned long long)list->records[i].connection_id);

            memmove(&list->records[i], &list->records[i + 1],
                    (--list->count - i) * sizeof(TCP_CONNECTION_RECORD));
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_connection_list(ConnectionList *list) {
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list->records);
    free(list);
}
```

