#define MAX_RNTI 16383 // Example upper limit for RNTI values

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to generate a random boolean value
bool generate_random_crcflag() {
    return rand() % 2 == 0;
}

// Function to check if an RNTI already exists in the list
bool rnti_exists(Node* head, int rnti) {
    while (head != NULL) {
        if (head->data.RNTI == rnti) {
            return true;
        }
        head = head->next;
    }
    return false;
}

// Function to generate a unique RNTI
int generate_unique_rnti(Node* head) {
    int rnti;
    do {
        rnti = rand() % (MAX_RNTI + 1);
    } while (rnti_exists(head, rnti));
    return rnti;
}

// Function to create and initialize a new node
Node* create_node(int rx_ue_info_tag, int crc_ind_rel8_tag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.RNTI = generate_unique_rnti(NULL); // No duplicates in the list yet
    new_node->data.CRC_INDICATION_REL8_TAG = crc_ind_rel8_tag;
    new_node->data.CRCFLAG = generate_random_crcflag();
    new_node->next = NULL;

    return new_node;
}

// Function to manage a dynamically sized list of NFAPI_CRC_INDICATION_PDU_T structures
Node* manage_nfa_list(int num_elements) {
    if (num_elements <= 0) {
        return NULL;
    }

    Node* head = create_node(rand(), rand());

    Node* current = head;
    for (int i = 1; i < num_elements; ++i) {
        Node* new_node = create_node(rand(), rand());
        current->next = new_node;
        current = new_node;

        // Update RNTI to ensure uniqueness
        new_node->data.RNTI = generate_unique_rnti(head);
    }

    return head;
}

// Function to free all allocated memory for the list
void free_nfa_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int num_elements = 10; // Example number of elements
    Node* list_head = manage_nfa_list(num_elements);

    // Free the allocated memory when done
    free_nfa_list(list_head);

    return 0;
}
