#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_THREADS 8

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    float crc_probability;
    int log_to_file;
} NfaapiConfig;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t num_entries;
    pthread_mutex_t mutex;
} NfaapiState;

void initialize_state(NfaapiState* state, size_t num_entries) {
    state->array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!state->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&state->mutex, NULL);
    state->num_entries = num_entries;
}

void free_state(NfaapiState* state) {
    free(state->array);
    pthread_mutex_destroy(&state->mutex);
}

int populate_structure(NFAPI_CRC_INDICATION_PDU_T* structure, NfaapiConfig config) {
    if (!structure) return 0;

    // Simulate tag generation
    structure->RX_UE_INFORMATION_TAG = rand() % 10000;
    if (structure->RX_UE_INFORMATION_TAG == 0) return 0; // Invalid tag

    structure->RNTI = rand() % 100000;

    float random_value = (float)rand() / RAND_MAX;
    structure->CRC_INDICATION_REL8_TAG.CRCFLAG = random_value < config.crc_probability ? 1 : 0;

    return 1;
}

void* thread_worker(void* arg) {
    NfaapiState* state = (NfaapiState*)arg;
    NfaapiConfig config = *(NfaapiConfig*)state->array; // Assume first entry is the config
    size_t start_idx, end_idx;

    pthread_mutex_lock(&state->mutex);
    for (size_t i = 0; i < state->num_entries - 1; ++i) {
        if (!populate_structure(&state->array[i + 1], config)) continue;

        // Log to file if enabled
        if (config.log_to_file) {
            FILE* log_file = fopen("log.txt", "a");
            if (log_file) {
                fprintf(log_file, "RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRCFLAG: %d\n",
                        state->array[i + 1].RX_UE_INFORMATION_TAG,
                        state->array[i + 1].RNTI,
                        state->array[i + 1].CRC_INDICATION_REL8_TAG.CRCFLAG);
                fclose(log_file);
            }
        }
    }
    pthread_mutex_unlock(&state->mutex);

    return NULL;
}

void populate_and_manage_array(NfaapiState* state, NfaapiConfig config, size_t num_entries) {
    if (num_entries <= 1 || config.crc_probability < 0.0f || config.crc_probability > 1.0f) {
        fprintf(stderr, "Invalid configuration parameters\n");
        return;
    }

    initialize_state(state, num_entries);
    state->array[0] = config; // First entry as config

    pthread_t threads[MAX_THREADS];
    int thread_count = (num_entries - 1 < MAX_THREADS) ? num_entries - 1 : MAX_THREADS;

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, thread_worker, state)) {
            perror("Failed to create thread");
            free_state(state);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Array population complete\n");
}

int main() {
    srand(time(NULL));

    NfaapiState state;
    NfaapiConfig config = { .crc_probability = 0.5f, .log_to_file = 1 };
    size_t num_entries = 100;

    populate_and_manage_array(&state, config, num_entries);

    free_state(&state);

    return 0;
}
