        if (padding_bytes > 0) {
            // Allocate memory for padding bytes
            array[i].padding = (unsigned char*)malloc(padding_bytes);
            if (!array[i].padding) {
                perror("Failed to allocate memory for padding");

                // Free already allocated resources in case of failure
                while (--i >= 0) {
