#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RETRIES 5

typedef struct {
    unsigned int RNTI;
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t mutex;
} NFAPICRCIndicationPool;

NFAPICRCIndicationPool* create_pool() {
    NFAPICRCIndicationPool* pool = (NFAPICRCIndicationPool*)malloc(sizeof(NFAPICRCIndicationPool));
    if (!pool) return NULL;

    pool->head = NULL;
    pool->tail = NULL;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(NFAPICRCIndicationPool* pool) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        pthread_mutex_lock(&pool->mutex);

        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            retries++;
            pthread_mutex_unlock(&pool->mutex);
            continue; // Retry allocation
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = &node->data;
        // Simulate unique RNTI assignment and other initializations.
        pdu->RNTI = rand();  // Replace with actual logic to assign unique RNTI
        pdu->RX_UE_INFORMATION_TAG = 1;  // Example initialization
        pdu->CRC_INDICATION_REL8_TAG = 1; // Example initialization

        node->next = NULL;
        node->prev = pool->tail;

        if (pool->tail) {
            pool->tail->next = node;
        } else {
            pool->head = node;
        }

        pool->tail = node;
        pool->count++;

        pthread_mutex_unlock(&pool->mutex);

        // Successfully allocated
        printf("Allocation successful after %d retries\n", retries);
        return pdu;
    }

    printf("Failed to allocate after maximum retries\n");
    return NULL;
}

void remove_pdu(NFAPICRCIndicationPool* pool, unsigned int RNTI) {
    pthread_mutex_lock(&pool->mutex);

    Node *current = pool->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                pool->head = current->next;
            }

            if (current->next) {
                current->next->prev = prev;
            } else {
                pool->tail = prev;
            }

            free(current);
            pool->count--;
            break; // Assuming RNTI is unique, exit after finding
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&pool->mutex);
}

void iterate_pool(NFAPICRCIndicationPool* pool) {
    pthread_mutex_lock(&pool->mutex);

    Node* current = pool->head;

    while (current != NULL) {
        // Process each node as required
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRC_INDICATION_REL8_TAG: %u\n",
               current->data.RNTI,
               current->data.RX_UE_INFORMATION_TAG,
               current->data.CRC_INDICATION_REL8_TAG);

        current = current->next;
    }

    pthread_mutex_unlock(&pool->mutex);
}

void iterate_pool_reverse(NFAPICRCIndicationPool* pool) {
    pthread_mutex_lock(&pool->mutex);

    Node* current = pool->tail;

    while (current != NULL) {
        // Process each node as required
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRC_INDICATION_REL8_TAG: %u\n",
               current->data.RNTI,
               current->data.RX_UE_INFORMATION_TAG,
               current->data.CRC_INDICATION_REL8_TAG);

        current = current->prev;
    }

    pthread_mutex_unlock(&pool->mutex);
}

void destroy_pool(NFAPICRCIndicationPool* pool) {
    pthread_mutex_lock(&pool->mutex);

    Node *current = pool->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}
