Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Function to add a node to the linked list ensuring unique RNTI
void add_unique_rnti(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    int retries = 0;
    while (retries < MAX_RETRIES) {
        Node* current = list->head;
        int is_duplicate = 0;

        while (current != NULL) {
            if (current->data.crc_tag.RNTI == data.crc_tag.RNTI) {
                is_duplicate = 1;
                break;
            }
            current = current->next;
        }

        if (!is_duplicate) {
            Node* new_node = create_node(data);
            new_node->next = list->head;
            list->head = new_node;
            pthread_mutex_unlock(&list->lock);
            return;
        } else {
            // Generate a new RNTI
            data.crc_tag.RNTI = rand() % 1000000; // Example range for RNTI
            retries++;
        }
    }

    fprintf(stderr, "Failed to generate unique RNTI after %d attempts\n", MAX_RETRIES);
    pthread_mutex_unlock(&list->lock);
}

// Function to free the linked list
void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to create and initialize the linked list
