#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t last_update;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

unsigned int hash(unsigned short rnti, size_t table_size) {
    return rnti % table_size;
}

int parity_check(int value) {
    int count = 0;
    while (value) {
        count += value & 1;
        value >>= 1;
    }
    return count % 2 == 0;
}

void toggle_bit(int* value, int bit_position) {
    *value ^= (1 << bit_position);
}

void correct_parity(int* value) {
    if (!parity_check(*value)) {
        for (int i = 0; i < 32; ++i) {
            toggle_bit(value, i);
            if (parity_check(*value)) return;
            toggle_bit(value, i); // revert if not corrected
        }
        printf("Warning: Parity correction failed.\n");
    }
}

void init_hash_table(HashTable* table, size_t size) {
    table->buckets = calloc(size, sizeof(Node*));
    table->size = size;
    pthread_mutex_init(&table->mutex, NULL);
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
}

void insert_or_update(HashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pdu.RNTI < 1 || pdu.RNTI > 65535) {
        printf("Error: Invalid RNTI value.\n");
        return;
    }

    pthread_mutex_lock(&table->mutex);
    unsigned int index = hash(pdu.RNTI, table->size);

    Node* current = table->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (current->data.RNTI == pdu.RNTI) {
            current->data.CRC_INDICATION_REL8_TAG = pdu.CRC_INDICATION_REL8_TAG;
            current->data.last_update = time(NULL);
            pthread_mutex_unlock(&table->mutex);
            return;
        }
        prev = current;
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&table->mutex);
        return;
    }

    new_node->data = pdu;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->mutex);
}

void process_pdu(HashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!parity_check(pdu.RX_UE_INFORMATION_TAG)) {
        printf("Warning: RX_UE_INFORMATION_TAG parity check failed.\n");
        correct_parity(&pdu.RX_UE_INFORMATION_TAG);
    }

    insert_or_update(table, pdu);
}

int main() {
    HashTable table;
    init_hash_table(&table, 1009); // Use a prime number for better distribution

    // Simulate concurrent updates
    pthread_t threads[MAX_ELEMENTS];
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_ELEMENTS];

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand() % 65536;
        pdus[i].CRC_INDICATION_REL8_TAG = rand();

        pthread_create(&threads[i], NULL, (void*(*)(void*))process_pdu, &table);
    }

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_hash_table(&table);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutex locks ensure thread-safe operations on the hash table.
- **Hash Table**: Provides efficient lookups and updates for managing CRC indications.
- **Parity Check**: Ensures even parity in specified fields, with a correction mechanism.
- **Validation**: Checks RNTI range and logs errors if validation fails.
- **Memory Management**: Uses dynamic allocation and ensures proper cleanup.']

