```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define CHECKSUM_MIN 0
#define CHECKSUM_MAX 65535
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList list;
LinkedList deletion_list;

uint16_t calculate_checksum(const uint8_t* data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return (uint16_t)(checksum & 0xFFFF);
}

int parity_check_and_correct(uint8_t* data, size_t length) {
    int set_bits = 0;
    for (size_t i = 0; i < length; ++i) {
        uint8_t byte = data[i];
        while (byte) {
            set_bits += byte & 1;
            byte >>= 1;
        }
    }

    if (set_bits % 2 == 0) return 0;

    for (size_t i = 0; i < length * 8; ++i) {
        size_t byte_index = i / 8;
        uint8_t bit_mask = 1 << (i % 8);
        data[byte_index] ^= bit_mask;

        if (!parity_check_and_correct(data, length)) {
            return 0;
        }

        data[byte_index] ^= bit_mask; // Revert the change
    }

    fprintf(stderr, "Warning: Unable to correct parity\n");
    return -1;
}

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

int validate_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (entry->RNTI < RNTI_MIN || entry->RNTI > RNTI_MAX) {
        log_error("Invalid RNTI value");
        return 0;
    }
    if (entry->RX_UE_INFORMATION_TAG == 0) {
        log_error("RX_UE_INFORMATION_TAG not initialized");
        return 0;
    }

    uint16_t checksum = calculate_checksum((uint8_t*)entry, sizeof(NFAPI_CRC_INDICATION_PDU_T) - sizeof(time_t));
    if (checksum < CHECKSUM_MIN || checksum > CHECKSUM_MAX) {
        log_error("Checksum validation failed");
        return 0;
    }

    int parity_result = parity_check_and_correct(entry->CRC_INDICATION_REL8_TAG, sizeof(entry->CRC_INDICATION_REL8_TAG));
    if (parity_result != 0) {
        log_error("Parity correction failed");
        return 0;
    }

    entry->timestamp = time(NULL);
    return 1;
}

void insert_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&list.lock);

    Node** current = &list.head;
    while (*current) {
        if ((*current)->data.RNTI == entry->RNTI) {
            // Update existing RNTI
            free(*current);
            *current = (Node*)malloc(sizeof(Node));
            if (!*current) {
                pthread_mutex_unlock(&list.lock);
                log_error("Memory allocation failed");
                return;
            }
        } else {
            current = &((*current)->next);
        }
    }

    if (validate_entry(entry)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&list.lock);
            log_error("Memory allocation failed");
            return;
        }
        memcpy(&new_node->data, entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = list.head;
        list.head = new_node;
    }

    pthread_mutex_unlock(&list.lock);
}

void mark_for_deletion(uint16_t rnti) {
    pthread_mutex_lock(&list.lock);

    Node** current = &list.head;
    while (*current) {
        if ((*current)->data.RNTI == rnti) {
            Node* to_delete = *current;
            *current = (*current)->next;
            to_delete->next = deletion_list.head;
            deletion_list.head = to_delete;
            break;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&list.lock);
}

void remove_marked_entries() {
    pthread_mutex_lock(&list.lock);

    Node** current = &deletion_list.head;
    while (*current) {
        Node* to_remove = *current;
        *current = (*current)->next;

        Node** delete_from_current = &list.head;
        while (*delete_from_current) {
            if ((*delete_from_current)->data.RNTI == to_remove->data.RNTI) {
                Node* to_delete = *delete_from_current;
                *delete_from_current = (*delete_from_current)->next;
                free(to_delete);
                break;
            }
            delete_from_current = &((*delete_from_current)->next);
        }

        free(to_remove);
    }

    pthread_mutex_unlock(&list.lock);
}

void initialize_list() {
    list.head = NULL;
    deletion_list.head = NULL;
    pthread_mutex_init(&list.lock, NULL);
    pthread_mutex_init(&deletion_list.lock, NULL);
}

void cleanup_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* to_free = current;
        current = current->next;
        free(to_free);
    }
    pthread_mutex_destroy(&list->lock);
}

int main() {
    initialize_list();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T entry = {12345, 1001, {0x12, 0x34, 0x56, 0x78}, 0};
    insert_entry(&entry);

    mark_for_deletion(1001);
    remove_marked_entries();

    cleanup_list(&list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to ensure thread-safe operations on the linked list.
- **Parity Check and Correction**: The parity check function attempts to correct single-bit errors by toggling bits.
- **Validation**: Each entry is validated for RNTI range, RX_UE_INFORMATION_TAG initialization, checksum, and parity before insertion.
- **Duplicate Handling**: Entries with duplicate `RNTI` values are updated rather than inserted again.
- **Deletion Management**: A secondary list manages entries marked for deletion, ensuring they're removed from the primary list without disrupting operations.
- **Logging**: Errors and warnings are logged to standard error.

This implementation is designed to handle concurrent updates and deletions efficiently while maintaining data integrity and performance.']

