} TCP_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    IP_HEADER ip_header;
    TCP_HEADER tcp_header;
    char *payload; // Dynamically allocated
    size_t payload_length;
} NICB;

// Define message types and constants
#define MESSAGE_TYPE_BULK 1
#define MESSAGE_TYPE_INTERACTIVE 2

#define MAX_INTERFACE_COUNT 4
size_t interface_load[MAX_INTERFACE_COUNT] = {0};

// External logging service stub
void log_transmission_status(const char *status) {
    printf("Log: %s\n", status);
}

// Function to initialize and populate NICBs
NICB* init_nicbs(size_t nicb_count, size_t payload_length, int message_type, const unsigned char mac_address[6]) {
    if (nicb_count == 0 || payload_length == 0) return NULL;

    NICB *nicbs = malloc(nicb_count * sizeof(NICB));
    if (!nicbs) {
        log_transmission_status("Failed to allocate memory for NICBs");
        return NULL;
    }

    size_t interface_index = 0; // Select the least loaded interface
    for (size_t i = 0; i < nicb_count; ++i) {
        NICB *nicb = &nicbs[i];

        // Initialize MAC_HEADER
        memset(nicb->mac_header.dest_mac, 0xFF, sizeof(nicb->mac_header.dest_mac)); // Broadcast address
        memcpy(nicb->mac_header.src_mac, mac_address, sizeof(mac_address));

        // Initialize IP_HEADER with dummy values for brevity
        nicb->ip_header.ver_ihl = (4 << 4) | 5;
        nicb->ip_header.ttl = 64;

        // Determine the TCP_FLAGS based on message_type
        unsigned short tcp_flags = TH_ACK; // Default to ACK
        if (message_type == MESSAGE_TYPE_BULK) {
            tcp_flags |= TH_PUSH;
        }

        // Initialize TCP_HEADER
        nicb->tcp_header.data_off_res_flags = ((5 << 12) & 0xF000) | (tcp_flags & 0x01FF);
        nicb->tcp_header.seq_num = rand(); // Random sequence number for simplicity

        // Allocate and initialize payload
        nicb->payload = malloc(payload_length);
        if (!nicb->payload) {
            log_transmission_status("Failed to allocate memory for NICB payload");
            free(nicbs); // Clean up allocated NICBs
            return NULL;
        }
        memset(nicb->payload, 'A', payload_length); // Dummy data

        nicb->payload_length = payload_length;

        // Update load balancing info
        interface_load[interface_index] += payload_length;

        // Rotate to next interface for fairness
        interface_index = (interface_index + 1) % MAX_INTERFACE_COUNT;
    }

    log_transmission_status("NICBs initialized successfully");
    return nicbs;
}

// Main function for demonstration purposes (not part of the task)
int main() {
    size_t num_nicbs = 5;
    size_t payload_len = 1024;
    int msg_type = MESSAGE_TYPE_INTERACTIVE;
    unsigned char my_mac[6] = {0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E};

    NICB *nicbs = init_nicbs(num_nicbs, payload_len, msg_type, my_mac);

    if (nicbs) {
        for (size_t i = 0; i < num_nicbs; ++i) {
            free(nicbs[i].payload); // Free allocated payload
        }
        free(nicbs); // Free NICBs array
    }

    return 0;
}
