    NFAPI_CRC_INDICATION_PDU_T **tempArray = realloc(*indicationArray, (*arraySize) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (tempArray == NULL) {
        fprintf(stderr, "Memory reallocation failed for indications array.\n");
        free(newIndication->pduHeaders);
        free(newIndication);
        return;
    }
    *indicationArray = tempArray;
    (*indicationArray)[*arraySize - 1] = newIndication;

    // Log success
    printf("Successfully added a new indication. Total indications: %zu\n", *arraySize);

    // Example of cleanup if needed (not shown in the snippet due to asynchronous nature)
