        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    return manager;
}

void destroy_crc_indication_manager(CRCIndicationManager *manager) {
    if (manager) {
        free(manager->data);
        pthread_mutex_destroy(&manager->mutex);
        pthread_cond_destroy(&manager->cond_var);
        free(manager);
    }
}

int add_crc_indication_pdu(CRCIndicationManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager || manager->count >= MAX_STRUCTURES) return -1;

    pthread_mutex_lock(&manager->mutex);

    manager->data[manager->count++] = pdu;

    // Signal any waiting threads that a new structure has been added
    pthread_cond_signal(&manager->cond_var);

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int get_crc_indication_pdu(CRCIndicationManager *manager, size_t index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!manager || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->mutex);

    *pdu = manager->data[index];

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void randomize_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256; // Random CRCFLAG between 0 and 255
}

// Usage example with threads (omitted for brevity)

int main() {
    srand((unsigned int)time(NULL)); // Seed random number generator

    CRCIndicationManager *manager = create_crc_indication_manager();
    if (!manager) return -1;

