NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be positive.\n");
        return NULL;
    }

    size_t chunk_size = 10; // Start with an initial chunk size
    size_t total_allocated = 0;
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    while (total_allocated < N) {
        size_t new_total = total_allocated + chunk_size;
        if (new_total > N) new_total = N;

        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(array, new_total * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            fprintf(stderr, "Memory allocation failed.\n");
            free(array);
            return NULL;
        }

        array = temp_array;

