            array[i].RX_UE_INFORMATION_TAG = generate_valid_tag();
            array[i].RNTI = generate_valid_tag();
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
