#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
    uint32_t checksum;
} DynamicList;

bool init_dynamic_list(DynamicList* list) {
    if (!list) return false;
    list->elements = NULL;
    list->size = 0;
    list->capacity = 0;
    list->checksum = 0;
    return true;
}

void free_dynamic_list(DynamicList* list) {
    if (list && list->elements) {
        free(list->elements);
        list->elements = NULL;
        list->size = 0;
        list->capacity = 0;
    }
}

bool resize_dynamic_list(DynamicList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) return false;

    list->capacity = new_capacity;
    list->elements = new_elements;
    memset(&list->elements[list->size], 0, (new_capacity - list->size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return true;
}

bool add_element(DynamicList* list, size_t index) {
    if (!list || index >= MAX_ELEMENTS || index >= list->capacity) {
        fprintf(stderr, "Error: Attempt to exceed element limit or invalid index.\n");
        return false;
    }

    if (list->size == list->capacity && !resize_dynamic_list(list, list->capacity + 100)) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[index];
    element->RX_UE_INFORMATION_TAG = rand() % UINT16_MAX; // Simulated valid tag
    element->RNTI = rand() % UINT16_MAX; // Simulated RNTI
    element->CRC_INDICATION_REL8_TAG = rand() % 256; // Simulated CRC tag
    element->CRC_INDICATION_REL8_TAG &= 1; // Randomly set CRC flag

    list->size = (index + 1 > list->size) ? index + 1 : list->size;

    uint32_t new_checksum = ((uint64_t)list->checksum + element->RNTI) % UINT32_MAX;
    if (new_checksum < list->checksum) {
        fprintf(stderr, "Warning: Checksum overflow detected.\n");
    }
    list->checksum = new_checksum;

    return true;
}

bool populate_dynamic_list(DynamicList* list, size_t num_elements) {
    if (!list || num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Invalid number of elements requested.\n");
        return false;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        if (!add_element(list, i)) {
            free_dynamic_list(list);
            return false;
        }
    }

    return true;
}

uint32_t calculate_checksum(const DynamicList* list) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < list->size; ++i) {
        uint64_t new_sum = (uint64_t)checksum + list->elements[i].RNTI;
        if (new_sum < checksum) {
            fprintf(stderr, "Warning: Checksum overflow detected during calculation.\n");
        }
        checksum = (uint32_t)(new_sum % UINT32_MAX);
    }
    return checksum;
}

bool verify_checksum(const DynamicList* list) {
    uint32_t calculated_checksum = calculate_checksum(list);
    if (calculated_checksum != list->checksum) {
        fprintf(stderr, "Error: Checksum verification failed.\n");
        return false;
    }
    return true;
}

int main() {
    DynamicList list;
    if (!init_dynamic_list(&list)) {
        fprintf(stderr, "Failed to initialize dynamic list.\n");
        return EXIT_FAILURE;
    }

    size_t num_elements = 5000; // Example number of elements
    if (!populate_dynamic_list(&list, num_elements)) {
        fprintf(stderr, "Failed to populate dynamic list.\n");
        free_dynamic_list(&list);
        return EXIT_FAILURE;
    }

    if (verify_checksum(&list)) {
        printf("Checksum verified successfully.\n");
    } else {
        fprintf(stderr, "Checksum verification failed.\n");
    }

    free_dynamic_list(&list);
    return EXIT_SUCCESS;
}
