bool fetch_and_validate_RNTI(int *rnti, const int whitelist[], size_t whitelist_size) {
    // Simulate network latency
    usleep(rand() % 1000);

    // Fetch an example RNTI; in a real application, this would be fetched from an external source
    *rnti = rand() % 100;

    for (size_t i = 0; i < whitelist_size; ++i) {
        if (*rnti == whitelist[i]) {
            return true;
        }
    }

    return false;
}

// Function to verify the integrity of data in structures
bool verify_integrity(NFAPI_CRC_INDICATION_PDU_T *structs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (structs[i].RX_UE_INFORMATION_TAG <= 0 ||
            structs[i].RNTI <= 0 ||
            (structs[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0 && 
             structs[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 1)) {
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* generate_structures(size_t count, const int whitelist[], size_t whitelist_size) {
    if (count > MAX_STRUCTS || count == 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *structs = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structs) {
        return NULL;
    }

    pthread_t threads[count];
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    size_t idx = 0;
    for (size_t i = 0; i < count; ++i) {
        int rnti;
        if (fetch_and_validate_RNTI(&rnti, whitelist, whitelist_size)) {
            pthread_create(&threads[idx++], &attr, 
                [](void *arg) -> void* {
                    NFAPI_CRC_INDICATION_PDU_T *structs = (NFAPI_CRC_INDICATION_PDU_T *)arg;

                    structs->RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Random valid tag
                    structs->RNTI = rand() % 100; // Already fetched and validated RNTI

                    structs->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

                    return NULL;
                }, 
            (void*)&structs[i]);
        }
    }

    pthread_attr_destroy(&attr);
    for (size_t i = 0; i < idx; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (!verify_integrity(structs, count)) {
        free(structs);
        return NULL;
    }

    return structs;
}

int main() {
    srand(time(NULL));

    const int whitelist[] = {1, 2, 3, 4, 5}; // Example whitelist
    size_t whitelist_size = sizeof(whitelist) / sizeof(whitelist[0]);

    NFAPI_CRC_INDICATION_PDU_T *structs = generate_structures(10000, whitelist, whitelist_size);

    if (structs) {
        printf("Structures generated successfully.\n");
        free(structs);
    } else {
        printf("Failed to generate structures.\n");
    }

    return 0;
}
