#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FLOW_ID 10000

typedef struct {
    int FlowId;
    char SourceIp[16];
    char DestinationIp[16];
} TrafficFlowConfig;

// Node for the hash table
struct ConfigNode {
    TrafficFlowConfig config;
    struct ConfigNode* next;
};

// Hash map structure
typedef struct {
    struct ConfigNode** buckets;
    size_t bucket_count;
    pthread_rwlock_t lock;
} ConfigMap;

// Hash function to distribute configurations evenly
unsigned long hash_config(const char* sourceIp, const char* destIp) {
    unsigned long hash = 5381;
    int c;
    while ((c = *sourceIp++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    while ((c = *destIp++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

// Initialize the configuration map
void init_config_map(ConfigMap* configMap, size_t bucket_count) {
    configMap->bucket_count = bucket_count;
    configMap->buckets = (struct ConfigNode**)calloc(bucket_count, sizeof(struct ConfigNode*));
    pthread_rwlock_init(&configMap->lock, NULL);
}

// Find configuration by FlowId
TrafficFlowConfig* find_by_flow_id(ConfigMap* configMap, int flowId) {
    pthread_rwlock_rdlock(&configMap->lock);
    for (size_t i = 0; i < configMap->bucket_count; ++i) {
        struct ConfigNode* node = configMap->buckets[i];
        while (node) {
            if (node->config.FlowId == flowId) {
                pthread_rwlock_unlock(&configMap->lock);
                return &node->config;
            }
            node = node->next;
        }
    }
    pthread_rwlock_unlock(&configMap->lock);
    return NULL;
}

// Add or update a configuration
int add_or_update_config(ConfigMap* configMap, TrafficFlowConfig newConfig) {
    unsigned long hash = hash_config(newConfig.SourceIp, newConfig.DestinationIp) % configMap->bucket_count;

    pthread_rwlock_wrlock(&configMap->lock);
    struct ConfigNode** bucket = &configMap->buckets[hash];
    while (*bucket) {
        if (strcmp((*bucket)->config.SourceIp, newConfig.SourceIp) == 0 &&
            strcmp((*bucket)->config.DestinationIp, newConfig.DestinationIp) == 0) {
            // Update existing entry
            (*bucket)->config.FlowId = newConfig.FlowId;
            pthread_rwlock_unlock(&configMap->lock);
            return 1; // Updated
        }
        bucket = &(*bucket)->next;
    }

    // Add new configuration
    struct ConfigNode* newNode = (struct ConfigNode*)malloc(sizeof(struct ConfigNode));
    if (!newNode) {
        pthread_rwlock_unlock(&configMap->lock);
        return -1; // Memory allocation failed
    }
    newNode->config = newConfig;
    newNode->next = *bucket;
    *bucket = newNode;

    pthread_rwlock_unlock(&configMap->lock);
    return 0; // Added
}

// Remove configuration by FlowId
int remove_config(ConfigMap* configMap, int flowId) {
    pthread_rwlock_wrlock(&configMap->lock);

    for (size_t i = 0; i < configMap->bucket_count; ++i) {
        struct ConfigNode** node = &configMap->buckets[i];
        while (*node) {
            if ((*node)->config.FlowId == flowId) {
                struct ConfigNode* toDelete = *node;
                *node = (*node)->next;
                free(toDelete);
                pthread_rwlock_unlock(&configMap->lock);
                return 0; // Removed
            }
            node = &(*node)->next;
        }
    }

    pthread_rwlock_unlock(&configMap->lock);
    return -1; // Not found
}

// Cleanup the configuration map
void cleanup_config_map(ConfigMap* configMap) {
    pthread_rwlock_wrlock(&configMap->lock);

    for (size_t i = 0; i < configMap->bucket_count; ++i) {
        struct ConfigNode* node = configMap->buckets[i];
        while (node) {
            struct ConfigNode* toDelete = node;
            node = node->next;
            free(toDelete);
        }
    }

    free(configMap->buckets);
    pthread_rwlock_unlock(&configMap->lock);
    pthread_rwlock_destroy(&configMap->lock);
}

int main() {
    ConfigMap configMap;
    init_config_map(&configMap, 100); // Initialize with 100 buckets

    TrafficFlowConfig newConfig = {1, "192.168.1.1", "10.0.0.1"};
    add_or_update_config(&configMap, newConfig);

    TrafficFlowConfig* foundConfig = find_by_flow_id(&configMap, 1);
    if (foundConfig) {
        printf("Found Config: FlowId=%d, SourceIp=%s, DestinationIp=%s\n", 
               foundConfig->FlowId, foundConfig->SourceIp, foundConfig->DestinationIp);
    }

    remove_config(&configMap, 1);

    cleanup_config_map(&configMap);
    return 0;
}
