#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <zlib.h>
#include <time.h>

#define MAX_FLOW_ID 1000000

typedef struct TrafficFlowConfig {
    int FlowId;
    char SourceIp[16];
    char DestinationIp[16];
} TrafficFlowConfig;

typedef struct Node {
    TrafficFlowConfig config;
    _Atomic struct Node* next;
} Node;

typedef struct {
    Node* head[MAX_FLOW_ID];
    pthread_mutex_t lock[MAX_FLOW_ID]; // Mutex array for each flow id
    size_t count;
} ConfigManager;

static inline unsigned int hash(const char *ip) {
    unsigned long hash = 5381;
    int c;
    while ((c = *ip++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % MAX_FLOW_ID;
}

ConfigManager* create_config_manager() {
    ConfigManager* manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    for (size_t i = 0; i < MAX_FLOW_ID; ++i) {
        manager->head[i] = NULL;
        pthread_mutex_init(&manager->lock[i], NULL);
    }
    manager->count = 0;
    return manager;
}

void destroy_config_manager(ConfigManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < MAX_FLOW_ID; ++i) {
        Node *current = manager->head[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->_Atomic.next;
            free(temp);
        }
        pthread_mutex_destroy(&manager->lock[i]);
    }

    free(manager);
}

int add_config(ConfigManager* manager, TrafficFlowConfig config) {
    unsigned int src_hash = hash(config.SourceIp);
    unsigned int dst_hash = hash(config.DestinationIp);

    pthread_mutex_lock(&manager->lock[src_hash]);
    Node *current = manager->head[src_hash];
    while (current != NULL) {
        if (strcmp(current->config.SourceIp, config.SourceIp) == 0 &&
            strcmp(current->config.DestinationIp, config.DestinationIp) == 0) {
            pthread_mutex_unlock(&manager->lock[src_hash]);
            return -1; // Duplicate configuration
        }
        current = current->_Atomic.next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock[src_hash]);
        return -2; // Memory allocation failure
    }

    new_node->config = config;
    new_node->_Atomic.next = manager->head[src_hash];
    manager->head[src_hash] = new_node;

    pthread_mutex_unlock(&manager->lock[src_hash]);
    manager->count++;
    return 0;
}

int remove_config(ConfigManager* manager, const char* SourceIp, const char* DestinationIp) {
    unsigned int src_hash = hash(SourceIp);

    pthread_mutex_lock(&manager->lock[src_hash]);
    Node **current_ptr = &manager->head[src_hash];
    while (*current_ptr != NULL) {
        Node *current = *current_ptr;
        if (strcmp(current->config.SourceIp, SourceIp) == 0 &&
            strcmp(current->config.DestinationIp, DestinationIp) == 0) {
            *current_ptr = current->_Atomic.next;
            free(current);
            pthread_mutex_unlock(&manager->lock[src_hash]);
            manager->count--;
            return 0; // Successfully removed
        }
        current_ptr = &current->_Atomic.next;
    }

    pthread_mutex_unlock(&manager->lock[src_hash]);
    return -1; // Configuration not found
}

int update_config(ConfigManager* manager, int FlowId, TrafficFlowConfig new_config) {
    for (size_t i = 0; i < MAX_FLOW_ID; ++i) {
        pthread_mutex_lock(&manager->lock[i]);

        Node *current = manager->head[i];
        while (current != NULL) {
            if (current->config.FlowId == FlowId) {
                // Remove old node
                Node **temp_ptr = &manager->head[i];
                while (*temp_ptr && *temp_ptr != current) {
                    temp_ptr = &(*temp_ptr)->_Atomic.next;
                }
                if (*temp_ptr) {
                    *temp_ptr = current->_Atomic.next;
                    free(current);

                    // Add updated node
                    Node* new_node = (Node*)malloc(sizeof(Node));
                    if (!new_node) {
                        pthread_mutex_unlock(&manager->lock[i]);
                        return -2; // Memory allocation failure
                    }
                    new_node->config = new_config;
                    new_node->_Atomic.next = manager->head[i];
                    manager->head[i] = new_node;
                }
                pthread_mutex_unlock(&manager->lock[i]);
                return 0; // Successfully updated
            }
            current = current->_Atomic.next;
        }

        pthread_mutex_unlock(&manager->lock[i]);
    }
    return -1; // Configuration not found
}

void dump_to_disk(ConfigManager* manager, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    deflateInit(&stream, Z_BEST_COMPRESSION);

    for (size_t i = 0; i < MAX_FLOW_ID; ++i) {
        pthread_mutex_lock(&manager->lock[i]);
        Node *current = manager->head[i];
        while (current != NULL) {
            char buffer[128] = {0};
            snprintf(buffer, sizeof(buffer), "%d %s %s\n", current->config.FlowId,
                     current->config.SourceIp, current->config.DestinationIp);

            stream.next_in = (unsigned char*)buffer;
            stream.avail_in = strlen(buffer) + 1;

            do {
                unsigned char out[128];
                stream.next_out = out;
                stream.avail_out = sizeof(out);

                deflate(&stream, Z_NO_FLUSH);

                size_t have = 128 - stream.avail_out;
                fwrite(out, 1, have, file);
            } while (stream.avail_out == 0);

            current = current->_Atomic.next;
        }
        pthread_mutex_unlock(&manager->lock[i]);
    }

    deflate(&stream, Z_FINISH);
    do {
        unsigned char out[128];
        stream.next_out = out;
        stream.avail_out = sizeof(out);

        deflate(&stream, Z_NO_FLUSH);

        size_t have = 128 - stream.avail_out;
        fwrite(out, 1, have, file);
    } while (stream.avail_out == 0);

    fclose(file);
    deflateEnd(&stream);
}

void log_operation(const char* operation) {
    FILE *log_file = fopen("operations.log", "a");
    if (!log_file) return;

    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), operation);
    fclose(log_file);
}

void recover_from_backup(ConfigManager* manager, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    inflateInit(&stream);

    unsigned char in[128];
    unsigned char out[1024];

    do {
        stream.avail_in = fread(in, 1, sizeof(in), file);
        if (ferror(file)) break;

        stream.next_in = in;

        stream.avail_out = sizeof(out);
        stream.next_out = out;

        inflate(&stream, Z_NO_FLUSH);

        size_t have = sizeof(out) - stream.avail_out;
        char buffer[1024];
        while (have > 0) {
            memcpy(buffer, out, have);
            buffer[have] = '\0';

            char *token = strtok(buffer, " ");
            int flow_id = atoi(token);
            token = strtok(NULL, " ");
            char source_ip[16];
            strncpy(source_ip, token, sizeof(source_ip));
            token = strtok(NULL, " ");
            char destination_ip[16];
            strncpy(destination_ip, token, sizeof(destination_ip));

            TrafficFlowConfig config = {flow_id, source_ip, destination_ip};
            add_config(manager, config);

            have -= strlen(token) + 1;
        }
    } while (stream.avail_out == 0);

    fclose(file);
    inflateEnd(&stream);
}

int main() {
    ConfigManager* manager = create_config_manager();

    TrafficFlowConfig config1 = {1, "192.168.1.1", "10.0.0.1"};
    add_config(manager, config1);
    log_operation("Added configuration for FlowId 1");

    TrafficFlowConfig config2 = {2, "192.168.1.2", "10.0.0.2"};
    add_config(manager, config2);
    log_operation("Added configuration for FlowId 2");

    remove_config(manager, "192.168.1.1", "10.0.0.1");
    log_operation("Removed configuration for SourceIp 192.168.1.1 and DestinationIp 10.0.0.1");

    TrafficFlowConfig updated_config = {3, "192.168.1.3", "10.0.0.3"};
    update_config(manager, 2, updated_config);
    log_operation("Updated configuration for FlowId 2");

    dump_to_disk(manager, "config_dump.gz");
    log_operation("Dumped configurations to disk");

    recover_from_backup(manager, "config_dump.gz");
    log_operation("Recovered from backup");

    destroy_config_manager(manager);

    return 0;
}
