#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct CRC_INDICATION_REL8_TAG {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueInfoTag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashTableEntry {
    unsigned short RNTI;
    bool isOccupied;
    struct HashTableEntry *next;
} HashTableEntry;

#define HASH_TABLE_SIZE 1024

static pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;

HashTableEntry* create_hash_table() {
    HashTableEntry *table = (HashTableEntry *)malloc(HASH_TABLE_SIZE * sizeof(HashTableEntry));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        table[i].RNTI = 0;
        table[i].isOccupied = false;
        table[i].next = NULL;
    }
    return table;
}

unsigned int hash_function(unsigned short rnti) {
    return rnti % HASH_TABLE_SIZE;
}

bool insert_into_hash_table(HashTableEntry *table, unsigned short rnti) {
    pthread_mutex_lock(&hash_table_lock);

    unsigned int index = hash_function(rnti);
    HashTableEntry *entry = &table[index];

    while (entry != NULL && entry->isOccupied) {
        if (entry->RNTI == rnti) {
            pthread_mutex_unlock(&hash_table_lock);
            return false; // RNTI already exists
        }
        entry = entry->next;
    }

    if (!entry->isOccupied) {
        entry->RNTI = rnti;
        entry->isOccupied = true;
        pthread_mutex_unlock(&hash_table_lock);
        return true;
    } else {
        HashTableEntry *new_entry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
        new_entry->RNTI = rnti;
        new_entry->isOccupied = true;
        new_entry->next = entry->next;
        entry->next = new_entry;
        pthread_mutex_unlock(&hash_table_lock);
        return true;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(unsigned int num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **last_ptr = &head;
    HashTableEntry *hash_table = create_hash_table();

    for (unsigned int i = 0; i < num_elements; ++i) {
        unsigned short rnti;
        do {
            rnti = rand() % MAX_RNTI;
        } while (!insert_into_hash_table(hash_table, rnti));

        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->ueInfoTag.RNTI = rnti;
        new_node->ueInfoTag.crcTag.CRCFLAG = rand() % 2 == 0;

        *last_ptr = new_node;
        last_ptr = &new_node->next;
    }

    free(hash_table);
    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
}
