#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct {
    int version;
    char FlowId[32];
    char SourceIp[16];
    char DestinationIp[16];
} NetworkFlowConfig;

typedef struct Node {
    NetworkFlowConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t capacity;
    pthread_rwlock_t lock;  // Read-write lock for thread safety
} ConfigManager;

unsigned int hash(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % INITIAL_CAPACITY;
}

ConfigManager* create_config_manager() {
    ConfigManager* manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    manager->capacity = INITIAL_CAPACITY;
    manager->table = (Node**)calloc(manager->capacity, sizeof(Node*));
    pthread_rwlock_init(&manager->lock, NULL);
    return manager;
}

void resize_table(ConfigManager* manager) {
    size_t old_capacity = manager->capacity;
    Node** old_table = manager->table;

    manager->capacity *= 2;
    manager->table = (Node**)calloc(manager->capacity, sizeof(Node*));

    for (size_t i = 0; i < old_capacity; ++i) {
        Node* entry = old_table[i];
        while (entry) {
            Node* next_entry = entry->next;
            size_t index = hash(entry->config.SourceIp) ^ hash(entry->config.DestinationIp);
            entry->next = manager->table[index];
            manager->table[index] = entry;
            entry = next_entry;
        }
    }

    free(old_table);
}

void add_config(ConfigManager* manager, NetworkFlowConfig config) {
    pthread_rwlock_wrlock(&manager->lock);

    size_t index = hash(config.SourceIp) ^ hash(config.DestinationIp);
    Node* node = manager->table[index];

    // Ensure uniqueness of SourceIp and DestinationIp
    while (node) {
        if (strcmp(node->config.SourceIp, config.SourceIp) == 0 &&
            strcmp(node->config.DestinationIp, config.DestinationIp) == 0) {
            pthread_rwlock_unlock(&manager->lock);
            return; // Entry already exists
        }
        node = node->next;
    }

    if (node == NULL && manager->capacity > INITIAL_CAPACITY * 0.75) {
        resize_table(manager);
        index = hash(config.SourceIp) ^ hash(config.DestinationIp);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    memcpy(&new_node->config, &config, sizeof(NetworkFlowConfig));
    new_node->next = manager->table[index];
    manager->table[index] = new_node;

    pthread_rwlock_unlock(&manager->lock);
}

int remove_config(ConfigManager* manager, const char* FlowId) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        Node *prev = NULL, *node = manager->table[i];

        while (node) {
            if (strcmp(node->config.FlowId, FlowId) == 0) {
                if (prev) {
                    prev->next = node->next;
                } else {
                    manager->table[i] = node->next;
                }
                free(node);
                pthread_rwlock_unlock(&manager->lock);
                return 1; // Successfully removed
            }
            prev = node;
            node = node->next;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return 0; // Not found
}

void update_config(ConfigManager* manager, const char* FlowId, NetworkFlowConfig new_config) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        Node* node = manager->table[i];

        while (node) {
            if (strcmp(node->config.FlowId, FlowId) == 0) {
                // Check uniqueness before updating
                size_t index = hash(new_config.SourceIp) ^ hash(new_config.DestinationIp);
                Node* existing_node = manager->table[index];

                while (existing_node && 
                       (strcmp(existing_node->config.FlowId, FlowId) != 0 ||
                        strcmp(existing_node->config.SourceIp, new_config.SourceIp) != 0 ||
                        strcmp(existing_node->config.DestinationIp, new_config.DestinationIp) != 0)) {
                    existing_node = existing_node->next;
                }

                if (existing_node == NULL || 
                    (strcmp(existing_node->config.FlowId, FlowId) == 0 &&
                     strcmp(existing_node->config.SourceIp, node->config.SourceIp) == 0 &&
                     strcmp(existing_node->config.DestinationIp, node->config.DestinationIp) == 0)) {

                    memcpy(&node->config, &new_config, sizeof(NetworkFlowConfig));
                } else {
                    pthread_rwlock_unlock(&manager->lock);
                    return; // Can't update due to uniqueness constraint
                }

                pthread_rwlock_unlock(&manager->lock);
                return;
            }
            node = node->next;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
}

void free_config_manager(ConfigManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        Node* entry = manager->table[i];
        while (entry) {
            Node* next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }

    free(manager->table);
    pthread_rwlock_destroy(&manager->lock);
    free(manager);
}

// Add additional utility functions for integration, testing, etc.
