#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define SUCCESS 0
#define ERROR_MEMORY -1

typedef struct CRC_INDICATION_REL8_TAG {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    int UEIndex;
    int UE_ID;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    int unique_rnti_count;
    pthread_mutex_t lock;
    uint16_t min_rnti;
    uint16_t max_rnti;
    FILE* log_file;
} DoublyLinkedList;

static inline bool is_rnti_in_range(uint16_t rnti, uint16_t min_rnti, uint16_t max_rnti) {
    return rnti >= min_rnti && rnti <= max_rnti;
}

DoublyLinkedList* create_doubly_linked_list(uint16_t min_rnti, uint16_t max_rnti, const char* log_filename) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->unique_rnti_count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->min_rnti = min_rnti;
    list->max_rnti = max_rnti;

    if (log_filename) {
        list->log_file = fopen(log_filename, "w");
        if (!list->log_file) {
            free(list);
            return NULL;
        }
    } else {
        list->log_file = NULL;
    }

    return list;
}

void destroy_doubly_linked_list(DoublyLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    if (list->log_file) fclose(list->log_file);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

static bool add_unique_rnti(DoublyLinkedList* list, uint16_t rnti_set[], int size, uint16_t new_rnti) {
    for (int i = 0; i < size; ++i) {
        if (rnti_set[i] == new_rnti) return false;
    }
    rnti_set[size] = new_rnti;
    return true;
}

static NFAPI_CRC_INDICATION_PDU_T* create_node(uint16_t rnti, int ue_index, int ue_id, uint8_t crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->rx_ue_information_tag.UEIndex = ue_index;
    node->rx_ue_information_tag.UE_ID = ue_id;
    node->rnti = rnti;
    node->crc_indication_rel8_tag.CRCFLAG = crc_flag;
    node->prev = NULL;
    node->next = NULL;

    return node;
}

int populate_doubly_linked_list(DoublyLinkedList* list, int num_entries) {
    if (!list || !is_rnti_in_range(list->min_rnti, 0, UINT16_MAX) ||
        !is_rnti_in_range(list->max_rnti, 0, UINT16_MAX)) {
        return ERROR_MEMORY;
    }

    uint16_t rnti_cache[1024] = {0};
    int cache_size = 0;

    for (int i = 0; i < num_entries; ++i) {
        pthread_mutex_lock(&list->lock);

        NFAPI_CRC_INDICATION_PDU_T* new_node;
        uint16_t rnti;
        bool valid_rnti_found = false;

        do {
            if (cache_size == sizeof(rnti_cache) / sizeof(rnti_cache[0])) break;  // Cache limit reached
            rnti = rand() % (list->max_rnti - list->min_rnti + 1) + list->min_rnti;
        } while (!is_rnti_in_range(rnti, list->min_rnti, list->max_rnti) ||
                 !add_unique_rnti(list, rnti_cache, cache_size, rnti));

        if (cache_size < sizeof(rnti_cache) / sizeof(rnti_cache[0])) {
            rnti_cache[cache_size++] = rnti;
        } else {
            pthread_mutex_unlock(&list->lock);
            continue;  // Retry with new random number
        }

        valid_rnti_found = true;
        uint8_t crc_flag = rand() % 2;

        new_node = create_node(rnti, i, rand(), crc_flag);
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            continue;  // Retry with next RNTI
        }

        if (list->head == NULL) {
            list->head = new_node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = list->head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
            new_node->prev = current;
        }

        ++list->unique_rnti_count;

        pthread_mutex_unlock(&list->lock);
    }

    if (list->log_file) {
        fprintf(list->log_file, "Total unique RNTIs used: %d\n", list->unique_rnti_count);
    }

    return SUCCESS;
}

// Usage example
int main() {
    DoublyLinkedList* list = create_doubly_linked_list(1000, 2000, "rnti_log.txt");
    if (!list) {
        printf("Failed to initialize the doubly linked list\n");
        return ERROR_MEMORY;
    }

    int result = populate_doubly_linked_list(list, 10000);
    if (result != SUCCESS) {
        printf("Failed to populate the list: %d\n", result);
    } else {
        printf("List populated successfully with unique RNTIs\n");
    }

    destroy_doubly_linked_list(list);
    return 0;
}
