} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t size;
    pthread_mutex_t lock;
    FILE* log_file;
    int unique_rntis;
} CRC_Indication_List;

CRC_Indication_List* create_list(FILE* log) {
    CRC_Indication_List* list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->log_file = log;
    list->unique_rntis = 0;

    return list;
}

void destroy_list(CRC_Indication_List* list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    if (list->log_file) fclose(list->log_file);
    free(list);
}

int add_to_list(CRC_Indication_List* list, RX_UE_INFORMATION_TAG rx_ue_info_tag, uint16_t rnti) {
    if (!list || list->size >= MAX_LIST_SIZE) return -1;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T** current = &list->head;
    while (*current && (*current)->RNTI != rnti) {
        current = &(*current)->next;
    }

    if (*current) { // RNTI already exists
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->rx_ue_info_tag = rx_ue_info_tag;
    new_node->RNTI = rnti;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->prev = NULL;
    new_node->next = *current;

    if (*current) {
        (*current)->prev = new_node;
    } else {
        list->head = new_node;
    }

    *current = new_node;
    list->size++;
    list->unique_rntis++;

    pthread_mutex_unlock(&list->lock);

    if (list->log_file) {
        fprintf(list->log_file, "Added RNTI: %u, List Size: %zu\n", rnti, list->size);
    }

    return 1;
}

void checkpoint_list(const CRC_Indication_List* list, const char* filename) {
    if (!list || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

int main() {
    FILE* log = fopen("crc_log.txt", "w");
    if (!log) return -1;

    CRC_Indication_List* list = create_list(log);
    if (!list) {
        fclose(log);
        return -1;
    }

    // Example usage
    RX_UE_INFORMATION_TAG example_tag;
    for (int i = 0; i < 10000; ++i) {
        add_to_list(list, example_tag, rand() % 65536); // Random RNTI
    }

    checkpoint_list(list, "crc_checkpoint.bin");

    destroy_list(list);
    fclose(log);

    return 0;
}
