#include <stdio.h>
#include <stdlib.h>
import "network_stack_headers.h"  // Assume necessary network stack headers are included

#define ALIGNMENT_BOUNDARY 16

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
    uint32_t crcflag;  // Assuming crcflag is a 32-bit integer
} NFAPI_CRC_INDICATION_PDU_T;

// Utility function for aligned memory allocation
void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
    return ptr;
}

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Hash table for CRCFLAG uniqueness
#define HASH_TABLE_SIZE 1024

typedef struct {
    Node** buckets;
    size_t count;
    size_t capacity;
} HashTable;

unsigned int hash_crcflag(uint32_t crcflag) {
    return crcflag % HASH_TABLE_SIZE;
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)aligned_malloc(sizeof(HashTable), ALIGNMENT_BOUNDARY);
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->buckets = (Node**)aligned_malloc(HASH_TABLE_SIZE * sizeof(Node*), ALIGNMENT_BOUNDARY);
    if (!table->buckets) {
        free(table);
        perror("Failed to allocate memory for hash buckets");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        table->buckets[i] = NULL;
    }
    table->count = 0;
    table->capacity = HASH_TABLE_SIZE;
    return table;
}

void insert_hash_table(HashTable* table, NFAPI_CRC_INDICATION_PDU_T data) {
    unsigned int index = hash_crcflag(data.crcflag);
    Node* new_node = (Node*)aligned_malloc(sizeof(Node), ALIGNMENT_BOUNDARY);
    if (!new_node) {
        perror("Failed to allocate memory for hash node");
        return;
    }
    new_node->data = data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->count++;
}

int is_crcflag_unique(HashTable* table, uint32_t crcflag) {
    unsigned int index = hash_crcflag(crcflag);
    Node* current = table->buckets[index];
    while (current) {
        if (current->data.crcflag == crcflag) {
            return 0; // Not unique
        }
        current = current->next;
    }
    return 1; // Unique
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    HashTable* hash_table;
} DynamicList;

DynamicList* create_dynamic_list(size_t max_capacity) {
    DynamicList* list = (DynamicList*)aligned_malloc(sizeof(DynamicList), ALIGNMENT_BOUNDARY);
    if (!list) {
        perror("Failed to allocate memory for dynamic list");
        exit(EXIT_FAILURE);
    }
    list->array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_malloc(max_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), ALIGNMENT_BOUNDARY);
    if (!list->array) {
        free(list);
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = max_capacity;
    list->hash_table = create_hash_table();
    return list;
}

int add_to_dynamic_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size == list->capacity) {
        printf("Warning: Maximum capacity reached. Further additions may fail.\n");
    }

    if (!is_crcflag_unique(list->hash_table, data.crcflag)) {
        printf("CRCFLAG %u is not unique.\n", data.crcflag);
        return 0; // CRCFLAG not unique
    }

    if (list->size < list->capacity) {
        list->array[list->size] = data;
        insert_hash_table(list->hash_table, data);
        list->size++;
        return 1; // Success
    } else {
        printf("Cannot add more structures: capacity limit reached.\n");
        return 0; // Failure due to capacity limit
    }
}

void free_dynamic_list(DynamicList* list) {
    if (!list) return;
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* current = list->hash_table->buckets[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(list->hash_table->buckets);
    free(list->hash_table);
    free(list->array);
    free(list);
}

int main() {
    size_t max_capacity = 100; // Example maximum limit
    DynamicList* list = create_dynamic_list(max_capacity);

    for (size_t i = 0; i < max_capacity + 10; ++i) { // Test beyond capacity
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.ue_info = /* Initialize */;
        pdu.rnti = /* Initialize */;
        pdu.crc_ind_tag = /* Initialize */;
