#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double timestamp;
    int packetID;
    char *buffer;
} FrameBufferEntry;

#define MAX_MEMORY_USAGE 10485760 // Example threshold: 10 MB

typedef struct {
    FrameBufferEntry **entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} FrameBuffer;

int initializeFrameBuffer(FrameBuffer *frameBuffer, size_t entryCount, size_t bufferSize) {
    if (entryCount == 0 || bufferSize == 0 || frameBuffer->capacity > MAX_MEMORY_USAGE / sizeof(char *)) {
        return -1; // Invalid parameters or memory limit exceeded
    }

    pthread_mutex_lock(&frameBuffer->mutex);

    frameBuffer->entries = (FrameBufferEntry **)calloc(entryCount, sizeof(FrameBufferEntry *));
    if (!frameBuffer->entries) {
        pthread_mutex_unlock(&frameBuffer->mutex);
        return -1; // Memory allocation failed for entry pointers
    }

    size_t totalMemoryUsage = entryCount * sizeof(FrameBufferEntry *) + entryCount * bufferSize;
    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        free(frameBuffer->entries);
        pthread_mutex_unlock(&frameBuffer->mutex);
        return -1; // Memory usage exceeds threshold
    }

    for (size_t i = 0; i < entryCount; ++i) {
        frameBuffer->entries[i] = (FrameBufferEntry *)malloc(sizeof(FrameBufferEntry));
        if (!frameBuffer->entries[i]) {
            for (size_t j = 0; j < i; ++j) { // Clean up previously allocated entries
                free(frameBuffer->entries[j]);
            }
            free(frameBuffer->entries);
            pthread_mutex_unlock(&frameBuffer->mutex);
            return -1; // Memory allocation failed for FrameBufferEntry
        }

        frameBuffer->entries[i]->buffer = (char *)malloc(bufferSize);
        if (!frameBuffer->entries[i]->buffer) {
            for (size_t j = 0; j <= i; ++j) { // Clean up all entries including current
                free(frameBuffer->entries[j]);
            }
            free(frameBuffer->entries);
            pthread_mutex_unlock(&frameBuffer->mutex);
            return -1; // Memory allocation failed for buffer
        }

        frameBuffer->entries[i]->timestamp = 0.0;
        frameBuffer->entries[i]->packetID = 0;
    }

    frameBuffer->count = entryCount;
    frameBuffer->capacity = entryCount;

    pthread_mutex_unlock(&frameBuffer->mutex);
    return 0; // Success
}

void cleanupFrameBuffer(FrameBuffer *frameBuffer) {
    if (!frameBuffer || !frameBuffer->entries) return;

    pthread_mutex_lock(&frameBuffer->mutex);

    for (size_t i = 0; i < frameBuffer->count; ++i) {
        free(frameBuffer->entries[i]->buffer);
        free(frameBuffer->entries[i]);
    }

    free(frameBuffer->entries);
    frameBuffer->entries = NULL;
    frameBuffer->count = 0;
    frameBuffer->capacity = 0;

    pthread_mutex_unlock(&frameBuffer->mutex);
}

int main() {
    FrameBuffer frameBuffer = {NULL, 0, 0};
    pthread_mutex_init(&frameBuffer.mutex, NULL);

    if (initializeFrameBuffer(&frameBuffer, 100, 256) != 0) {
        printf("Failed to initialize frame buffer\n");
    } else {
        printf("Frame buffer initialized successfully\n");
    }

    cleanupFrameBuffer(&frameBuffer);
    pthread_mutex_destroy(&frameBuffer.mutex);

    return 0;
}
