['Below is a C implementation for managing a dynamic list of `NetworkSession` objects with thread safety and efficient memory management:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SESSION_LIMIT 100

typedef struct {
    int sessionID;
    time_t connectionTimestamp;
    int socketDescriptor;
} NetworkSession;

typedef struct Node {
    NetworkSession* session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t limit;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* create_session_manager(size_t initial_limit) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->head = NULL;
    manager->count = 0;
    manager->limit = initial_limit;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_session_manager(SessionManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current->session);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

NetworkSession* create_network_session(int sessionID, int socketDescriptor) {
    NetworkSession* session = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (!session) return NULL;

    session->sessionID = sessionID;
    session->connectionTimestamp = time(NULL);
    session->socketDescriptor = socketDescriptor;

    return session;
}

void destroy_network_session(NetworkSession* session) {
    free(session);
}

int add_session(SessionManager* manager, int sessionID, int socketDescriptor) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->limit) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Limit exceeded
    }

    NetworkSession* newSession = create_network_session(sessionID, socketDescriptor);
    if (!newSession) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Allocation failed
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        destroy_network_session(newSession);
        pthread_mutex_unlock(&manager->lock);
        return -3; // Allocation failed
    }

    newNode->session = newSession;
    newNode->next = manager->head;
    manager->head = newNode;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int remove_session(SessionManager* manager, int sessionID) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;

    while (current) {
        if (current->session->sessionID == sessionID) {
            if (prev) prev->next = current->next;
            else manager->head = current->next;

            destroy_network_session(current->session);
            free(current);

            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

void set_session_limit(SessionManager* manager, size_t new_limit) {
    pthread_mutex_lock(&manager->lock);

    if (new_limit < manager->count) {
        Node *current = manager->head;
        while (new_limit != manager->count && current) {
            Node *to_remove = current;
            current = current->next;

            destroy_network_session(to_remove->session);
            free(to_remove);

            manager->count--;
        }
    }

    manager->limit = new_limit;
    pthread_mutex_unlock(&manager->lock);
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for locking to ensure safe concurrent access.
- **Dynamic Scaling**: Allows adjusting the session limit at runtime with `set_session_limit`.
- **Efficient Memory Management**: Handles allocation and deallocation of sessions and nodes carefully.
- **Error Handling**: Returns error codes for various failure scenarios (e.g., allocation failures, limit exceeded).
- **Scalability**: Designed to handle high-load conditions efficiently.']

