// Helper function to set random CRCFLAG
void set_random_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    if (tag) {
        tag->CRCFLAG = rand() % 2;
    }
}

// Logging helper function
void log_message(const char* message, LogLevel level) {
    if (level <= current_log_level && strlen(message) + strlen(log_buffer) < MAX_LOG_LENGTH - 1) {
        strncat(log_buffer, message, MAX_LOG_LENGTH - strlen(log_buffer) - 1);
        strcat(log_buffer, "\n");
    } else if (strlen(log_buffer) >= MAX_LOG_LENGTH - 10) {
        snprintf(log_buffer + MAX_LOG_LENGTH - 10, 11, " [Log truncated]");
    }
}

// Insert a PDU into the linked list
void insert_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list_lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for node.", LOG_LEVEL_DEBUG);
        return;
    }

    new_node->data = pdu;
    set_random_crcflag(&new_node->data.crc_indication_rel8_tag);
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&list_lock);

    log_message("PDU inserted.", LOG_LEVEL_INFO);
}

// Find and remove a PDU from the linked list by RNTI
NFAPI_CRC_INDICATION_PDU_T* find_and_remove_pdu(unsigned int rnti) {
    pthread_mutex_lock(&list_lock);

    Node **indirect = &head;
    while (*indirect) {
        Node *entry = *indirect;

        if (entry->data.rnti == rnti) {
            *indirect = entry->next;
            NFAPI_CRC_INDICATION_PDU_T* pdu = &(entry->data);
            free(entry);

            pthread_mutex_unlock(&list_lock);
            log_message("PDU removed.", LOG_LEVEL_INFO);
            return pdu;
        }
        indirect = &entry->next;
    }

    pthread_mutex_unlock(&list_lock);
    log_message("PDU not found for removal.", LOG_LEVEL_DEBUG);
    return NULL;
}

// Read integers from stdin into a dynamic array
int read_integers_from_stdin(size_t max_size) {
    int number, capacity = 10;
    int_array = (int*)malloc(capacity * sizeof(int));

    if (!int_array) {
        log_message("Memory allocation failed for integer array.", LOG_LEVEL_DEBUG);
        return -1;
    }

    size_t count = 0;
    while (count < max_size && scanf("%d", &number) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            int* temp = realloc(int_array, capacity * sizeof(int));
            if (!temp) {
                log_message("Memory reallocation failed for integer array.", LOG_LEVEL_DEBUG);
                free(int_array);
                return -1;
            }
            int_array = temp;
        }

        pthread_mutex_lock(&array_lock);
        int_array[count++] = number;
        pthread_mutex_unlock(&array_lock);
    }

    int_array_size = count;
    log_message("Integers read from stdin.", LOG_LEVEL_INFO);
    return 0;
}

// Find the maximum value in the integer array
int find_max_in_array() {
    pthread_mutex_lock(&array_lock);

    if (int_array_size == 0) {
        pthread_mutex_unlock(&array_lock);
        log_message("No integers to evaluate for max.", LOG_LEVEL_DEBUG);
        return INT_MIN;
    }

    int max_value = INT_MIN;
    for (size_t i = 0; i < int_array_size; ++i) {
        if (int_array[i] > max_value) {
            max_value = int_array[i];
        }
    }

    pthread_mutex_unlock(&array_lock);
    log_message("Maximum value found.", LOG_LEVEL_INFO);
    return max_value;
}

// Periodic garbage collection
void garbage_collect() {
    // Placeholder for garbage collection logic, e.g., checking for unused memory blocks.
    // As an example, this function can be used to periodically clean up or optimize resources.

    pthread_mutex_lock(&list_lock);

    Node *current = head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL;

    pthread_mutex_unlock(&list_lock);

    if (int_array) {
        pthread_mutex_lock(&array_lock);
        free(int_array);
        int_array = NULL;
        int_array_size = 0;
        pthread_mutex_unlock(&array_lock);
    }

    log_message("Garbage collection completed.", LOG_LEVEL_INFO);
}

// Main function
int main() {
    srand(time(NULL));

    // Initialize mutexes
    if (pthread_mutex_init(&list_lock, NULL) != 0 ||
        pthread_mutex_init(&array_lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return EXIT_FAILURE;
    }

    log_message("Application started.", LOG_LEVEL_INFO);

    // Example usage of the functions
    NFAPI_CRC_INDICATION_PDU_T pdu = {{0}, 12345};
    insert_pdu(pdu);

    if (read_integers_from_stdin(100) == 0) {
        printf("Maximum value: %d\n", find_max_in_array());
    }

    garbage_collect();

    // Clean up
    pthread_mutex_destroy(&list_lock);
    pthread_mutex_destroy(&array_lock);

    log_message("Application terminated.", LOG_LEVEL_INFO);

    return EXIT_SUCCESS;
}
