        uint16_t rnti = 0;
        if (fetch_valid_rnti(&rnti) < 0 || !validate_rnti(rnti)) {
            fprintf(stderr, "Failed to fetch or validate RNTI for index %zu.\n", i);
            free(pdu);
            pthread_mutex_unlock(&lock);

            free(entries[i].buffer);
            continue;  // Skip this entry and proceed
        }

        pdu->ue_info_tag.RNTI = rnti;
        pdu->rnti = rnti;
        pdu->crc_ind_rel8.CRCFLAG = rand() % 2;

        memcpy(entries[i].buffer, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        pthread_mutex_unlock(&lock);
    }
