// Define a node in the doubly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

// Global head and tail pointers for the doubly linked list
Node* head = NULL;
Node* tail = NULL;

// Mutex for thread-safe operations
pthread_mutex_t lock;

// Function to initialize a new node
Node* create_node(int rx_ue_tag, int rnti) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->data.RNTI = rnti;
    new_node->data.crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a node in ascending order based on RX_UE_INFORMATION_TAG and RNTI
void insert_sorted(int rx_ue_tag, int rnti) {
    pthread_mutex_lock(&lock);

    Node* new_node = create_node(rx_ue_tag, rnti);
    if (!new_node) return;

    // Insert at the head if list is empty or new node has smallest value
    if (!head || (rx_ue_tag < head->data.RX_UE_INFORMATION_TAG) ||
        ((rx_ue_tag == head->data.RX_UE_INFORMATION_TAG) && (rnti < head->data.RNTI))) {
        new_node->next = head;
        if (head) head->prev = new_node;
        head = new_node;
    } else {
        Node* current = head;
        while (current->next &&
               ((current->next->data.RX_UE_INFORMATION_TAG < rx_ue_tag) ||
                ((current->next->data.RX_UE_INFORMATION_TAG == rx_ue_tag) &&
                 (current->next->data.RNTI < rnti)))) {
            current = current->next;
        }
        new_node->next = current->next;
        if (current->next) current->next->prev = new_node;
        current->next = new_node;
        new_node->prev = current;
    }

    // Update tail if necessary
    if (!tail || new_node->data.RX_UE_INFORMATION_TAG > tail->data.RX_UE_INFORMATION_TAG ||
        (new_node->data.RX_UE_INFORMATION_TAG == tail->data.RX_UE_INFORMATION_TAG &&
         new_node->data.RNTI > tail->data.RNTI)) {
        tail = new_node;
    }

    pthread_mutex_unlock(&lock);
}

// Transaction processing module
