        }
    }

    // Output results
    printf("Max Weighted Sum: %.2f, Transaction ID: %d\n", max_weighted_sum, max_transaction_id);
}

// Initialize the mutex
void init_mutex() {
    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        exit(EXIT_FAILURE);
    }
}

// Cleanup function to free memory and destroy mutex
void cleanup() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}

// Main function to demonstrate usage
