#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>

#define INITIAL_CAPACITY 10
#define BUFFER_SIZE 1024

typedef enum {
    CONNECTION_FREE,
    CONNECTION_ACTIVE,
    CONNECTION_CLOSED
} ConnectionState;

typedef struct {
    int socket_fd;
    char buffer[BUFFER_SIZE];
    ConnectionState status;
} Connection;

typedef struct {
    Connection *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConnectionList;

ConnectionList* create_connection_list() {
    ConnectionList *list = malloc(sizeof(ConnectionList));
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->connections = malloc(sizeof(Connection) * list->capacity);
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_connection_list(ConnectionList *list) {
    size_t new_capacity = list->capacity * 2;
    Connection *new_connections = realloc(list->connections, sizeof(Connection) * new_capacity);
    if (new_connections) {
        list->connections = new_connections;
        list->capacity = new_capacity;
    } else {
        perror("Failed to resize connection list");
        exit(EXIT_FAILURE);
    }
}

int add_connection(ConnectionList *list, int socket_fd) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        resize_connection_list(list);
    }

    Connection *conn = &list->connections[list->count++];
    conn->socket_fd = socket_fd;
    memset(conn->buffer, 0, BUFFER_SIZE);
    conn->status = CONNECTION_ACTIVE;

    pthread_mutex_unlock(&list->lock);

    // Log connection event
    printf("Connection added: fd %d\n", socket_fd);

    return 0;
}

void remove_connection(ConnectionList *list, int socket_fd) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->connections[i].socket_fd == socket_fd) {
            list->connections[i].status = CONNECTION_CLOSED;
            // Log connection close event
            printf("Connection closed: fd %d\n", socket_fd);
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void process_packets(ConnectionList *list) {
    while (1) {
        for (size_t i = 0; i < list->count; ++i) {
            Connection *conn = &list->connections[i];
            if (conn->status == CONNECTION_ACTIVE) {
                ssize_t bytes_received = recv(conn->socket_fd, conn->buffer, BUFFER_SIZE - 1, 0);
                if (bytes_received > 0) {
                    // Process packet
                    printf("Received %zd bytes on fd %d\n", bytes_received, conn->socket_fd);
                } else if (bytes_received == 0 || (bytes_received < 0 && errno != EWOULDBLOCK)) {
                    remove_connection(list, conn->socket_fd);
                }
            }
        }
        usleep(10000); // Sleep briefly to reduce CPU usage
    }
}

void cleanup(ConnectionList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->connections[i].status != CONNECTION_FREE) {
            close(list->connections[i].socket_fd);
        }
    }

    free(list->connections);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    ConnectionList *conn_list = create_connection_list();

    // Example: Add a connection
    int socket_fd = 1; // Placeholder for an actual socket descriptor
    add_connection(conn_list, socket_fd);

    // Start packet processing in a separate thread
    pthread_t processing_thread;
    if (pthread_create(&processing_thread, NULL, (void *(*)(void *))process_packets, conn_list) != 0) {
        perror("Failed to create packet processing thread");
        cleanup(conn_list);
        return EXIT_FAILURE;
    }

    // Wait for the processing thread to finish
    pthread_join(processing_thread, NULL);

    cleanup(conn_list);
    return 0;
}
