DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*) malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->elements = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Function to free the dynamic array.
void destroy_dynamic_array(DynamicArray *array) {
    if (!array) return;
    pthread_mutex_lock(&array->lock);
    free(array->elements);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Internal function to ensure the dynamic array has enough capacity.
void ensure_capacity(DynamicArray *array, size_t new_capacity) {
    if (new_capacity > array->capacity) {
        size_t new_size = new_capacity > 1 ? new_capacity : 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(array->elements, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) return; // Handle allocation failure gracefully.
        array->elements = new_elements;
        array->capacity = new_size;
    }
}

// Function to add a new element.
int add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->lock);

    if (!element.valid || !element.RNTI) { // Basic validation
        pthread_mutex_unlock(&array->lock);
        return -1; // Invalid data.
    }

    ensure_capacity(array, array->size + 1);
    array->elements[array->size++] = element;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

// Function to remove an element by RNTI.
