                    (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --array->size;
            pthread_mutex_unlock(&array->lock);
            return 0; // Successfully removed.
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Element not found.
}

