// Function to get statistics from the dynamic array.
void get_statistics(DynamicArray *array, size_t *num_elements, float *average_crc_flag, unsigned int *max_rnti) {
    if (!array || !num_elements || !average_crc_flag || !max_rnti) return;

    pthread_mutex_lock(&array->lock);

    *num_elements = array->size;
    float sum_crc_flags = 0;
    *max_rnti = 0;

