#include <arpa/inet.h>
#include <errno.h>
#include <time.h>

#define MAX_CONNECTIONS 100
#define INITIAL_BUFFER_SIZE 1024
#define PACKET_TIMEOUT 30 // seconds
#define LOG_FILE "network_interface.log"
#define MTU 1500

typedef struct {
    int socket;
    char *buffer;
    size_t buffer_size;
    int status; // 0: inactive, 1: active
    time_t last_packet_received;
} Connection;

typedef struct {
    Connection *connections;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int max_connections;
} NetworkInterface;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        fprintf(log, "[%s] %s\n", ctime(&now), event);
        fclose(log);
    }
}

int allocate_buffer(char **buffer, size_t new_size) {
    char *new_buf = realloc(*buffer, new_size);
    if (!new_buf) return -1;
    *buffer = new_buf;
    return 0;
}

void initialize_network_interface(NetworkInterface *ni, int max_connections) {
    ni->connections = malloc(sizeof(Connection) * MAX_CONNECTIONS);
    if (!ni->connections) {
        log_event("Memory allocation failed for connection list");
        exit(EXIT_FAILURE);
    }
    ni->capacity = MAX_CONNECTIONS;
    pthread_mutex_init(&ni->lock, NULL);
    pthread_cond_init(&ni->cond, NULL);
    ni->max_connections = max_connections;

    for (size_t i = 0; i < ni->capacity; ++i) {
        ni->connections[i].socket = -1;
        ni->connections[i].buffer = malloc(INITIAL_BUFFER_SIZE);
        if (!ni->connections[i].buffer) {
            log_event("Memory allocation failed for connection buffer");
            exit(EXIT_FAILURE);
        }
        ni->connections[i].buffer_size = INITIAL_BUFFER_SIZE;
        ni->connections[i].status = 0;
    }
}

void handle_connection(NetworkInterface *ni, int conn_fd) {
    pthread_mutex_lock(&ni->lock);

    // Find an inactive slot or expand the list
    size_t i;
    for (i = 0; i < ni->capacity && ni->connections[i].status == 1; ++i);
    if (i >= ni->capacity) { // List full, check capacity and resize if needed
        if (ni->capacity * 2 <= MAX_CONNECTIONS) {
            Connection *new_connections = realloc(ni->connections, sizeof(Connection) * ni->capacity * 2);
            if (!new_connections) {
                log_event("Memory allocation failed while resizing connection list");
                pthread_mutex_unlock(&ni->lock);
                return;
            }
            ni->connections = new_connections;
            for (size_t j = ni->capacity; j < ni->capacity * 2; ++j) {
                ni->connections[j].socket = -1;
                char *buffer = malloc(INITIAL_BUFFER_SIZE);
                if (!buffer) {
                    log_event("Memory allocation failed for connection buffer");
                    pthread_mutex_unlock(&ni->lock);
                    exit(EXIT_FAILURE);
                }
                ni->connections[j].buffer = buffer;
                ni->connections[j].buffer_size = INITIAL_BUFFER_SIZE;
                ni->connections[j].status = 0;
            }
            ni->capacity *= 2;
        } else {
            log_event("Maximum connections reached");
            pthread_mutex_unlock(&ni->lock);
            return;
        }
    }

    ni->connections[i].socket = conn_fd;
    ni->connections[i].status = 1;
    ni->connections[i].last_packet_received = time(NULL);

    log_event("New connection established");

    pthread_mutex_unlock(&ni->lock);
}

void process_packets(NetworkInterface *ni) {
    while (1) {
        pthread_mutex_lock(&ni->lock);

        for (size_t i = 0; i < ni->capacity; ++i) {
            if (ni->connections[i].status == 1 && ni->connections[i].socket != -1) {
                ssize_t bytes_received;
                char *buffer = realloc(ni->connections[i].buffer, MTU);
                if (!buffer) {
                    log_event("Memory allocation failed for packet buffer");
                    pthread_mutex_unlock(&ni->lock);
                    continue;
                }
                ni->connections[i].buffer = buffer;
                ni->connections[i].buffer_size = MTU;

                bytes_received = recv(ni->connections[i].socket, ni->connections[i].buffer, MTU, 0);
                if (bytes_received <= 0) {
                    log_event("Connection closed or error occurred");
                    close(ni->connections[i].socket);
                    ni->connections[i].status = 0;
                    ni->connections[i].last_packet_received = time(NULL); // Mark as inactive
                    continue;
                }
                ni->connections[i].buffer_size = bytes_received;
                ni->connections[i].last_packet_received = time(NULL);

                log_event("Packet received");
            } else if (ni->connections[i].status == 1 && difftime(time(NULL), ni->connections[i].last_packet_received) > PACKET_TIMEOUT) {
                // Timeout logic
                log_event("Connection timed out");
                close(ni->connections[i].socket);
                ni->connections[i].status = 0;
            }
        }

        pthread_mutex_unlock(&ni->lock);

        usleep(10000); // Sleep to reduce CPU usage
    }
}

void close_connections(NetworkInterface *ni) {
    pthread_mutex_lock(&ni->lock);
    for (size_t i = 0; i < ni->capacity; ++i) {
        if (ni->connections[i].status == 1 && ni->connections[i].socket != -1) {
            log_event("Closing connection");
            close(ni->connections[i].socket);
            ni->connections[i].status = 0;
        }
    }
    pthread_mutex_unlock(&ni->lock);

    for (size_t i = 0; i < ni->capacity; ++i) {
        free(ni->connections[i].buffer);
    }

    free(ni->connections);
    pthread_mutex_destroy(&ni->lock);
    pthread_cond_destroy(&ni->cond);
}

int main() {
    NetworkInterface ni;
    initialize_network_interface(&ni, 50);

    // Simulate handling connections and packet processing
    // In a real application, you'd use select/poll or similar to accept connections

    pthread_t process_thread;
    pthread_create(&process_thread, NULL, (void *)process_packets, &ni);
    pthread_join(process_thread, NULL);

    close_connections(&ni);
    return 0;
}
