#define INITIAL_BUFFER_SIZE 100
#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    size_t capacity;
    size_t count;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

typedef struct {
    CircularBuffer *circular_buffer;
    int structures_processed;
    int memory_limits_reached;
    int performance_bottlenecks;
} BufferManager;

static unsigned char generate_crc_flag() {
    return rand() % 2;
}

void seed_rng() {
    srand((unsigned)time(NULL));
}

CircularBuffer* create_circular_buffer(size_t capacity) {
    CircularBuffer *cb = malloc(sizeof(CircularBuffer));
    cb->buffer = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cb->capacity = capacity;
    cb->count = 0;
    cb->head = 0;
    cb->tail = 0;
    pthread_mutex_init(&cb->lock, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);
    return cb;
}

void destroy_circular_buffer(CircularBuffer *cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->lock);
    pthread_cond_destroy(&cb->not_full);
    pthread_cond_destroy(&cb->not_empty);
    free(cb);
}

int enqueue(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&cb->lock);
    while (cb->count == cb->capacity) {
        pthread_cond_wait(&cb->not_full, &cb->lock);
    }
    cb->buffer[cb->tail] = item;
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->count++;
    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->lock);
    return 0;
}

int dequeue(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&cb->lock);
    while (cb->count == 0) {
        pthread_cond_wait(&cb->not_empty, &cb->lock);
    }
    *item = cb->buffer[cb->head];
    cb->head = (cb->head + 1) % cb->capacity;
    cb->count--;
    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->lock);
    return 0;
}

void resize_circular_buffer(CircularBuffer *cb, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_buffer = malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size_t i, j;

    for (i = 0, j = cb->head; i < cb->count; ++i, j = (j + 1) % cb->capacity) {
        new_buffer[i] = cb->buffer[j];
    }

    free(cb->buffer);
    cb->buffer = new_buffer;
    cb->capacity = new_capacity;
    cb->head = 0;
    cb->tail = cb->count;
}

void initialize_and_manage_list(BufferManager *bm, size_t initial_capacity) {
    seed_rng();
    bm->circular_buffer = create_circular_buffer(initial_capacity);

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_t thread_id;
        int rc = pthread_create(&thread_id, NULL, process_pdu_thread, (void *)bm);
        if (rc) {
            fprintf(stderr, "Error: unable to create thread %d\n", rc);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for threads to complete processing
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(thread_id, NULL);
    }

    printf("Structures processed: %d\n", bm->structures_processed);
    printf("Memory limits reached: %d times\n", bm->memory_limits_reached);
    printf("Performance bottlenecks encountered: %d times\n", bm->performance_bottlenecks);

    destroy_circular_buffer(bm->circular_buffer);
}

void* process_pdu_thread(void *arg) {
    BufferManager *bm = (BufferManager *)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (1) { // Replace with appropriate termination condition
        memset(&pdu, 0, sizeof(pdu));
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 1000;
        generate_crc_flag(); // Seed the RNG based on system time

        for (int i = 0; i < 4; ++i) {
            pdu.CRC_INDICATION_REL8_TAG[i] = rand();
        }

        if (enqueue(bm->circular_buffer, pdu) == -1) {
            bm->memory_limits_reached++;
            // Consider resizing the buffer here
        }

        NFAPI_CRC_INDICATION_PDU_T dequeued_pdu;
        if (dequeue(bm->circular_buffer, &dequeued_pdu) == 0) {
            // Process dequeued_pdu...
            bm->structures_processed++;
        }

        // Simulate processing time and workload management
    }

    return NULL;
}
