// Define a pool structure for memory pooling
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock; // For thread safety during initialization
} MemoryPool;

// Initialize memory pool
void initialize_memory_pool(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    mp->pool_size = size;
    pthread_mutex_unlock(&mp->lock);
}

// Deallocate memory pool
void deallocate_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    mp->pool = NULL;
    mp->pool_size = 0;
}

