            logError("Invalid RNTI detected.", array);
            continue; // Skip invalid entries
        }

        // Add new PDU to the array
        if (array->size >= array->capacity) {
            resizePDUArray(array); // Resize if capacity is exceeded
        }

        array->data[array->size++] = newPDU;

        // Log performance metrics every second
