        if (difftime(currentTime, array->lastLogTime) >= 1.0) {
            fprintf(array->logFile, "Processed %zu PDUs.\n", array->size);
            fflush(array->logFile); // Ensure logging is done immediately
            array->lastLogTime = currentTime;
        }

        // Simulate real-time processing delay (e.g., 1 millisecond per session)
        usleep(1000);
    }
}

// Resize the PDU array when capacity is exceeded
void resizePDUArray(PDUArray* array) {
    size_t newCapacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* newData = realloc(array->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!newData) {
        logError("Memory allocation failed during resize.", array);
        exit(EXIT_FAILURE); // Handle memory allocation failure
    }

    array->data = newData;
    array->capacity = newCapacity;
}

// Check if the RNTI is valid (dummy implementation)
