    return rnti <= MAX_UE_SESSIONS; // Example validation logic
}

// Log errors to the specified file with frequency control
void logError(const char* message, PDUArray* array) {
    time_t currentTime = time(NULL);
    if (difftime(currentTime, array->lastLogTime) >= 1.0) { // Limit logging frequency
        fprintf(array->logFile, "ERROR: %s\n", message);
        fflush(array->logFile); // Ensure immediate writing to file
        array->lastLogTime = currentTime;
    }
}

// Example of initializing and using the PDUArray
int main() {
