    pduArray.capacity = INITIAL_CAPACITY;
    pduArray.data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pduArray.logFile = logFile;

    if (!pduArray.data) {
        fclose(logFile);
