['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
} NFALIST;

NFALIST* create_list() {
    NFALIST *list = (NFALIST*)malloc(sizeof(NFALIST));
    if (!list) return NULL;

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    for (int i = 0; i < MAX_RECORDS; i++) {
        list->records[i] = NULL;
    }
    return list;
}

void destroy_list(NFALIST *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        free(list->records[i]);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_record(NFALIST *list, uint16_t rx_tag, uint16_t rnti) {
    if (!list || list->count >= MAX_RECORDS) return -1;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_rec = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(alignof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_rec) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_rec->RX_UE_INFORMATION_TAG = rx_tag;
    new_rec->RNTI = rnti;
    new_rec->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->records[list->count++] = new_rec;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_record(NFALIST *list, uint16_t rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; i++) {
        if (list->records[i]->RNTI == rnti) {
            free(list->records[i]);
            memmove(&list->records[i], &list->records[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->count - i - 1));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int update_crcflag_by_rx_tag(NFALIST *list, uint16_t rx_tag, uint8_t new_crcflag) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; i++) {
        if (list->records[i]->RX_UE_INFORMATION_TAG == rx_tag) {
            list->records[i]->crc_tag.CRCFLAG = new_crcflag;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

uint32_t calculate_crc(NFALIST *list) {
    if (!list) return -1;

    uint32_t crc = 0; // Simplified CRC calculation for example purposes

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *rec = list->records[i];
        crc += rec->RX_UE_INFORMATION_TAG + rec->RNTI + rec->crc_tag.CRCFLAG;
    }

    pthread_mutex_unlock(&list->lock);

    return crc;
}
```

This code provides a thread-safe implementation of managing dynamic lists with structures containing specific fields. It includes functions to create and destroy the list, add or remove records based on certain conditions, update fields within the records efficiently, and calculate a simplified checksum for data integrity verification. Memory allocation is handled with proper checks, ensuring graceful handling of potential allocation failures.']

