        return NULL;
    }

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void* pool_ptr = custom_alloc(N * struct_size);

    if (pool_ptr == NULL) {
        void* heap_ptr = alternative_alloc(N * struct_size);
        if (heap_ptr == NULL) {
            fprintf(stderr, "Out of memory.\n");
