typedef struct LTE_DL_FRAME_MSG_NODE {
    DL_FRAME_INFO frame_info;
    PHY_PARAMS phy_params;
    CHANNEL_MEASUREMENT channel_measurement;
    int frame_number;
    int time_slot_index;
    struct LTE_DL_FRAME_MSG_NODE *prev;
    struct LTE_DL_FRAME_MSG_NODE *next;
} LTE_DL_FRAME_MSG_NODE;

typedef struct {
    pthread_mutex_t lock;
    LTE_DL_FRAME_MSG_NODE* head;
} DoublyLinkedList;

DoublyLinkedList* initialize_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

void free_list_node(LTE_DL_FRAME_MSG_NODE* node) {
    free(node);
}

void insert_in_order(DoublyLinkedList* list, LTE_DL_FRAME_MSG_NODE* new_node) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || (new_node->frame_number < list->head->frame_number ||
        (new_node->frame_number == list->head->frame_number &&
         new_node->time_slot_index <= list->head->time_slot_index))) {
        new_node->next = list->head;
        if (list->head) list->head->prev = new_node;
        list->head = new_node;
    } else {
        LTE_DL_FRAME_MSG_NODE* current = list->head;
        while (current->next && 
               (current->next->frame_number < new_node->frame_number ||
                (current->next->frame_number == new_node->frame_number &&
                 current->next->time_slot_index < new_node->time_slot_index))) {
            current = current->next;
        }
        new_node->next = current->next;
        if (current->next) current->next->prev = new_node;
        current->next = new_node;
        new_node->prev = current;
    }

    pthread_mutex_unlock(&list->lock);
}

void populateAndProcessFrames(DoublyLinkedList* list, int frame_count, int measurement_range_min, int measurement_range_max, size_t crc_pdu_count) {
    srand(time(NULL));

    for (int i = 0; i < frame_count; ++i) {
        LTE_DL_FRAME_MSG_NODE* node = (LTE_DL_FRAME_MSG_NODE*)malloc(sizeof(LTE_DL_FRAME_MSG_NODE));
        if (!node) continue;

        node->frame_info.subframe = rand() % 10;
        node->frame_info.symbol = rand() % 14;
        node->phy_params.parameter1 = rand();
        node->phy_params.parameter2 = rand();
        node->channel_measurement.measurement_value = (double)(rand() % (measurement_range_max - measurement_range_min + 1)) + measurement_range_min;
        node->frame_number = i;
        node->time_slot_index = rand() % 10;

        insert_in_order(list, node);
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(crc_pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_pdus) return;

    for (size_t i = 0; i < crc_pdu_count; ++i) {
        crc_pdus[i].RNTI = rand();
        crc_pdus[i].RX_UE_INFORMATION_TAG = rand() % 256;
        crc_pdus[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    }
}

void free_c_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    LTE_DL_FRAME_MSG_NODE* current = list->head;
    while (current) {
        LTE_DL_FRAME_MSG_NODE* next_node = current->next;
        free_list_node(current);
        current = next_node;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

