#define MAX_ELEMENTS 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(size_t size) {
    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->table = (Node**)calloc(size, sizeof(Node*));
    hashTable->size = size;
    pthread_mutex_init(&hashTable->lock, NULL);
    return hashTable;
}

unsigned int hashRNTI(uint16_t rnti, size_t size) {
    return rnti % size;
}

int insertHashTable(HashTable* hashTable, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&hashTable->lock);
    unsigned int index = hashRNTI(pdu.RNTI, hashTable->size);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&hashTable->lock);
        return -1;
    }
    newNode->data = pdu;
    newNode->next = hashTable->table[index];
    hashTable->table[index] = newNode;
    pthread_mutex_unlock(&hashTable->lock);
    return 0;
}

int checkHashTable(HashTable* hashTable, uint16_t rnti) {
    unsigned int index = hashRNTI(rnti, hashTable->size);
    Node* node = hashTable->table[index];
    while (node) {
        if (node->data.RNTI == rnti) {
            return 1;
        }
        node = node->next;
    }
    return 0;
}

void freeHashTable(HashTable* hashTable) {
    for (size_t i = 0; i < hashTable->size; ++i) {
        Node* node = hashTable->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(hashTable->table);
    pthread_mutex_destroy(&hashTable->lock);
    free(hashTable);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    size_t capacity;
    HashTable* hashTable;
} PduList;

PduList* createPduList(size_t initialCapacity, size_t hashTableSize) {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initialCapacity;
    list->hashTable = createHashTable(hashTableSize);
    return list;
}

int addPdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->count >= MAX_ELEMENTS || checkHashTable(list->hashTable, pdu.RNTI)) {
        return -1;
    }
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        if (newCapacity > MAX_ELEMENTS) newCapacity = MAX_ELEMENTS;
        NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) return -1;
        list->data = newData;
        list->capacity = newCapacity;
    }
    list->data[list->count++] = pdu;
    insertHashTable(list->hashTable, pdu);
    return 0;
}

void freePduList(PduList* list) {
    free(list->data);
    freeHashTable(list->hashTable);
    free(list);
}

uint16_t allocateRNTI() {
    // Simulate RNTI allocation with random value
    return rand() % (MAX_ELEMENTS / 2) + 1;
}

int initializePdu(PduList* list, uint16_t rxTag, uint8_t crcIndRel8Tag) {
    for (int attempt = 0; attempt < 5; ++attempt) {
