        pdu.RX_UE_INFORMATION_TAG = rxTag;
        pdu.RNTI = rnti;
        pdu.CRC_INDICATION_REL8_TAG = crcIndRel8Tag;
        pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        if (addPdu(list, pdu) == 0) {
            return 0;
        }
    }
    return -1;
}

void logOperation(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int main() {
    srand(time(NULL));
    PduList* list = createPduList(10, 1000);

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (initializePdu(list, i + 1, rand() % 256)) {
            logOperation("Failed to initialize PDU");
            break;
        }
        logOperation("Successfully initialized PDU");
    }

    freePduList(list);
    return 0;
}
