unsigned long hash_cell_id(int cell_id) {
    return (unsigned long)cell_id;
}

int log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
    return 0;
}

DynamicQueue* create_queue(DynamicQueue* dq, int (*log_func)(const char*)) {
    if (!dq) {
        dq = (DynamicQueue*)malloc(sizeof(DynamicQueue));
        if (!dq) return NULL;
    }
    dq->head = NULL;
    dq->size = 0;
    dq->capacity = MAX_QUEUE_SIZE;
    dq->log_func = log_func;
    return dq;
}

void free_queue(DynamicQueue* dq) {
    Node* current = dq->head;
    while (current) {
        Node* next = current->next;
        // Free CHANNEL_CONFIGURATIONS if necessary
        free(current);
        current = next;
    }
    free(dq);
}

int enqueue(DynamicQueue* dq, NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T item, int retry_count) {
    if (dq->size >= dq->capacity) return -1;

    unsigned long cell_id_hash = hash_cell_id(item.CELL_ID);

    Node** curr = &dq->head;
    while (*curr) {
        if ((*curr)->data.CELL_ID == item.CELL_ID)
            return -2; // Duplicate CELL_ID
        curr = &(*curr)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = item;
    new_node->next = NULL;
    *curr = new_node;
    dq->size++;

    if (dq->log_func)
        dq->log_func("Enqueued successfully");

    return 0;
}

int fetch_and_enqueue(DynamicQueue* dq, int cell_id, int rrc_version, void* channel_configurations) {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T request = {cell_id, rrc_version, channel_configurations};
    int retry_count = 0;

    while (retry_count < RETRY_LIMIT) {
        // Simulate data fetch with potential failure
        if (rand() % 2 == 0) { // Randomly fail to simulate external service delay
            sleep(1 << retry_count); // Exponential backoff
            retry_count++;
            continue;
        }

        int result = enqueue(dq, request, retry_count);
        if (result == 0) return 0; // Success

        if (result == -2 && retry_count < RETRY_LIMIT) {
            sleep(1 << retry_count); // Backoff for duplicate CELL_ID
            retry_count++;
        } else {
            break;
        }
    }

    if (dq->log_func)
        dq->log_func("Failed to enqueue after retries");

    return -1; // Failure after retries
}

int main() {
    DynamicQueue* queue = create_queue(NULL, log_message);
    if (!queue) return 1;

    // Example usage
    int cell_id = 123;
    int rrc_version = 8;
    void* channel_configurations = NULL; // Replace with actual initialization

    fetch_and_enqueue(queue, cell_id, rrc_version, channel_configurations);

    free_queue(queue);
    return 0;
}
