#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int MEASUREMENT_REPORT_ID;
    int CELL_ID;
    float RSRP_LEVEL;
} LTE_MEASUREMENT_REPORT;

typedef struct Node {
    LTE_MEASUREMENT_REPORT report;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    unsigned long cell_id_cache[1000]; // Example cache size
} ReportList;

ReportList* create_report_list() {
    ReportList* list = (ReportList*)malloc(sizeof(ReportList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    memset(list->cell_id_cache, -1, sizeof(list->cell_id_cache)); // Initialize cache
    return list;
}

int is_duplicate_cell_id(ReportList* list, int cell_id) {
    Node* current = list->head;
    while (current) {
        if (current->report.CELL_ID == cell_id) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0;
}

int add_report(ReportList* list, LTE_MEASUREMENT_REPORT report) {
    if (list->size >= MAX_ELEMENTS) {
        log_error("Max elements reached.");
        return -1;
    }

    // Check for duplicate CELL_ID with backoff strategy
    int retries = 3;
    while (retries > 0) {
        if (!is_duplicate_cell_id(list, report.CELL_ID)) break;
        sleep(1); // Simple backoff strategy
        retries--;
    }
    if (retries == 0) {
        log_error("Duplicate CELL_ID after retries.");
        return -2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed.");
        return -3;
    }
    new_node->report = report;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    // Cache the CELL_ID
    for (int i = 0; i < sizeof(list->cell_id_cache) / sizeof(list->cell_id_cache[0]); i++) {
        if (list->cell_id_cache[i] == -1) {
            list->cell_id_cache[i] = report.CELL_ID;
            break;
        }
    }

    log_info("Report added successfully.");
    return 0;
}

void free_report_list(ReportList* list) {
    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    free(list);
    log_info("Report list freed.");
}

void log_info(const char* message) {
    time_t now = time(NULL);
    printf("[%s] INFO: %s\n", ctime(&now), message);
}

void log_error(const char* message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] ERROR: %s\n", ctime(&now), message);
}

// Example usage
int main() {
    ReportList* list = create_report_list();
    if (!list) return -1;

    LTE_MEASUREMENT_REPORT report = {1, 12345, -95.5};
    add_report(list, report);

    free_report_list(list);
    return 0;
}
