    return (pdu->RNTI >= VALID_RNTI_MIN && pdu->RNTI <= VALID_RNTI_MAX);
}

void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return;

    array->data = new_data;
    array->capacity = new_capacity;
}

void log_error(const char *message) {
    static pthread_mutex_t log_lock;
    static time_t last_log_time = 0;

    pthread_once(&log_lock, PTHREAD_ONCE_INIT);

    time_t current_time = time(NULL);
    if (difftime(current_time, last_log_time) >= 1.0) {
        pthread_mutex_lock(&log_lock);
        FILE *logfile = fopen("error.log", "a");
        if (logfile) {
            fprintf(logfile, "%s\n", message);
            fclose(logfile);
        }
        pthread_mutex_unlock(&log_lock);
        last_log_time = current_time;
    }
}

