#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1024
#define MAX_DATA_SIZE (10 * 1024) // 10KB

typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    unsigned short rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Global variables for thread safety
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;

void insert_sorted(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list_lock);

    Node** current = &head;
    while (*current && (*current)->data.rnti < pdu.rnti) {
        current = &(*current)->next;
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    newNode->data = pdu;
    newNode->next = *current;

    *current = newNode;

    pthread_mutex_unlock(&list_lock);
}

int list_size() {
    int size = 0;
    Node* current = head;
    while (current) {
        size++;
        current = current->next;
    }
    return size;
}

void serialize_list(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list_lock);

    Node* current = head;
    while (current && fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
    fclose(file);
}

void free_list() {
    pthread_mutex_lock(&list_lock);

    Node* current = head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;

    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.rx_ue_information_tag.RNTI = rand();
    pdu.rnti = (unsigned short)rand() % 65536; // RNTI is typically up to 16 bits
    pdu.crc_indication_rel8_tag.CRCFLAG = rand() & 0x01; // Random binary flag

    return pdu;
}

void generate_linked_list(size_t n) {
    if (n > MAX_ELEMENTS || list_size() + n > MAX_ELEMENTS) {
        fprintf(stderr, "Exceeds maximum allowed elements\n");
        return;
    }

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        insert_sorted(pdu);
    }
}

int main() {
    srand(time(NULL));

    // Example usage
    generate_linked_list(100); // Generate and sort 100 elements

    serialize_list("linked_list.bin"); // Serialize to a file

    free_list(); // Clean up the linked list
    return 0;
}
