#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
DynamicArray* init_dynamic_array() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    pthread_mutex_init(&da->lock, NULL);
    da->capacity = INITIAL_SIZE;
    da->size = 0;
    da->array = calloc(da->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    return da;
}

// Resize the array
int resize_array(DynamicArray* da, size_t new_capacity) {
    pthread_mutex_lock(&da->lock);
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    da->capacity = new_capacity;
    da->array = temp;
    memset(da->array + da->size, 0, (new_capacity - da->size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&da->lock);
    return 0;
}

// Add a new element to the array
int add_element(DynamicArray* da, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity) {
        if (resize_array(da, da->capacity * 2) != 0) {
            pthread_mutex_unlock(&da->lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &da->array[da->size];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    element->CRCFLAG = rand() % 2; // Randomly 0 or 1

    da->size++;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

// Iterate over the array
void iterate_array(DynamicArray* da, void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        operation(&da->array[i]);
    }

    pthread_mutex_unlock(&da->lock);
}

// Integrate with external data source
void update_from_external_source(DynamicArray* da, int new_RX_UE_INFORMATION_TAG, int new_RNTI) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        da->array[i].RX_UE_INFORMATION_TAG = new_RX_UE_INFORMATION_TAG;
        da->array[i].RNTI = new_RNTI;
    }

    pthread_mutex_unlock(&da->lock);
}

// Clean up the dynamic array
void destroy_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);

    free(da->array);
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
    free(da);
}
