} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    pthread_mutex_t mutex;
} CRCHashMap;

unsigned int hash_function(uint16_t rnti, size_t size) {
    return (rnti * 2654435761u) % size;
}

int is_parity_even(uint8_t data) {
    int count = 0;
    while(data) {
        count += data & 1;
        data >>= 1;
    }
    return !(count % 2);
}

void toggle_bit_to_fix_parity(uint8_t* data) {
    for (int i = 0; i < 8; ++i) {
        *data ^= (1 << i);
        if (is_parity_even(*data)) {
            return;
        }
        *data ^= (1 << i); // revert the toggle
    }
}

CRCHashMap* create_crc_hash_map(size_t size) {
    CRCHashMap* map = malloc(sizeof(CRCHashMap));
    map->buckets = calloc(size, sizeof(Node*));
    map->size = size;
    pthread_mutex_init(&map->mutex, NULL);
    return map;
}

void free_crc_hash_map(CRCHashMap* map) {
    for (size_t i = 0; i < map->size; ++i) {
        Node* node = map->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(map->buckets);
    pthread_mutex_destroy(&map->mutex);
    free(map);
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void add_crc_indication(CRCHashMap* map, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pdu.RNTI < 1 || pdu.RNTI > MAX_RNTI) {
        log_error("Invalid RNTI value.");
        return;
    }

    if (!is_parity_even(pdu.crc_indication_rel8_tag.CRCFLAG)) {
        toggle_bit_to_fix_parity(&pdu.crc_indication_rel8_tag.CRCFLAG);
    }

    pthread_mutex_lock(&map->mutex);

    unsigned int index = hash_function(pdu.RNTI, map->size);
    Node* head = map->buckets[index];

    // Update existing node if RNTI is already present
    while (head) {
        if (head->data.RNTI == pdu.RNTI) {
            head->data = pdu;
            pthread_mutex_unlock(&map->mutex);
            return;
        }
        head = head->next;
    }

    // Add new node
    Node* newNode = malloc(sizeof(Node));
    newNode->data = pdu;
    newNode->next = map->buckets[index];
    map->buckets[index] = newNode;

    pthread_mutex_unlock(&map->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_indication(CRCHashMap* map, uint16_t rnti) {
    if (rnti < 1 || rnti > MAX_RNTI) return NULL;

    pthread_mutex_lock(&map->mutex);

    unsigned int index = hash_function(rnti, map->size);
    Node* node = map->buckets[index];

    while (node) {
        if (node->data.RNTI == rnti) {
            pthread_mutex_unlock(&map->mutex);
            return &node->data;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&map->mutex);
    return NULL;
}

void remove_crc_indication(CRCHashMap* map, uint16_t rnti) {
    if (rnti < 1 || rnti > MAX_RNTI) return;

    pthread_mutex_lock(&map->mutex);

    unsigned int index = hash_function(rnti, map->size);
    Node* node = map->buckets[index];
    Node* prev = NULL;

    while (node) {
        if (node->data.RNTI == rnti) {
            if (prev) {
                prev->next = node->next;
            } else {
                map->buckets[index] = node->next;
            }
            free(node);
            pthread_mutex_unlock(&map->mutex);
            return;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&map->mutex);
}

int main() {
    CRCHashMap* crcMap = create_crc_hash_map(1024);

    // Example of adding elements to the hash map
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{ .RNTI = 12345 }, 12345, { .CRCFLAG = 0b10101010 }};
    add_crc_indication(crcMap, pdu1);

    // Retrieve and print an element by RNTI
