    if (retrieved) {
        printf("Retrieved CRCFLAG: %u\n", retrieved->crc_indication_rel8_tag.CRCFLAG);
    }

    // Remove an element by RNTI
    remove_crc_indication(crcMap, 12345);

    free_crc_hash_map(crcMap);
    return 0;
}
