// Free the entire linked list
void freeInterfaceList(InterfaceList* list) {
    ConfigNode *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Add a new configuration
void addNetworkInterfaceConfig(InterfaceList* list, const NetworkInterfaceConfig* config) {
    if (!isValidIPAddress(config->ipAddress) || !isValidIPAddress(config->subnetMask)) {
        return;  // Invalid IP address.
    }

    pthread_mutex_lock(&list->lock);

    ConfigNode* newNode = (ConfigNode*)malloc(sizeof(ConfigNode));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    memcpy(&newNode->config, config, sizeof(NetworkInterfaceConfig));
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

// Remove a configuration by interface name
void removeNetworkInterfaceConfig(InterfaceList* list, const char *interfaceName) {
    pthread_mutex_lock(&list->lock);

    ConfigNode **current = &list->head, *temp;
    while (*current != NULL) {
        if (strcmp((*current)->config.interfaceName, interfaceName) == 0) {
            temp = *current;
            *current = (*current)->next;
            free(temp);
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Iterate over all configurations
void iterateNetworkInterfaceConfigs(InterfaceList* list, void (*callback)(const NetworkInterfaceConfig*)) {
    pthread_mutex_lock(&list->lock);

    ConfigNode *current = list->head;
    while (current != NULL) {
        callback(&current->config);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
