// Function to merge capabilities of two handlers
void merge_capabilities(ProtocolHandler *base, ProtocolHandler *new) {
    // Merging features example
    base->features = realloc(base->features, (base->feature_count + new->feature_count) * sizeof(char *));
    for (size_t i = 0; i < new->feature_count; ++i) {
        base->features[base->feature_count++] = strdup(new->features[i]);
