// Function to load protocol handlers from a directory
Node* load_protocol_handlers(const char *directory_path) {
    DIR *dir;
    struct dirent *entry;
    Node *head = NULL, *tail = NULL;

    if (!(dir = opendir(directory_path))) {
        perror("opendir");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_LNK || entry->d_type == DT_REG) {
            char path[256];
            snprintf(path, sizeof(path), "%s/%s", directory_path, entry->d_name);

            void *handle = dlopen(path, RTLD_NOW);
            if (!handle) continue;

            // Load symbol for handler creation
            ProtocolHandler* (*create_handler)();
            create_handler = (ProtocolHandler* (*)())dlsym(handle, "create_handler");
            if (!create_handler) {
                dlclose(handle);
                continue;
            }

            pthread_mutex_lock(&lock);

            Node *new_node = malloc(sizeof(Node));
            new_node->handler = create_handler();

            // Fetch additional metadata
            fetch_metadata(new_node->handler->name, &new_node->handler->features, &new_node->handler->feature_count);

            if (head == NULL) {
                head = tail = new_node;
                new_node->next = NULL;
            } else {
                Node *current = head;
                while (current != NULL) {
                    if (strcmp(current->handler->name, new_node->handler->name) == 0) {
                        merge_capabilities(current->handler, new_node->handler);
                        free(new_node->handler); // Free duplicate handler
                        free(new_node); // Free node itself
                        pthread_mutex_unlock(&lock);
                        break;
                    }
                    if (current->next == NULL) {
                        current->next = new_node;
                        new_node->next = NULL;
                        tail = new_node;
                        pthread_mutex_unlock(&lock);
                        break;
                    }
                    current = current->next;
                }
            }

            pthread_mutex_unlock(&lock);

            dlclose(handle);
        }
    }

    closedir(dir);
    pthread_mutex_destroy(&lock);
    return head;
}

// Function to generate NFAPI_CRC_INDICATION_PDU_T list
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < count; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 256;
        list[i].RNTI = rand() % 65536;
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    }

    return list;
}

// Cleanup function for the protocol handler list
void free_protocol_handler_list(Node *head) {
    Node *current = head, *next;
    while (current != NULL) {
        next = current->next;
        free(current->handler->name);
        for (size_t i = 0; i < current->handler->feature_count; ++i) {
            free(current->handler->features[i]);
        }
        free(current->handler->features);
        free(current->handler);
        free(current);
        current = next;
    }
}

