['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDU_COUNT 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[32];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PDU_Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    int priority; // 0 for normal, 1 for urgent
    struct PDU_Node* next;
} PDU_Node;

typedef struct {
    PDU_Node** pdus;
    size_t count;
    pthread_mutex_t mutex;
} PDU_Manager;

PDU_Manager* create_pdu_manager() {
    PDU_Manager* manager = (PDU_Manager*)malloc(sizeof(PDU_Manager));
    if (!manager) return NULL;

    manager->pdus = (PDU_Node**)calloc(MAX_PDU_COUNT, sizeof(PDU_Node*));
    if (!manager->pdus) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

int add_pdu(PDU_Manager* manager, NFAPI_CRC_INDICATION_PDU_T new_pdu, int priority) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        PDU_Node* node = manager->pdus[i];

        // Check for duplicate identifiers
        while (node != NULL) {
            if (node->pdu.RX_UE_INFORMATION_TAG == new_pdu.RX_UE_INFORMATION_TAG &&
                node->pdu.RNTI == new_pdu.RNTI) {

                // Update existing PDU
                memcpy(&node->pdu, &new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
                node->priority = priority;
                node->timestamp = time(NULL);

                pthread_mutex_unlock(&manager->mutex);
                return 0; // Successfully updated
            }
            node = node->next;
        }
    }

    if (manager->count >= MAX_PDU_COUNT) {
        fprintf(stderr, "Memory pressure: Max PDU count reached.\n");
        pthread_mutex_unlock(&manager->mutex);
        return -2;
    }

    PDU_Node* new_node = (PDU_Node*)malloc(sizeof(PDU_Node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->mutex);
        // Fallback mechanism for failed allocation
        fprintf(stderr, "Allocation failure: Failed to allocate memory for a new PDU.\n");
        return -1;
    }

    memcpy(&new_node->pdu, &new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->priority = priority;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    manager->pdus[manager->count++] = new_node;

    pthread_mutex_unlock(&manager->mutex);

    // Logging the PDU addition
    printf("PDU added: RX_UE_INFORMATION_TAG=%d, RNTI=%d, Timestamp=%ld\n", 
           new_pdu.RX_UE_INFORMATION_TAG, new_pdu.RNTI, new_node->timestamp);

    return 0; // Successfully added
}

int get_pdu_count(PDU_Manager* manager) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->mutex);

    int count = manager->count;
    pthread_mutex_unlock(&manager->mutex);

    return count;
}

PDU_Node** get_urgent_pdus(PDU_Manager* manager, size_t* urgent_count) {
    if (!manager || !urgent_count) return NULL;

    PDU_Node** urgent_list = (PDU_Node**)calloc(MAX_PDU_COUNT, sizeof(PDU_Node*));
    if (!urgent_list) return NULL;

    pthread_mutex_lock(&manager->mutex);

    *urgent_count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        PDU_Node* node = manager->pdus[i];

        while (node != NULL) {
            if (node->priority == 1) {
                urgent_list[(*urgent_count)++] = node;
            }
            node = node->next;
        }
    }

    pthread_mutex_unlock(&manager->mutex);

    return urgent_list;
}

void free_pdu_manager(PDU_Manager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        PDU_Node* node = manager->pdus[i];

        while (node != NULL) {
            PDU_Node* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(manager->pdus);
    pthread_mutex_unlock(&manager->mutex);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

