} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    atomic_uintptr_t head; // Pointer to the first element
    atomic_uintptr_t tail; // Pointer to one past the last element
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
} ConcurrentDynamicArray;

bool initialize_array(ConcurrentDynamicArray *array, size_t initial_capacity) {
    if (initial_capacity == 0) return false;

    array->capacity = initial_capacity;
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) return false;

    atomic_store(&array->head, 0);
    atomic_store(&array->tail, 0);

    return true;
}

void destroy_array(ConcurrentDynamicArray *array) {
    free(array->array);
    array->array = NULL;
    array->capacity = 0;
}

bool resize_if_needed(ConcurrentDynamicArray *array) {
    size_t current_size = atomic_load(&array->tail);
    if (current_size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return false;

        array->array = new_array;
        array->capacity = new_capacity;
    }
    return true;
}

bool enqueue(ConcurrentDynamicArray *array, uint32_t rx_ue_info_tag, uint16_t rnti) {
    if (!resize_if_needed(array)) return false;

    size_t tail = atomic_load(&array->tail);
    uintptr_t next_tail = (uintptr_t)(tail + 1);

    // Attempt to move the tail forward
    while (!atomic_compare_exchange_weak((atomic_uintptr_t *)&array->tail, &tail, next_tail)) {
        // CAS failed, try again
    }

    if (next_tail >= array->capacity) {
        atomic_store(&array->tail, 0); // Wrap around
        next_tail = 0;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &array->array[next_tail];
    pdu->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu->RNTI = rnti;

    // Initialize CRC flag randomly
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) == 0;

    return true;
}

bool dequeue(ConcurrentDynamicArray *array, NFAPI_CRC_INDICATION_PDU_T *out_pdu) {
    size_t head = atomic_load(&array->head);
    uintptr_t next_head = (uintptr_t)(head + 1);

    if (next_head >= array->capacity) {
        // Array is empty
        return false;
    }

    // Attempt to move the head forward
    while (!atomic_compare_exchange_weak((atomic_uintptr_t *)&array->head, &head, next_head)) {
        // CAS failed, try again
    }

    *out_pdu = array->array[head];
    return true;
}

int main() {
    ConcurrentDynamicArray array;
    if (!initialize_array(&array, 4)) {
        fprintf(stderr, "Failed to initialize array\n");
        return EXIT_FAILURE;
    }

    // Example usage:
    enqueue(&array, 0x12345678, 0x9ABC);
    NFAPI_CRC_INDICATION_PDU_T pdu;
    if (dequeue(&array, &pdu)) {
        printf("Dequeued PDU with RX_UE_INFORMATION_TAG: %u\n", pdu.RX_UE_INFORMATION_TAG);
    }

    destroy_array(&array);
    return EXIT_SUCCESS;
}
```

