    MEASUREMENT_TYPE_2
} MeasurementType;

typedef struct {
    MeasurementType type;
    double value;
    double error_margin;
} MeasurementResult;

typedef struct MeasurementResultNode {
    MeasurementResult data;
    struct MeasurementResultNode* next;
} MeasurementResultNode;

typedef struct {
    int ueId;
    MeasurementResultNode* measurements_head;
    time_t timestamp;
} UeSessionStats;

#define MAX_UE_SESSIONS 1000

UeSessionStats sessions[MAX_UE_SESSIONS];
pthread_mutex_t session_mutexes[MAX_UE_SESSIONS];

void initialize_sessions() {
    for (int i = 0; i < MAX_UE_SESSIONS; ++i) {
        pthread_mutex_init(&session_mutexes[i], NULL);
        sessions[i].ueId = -1;
        sessions[i].measurements_head = NULL;
    }
}

void populate_session(int ueId, MeasurementResult* results, int num_results) {
    if (ueId < 0 || ueId >= MAX_UE_SESSIONS) return;

    pthread_mutex_lock(&session_mutexes[ueId]);

    UeSessionStats* session = &sessions[ueId];
    session->ueId = ueId;
    session->measurements_head = NULL;

    MeasurementResultNode* prev_node = NULL;
    for (int i = 0; i < num_results; ++i) {
        MeasurementResultNode* new_node = malloc(sizeof(MeasurementResultNode));
        if (!new_node) break;

        new_node->data = results[i];
        new_node->next = NULL;

        if (prev_node == NULL) {
            session->measurements_head = new_node;
        } else {
            prev_node->next = new_node;
        }
        prev_node = new_node;
    }

    session->timestamp = time(NULL);

    pthread_mutex_unlock(&session_mutexes[ueId]);
}

void free_session(int ueId) {
    if (ueId < 0 || ueId >= MAX_UE_SESSIONS) return;

    pthread_mutex_lock(&session_mutexes[ueId]);

    MeasurementResultNode* current = sessions[ueId].measurements_head;
    while (current != NULL) {
        MeasurementResultNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&session_mutexes[ueId]);
}

void cleanup_sessions() {
    for (int i = 0; i < MAX_UE_SESSIONS; ++i) {
        if (sessions[i].ueId != -1) {
            free_session(i);
        }
        pthread_mutex_destroy(&session_mutexes[i]);
    }
}
```']

