#define MAX_RNTI 1024
#define CACHE_SIZE 256

typedef struct {
    uint16_t RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

