    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
uint16_t recent_rntis[CACHE_SIZE];
size_t cache_head = 0;

void log_error(uint16_t rnti) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0'; // Remove newline
    fprintf(stderr, "Error: Duplicate RNTI %u attempted at %s\n", rnti, timestamp);
}

uint16_t generate_random_rnti() {
    return rand() % MAX_RNTI;
}

int is_recent(uint16_t rnti) {
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (recent_rntis[i] == rnti) {
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

void update_recent_cache(uint16_t rnti) {
    pthread_mutex_lock(&cache_lock);
    recent_rntis[cache_head] = rnti;
    cache_head = (cache_head + 1) % CACHE_SIZE;
    pthread_mutex_unlock(&cache_lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_indication_list(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list) return NULL;

    uint16_t prev_rnti = 0;
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) free(list[j]);
            free(list);
            return NULL;
        }

        uint16_t rnti;
        do {
            rnti = generate_random_rnti();
        } while (rnti == prev_rnti || is_recent(rnti));

        if (!is_recent(rnti)) {
            log_error(rnti);
            // Fallback mechanism: reuse an older RNTI or another strategy
        }

        pdu->ue_info_tag.RNTI = rnti;
        pdu->rnti = rnti;
        pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

        prev_rnti = rnti;
        update_recent_cache(rnti);
        list[i] = pdu;
    }

    return list;
}

void free_nfa_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *list[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (list[i]) free(list[i]);
    }
    free(list);
}
```

