    return (rnti >= 0 && rnti <= MAX_RNTI);
}

void add_node(RX_UE_INFO ue_info, int rnti, unsigned int seed) {
    pthread_mutex_lock(&list_mutex);

    if (!is_valid_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI value: %d\n", rnti);
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_node->data.ue_info = ue_info;
    new_node->data.RNTI = rnti;
    initialize_crc_flag(&new_node->data.crc_rel8_tag, seed);
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&list_mutex);
}

void reset_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        Node* to_free = current;
        current = current->next;
        free(to_free);
    }
    head = NULL;

    pthread_mutex_unlock(&list_mutex);
}

// Example usage
int main() {
    RX_UE_INFO ue_info_example = { .RX_UE_INFORMATION_TAG = 1 };
    unsigned int seed_example = 12345;

    add_node(ue_info_example, 1000, seed_example); // Add a valid node
    add_node(ue_info_example, -1, seed_example);   // Attempt to add an invalid node

    reset_list(); // Reset and free the list

    return 0;
}
