EventLogBuffer* create_event_log_buffer() {
    EventLogBuffer* buffer = malloc(sizeof(EventLogBuffer));
    if (!buffer) return NULL;
    memset(buffer->events, 0, sizeof(NetworkEvent) * MAX_EVENTS);
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void free_event_log_buffer(EventLogBuffer* buffer) {
    if (buffer) {
        pthread_mutex_destroy(&buffer->lock);
        free(buffer);
    }
}

int insert_event(EventLogBuffer* buffer, NetworkEvent event) {
    pthread_mutex_lock(&buffer->lock);

    // Find oldest or least important to replace
    size_t replace_idx = 0;
    for (size_t i = 1; i < MAX_EVENTS; ++i) {
        if (buffer->events[i].timestamp < buffer->events[replace_idx].timestamp ||
            (buffer->events[i].timestamp == buffer->events[replace_idx].timestamp &&
             buffer->events[i].importance < buffer->events[replace_idx].importance)) {
            replace_idx = i;
        }
    }

    if (buffer->count < MAX_EVENTS) {
        buffer->events[replace_idx] = event;
        buffer->count++;
    } else {
        buffer->events[replace_idx] = event; // Overwrite oldest/least important
    }

    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

NetworkEvent* find_event(EventLogBuffer* buffer, uint32_t event_id) {
    pthread_mutex_lock(&buffer->lock);

    for (size_t i = 0; i < buffer->count; ++i) {
        if (buffer->events[i].event_id == event_id) {
            NetworkEvent* evt = &buffer->events[i];
            pthread_mutex_unlock(&buffer->lock);
            return evt;
        }
    }

    pthread_mutex_unlock(&buffer->lock);
    return NULL;
}

int delete_event(EventLogBuffer* buffer, uint32_t event_id) {
    pthread_mutex_lock(&buffer->lock);

    for (size_t i = 0; i < buffer->count; ++i) {
        if (buffer->events[i].event_id == event_id) {
            memmove(&buffer->events[i], &buffer->events[i + 1],
                    (buffer->count - i - 1) * sizeof(NetworkEvent));
            --buffer->count;
            pthread_mutex_unlock(&buffer->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&buffer->lock);
    return -1; // Not found
