    int cache_index;
    pthread_rwlock_t list_lock;
} DynamicList;

pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned short used_rnti[MAX_RNTI] = {0};

void log_error(const char* message) {
    time_t now = time(NULL);
    char buf[100];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] ERROR: %s\n", buf, message);
}

bool is_rnti_unique(unsigned short rnti) {
    pthread_mutex_lock(&rnti_mutex);
    bool unique = !used_rnti[rnti];
    used_rnti[rnti] = 1;
    pthread_mutex_unlock(&rnti_mutex);
    return unique;
}

unsigned short get_random_rnti() {
    unsigned short rnti;
    do {
        rnti = rand() % MAX_RNTI;
    } while (!is_rnti_unique(rnti));
    return rnti;
}

void add_to_recent_cache(unsigned short* cache, int* index, unsigned short rnti) {
    cache[*index] = rnti;
    (*index)++;
    if (*index >= CACHE_SIZE) *index = 0;
}

bool is_in_recent_cache(unsigned short* cache, int size, unsigned short rnti) {
    for (int i = 0; i < size; ++i)
        if (cache[i] == rnti)
            return true;
    return false;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->tag.RX_UE_INFORMATION_TAG = rand();
    pdu->tag.RNTI = get_random_rnti();
    pdu->tag.CRCFLAG = rand() % 2 == 0;

    return pdu;
}

void add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_rwlock_wrlock(&list->list_lock);

    unsigned short rnti = pdu->tag.RNTI;
    if (is_in_recent_cache(list->recent_RNTI, list->cache_index, rnti)) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Duplicate RNTI: %u", rnti);
        log_error(error_message);
        free(pdu); // Memory management responsibility of the caller
        pthread_rwlock_unlock(&list->list_lock);
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_rwlock_unlock(&list->list_lock);
        free(pdu);
        log_error("Memory allocation failed for new node");
        return;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    add_to_recent_cache(list->recent_RNTI, &list->cache_index, rnti);

    pthread_rwlock_unlock(&list->list_lock);
}

void initialize_list(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->list_lock, NULL);
    memset(list->recent_RNTI, 0, sizeof(list->recent_RNTI));
    list->cache_index = 0;
}

void free_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->list_lock);
}

