    NFAPI_CRC_INDICATION_PDU_T data;
    int priority;
    struct Node* next;
} Node;

typedef struct PriorityQueue {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

void initializePriorityQueue(PriorityQueue* pq) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
}

int comparePriorities(int p1, int p2) {
    return p1 > p2;
}

void push(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) exit(EXIT_FAILURE);
    newNode->data = data;
    newNode->priority = priority;
    newNode->next = NULL;

    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL || comparePriorities(priority, pq->head->priority)) {
        newNode->next = pq->head;
        pq->head = newNode;
    } else {
        Node* current = pq->head;
        while (current->next != NULL && !comparePriorities(priority, current->next->priority))
            current = current->next;

        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&pq->lock);
}

NFAPI_CRC_INDICATION_PDU_T pop(PriorityQueue* pq) {
    if (pq->head == NULL) {
        fprintf(stderr, "Priority queue is empty\n");
        exit(EXIT_FAILURE);
    }

    Node* temp = pq->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    pq->head = pq->head->next;

    pthread_mutex_lock(&pq->lock);

    free(temp);

    pthread_mutex_unlock(&pq->lock);

    return data;
}

