    Node *current = head, *prev = NULL;

    while (current != NULL) {
        if ((current_time - current->data.timestamp) > age_threshold_seconds) {
            if (prev == NULL) { // Head node
                head = current->next;
                free(current);
                current = head;
            } else {
                prev->next = current->next;
                free(current);
                current = prev->next;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list_lock);
}

