        manager->contexts[i].rrcConnInfo.rrcConnectionId = rand() % 1000;
        manager->contexts[i].srsConfig.thresholdRSRP = rand() / (float)RAND_MAX * -140 + 20; // Random value between -120 and 20
        manager->contexts[i].srsConfig.thresholdRSRQ = rand() / (float)RAND_MAX * -10 + 5;   // Random value between -5 and 5
        manager->contexts[i].nrMeasureReport.measurementReportId = rand() % 1000;
        manager->contexts[i].nrMeasureReport.rsrp = rand() / (float)RAND_MAX * -140 + 20;
        manager->contexts[i].nrMeasureReport.rsrq = rand() / (float)RAND_MAX * -10 + 5;
    }
}

UEManager* createUEContexts(size_t initialCapacity) {
    UEManager *manager = malloc(sizeof(UEManager));
    if (!manager) return NULL;

    manager->contexts = calloc(initialCapacity, sizeof(UEContext));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resizeUEContexts(UEManager *manager, size_t newCapacity) {
    UEContext *newContexts = realloc(manager->contexts, newCapacity * sizeof(UEContext));
    if (!newContexts) return;

    manager->contexts = newContexts;
    manager->capacity = newCapacity;
}

int addUEContext(UEManager *manager, const UEContext *context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity ? manager->capacity * 2 : 1;
        resizeUEContexts(manager, newCapacity);
        if (!manager->contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
    }

    memcpy(&manager->contexts[manager->count++], context, sizeof(UEContext));

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void freeUEManager(UEManager *manager) {
    if (manager) {
        free(manager->contexts);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int serializeUEContexts(const char *filename, const UEManager *manager) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->contexts, sizeof(UEContext), manager->count, file);

    pthread_mutex_unlock(&manager->lock);
    fclose(file);

    return 0;
}

int deserializeUEContexts(const char *filename, UEManager *manager) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    if (count > manager->capacity) {
        resizeUEContexts(manager, count);
        if (!manager->contexts) {
            fclose(file);
            return -1; // Memory allocation failed
        }
    }

    fread(manager->contexts, sizeof(UEContext), count, file);
    manager->count = count;

    pthread_mutex_unlock(&manager->lock);
    fclose(file);

    return 0;
}

int main() {
    UEManager *manager = createUEContexts(10); // Initial capacity of 10
    if (!manager) return -1;

    initializeRandomData(manager);

    UEContext newContext;
    memset(&newContext, 0, sizeof(UEContext));
    addUEContext(manager, &newContext);

    serializeUEContexts("uecontexts.dat", manager);
    UEManager *loadedManager = createUEContexts(MAX_UE_CONTEXTS);
    deserializeUEContexts("uecontexts.dat", loadedManager);

    freeUEManager(manager);
    freeUEManager(loadedManager);

    return 0;
}
```

