    }
}

void addUEContext(UEContextArray *array, const UEContext *context) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        UEContext *newContexts = realloc(array->contexts, newCapacity * sizeof(UEContext));
        if (!newContexts) {
            perror("Failed to reallocate memory for UEContextArray");
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->contexts = newContexts;
        array->capacity = newCapacity;
    }

    memcpy(&array->contexts[array->count], context, sizeof(UEContext));
    array->count++;
    logEvent("UEContext added");
    pthread_mutex_unlock(&array->lock);
}

void removeUEContext(UEContextArray *array, size_t index) {
    pthread_mutex_lock(&array->lock);
    if (index >= array->count) {
        pthread_mutex_unlock(&array->lock);
        return;
    }

    memmove(&array->contexts[index], &array->contexts[index + 1],
            (array->count - index - 1) * sizeof(UEContext));
    array->count--;
    logEvent("UEContext removed");
    pthread_mutex_unlock(&array->lock);
}

void destroyUEContextArray(UEContextArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->contexts);
    pthread_mutex_destroy(&array->lock);
    logEvent("UEContextArray destroyed");
}

