    }
    pthread_mutex_unlock(&array->lock);
}

int deserializeFromFile(UEContextArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);
    FILE *file = fopen(filename, "rb");
    if (file) {
        size_t count = fread(array->contexts, sizeof(UEContext), array->capacity, file);
        if (count == 0 || ferror(file)) {
            perror("Failed to read from file during deserialization");
            fclose(file);
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->count = count;
        fclose(file);
    } else {
        perror("Failed to open file for deserialization");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    pthread_mutex_unlock(&array->lock);
    logEvent("UEContextArray deserialized from file");
    return 0;
}
