#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/syscall.h> // For syscall(SYS_gettid)
#include <syslog.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure for memory pool if needed (not shown here for simplicity)

#define NUM_THREADS 4 // Example number of concurrent threads

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    pthread_t current_thread_id = syscall(SYS_gettid);

    // Locking the critical section
    if (pthread_mutex_lock(&mutex) != 0) {
        syslog(LOG_ERR, "Failed to lock mutex in thread %lu", current_thread_id);
        return NULL;
    }

    array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        syslog(LOG_ERR, "Memory allocation failed for %zu elements by thread %lu", count, current_thread_id);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize the structures and log each
    for (size_t i = 0; i < count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example randomization
        array[i].RNTI = rand() % 10000;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0);

        syslog(LOG_INFO, "Created NFAPI_CRC_INDICATION_PDU_T at address %p: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u", 
            &array[i], array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    // Unlocking the critical section
    pthread_mutex_unlock(&mutex);

    return array;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (!array) return;

    // It's generally safe to free without a mutex here as each thread should only free its own data
    free(array);
}

// A simple test function for demonstration purposes
void* worker_function(void *arg) {
    size_t count = *(size_t*)arg;
    NFAPI_CRC_INDICATION_PDU_T *data = allocate_crc_indications(count);

    if (data) {
        // Simulate some work
        usleep(100000);

        free_crc_indications(data);
    }

    pthread_exit(NULL);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    // Open syslog for logging
    openlog("NFAPI_CRC_Logger", LOG_PID | LOG_CONS, LOG_USER);

    pthread_t threads[NUM_THREADS];
    size_t counts[NUM_THREADS] = {1000, 2000, 1500, 1200}; // Example sizes

    for (int i = 0; i < NUM_THREADS; ++i) {
        if(pthread_create(&threads[i], NULL, worker_function, &counts[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    closelog();

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutex locks are used to ensure that only one thread can allocate memory at a time, preventing race conditions during allocation.
- **Logging**: `syslog` is used for logging the creation of each structure with its address and contents.
- **Error Handling**: Memory allocation failures are logged as errors. Threads exit gracefully if they cannot lock or allocate memory.
- **Concurrency**: Multiple threads can safely call `allocate_crc_indications`, but only one at a time due to mutex locking.
- **Resource Management**: Ensures that allocated memory is freed after use.

