        return 1;
    else
        return 0;
}

void add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu, int signal_quality, int packet_integrity) {
    pthread_mutex_lock(&list->lock);

    if (!is_valid_rnti(pdu.RNTI) || !is_valid_ue_identifier(&pdu.rx_ue_information_tag)) {
        printf("Invalid RNTI or UE identifier\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    pdu.crc_indication_rel8_tag.CRCFLAG = calculate_crc_flag(signal_quality, packet_integrity);
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        delete_node(&current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

