    NFAPI_CRC_INDICATION_PDU_T example_pdu = { .rx_ue_information_tag = {.UE_identifier = 123}, .RNTI = 456 };
    add_pdu(pdu_list, example_pdu, signal_quality=85, packet_integrity=95);

    free_list(pdu_list);
    return 0;
}
