void log_failure(const char *message) {
    fprintf(stderr, "Failure: %s\n", message);
}

int initialize_dynamic_array(DynamicArray *dynamic_array, size_t n) {
    if (pthread_mutex_init(&dynamic_array->lock, NULL) != 0) {
        return -1;
    }

    dynamic_array->array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_array->array) {
        pthread_mutex_destroy(&dynamic_array->lock);
        return -1;
    }

    dynamic_array->capacity = n;
    dynamic_array->count = 0;

    for (size_t i = 0; i < n; ++i) {
        srand(time(NULL) + i); // Seed with different value per element
        dynamic_array->array[i].crc_tag.CRCFLAG = rand() % 2;
    }

    return 0;
}

void free_dynamic_array(DynamicArray *dynamic_array) {
    pthread_mutex_lock(&dynamic_array->lock);
    if (dynamic_array->array) {
        free(dynamic_array->array);
        dynamic_array->array = NULL;
    }
    dynamic_array->count = 0;
    dynamic_array->capacity = 0;
    pthread_mutex_unlock(&dynamic_array->lock);

    pthread_mutex_destroy(&dynamic_array->lock);
}

void update_crc_flags(DynamicArray *dynamic_array) {
    pthread_mutex_lock(&dynamic_array->lock);

    for (size_t i = 0; i < dynamic_array->count; ++i) {
        // Simulate external data source update
        srand(time(NULL) + i); 
        dynamic_array->array[i].crc_tag.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&dynamic_array->lock);
}

void validate_crc_flags(DynamicArray *dynamic_array) {
    pthread_mutex_lock(&dynamic_array->lock);

    for (size_t i = 0; i < dynamic_array->count - 1; ++i) {
        if (dynamic_array->array[i].crc_tag.CRCFLAG != dynamic_array->array[i + 1].crc_tag.CRCFLAG) {
            log_failure("Inconsistency detected in CRC flags.");
            break;
        }
    }

    pthread_mutex_unlock(&dynamic_array->lock);
}

void periodic_update_and_validate(DynamicArray *dynamic_array, void (*update_func)(DynamicArray*),
                                  void (*validate_func)(DynamicArray*)) {
    // Example of a thread running periodic updates and validations
    while (1) {
        update_func(dynamic_array);
        validate_func(dynamic_array);

        // Sleep or wait for next update cycle
        sleep(5);  // Adjust the timing as necessary for your application
    }
}

int main() {
    DynamicArray dynamic_array;
    size_t n = 100;  // Example capacity

    if (initialize_dynamic_array(&dynamic_array, n) != 0) {
        fprintf(stderr, "Failed to initialize dynamic array.\n");
        return EXIT_FAILURE;
    }

    pthread_t update_thread;
    if (pthread_create(&update_thread, NULL, 
                       (void *(*)(void *))periodic_update_and_validate, 
                       &dynamic_array)) {
        free_dynamic_array(&dynamic_array);
        fprintf(stderr, "Failed to create thread.\n");
        return EXIT_FAILURE;
    }

    pthread_join(update_thread, NULL);

    free_dynamic_array(&dynamic_array);
    return 0;
}
