typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

Node* head = NULL;
size_t current_size = 0;

void initialize_list(size_t max_threshold) {
    pthread_mutex_lock(&list_lock);
    if (head == NULL || current_size >= max_threshold) {
        // Free the existing list to prevent memory leaks
        Node* temp;
        while (head != NULL) {
            temp = head;
            head = head->next;
            free(temp);
        }
        current_size = 0;
    }
    pthread_mutex_unlock(&list_lock);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; // Error handling for memory allocation failure
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data, uint16_t* critical_rntis, size_t num_critical_rntis) {
    pthread_mutex_lock(&list_lock);
    if (current_size >= MAX_NFAPIS) {
        fprintf(stderr, "Maximum list threshold reached.\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    for (size_t i = 0; i < num_critical_rntis; ++i) {
        if (data.RNTI == critical_rntis[i]) {
            data.crc_tag.CRCFLAG = true;
            break;
        }
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for a new list node.\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    new_node->next = head;
    head = new_node;
    ++current_size;

    pthread_mutex_unlock(&list_lock);
}

void serialize_list(FILE* file) {
    pthread_mutex_lock(&list_lock);

    Node* current = head;
    while (current != NULL) {
        fwrite(&(current->data.RX_UE_INFORMATION_TAG), sizeof(current->data.RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&(current->data.RNTI), sizeof(current->data.RNTI), 1, file);
        fwrite(&(current->data.crc_tag.CRCFLAG), sizeof(current->data.crc_tag.CRCFLAG), 1, file);

        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
}

void free_list() {
    pthread_mutex_lock(&list_lock);

    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    current_size = 0;

    pthread_mutex_unlock(&list_lock);
}

