}

void initialize_dynamic_buffer(DynamicBuffer* db, size_t initial_capacity) {
    pthread_mutex_init(&db->lock, NULL);
    db->capacity = initial_capacity;
    db->count = 0;
    db->buffer = (NR_PDU_T*)malloc(sizeof(NR_PDU_T) * db->capacity);
}

void resize_dynamic_buffer(DynamicBuffer* db, size_t new_capacity) {
    pthread_mutex_lock(&db->lock);
    NR_PDU_T* new_buffer = (NR_PDU_T*)realloc(db->buffer, sizeof(NR_PDU_T) * new_capacity);
    if (new_buffer != NULL) {
        db->capacity = new_capacity;
        db->buffer = new_buffer;
    }
    pthread_mutex_unlock(&db->lock);
}

int add_pdu_to_dynamic_buffer(DynamicBuffer* db, NR_PDU_T* pdu) {
    pthread_mutex_lock(&db->lock);

    if (db->count >= db->capacity) {
        resize_dynamic_buffer(db, db->capacity * 2);
    }

    // Ensure no two consecutive structures have the same RNTI
    if (db->count > 0 && db->buffer[db->count - 1].RNTI == pdu->RNTI) {
        pthread_mutex_unlock(&db->lock);
        return -1; // Failure due to duplicate RNTI
    }

    // Validate SRS alignment
    if (!validate_srs_alignment(pdu)) {
        pthread_mutex_unlock(&db->lock);
        return -2; // Failure due to invalid SRS alignment
    }

    db->buffer[db->count++] = *pdu;
    pthread_mutex_unlock(&db->lock);

    return 0; // Success
}

void free_dynamic_buffer(DynamicBuffer* db) {
    pthread_mutex_destroy(&db->lock);
    free(db->buffer);
    db->buffer = NULL;
    db->capacity = 0;
    db->count = 0;
}

// Unit tests for the dynamic buffer

#include <assert.h>

#define TEST_CAPACITY 100
#define MAX_PDUS 5000

void test_dynamic_buffer() {
    DynamicBuffer db;
    initialize_dynamic_buffer(&db, TEST_CAPACITY);

    srand(time(NULL));
    for (size_t i = 0; i < MAX_PDUS; ++i) {
        NR_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 100000; // Simulate RNTI
        pdu.srs_info.SRS_INDICATION_TAG = rand();
        pdu.srs_info.SRSFLAG = rand() % 2; // Randomly set SRSFLAG to 0 or 1

        int result = add_pdu_to_dynamic_buffer(&db, &pdu);
        assert(result == 0); // Ensure addition is successful
    }

    assert(db.count <= db.capacity); // Buffer should not exceed its capacity
    free_dynamic_buffer(&db);

    printf("All tests passed!\n");
}

int main() {
    test_dynamic_buffer();
    return 0;
}
```']

