pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER
list<NFAPI_CRC_INDICATION_PDU_T*> pdu_list

// Logging function
def log_message(message):
    printf("Log: %s\n", message)

// Function to check memory usage (platform-specific; mock implementation)
