NFAPI_CRC_INDICATION_PDU_T* create_list_node(RX_UE_INFORMATION_TAG ue_info, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for new list node.\n");
        return NULL;
    }
    node->ue_info_tag = ue_info;
    node->rnti = rnti;
    node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    node->next = NULL;
    return node;
}

void append_list(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* new_node) {
    pthread_mutex_lock(&list_mutex);

    if (!new_node) {
        fprintf(stderr, "Attempt to append a NULL node.\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    if (*head == NULL || ((*head)->rnti != new_node->rnti)) {
        if (*head == NULL || ((*head)->next == NULL && (*head)->rnti != new_node->rnti)) {
            // Insert at head if empty list or different RNTI
            new_node->next = *head;
            *head = new_node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = *head;
            while (current->next != NULL && current->next->rnti == new_node->rnti) {
                // Skip nodes with the same RNTI
                current = current->next;
            }
            if (current->next != NULL && current->next->rnti == new_node->rnti) {
                fprintf(stderr, "Attempt to append a node with consecutive duplicate RNTI.\n");
            } else {
                // Append at the end of the list
                current->next = new_node;
            }
        }
    } else {
        fprintf(stderr, "Attempt to append a node with the same RNTI as previous.\n");
    }

    pthread_mutex_unlock(&list_mutex);
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

void export_list_to_binary(const char *filename, NFAPI_CRC_INDICATION_PDU_T* head) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", filename);
        return;
    }

    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fwrite(&(current->ue_info_tag), sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&(current->rnti), sizeof(unsigned int), 1, file);
        fwrite(&(current->crc_indication_rel8_tag.CRCFLAG), sizeof(current->crc_indication_rel8_tag.CRCFLAG), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);

    fclose(file);
}

int main() {
